#include <iostream>
#include <string>
#include <vector>
#include <iomanip>

using namespace std;

struct Number {
    string raw;
    string intPart;
    string fracPart;
    bool hasDot;
};

Number parseNumber(const string& s) {
    Number num;
    num.raw = s;
    size_t dotPos = s.find('.');
    if (dotPos == string::npos) {
        num.intPart = s;
        num.fracPart = "";
        num.hasDot = false;
    } else {
        num.intPart = s.substr(0, dotPos);
        num.fracPart = s.substr(dotPos + 1);
        num.hasDot = true;
    }
    return num;
}

string padLeft(const string& s, int w) {
    if ((int)s.length() >= w) return s;
    return string(w - s.length(), ' ') + s;
}

string padRight(const string& s, int w) {
    if ((int)s.length() >= w) return s;
    return s + string(w - s.length(), ' ');
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<pair<Number, Number>> rows(4);
    for (int i = 0; i < 4; ++i) {
        string s1, s2;
        if (!(cin >> s1 >> s2)) return 0;
        rows[i].first = parseNumber(s1);
        rows[i].second = parseNumber(s2);
    }

    // 1. Left-aligned
    for (int i = 0; i < 4; ++i) {
        cout << padRight(rows[i].first.raw, 12) << " "
             << padRight(rows[i].second.raw, 12) << "\n";
    }
    cout << "\n";

    // 2. Right-aligned
    for (int i = 0; i < 4; ++i) {
        cout << padLeft(rows[i].first.raw, 12) << " "
             << padLeft(rows[i].second.raw, 12) << "\n";
    }
    cout << "\n";

    // 3. Decimal aligned (6 chars for int part right-aligned, '.', 5 chars for frac part left-aligned)
    for (int i = 0; i < 4; ++i) {
        auto formatCol = [](const Number& n) {
            string sInt = padLeft(n.intPart, 6);
            string dot = n.hasDot ? "." : " ";
            string sFrac = padRight(n.fracPart, 5);
            return sInt + dot + sFrac;
        };
        cout << formatCol(rows[i].first) << " "
             << formatCol(rows[i].second) << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<string> col1(4), col2(4);
    for (int i = 0; i < 4; ++i) {
        if (!(cin >> col1[i] >> col2[i])) return 0;
    }

    // Format 1: Left align 12
    for (int i = 0; i < 4; ++i) {
        string c1 = col1[i] + string(max(0, 12 - (int)col1[i].size()), ' ');
        string c2 = col2[i] + string(max(0, 12 - (int)col2[i].size()), ' ');
        cout << c1 << " " << c2 << "\n";
    }
    cout << "\n";

    // Format 2: Right align 12
    for (int i = 0; i < 4; ++i) {
        string c1 = string(max(0, 12 - (int)col1[i].size()), ' ') + col1[i];
        string c2 = string(max(0, 12 - (int)col2[i].size()), ' ') + col2[i];
        cout << c1 << " " << c2 << "\n";
    }
    cout << "\n";

    // Format 3: Decimal align
    auto alignDot = [](const string& s) -> string {
        size_t p = s.find('.');
        string intP = (p == string::npos) ? s : s.substr(0, p);
        string fracP = (p == string::npos) ? "" : s.substr(p + 1);
        char dot = (p == string::npos) ? ' ' : '.';
        string part1 = string(max(0, 6 - (int)intP.size()), ' ') + intP;
        string part2 = fracP + string(max(0, 5 - (int)fracP.size()), ' ');
        return part1 + dot + part2;
    };

    for (int i = 0; i < 4; ++i) {
        cout << alignDot(col1[i]) << " " << alignDot(col2[i]) << "\n";
    }

    return 0;
}

