const double PI_CONST = 3.141592653589793;

struct ShapeCalculator {
    static double sq_perimeter(double side) { return 4.0 * side; }
    static double sq_area(double side) { return side * side; }
    static double rect_perimeter(double len, double wid) { return (len + wid) * 2.0; }
    static double rect_area(double len, double wid) { return len * wid; }
    static double circ_perimeter(double rad) { return 2.0 * PI_CONST * rad; }
    static double circ_area(double rad) { return PI_CONST * rad * rad; }
};

int main() {
    double a, l, w, r;
    if (std::cin >> a >> l >> w >> r) {
        std::cout << std::fixed << std::setprecision(2);
        std::cout << ShapeCalculator::sq_perimeter(a) << " " << ShapeCalculator::sq_area(a) << "\n";
        std::cout << ShapeCalculator::rect_perimeter(l, w) << " " << ShapeCalculator::rect_area(l, w) << "\n";
        std::cout << ShapeCalculator::circ_perimeter(r) << " " << ShapeCalculator::circ_area(r) << "\n";
    }
    return 0;
}

