        if (isEquilateral) {
            cout << "Tam giac deu" << endl;
        } else if (isRight && isIsosceles) {
            cout << "Tam giac vuong can" << endl;
        } else if (isRight) {
            cout << "Tam giac vuong" << endl;
        } else if (isIsosceles) {
            cout << "Tam giac can" << endl;
        } else {
            cout << "Tam giac thuong" << endl;
        }
    }
    return 0;
}

