bool isPerfect(long long x) {
    if (x <= 1) return false;
    long long sum = 1;
    for (long long i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            sum += i;
            if (i * i != x) {
                sum += x / i;
            }
        }
    }
    return sum == x;
}

