int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<double> a(n);
    double sum_all = 0;
    double sum_neg = 0;
    double sum_pos = 0;
    double sum_even_pos = 0;
    double sum_odd_pos = 0;

    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        sum_all += a[i];
        if (a[i] < 0) sum_neg += a[i];
        else if (a[i] > 0) sum_pos += a[i];

        if ((i + 1) % 2 == 0) {
            sum_even_pos += a[i];
        } else {
            sum_odd_pos += a[i];
        }
    }

    double avg = sum_all / n;

    double best_val = a[0];
    double min_diff = std::abs(a[0] - avg);

    for (int i = 1; i < n; ++i) {
        double diff = std::abs(a[i] - avg);
        if (diff < min_diff) {
            min_diff = diff;
            best_val = a[i];
        }
    }

    cout << fixed << setprecision(2);
    cout << sum_all << " "
         << avg << " "
         << sum_neg << " "
         << sum_pos << " "
         << sum_even_pos << " "
         << sum_odd_pos << " "
         << best_val << "\n";

    return 0;
}

