using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    vector<double> arr(n);
    double total = 0.0;
    double neg_sum = 0.0;
    double pos_sum = 0.0;
    double even_idx_sum = 0.0;
    double odd_idx_sum = 0.0;

    for (int i = 0; i < n; ++i) {
        scanf("%lf", &arr[i]);
        total += arr[i];
        if (arr[i] < 0.0) {
            neg_sum += arr[i];
        } else if (arr[i] > 0.0) {
            pos_sum += arr[i];
        }

        if ((i + 1) % 2 == 0) {
            even_idx_sum += arr[i];
        } else {
            odd_idx_sum += arr[i];
        }
    }

    double mean = total / (double)n;
    double closest = arr[0];
    double min_dist = fabs(arr[0] - mean);

    for (int i = 1; i < n; ++i) {
        double dist = fabs(arr[i] - mean);
        if (dist < min_dist) {
            min_dist = dist;
            closest = arr[i];
        }
    }

    printf("%.2f %.2f %.2f %.2f %.2f %.2f %.2f\n",
           total, mean, neg_sum, pos_sum, even_idx_sum, odd_idx_sum, closest);

    return 0;
}

