#include <iostream>
#include <vector>

using namespace std;

typedef vector<vector<long long>> Matrix;

Matrix createMatrix(int n) {
    return Matrix(n, vector<long long>(n, 0));
}

Matrix add(const Matrix& A, const Matrix& B, int n) {
    Matrix C = createMatrix(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            C[i][j] = A[i][j] + B[i][j];
        }
    }
    return C;
}

Matrix sub(const Matrix& A, const Matrix& B, int n) {
    Matrix C = createMatrix(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            C[i][j] = A[i][j] - B[i][j];
        }
    }
    return C;
}

Matrix mul(const Matrix& A, const Matrix& B, int n) {
    Matrix C = createMatrix(n);
    for (int i = 0; i < n; ++i) {
        for (int k = 0; k < n; ++k) {
            for (int j = 0; j < n; ++j) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

void printMatrix(const string& label, const Matrix& M, int n) {
    cout << label << "\n";
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << M[i][j] << (j == n - 1 ? "" : " ");
        }
        cout << "\n";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    Matrix A = createMatrix(n);
    Matrix B = createMatrix(n);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> A[i][j];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> B[i][j];

    Matrix sumAB = add(A, B, n);
    Matrix subAB = sub(A, B, n);
    Matrix mulAB = mul(A, B, n);
    Matrix A2 = mul(A, A, n);
    Matrix B2 = mul(B, B, n);
    Matrix diffSquares = sub(A2, B2, n);

    printMatrix("A + B:", sumAB, n);
    printMatrix("A - B:", subAB, n);
    printMatrix("A * B:", mulAB, n);
    printMatrix("A^2 - B^2:", diffSquares, n);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);
    int n;
    if (!(cin >> n)) return 0;
    vector<vector<long long>> a(n, vector<long long>(n));
    vector<vector<long long>> b(n, vector<long long>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) cin >> a[i][j];
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) cin >> b[i][j];
    }

    auto print_mat = [&](const string& tag, const vector<vector<long long>>& mat) {
        cout << tag << "\n";
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                cout << mat[i][j] << (j + 1 == n ? "\n" : " ");
            }
        }
    };

    vector<vector<long long>> add_res(n, vector<long long>(n));
    vector<vector<long long>> sub_res(n, vector<long long>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            add_res[i][j] = a[i][j] + b[i][j];
            sub_res[i][j] = a[i][j] - b[i][j];
        }
    }

    auto multiply = [&](const vector<vector<long long>>& m1, const vector<vector<long long>>& m2) {
        vector<vector<long long>> res(n, vector<long long>(n, 0));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k < n; ++k) {
                    res[i][j] += m1[i][k] * m2[k][j];
                }
            }
        }
        return res;
    };

    auto mul_ab = multiply(a, b);
    auto a2 = multiply(a, a);
    auto b2 = multiply(b, b);
    vector<vector<long long>> diff2(n, vector<long long>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            diff2[i][j] = a2[i][j] - b2[i][j];
        }
    }

    print_mat("A + B:", add_res);
    print_mat("A - B:", sub_res);
    print_mat("A * B:", mul_ab);
    print_mat("A^2 - B^2:", diff2);

    return 0;
}

