#include <iostream>
#include <vector>
#include <iomanip>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int m, n;
    if (!(cin >> m >> n)) return 0;

    vector<vector<double>> a(m, vector<double>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    cout << fixed << setprecision(2);

    // 1. Toan bo ma tran
    int min_r = 0, min_c = 0;
    int max_r = 0, max_c = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[i][j] < a[min_r][min_c]) {
                min_r = i;
                min_c = j;
            }
            if (a[i][j] > a[max_r][max_c]) {
                max_r = i;
                max_c = j;
            }
        }
    }
    cout << "MIN " << a[min_r][min_c] << " AT " << min_r + 1 << " " << min_c + 1 << "\n";
    cout << "MAX " << a[max_r][max_c] << " AT " << max_r + 1 << " " << max_c + 1 << "\n";

    // 2. Tung hang
    for (int i = 0; i < m; ++i) {
        int c_min = 0, c_max = 0;
        for (int j = 1; j < n; ++j) {
            if (a[i][j] < a[i][c_min]) c_min = j;
            if (a[i][j] > a[i][c_max]) c_max = j;
        }
        cout << "ROW " << i + 1 << ": MIN " << a[i][c_min] << " AT " << c_min + 1
             << ", MAX " << a[i][c_max] << " AT " << c_max + 1 << "\n";
    }

    // 3. Tung cot
    for (int j = 0; j < n; ++j) {
        int r_min = 0, r_max = 0;
        for (int i = 1; i < m; ++i) {
            if (a[i][j] < a[r_min][j]) r_min = i;
            if (a[i][j] > a[r_max][j]) r_max = i;
        }
        cout << "COL " << j + 1 << ": MIN " << a[r_min][j] << " AT " << r_min + 1
             << ", MAX " << a[r_max][j] << " AT " << r_max + 1 << "\n";
    }

    // 4. Cheo chinh
    int k = min(m, n);
    int d_min = 0, d_max = 0;
    for (int i = 1; i < k; ++i) {
        if (a[i][i] < a[d_min][d_min]) d_min = i;
        if (a[i][i] > a[d_max][d_max]) d_max = i;
    }
    cout << "MAIN DIAGONAL: MIN " << a[d_min][d_min] << " AT " << d_min + 1 << " " << d_min + 1
         << ", MAX " << a[d_max][d_max] << " AT " << d_max + 1 << " " << d_max + 1 << "\n";

    // 5. Cheo phu
    int ad_min = 0, ad_max = 0;
    for (int i = 1; i < k; ++i) {
        if (a[i][n - 1 - i] < a[ad_min][n - 1 - ad_min]) ad_min = i;
        if (a[i][n - 1 - i] > a[ad_max][n - 1 - ad_max]) ad_max = i;
    }
    cout << "ANTI DIAGONAL: MIN " << a[ad_min][n - 1 - ad_min] << " AT " << ad_min + 1 << " " << n - ad_min
         << ", MAX " << a[ad_max][n - 1 - ad_max] << " AT " << ad_max + 1 << " " << n - ad_max << "\n";

    return 0;
}

#include <cstdio>
#include <vector>
#include <algorithm>

using namespace std;

struct Element {
    double val;
    int r, c;
};

int main() {
    int m, n;
    if (scanf("%d %d", &m, &n) != 2) return 0;

    vector<vector<double>> mat(m, vector<double>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            scanf("%lf", &mat[i][j]);
        }
    }

    // Global Min & Max
    Element g_min = {mat[0][0], 1, 1};
    Element g_max = {mat[0][0], 1, 1};
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] < g_min.val) {
                g_min = {mat[i][j], i + 1, j + 1};
            }
            if (mat[i][j] > g_max.val) {
                g_max = {mat[i][j], i + 1, j + 1};
            }
        }
    }
    printf("MIN %.2f AT %d %d\n", g_min.val, g_min.r, g_min.c);
    printf("MAX %.2f AT %d %d\n", g_max.val, g_max.r, g_max.c);

    // Rows
    for (int i = 0; i < m; ++i) {
        int min_c = 1, max_c = 1;
        double min_v = mat[i][0], max_v = mat[i][0];
        for (int j = 1; j < n; ++j) {
            if (mat[i][j] < min_v) {
                min_v = mat[i][j];
                min_c = j + 1;
            }
            if (mat[i][j] > max_v) {
                max_v = mat[i][j];
                max_c = j + 1;
            }
        }
        printf("ROW %d: MIN %.2f AT %d, MAX %.2f AT %d\n", i + 1, min_v, min_c, max_v, max_c);
    }

    // Columns
    for (int j = 0; j < n; ++j) {
        int min_r = 1, max_r = 1;
        double min_v = mat[0][j], max_v = mat[0][j];
        for (int i = 1; i < m; ++i) {
            if (mat[i][j] < min_v) {
                min_v = mat[i][j];
                min_r = i + 1;
            }
            if (mat[i][j] > max_v) {
                max_v = mat[i][j];
                max_r = i + 1;
            }
        }
        printf("COL %d: MIN %.2f AT %d, MAX %.2f AT %d\n", j + 1, min_v, min_r, max_v, max_r);
    }

    // Main diagonal
    int len = min(m, n);
    int d_min_idx = 0, d_max_idx = 0;
    for (int i = 1; i < len; ++i) {
        if (mat[i][i] < mat[d_min_idx][d_min_idx]) d_min_idx = i;
        if (mat[i][i] > mat[d_max_idx][d_max_idx]) d_max_idx = i;
    }
    printf("MAIN DIAGONAL: MIN %.2f AT %d %d, MAX %.2f AT %d %d\n",
           mat[d_min_idx][d_min_idx], d_min_idx + 1, d_min_idx + 1,
           mat[d_max_idx][d_max_idx], d_max_idx + 1, d_max_idx + 1);

    // Anti diagonal
    int ad_min_idx = 0, ad_max_idx = 0;
    for (int i = 1; i < len; ++i) {
        if (mat[i][n - 1 - i] < mat[ad_min_idx][n - 1 - ad_min_idx]) ad_min_idx = i;
        if (mat[i][n - 1 - i] > mat[ad_max_idx][n - 1 - ad_max_idx]) ad_max_idx = i;
    }
    printf("ANTI DIAGONAL: MIN %.2f AT %d %d, MAX %.2f AT %d %d\n",
           mat[ad_min_idx][n - 1 - ad_min_idx], ad_min_idx + 1, n - ad_min_idx,
           mat[ad_max_idx][n - 1 - ad_max_idx], ad_max_idx + 1, n - ad_max_idx);

    return 0;
}

