#include <iostream>

// Sử dụng cây tìm kiếm nhị phân (hoặc cây AVL / Treap để cân bằng) 
// Để đơn giản và tối ưu, sử dụng Treap (Cartesian Tree) hoàn toàn bằng con trỏ, không dùng mảng.

struct Node {
    long long key;
    int priority;
    int count;
    Node *left, *right;
    Node(long long k) : key(k), priority(rand()), count(1), left(nullptr), right(nullptr) {}
};

void rotateRight(Node* &root) {
    Node* l = root->left;
    root->left = l->right;
    l->right = root;
    root = l;
}

void rotateLeft(Node* &root) {
    Node* r = root->right;
    root->right = r->left;
    r->left = root;
    root = r;
}

void insert(Node* &root, long long key) {
    if (!root) {
        root = new Node(key);
        return;
    }
    if (key == root->key) {
        root->count++;
        return;
    }
    if (key < root->key) {
        insert(root->left, key);
        if (root->left->priority > root->priority) {
            rotateRight(root);
        }
    } else {
        insert(root->right, key);
        if (root->right->priority > root->priority) {
            rotateLeft(root);
        }
    }
}

bool first = true;
void inorder(Node* root) {
    if (!root) return;
    inorder(root->left);
    for (int i = 0; i < root->count; ++i) {
        if (!first) std::cout << " ";
        std::cout << root->key;
        first = false;
    }
    inorder(root->right);
}

void clearTree(Node* root) {
    if (!root) return;
    clearTree(root->left);
    clearTree(root->right);
    delete root;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    if (!(std::cin >> n)) return 0;
    Node* root = nullptr;
    for (int i = 0; i < n; ++i) {
        long long val;
        std::cin >> val;
        insert(root, val);
    }
    inorder(root);
    std::cout << "\n";
    clearTree(root);
    return 0;
}

#include <iostream>

// Triển khai bằng danh sách liên kết đơn (Singly Linked List) và Merge Sort trên Linked List.

struct Node {
    long long val;
    Node* next;
    Node(long long v) : val(v), next(nullptr) {}
};

Node* merge(Node* a, Node* b) {
    Node dummy(0);
    Node* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) {
            tail->next = a;
            a = a->next;
        } else {
            tail->next = b;
            b = b->next;
        }
        tail = tail->next;
    }
    tail->next = (a ? a : b);
    return dummy.next;
}

void split(Node* source, Node** frontRef, Node** backRef) {
    Node* fast = source->next;
    Node* slow = source;
    while (fast != nullptr) {
        fast = fast->next;
        if (fast != nullptr) {
            slow = slow->next;
            fast = fast->next;
        }
    }
    *frontRef = source;
    *backRef = slow->next;
    slow->next = nullptr;
}

void mergeSort(Node** headRef) {
    Node* head = *headRef;
    if (!head || !head->next) return;
    Node* a = nullptr;
    Node* b = nullptr;
    split(head, &a, &b);
    mergeSort(&a);
    mergeSort(&b);
    *headRef = merge(a, b);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    if (!(std::cin >> n)) return 0;
    Node* head = nullptr;
    Node* tail = nullptr;
    for (int i = 0; i < n; ++i) {
        long long x;
        std::cin >> x;
        Node* newNode = new Node(x);
        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }
    mergeSort(&head);
    Node* cur = head;
    bool first = true;
    while (cur) {
        if (!first) std::cout << " ";
        std::cout << cur->val;
        first = false;
        Node* temp = cur;
        cur = cur->next;
        delete temp;
    }
    std::cout << "\n";
    return 0;
}

