#include <iostream>
#include <vector>

using namespace std;

void swapElements(long long &x, long long &y) {
    long long temp = x;
    x = y;
    y = temp;
}

void heapify(vector<long long> &arr, int n, int i) {
    int largest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < n && arr[left] > arr[largest])
        largest = left;

    if (right < n && arr[right] > arr[largest])
        largest = right;

    if (largest != i) {
        swapElements(arr[i], arr[largest]);
        heapify(arr, n, largest);
    }
}

void heapSort(vector<long long> &arr, int n) {
    for (int i = n / 2 - 1; i >= 0; i--)
        heapify(arr, n, i);

    for (int i = n - 1; i > 0; i--) {
        swapElements(arr[0], arr[i]);
        heapify(arr, i, 0);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    heapSort(a, n);

    for (int i = 0; i < n; ++i) {
        cout << a[i] << (i + 1 == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}

