bool isPerfect(int x) {
    if (x <= 1) return false;
    int sum = 1;
    for (int i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            sum += i;
            if (i * i != x) {
                sum += x / i;
            }
        }
    }
    return sum == x;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> result;
    for (int i = 1; i <= n; ++i) {
        if (isPerfect(i)) {
            result.push_back(i);
        }
    }

    if (result.empty()) {
        cout << -1 << "\n";
    } else {
        for (size_t i = 0; i < result.size(); ++i) {
            cout << result[i] << (i + 1 == result.size() ? "" : " ");
        }
        cout << "\n";
    }
    return 0;
}

