#include <iostream>
#include <vector>

using namespace std;

const int MAXN = 1000000;
bool is_prime[MAXN + 1];

void sieve() {
    for (int i = 2; i <= MAXN; ++i) is_prime[i] = true;
    for (int p = 2; p * p <= MAXN; ++p) {
        if (is_prime[p]) {
            for (int i = p * p; i <= MAXN; i += p) {
                is_prime[i] = false;
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    sieve();
    int n;
    if (cin >> n) {
        bool found = false;
        for (int p = 2; p <= n / 2; ++p) {
            if (is_prime[p] && is_prime[n - p]) {
                cout << p << " " << n - p << "\n";
                found = true;
                break;
            }
        }
        if (!found) {
            cout << -1 << "\n";
        }
    }
    return 0;
}

#include <iostream>

using namespace std;

bool checkPrime(int k) {
    if (k < 2) return false;
    if (k == 2 || k == 3) return true;
    if (k % 2 == 0 || k % 3 == 0) return false;
    for (int i = 5; 1LL * i * i <= k; i += 6) {
        if (k % i == 0 || k % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (cin >> n) {
        int ans_p = -1, ans_q = -1;
        for (int p = 2; p <= n / 2; ++p) {
            if (checkPrime(p) && checkPrime(n - p)) {
                ans_p = p;
                ans_q = n - p;
                break;
            }
        }
        if (ans_p != -1) {
            cout << ans_p << " " << ans_q << "\n";
        } else {
            cout << -1 << "\n";
        }
    }
    return 0;
}

