using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;

    vector<int> primes;
    primes.reserve(n);

    long long total_sum = 0;
    int candidate = 2;
    while ((int)primes.size() < n) {
        bool is_prime = true;
        for (int p : primes) {
            if ((long long)p * p > candidate) break;
            if (candidate % p == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            primes.push_back(candidate);
            total_sum += candidate;
        }
        candidate++;
    }

    cout << total_sum << "\n";
    return 0;
}

