using namespace std;

const double EPS = 1e-9;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double a, b, c;
    if (!(cin >> a >> b >> c)) return 0;

    double delta = b * b - 4 * a * c;
    vector<double> roots_t;

    if (delta < -EPS) {
        // delta < 0: vo nghiem
    } else if (abs(delta) <= EPS) {
        roots_t.push_back(-b / (2 * a));
    } else {
        double sqrt_d = sqrt(delta);
        roots_t.push_back((-b - sqrt_d) / (2 * a));
        roots_t.push_back((-b + sqrt_d) / (2 * a));
    }

    vector<double> x;
    for (double t : roots_t) {
        if (t > EPS) {
            double r = sqrt(t);
            x.push_back(-r);
            x.push_back(r);
        } else if (abs(t) <= EPS) {
            x.push_back(0.0);
        }
    }

    sort(x.begin(), x.end());
    vector<double> unique_x;
    for (double val : x) {
        if (unique_x.empty() || abs(val - unique_x.back()) > EPS) {
            unique_x.push_back(val);
        }
    }

    if (unique_x.empty()) {
        cout << "VO NGHIEM\n";
    } else {
        cout << unique_x.size() << "\n";
        cout << fixed << setprecision(4);
        for (size_t i = 0; i < unique_x.size(); ++i) {
            double v = unique_x[i];
            if (abs(v) < 1e-7) v = 0.0;
            cout << v << (i + 1 == unique_x.size() ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

#include <cstdio>
#include <cmath>
#include <vector>
#include <algorithm>

using namespace std;

int solveQuadratic(double a, double b, double c, double &t1, double &t2) {
    double delta = b * b - 4.0 * a * c;
    if (delta < -1e-9) return 0;
    if (fabs(delta) <= 1e-9) {
        t1 = -b / (2.0 * a);
        return 1;
    }
    double s = sqrt(delta);
    t1 = (-b - s) / (2.0 * a);
    t2 = (-b + s) / (2.0 * a);
    return 2;
}

int main() {
    double a, b, c;
    if (scanf("%lf %lf %lf", &a, &b, &c) != 3) return 0;

    double t1 = 0, t2 = 0;
    int num_t = solveQuadratic(a, b, c, t1, t2);

    vector<double> res;
    auto addRoots = [&](double t) {
        if (t > 1e-9) {
            double val = sqrt(t);
            res.push_back(-val);
            res.push_back(val);
        } else if (fabs(t) <= 1e-9) {
            res.push_back(0.0);
        }
    };

    if (num_t >= 1) addRoots(t1);
    if (num_t == 2) addRoots(t2);

    sort(res.begin(), res.end());
    vector<double> ans;
    for (double r : res) {
        if (ans.empty() || fabs(r - ans.back()) > 1e-7) {
            ans.push_back(r);
        }
    }

    if (ans.empty()) {
        printf("VO NGHIEM\n");
    } else {
        printf("%zu\n", ans.size());
        for (size_t i = 0; i < ans.size(); ++i) {
            double val = ans[i];
            if (fabs(val) < 1e-6) val = 0.0;
            printf("%.4f%c", val, i + 1 == ans.size() ? '\n' : ' ');
        }
    }

    return 0;
}

