using namespace std;

struct Person {
    string fullName;
    string firstName;
};

string getFirstName(const string& s) {
    size_t pos = s.rfind(' ');
    if (pos == string::npos) {
        return s;
    }
    return s.substr(pos + 1);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);
    vector<Person> a(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, a[i].fullName);
        a[i].firstName = getFirstName(a[i].fullName);
    }
    sort(a.begin(), a.end(), [](const Person& x, const Person& y) {
        if (x.firstName != y.firstName) {
            return x.firstName < y.firstName;
        }
        return x.fullName < y.fullName;
    });
    for (int i = 0; i < n; ++i) {
        cout << a[i].fullName << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

pair<string, string> extractKeys(const string& full) {
    int idx = -1;
    for (int i = (int)full.length() - 1; i >= 0; --i) {
        if (full[i] == ' ') {
            idx = i;
            break;
        }
    }
    string name = (idx == -1) ? full : full.substr(idx + 1);
    return {name, full};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (cin >> n) {
        string line;
        getline(cin, line);
        vector<string> names(n);
        for (int i = 0; i < n; ++i) {
            getline(cin, names[i]);
        }
        sort(names.begin(), names.end(), [](const string& a, const string& b) {
            auto ka = extractKeys(a);
            auto kb = extractKeys(b);
            if (ka.first != kb.first) {
                return ka.first < kb.first;
            }
            return ka.second < kb.second;
        });
        for (const auto& s : names) {
            cout << s << "\n";
        }
    }
    return 0;
}

