using namespace std;

const string digits[] = {"khong", "mot", "hai", "ba", "bon", "nam", "sau", "bay", "tam", "chin"};

void read_block(int n, bool has_higher, vector<string>& words) {
    int c = n / 100;
    int b = (n / 10) % 10;
    int a = n % 10;

    if (has_higher || c > 0) {
        words.push_back(digits[c]);
        words.push_back("tram");
    }

    if (b == 0 && a != 0) {
        if (has_higher || c > 0) {
            words.push_back("linh");
        }
        words.push_back(digits[a]);
    } else if (b == 1) {
        words.push_back("muoi");
        if (a == 5) {
            words.push_back("lam");
        } else if (a != 0) {
            words.push_back(digits[a]);
        }
    } else if (b > 1) {
        words.push_back(digits[b]);
        words.push_back("muoi");
        if (a == 1) {
            words.push_back("mot");
        } else if (a == 4) {
            words.push_back("tu");
        } else if (a == 5) {
            words.push_back("lam");
        } else if (a != 0) {
            words.push_back(digits[a]);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long N;
    if (!(cin >> N)) return 0;
    if (N == 0) {
        cout << "khong\n";
        return 0;
    }
    if (N == 1000000000LL) {
        cout << "mot ty\n";
        return 0;
    }

    int ty = N / 1000000000LL;
    int trieu = (N / 1000000) % 1000;
    int nghin = (N / 1000) % 1000;
    int donvi = N % 1000;

    vector<string> words;
    bool has_higher = false;

    if (ty > 0) {
        read_block(ty, false, words);
        words.push_back("ty");
        has_higher = true;
    }
    if (trieu > 0) {
        read_block(trieu, has_higher, words);
        words.push_back("trieu");
        has_higher = true;
    }
    if (nghin > 0) {
        read_block(nghin, has_higher, words);
        words.push_back("nghin");
        has_higher = true;
    }
    if (donvi > 0) {
        read_block(donvi, has_higher, words);
    }

    for (size_t i = 0; i < words.size(); ++i) {
        cout << words[i] << (i + 1 < words.size() ? " " : "\n");
    }
    return 0;
}

#include <iostream>
#include <string>
