using namespace std;

string get_word(int d) {
    static const char* text[] = {"khong", "mot", "hai", "ba", "bon", "nam", "sau", "bay", "tam", "chin"};
    return text[d];
}

int main() {
    long long n;
    if (!(cin >> n)) return 0;
    if (n == 0) {
        cout << "khong\n";
        return 0;
    }

    int groups[4];
    groups[3] = n / 1000000000LL;       // ty
    groups[2] = (n / 1000000) % 1000;    // trieu
    groups[1] = (n / 1000) % 1000;       // nghin
    groups[0] = n % 1000;                // don vi

    const string scale_names[] = {"", "nghin", "trieu", "ty"};

    vector<string> res;
    bool has_prev = false;

    for (int i = 3; i >= 0; --i) {
        int val = groups[i];
        if (val == 0) continue;

        int h = val / 100;
        int t = (val / 10) % 10;
        int u = val % 10;

        if (has_prev || h > 0) {
            res.push_back(get_word(h));
            res.push_back("tram");
        }

        if (t == 0) {
            if (u > 0) {
                if (has_prev || h > 0) {
                    res.push_back("linh");
                }
                res.push_back(get_word(u));
            }
        } else if (t == 1) {
            res.push_back("muoi");
            if (u == 5) res.push_back("lam");
            else if (u > 0) res.push_back(get_word(u));
        } else {
            res.push_back(get_word(t));
            res.push_back("muoi");
            if (u == 1) res.push_back("mot");
            else if (u == 4) res.push_back("tu");
            else if (u == 5) res.push_back("lam");
            else if (u > 0) res.push_back(get_word(u));
        }

        if (i > 0) {
            res.push_back(scale_names[i]);
        }
        has_prev = true;
    }

    for (size_t i = 0; i < res.size(); ++i) {
        if (i > 0) cout << " ";
        cout << res[i];
    }
    cout << "\n";
    return 0;
}

