#include <iostream>
#include <vector>

using namespace std;

#define SWAP(x, y) do { auto temp = (x); (x) = (y); (y) = temp; } while (0)

void quickSort(vector<long long>& a, int left, int right) {
    int i = left, j = right;
    long long pivot = a[left + (right - left) / 2];
    while (i <= j) {
        while (a[i] < pivot) i++;
        while (a[j] > pivot) j--;
        if (i <= j) {
            SWAP(a[i], a[j]);
            i++;
            j--;
        }
    }
    if (left < j) quickSort(a, left, j);
    if (i < right) quickSort(a, i, right);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    if (n > 1) {
        quickSort(a, 0, n - 1);
    }

    for (int i = 0; i < n; ++i) {
        cout << a[i] << (i + 1 == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}

