using namespace std;

struct SoPhuc {
    double re;
    double im;
};

SoPhuc cong(SoPhuc u, SoPhuc v) {
    return {u.re + v.re, u.im + v.im};
}

SoPhuc tru(SoPhuc u, SoPhuc v) {
    return {u.re - v.re, u.im - v.im};
}

SoPhuc nhan(SoPhuc u, SoPhuc v) {
    return {u.re * v.re - u.im * v.im, u.re * v.im + u.im * v.re};
}

void inSoThuc(double val) {
    if (abs(val) < 1e-9) val = 0.0;
    // Làm tròn đến 2 chữ số thập phân để tránh in -0.00
    double rounded = round(val * 100.0) / 100.0;
    if (abs(rounded) < 1e-9) rounded = 0.0;
    cout << fixed << setprecision(2) << rounded;
}

void inSoPhuc(SoPhuc z) {
    inSoThuc(z.re);
    cout << " ";
    inSoThuc(z.im);
    cout << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    SoPhuc z1, z2;
    if (!(cin >> z1.re >> z1.im >> z2.re >> z2.im)) return 0;

    inSoPhuc(cong(z1, z2));
    inSoPhuc(tru(z1, z2));
    inSoPhuc(nhan(z1, z2));

    double mau = z2.re * z2.re + z2.im * z2.im;
    if (mau < 1e-12) {
        cout << "KHONG THE CHIA\n";
    } else {
        SoPhuc thuong;
        thuong.re = (z1.re * z2.re + z1.im * z2.im) / mau;
        thuong.im = (z1.im * z2.re - z1.re * z2.im) / mau;
        inSoPhuc(thuong);
    }

    return 0;
}

#include <cstdio>
#include <cmath>

typedef struct {
    double thuc;
    double ao;
} Complex;

Complex add(Complex a, Complex b) {
    Complex c = {a.thuc + b.thuc, a.ao + b.ao};
    return c;
}

Complex sub(Complex a, Complex b) {
    Complex c = {a.thuc - b.thuc, a.ao - b.ao};
    return c;
}

Complex mul(Complex a, Complex b) {
    Complex c = {a.thuc * b.thuc - a.ao * b.ao, a.thuc * b.ao + a.ao * b.thuc};
    return c;
}

void printComplex(Complex z) {
    double r = round(z.thuc * 100.0) / 100.0;
    double i = round(z.ao * 100.0) / 100.0;
    if (std::abs(r) < 1e-7) r = 0.0;
    if (std::abs(i) < 1e-7) i = 0.0;
    printf("%.2f %.2f\n", r, i);
}

int main() {
    Complex z1, z2;
    if (scanf("%lf %lf %lf %lf", &z1.thuc, &z1.ao, &z2.thuc, &z2.ao) == 4) {
        printComplex(add(z1, z2));
        printComplex(sub(z1, z2));
        printComplex(mul(z1, z2));

        double denom = z2.thuc * z2.thuc + z2.ao * z2.ao;
        if (denom < 1e-12) {
            printf("KHONG THE CHIA\n");
        } else {
            Complex div;
            div.thuc = (z1.thuc * z2.thuc + z1.ao * z2.ao) / denom;
            div.ao = (z1.ao * z2.thuc - z1.thuc * z2.ao) / denom;
            printComplex(div);
        }
    }
    return 0;
}

#include <iostream>
#include <numeric>

using namespace std;

struct PhanSo {
    long long tu, mau;
};

long long gcd(long long a, long long b) {
    a = abs(a);
    b = abs(b);
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

PhanSo rutGon(PhanSo p) {
    if (p.mau < 0) {
        p.tu = -p.tu;
        p.mau = -p.mau;
    }
    if (p.tu == 0) {
        return {0, 1};
    }
    long long g = gcd(p.tu, p.mau);
    p.tu /= g;
    p.mau /= g;
    return p;
}

PhanSo cong(PhanSo a, PhanSo b) {
    PhanSo res;
    res.tu = a.tu * b.mau + b.tu * a.mau;
    res.mau = a.mau * b.mau;
    return rutGon(res);
}

PhanSo tru(PhanSo a, PhanSo b) {
    PhanSo res;
    res.tu = a.tu * b.mau - b.tu * a.mau;
    res.mau = a.mau * b.mau;
    return rutGon(res);
}

PhanSo nhan(PhanSo a, PhanSo b) {
    PhanSo res;
    res.tu = a.tu * b.tu;
    res.mau = a.mau * b.mau;
    return rutGon(res);
}

void inPhanSo(PhanSo p) {
    cout << p.tu << "/" << p.mau << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long a, b, c, d;
    if (!(cin >> a >> b >> c >> d)) return 0;
    PhanSo p1 = rutGon({a, b});
    PhanSo p2 = rutGon({c, d});

    inPhanSo(cong(p1, p2));
    inPhanSo(tru(p1, p2));
    inPhanSo(nhan(p1, p2));

    if (p2.tu == 0) {
        cout << "KHONG XAC DINH\n";
    } else {
        PhanSo thuong;
        thuong.tu = p1.tu * p2.mau;
        thuong.mau = p1.mau * p2.tu;
        inPhanSo(rutGon(thuong));
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fraction {
    long long num, den;

    void simplify() {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        if (num == 0) {
            den = 1;
            return;
        }
        long long g = std::gcd(std::abs(num), std::abs(den));
        num /= g;
        den /= g;
    }
};

int main() {
    long long a, b, c, d;
    if (cin >> a >> b >> c >> d) {
        Fraction f1{a, b}, f2{c, d};
        f1.simplify();
        f2.simplify();

        // Sum
        Fraction sum{f1.num * f2.den + f2.num * f1.den, f1.den * f2.den};
        sum.simplify();
        cout << sum.num << "/" << sum.den << "\n";

        // Diff
        Fraction diff{f1.num * f2.den - f2.num * f1.den, f1.den * f2.den};
        diff.simplify();
        cout << diff.num << "/" << diff.den << "\n";

        // Product
        Fraction prod{f1.num * f2.num, f1.den * f2.den};
        prod.simplify();
        cout << prod.num << "/" << prod.den << "\n";

        // Quotient
        if (f2.num == 0) {
            cout << "KHONG XAC DINH\n";
        } else {
            Fraction quot{f1.num * f2.den, f1.den * f2.num};
            quot.simplify();
            cout << quot.num << "/" << quot.den << "\n";
        }
    }
    return 0;
}

