// Chuyển đổi ngày sang số ngày tính từ 01/01/0001
long long dateToDays(int d, int m, int y) {
    long long totalDays = 0;
    int prevY = y - 1;
    totalDays += 1LL * prevY * 365 + (prevY / 4) - (prevY / 100) + (prevY / 400);
    for (int i = 1; i < m; ++i) {
        totalDays += daysInMonth(i, y);
    }
    totalDays += d;
    return totalDays;
}

