    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int d1, m1, y1;
    int d2, m2, y2;
    if (cin >> d1 >> m1 >> y1 >> d2 >> m2 >> y2) {
        long long days1 = dateToDays(d1, m1, y1);
        long long days2 = dateToDays(d2, m2, y2);
        cout << llabs(days1 - days2) << "\n";
    }
    return 0;
}

