// Chuyển đổi theo thuật toán Rata Die
long long toRataDie(int d, int m, int y) {
    if (m < 3) {
        m += 12;
        y -= 1;
    }
    return 365LL * y + y / 4 - y / 100 + y / 400 + (153 * (m + 1)) / 5 + d - 428;
}

