#include <iostream>
#include <string>

using namespace std;

bool isLeapYear(int y) {
    return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
}

int daysInMonth(int m, int y) {
    switch (m) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return isLeapYear(y) ? 29 : 28;
    }
    return 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int d, m, y;
    if (!(cin >> d >> m >> y)) return 0;

    // Using Zeller's congruence
    // For Gregorian calendar:
    // h = (q + [13(m+1)/5] + K + [K/4] + [J/4] - 2J) mod 7
    // where m = 3..14 (Jan and Feb are 13 and 14 of year-1)
    int m_adj = m;
    int y_adj = y;
    if (m_adj <= 2) {
        m_adj += 12;
        y_adj -= 1;
    }
    int K = y_adj % 100;
    int J = y_adj / 100;
    int h = (d + (13 * (m_adj + 1)) / 5 + K + K / 4 + J / 4 - 2 * J) % 7;
    if (h < 0) h = (h + 7) % 7;
    // h: 0 = Saturday, 1 = Sunday, 2 = Monday, ..., 6 = Friday
    string names[] = {"Thu Bay", "Chu Nhat", "Thu Hai", "Thu Ba", "Thu Tu", "Thu Nam", "Thu Sau"};
    cout << names[h] << "\n";
    return 0;
}

