// Sakamoto's algorithm
// Returns 0 for Sunday, 1 for Monday, etc.
int dayOfWeek(int d, int m, int y) {
    static int t[] = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4};
    if (m < 3) {
        y -= 1;
    }
    return (y + y / 4 - y / 100 + y / 400 + t[m - 1] + d) % 7;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int d, m, y;
