        int dow = dayOfWeek(d, m, y);
        string names[] = {"Chu Nhat", "Thu Hai", "Thu Ba", "Thu Tu", "Thu Nam", "Thu Sau", "Thu Bay"};
        cout << names[dow] << "\n";
    }
    return 0;
}

