    if (!(cin >> n >> k)) return 0;

    Node* head = nullptr;
    Node* tail = nullptr;

    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        Node* newNode = new Node(c);
        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    if (k < n) {
        // Tìm nút thứ k
        Node* kthNode = head;
        for (int i = 1; i < k; ++i) {
            kthNode = kthNode->next;
        }
        // Nối đuôi cũ với đầu cũ
        tail->next = head;
        // Đầu mới là phần tử sau nút k
