    long double W, v1, v2;
    if (cin >> W >> v1 >> v2) {
        long double t_meet = W / (v1 + v2);
        long double x_meet = v1 * t_meet;
        // Sau khi gặp nhau, người 1 đi từ x_meet về 0 với vận tốc v1 mất thời gian x_meet / v1 = t_meet.
        // Người 2 đi từ x_meet về W với vận tốc v2 mất thời gian (W - x_meet) / v2 = t_meet.
        // Do đó cả hai quay lại biên đúng vào thời điểm t_meet + t_meet = 2 * t_meet.
        long double t1_return = t_meet + (x_meet / v1);
        long double t2_return = t_meet + ((W - x_meet) / v2);
        long double t_end = max(t1_return, t2_return);

        cout << fixed << setprecision(4) << (double)t_meet << " " << (double)x_meet << "\n";
        cout << fixed << setprecision(4) << (double)t_end << "\n";
    }
    return 0;
}

