        for (int k = 0; k < n; ++k) {
            for (int j = 0; j < p; ++j) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            cout << C[i][j] << (j + 1 == p ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

