#include <iostream>
#include <vector>
#include <string>
#include <iomanip>

using namespace std;

struct Student {
    string id;
    string name;
    string dob;
    string gender;
    double score;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    vector<Student> list;
    string cmd;
    while (cin >> cmd) {
        if (cmd == "QUIT") break;
        if (cmd == "ADD") {
            string id, name, dob, gender;
            double score;
            cin >> id >> name >> dob >> gender >> score;
            bool exists = false;
            for (const auto& s : list) {
                if (s.id == id) {
                    exists = true;
                    break;
                }
            }
            if (!exists) {
                list.push_back({id, name, dob, gender, score});
            }
        } else if (cmd == "VIEW") {
            string id;
            cin >> id;
            bool found = false;
            for (const auto& s : list) {
                if (s.id == id) {
                    cout << s.id << " " << s.name << " " << s.dob << " " << s.gender << " " << fixed << setprecision(2) << s.score << "\n";
                    found = true;
                    break;
                }
            }
            if (!found) {
                cout << "NOT FOUND\n";
            }
        } else if (cmd == "DELETE") {
            string id;
            cin >> id;
            bool found = false;
            for (auto it = list.begin(); it != list.end(); ++it) {
                if (it->id == id) {
                    list.erase(it);
                    found = true;
                    cout << "DELETED\n";
                    break;
                }
            }
            if (!found) {
                cout << "NOT FOUND\n";
            }
        } else if (cmd == "UPDATE") {
            string id, name, dob, gender;
            double score;
            cin >> id >> name >> dob >> gender >> score;
            bool found = false;
            for (auto& s : list) {
                if (s.id == id) {
                    s.name = name;
                    s.dob = dob;
                    s.gender = gender;
                    s.score = score;
                    found = true;
                    cout << "UPDATED\n";
                    break;
                }
            }
            if (!found) {
                cout << "NOT FOUND\n";
            }
        } else if (cmd == "AVERAGE") {
            if (list.empty()) {
                cout << "0.00\n";
            } else {
                double sum = 0;
                for (const auto& s : list) sum += s.score;
                cout << fixed << setprecision(2) << (sum / list.size()) << "\n";
            }
        } else if (cmd == "ALL") {
            if (list.empty()) {
                cout << "EMPTY\n";
            } else {
                for (const auto& s : list) {
                    cout << s.id << " " << s.name << " " << s.dob << " " << s.gender << " " << fixed << setprecision(2) << s.score << "\n";
                }
            }
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Record {
    string id, name, dob, gender;
    double score;
};

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);
    vector<Record> students;
    string op;

    auto find_student = [&](const string& id) -> int {
        for (int i = 0; i < (int)students.size(); ++i) {
            if (students[i].id == id) return i;
        }
        return -1;
    };

    while (cin >> op) {
        if (op == "QUIT") break;
        if (op == "ADD") {
            Record r;
            cin >> r.id >> r.name >> r.dob >> r.gender >> r.score;
            if (find_student(r.id) == -1) {
                students.push_back(r);
            }
        } else if (op == "VIEW") {
            string id;
            cin >> id;
            int idx = find_student(id);
            if (idx != -1) {
                cout << students[idx].id << " " << students[idx].name << " "
                     << students[idx].dob << " " << students[idx].gender << " "
                     << fixed << setprecision(2) << students[idx].score << "\n";
            } else {
                cout << "NOT FOUND\n";
            }
        } else if (op == "DELETE") {
            string id;
            cin >> id;
            int idx = find_student(id);
            if (idx != -1) {
                students.erase(students.begin() + idx);
                cout << "DELETED\n";
            } else {
                cout << "NOT FOUND\n";
            }
        } else if (op == "UPDATE") {
            string id, name, dob, gender;
            double score;
            cin >> id >> name >> dob >> gender >> score;
            int idx = find_student(id);
            if (idx != -1) {
                students[idx] = {id, name, dob, gender, score};
                cout << "UPDATED\n";
            } else {
                cout << "NOT FOUND\n";
            }
        } else if (op == "AVERAGE") {
            if (students.empty()) {
                cout << "0.00\n";
            } else {
                double total = 0;
                for (auto &st : students) total += st.score;
                cout << fixed << setprecision(2) << (total / (double)students.size()) << "\n";
            }
        } else if (op == "ALL") {
            if (students.empty()) {
                cout << "EMPTY\n";
            } else {
                for (auto &st : students) {
                    cout << st.id << " " << st.name << " " << st.dob << " "
                         << st.gender << " " << fixed << setprecision(2) << st.score << "\n";
                }
            }
        }
    }
    return 0;
}

