        printf("The miles/gallon for this tank was %.6f\n", tank_mpg);
        sum_m += miles;
        sum_g += gallons;
    }

    if (sum_g > 0.0) {
        printf("The overall average miles/gallon was %.6f\n", sum_m / sum_g);
    }

