#include <cstdio>

void print_seq(int start, int end, int step) {
    if (step > 0) {
        for (int v = start; v <= end; v += step) {
            printf("%d%c", v, (v + step > end ? '\n' : ' '));
        }
    } else {
        for (int v = start; v >= end; v += step) {
            printf("%d%c", v, (v + step < end ? '\n' : ' '));
        }
    }
}

int main() {
    char opt;
    while (scanf(" %c", &opt) == 1) {
        switch (opt) {
            case 'a':
                print_seq(1, 7, 1);
                break;
            case 'b':
                print_seq(3, 23, 5);
                break;
            case 'c':
                print_seq(20, -10, -6);
                break;
            case 'd':
                print_seq(19, 51, 8);
                break;
            default:
                break;
        }
    }
    return 0;
}

