#include <vector>
#include <utility>

using namespace std;

void solve() {
    int type;
    string s;
    if (!(cin >> type >> s)) return;
    vector<int> d(4);
    for (int i = 0; i < 4; ++i) {
        d[i] = s[i] - '0';
    }
    if (type == 1) {
        for (int i = 0; i < 4; ++i) {
            d[i] = (d[i] + 7) % 10;
        }
        swap(d[0], d[2]);
        swap(d[1], d[3]);
    } else {
        swap(d[0], d[2]);
        swap(d[1], d[3]);
        for (int i = 0; i < 4; ++i) {
            d[i] = (d[i] + 10 - 7) % 10;
        }
    }
    for (int i = 0; i < 4; ++i) {
        cout << d[i];
    }
    cout << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
