                stars = i;
                break;
            case 'B':
                spaces = 0;
                stars = n - i + 1;
                break;
            case 'C':
                spaces = i - 1;
                stars = n - i + 1;
                break;
            case 'D':
                spaces = n - i;
                stars = i;
                break;
        }
        for (int s = 0; s < spaces; ++s) putchar(' ');
        for (int st = 0; st < stars; ++st) putchar('*');
        putchar('\n');
    }
