#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    long long N;
    double eps;
    if (!(std::cin >> N >> eps)) return 0;

    double pi_approx = 0.0;
    for (long long i = 1; i <= N; ++i) {
        double term = 4.0 / (2.0 * i - 1.0);
        if (i % 2 == 1) {
            pi_approx += term;
        } else {
            pi_approx -= term;
        }
    }

    const double PI_CONST = 3.14159265358979323846;

    // Chuỗi Leibniz là chuỗi đan dấu có số hạng giảm dần về 0.
    // Ta có thể tìm k trực tiếp hoặc tính toán: sai số |S_k - pi| xấp xỉ hoặc bằng cách lặp nếu k nhỏ.
    // Vì epsilon >= 10^-6, k có thể lên tới khoảng 2/eps ~ 2 * 10^6.
    // Ta duyệt tìm k nhỏ nhất.
    long long k_found = -1;
    double current_pi = 0.0;
    for (long long k = 1; ; ++k) {
        double term = 4.0 / (2.0 * k - 1.0);
        if (k % 2 == 1) {
            current_pi += term;
        } else {
            current_pi -= term;
        }
        if (std::abs(current_pi - PI_CONST) <= eps) {
            k_found = k;
            break;
        }
    }

    std::cout << std::fixed << std::setprecision(8) << pi_approx << "\n";
    std::cout << k_found << "\n";

    return 0;
}

#include <cstdio>
#include <cmath>

int main() {
    long long n;
    double eps;
    if (scanf("%lld %lf", &n, &eps) != 2) return 0;

    double sum_n = 0.0;
    double sign = 1.0;
    for (long long i = 1; i <= n; ++i) {
        sum_n += sign * (4.0 / (2LL * i - 1LL));
        sign = -sign;
    }

    const double target_pi = std::acos(-1.0);
    long long k = 1;
    double cur_sum = 0.0;
    double cur_sign = 1.0;
    while (true) {
        cur_sum += cur_sign * (4.0 / (2LL * k - 1LL));
        cur_sign = -cur_sign;
        if (std::fabs(cur_sum - target_pi) <= eps) {
            break;
        }
        ++k;
    }

    printf("%.8f\n%lld\n", sum_n, k);
    return 0;
}

