// Làm tròn số hữu tỉ a / b về số nguyên gần nhất (b > 0)
// round(a/b) = floor(a/b + 0.5) với số dương, đối xứng qua 0
long long roundDiv(long long num, long long den) {
    if (den < 0) {
        num = -num;
        den = -den;
    }
    if (num >= 0) {
        return (num + den / 2) / den;
    } else {
        return (num - den / 2) / den;
    }
}

long long cToF(long long c) {
    // F = 9/5 * C + 32 = (9 * C + 160) / 5
    return roundDiv(9LL * c + 160LL, 5LL);
}

long long fToC(long long f) {
    // C = 5/9 * (F - 32) = 5 * (F - 32) / 9
    return roundDiv(5LL * (f - 32LL), 9LL);
}

