#include <iostream>
#include <vector>

struct Move {
    int n;
    int from;
    int to;
    int aux;
};

void solveHanoi(int n, int src, int dst, int tmp) {
    std::vector<Move> st;
    st.push_back({n, src, dst, tmp});
    while (!st.empty()) {
        Move cur = st.back();
        st.pop_back();
        if (cur.n == 1) {
            std::cout << cur.from << " -> " << cur.to << "\n";
        } else {
            // Push operations in reverse order: 3rd step, 2nd step, 1st step
            st.push_back({cur.n - 1, cur.aux, cur.to, cur.from});
            st.push_back({1, cur.from, cur.to, cur.aux});
            st.push_back({cur.n - 1, cur.from, cur.aux, cur.to});
        }
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    if (std::cin >> n) {
        solveHanoi(n, 1, 3, 2);
    }
