    int n;
    if (!(cin >> n)) return 0;

    // sales[product - 1][salesperson - 1]
    // 5 products (rows 0..4), 4 salespersons (cols 0..3)
    double sales[6][5] = {0.0};

    for (int i = 0; i < n; ++i) {
        int s, p;
        double v;
        cin >> s >> p >> v;
        if (s >= 1 && s <= 4 && p >= 1 && p <= 5) {
            sales[p - 1][s - 1] += v;
        }
    }

    // Compute row totals
    for (int p = 0; p < 5; ++p) {
        double row_sum = 0.0;
        for (int s = 0; s < 4; ++s) {
            row_sum += sales[p][s];
        }
        sales[p][4] = row_sum;
    }

    // Compute column totals
    for (int s = 0; s < 5; ++s) {
        double col_sum = 0.0;
        for (int p = 0; p < 5; ++p) {
            col_sum += sales[p][s];
        }
        sales[5][s] = col_sum;
    }

    cout << fixed << setprecision(2);
    for (int r = 0; r < 6; ++r) {
        for (int c = 0; c < 5; ++c) {
            cout << sales[r][c] << (c == 4 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

