#include <cctype>

using namespace std;

bool isPalindromeRec(const string& s, int left, int right) {
    while (left < right && !isalnum(static_cast<unsigned char>(s[left]))) {
        left++;
    }
    while (left < right && !isalnum(static_cast<unsigned char>(s[right]))) {
        right--;
    }
    if (left >= right) {
        return true;
    }
    if (tolower(static_cast<unsigned char>(s[left])) != tolower(static_cast<unsigned char>(s[right]))) {
        return false;
    }
    return isPalindromeRec(s, left + 1, right - 1);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (getline(cin, s)) {
        cout << (isPalindromeRec(s, 0, (int)s.length() - 1) ? 1 : 0) << "\n";
    } else {
        cout << 1 << "\n";
    }
    return 0;
}

