#include <iostream>
#include <vector>
#include <algorithm>

// Đệ quy chia để trị / đệ quy giảm dần kích thước
// Để tránh tràn ngăn xếp khi n lên đến 10^5, dùng đệ quy chia đôi [l, r]
int findMinRec(const std::vector<int>& a, int l, int r) {
    if (l == r) {
        return a[l];
    }
    int mid = l + (r - l) / 2;
    int leftMin = findMinRec(a, l, mid);
    int rightMin = findMinRec(a, mid + 1, r);
    return std::min(leftMin, rightMin);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }
    std::cout << findMinRec(a, 0, n - 1) << "\n";
    return 0;
}

