// Đệ quy theo kích thước giảm dần dạng dải [start, end]
// Kết hợp theo khối để kiểm soát độ sâu ngăn xếp
int recursiveMinimum(const std::vector<int>& arr, int left, int right) {
    if (left >= right) {
        return arr[left];
    }
    int mid = left + (right - left) / 2;
    int m1 = recursiveMinimum(arr, left, mid);
    int m2 = recursiveMinimum(arr, mid + 1, right);
    return (m1 < m2) ? m1 : m2;
}

