const int MAX_VAL = 1000000;
vector<bool> prime(MAX_VAL + 1, true);

void sieve() {
    prime[0] = prime[1] = false;
    for (int p = 2; p * p <= MAX_VAL; p++) {
        if (prime[p]) {
            for (int i = p * p; i <= MAX_VAL; i += p)
                prime[i] = false;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    sieve();

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    int *ptr = a.data();
    long long total = 0;

    for (int i = 0; i < n; ++i) {
        cin >> *(ptr + i);
        int val = *(ptr + i);
        if (val >= 2 && val <= MAX_VAL && prime[val]) {
            total += val;
        }
    }

    cout << total << "\n";
    return 0;
}

