        ds[i].dtb = (ds[i].toan + ds[i].van) / 2.0;
        ds[i].id = i;
    }
    stable_sort(ds.begin(), ds.end(), [](const HocSinh& a, const HocSinh& b) {
        return a.dtb > b.dtb;
    });
    cout << fixed << setprecision(2);
    for (int i = 0; i < n; ++i) {
        cout << ds[i].hoTen << " " << ds[i].toan << " " << ds[i].van << " " << ds[i].dtb << "\n";
