#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

struct Element {
    long long val;
    int id;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<Element> b(n);
    for (int i = 0; i < n; ++i) {
        b[i] = {a[i], i};
    }

    sort(b.begin(), b.end(), [](const Element& x, const Element& y) {
        if (x.val != y.val) return x.val < y.val;
        return x.id < y.id;
    });

    long long min_diff = -1;
    int best_i = -1, best_j = -1;

    for (int k = 0; k < n - 1; ++k) {
        long long diff = b[k + 1].val - b[k].val;
        int u = min(b[k].id, b[k + 1].id);
        int v = max(b[k].id, b[k + 1].id);

        if (min_diff == -1 || diff < min_diff) {
            min_diff = diff;
            best_i = u;
            best_j = v;
        } else if (diff == min_diff) {
            if (u < best_i || (u == best_i && v < best_j)) {
                best_i = u;
                best_j = v;
            }
        }
    }

    long long val1 = a[best_i];
    long long val2 = a[best_j];
    if (val1 > val2) swap(val1, val2);

    cout << min_diff << " " << val1 << " " << val2 << "\n";
    return 0;
}

