#include <iostream>
#include <vector>

using namespace std;

void merge(vector<long long>& a, int left, int mid, int right) {
    vector<long long> temp(right - left + 1);
    int i = left, j = mid + 1, k = 0;
    while (i <= mid && j <= right) {
        if (a[i] <= a[j]) {
            temp[k++] = a[i++];
        } else {
            temp[k++] = a[j++];
        }
    }
    while (i <= mid) temp[k++] = a[i++];
    while (j <= right) temp[k++] = a[j++];
    for (int p = 0; p < k; ++p) {
        a[left + p] = temp[p];
    }
}

void mergeSort(vector<long long>& a, int left, int right) {
    if (left >= right) return;
    int mid = left + (right - left) / 2;
    mergeSort(a, left, mid);
    mergeSort(a, mid + 1, right);
    merge(a, left, mid, right);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    mergeSort(a, 0, n - 1);

    for (int i = 0; i < n; ++i) {
        cout << a[i] << (i == n - 1 ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <iomanip>

using namespace std;

struct Employee {
    string name;
    string dob;
    int gender; // 0: Nu, 1: Nam
    double salary;
    Employee* next;
    Employee(string n, string d, int g, double s) : name(n), dob(d), gender(g), salary(s), next(nullptr) {}
};

struct LinkedList {
    Employee* head = nullptr;
    Employee* tail = nullptr;
    int size = 0;

    void insertFirst(string name, string dob, int gender, double salary) {
        Employee* p = new Employee(name, dob, gender, salary);
        p->next = head;
        head = p;
        if (tail == nullptr) tail = p;
        size++;
    }

    void insertLast(string name, string dob, int gender, double salary) {
        Employee* p = new Employee(name, dob, gender, salary);
        if (tail == nullptr) {
            head = tail = p;
        } else {
            tail->next = p;
            tail = p;
        }
        size++;
    }

    void insertPos(int k, string name, string dob, int gender, double salary) {
        if (k < 1 || k > size + 1) return;
        if (k == 1) {
            insertFirst(name, dob, gender, salary);
            return;
        }
        if (k == size + 1) {
            insertLast(name, dob, gender, salary);
            return;
        }
        Employee* curr = head;
        for (int i = 1; i < k - 1; ++i) {
            curr = curr->next;
        }
        Employee* p = new Employee(name, dob, gender, salary);
        p->next = curr->next;
        curr->next = p;
        size++;
    }

    void deleteFirst() {
        if (size == 0) return;
        Employee* temp = head;
        head = head->next;
        delete temp;
        size--;
        if (size == 0) tail = nullptr;
    }

    void deleteLast() {
        if (size == 0) return;
        if (size == 1) {
            delete head;
            head = tail = nullptr;
            size = 0;
            return;
        }
        Employee* curr = head;
        while (curr->next != tail) {
            curr = curr->next;
        }
        delete tail;
        tail = curr;
        tail->next = nullptr;
        size--;
    }

    void deletePos(int k) {
        if (k < 1 || k > size) return;
        if (k == 1) {
            deleteFirst();
            return;
        }
        if (k == size) {
            deleteLast();
            return;
        }
        Employee* curr = head;
        for (int i = 1; i < k - 1; ++i) {
            curr = curr->next;
        }
        Employee* temp = curr->next;
        curr->next = temp->next;
        delete temp;
        size--;
    }

    void search(const string& name) {
        bool found = false;
        Employee* curr = head;
        while (curr != nullptr) {
            if (curr->name == name) {
                found = true;
                cout << curr->name << " " << curr->dob << " " << (curr->gender == 1 ? "Nam" : "Nu") << " " << fixed << setprecision(2) << curr->salary << "\n";
            }
            curr = curr->next;
        }
        if (!found) {
            cout << -1 << "\n";
        }
    }

    void print() {
        if (size == 0) {
            cout << "EMPTY\n";
            return;
        }
        Employee* curr = head;
        while (curr != nullptr) {
            cout << curr->name << " " << curr->dob << " " << (curr->gender == 1 ? "Nam" : "Nu") << " " << fixed << setprecision(2) << curr->salary << "\n";
            curr = curr->next;
        }
    }

    void sortSalary() {
        if (size <= 1) return;
        // Stable merge sort for singly linked list
        head = mergeSort(head);
        tail = head;
        while (tail && tail->next) {
            tail = tail->next;
        }
    }

private:
    Employee* mergeSort(Employee* start) {
        if (!start || !start->next) return start;
        Employee* slow = start;
        Employee* fast = start->next;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        Employee* mid = slow->next;
        slow->next = nullptr;

        Employee* left = mergeSort(start);
        Employee* right = mergeSort(mid);

        return merge(left, right);
    }

    Employee* merge(Employee* a, Employee* b) {
        Employee dummy("", "", 0, 0);
        Employee* tailPtr = &dummy;
        while (a && b) {
            // Descending order, stable: if a->salary >= b->salary, pick a
            if (a->salary >= b->salary) {
                tailPtr->next = a;
                a = a->next;
            } else {
                tailPtr->next = b;
                b = b->next;
            }
            tailPtr = tailPtr->next;
        }
        if (a) tailPtr->next = a;
        else tailPtr->next = b;
        return dummy.next;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int q;
    if (!(cin >> q)) return 0;
    LinkedList list;
    while (q--) {
        string op;
        cin >> op;
        if (op == "INSERT_FIRST") {
            string name, dob;
            int gender;
            double salary;
            cin >> name >> dob >> gender >> salary;
            list.insertFirst(name, dob, gender, salary);
        } else if (op == "INSERT_LAST") {
            string name, dob;
            int gender;
            double salary;
            cin >> name >> dob >> gender >> salary;
            list.insertLast(name, dob, gender, salary);
        } else if (op == "INSERT_POS") {
            int k;
            string name, dob;
            int gender;
            double salary;
            cin >> k >> name >> dob >> gender >> salary;
            list.insertPos(k, name, dob, gender, salary);
        } else if (op == "DELETE_FIRST") {
            list.deleteFirst();
        } else if (op == "DELETE_LAST") {
            list.deleteLast();
        } else if (op == "DELETE_POS") {
            int k;
            cin >> k;
            list.deletePos(k);
        } else if (op == "SEARCH") {
            string name;
            cin >> name;
            list.search(name);
        } else if (op == "PRINT") {
            list.print();
        } else if (op == "SORT_SALARY") {
            list.sortSalary();
        }
    }
    return 0;
}

#include <iostream>
