using namespace std;

struct Node {
    string name;
    string dob;
    int gender;
    double salary;
    Node* next;
    Node(string n, string d, int g, double s) : name(n), dob(d), gender(g), salary(s), next(nullptr) {}
};

class StaffList {
private:
    Node* head;
    int count;

public:
    StaffList() : head(nullptr), count(0) {}

    ~StaffList() {
        while (head) {
            Node* tmp = head;
            head = head->next;
            delete tmp;
        }
    }

    int size() const {
        return count;
    }

    void addFirst(const string& n, const string& d, int g, double s) {
        Node* p = new Node(n, d, g, s);
        p->next = head;
        head = p;
        count++;
    }

    void addLast(const string& n, const string& d, int g, double s) {
        Node* p = new Node(n, d, g, s);
        if (!head) {
            head = p;
        } else {
            Node* cur = head;
            while (cur->next) cur = cur->next;
            cur->next = p;
        }
        count++;
    }

    void addAt(int k, const string& n, const string& d, int g, double s) {
        if (k < 1 || k > count + 1) return;
        if (k == 1) {
            addFirst(n, d, g, s);
            return;
        }
        Node* cur = head;
        for (int i = 1; i < k - 1; ++i) {
            cur = cur->next;
        }
        Node* p = new Node(n, d, g, s);
        p->next = cur->next;
        cur->next = p;
        count++;
    }

    void removeFirst() {
        if (!head) return;
        Node* tmp = head;
        head = head->next;
        delete tmp;
        count--;
    }

    void removeLast() {
        if (!head) return;
        if (!head->next) {
            delete head;
            head = nullptr;
            count = 0;
            return;
        }
        Node* cur = head;
        while (cur->next->next) {
            cur = cur->next;
        }
        delete cur->next;
        cur->next = nullptr;
        count--;
    }

    void removeAt(int k) {
        if (k < 1 || k > count) return;
        if (k == 1) {
            removeFirst();
            return;
        }
        Node* cur = head;
        for (int i = 1; i < k - 1; ++i) {
            cur = cur->next;
        }
        Node* tmp = cur->next;
        cur->next = tmp->next;
        delete tmp;
        count--;
    }

    void searchName(const string& n) const {
        bool found = false;
        for (Node* cur = head; cur != nullptr; cur = cur->next) {
            if (cur->name == n) {
                found = true;
                cout << cur->name << " " << cur->dob << " " << (cur->gender == 1 ? "Nam" : "Nu") << " " << fixed << setprecision(2) << cur->salary << "\n";
            }
        }
        if (!found) {
            cout << -1 << "\n";
        }
    }

    void display() const {
        if (!head) {
            cout << "EMPTY\n";
            return;
        }
        for (Node* cur = head; cur != nullptr; cur = cur->next) {
            cout << cur->name << " " << cur->dob << " " << (cur->gender == 1 ? "Nam" : "Nu") << " " << fixed << setprecision(2) << cur->salary << "\n";
        }
    }

    void sortBySalary() {
        if (count <= 1) return;
        vector<Node*> nodes;
        for (Node* cur = head; cur != nullptr; cur = cur->next) {
            nodes.push_back(cur);
        }
        stable_sort(nodes.begin(), nodes.end(), [](Node* a, Node* b) {
            return a->salary > b->salary;
        });
        head = nodes[0];
        for (size_t i = 0; i < nodes.size() - 1; ++i) {
            nodes[i]->next = nodes[i + 1];
        }
        nodes.back()->next = nullptr;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int q;
    if (!(cin >> q)) return 0;
    StaffList sl;
    for (int i = 0; i < q; ++i) {
        string cmd;
        cin >> cmd;
        if (cmd == "INSERT_FIRST") {
            string name, dob;
            int gender;
            double salary;
            cin >> name >> dob >> gender >> salary;
            sl.addFirst(name, dob, gender, salary);
        } else if (cmd == "INSERT_LAST") {
            string name, dob;
            int gender;
            double salary;
            cin >> name >> dob >> gender >> salary;
            sl.addLast(name, dob, gender, salary);
        } else if (cmd == "INSERT_POS") {
            int k;
            string name, dob;
            int gender;
            double salary;
            cin >> k >> name >> dob >> gender >> salary;
            sl.addAt(k, name, dob, gender, salary);
        } else if (cmd == "DELETE_FIRST") {
            sl.removeFirst();
        } else if (cmd == "DELETE_LAST") {
            sl.removeLast();
        } else if (cmd == "DELETE_POS") {
            int k;
            cin >> k;
            sl.removeAt(k);
        } else if (cmd == "SEARCH") {
            string name;
            cin >> name;
            sl.searchName(name);
        } else if (cmd == "PRINT") {
            sl.display();
        } else if (cmd == "SORT_SALARY") {
            sl.sortBySalary();
        }
    }
    return 0;
}

