        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
            if (isPrime(a[i][j])) {
                cnt++;
            }
        }
        if (cnt > max_primes) {
            max_primes = cnt;
            best_row = i;
        }
    }

    cout << (best_row + 1) << "\n";
    bool first = true;
