#include <iostream>
#include <vector>

using namespace std;

const int MAX_VAL = 1000000;
vector<bool> prime;

void sieve(int limit) {
    prime.assign(limit + 1, true);
    if (limit >= 0) prime[0] = false;
    if (limit >= 1) prime[1] = false;
    for (int p = 2; p * p <= limit; p++) {
        if (prime[p]) {
            for (int i = p * p; i <= limit; i += p)
                prime[i] = false;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    sieve(MAX_VAL);

    int n;
    if (!(cin >> n)) return 0;

    int best_idx = 1;
    int max_cnt = -1;
    vector<int> best_primes;

    for (int i = 1; i <= n; ++i) {
        vector<int> current_primes;
        for (int j = 1; j <= n; ++j) {
            int val;
            cin >> val;
            if (val <= MAX_VAL && prime[val]) {
                current_primes.push_back(val);
            }
        }
        if ((int)current_primes.size() > max_cnt) {
            max_cnt = current_primes.size();
            best_idx = i;
            best_primes = current_primes;
        }
    }

    cout << best_idx << "\n";
    for (size_t i = 0; i < best_primes.size(); ++i) {
        if (i > 0) cout << " ";
        cout << best_primes[i];
    }
    cout << "\n";

    return 0;
}

