bool is_prime(long long n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (long long i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long a, b;
    if (!(cin >> a >> b)) return 0;

    const int digits[] = {2, 3, 5, 7};
    vector<long long> pure_primes;

    vector<long long> cur = {2, 3, 5, 7};
    while (!cur.empty()) {
        vector<long long> next_cur;
        for (long long val : cur) {
            if (val > b) continue;
            // Check digit sum
            long long temp = val;
            int sum_d = 0;
            while (temp > 0) {
                sum_d += temp % 10;
                temp /= 10;
            }
            if (is_prime(sum_d) && is_prime(val)) {
                if (val >= a) {
                    pure_primes.push_back(val);
                }
            }
            for (int d : digits) {
                long long nxt = val * 10 + d;
                if (nxt <= b) {
                    next_cur.push_back(nxt);
                }
            }
        }
        cur = move(next_cur);
    }

    cout << pure_primes.size() << "\n";
    return 0;
}

