using namespace std;

bool isPrime(long long n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (long long i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int n;
int ans = 0;

void genInc(int len, int last_digit, long long val) {
    if (len == n) {
        if (isPrime(val)) ans++;
        return;
    }
    for (int d = last_digit + 1; d <= 9; ++d) {
        genInc(len + 1, d, val * 10 + d);
    }
}

void genDec(int len, int last_digit, long long val) {
    if (len == n) {
        if (isPrime(val)) ans++;
        return;
    }
    for (int d = last_digit - 1; d >= 0; --d) {
        genDec(len + 1, d, val * 10 + d);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    if (!(cin >> n)) return 0;
    if (n == 1) {
        // Single digit primes: 2, 3, 5, 7
        cout << 4 << "\n";
        return 0;
    }
    ans = 0;
    // Increasing numbers: start with digit 1..9
    for (int d = 1; d <= 9; ++d) {
        genInc(1, d, d);
    }
    // Decreasing numbers: start with digit 1..9
    for (int d = 1; d <= 9; ++d) {
        genDec(1, d, d);
    }
    cout << ans << "\n";
    return 0;
}

