int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    if (n == 1) {
        cout << 4 << "\n";
        return 0;
    }

    int count = 0;

    // DFS for strictly increasing numbers
    auto dfsInc = [&](auto& self, int len, int last, long long val) -> void {
        if (len == n) {
            if (checkPrime(val)) count++;
            return;
        }
        for (int next_d = last + 1; next_d <= 9; ++next_d) {
            self(self, len + 1, next_d, val * 10 + next_d);
        }
    };

    // DFS for strictly decreasing numbers
    auto dfsDec = [&](auto& self, int len, int last, long long val) -> void {
        if (len == n) {
            if (checkPrime(val)) count++;
            return;
        }
        for (int next_d = 0; next_d < last; ++next_d) {
            self(self, len + 1, next_d, val * 10 + next_d);
        }
    };

    for (int first = 1; first <= 9; ++first) {
        dfsInc(dfsInc, 1, first, first);
        dfsDec(dfsDec, 1, first, first);
    }

    cout << count << "\n";
    return 0;
}

