bool isFibonacci(int n) {
    if (n < 1) return false;
    int a = 1, b = 1;
    while (b < n) {
        int c = a + b;
        a = b;
        b = c;
    }
    return (b == n || a == n);
}

int sumDigits(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

