    for (int p = 2; p * p <= maxVal; ++p) {
        if (isPrime[p]) {
            for (int i = p * p; i <= maxVal; i += p) {
                isPrime[i] = false;
            }
        }
    }

    bool first = true;
    for (int i = max(2, a); i <= b; ++i) {
