    if (n <= 0) return 0;
    int half = (n + 1) / 2;
    // We need to choose the first 'half' digits.
    // First digit is 1..9, others 0..9.
    // Each digit from 1 to n/2 contributes twice to the sum (if n is even or odd).
    // If n is odd, the middle digit (digit at 'half') contributes once.
    // Since sum mod 10 depends on the digits, let's use DP or recursion.
    // With n <= 12, half <= 6. We can use dynamic programming:
    // dp[i][rem]: number of prefixes of length i with (sum of mirrored digits) % 10 == rem.
    vector<long long> dp(10, 0);

    for (int d = 1; d <= 9; ++d) {
        int weight = (n % 2 == 1 && half == 1) ? 1 : 2;
        dp[(d * weight) % 10]++;
    }

    for (int i = 2; i <= half; ++i) {
        vector<long long> next_dp(10, 0);
        int weight = (n % 2 == 1 && i == half) ? 1 : 2;
        for (int rem = 0; rem < 10; ++rem) {
            if (dp[rem] == 0) continue;
            for (int d = 0; d <= 9; ++d) {
                int nrem = (rem + d * weight) % 10;
                next_dp[nrem] += dp[rem];
            }
        }
        dp = move(next_dp);
    }

    return dp[0];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (cin >> n) {
        cout << count_beautiful(n) << "\n";
    }
    return 0;
}

