using namespace std;

long long ans = 0;
int n, half;

void backtrack(int pos, int current_sum_mod) {
    if (pos > half) {
        if (current_sum_mod == 0) ans++;
        return;
    }
    int start_d = (pos == 1) ? 1 : 0;
    int weight = (n % 2 == 1 && pos == half) ? 1 : 2;
    for (int d = start_d; d <= 9; ++d) {
        backtrack(pos + 1, (current_sum_mod + d * weight) % 10);
    }
}

