    reverse(r.begin(), r.end());
    return s == r;
}

bool hasAtLeast3PrimeFactors(int n) {
    int count = 0;
    int d = 2;
    while (d * d <= n) {
        if (n % d == 0) {
            count++;
            while (n % d == 0) {
                n /= d;
            }
        }
        d++;
    }
    if (n > 1) {
        count++;
    }
    return count >= 3;
}

