bool isArmstrong(long long num) {
    if (num <= 0) return false;
    long long temp = num;
    int k = 0;
    while (temp > 0) {
        k++;
        temp /= 10;
    }
    temp = num;
    long long sum = 0;
    while (temp > 0) {
        int digit = temp % 10;
        long long p = 1;
        for (int i = 0; i < k; ++i) {
            p *= digit;
        }
        sum += p;
        temp /= 10;
    }
    return sum == num;
}

