                if (num % d == 0) {
                    div_sum += d;
                    long long other = num / d;
                    if (other != d) {
                        div_sum += other;
                    }
                }
            }
            if (div_sum == num) {
                results.push_back(num);
            }
        }
        for (size_t i = 0; i < results.size(); ++i) {
            cout << results[i] << (i + 1 == results.size() ? "" : " ");
        }
    }
    return 0;
