#include <iostream>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, t;
    if (!(cin >> n >> t)) return 0;

    if (t == 10) {
        if (n == 1) {
            cout << -1 << "\n";
        } else {
            cout << 1;
            for (int i = 0; i < n - 1; ++i) {
                cout << 0;
            }
            cout << "\n";
        }
    } else {
        // For 2 <= t <= 9:
        // We want the smallest n-digit number divisible by t.
        // Start with 10^(n-1).
        // Remainder of 10^(n-1) modulo t:
        // Let's compute rem = (10^(n-1)) % t
        int rem = 1 % t;
        for (int i = 1; i < n; ++i) {
            rem = (rem * 10) % t;
        }
        int add = (t - rem) % t;
        // The number is 10^(n-1) + add.
        // Since add < t <= 9, it only affects the last digit (for n > 1) or the single digit (for n = 1).
        if (n == 1) {
            cout << 1 + add << "\n";
        } else {
            cout << 1;
            for (int i = 0; i < n - 2; ++i) {
                cout << 0;
            }
            cout << add << "\n";
        }
    }
    return 0;
}
