// Số cách chia n quả táo giống nhau vào m hộp phân biệt sao cho mỗi hộp >= 1 quả
// chính là số nghiệm nguyên dương của x_1 + x_2 + ... + x_m = n
// Công thức: C(n - 1, m - 1)

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    if (r == 0 || r == n) return 1;
    if (r > n - r) r = n - r;
    long long res = 1;
    for (int i = 1; i <= r; ++i) {
        res = res * (n - i + 1) / i;
    }
    return res;
}

