using namespace std;

const int MAX_VAL = 1000000;
vector<bool> prime;

void sieve() {
    prime.assign(MAX_VAL + 1, true);
    prime[0] = prime[1] = false;
    for (int p = 2; p * p <= MAX_VAL; p++) {
        if (prime[p]) {
            for (int i = p * p; i <= MAX_VAL; i += p)
                prime[i] = false;
        }
    }
}

bool checkPrime(long long val) {
    if (val < 2) return false;
    if (val <= MAX_VAL) return prime[val];
    for (long long i = 2; i * i <= val; ++i) {
        if (val % i == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    sieve();

    int n;
    if (!(cin >> n)) return 0;

    long long total = 0;
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            long long x;
            cin >> x;
            if (c <= r && checkPrime(x)) {
                total += x;
            }
        }
    }

    cout << total << "\n";
    return 0;
}

