        }
    }

    int count = 0;
    for (int i = 0; i < n; ++i) {
        // Đường chéo chính: (i, i)
        if (isPrime(a[i][i])) {
            count++;
        }
        // Đường chéo phụ: (i, n - 1 - i)
        // Chỉ xét nếu không trùng với đường chéo chính
        int j = n - 1 - i;
        if (j != i && isPrime(a[i][j])) {
            count++;
        }
    }

    cout << count << "\n";
    return 0;
}

