#include <iostream>

long long factorial(int d) {
    long long f = 1;
    for (int i = 2; i <= d; ++i) {
        f *= i;
    }
    return f;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    long long n;
    if (std::cin >> n) {
        long long temp = n;
        long long sum = 0;
        while (temp > 0) {
            int digit = temp % 10;
            sum += factorial(digit);
            temp /= 10;
        }
        if (sum == n) {
            std::cout << 1 << "\n";
        } else {
            std::cout << 0 << "\n";
        }
    }
    return 0;
}

