        cin >> a[i];
    }

    int max_len = 1;
    int cur_len = 1;
    for (int i = 1; i < n; ++i) {
        if (a[i] > a[i - 1]) {
            cur_len++;
        } else {
            cur_len = 1;
        }
        if (cur_len > max_len) {
            max_len = cur_len;
        }
