bool hasRightTriangle(int n, vector<long long>& arr) {
    for (int i = 0; i < n; ++i) {
        arr[i] = arr[i] * arr[i];
    }
    sort(arr.begin(), arr.end());

    for (int i = n - 1; i >= 2; --i) {
        int l = 0, r = i - 1;
        while (l < r) {
            if (arr[l] + arr[r] == arr[i]) {
                return true;
            }
            if (arr[l] + arr[r] < arr[i]) {
                l++;
            } else {
                r--;
            }
        }
    }
    return false;
}

