long long integer_sqrt_ceil(long long n) {
    long long l = 1, r = 1000000, ans = 1000000;
    while (l <= r) {
        long long mid = l + (r - l) / 2;
        if (mid * mid >= n) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}

long long integer_sqrt_floor(long long n) {
    long long l = 1, r = 1000000, ans = 0;
    while (l <= r) {
        long long mid = l + (r - l) / 2;
        if (mid * mid <= n) {
            ans = mid;
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return ans;
}

