long long sum_divisors(long long n) {
    long long total = 1;
    long long temp = n;
    for (long long p = 2; p * p <= temp; ++p) {
        if (temp % p == 0) {
            long long p_pow = 1;
            long long sum_p = 1;
            while (temp % p == 0) {
                p_pow *= p;
                sum_p += p_pow;
                temp /= p;
            }
            total *= sum_p;
        }
    }
    if (temp > 1) {
        total *= (1 + temp);
    }
    return total;
}

