#include <iostream>
#include <vector>
#include <string>

using namespace std;

bool isPrime(long long n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (long long i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

bool isIncreasingOrDecreasing(long long num, int n) {
    if (n == 1) return true;
    string s = to_string(num);
    bool inc = true, dec = true;
    for (size_t i = 1; i < s.length(); ++i) {
        if (s[i] <= s[i - 1]) inc = false;
        if (s[i] >= s[i - 1]) dec = false;
    }
    return inc || dec;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;

    int count = 0;
    auto genInc = [&](auto& self, int len, int last_digit, long long val) -> void {
        if (len == n) {
            if (isPrime(val)) count++;
            return;
        }
        for (int d = last_digit + 1; d <= 9; ++d) {
            self(self, len + 1, d, val * 10 + d);
        }
    };

    auto genDec = [&](auto& self, int len, int last_digit, long long val) -> void {
        if (len == n) {
            if (isPrime(val)) count++;
            return;
        }
        for (int d = last_digit - 1; d >= 0; --d) {
            self(self, len + 1, d, val * 10 + d);
        }
    };

    if (n == 1) {
        for (int d = 2; d <= 9; ++d) {
            if (isPrime(d)) count++;
        }
    } else {
        // Generate increasing numbers
        for (int d = 1; d <= 9; ++d) {
            genInc(genInc, 1, d, d);
        }
        // Generate decreasing numbers
        for (int d = 1; d <= 9; ++d) {
            genDec(genDec, 1, d, d);
        }
    }

    cout << count << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <set>

using namespace std;

bool checkPrime(long long n) {
    if (n < 2) return false;
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;

    set<long long> valid_primes;

    // DFS to generate increasing numbers
    auto dfs_inc = [&](auto& self, long long current, int last, int len) -> void {
        if (len == n) {
            if (checkPrime(current)) {
                valid_primes.insert(current);
            }
            return;
        }
        for (int d = last + 1; d <= 9; ++d) {
            self(self, current * 10 + d, d, len + 1);
        }
    };

    // DFS to generate decreasing numbers
    auto dfs_dec = [&](auto& self, long long current, int last, int len) -> void {
        if (len == n) {
            if (checkPrime(current)) {
                valid_primes.insert(current);
            }
            return;
        }
        for (int d = last - 1; d >= 0; --d) {
            self(self, current * 10 + d, d, len + 1);
        }
    };

    for (int start = 1; start <= 9; ++start) {
        dfs_inc(dfs_inc, start, start, 1);
        if (n > 1) {
            dfs_dec(dfs_dec, start, start, 1);
        }
    }

    cout << valid_primes.size() << "\n";
    return 0;
}

