bool isPalindrome(int n) {
    int original = n;
    int reversed = 0;
    while (n > 0) {
        reversed = reversed * 10 + n % 10;
        n /= 10;
    }
    return original == reversed;
}

bool hasAtLeast3PrimeFactors(int n) {
    int count = 0;
    if (n % 2 == 0) {
        count++;
        while (n % 2 == 0) n /= 2;
    }
    for (int i = 3; i * 1LL * i <= n; i += 2) {
        if (n % i == 0) {
            count++;
            while (n % i == 0) n /= i;
        }
    }
    if (n > 1) count++;
    return count >= 3;
}

