static inline bool checkPalin(int x) {
    string s = to_string(x);
    int l = 0, r = (int)s.size() - 1;
    while (l < r) {
        if (s[l] != s[r]) return false;
        l++;
        r--;
    }
    return true;
}

static inline bool checkDistinctPrimeFactors(int x) {
    int distinctCount = 0;
    for (int d = 2; d * 1LL * d <= x; ++d) {
        if (x % d == 0) {
            distinctCount++;
            if (distinctCount >= 3) return true;
            while (x % d == 0) x /= d;
        }
    }
    if (x > 1) distinctCount++;
    return distinctCount >= 3;
}

