#include <iostream>
#include <numeric>

using namespace std;

long long gcd_ll(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

long long lcm_ll(long long a, long long b) {
    if (a == 0 || b == 0) return 0;
    return (a / gcd_ll(a, b)) * b;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long x, y, z, n;
    if (!(cin >> x >> y >> z >> n)) return 0;

    long long L = lcm_ll(x, lcm_ll(y, z));

    long long lower = 1;
    for (int i = 1; i < n; ++i) {
        lower *= 10;
    }
    long long upper = lower * 10 - 1;
    if (n == 19) upper = -1; // safeguard, though n <= 16

    // Find the smallest multiple of L >= lower
    long long rem = lower % L;
    long long ans;
    if (rem == 0) {
        ans = lower;
    } else {
        ans = lower + (L - rem);
    }

    if (ans <= upper) {
        cout << ans << "\n";
    } else {
        cout << -1 << "\n";
    }

    return 0;
}

#include <iostream>

using namespace std;

long long get_gcd(long long a, long long b) {
    return b == 0 ? a : get_gcd(b, a % b);
}

long long get_lcm(long long a, long long b) {
    return (a / get_gcd(a, b)) * b;
}

int main() {
    long long x, y, z;
    int n;
    if (cin >> x >> y >> z >> n) {
        long long L = get_lcm(x, get_lcm(y, z));

        long long min_val = 1;
        for (int i = 0; i < n - 1; ++i) {
            min_val *= 10;
        }

        // Smallest multiple of L >= min_val is ceil(min_val / L) * L
        long long k = (min_val + L - 1) / L;
        // Check overflow or exceeding n digits
        // min_val has n digits. Next power of 10 is max_val + 1
        long long max_val = min_val * 10 - 1;

        // To avoid overflow in k * L
        if (k > max_val / L) {
            cout << -1 << endl;
        } else {
            long long ans = k * L;
            if (ans <= max_val) {
                cout << ans << endl;
            } else {
                cout << -1 << endl;
            }
        }
    }
    return 0;
}

