const int MAXN = 1000000;
int phi[MAXN + 1];

void sieve() {
    for (int i = 0; i <= MAXN; ++i) {
        phi[i] = i;
    }
    for (int i = 2; i <= MAXN; ++i) {
        if (phi[i] == i) {
            for (int j = i; j <= MAXN; j += i) {
                phi[j] -= phi[j] / i;
            }
        }
    }
}

