            cout << phi[i] << (i == n ? "" : " ");
        }
        cout << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MAXN = 1000000;
int phi[MAXN + 1];
vector<int> primes;
bool is_prime[MAXN + 1];

void linear_sieve() {
    for (int i = 2; i <= MAXN; ++i) is_prime[i] = true;
    phi[1] = 1;
    for (int i = 2; i <= MAXN; ++i) {
        if (is_prime[i]) {
            primes.push_back(i);
            phi[i] = i - 1;
        }
        for (int p : primes) {
            if (i * 1LL * p > MAXN) break;
            is_prime[i * p] = false;
            if (i % p == 0) {
                phi[i * p] = phi[i] * p;
                break;
            } else {
                phi[i * p] = phi[i] * (p - 1);
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    linear_sieve();
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n;
        cin >> n;
        for (int i = 1; i <= n; ++i) {
            cout << phi[i] << (i == n ? '\n' : ' ');
        }
    }
    return 0;
}

