#include <iostream>
#include <vector>

using namespace std;

// Sàng số nguyên tố để lấy các số nguyên tố <= 100
vector<int> get_primes(int n) {
    vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int p = 2; p * p <= n; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i <= n; i += p)
                is_prime[i] = false;
        }
    }
    vector<int> primes;
    for (int p = 2; p <= n; p++) {
        if (is_prime[p]) primes.push_back(p);
    }
    return primes;
}

// Đếm số mũ của số nguyên tố p trong n! theo công thức Legendre
long long legendre(int n, int p) {
    long long count = 0;
    while (n > 0) {
        count += n / p;
        n /= p;
    }
    return count;
}

void solve() {
    int n;
    if (!(cin >> n)) return;
    if (n <= 1) {
        cout << 1 << "\n";
        return;
    }
    vector<int> primes = get_primes(n);
    unsigned long long ans = 1;
    for (int p : primes) {
        long long exp = legendre(n, p);
        ans *= (exp + 1);
    }
    cout << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

