string capitalizeFirst(string s) {
    for (char &c : s) c = tolower(c);
    if (!s.empty()) s[0] = toupper(s[0]);
    return s;
}

string toUpperAll(string s) {
    for (char &c : s) c = toupper(c);
    return s;
}

