const int MAX_VAL = 100000;
vector<bool> sieve(MAX_VAL + 1, true);

void initSieve() {
    sieve[0] = sieve[1] = false;
    for (int p = 2; p * p <= MAX_VAL; p++) {
        if (sieve[p]) {
            for (int i = p * p; i <= MAX_VAL; i += p)
                sieve[i] = false;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
