            vector<int> primes;
            for (int i = 0; i < n; ++i) {
                int val;
                cin >> val;
                if (val <= MAX_VAL && sieve[val]) {
                    primes.push_back(val);
                }
            }
            sort(primes.begin(), primes.end());
            cout << "Test " << test << ":\n";
            int m = primes.size();
            for (int i = 0; i < m; ) {
                int j = i;
                while (j < m && primes[j] == primes[i]) {
                    j++;
                }
                cout << primes[i] << " xuat hien " << (j - i) << " lan\n";
                i = j;
            }
        }
    }
