// Cài đặt thuật toán Selection Sort (Sắp xếp chọn)
void selectionSort(vector<long long>& a, int n) {
    for (int i = 0; i < n - 1; ++i) {
        int min_idx = i;
        for (int j = i + 1; j < n; ++j) {
            if (a[j] < a[min_idx]) {
                min_idx = j;
            }
        }
        if (min_idx != i) {
            swap(a[i], a[min_idx]);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
