// Cài đặt thuật toán Interchange Sort (Đổi chỗ trực tiếp)
void interchangeSort(vector<long long>& a, int n) {
    for (int i = 0; i < n - 1; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (a[i] > a[j]) {
                swap(a[i], a[j]);
            }
        }
    }
}

