#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int a[105];
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }
    for (int step = 1; step <= n - 1; ++step) {
        int i = step - 1;
        for (int j = i + 1; j < n; ++j) {
            if (a[j] < a[i]) {
                swap(&a[i], &a[j]);
            }
        }
        printf("Buoc %d:", step);
        for (int k = 0; k < n; ++k) {
            printf(" %d", a[k]);
        }
        printf("\n");
    }
    return 0;
}

