};

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);
    int n;
    if (!(cin >> n)) return 0;

    cin.ignore();
    vector<Student> a(n);
    for (int i = 0; i < n; ++i) {
        a[i].original_index = i;
        getline(cin, a[i].name);
        cin >> a[i].math >> a[i].literature;
        cin.ignore();
        a[i].gpa = (a[i].math + a[i].literature) / 2.0;
    }

    // 1. Math < 5.0
    vector<string> failed_math;
    for (const auto& s : a) {
        if (s.math < 5.0) {
            failed_math.push_back(s.name);
        }
    }
    if (failed_math.empty()) {
        cout << "KHONG CO\n";
    } else {
        for (const auto& name : failed_math) {
            cout << name << "\n";
        }
    }

    cout << "---\n";

    // 2. Count math > 8 and literature > 8
    int cnt = 0;
    for (const auto& s : a) {
        if (s.math > 8.0 && s.literature > 8.0) {
            cnt++;
        }
    }
    cout << cnt << "\n";

    cout << "---\n";

    // 3. Sort by gpa descending, tie-break by original_index
    sort(a.begin(), a.end(), [](const Student& x, const Student& y) {
        if (abs(x.gpa - y.gpa) > 1e-9) {
            return x.gpa > y.gpa;
        }
        return x.original_index < y.original_index;
    });

    cout << fixed << setprecision(2);
    for (const auto& s : a) {
        cout << s.name << " | " << s.gpa << "\n";
    }

    return 0;
}

