    string tenTacGia;
    int namXuatBan;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<Sach> ds(n);
    map<int, int> countYear;

    for (int i = 0; i < n; ++i) {
        getline(cin, ds[i].tenSach);
        getline(cin, ds[i].tenTacGia);
        cin >> ds[i].namXuatBan;
        getline(cin, dummy);
        countYear[ds[i].namXuatBan]++;
    }

    // 1. Tìm sách cũ nhất (xuất hiện đầu tiên)
    int idxOldest = 0;
    for (int i = 1; i < n; ++i) {
        if (ds[i].namXuatBan < ds[idxOldest].namXuatBan) {
            idxOldest = i;
        }
    }

    // 2. Tìm năm có nhiều sách nhất, nếu bằng nhau chọn năm nhỏ nhất
    int maxCount = -1;
    int bestYear = -1;
    for (auto const& [year, count] : countYear) {
        if (count > maxCount) {
            maxCount = count;
            bestYear = year;
        } else if (count == maxCount) {
            if (bestYear == -1 || year < bestYear) {
                bestYear = year;
            }
        }
    }

    cout << "CU NHAT: " << ds[idxOldest].tenSach << " - " << ds[idxOldest].tenTacGia << " - " << ds[idxOldest].namXuatBan << "\n";
    cout << "NAM PHO BIEN: " << bestYear << "\n";
    for (int i = 0; i < n; ++i) {
        if (ds[i].namXuatBan == bestYear) {
            cout << ds[i].tenSach << " - " << ds[i].tenTacGia << "\n";
        }
    }

    return 0;
}

