    string author;
    int year;
};

int main() {
    int n;
    if (scanf("%d\n", &n) != 1) return 0;

    vector<Book> a(n);
    unordered_map<int, int> freq;
    int minYear = 1e9;
    int oldestIndex = -1;

    for (int i = 0; i < n; ++i) {
        getline(cin, a[i].title);
        getline(cin, a[i].author);
        string yStr;
        getline(cin, yStr);
        a[i].year = stoi(yStr);
        freq[a[i].year]++;

        if (a[i].year < minYear) {
            minYear = a[i].year;
            oldestIndex = i;
        }
    }

    int bestYear = -1;
    int maxFreq = 0;
    for (auto p : freq) {
        int y = p.first;
        int f = p.second;
        if (f > maxFreq || (f == maxFreq && y < bestYear)) {
            maxFreq = f;
            bestYear = y;
        }
    }

    cout << "CU NHAT: " << a[oldestIndex].title << " - " << a[oldestIndex].author << " - " << a[oldestIndex].year << "\n";
    cout << "NAM PHO BIEN: " << bestYear << "\n";
    for (const auto& b : a) {
        if (b.year == bestYear) {
            cout << b.title << " - " << b.author << "\n";
        }
    }
    return 0;
}

