using namespace std;

struct HOPSUA {
    string brand;
    double weight;
    int day, month, year;
    int original_order;
};

long long dateToKey(int d, int m, int y) {
    return (long long)y * 10000 + m * 100 + d;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    vector<HOPSUA> a(n);
    int cnt2003 = 0;
    int latest_idx = 0;
    long long max_date = -1;

    for (int i = 0; i < n; ++i) {
        char buf[50];
        scanf("%s %lf %d %d %d", buf, &a[i].weight, &a[i].day, &a[i].month, &a[i].year);
        a[i].brand = buf;
        a[i].original_order = i;

        if (a[i].year < 2003) {
            cnt2003++;
        }

        long long cur_date = dateToKey(a[i].day, a[i].month, a[i].year);
        if (cur_date > max_date) {
            max_date = cur_date;
            latest_idx = i;
        }
    }

    printf("%d\n", cnt2003);
    printf("%s %.2f %02d/%02d/%04d\n", a[latest_idx].brand.c_str(), a[latest_idx].weight, a[latest_idx].day, a[latest_idx].month, a[latest_idx].year);

    sort(a.begin(), a.end(), [](const HOPSUA& x, const HOPSUA& y) {
        long long k1 = dateToKey(x.day, x.month, x.year);
        long long k2 = dateToKey(y.day, y.month, y.year);
        if (k1 != k2) return k1 < k2;
        return x.original_order < y.original_order;
    });

    for (int i = 0; i < n; ++i) {
        printf("%s %.2f %02d/%02d/%04d\n", a[i].brand.c_str(), a[i].weight, a[i].day, a[i].month, a[i].year);
    }

    return 0;
}

