using namespace std;

struct Date {
    int d, m, y;
    bool operator<(const Date& other) const {
        if (y != other.y) return y < other.y;
        if (m != other.m) return m < other.m;
        return d < other.d;
    }
    bool operator==(const Date& other) const {
        return d == other.d && m == other.m && y == other.y;
    }
};

struct Time {
    int h, m;
};

struct Flight {
    string code;
    Date date;
    Time time;
    string from;
    string to;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<Flight> flights(n);
    map<Date, int> countDate;
    for (int i = 0; i < n; ++i) {
        cin >> flights[i].code >> flights[i].date.d >> flights[i].date.m >> flights[i].date.y
            >> flights[i].time.h >> flights[i].time.m >> flights[i].from >> flights[i].to;
        countDate[flights[i].date]++;
    }

    Date bestDate = flights[0].date;
    int maxCount = 0;
    for (auto const& [date, count] : countDate) {
        if (count > maxCount) {
            maxCount = count;
            bestDate = date;
        } else if (count == maxCount) {
            if (date < bestDate) {
                bestDate = date;
            }
        }
    }

    cout << setfill('0') << setw(2) << bestDate.d << "/"
         << setw(2) << bestDate.m << "/"
         << setw(4) << bestDate.y << " " << maxCount << "\n";

    int q;
    if (cin >> q) {
        while (q--) {
            string queryCode;
            cin >> queryCode;
            bool found = false;
            for (int i = 0; i < n; ++i) {
                if (flights[i].code == queryCode) {
                    cout << flights[i].code << " "
                         << setfill('0') << setw(2) << flights[i].date.d << "/"
                         << setw(2) << flights[i].date.m << "/"
                         << setw(4) << flights[i].date.y << " "
                         << setw(2) << flights[i].time.h << ":"
                         << setw(2) << flights[i].time.m << " "
                         << flights[i].from << " " << flights[i].to << "\n";
                    found = true;
                    break;
                }
            }
            if (!found) {
                cout << "NOT FOUND\n";
            }
        }
    }
    return 0;
}

#include <cstdio>
#include <vector>
#include <string>
#include <algorithm>
#include <iostream>

using namespace std;

struct Flight {
    string id;
    int d, m, y;
    int hh, mm;
    string orig;
    string dest;
};

struct DateKey {
    int d, m, y;
};

bool compareDates(const DateKey& a, const DateKey& b) {
    if (a.y != b.y) return a.y < b.y;
    if (a.m != b.m) return a.m < b.m;
    return a.d < b.d;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<Flight> list(n);
    for (int i = 0; i < n; i++) {
        cin >> list[i].id >> list[i].d >> list[i].m >> list[i].y 
            >> list[i].hh >> list[i].mm >> list[i].orig >> list[i].dest;
    }

    // Find most frequent date
    vector<DateKey> distinctDates;
    for (int i = 0; i < n; i++) {
        bool exists = false;
        for (auto& dk : distinctDates) {
            if (dk.d == list[i].d && dk.m == list[i].m && dk.y == list[i].y) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            distinctDates.push_back({list[i].d, list[i].m, list[i].y});
        }
    }

    int maxCount = -1;
    DateKey bestDate = {0, 0, 0};
    for (const auto& dk : distinctDates) {
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if (list[i].d == dk.d && list[i].m == dk.m && list[i].y == dk.y) {
                cnt++;
            }
        }
        if (cnt > maxCount) {
            maxCount = cnt;
            bestDate = dk;
        } else if (cnt == maxCount) {
            if (compareDates(dk, bestDate)) {
                bestDate = dk;
            }
        }
    }

    printf("%02d/%02d/%04d %d\n", bestDate.d, bestDate.m, bestDate.y, maxCount);

    int q;
    if (cin >> q) {
        for (int k = 0; k < q; k++) {
            string target;
            cin >> target;
            int idx = -1;
            for (int i = 0; i < n; i++) {
                if (list[i].id == target) {
                    idx = i;
                    break;
                }
            }
            if (idx == -1) {
                cout << "NOT FOUND\n";
            } else {
                printf("%s %02d/%02d/%04d %02d:%02d %s %s\n",
                       list[idx].id.c_str(), list[idx].d, list[idx].m, list[idx].y,
                       list[idx].hh, list[idx].mm, list[idx].orig.c_str(), list[idx].dest.c_str());
            }
        }
    }
    return 0;
}

