struct Item {
    int id;
    string name;
    double importPrice;
    double exportPrice;
};

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);

    vector<Item> catalog;
    int next_id = 1;
    int type;

    while (cin >> type) {
        if (type == 1) {
            int n;
            cin >> n;
            string ignore_line;
            getline(cin, ignore_line);
            for (int i = 0; i < n; ++i) {
                string pname;
                getline(cin, pname);
                double imp, exp;
                cin >> imp >> exp;
                getline(cin, ignore_line);
                catalog.push_back({next_id++, pname, imp, exp});
            }
            cout << n << "\n";
        } else if (type == 2) {
            int target_id;
            cin >> target_id;
            string ignore_line;
            getline(cin, ignore_line);
            string pname;
            getline(cin, pname);
            double imp, exp;
            cin >> imp >> exp;
            getline(cin, ignore_line);
            for (auto &item : catalog) {
                if (item.id == target_id) {
                    item.name = pname;
                    item.importPrice = imp;
                    item.exportPrice = exp;
                    break;
                }
            }
            cout << target_id << "\n";
        } else if (type == 3) {
            for (const auto &item : catalog) {
                if (item.exportPrice - item.importPrice > item.importPrice + 1e-9) {
                    cout << item.id << " " << item.name << " " 
                         << fixed << setprecision(2) << item.importPrice << " " 
                         << item.exportPrice << "\n";
                }
            }
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <iomanip>

using namespace std;

struct Device {
    int id;
    string name;
    double price;
    int warranty;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<Device> devices;
    int next_id = 1;
    int op;

    while (cin >> op) {
        if (op == 1) {
            int k;
            if (!(cin >> k)) break;
            cin.ignore();
            for (int i = 0; i < k; ++i) {
                Device d;
                d.id = next_id++;
                getline(cin, d.name);
                cin >> d.price >> d.warranty;
                cin.ignore();
                devices.push_back(d);
            }
            cout << k << "\n";
        } else if (op == 2) {
            int id_to_update;
            if (!(cin >> id_to_update)) break;
            cin.ignore();
            string new_name;
            getline(cin, new_name);
            double new_price;
            int new_warranty;
            cin >> new_price >> new_warranty;
            cin.ignore();

            bool found = false;
            for (auto &d : devices) {
                if (d.id == id_to_update) {
                    d.name = new_name;
                    d.price = new_price;
                    d.warranty = new_warranty;
                    found = true;
                    break;
                }
            }
            if (found) {
                cout << id_to_update << "\n";
            }
        } else if (op == 3) {
            vector<Device> sorted_list = devices;
            sort(sorted_list.begin(), sorted_list.end(), [](const Device &a, const Device &b) {
                if (a.price != b.price) {
                    return a.price > b.price;
                }
                return a.id < b.id;
            });
            for (const auto &d : sorted_list) {
                cout << d.id << " " << d.name << " " << d.price << " " << d.warranty << "\n";
            }
        }
    }
    return 0;
}

