#include <iostream>
#include <string>
#include <vector>

using namespace std;

struct Item {
    int id;
    int type;
    string name;
    long long amount;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<Item> items;
    long long totalIncome = 0;
    long long totalExpense = 0;
    int nextId = 1;

    int cmd;
    while (cin >> cmd) {
        if (cmd == 1) {
            int k;
            if (!(cin >> k)) break;
            int addThu = 0, addChi = 0;
            for (int i = 0; i < k; ++i) {
                int t;
                long long amt;
                string name;
                cin >> t;
                cin.ignore();
                getline(cin, name);
                cin >> amt;

                items.push_back({nextId++, t, name, amt});
                if (t == 1) {
                    addThu++;
                    totalIncome += amt;
                } else {
                    addChi++;
                    totalExpense += amt;
                }
            }
            cout << addThu << " " << addChi << "\n";
        } else if (cmd == 2) {
            int id, t;
            long long amt;
            string name;
            cin >> id >> t;
            cin.ignore();
            getline(cin, name);
            cin >> amt;

            int idx = id - 1;
            if (idx >= 0 && idx < (int)items.size()) {
                if (items[idx].type == 1) totalIncome -= items[idx].amount;
                else totalExpense -= items[idx].amount;

                items[idx].type = t;
                items[idx].name = name;
                items[idx].amount = amt;

                if (items[idx].type == 1) totalIncome += items[idx].amount;
                else totalExpense += items[idx].amount;

                cout << items[idx].name << "\n";
            }
        } else if (cmd == 3) {
            cout << totalIncome << " " << totalExpense << " " << (totalIncome - totalExpense) << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <map>

using namespace std;

class ExpenseManager {
private:
    struct Record {
        int type;
        string name;
        long long amount;
    };
    map<int, Record> database;
    int autoId;
    long long sumThu;
    long long sumChi;

public:
    ExpenseManager() : autoId(1), sumThu(0), sumChi(0) {}

    void addItems(int k) {
        int cntThu = 0, cntChi = 0;
        for (int i = 0; i < k; ++i) {
            int t;
            long long amt;
            string name;
            cin >> t;
            cin.ignore();
            getline(cin, name);
            cin >> amt;

            database[autoId++] = {t, name, amt};
            if (t == 1) {
                cntThu++;
                sumThu += amt;
            } else {
                cntChi++;
                sumChi += amt;
            }
        }
        cout << cntThu << " " << cntChi << "\n";
    }

    void updateItem(int id) {
        int t;
        long long amt;
        string name;
        cin >> t;
        cin.ignore();
        getline(cin, name);
        cin >> amt;

        auto it = database.find(id);
        if (it != database.end()) {
            if (it->second.type == 1) {
                sumThu -= it->second.amount;
            } else {
                sumChi -= it->second.amount;
            }
            it->second = {t, name, amt};
            if (t == 1) {
                sumThu += amt;
            } else {
                sumChi += amt;
            }
            cout << name << "\n";
        }
    }

    void showSummary() const {
        cout << sumThu << " " << sumChi << " " << (sumThu - sumChi) << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ExpenseManager manager;
    int opt;
    while (cin >> opt) {
        if (opt == 1) {
            int k;
            if (cin >> k) manager.addItems(k);
        } else if (opt == 2) {
            int id;
            if (cin >> id) manager.updateItem(id);
        } else if (opt == 3) {
            manager.showSummary();
        }
    }
    return 0;
}

