#include <iostream>
#include <string>
#include <vector>
#include <iomanip>
#include <algorithm>

using namespace std;

struct Product {
    int id;
    string name;
    double cost;
    double price;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<Product> products;
    int auto_id = 1;
    int type;

    while (cin >> type) {
        if (type == 1) {
            int k;
            cin >> k;
            string dummy;
            getline(cin, dummy);
            for (int i = 0; i < k; ++i) {
                Product p;
                p.id = auto_id++;
                getline(cin, p.name);
                cin >> p.cost >> p.price;
                getline(cin, dummy);
                products.push_back(p);
            }
            cout << k << "\n";
        } else if (type == 2) {
            int target_id;
            cin >> target_id;
            string dummy;
            getline(cin, dummy);
            string new_name;
            getline(cin, new_name);
            double new_cost, new_price;
            cin >> new_cost >> new_price;
            getline(cin, dummy);
            for (auto &p : products) {
                if (p.id == target_id) {
                    p.name = new_name;
                    p.cost = new_cost;
                    p.price = new_price;
                    break;
                }
            }
            cout << target_id << "\n";
        } else if (type == 3) {
            vector<Product> list = products;
            stable_sort(list.begin(), list.end(), [](const Product &a, const Product &b) {
                double diff_a = a.price - a.cost;
                double diff_b = b.price - b.cost;
                if (abs(diff_a - diff_b) > 1e-9) {
                    return diff_a > diff_b;
                }
                return a.id < b.id;
            });
            cout << fixed << setprecision(2);
            for (const auto &p : list) {
                cout << p.id << " " << p.name << " " << p.cost << " " << p.price << "\n";
            }
        }
    }
    return 0;
}

