    cin.tie(nullptr);

    vector<Item> items;
    int cur_id = 1;
    int cmd;

    while (cin >> cmd) {
        if (cmd == 1) {
            int count;
            cin >> count;
            for (int i = 0; i < count; ++i) {
                string s;
                while (s.empty()) {
                    getline(cin, s);
                }
                double b, se;
                cin >> b >> se;
                items.push_back({cur_id++, s, b, se});
            }
