#include <iostream>
#include <string>

using namespace std;

void solve() {
    string a, b, c;
    if (!(cin >> a >> b >> c)) return;
    int n = a.length();
    bool possible = true;
    for (int i = 0; i < n; ++i) {
        // At index i, we either swap c[i] with a[i] (so a[i] becomes c[i])
        // or swap c[i] with b[i] (so b[i] becomes c[i]).
        // In the end, we need a[i] == b[i].
        // Case 1: swap c[i] with a[i] -> final a[i] = c[i], final b[i] = b[i]. Needs c[i] == b[i].
        // Case 2: swap c[i] with b[i] -> final a[i] = a[i], final b[i] = c[i]. Needs a[i] == c[i].
        // Therefore, we must have c[i] == a[i] or c[i] == b[i].
        if (c[i] != a[i] && c[i] != b[i]) {
            possible = false;
            break;
        }
    }
    if (possible) cout << "YES\n";
    else cout << "NO\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

