    int count0 = count(s.begin(), s.end(), '0');
    int count1 = n - count0;
    if (count0 != count1) {
        cout << 1 << "\n" << s << "\n";
    } else {
        cout << 2 << "\n";
        for (int len = 1; len < n; ++len) {
            int pref0 = count(s.begin(), s.begin() + len, '0');
            int pref1 = len - pref0;
            int suff0 = count0 - pref0;
            int suff1 = count1 - pref1;
            if (pref0 != pref1 && suff0 != suff1) {
                cout << s.substr(0, len) << " " << s.substr(len) << "\n";
                break;
            }
        }
    }
    return 0;
}

