void solve() {
    string s;
    if (!(cin >> s)) return;
    set<char> working;
    int n = s.length();
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && s[j] == s[i]) {
            j++;
        }
        int len = j - i;
        if (len % 2 == 1) {
            working.insert(s[i]);
        }
        i = j;
    }
    string res = "";
    for (char c : working) {
        res += c;
    }
    cout << res << "\n";
}

