#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;

    int total = n * n;
    vector<unsigned long long> fib(total);
    if (total > 0) fib[0] = 0;
    if (total > 1) fib[1] = 1;
    for (int i = 2; i < total; ++i) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    vector<vector<unsigned long long>> a(n, vector<unsigned long long>(n, 0));
    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    int idx = 0;

    while (top <= bottom && left <= right) {
        for (int j = left; j <= right; ++j) {
            a[top][j] = fib[idx++];
        }
        top++;
        for (int i = top; i <= bottom; ++i) {
            a[i][right] = fib[idx++];
        }
        right--;
        if (top <= bottom) {
            for (int j = right; j >= left; --j) {
                a[bottom][j] = fib[idx++];
            }
            bottom--;
        }
        if (left <= right) {
            for (int i = bottom; i >= top; --i) {
                a[i][left] = fib[idx++];
            }
            left++;
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << a[i][j] << (j + 1 == n ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;

    vector<unsigned long long> f(n * n);
    if (n * n > 0) f[0] = 0;
    if (n * n > 1) f[1] = 1;
    for (int i = 2; i < n * n; ++i) {
        f[i] = f[i - 1] + f[i - 2];
    }

    vector<vector<unsigned long long>> res(n, vector<unsigned long long>(n));
    vector<vector<bool>> visited(n, vector<bool>(n, false));

    int dr[] = {0, 1, 0, -1};
    int dc[] = {1, 0, -1, 0};
    int r = 0, c = 0, dir = 0;

    for (int i = 0; i < n * n; ++i) {
        res[r][c] = f[i];
        visited[r][c] = true;
        int nr = r + dr[dir];
        int nc = c + dc[dir];
        if (nr < 0 || nr >= n || nc < 0 || nc >= n || visited[nr][nc]) {
            dir = (dir + 1) % 4;
            nr = r + dr[dir];
            nc = c + dc[dir];
        }
        r = nr;
        c = nc;
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << res[i][j] << (j == n - 1 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

