using namespace std;

bool isPalindrome(const string &s) {
    int l = 0, r = (int)s.length() - 1;
    while (l < r) {
        if (s[l] != s[r]) return false;
        l++;
        r--;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string word;
    vector<string> order;
    unordered_map<string, int> count;
    int max_len = 0;

    while (cin >> word) {
        if (isPalindrome(word)) {
            if (count[word] == 0) {
                order.push_back(word);
            }
            count[word]++;
            if ((int)word.length() > max_len) {
                max_len = word.length();
            }
        }
    }

    for (const string &w : order) {
        if ((int)w.length() == max_len) {
            cout << w << " " << count[w] << "\n";
        }
    }

    return 0;
}

