#include <iostream>
#include <numeric>

using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

long long lcm(long long a, long long b) {
    return (a / gcd(a, b)) * b;
}

struct Fraction {
    long long num, den;
    void simplify() {
        long long g = gcd(num, den);
        num /= g;
        den /= g;
    }
};

void solve(int tc) {
    long long a, b, c, d;
    cin >> a >> b >> c >> d;
    cout << "Case #" << tc << ":\n";

    Fraction p = {a, b};
    Fraction q = {c, d};
    p.simplify();
    q.simplify();

    long long common_den = lcm(p.den, q.den);
    long long p_num = p.num * (common_den / p.den);
    long long q_num = q.num * (common_den / q.den);

    cout << p_num << "/" << common_den << " " << q_num << "/" << common_den << "\n";

    Fraction sum = {p_num + q_num, common_den};
    sum.simplify();
    cout << sum.num << "/" << sum.den << "\n";

    Fraction div = {p.num * q.den, p.den * q.num};
    div.simplify();
    cout << div.num << "/" << div.den << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        for (int i = 1; i <= t; ++i) {
            solve(i);
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (!(cin >> T)) return 0;
    for (int t = 1; t <= T; ++t) {
        long long a, b, c, d;
        cin >> a >> b >> c >> d;

        // Step 1: Simplify both fractions
        long long g1 = std::gcd(a, b);
        a /= g1;
        b /= g1;

        long long g2 = std::gcd(c, d);
        c /= g2;
        d /= g2;

        // Find common denominator (LCM)
        long long m = std::lcm(b, d);
        long long num1 = a * (m / b);
        long long num2 = c * (m / d);

        // Sum
        long long sum_num = num1 + num2;
        long long sum_den = m;
        long long g_sum = std::gcd(sum_num, sum_den);
        sum_num /= g_sum;
        sum_den /= g_sum;

        // Quotient p / q = (a/b) / (c/d) = (a*d) / (b*c)
        long long quot_num = a * d;
        long long quot_den = b * c;
        long long g_quot = std::gcd(quot_num, quot_den);
        quot_num /= g_quot;
        quot_den /= g_quot;

        cout << "Case #" << t << ":\n";
        cout << num1 << "/" << m << " " << num2 << "/" << m << "\n";
        cout << sum_num << "/" << sum_den << "\n";
        cout << quot_num << "/" << quot_den << "\n";
    }
    return 0;
}

