using namespace std;

bool checkPerfectSquare(unsigned long long x) {
    unsigned long long low = 0, high = 1000000000ULL;
    while (low <= high) {
        unsigned long long mid = low + (high - low) / 2;
        unsigned long long sq = mid * mid;
        if (sq == x) return true;
        if (sq < x) low = mid + 1;
        else high = mid - 1;
    }
    return false;
}

