    int count25 = 0, count50 = 0;
    bool possible = true;

    for (int i = 0; i < n; ++i) {
        int bill;
        cin >> bill;
        if (!possible) continue;

        if (bill == 25) {
            count25++;
        } else if (bill == 50) {
            if (count25 > 0) {
                count25--;
                count50++;
            } else {
                possible = false;
            }
        } else if (bill == 100) {
            // Cần thối lại 75: ưu tiên 1 tờ 50 và 1 tờ 25, nếu không thì 3 tờ 25
            if (count50 > 0 && count25 > 0) {
                count50--;
                count25--;
            } else if (count25 >= 3) {
                count25 -= 3;
            } else {
                possible = false;
            }
        }
    }

    if (possible) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

