    int n;
    if (scanf("%d", &n) != 1) return 0;

    int ans = 0;
    while (n--) {
        int x, y, z;
        scanf("%d %d %d", &x, &y, &z);
        int sum = x + y + z;
        ans += (sum >= 2);
    }

    printf("%d\n", ans);
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    sort(a.begin(), a.end());

    long long best_val = a[0];
    int max_count = 1;

    long long cur_val = a[0];
    int cur_count = 1;

    for (int i = 1; i < n; ++i) {
        if (a[i] == cur_val) {
            cur_count++;
        } else {
            if (cur_count > max_count) {
                max_count = cur_count;
                best_val = cur_val;
            }
            cur_val = a[i];
            cur_count = 1;
        }
    }

    if (cur_count > max_count) {
        max_count = cur_count;
        best_val = cur_val;
    }

    cout << best_val << " " << max_count << "\n";
    return 0;
}

