#include <iostream>
#include <string>
#include <vector>
#include <iomanip>
#include <algorithm>

using namespace std;

struct Candidate {
    int id;
    string name;
    string dob;
    double p1, p2, p3;
    double total;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);
    vector<Candidate> a(n);
    for (int i = 0; i < n; ++i) {
        a[i].id = i + 1;
        getline(cin, a[i].name);
        getline(cin, a[i].dob);
        cin >> a[i].p1 >> a[i].p2 >> a[i].p3;
        getline(cin, dummy);
        a[i].total = a[i].p1 + a[i].p2 + a[i].p3;
    }
    stable_sort(a.begin(), a.end(), [](const Candidate& x, const Candidate& y) {
        // To handle floating point comparisons reliably
        if (abs(x.total - y.total) > 1e-7) {
            return x.total > y.total;
        }
        return x.id < y.id;
    });
    for (const auto& c : a) {
        cout << c.id << " " << c.name << " " << c.dob << " "
             << fixed << setprecision(1) << c.total << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <iomanip>
#include <algorithm>

using namespace std;

struct ThiSinh {
    int ma;
    string ten;
    string ngaysinh;
    double tong_diem;
};

bool cmp(const ThiSinh& a, const ThiSinh& b) {
    if (abs(a.tong_diem - b.tong_diem) > 1e-7) {
        return a.tong_diem > b.tong_diem;
    }
    return a.ma < b.ma;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (cin >> n) {
        string line;
        getline(cin, line);
        vector<ThiSinh> ds(n);
        for (int i = 0; i < n; ++i) {
            ds[i].ma = i + 1;
            getline(cin, ds[i].ten);
            getline(cin, ds[i].ngaysinh);
            double d1, d2, d3;
            cin >> d1 >> d2 >> d3;
            getline(cin, line);
            ds[i].tong_diem = d1 + d2 + d3;
        }
        sort(ds.begin(), ds.end(), cmp);
        for (int i = 0; i < n; ++i) {
            cout << ds[i].ma << " " << ds[i].ten << " " << ds[i].ngaysinh << " "
                 << fixed << setprecision(1) << ds[i].tong_diem << "\n";
        }
    }
    return 0;
}

