#include <iostream>

using namespace std;

long long gcd_func(long long a, long long b) {
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    long long current_gcd = 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        current_gcd = gcd_func(current_gcd, x);
    }

    cout << current_gcd << "\n";
    return 0;
}

