#include <cstdio>
#include <cstring>

int stringLength(const char* str) {
    int len = 0;
    while (str[len] != '\0') {
        len++;
    }
    return len;
}

int main() {
    static char buffer[100005];
    if (fgets(buffer, sizeof(buffer), stdin)) {
        int len = stringLength(buffer);
        while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r')) {
            buffer[--len] = '\0';
        }
        printf("%d\n", len);
    } else {
        printf("0\n");
    }
    return 0;
}

