    cin.tie(NULL);
    string s;
    if (!(cin >> s)) return 0;

    const string vowels = "aoyeuiAOYEUI";
    string ans;
    ans.reserve(s.length() * 2);

    for (size_t i = 0; i < s.length(); ++i) {
        char ch = s[i];
        if (vowels.find(ch) == string::npos) {
            ans.push_back('.');
            if (ch >= 'A' && ch <= 'Z') {
                ans.push_back(ch + ('a' - 'A'));
            } else {
                ans.push_back(ch);
            }
        }
    }
    cout << ans << "\n";
    return 0;
}

