#include <iostream>
#include <iomanip>
#include <cmath>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    double a, b, c;
    if (!(cin >> a >> b >> c)) return 0;

    const double EPS = 1e-9;
    if (abs(a) < EPS) {
        if (abs(b) < EPS) {
            if (abs(c) < EPS) {
                cout << "INF\n";
            } else {
                cout << "NO\n";
            }
        } else {
            double x = -c / b;
            if (abs(x) < 1e-7) x = 0.0;
            cout << fixed << setprecision(2) << x << "\n";
        }
    } else {
        double delta = b * b - 4 * a * c;
        if (delta < -EPS) {
            cout << "NO\n";
        } else if (abs(delta) <= EPS) {
            double x = -b / (2 * a);
            if (abs(x) < 1e-7) x = 0.0;
            cout << fixed << setprecision(2) << x << "\n";
        } else {
            double x1 = (-b + sqrt(delta)) / (2 * a);
            double x2 = (-b - sqrt(delta)) / (2 * a);
            if (x1 < x2) swap(x1, x2);
            if (abs(x1) < 1e-7) x1 = 0.0;
            if (abs(x2) < 1e-7) x2 = 0.0;
            cout << fixed << setprecision(2) << x1 << " " << x2 << "\n";
        }
    }
    return 0;
}

#include <cstdio>
#include <cmath>
#include <algorithm>

int main() {
    double a, b, c;
    if (scanf("%lf %lf %lf", &a, &b, &c) != 3) return 0;

    double eps = 1e-9;
    if (std::abs(a) < eps) {
        if (std::abs(b) < eps) {
            if (std::abs(c) < eps) {
                printf("INF\n");
            } else {
                printf("NO\n");
            }
        } else {
            double x = -c / b;
            if (std::abs(x) < 1e-7) x = 0.0;
            printf("%.2f\n", x);
        }
    } else {
        double delta = b * b - 4.0 * a * c;
        if (delta < -eps) {
            printf("NO\n");
        } else if (std::abs(delta) <= eps) {
            double x = -b / (2.0 * a);
            if (std::abs(x) < 1e-7) x = 0.0;
            printf("%.2f\n", x);
        } else {
            double sqrt_d = std::sqrt(delta);
            double x1 = (-b + sqrt_d) / (2.0 * a);
            double x2 = (-b - sqrt_d) / (2.0 * a);
            if (x1 < x2) std::swap(x1, x2);
            if (std::abs(x1) < 1e-7) x1 = 0.0;
            if (std::abs(x2) < 1e-7) x2 = 0.0;
            printf("%.2f %.2f\n", x1, x2);
        }
    }
    return 0;
}

