using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double a, b, c;
    if (!(cin >> a >> b >> c)) return 0;

    double C = a + b + c;
    double p = C / 2.0;
    double S = sqrt(p * (p - a) * (p - b) * (p - c));

    double ha = 2.0 * S / a;
    double hb = 2.0 * S / b;
    double hc = 2.0 * S / c;

    double ma = 0.5 * sqrt(2.0 * b * b + 2.0 * c * c - a * a);
    double mb = 0.5 * sqrt(2.0 * a * a + 2.0 * c * c - b * b);
    double mc = 0.5 * sqrt(2.0 * a * a + 2.0 * b * b - c * c);

    double ga = (2.0 / (b + c)) * sqrt(b * c * p * (p - a));
    double gb = (2.0 / (a + c)) * sqrt(a * c * p * (p - b));
    double gc = (2.0 / (a + b)) * sqrt(a * b * p * (p - c));

    double r = S / p;
    double R = (a * b * c) / (4.0 * S);

    cout << fixed << setprecision(2);
    cout << C << " " << S << "\n";
    cout << ha << " " << hb << " " << hc << "\n";
    cout << ma << " " << mb << " " << mc << "\n";
    cout << ga << " " << gb << " " << gc << "\n";
    cout << r << "\n";
    cout << R << "\n";

    return 0;
}

