int main() {
    double a, b, c;
    if (scanf("%lf %lf %lf", &a, &b, &c) != 3) return 0;

    double perimeter = a + b + c;
    double p = perimeter / 2.0;
    double area = std::sqrt(p * (p - a) * (p - b) * (p - c));

    double h_a = (2.0 * area) / a;
    double h_b = (2.0 * area) / b;
    double h_c = (2.0 * area) / c;

    double m_a = std::sqrt(2.0 * (b * b + c * c) - a * a) / 2.0;
    double m_b = std::sqrt(2.0 * (a * a + c * c) - b * b) / 2.0;
    double m_c = std::sqrt(2.0 * (a * a + b * b) - c * c) / 2.0;

    double g_a = (2.0 * std::sqrt(b * c * p * (p - a))) / (b + c);
    double g_b = (2.0 * std::sqrt(a * c * p * (p - b))) / (a + c);
    double g_c = (2.0 * std::sqrt(a * b * p * (p - c))) / (a + b);

    double in_r = area / p;
    double out_R = (a * b * c) / (4.0 * area);

    std::printf("%.2f %.2f\n", perimeter, area);
    std::printf("%.2f %.2f %.2f\n", h_a, h_b, h_c);
    std::printf("%.2f %.2f %.2f\n", m_a, m_b, m_c);
    std::printf("%.2f %.2f %.2f\n", g_a, g_b, g_c);
    std::printf("%.2f\n", in_r);
    std::printf("%.2f\n", out_R);

    return 0;
}

