void solve() {
    int type;
    if (!(cin >> type)) return;
    if (type == 1) {
        double M;
        cin >> M;
        if (M <= 1.0) {
            cout << 0 << "\n";
            return;
        }
        double sum = 0.0;
        long long n = 0;
        while (true) {
            long long next_n = n + 1;
            double term = 1.0 / (2.0 * next_n - 1.0);
            if (sum + term < M - 1e-12) {
                sum += term;
                n = next_n;
            } else {
                break;
            }
        }
        cout << n << "\n";
    } else {
        double K;
        cin >> K;
        long long n = 1;
        long long ans = 0;
        while (true) {
            double val = exp((double)n) - 1999.0 * log10((double)n);
            if (val < K - 1e-9) {
                ans = n;
                n++;
            } else {
                break;
            }
        }
        cout << ans << "\n";
    }
}

