using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double x, a;
    if (!(cin >> x >> a)) return 0;

    const double eps = 1e-6;

    // 1. Pi
    double sum_pi = 0.0;
    long long k = 1;
    while (true) {
        double term = 1.0 / (static_cast<double>(k) * k);
        sum_pi += term;
        if (term < eps) break;
        k++;
    }
    double pi_val = sqrt(6.0 * sum_pi);

    // 2. e^x
    double exp_val = 1.0;
    double term_exp = 1.0;
    int n_exp = 1;
    while (true) {
        term_exp *= x / n_exp;
        exp_val += term_exp;
        if (fabs(term_exp) < eps) break;
        n_exp++;
    }

    // 3. sin(x)
    double sin_val = x;
    double term_sin = x;
    int n_sin = 1;
    while (true) {
        term_sin *= - (x * x) / ((2 * n_sin) * (2 * n_sin + 1.0));
        sin_val += term_sin;
        if (fabs(term_sin) < eps) break;
        n_sin++;
    }

    // 4. sqrt(a)
    double s_prev = a;
    double s_curr = 0.0;
    while (true) {
        s_curr = 0.5 * (s_prev + a / s_prev);
        if (fabs(s_curr - s_prev) < eps) break;
        s_prev = s_curr;
    }
    double sqrt_val = s_curr;

    cout << fixed << setprecision(6);
    cout << pi_val << " " << exp_val << " " << sin_val << " " << sqrt_val << "\n";

    return 0;
}

#include <cstdio>
#include <cmath>

int main() {
    double x, a;
    if (scanf("%lf %lf", &x, &a) != 2) return 0;

    const double EPS = 1e-6;

    // a. Pi computation
    double s_euler = 0.0;
    for (long long i = 1; ; ++i) {
        double t = 1.0 / (double(i) * double(i));
        s_euler += t;
        if (t < EPS) break;
    }
    double res_pi = std::sqrt(6.0 * s_euler);

    // b. e^x computation
    double res_exp = 1.0;
    double cur_exp = 1.0;
    for (int step = 1; ; ++step) {
        cur_exp = cur_exp * x / step;
        res_exp += cur_exp;
        if (std::abs(cur_exp) < EPS) break;
    }

    // c. sin(x) computation
    double res_sin = x;
    double cur_sin = x;
    for (int step = 1; ; ++step) {
        cur_sin = -cur_sin * x * x / ((2.0 * step) * (2.0 * step + 1.0));
        res_sin += cur_sin;
        if (std::abs(cur_sin) < EPS) break;
    }

    // d. sqrt(a) via Heron / Newton-Raphson
    double prev_s = a;
    double curr_s = a;
    do {
        curr_s = (prev_s * prev_s + a) / (2.0 * prev_s);
        if (std::abs(curr_s - prev_s) < EPS) {
            break;
        }
        prev_s = curr_s;
    } while (true);

    printf("%.6f %.6f %.6f %.6f\n", res_pi, res_exp, res_sin, curr_s);
    return 0;
}

