using namespace std;

double eval_poly(const vector<double>& c, double x) {
    double res = 0;
    for (double coeff : c) {
        res = res * x + coeff;
    }
    return res;
}

double f(int t, const vector<double>& c, double x) {
    if (t == 1) {
        return exp(x) - 1.5;
    } else if (t == 2) {
        return x * pow(2.0, x) - 1.0;
    } else {
        return eval_poly(c, x);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (!(cin >> t)) return 0;

    double a = 0, b = 1;
    vector<double> c;

    if (t == 3) {
        int n;
        cin >> n;
        c.resize(n + 1);
        for (int i = 0; i <= n; ++i) cin >> c[i];
        cin >> a >> b;
    }

    double fa = f(t, c, a);
    double fb = f(t, c, b);
    if (fa == 0.0) {
        cout << fixed << setprecision(6) << a << "\n";
        return 0;
    }
    if (fb == 0.0) {
        cout << fixed << setprecision(6) << b << "\n";
        return 0;
    }

    double left = a, right = b;
    double ans = (left + right) / 2.0;

    while (right - left >= 1e-6) {
        double mid = left + (right - left) / 2.0;
        double fmid = f(t, c, mid);
        if (fmid == 0.0) {
            ans = mid;
            break;
        }
        double fleft = f(t, c, left);
        if ((fleft > 0 && fmid < 0) || (fleft < 0 && fmid > 0)) {
            right = mid;
        } else {
            left = mid;
        }
        ans = (left + right) / 2.0;
    }

    cout << fixed << setprecision(6) << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int type;
    if (!(cin >> type)) return 0;

    double a = 0.0, b = 1.0;
    int n = 0;
    vector<double> coeffs;

    if (type == 3) {
        cin >> n;
        coeffs.resize(n + 1);
        for (int i = 0; i <= n; ++i) {
            cin >> coeffs[i];
        }
        cin >> a >> b;
    }

    auto func = [&](double x) -> double {
        if (type == 1) {
            return std::exp(x) - 1.5;
        } else if (type == 2) {
            return x * std::pow(2.0, x) - 1.0;
        } else {
            double val = 0.0;
            for (double ci : coeffs) {
                val = val * x + ci;
            }
            return val;
        }
    };

    double l = a, r = b;
    if (func(l) == 0.0) {
        cout << fixed << setprecision(6) << l << "\n";
        return 0;
    }
    if (func(r) == 0.0) {
        cout << fixed << setprecision(6) << r << "\n";
        return 0;
    }

    while (r - l >= 1e-6) {
        double m = (l + r) / 2.0;
        double fm = func(m);
        if (fm == 0.0) {
            l = r = m;
            break;
        }
        double fl = func(l);
        if ((fl < 0 && fm < 0) || (fl > 0 && fm > 0)) {
            l = m;
        } else {
            r = m;
        }
    }

