// Recursive function to compute sum 1 + 2 + ... + n
long long sumLinear(long long n) {
    if (n <= 1) return n;
    return n + sumLinear(n - 1);
}

// Recursive function to compute 1^2 + 2^2 + ... + n^2
long long sumSquares(long long n) {
    if (n <= 1) return n * n;
    return n * n + sumSquares(n - 1);
}

