long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a < 0 ? -a : a;
}

struct Fraction {
    long long num, den;

    void simplify() {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        long long g = gcd_ll(num, den);
        if (g != 0) {
