            den /= g;
        }
    }
};

Fraction add(Fraction a, Fraction b) {
    Fraction res;
    long long g = gcd_ll(a.den, b.den);
    long long common_den = (a.den / g) * b.den;
    res.num = a.num * (b.den / g) + b.num * (a.den / g);
    res.den = common_den;
    res.simplify();
    return res;
}

