#include <iostream>

struct Fraction {
    long long num, den;

    static long long gcd(long long x, long long y) {
        while (y != 0) {
            long long r = x % y;
            x = y;
            y = r;
        }
        return x < 0 ? -x : x;
    }

    void simplify() {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        if (num == 0) {
            den = 1;
            return;
        }
        long long g = gcd(num, den);
        num /= g;
        den /= g;
    }
};

