long long factorial(int n, int depth) {
    for (int i = 0; i < depth * 2; ++i) cout << ' ';
    cout << "Goi factorial(" << n << ")\n";

    if (n <= 1) {
        for (int i = 0; i < depth * 2; ++i) cout << ' ';
        cout << "Tra ve 1\n";
        return 1;
    }

    long long sub = factorial(n - 1, depth + 1);
    long long ans = (long long)n * sub;

    for (int i = 0; i < depth * 2; ++i) cout << ' ';
    cout << "Tra ve " << n << " * " << sub << " = " << ans << "\n";
    return ans;
}

