long long trace_factorial(int n, int depth) {
    printf("%*sGoi factorial(%d)\n", depth * 2, "", n);
    if (n <= 1) {
        printf("%*sTra ve 1\n", depth * 2, "");
        return 1LL;
    }
    long long res = trace_factorial(n - 1, depth + 1);
    long long total = (long long)n * res;
    printf("%*sTra ve %d * %lld = %lld\n", depth * 2, "", n, res, total);
    return total;
}

