#include <iostream>

long long recursiveProduct(long long a, long long b) {
    if (b == 0) return 0;
    if (b == 1) return a;
    if (b == -1) return -a;
    if (b > 1) {
        return a + recursiveProduct(a, b - 1);
    }
    // b < -1
    return -a + recursiveProduct(a, b + 1);
}

