using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    if (n <= 0) return 0;

    int src = 1, aux = 2, dst = 3;
    if (n % 2 == 0) {
        swap(aux, dst);
    }

    long long total_moves = (1LL << n) - 1;
    vector<int> peg[4];
    for (int i = n; i >= 1; --i) {
        peg[1].push_back(i);
    }

    auto make_move = [&](int a, int b) {
        if (peg[a].empty()) {
            int d = peg[b].back();
            peg[b].pop_back();
            peg[a].push_back(d);
            cout << b << " -> " << a << "\n";
        } else if (peg[b].empty()) {
            int d = peg[a].back();
            peg[a].pop_back();
            peg[b].push_back(d);
            cout << a << " -> " << b << "\n";
        } else if (peg[a].back() < peg[b].back()) {
            int d = peg[a].back();
            peg[a].pop_back();
            peg[b].push_back(d);
            cout << a << " -> " << b << "\n";
        } else {
            int d = peg[b].back();
            peg[b].pop_back();
            peg[a].push_back(d);
            cout << b << " -> " << a << "\n";
        }
    };

    for (long long m = 1; m <= total_moves; ++m) {
        if (m % 3 == 1) {
            make_move(src, dst);
        } else if (m % 3 == 2) {
            make_move(src, aux);
        } else {
            make_move(aux, dst);
        }
    }
    return 0;
}

#include <iostream>
#include <stack>

using namespace std;

struct Frame {
    int count;
    int from_peg;
    int to_peg;
    int aux_peg;
    int state;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    if (n <= 0) return 0;

    stack<Frame> st;
    st.push({n, 1, 3, 2, 0});

    while (!st.empty()) {
        Frame &f = st.top();
        if (f.count == 1) {
            cout << f.from_peg << " -> " << f.to_peg << "\n";
            st.pop();
            continue;
        }
        if (f.state == 0) {
            f.state = 1;
            st.push({f.count - 1, f.from_peg, f.aux_peg, f.to_peg, 0});
        } else if (f.state == 1) {
            cout << f.from_peg << " -> " << f.to_peg << "\n";
            f.state = 2;
            st.push({f.count - 1, f.aux_peg, f.to_peg, f.from_peg, 0});
        } else {
            st.pop();
        }
    }
    return 0;
}

