using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    long double sum = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        sum += a[i];
    }

    long double mean = sum / n;

    sort(a.begin(), a.end());

    long double median;
    if (n % 2 == 1) {
        median = a[n / 2];
    } else {
        median = (static_cast<long double>(a[n / 2 - 1]) + a[n / 2]) / 2.0;
    }

    // Mode calculation using run-length on sorted array
    int max_freq = 0;
    vector<long long> modes;
    int current_freq = 0;
    for (int i = 0; i < n; ++i) {
        current_freq++;
        if (i == n - 1 || a[i] != a[i + 1]) {
            if (current_freq > max_freq) {
                max_freq = current_freq;
                modes.clear();
                modes.push_back(a[i]);
            } else if (current_freq == max_freq) {
                modes.push_back(a[i]);
            }
            current_freq = 0;
        }
    }

    cout << fixed << setprecision(2);
    cout << "Mean: " << (double)mean << "\n";
    cout << "Median: " << (double)median << "\n";
    cout << "Mode:";
    for (long long m : modes) {
        cout << " " << m;
    }
    cout << "\n";

    return 0;
}

