#include <iostream>

using namespace std;

enum Status { CONTINUE, WON, LOST };

bool playCraps() {
    int die1, die2;
    if (!(cin >> die1 >> die2)) return false;
    int sum = die1 + die2;
    int myPoint = 0;
    Status gameStatus;

    switch (sum) {
        case 7:
        case 11:
            gameStatus = WON;
            break;
        case 2:
        case 3:
        case 12:
            gameStatus = LOST;
            break;
        default:
            gameStatus = CONTINUE;
            myPoint = sum;
            break;
    }

    while (gameStatus == CONTINUE) {
        if (!(cin >> die1 >> die2)) break;
        sum = die1 + die2;
        if (sum == myPoint) {
            gameStatus = WON;
        } else if (sum == 7) {
            gameStatus = LOST;
        }
    }

    return (gameStatus == WON);
}

