        int point = 0;
        bool won = false;
        for (int step = 1; step <= K; ++step) {
            int sum;
            scanf("%d", &sum);
            if (step == 1) {
                if (sum == 7 || sum == 11) {
                    won = true;
                } else if (sum == 2 || sum == 3 || sum == 12) {
                    won = false;
                } else {
                    point = sum;
                }
            } else {
                if (sum == point) {
                    won = true;
                } else if (sum == 7) {
                    won = false;
                }
            }
        }

        int idx = (K <= 20) ? K : 21;
        if (won) {
            win_counts[idx]++;
            total_won_games++;
        } else {
            lose_counts[idx]++;
        }
    }

    for (int i = 1; i <= 20; ++i) {
        printf("Won roll %d: %d\n", i, win_counts[i]);
    }
    printf("Won after roll 20: %d\n", win_counts[21]);

    for (int i = 1; i <= 20; ++i) {
        printf("Lost roll %d: %d\n", i, lose_counts[i]);
    }
    printf("Lost after roll 20: %d\n", lose_counts[21]);

    double win_percentage = (double)total_won_games * 100.0 / (double)N;
    double avg_roll_len = (double)sum_rolls / (double)N;

    printf("Win rate: %.2f%%\n", win_percentage);
    printf("Average rolls: %.2f\n", avg_roll_len);

    return 0;
}

