int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<vector<int>> floor(50, vector<int>(50, 0));
    int r = 0, c = 0;
    int dir = 0; // 0: Right, 1: Down, 2: Left, 3: Up
    bool penDown = false;

    int dr[] = {0, 1, 0, -1};
    int dc[] = {1, 0, -1, 0};

    string token;
    while (cin >> token) {
        if (token.empty()) continue;
        int cmd = 0;
        if (token[0] >= '0' && token[0] <= '9') {
            cmd = token[0] - '0';
        }

        if (cmd == 1) {
            penDown = false;
        } else if (cmd == 2) {
            penDown = true;
            floor[r][c] = 1;
        } else if (cmd == 3) {
            dir = (dir + 1) % 4;
        } else if (cmd == 4) {
            dir = (dir + 3) % 4;
        } else if (cmd == 5) {
            int steps = 0;
            size_t commaPos = token.find(',');
            if (commaPos != string::npos && commaPos + 1 < token.size()) {
                steps = stoi(token.substr(commaPos + 1));
            } else {
                char ch;
                if (cin.peek() == ',') {
                    cin >> ch;
                }
                cin >> steps;
            }
            for (int i = 0; i < steps; ++i) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (nr >= 0 && nr < 50 && nc >= 0 && nc < 50) {
                    r = nr;
                    c = nc;
                    if (penDown) {
                        floor[r][c] = 1;
                    }
                } else {
                    break;
                }
            }
        } else if (cmd == 6) {
            for (int i = 0; i < 50; ++i) {
                for (int j = 0; j < 50; ++j) {
                    cout << (floor[i][j] ? '*' : ' ');
                }
                cout << "\n";
            }
        } else if (cmd == 9) {
            break;
        }
    }
    return 0;
}

