using namespace std;

const int dr[8] = {-1, -2, -2, -1, 1, 2, 2, 1};
const int dc[8] = {2, 1, -1, -2, -2, -1, 1, 2};

bool isValid(int r, int c, const int board[8][8]) {
    return (r >= 0 && r < 8 && c >= 0 && c < 8 && board[r][c] == 0);
}

int getAccessibility(int r, int c, const int board[8][8]) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (isValid(nr, nc, board)) {
            count++;
        }
    }
    return count;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int r0, c0;
    if (!(cin >> r0 >> c0)) return 0;

    int board[8][8] = {0};
    int curR = r0, curC = c0;
    board[curR][curC] = 1;

    for (int step = 2; step <= 64; ++step) {
        int bestMove = -1;
        int minAccess = 999;

        for (int m = 0; m < 8; ++m) {
            int nextR = curR + dr[m];
            int nextC = curC + dc[m];
            if (isValid(nextR, nextC, board)) {
                int access = getAccessibility(nextR, nextC, board);
                if (access < minAccess) {
                    minAccess = access;
                    bestMove = m;
                }
            }
        }

        if (bestMove == -1) {
            break; // No valid move left
        }

        curR += dr[bestMove];
        curC += dc[bestMove];
        board[curR][curC] = step;
    }

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            cout << board[i][j] << (j == 7 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

