inline bool inside(int r, int c) {
    return r >= 0 && r < 8 && c >= 0 && c < 8;
}

int main() {
    int startR, startC;
    if (scanf("%d %d", &startR, &startC) != 2) return 0;

    vector<vector<int>> grid(8, vector<int>(8, 0));
    int r = startR, c = startC;
    grid[r][c] = 1;

    for (int moveCount = 1; moveCount < 64; ++moveCount) {
        int selectedMove = -1;
        int lowestDeg = 100;

        for (int i = 0; i < 8; ++i) {
            int nr = r + moves[i].r;
            int nc = c + moves[i].c;

            if (inside(nr, nc) && grid[nr][nc] == 0) {
                // Calculate accessibility for (nr, nc)
                int deg = 0;
                for (int j = 0; j < 8; ++j) {
                    int nnr = nr + moves[j].r;
                    int nnc = nc + moves[j].c;
                    if (inside(nnr, nnc) && grid[nnr][nnc] == 0) {
                        deg++;
                    }
                }

                if (deg < lowestDeg) {
                    lowestDeg = deg;
                    selectedMove = i;
                }
            }
        }

        if (selectedMove == -1) break;

        r += moves[selectedMove].r;
        c += moves[selectedMove].c;
        grid[r][c] = moveCount + 1;
    }

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            printf("%d%c", grid[i][j], j == 7 ? '\n' : ' ');
        }
    }

    return 0;
}

#include <iostream>
