using namespace std;

const int dr[8] = {-1, -2, -2, -1, 1, 2, 2, 1};
const int dc[8] = {-2, -1, 1, 2, 2, 1, -1, -2};

struct LCG {
    unsigned long long x;
    unsigned long long a, c, m;
    unsigned long long next() {
        x = (a * x + c) % m;
        return x;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int T;
    if (!(cin >> T)) return 0;
    int r0, c0;
    cin >> r0 >> c0;
    LCG rng;
    cin >> rng.x >> rng.a >> rng.c >> rng.m;

    vector<int> length_count(65, 0);
    vector<vector<int>> first_board;
    int max_len = 0;

    for (int t = 0; t < T; ++t) {
        vector<vector<int>> board(8, vector<int>(8, 0));
        int curr_r = r0, curr_c = c0;
        int step = 1;
        board[curr_r][curr_c] = step;

        while (true) {
            vector<pair<int, int>> valid_moves;
            for (int i = 0; i < 8; ++i) {
                int nr = curr_r + dr[i];
                int nc = curr_c + dc[i];
                if (nr >= 0 && nr < 8 && nc >= 0 && nc < 8 && board[nr][nc] == 0) {
                    valid_moves.push_back({nr, nc});
                }
            }
            if (valid_moves.empty()) {
                break;
            }
            unsigned long long val = rng.next();
            int choice = val % valid_moves.size();
            curr_r = valid_moves[choice].first;
            curr_c = valid_moves[choice].second;
            step++;
            board[curr_r][curr_c] = step;
        }

        if (t == 0) {
            first_board = board;
        }
        length_count[step]++;
        if (step > max_len) {
            max_len = step;
        }
    }

    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            cout << first_board[r][c] << (c == 7 ? "" : " ");
        }
        cout << "\n";
    }

    cout << "Max length: " << max_len << "\n";
    for (int l = 1; l <= 64; ++l) {
        if (length_count[l] > 0) {
            cout << l << ": " << length_count[l] << "\n";
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const int D_ROW[8] = {-1, -2, -2, -1, 1, 2, 2, 1};
static const int D_COL[8] = {-2, -1, 1, 2, 2, 1, -1, -2};

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);

    int trials;
    if (!(cin >> trials)) return 0;
    int startR, startC;
    cin >> startR >> startC;

    unsigned long long state, mult, add, mod;
    cin >> state >> mult >> add >> mod;

    auto get_next_rand = [&]() -> unsigned long long {
        state = (mult * state + add) % mod;
        return state;
    };

    int first_tour[8][8];
    int counts[65] = {0};
    int max_length = 0;

    for (int run = 0; run < trials; ++run) {
        int grid[8][8] = {0};
        int cr = startR, cc = startC;
        int moves = 1;
        grid[cr][cc] = moves;

        while (true) {
            int next_r[8], next_c[8];
            int num_valid = 0;
            for (int dir = 0; dir < 8; ++dir) {
                int tr = cr + D_ROW[dir];
                int tc = cc + D_COL[dir];
                if (tr >= 0 && tr < 8 && tc >= 0 && tc < 8 && grid[tr][tc] == 0) {
                    next_r[num_valid] = tr;
                    next_c[num_valid] = tc;
                    num_valid++;
                }
            }
            if (num_valid == 0) break;

            unsigned long long rval = get_next_rand();
            int picked = (int)(rval % (unsigned long long)num_valid);
            cr = next_r[picked];
            cc = next_c[picked];
            grid[cr][cc] = ++moves;
        }

        if (run == 0) {
            memcpy(first_tour, grid, sizeof(grid));
        }
        counts[moves]++;
        if (moves > max_length) max_length = moves;
    }

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            cout << first_tour[i][j] << (j == 7 ? "" : " ");
        }
        cout << "\n";
    }

    cout << "Max length: " << max_length << "\n";
    for (int len = 1; len <= 64; ++len) {
        if (counts[len] > 0) {
            cout << len << ": " << counts[len] << "\n";
        }
    }

    return 0;
}

