// Ham de quy tim kiem tuyen tinh tu vi tri dau tien
// De tranh tran stack voi n lon (10^5), chia doi de quy hoac de quy theo khoang
int recursiveLinearSearch(const vector<int>& a, int left, int right, int key) {
    if (left > right) return -1;
    if (left == right) {
        return (a[left] == key) ? left : -1;
    }
    int mid = left + (right - left) / 2;
    int leftResult = recursiveLinearSearch(a, left, mid, key);
    if (leftResult != -1) return leftResult;
    return recursiveLinearSearch(a, mid + 1, right, key);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    long long key;
    if (!(cin >> n >> key)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    cout << recursiveLinearSearch(a, 0, n - 1, (int)key) << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

// Cach trien khai de quy chia de tri (divide-and-conquer linear search)
int linearSearchRecursive(const int* arr, int start, int n, int key) {
    if (n <= 0) return -1;
    if (n == 1) return (arr[start] == key) ? start : -1;
    int mid = n / 2;
    int res = linearSearchRecursive(arr, start, mid, key);
    if (res != -1) return res;
    return linearSearchRecursive(arr, start + mid, n - mid, key);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, key;
    if (cin >> n >> key) {
        vector<int> a(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }
        if (n == 0) {
            cout << -1 << "\n";
        } else {
            cout << linearSearchRecursive(a.data(), 0, n, key) << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

bool isUnderAttack(int r1, int c1, int r2, int c2) {
    return (r1 == r2 || c1 == c2 || abs(r1 - r2) == abs(c1 - c2));
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<string> board(8);
    vector<pair<int, int>> queens;
    for (int i = 0; i < 8; ++i) {
        if (!(cin >> board[i])) return 0;
        for (int j = 0; j < 8; ++j) {
            if (board[i][j] == 'Q') {
                queens.push_back({i, j});
            }
        }
    }

    // Check if initial queens attack each other
    for (size_t i = 0; i < queens.size(); ++i) {
        for (size_t j = i + 1; j < queens.size(); ++j) {
            if (isUnderAttack(queens[i].first, queens[i].second, queens[j].first, queens[j].second)) {
                cout << -1 << "\n";
                return 0;
            }
        }
    }

    // Mark squares already attacked by existing queens
    vector<vector<bool>> attacked(8, vector<bool>(8, false));
    for (auto& q : queens) {
        for (int r = 0; r < 8; ++r) {
            for (int c = 0; c < 8; ++c) {
                if (isUnderAttack(q.first, q.second, r, c)) {
                    attacked[r][c] = true;
                }
            }
        }
    }

    int minElim = 1000;
    int countMin = 0;
    bool foundCandidate = false;

    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            if (!attacked[r][c]) {
                foundCandidate = true;
                // Count how many squares not yet attacked would be eliminated by placing a queen at (r, c)
                int elim = 0;
                for (int nr = 0; nr < 8; ++nr) {
                    for (int nc = 0; nc < 8; ++nc) {
                        if (!attacked[nr][nc] && isUnderAttack(r, c, nr, nc)) {
                            elim++;
                        }
                    }
                }
                if (elim < minElim) {
                    minElim = elim;
                    countMin = 1;
                } else if (elim == minElim) {
                    countMin++;
                }
            }
        }
    }

    if (!foundCandidate) {
        cout << "0 0\n";
    } else {
        cout << minElim << " " << countMin << "\n";
    }

    return 0;
}

