        for (int c = 0; c < 8; ++c) {
            if (!(cin >> grid[r][c])) return 0;
            if (grid[r][c] == 'Q') {
                qPos.emplace_back(r, c);
            }
        }
    }

    int nQ = qPos.size();
    for (int i = 0; i < nQ; ++i) {
        for (int j = i + 1; j < nQ; ++j) {
            int dr = abs(qPos[i].first - qPos[j].first);
            int dc = abs(qPos[i].second - qPos[j].second);
            if (dr == 0 || dc == 0 || dr == dc) {
                cout << -1 << "\n";
                return 0;
            }
        }
    }

    bool covered[8][8] = {false};
    for (const auto& q : qPos) {
        for (int r = 0; r < 8; ++r) {
            for (int c = 0; c < 8; ++c) {
                if (r == q.first || c == q.second || abs(r - q.first) == abs(c - q.second)) {
                    covered[r][c] = true;
                }
            }
        }
    }

    int bestElim = 1e9;
    int ways = 0;
    int validSlots = 0;

    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            if (!covered[r][c]) {
                validSlots++;
                int elimCount = 0;
                for (int i = 0; i < 8; ++i) {
                    for (int j = 0; j < 8; ++j) {
                        if (!covered[i][j]) {
                            if (i == r || j == c || abs(i - r) == abs(j - c)) {
                                elimCount++;
                            }
                        }
                    }
                }
                if (elimCount < bestElim) {
                    bestElim = elimCount;
                    ways = 1;
                } else if (elimCount == bestElim) {
                    ways++;
                }
            }
