// Second reference implementation using an explicit recursive helper
int recursiveBinarySearch(const int* arr, int left, int right, int x) {
    if (left > right) return -1;
    int mid = left + (right - left) / 2;
    if (*(arr + mid) == x) return mid;
    if (*(arr + mid) < x) return recursiveBinarySearch(arr, mid + 1, right, x);
    return recursiveBinarySearch(arr, left, mid - 1, x);
}

int main() {
