        for (int i = 0; i < n; ++i) {
            std::cin >> data[i];
        }
        int idx = (n == 0) ? -1 : recursiveBinarySearch(data.data(), 0, n - 1, key);
        std::cout << idx << "\n";
    }
    return 0;
}

