using namespace std;

bool isKnightMove(int r1, int c1, int r2, int c2) {
    int dr = abs(r1 - r2);
    int dc = abs(c1 - c2);
    return (dr == 1 && dc == 2) || (dr == 2 && dc == 1);
}

void solve() {
    int n;
    if (!(cin >> n)) return;
    int total = n * n;
    vector<vector<int>> board(n, vector<int>(n));
    vector<pair<int, int>> pos(total + 1, {-1, -1});
    bool validPermutation = true;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> board[i][j];
            int val = board[i][j];
            if (val >= 1 && val <= total) {
                if (pos[val].first != -1) {
                    validPermutation = false;
                } else {
                    pos[val] = {i, j};
                }
            } else {
                validPermutation = false;
            }
        }
    }

    if (!validPermutation) {
        cout << "INVALID\n";
        return;
    }

    for (int k = 1; k < total; ++k) {
        if (!isKnightMove(pos[k].first, pos[k].second, pos[k + 1].first, pos[k + 1].second)) {
            cout << "INVALID\n";
            return;
        }
    }

    if (isKnightMove(pos[total].first, pos[total].second, pos[1].first, pos[1].second)) {
        cout << "CLOSED\n";
    } else {
        cout << "OPEN\n";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

