    if (r >= '2' && r <= '9') return r - '0';
    if (r == 'J') return 11;
    if (r == 'Q') return 12;
    if (r == 'K') return 13;
    if (r == 'A') return 14;
    return 0;
}

Card parseCard(const string& s) {
    int r = parseRank(s);
    char su = s.back();
    return {r, su};
}

struct HandEval {
    int handType;
    vector<int> tieBreakers;

    bool operator<(const HandEval& other) const {
        if (handType != other.handType) return handType < other.handType;
        return tieBreakers < other.tieBreakers;
    }
    bool operator==(const HandEval& other) const {
        return handType == other.handType && tieBreakers == other.tieBreakers;
    }
};

HandEval evaluate(vector<Card>& cards) {
    vector<int> ranks;
    bool isFlush = true;
    for (int i = 0; i < 5; ++i) {
        ranks.push_back(cards[i].rank);
        if (cards[i].suit != cards[0].suit) isFlush = false;
    }
    sort(ranks.begin(), ranks.end(), greater<int>());

    map<int, int> counts;
    for (int r : ranks) counts[r]++;

    bool isStraight = false;
    int straightHigh = 0;
    vector<int> distinctRanks;
    for (auto const& [r, c] : counts) distinctRanks.push_back(r);
    sort(distinctRanks.begin(), distinctRanks.end(), greater<int>());

    if (distinctRanks.size() == 5) {
        if (distinctRanks[0] - distinctRanks[4] == 4) {
            isStraight = true;
            straightHigh = distinctRanks[0];
        } else if (distinctRanks[0] == 14 && distinctRanks[1] == 5 && distinctRanks[2] == 4 && distinctRanks[3] == 3 && distinctRanks[4] == 2) {
            isStraight = true;
            straightHigh = 5;
        }
    }

    if (isStraight && isFlush) {
        return {9, {straightHigh}};
    }

    vector<pair<int, int>> groups;
    for (auto const& [r, c] : counts) {
        groups.push_back({c, r});
    }
    sort(groups.begin(), groups.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second > b.second;
    });

    if (groups[0].first == 4) {
        return {8, {groups[0].second, groups[1].second}};
    }
    if (groups[0].first == 3 && groups[1].first == 2) {
        return {7, {groups[0].second, groups[1].second}};
    }
    if (isFlush) {
        return {6, ranks};
    }
    if (isStraight) {
        return {5, {straightHigh}};
    }
    if (groups[0].first == 3) {
        return {4, {groups[0].second, groups[1].second, groups[2].second}};
    }
    if (groups[0].first == 2 && groups[1].first == 2) {
        return {3, {groups[0].second, groups[1].second, groups[2].second}};
    }
    if (groups[0].first == 2) {
        return {2, {groups[0].second, groups[1].second, groups[2].second, groups[3].second}};
    }
    return {1, ranks};
}

void solve() {
    vector<Card> h1(5), h2(5);
    for (int i = 0; i < 5; ++i) {
        string s; if (!(cin >> s)) return;
        h1[i] = parseCard(s);
    }
    for (int i = 0; i < 5; ++i) {
        string s; cin >> s;
        h2[i] = parseCard(s);
    }
    HandEval e1 = evaluate(h1);
    HandEval e2 = evaluate(h2);
    if (e2 < e1) cout << "Player 1\n";
    else if (e1 < e2) cout << "Player 2\n";
    else cout << "Tie\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) solve();
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

struct HandScore {
    int category;
    vector<int> tieVector;

    bool operator>(const HandScore& o) const {
        if (category != o.category) return category > o.category;
        return tieVector > o.tieVector;
    }
    bool operator<(const HandScore& o) const {
        if (category != o.category) return category < o.category;
        return tieVector < o.tieVector;
    }
};

HandScore evalHand(const vector<string>& s) {
    vector<int> r(5);
    vector<char> su(5);
    for (int i = 0; i < 5; ++i) {
        su[i] = s[i].back();
        string rstr = s[i].substr(0, s[i].size() - 1);
        if (rstr == "A") r[i] = 14;
        else if (rstr == "K") r[i] = 13;
        else if (rstr == "Q") r[i] = 12;
        else if (rstr == "J") r[i] = 11;
        else if (rstr == "10") r[i] = 10;
        else r[i] = stoi(rstr);
    }
    bool flush = true;
    for (int i = 1; i < 5; ++i) {
        if (su[i] != su[0]) flush = false;
    }

    int cnt[15] = {0};
    for (int x : r) cnt[x]++;

    bool straight = false;
    int straight_top = 0;
    vector<int> unique_r;
    for (int v = 2; v <= 14; ++v) {
        if (cnt[v] > 0) unique_r.push_back(v);
    }
    if (unique_r.size() == 5) {
        if (unique_r[4] - unique_r[0] == 4) {
            straight = true;
            straight_top = unique_r[4];
        } else if (unique_r[0] == 2 && unique_r[1] == 3 && unique_r[2] == 4 && unique_r[3] == 5 && unique_r[4] == 14) {
            straight = true;
            straight_top = 5;
        }
    }

    if (straight && flush) return {9, {straight_top}};

    vector<pair<int, int>> freq;
    for (int v = 2; v <= 14; ++v) {
        if (cnt[v] > 0) freq.push_back({cnt[v], v});
    }
    sort(freq.rbegin(), freq.rend());

    if (freq[0].first == 4) {
        return {8, {freq[0].second, freq[1].second}};
    }
    if (freq[0].first == 3 && freq[1].first == 2) {
        return {7, {freq[0].second, freq[1].second}};
    }
    if (flush) {
        vector<int> tie = r;
        sort(tie.rbegin(), tie.rend());
        return {6, tie};
    }
    if (straight) {
        return {5, {straight_top}};
    }
    if (freq[0].first == 3) {
        return {4, {freq[0].second, freq[1].second, freq[2].second}};
    }
    if (freq[0].first == 2 && freq[1].first == 2) {
        return {3, {freq[0].second, freq[1].second, freq[2].second}};
    }
    if (freq[0].first == 2) {
        return {2, {freq[0].second, freq[1].second, freq[2].second, freq[3].second}};
    }

    vector<int> tie = r;
    sort(tie.rbegin(), tie.rend());
    return {1, tie};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            vector<string> p1(5), p2(5);
            for (int i = 0; i < 5; ++i) cin >> p1[i];
            for (int i = 0; i < 5; ++i) cin >> p2[i];
            HandScore s1 = evalHand(p1);
            HandScore s2 = evalHand(p2);
            if (s1 > s2) cout << "Player 1\n";
            else if (s2 > s1) cout << "Player 2\n";
            else cout << "Tie\n";
        }
    }
    return 0;
}

