void printArray(const vector<vector<int>>& grades) {
    for (size_t i = 0; i < grades.size(); ++i) {
        for (size_t j = 0; j < grades[i].size(); ++j) {
            cout << grades[i][j] << (j + 1 == grades[i].size() ? "" : " ");
        }
        cout << "\n";
    }
}

void minimum(const vector<vector<int>>& grades) {
    int minGrade = 101;
    for (const auto& row : grades) {
        for (int val : row) {
            if (val < minGrade) minGrade = val;
        }
    }
    cout << minGrade << "\n";
}

void maximum(const vector<vector<int>>& grades) {
    int maxGrade = -1;
    for (const auto& row : grades) {
        for (int val : row) {
            if (val > maxGrade) maxGrade = val;
        }
    }
    cout << maxGrade << "\n";
}

void average(const vector<vector<int>>& grades) {
    cout << fixed << setprecision(2);
    for (const auto& row : grades) {
        double sum = 0;
        for (int val : row) {
            sum += val;
        }
        cout << sum / row.size() << "\n";
    }
}

