#include <cstdio>
#include <vector>

using namespace std;

typedef void (*FuncPtr)(int, int, const int*);

void doPrint(int r, int c, const int* arr) {
    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            printf("%d%c", arr[i * c + j], (j == c - 1 ? '\n' : ' '));
        }
    }
}

void doMin(int r, int c, const int* arr) {
    int mn = arr[0];
    int total = r * c;
    for (int i = 1; i < total; ++i) {
        if (arr[i] < mn) mn = arr[i];
    }
    printf("%d\n", mn);
}

void doMax(int r, int c, const int* arr) {
    int mx = arr[0];
    int total = r * c;
    for (int i = 1; i < total; ++i) {
        if (arr[i] > mx) mx = arr[i];
    }
    printf("%d\n", mx);
}

void doAvg(int r, int c, const int* arr) {
    for (int i = 0; i < r; ++i) {
        long long sum = 0;
        for (int j = 0; j < c; ++j) {
            sum += arr[i * c + j];
        }
        printf("%.2f\n", (double)sum / c);
    }
}

int main() {
    int r, c;
    if (scanf("%d %d", &r, &c) != 2) return 0;
    vector<int> a(r * c);
    for (int i = 0; i < r * c; ++i) {
        scanf("%d", &a[i]);
    }

    FuncPtr funcs[4] = { doPrint, doMin, doMax, doAvg };

    int op;
    while (scanf("%d", &op) == 1) {
        if (op == 4) break;
        if (op >= 0 && op <= 3) {
            funcs[op](r, c, a.data());
        }
    }
    return 0;
}

