using namespace std;

// 0: Bac (-1, 0), 1: Dong (0, 1), 2: Nam (1, 0), 3: Tay (0, -1)
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, 1, 0, -1};

int getInitialDirection(int r, int c) {
    if (r == 0) return 2;   // Nam
    if (r == 11) return 0;  // Bac
    if (c == 0) return 1;   // Dong
    if (c == 11) return 3;  // Tay
    return 2;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<string> maze(12);
    for (int i = 0; i < 12; ++i) {
        if (!(cin >> maze[i])) return 0;
    }

    int r_start, c_start;
    if (!(cin >> r_start >> c_start)) return 0;

    int r = r_start, c = c_start;
    int dir = getInitialDirection(r_start, c_start);

    maze[r][c] = 'X';

    for (int step = 0; step < 1000; ++step) {
        // Kiem tra da den loi thoat chua (o bien khac o bat dau)
        if ((r != r_start || c != c_start) && (r == 0 || r == 11 || c == 0 || c == 11)) {
            break;
        }

        // Quy tac ban tay phai: thu cac huong uu tien: Phai -> Thang -> Trai -> Quay lui
        int next_dir = -1;
        int next_r = -1, next_c = -1;

        for (int i = 1; i <= 4; ++i) {
            int d = (dir + i) % 4; // i=1: phai, i=2: lui (neu quy uoc d+1, d, d-1), can tinh dung thu tu
            // Uu tien: (dir + 1) % 4 (phai), dir (thang), (dir + 3) % 4 (trai), (dir + 2) % 4 (nguoc lai)
        }

        int turn_offsets[4] = {1, 0, 3, 2};
        bool moved = false;
        for (int i = 0; i < 4; ++i) {
            int d = (dir + turn_offsets[i]) % 4;
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr >= 0 && nr < 12 && nc >= 0 && nc < 12 && maze[nr][nc] != '#') {
                dir = d;
                r = nr;
                c = nc;
                maze[r][c] = 'X';
                moved = true;
                break;
            }
        }

        if (!moved) break;
        if (r == r_start && c == c_start && step > 0) {
            break;
        }
    }

    for (int i = 0; i < 12; ++i) {
        cout << maze[i] << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
