int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string grid[12];
    for (int i = 0; i < 12; ++i) {
        cin >> grid[i];
    }
    int startR, startC;
    if (!(cin >> startR >> startC)) return 0;

    // 0: Up (North), 1: Right (East), 2: Down (South), 3: Left (West)
    int dRow[4] = {-1, 0, 1, 0};
    int dCol[4] = {0, 1, 0, -1};

    int d = 2; // Default South
    if (startR == 0) d = 2;
    else if (startR == 11) d = 0;
    else if (startC == 0) d = 1;
    else if (startC == 11) d = 3;

    int curR = startR, curC = startC;
    grid[curR][curC] = 'X';

    const int priorityTurn[4] = {1, 0, 3, 2};

    for (int steps = 0; steps < 1000; ++steps) {
        if (steps > 0 && (curR == 0 || curR == 11 || curC == 0 || curC == 11)) {
            break;
        }

        bool canMove = false;
        for (int p = 0; p < 4; ++p) {
            int nd = (d + priorityTurn[p]) % 4;
            int nr = curR + dRow[nd];
            int nc = curC + dCol[nd];
            if (nr >= 0 && nr < 12 && nc >= 0 && nc < 12 && grid[nr][nc] != '#') {
                d = nd;
                curR = nr;
                curC = nc;
                grid[curR][curC] = 'X';
                canMove = true;
                break;
            }
        }

        if (!canMove) break;
        if (curR == startR && curC == startC) break;
    }

    for (int i = 0; i < 12; ++i) {
        cout << grid[i] << "\n";
    }
    return 0;
}

