#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<int> memory(1000, 0);
    int loadAddress = 0;
    int instruction;

    while (cin >> instruction) {
        if (instruction == -99999) break;
        if (loadAddress < 1000) {
            memory[loadAddress++] = instruction;
        }
    }

    int accumulator = 0;
    int instructionCounter = 0;
    int steps = 0;
    const int MAX_STEPS = 100000;

    while (instructionCounter >= 0 && instructionCounter < 1000 && steps < MAX_STEPS) {
        steps++;
        int currentInstruction = memory[instructionCounter];
        int operationCode = currentInstruction / 1000;
        int operand = abs(currentInstruction % 1000);

        instructionCounter++;

        if (operationCode == 43) { // HALT
            break;
        } else if (operationCode == 10) { // READ
            int val;
            if (cin >> val) {
                memory[operand] = val;
            }
        } else if (operationCode == 11) { // WRITE
            cout << memory[operand] << "\n";
        } else if (operationCode == 12) { // NEWLINE
            cout << "\n";
        } else if (operationCode == 20) { // LOAD
            accumulator = memory[operand];
        } else if (operationCode == 21) { // STORE
            memory[operand] = accumulator;
        } else if (operationCode == 30) { // ADD
            accumulator += memory[operand];
        } else if (operationCode == 31) { // SUBTRACT
            accumulator -= memory[operand];
        } else if (operationCode == 32) { // DIVIDE
            if (memory[operand] != 0) {
                accumulator /= memory[operand];
            }
        } else if (operationCode == 33) { // MULTIPLY
            accumulator *= memory[operand];
        } else if (operationCode == 34) { // REMAINDER
            if (memory[operand] != 0) {
                accumulator %= memory[operand];
            }
        } else if (operationCode == 35) { // EXPONENTIATION
            long long base = accumulator;
            long long exp = memory[operand];
            long long res = 1;
            for (int i = 0; i < exp; ++i) {
                res *= base;
            }
            accumulator = res;
        } else if (operationCode == 40) { // BRANCH
            instructionCounter = operand;
        } else if (operationCode == 41) { // BRANCHNEG
            if (accumulator < 0) {
                instructionCounter = operand;
            }
        } else if (operationCode == 42) { // BRANCHZERO
            if (accumulator == 0) {
                instructionCounter = operand;
            }
        }
    }

    return 0;
}

