struct Simpletron {
    int memory[1000];
    int accum;
    int pc;

    Simpletron() : accum(0), pc(0) {
        fill(memory, memory + 1000, 0);
    }

    void run() {
        int count = 0;
        while (pc >= 0 && pc < 1000 && count++ < 100000) {
            int word = memory[pc++];
            int op = word / 1000;
            int addr = abs(word % 1000);

            switch (op) {
                case 10: // READ
                    cin >> memory[addr];
                    break;
                case 11: // WRITE
                    cout << memory[addr] << "\n";
                    break;
                case 12: // NEWLINE
                    cout << "\n";
                    break;
                case 20: // LOAD
                    accum = memory[addr];
                    break;
                case 21: // STORE
                    memory[addr] = accum;
                    break;
                case 30: // ADD
                    accum += memory[addr];
                    break;
                case 31: // SUBTRACT
                    accum -= memory[addr];
                    break;
                case 32: // DIVIDE
                    if (memory[addr] != 0) accum /= memory[addr];
                    break;
                case 33: // MULTIPLY
                    accum *= memory[addr];
                    break;
                case 34: // REMAINDER
                    if (memory[addr] != 0) accum %= memory[addr];
                    break;
                case 35: { // EXPONENTIATION
                    long long b = accum, p = memory[addr], ans = 1;
                    while (p > 0) {
                        if (p & 1) ans *= b;
                        b *= b;
                        p >>= 1;
                    }
                    accum = (int)ans;
                    break;
                }
                case 40: // BRANCH
                    pc = addr;
                    break;
                case 41: // BRANCHNEG
                    if (accum < 0) pc = addr;
                    break;
                case 42: // BRANCHZERO
                    if (accum == 0) pc = addr;
                    break;
                case 43: // HALT
                    return;
                default:
                    break;
            }
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    Simpletron smp;
    int word, idx = 0;
    while (cin >> word && word != -99999) {
        if (idx < 1000) {
            smp.memory[idx++] = word;
        }
    }
    smp.run();
    return 0;
}

