    }

    int best_idx = 0;
    int worst_idx = 0;
    for (int j = 1; j < 5; ++j) {
        if (sum[j] > sum[best_idx]) {
            best_idx = j;
        }
        if (sum[j] < sum[worst_idx]) {
            worst_idx = j;
        }
    }

    printf("%d %lld\n", best_idx + 1, sum[best_idx]);
    printf("%d %lld\n", worst_idx + 1, sum[worst_idx]);

