#include <iostream>
#include <vector>
#include <string>

using namespace std;

// Directions: 0: North, 1: East, 2: South, 3: West
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, 1, 0, -1};

int getInitialDir(int R, int C, int r, int c) {
    if (r == 0) return 2; // South
    if (r == R - 1) return 0; // North
    if (c == 0) return 1; // East
    if (c == C - 1) return 3; // West
    return 2;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int R, C;
    if (!(cin >> R >> C)) return 0;
    int r_start, c_start;
    cin >> r_start >> c_start;
    vector<string> grid(R);
    for (int i = 0; i < R; ++i) {
        cin >> grid[i];
    }

    int r = r_start, c = c_start;
    int dir = getInitialDir(R, C, r, c);
    int start_dir = dir;
    grid[r][c] = 'X';

    const int MAX_STEPS = 1000000;
    int steps = 0;

    while (steps < MAX_STEPS) {
        int next_dir = -1;
        int nr = -1, nc = -1;
        // Priority order: right, straight, left, back
        int check_dirs[4] = {
            (dir + 1) % 4,
            dir,
            (dir + 3) % 4,
            (dir + 2) % 4
        };

        for (int i = 0; i < 4; ++i) {
            int cd = check_dirs[i];
            int tr = r + dr[cd];
            int tc = c + dc[cd];
            if (tr >= 0 && tr < R && tc >= 0 && tc < C && grid[tr][tc] != '#') {
                next_dir = cd;
                nr = tr;
                nc = tc;
                break;
            }
        }

        if (next_dir == -1) {
            // No moves possible
            break;
        }

        r = nr;
        c = nc;
        dir = next_dir;
        grid[r][c] = 'X';
        steps++;

        // Check if reached an exit on the boundary (different from start)
        if ((r != r_start || c != c_start) && (r == 0 || r == R - 1 || c == 0 || c == C - 1)) {
            break;
        }
        // Check if looped back to start with original direction
        if (r == r_start && c == c_start && dir == start_dir) {
            break;
        }
    }

    for (int i = 0; i < R; ++i) {
        cout << grid[i] << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int R, C;
    if (!(cin >> R >> C)) return 0;
    int sr, sc;
    cin >> sr >> sc;
    vector<string> maze(R);
    for (int i = 0; i < R; i++) {
        cin >> maze[i];
    }

    // 0: N (-1, 0), 1: E (0, 1), 2: S (1, 0), 3: W (0, -1)
    int dRow[] = {-1, 0, 1, 0};
    int dCol[] = {0, 1, 0, -1};

    auto determineStartDirection = [&](int r, int c) {
        if (r == 0) return 2;
        if (r == R - 1) return 0;
        if (c == 0) return 1;
        return 3;
    };

    int dir = determineStartDirection(sr, sc);
    int initDir = dir;
    int curR = sr, curC = sc;
    maze[curR][curC] = 'X';

    for (int step = 0; step < 500000; ++step) {
        int chosenDir = -1;
        int nextR = -1, nextC = -1;

        // Right: (dir + 1) % 4, Ahead: dir, Left: (dir + 3) % 4, Back: (dir + 2) % 4
        int attempts[] = {(dir + 1) % 4, dir, (dir + 3) % 4, (dir + 2) % 4};
        for (int d : attempts) {
            int nr = curR + dRow[d];
            int nc = curC + dCol[d];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && maze[nr][nc] != '#') {
                chosenDir = d;
                nextR = nr;
                nextC = nc;
                break;
            }
        }

        if (chosenDir == -1) break;

        curR = nextR;
        curC = nextC;
        dir = chosenDir;
        maze[curR][curC] = 'X';

        bool isBoundary = (curR == 0 || curR == R - 1 || curC == 0 || curC == C - 1);
        if (isBoundary && (curR != sr || curC != sc)) {
            break;
        }
        if (curR == sr && curC == sc && dir == initDir) {
            break;
        }
    }

    for (int i = 0; i < R; i++) {
        cout << maze[i] << "\n";
    }

    return 0;
}

