#include <cstdio>
#include <cstring>
#include <cctype>

int main() {
    char s[105];
    if (fgets(s, sizeof(s), stdin) == nullptr) {
        return 0;
    }

    size_t len = strlen(s);
    if (len > 0 && s[len - 1] == '\n') {
        s[len - 1] = '\0';
        len--;
    }
    if (len > 0 && s[len - 1] == '\r') {
        s[len - 1] = '\0';
        len--;
    }

    char upper_s[105];
    char lower_s[105];

    for (size_t i = 0; i < len; ++i) {
        upper_s[i] = (char)toupper((unsigned char)s[i]);
        lower_s[i] = (char)tolower((unsigned char)s[i]);
    }
    upper_s[len] = '\0';
    lower_s[len] = '\0';

    printf("%s\n", upper_s);
    printf("%s\n", lower_s);

    return 0;
}

