int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s1, s2;
    getline(cin, s1);
    getline(cin, s2);
    size_t n;
    cin >> n;

    size_t len1 = s1.length();
    size_t len2 = s2.length();
    size_t limit = min(n, min(len1, len2));

    int cmp = 0;
    for (size_t i = 0; i < limit; ++i) {
        unsigned char c1 = static_cast<unsigned char>(s1[i]);
        unsigned char c2 = static_cast<unsigned char>(s2[i]);
        if (c1 < c2) {
            cmp = -1;
            break;
        } else if (c1 > c2) {
            cmp = 1;
            break;
        }
    }

    if (cmp == 0 && limit < n) {
        if (len1 < len2) {
            cmp = -1;
        } else if (len1 > len2) {
            cmp = 1;
        }
    }

    if (cmp < 0) {
        cout << "LESS\n";
    } else if (cmp == 0) {
        cout << "EQUAL\n";
    } else {
        cout << "GREATER\n";
    }

    return 0;
}

