        }

        instructionRegister = memory[instructionCounter];
        int code_val = abs(instructionRegister);
        operationCode = code_val / 100;
        operand = code_val % 100;

        if (instructionRegister < 0 && operationCode != 43) {
            printf("*** Invalid operation code ***\n");
            printf("*** Simpletron execution abnormally terminated ***\n");
            break;
        }

        int is_branch = 0;
        int fatal = 0;

        if (operationCode == 10) {
            int input_num;
            if (scanf("%d", &input_num) == 1) {
                memory[operand] = input_num;
            }
        } else if (operationCode == 11) {
            printf("%+05d\n", memory[operand]);
        } else if (operationCode == 20) {
            accumulator = memory[operand];
        } else if (operationCode == 21) {
            memory[operand] = accumulator;
        } else if (operationCode == 30) {
            int temp = accumulator + memory[operand];
            if (temp < -9999 || temp > 9999) {
                printf("*** Accumulator overflow ***\n");
                printf("*** Simpletron execution abnormally terminated ***\n");
                fatal = 1;
            } else {
                accumulator = temp;
            }
        } else if (operationCode == 31) {
            int temp = accumulator - memory[operand];
            if (temp < -9999 || temp > 9999) {
                printf("*** Accumulator overflow ***\n");
                printf("*** Simpletron execution abnormally terminated ***\n");
                fatal = 1;
            } else {
                accumulator = temp;
            }
        } else if (operationCode == 32) {
            if (memory[operand] == 0) {
                printf("*** Attempt to divide by zero ***\n");
                printf("*** Simpletron execution abnormally terminated ***\n");
                fatal = 1;
            } else {
                accumulator /= memory[operand];
            }
        } else if (operationCode == 33) {
            long long temp = 1LL * accumulator * memory[operand];
            if (temp < -9999 || temp > 9999) {
                printf("*** Accumulator overflow ***\n");
                printf("*** Simpletron execution abnormally terminated ***\n");
                fatal = 1;
            } else {
                accumulator = (int)temp;
            }
        } else if (operationCode == 40) {
            instructionCounter = operand;
            is_branch = 1;
        } else if (operationCode == 41) {
            if (accumulator < 0) {
                instructionCounter = operand;
                is_branch = 1;
            }
        } else if (operationCode == 42) {
            if (accumulator == 0) {
                instructionCounter = operand;
                is_branch = 1;
            }
        } else if (operationCode == 43) {
            printf("*** Simpletron execution terminated ***\n");
            print_dump(accumulator, instructionCounter, instructionRegister, operationCode, operand, memory);
            return 0;
        } else {
            printf("*** Invalid operation code ***\n");
            printf("*** Simpletron execution abnormally terminated ***\n");
            fatal = 1;
        }

        if (fatal) break;
        if (!is_branch) {
            instructionCounter++;
        }
    }

    print_dump(accumulator, instructionCounter, instructionRegister, operationCode, operand, memory);
    return 0;
}

