#include <vector>
#include <string>

using namespace std;

// Triển khai quicksort để minh họa kỹ thuật sắp xếp mảng chuỗi
void quickSort(vector<string>& arr, int low, int high) {
    if (low < high) {
        string pivot = arr[high];
        int i = low - 1;
        for (int j = low; j < high; ++j) {
            if (arr[j] <= pivot) {
                ++i;
                swap(arr[i], arr[j]);
            }
        }
        swap(arr[i + 1], arr[high]);
        int pi = i + 1;

        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<string> towns(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, towns[i]);
    }

    quickSort(towns, 0, n - 1);

    for (int i = 0; i < n; ++i) {
        cout << towns[i] << "\n";
    }

    return 0;
}

