using namespace std;

// Phien ban 1: Dung chi so mang (array indexing)
int my_strcmp_idx(const string &s1, const string &s2) {
    size_t i = 0;
    while (i < s1.size() && i < s2.size()) {
        unsigned char c1 = (unsigned char)s1[i];
        unsigned char c2 = (unsigned char)s2[i];
        if (c1 < c2) return -1;
        if (c1 > c2) return 1;
        i++;
    }
    if (s1.size() < s2.size()) return -1;
    if (s1.size() > s2.size()) return 1;
    return 0;
}

int my_strncmp_idx(const string &s1, const string &s2, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        bool end1 = (i >= s1.size());
        bool end2 = (i >= s2.size());
        if (end1 && end2) return 0;
        if (end1) return -1;
        if (end2) return 1;

        unsigned char c1 = (unsigned char)s1[i];
        unsigned char c2 = (unsigned char)s2[i];
        if (c1 < c2) return -1;
        if (c1 > c2) return 1;
    }
    return 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s1, s2;
    if (!getline(cin, s1)) return 0;
    if (!getline(cin, s2)) return 0;
    size_t n;
    if (!(cin >> n)) return 0;

    cout << my_strcmp_idx(s1, s2) << " " << my_strncmp_idx(s1, s2, n) << "\n";
    return 0;
}

#include <iostream>
#include <string>

using namespace std;

// Phien ban 2: Dung con tro va phep toan con tro (pointers and pointer arithmetic)
int my_strcmp_ptr(const char *p1, const char *p2) {
    while (*p1 != '\0' && *p1 == *p2) {
        p1++;
        p2++;
    }
    unsigned char u1 = (unsigned char)(*p1);
    unsigned char u2 = (unsigned char)(*p2);
    if (u1 < u2) return -1;
    if (u1 > u2) return 1;
    return 0;
}

int my_strncmp_ptr(const char *p1, const char *p2, size_t n) {
    while (n > 0 && *p1 != '\0' && *p1 == *p2) {
        p1++;
        p2++;
        n--;
    }
    if (n == 0) return 0;
    unsigned char u1 = (unsigned char)(*p1);
    unsigned char u2 = (unsigned char)(*p2);
    if (u1 < u2) return -1;
    if (u1 > u2) return 1;
    return 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s1, s2;
    if (!getline(cin, s1)) return 0;
    if (!getline(cin, s2)) return 0;
    size_t n;
    if (!(cin >> n)) return 0;

    int cmp = my_strcmp_ptr(s1.c_str(), s2.c_str());
    int ncmp = my_strncmp_ptr(s1.c_str(), s2.c_str(), n);

    cout << cmp << " " << ncmp << "\n";
    return 0;
}

