#include <iostream>

using namespace std;

int my_isdigit(int c) {
    return (c >= '0' && c <= '9') ? 1 : 0;
}

int my_islower(int c) {
    return (c >= 'a' && c <= 'z') ? 1 : 0;
}

int my_isupper(int c) {
    return (c >= 'A' && c <= 'Z') ? 1 : 0;
}

int my_isalpha(int c) {
    return (my_islower(c) || my_isupper(c)) ? 1 : 0;
}

int my_isalnum(int c) {
    return (my_isalpha(c) || my_isdigit(c)) ? 1 : 0;
}

int my_isxdigit(int c) {
    return (my_isdigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) ? 1 : 0;
}

int my_tolower(int c) {
    if (my_isupper(c)) return c + ('a' - 'A');
    return c;
}

int my_toupper(int c) {
    if (my_islower(c)) return c - ('a' - 'A');
    return c;
}

int my_isspace(int c) {
    return (c == ' ' || c == '\n' || c == '\t' || c == '\v' || c == '\f' || c == '\r') ? 1 : 0;
}

int my_iscntrl(int c) {
    return ((c >= 0 && c <= 31) || c == 127) ? 1 : 0;
}

int my_isprint(int c) {
    return (c >= 32 && c <= 126) ? 1 : 0;
}

int my_isgraph(int c) {
    return (c >= 33 && c <= 126) ? 1 : 0;
}

int my_ispunct(int c) {
    return (my_isgraph(c) && !my_isalnum(c)) ? 1 : 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int c;
        cin >> c;
        cout << my_isdigit(c) << " "
             << my_isalpha(c) << " "
             << my_isalnum(c) << " "
             << my_isxdigit(c) << " "
             << my_islower(c) << " "
             << my_isupper(c) << " "
             << my_tolower(c) << " "
             << my_toupper(c) << " "
             << my_isspace(c) << " "
             << my_iscntrl(c) << " "
             << my_isprint(c) << " "
             << my_isgraph(c) << " "
             << my_ispunct(c) << "\n";
    }
    return 0;
}

#include <vector>
#include <iostream>

using namespace std;

struct CharHandler {
    static bool isDigit(int c) { return c >= 48 && c <= 57; }
    static bool isLower(int c) { return c >= 97 && c <= 122; }
    static bool isUpper(int c) { return c >= 65 && c <= 90; }
    static bool isAlpha(int c) { return isLower(c) || isUpper(c); }
    static bool isAlnum(int c) { return isAlpha(c) || isDigit(c); }
    static bool isXDigit(int c) {
        return isDigit(c) || (c >= 65 && c <= 70) || (c >= 97 && c <= 102);
    }
    static int toLower(int c) {
        return isUpper(c) ? (c + 32) : c;
    }
    static int toUpper(int c) {
        return isLower(c) ? (c - 32) : c;
    }
    static bool isSpace(int c) {
        return c == 32 || (c >= 9 && c <= 13);
    }
    static bool isCntrl(int c) {
        return (c >= 0 && c <= 31) || c == 127;
    }
    static bool isPrint(int c) {
        return c >= 32 && c <= 126;
    }
    static bool isGraph(int c) {
        return c >= 33 && c <= 126;
    }
    static bool isPunct(int c) {
        return isPrint(c) && c != 32 && !isAlnum(c);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (cin >> T) {
        while (T--) {
            int v;
            cin >> v;
            cout << (CharHandler::isDigit(v) ? 1 : 0) << " "
                 << (CharHandler::isAlpha(v) ? 1 : 0) << " "
                 << (CharHandler::isAlnum(v) ? 1 : 0) << " "
                 << (CharHandler::isXDigit(v) ? 1 : 0) << " "
                 << (CharHandler::isLower(v) ? 1 : 0) << " "
                 << (CharHandler::isUpper(v) ? 1 : 0) << " "
                 << CharHandler::toLower(v) << " "
                 << CharHandler::toUpper(v) << " "
                 << (CharHandler::isSpace(v) ? 1 : 0) << " "
                 << (CharHandler::isCntrl(v) ? 1 : 0) << " "
                 << (CharHandler::isPrint(v) ? 1 : 0) << " "
                 << (CharHandler::isGraph(v) ? 1 : 0) << " "
                 << (CharHandler::isPunct(v) ? 1 : 0) << "\n";
        }
    }
    return 0;
}

#include <iostream>
