#include <unordered_map>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<long long> letter_counts(26, 0);
    vector<string> order;
    unordered_map<string, long long> word_counts;
    unordered_map<int, long long> len_counts;
    int max_len = 0;

    string line;
    while (getline(cin, line)) {
        string cur_word = "";
        for (char ch : line) {
            if (isalpha(static_cast<unsigned char>(ch))) {
                char lower_ch = tolower(static_cast<unsigned char>(ch));
                letter_counts[lower_ch - 'a']++;
                cur_word += lower_ch;
            } else {
                if (!cur_word.empty()) {
                    int len = cur_word.length();
                    len_counts[len]++;
                    if (len > max_len) max_len = len;
                    if (word_counts[cur_word] == 0) {
                        order.push_back(cur_word);
                    }
                    word_counts[cur_word]++;
                    cur_word.clear();
                }
            }
        }
        if (!cur_word.empty()) {
            int len = cur_word.length();
            len_counts[len]++;
            if (len > max_len) max_len = len;
            if (word_counts[cur_word] == 0) {
                order.push_back(cur_word);
            }
            word_counts[cur_word]++;
            cur_word.clear();
        }
    }

    cout << "Letter Occurrences\n";
    for (int i = 0; i < 26; ++i) {
        cout << (char)('a' + i) << ": " << letter_counts[i] << "\n";
    }

    cout << "Word Length Occurrences\n";
    for (int l = 1; l <= max_len; ++l) {
        cout << l << ": " << len_counts[l] << "\n";
    }

    cout << "Unique Word Occurrences\n";
    for (const string &w : order) {
        cout << w << ": " << word_counts[w] << "\n";
    }

    return 0;
}

