#include <iostream>
#include <string>
#include <vector>
#include <iomanip>

using namespace std;

const vector<string> ones = {
    "", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE",
    "TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN", "EIGHTEEN", "NINETEEN"
};

const vector<string> tens = {
    "", "", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"
};

string convertLessThanThousand(int n) {
    string res = "";
    if (n >= 100) {
        res += ones[n / 100] + " HUNDRED";
        n %= 100;
        if (n > 0) res += " ";
    }
    if (n >= 20) {
        res += tens[n / 10];
        if (n % 10 > 0) {
            res += " " + ones[n % 10];
        }
    } else if (n > 0) {
        res += ones[n];
    }
    return res;
}

string numberToWords(long long n) {
    if (n == 0) return "ZERO";
    string res = "";
    if (n >= 1000) {
        res += convertLessThanThousand(n / 1000) + " THOUSAND";
        n %= 1000;
        if (n > 0) res += " ";
    }
    if (n > 0) {
        res += convertLessThanThousand(n);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (cin >> s) {
        size_t dot = s.find('.');
        long long intPart = 0;
        string cents = "00";
        if (dot == string::npos) {
            intPart = stoll(s);
        } else {
            intPart = stoll(s.substr(0, dot));
            cents = s.substr(dot + 1);
            while (cents.length() < 2) cents += '0';
            if (cents.length() > 2) cents = cents.substr(0, 2);
        }
        cout << numberToWords(intPart) << " and " << cents << "/100\n";
    }
    return 0;
}

#include <cstdio>
