using namespace std;

string spell999(int num) {
    static const char* const below20[] = {
        "", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE",
        "TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN", "EIGHTEEN", "NINETEEN"
    };
    static const char* const tensArr[] = {
        "", "", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"
    };

    string out = "";
    if (num >= 100) {
        out += below20[num / 100];
        out += " HUNDRED";
        num %= 100;
        if (num > 0) out += " ";
    }
    if (num >= 20) {
        out += tensArr[num / 10];
        if (num % 10 != 0) {
            out += " ";
            out += below20[num % 10];
        }
    } else if (num > 0) {
        out += below20[num];
    }
    return out;
}

int main() {
    string line;
    if (!(cin >> line)) return 0;

    int intPart = 0;
    int cents = 0;
    size_t dotPos = line.find('.');
    if (dotPos == string::npos) {
        intPart = stoi(line);
        cents = 0;
    } else {
        intPart = stoi(line.substr(0, dotPos));
        string centStr = line.substr(dotPos + 1);
        if (centStr.length() == 1) centStr += "0";
        cents = stoi(centStr.substr(0, 2));
    }

    string words = "";
    if (intPart == 0) {
        words = "ZERO";
    } else {
        int thousands = intPart / 1000;
        int remainder = intPart % 1000;
        if (thousands > 0) {
            words += spell999(thousands) + " THOUSAND";
            if (remainder > 0) words += " ";
        }
        if (remainder > 0) {
            words += spell999(remainder);
        }
    }

    char centBuf[8];
    snprintf(centBuf, sizeof(centBuf), "%02d/100", cents);
    cout << words << " and " << centBuf << "\n";
    return 0;
}

