#include <iostream>
#include <string>
#include <vector>

using namespace std;

struct Rule {
    string original;
    string replacement;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int m;
    if (!(cin >> m)) return 0;
    cin.ignore();

    vector<Rule> rules;
    rules.reserve(m);
    for (int i = 0; i < m; ++i) {
        string o, r;
        getline(cin, o);
        getline(cin, r);
        bool exists = false;
        for (const auto& existing : rules) {
            if (existing.original == o) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            rules.push_back({o, r});
        }
    }

    int n;
    if (!(cin >> n)) return 0;
    cin.ignore();

    for (int i = 0; i < n; ++i) {
        string ingredient;
        getline(cin, ingredient);
        bool replaced = false;
        for (const auto& rule : rules) {
            if (rule.original == ingredient) {
                cout << rule.replacement << "\n";
                replaced = true;
                break;
            }
        }
        if (!replaced) {
            cout << ingredient << "\n";
        }
    }

    cout << "Always consult your physician before making significant changes to your diet." << "\n";
