using namespace std;

struct Rule {
    string abbr;
    string full;
    vector<string> full_tokens;
    int id;
};

string toLower(const string& s) {
    string res = s;
    for (char &c : res) c = tolower(c);
    return res;
}

vector<string> splitWords(const string& s) {
    vector<string> tokens;
    stringstream ss(s);
    string w;
    while (ss >> w) {
        tokens.push_back(w);
    }
    return tokens;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int k;
    if (!(cin >> k)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<Rule> rules(k);
    for (int i = 0; i < k; ++i) {
        string line;
        getline(cin, line);
        auto pos = line.find(':');
        rules[i].abbr = line.substr(0, pos);
        rules[i].full = line.substr(pos + 1);
        rules[i].full_tokens = splitWords(rules[i].full);
        rules[i].id = i;
    }

    int m;
    cin >> m;
    getline(cin, dummy);

    string text;
    getline(cin, text);
    vector<string> words = splitWords(text);

    vector<string> result;
    if (m == 1) {
        for (const auto& w : words) {
            string w_low = toLower(w);
            bool matched = false;
            for (const auto& r : rules) {
                if (toLower(r.abbr) == w_low) {
                    vector<string> ft = r.full_tokens;
                    for (const auto& tok : ft) result.push_back(tok);
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                result.push_back(w);
            }
        }
    } else {
        int i = 0;
        int n = words.size();
        while (i < n) {
            int best_len = 0;
            int best_idx = -1;
            for (int r_idx = 0; r_idx < k; ++r_idx) {
                const auto& r = rules[r_idx];
                int flen = r.full_tokens.size();
                if (i + flen <= n) {
                    bool match = true;
                    for (int j = 0; j < flen; ++j) {
                        if (toLower(words[i + j]) != toLower(r.full_tokens[j])) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        if (flen > best_len) {
                            best_len = flen;
                            best_idx = r_idx;
                        }
                    }
                }
            }
            if (best_idx != -1) {
                result.push_back(rules[best_idx].abbr);
                i += best_len;
            } else {
                result.push_back(words[i]);
                i++;
            }
        }
    }

    for (size_t i = 0; i < result.size(); ++i) {
        cout << result[i] << (i + 1 == result.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}

