using namespace std;

string toLowerStr(const string& s) {
    string res = s;
    for (char &c : res) c = tolower(c);
    return res;
}

string applyCasing(const string& orig, const string& repl) {
    bool allUpper = true;
    for (char c : orig) {
        if (!isupper(c)) {
            allUpper = false;
            break;
        }
    }
    if (allUpper) {
        string res = repl;
        for (char &c : res) c = toupper(c);
        return res;
    }

    bool title = isupper(orig[0]);
    for (size_t i = 1; i < orig.size(); ++i) {
        if (!islower(orig[i])) {
            title = false;
            break;
        }
    }
    if (title) {
        string res = repl;
        for (char &c : res) c = tolower(c);
        if (!res.empty()) res[0] = toupper(res[0]);
        return res;
    }

    string res = repl;
    for (char &c : res) c = tolower(c);
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int m;
    if (!(cin >> m)) return 0;

    map<string, string> dict;
    for (int i = 0; i < m; ++i) {
        string u, v;
        cin >> u >> v;
        dict[toLowerStr(u)] = toLowerStr(v);
    }

    int n;
    cin >> n;
    string dummy;
    getline(cin, dummy);

    for (int i = 0; i < n; ++i) {
        string line;
        getline(cin, line);
        string out = "";
        size_t j = 0;
        while (j < line.size()) {
            if (isalpha(line[j])) {
                size_t k = j;
                while (k < line.size() && isalpha(line[k])) {
                    k++;
                }
                string word = line.substr(j, k - j);
                string lowerWord = toLowerStr(word);
                if (dict.count(lowerWord)) {
                    out += applyCasing(word, dict[lowerWord]);
                } else {
                    out += word;
                }
                j = k;
            } else {
                out += line[j];
                j++;
            }
        }
        cout << out << "\n";
    }
    return 0;
}

