int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int M;
    if (!(cin >> M)) return 0;
    unordered_map<string, string> rules;
    for (int i = 0; i < M; ++i) {
        string from, to;
        cin >> from >> to;
        for (auto &c : from) c = tolower(c);
        for (auto &c : to) c = tolower(c);
        rules[from] = to;
    }

    int N;
    cin >> N;
    string emptyLine;
    getline(cin, emptyLine);

    auto transformWord = [&](const string& word) -> string {
        string lowerW = word;
        for (auto &c : lowerW) c = tolower(c);
        auto it = rules.find(lowerW);
        if (it == rules.end()) return word;

        const string& rep = it->second;
        bool isAllUpper = true;
        for (char c : word) {
            if (!isupper(static_cast<unsigned char>(c))) {
                isAllUpper = false;
                break;
            }
        }
        if (isAllUpper) {
            string res = rep;
            for (char &c : res) c = toupper(static_cast<unsigned char>(c));
            return res;
        }

        bool isTitle = isupper(static_cast<unsigned char>(word[0]));
        for (size_t i = 1; i < word.length(); ++i) {
            if (!islower(static_cast<unsigned char>(word[i]))) {
                isTitle = false;
                break;
            }
        }
        if (isTitle) {
            string res = rep;
            for (char &c : res) c = tolower(static_cast<unsigned char>(c));
            if (!res.empty()) res[0] = toupper(static_cast<unsigned char>(res[0]));
            return res;
        }

        string res = rep;
        for (char &c : res) c = tolower(static_cast<unsigned char>(c));
        return res;
    };

    for (int lineIdx = 0; lineIdx < N; ++lineIdx) {
        string s;
        getline(cin, s);
        string res = "";
        string cur = "";
        for (char c : s) {
            if (isalpha(static_cast<unsigned char>(c))) {
                cur.push_back(c);
            } else {
                if (!cur.empty()) {
                    res += transformWord(cur);
                    cur.clear();
                }
                res.push_back(c);
            }
        }
        if (!cur.empty()) {
            res += transformWord(cur);
        }
        cout << res << "\n";
    }
    return 0;
}

