#include <bits/stdc++.h>
using namespace std;

struct Unit {
    int category;
    double factor;
};

static const unordered_map<string, Unit> UNIT_DICT = {
    {"meters", {1, 1.0}},
    {"centimeters", {1, 0.01}},
    {"millimeters", {1, 0.001}},
    {"kilometers", {1, 1000.0}},
    {"inches", {1, 0.0254}},
    {"feet", {1, 0.3048}},
    {"yards", {1, 0.9144}},
    {"miles", {1, 1609.344}},
    {"kilograms", {2, 1.0}},
    {"grams", {2, 0.001}},
    {"milligrams", {2, 0.000001}},
    {"pounds", {2, 0.45359237}},
    {"ounces", {2, 0.028349523125}},
    {"liters", {3, 1.0}},
    {"milliliters", {3, 0.001}},
    {"quarts", {3, 0.946352946}},
    {"gallons", {3, 3.785411784}},
    {"cups", {3, 0.2365882365}}
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (!(cin >> T)) return 0;
    string dummy;
    getline(cin, dummy);
    while (T--) {
        string line;
        if (!getline(cin, line)) break;
        if (line.empty()) {
            T++;
            continue;
        }
        stringstream ss(line);
        string token;
        vector<string> tokens;
        while (ss >> token) {
            tokens.push_back(token);
        }
        if (tokens.size() < 7) {
            cout << "Invalid conversion\n";
            continue;
        }
        string targetUnit = tokens[2];
        double val = stod(tokens[5]);
        string sourceUnit = tokens[6];
        if (!sourceUnit.empty() && sourceUnit.back() == '?') {
            sourceUnit.pop_back();
        }
        auto uSrc = UNIT_DICT.find(sourceUnit);
        auto uDst = UNIT_DICT.find(targetUnit);
        if (uSrc == UNIT_DICT.end() || uDst == UNIT_DICT.end()) {
            cout << "Invalid conversion\n";
        } else if (uSrc->second.category != uDst->second.category) {
            cout << "Invalid conversion\n";
        } else {
            double inBase = val * uSrc->second.factor;
            double ans = inBase / uDst->second.factor;
            cout << fixed << setprecision(4) << ans << "\n";
        }
    }
    return 0;
}

