uint32_t packCharacters(char c1, char c2, char c3, char c4) {
    uint32_t packed = static_cast<unsigned char>(c1);
    packed = (packed << 8) | static_cast<unsigned char>(c2);
    packed = (packed << 8) | static_cast<unsigned char>(c3);
    packed = (packed << 8) | static_cast<unsigned char>(c4);
    return packed;
}

