struct Date {
    int day;
    int month;
    int year;
};

struct HealthProfile {
    string firstName;
    string lastName;
    string gender;
    Date dob;
    double height;
    double weight;
};

int calculateAge(const Date& dob, const Date& current) {
    int age = current.year - dob.year;
    if (current.month < dob.month || (current.month == dob.month && current.day < dob.day)) {
        age--;
    }
    return age;
}

double calculateBMI(double height, double weight) {
    return (weight * 703.0) / (height * height);
}

int calculateMaxHeartRate(int age) {
    return 220 - age;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    HealthProfile p;
    Date current;

    if (!(cin >> p.firstName >> p.lastName)) return 0;
    cin >> p.gender;
    cin >> p.dob.day >> p.dob.month >> p.dob.year;
    cin >> current.day >> current.month >> current.year;
    cin >> p.height >> p.weight;

    int age = calculateAge(p.dob, current);
    double bmi = calculateBMI(p.height, p.weight);
    int maxHeartRate = calculateMaxHeartRate(age);
    double minTarget = maxHeartRate * 0.50;
    double maxTarget = maxHeartRate * 0.85;

    cout << "Name: " << p.lastName << " " << p.firstName << "\n";
    cout << "Gender: " << p.gender << "\n";
    cout << "Date of Birth: " << p.dob.day << "/" << p.dob.month << "/" << p.dob.year << "\n";
    cout << "Age: " << age << "\n";
    cout << fixed << setprecision(1);
    cout << "Height: " << p.height << " inches\n";
    cout << "Weight: " << p.weight << " pounds\n";
    cout << "BMI: " << bmi << "\n";
    cout << "Max Heart Rate: " << maxHeartRate << " bpm\n";
    cout << "Target Heart Rate: " << minTarget << " - " << maxTarget << " bpm\n";

    return 0;
}

