#include <iostream>
#include <string>
#include <vector>

using namespace std;

const vector<string> keypad = {
    "",    // 0
    "",    // 1
    "ABC", // 2
    "DEF", // 3
    "GHI", // 4
    "JKL", // 5
    "MNO", // 6
    "PRS", // 7
    "TUV", // 8
    "WXY"  // 9
};

void backtrack(const string& digits, int index, string& current) {
    if (index == 7) {
        cout << current << "\n";
        return;
    }
    int digit = digits[index] - '0';
    for (char c : keypad[digit]) {
        current.push_back(c);
        backtrack(digits, index + 1, current);
        current.pop_back();
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (cin >> s) {
        string current = "";
        backtrack(s, 0, current);
    }
    return 0;
}

