    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    vector<MasterRecord> masters(n);
    for (int i = 0; i < n; ++i) {
        cin >> masters[i].account >> masters[i].name >> masters[i].balance;
    }

    int m;
