    vector<TransRecord> trans(m);
    for (int i = 0; i < m; ++i) {
        cin >> trans[i].account >> trans[i].amount;
    }

    vector<string> unmatched_errors;
    vector<MasterRecord> new_masters;

    int i = 0, j = 0;
    while (i < n && j < m) {
