};

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);

    int n;
    if (!(cin >> n)) return 0;
    vector<Account> old_mast(n);
    for (int i = 0; i < n; ++i) {
        cin >> old_mast[i].id >> old_mast[i].name >> old_mast[i].balance;
    }

    int m;
    if (!(cin >> m)) return 0;
    vector<pair<long long, double>> transactions(m);
    for (int i = 0; i < m; ++i) {
        cin >> transactions[i].first >> transactions[i].second;
    }

    vector<string> unmatched;
    vector<Account> new_mast;
    new_mast.reserve(n);

    size_t ptr_m = 0, ptr_t = 0;
    while (ptr_m < old_mast.size() || ptr_t < transactions.size()) {
        if (ptr_m == old_mast.size()) {
            unmatched.push_back("Unmatched transaction record for account number " + to_string(transactions[ptr_t].first));
            ptr_t++;
        } else if (ptr_t == transactions.size()) {
            new_mast.push_back(old_mast[ptr_m]);
