#include <iostream>
#include <string>
#include <vector>
#include <set>
#include <unordered_set>
#include <algorithm>

using namespace std;

const string mapping_table[10] = {
    "", "", "ABC", "DEF", "GHI", "JKL", "MNO", "PRS", "TUV", "WXY"
};

bool canForm(const string& s, const unordered_set<string>& dict) {
    int n = s.length();
    vector<bool> dp(n + 1, false);
    dp[0] = true;
    for (int i = 0; i < n; ++i) {
        if (!dp[i]) continue;
        string cur = "";
        for (int j = i; j < n; ++j) {
            cur += s[j];
            if (dict.count(cur)) {
                dp[j + 1] = true;
            }
        }
    }
    return dp[n];
}

void generateAll(int idx, const string& digits, string& current, const unordered_set<string>& dict, vector<string>& results) {
    if (idx == 7) {
        if (canForm(current, dict)) {
            results.push_back(current);
        }
        return;
    }
    int d = digits[idx] - '0';
    for (char c : mapping_table[d]) {
        current.push_back(c);
        generateAll(idx + 1, digits, current, dict, results);
        current.pop_back();
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string phoneRaw;
    if (!(cin >> phoneRaw)) return 0;
    string digits = "";
    for (char c : phoneRaw) {
        if (c >= '2' && c <= '9') {
            digits += c;
        }
    }
    int n;
    if (!(cin >> n)) return 0;
    unordered_set<string> dict;
    for (int i = 0; i < n; ++i) {
        string w;
        cin >> w;
        dict.insert(w);
    }
    vector<string> results;
    string current = "";
    generateAll(0, digits, current, dict, results);
    sort(results.begin(), results.end());
    results.erase(unique(results.begin(), results.end()), results.end());
    if (results.empty()) {
        cout << "NONE\n";
    } else {
        for (const string& s : results) {
            cout << s << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <set>

using namespace std;

struct TrieNode {
    TrieNode* children[26];
    bool isEnd;
    TrieNode() {
        isEnd = false;
        for (int i = 0; i < 26; ++i) children[i] = nullptr;
    }
};

void insertTrie(TrieNode* root, const string& word) {
    TrieNode* curr = root;
    for (char c : word) {
        int idx = c - 'A';
        if (idx < 0 || idx >= 26) return;
        if (!curr->children[idx]) {
            curr->children[idx] = new TrieNode();
        }
        curr = curr->children[idx];
    }
    curr->isEnd = true;
}

const string MAP_KEY[10] = {
    "", "", "ABC", "DEF", "GHI", "JKL", "MNO", "PRS", "TUV", "WXY"
};

bool matchTrie(TrieNode* root, const string& s, int start, vector<int>& memo) {
    if (start == (int)s.length()) return true;
    if (memo[start] != -1) return memo[start];
    TrieNode* curr = root;
    for (int i = start; i < (int)s.length(); ++i) {
        int idx = s[i] - 'A';
        if (!curr->children[idx]) break;
        curr = curr->children[idx];
        if (curr->isEnd) {
            if (matchTrie(root, s, i + 1, memo)) {
                return memo[start] = 1;
            }
        }
    }
    return memo[start] = 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string raw;
    if (!(cin >> raw)) return 0;
    string digits = "";
    for (char c : raw) {
        if (c >= '2' && c <= '9') digits += c;
    }
    int n;
    if (!(cin >> n)) return 0;
    TrieNode* root = new TrieNode();
    for (int i = 0; i < n; ++i) {
        string w;
        cin >> w;
        insertTrie(root, w);
    }
    vector<string> valid;
    auto dfs = [&](auto self, int idx, string cur) -> void {
        if (idx == 7) {
            vector<int> memo(8, -1);
            if (matchTrie(root, cur, 0, memo)) {
                valid.push_back(cur);
            }
            return;
        }
        int d = digits[idx] - '0';
        for (char c : MAP_KEY[d]) {
            self(self, idx + 1, cur + c);
        }
    };
    dfs(dfs, 0, "");
    if (valid.empty()) {
        cout << "NONE\n";
    } else {
        for (const string& ans : valid) {
            cout << ans << "\n";
        }
    }
    return 0;
}

