Node* merge(Node* l1, Node* l2) {
    Node dummy(0);
    Node* tail = &dummy;
    while (l1 != nullptr && l2 != nullptr) {
        if (l1->data <= l2->data) {
            tail->next = l1;
            l1 = l1->next;
        } else {
            tail->next = l2;
            l2 = l2->next;
        }
        tail = tail->next;
    }
    if (l1 != nullptr) tail->next = l1;
    else tail->next = l2;
    return dummy.next;
}

