Node* buildList(int len, const string& s) {
    if (len == 0) return nullptr;
    Node* head = new Node(s[0]);
    Node* cur = head;
    for (int i = 1; i < len; ++i) {
        cur->next = new Node(s[i]);
        cur = cur->next;
    }
    return head;
}

void concatenate(Node*& head1, Node* head2) {
    if (head1 == nullptr) {
        head1 = head2;
        return;
    }
    Node* cur = head1;
    while (cur->next != nullptr) {
        cur = cur->next;
    }
    cur->next = head2;
}

void printList(Node* head) {
    Node* cur = head;
    while (cur != nullptr) {
        cout << cur->data;
        cur = cur->next;
    }
    cout << "\n";
}

