    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Keyword> keywords(n);
    for (int i = 0; i < n; ++i) {
        cin >> keywords[i].points;
        string dummy;
        getline(cin, dummy); // read remainder of line
        // dummy has a leading space
        if (!dummy.empty() && dummy[0] == ' ') {
            dummy.erase(0, 1);
        }
        keywords[i].original = dummy;
        keywords[i].lower = toLower(dummy);
    }

    int m;
    if (!(cin >> m)) return 0;
    string dummy;
    getline(cin, dummy); // consume newline after m

    string fullText = "";
    for (int i = 0; i < m; ++i) {
        string line;
        getline(cin, line);
        fullText += line;
        if (i < m - 1) fullText += "\n";
    }

    string lowerText = toLower(fullText);
    long long totalScore = 0;

    for (int i = 0; i < n; ++i) {
        int cnt = countOccurrences(lowerText, keywords[i].lower);
        if (cnt > 0) {
            long long pts = (long long)cnt * keywords[i].points;
            totalScore += pts;
