long long power(long long base, long long exp) {
    long long res = 1;
    long long b = base;
    while (exp > 0) {
        if (exp & 1) res *= b;
        b *= b;
        exp >>= 1;
    }
    return res;
}

long long calculate(long long op1, long long op2, char op) {
    switch (op) {
        case '+': return op1 + op2;
        case '-': return op1 - op2;
        case '*': return op1 * op2;
        case '/': return op1 / op2;
        case '%': return op1 % op2;
        case '^': return power(op1, op2);
        default: return 0;
    }
}

