    for (char c : line) {
        if (!isspace(c)) {
            infix += c;
        }
    }

    vector<char> st;
    st.push_back('(');
    infix.push_back(')');

    vector<char> postfix;

    for (size_t i = 0; i < infix.size() && !st.empty(); ++i) {
        char c = infix[i];
        if (isdigit(c)) {
            postfix.push_back(c);
        } else if (c == '(') {
            st.push_back(c);
        } else if (isOp(c)) {
            while (!st.empty() && isOp(st.back()) && getPrecedence(st.back()) >= getPrecedence(c)) {
                postfix.push_back(st.back());
                st.pop_back();
            }
            st.push_back(c);
        } else if (c == ')') {
            while (!st.empty() && st.back() != '(') {
                postfix.push_back(st.back());
                st.pop_back();
            }
            if (!st.empty() && st.back() == '(') {
                st.pop_back();
            }
        }
    }

    for (size_t i = 0; i < postfix.size(); ++i) {
        if (i > 0) cout << " ";
