#include <vector>

using namespace std;

struct StackNode {
    char data;
    StackNode* nextPtr;
    StackNode(char val, StackNode* next = nullptr) : data(val), nextPtr(next) {}
};

typedef StackNode* StackNodePtr;

void push(StackNodePtr* topPtr, char value) {
    *topPtr = new StackNode(value, *topPtr);
}

char pop(StackNodePtr* topPtr) {
    if (*topPtr == nullptr) return '\0';
    StackNodePtr temp = *topPtr;
    char val = temp->data;
    *topPtr = (*topPtr)->nextPtr;
    delete temp;
    return val;
}

char stackTop(StackNodePtr topPtr) {
    return (topPtr != nullptr) ? topPtr->data : '\0';
}

int isEmpty(StackNodePtr topPtr) {
    return topPtr == nullptr;
}

int isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '^';
}

int precedenceValue(char op) {
    switch (op) {
        case '^': return 3;
        case '*': case '/': case '%': return 2;
        case '+': case '-': return 1;
        default: return 0;
    }
}

int precedence(char op1, char op2) {
    int p1 = precedenceValue(op1);
    int p2 = precedenceValue(op2);
    if (p1 < p2) return -1;
    if (p1 == p2) return 0;
    return 1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string raw;
    if (!getline(cin, raw)) return 0;

    string infix = "";
    for (char ch : raw) {
        if (ch != ' ' && ch != '\t' && ch != '\r' && ch != '\n') {
            infix += ch;
        }
    }

    StackNodePtr stackTopPtr = nullptr;
    push(&stackTopPtr, '(');
    infix += ')';

    vector<char> postfix;

    for (char c : infix) {
        if (isEmpty(stackTopPtr)) break;

        if (c >= '0' && c <= '9') {
            postfix.push_back(c);
        } else if (c == '(') {
            push(&stackTopPtr, '(');
        } else if (isOperator(c)) {
            while (!isEmpty(stackTopPtr) && isOperator(stackTop(stackTopPtr)) &&
                   precedence(stackTop(stackTopPtr), c) >= 0) {
                postfix.push_back(pop(&stackTopPtr));
            }
            push(&stackTopPtr, c);
        } else if (c == ')') {
            while (!isEmpty(stackTopPtr) && stackTop(stackTopPtr) != '(') {
                postfix.push_back(pop(&stackTopPtr));
            }
            if (!isEmpty(stackTopPtr) && stackTop(stackTopPtr) == '(') {
                pop(&stackTopPtr);
            }
        }
    }

    for (size_t i = 0; i < postfix.size(); ++i) {
        cout << (i == 0 ? "" : " ") << postfix[i];
    }
    cout << "\n";

    while (!isEmpty(stackTopPtr)) {
        pop(&stackTopPtr);
    }

    return 0;
}

