#include <iostream>
#include <vector>

using namespace std;

struct Node {
    long long data;
    Node* left = nullptr;
    Node* right = nullptr;
};

void insertIterative(Node*& root, long long val) {
    Node* newNode = new Node{val, nullptr, nullptr};
    if (root == nullptr) {
        root = newNode;
        return;
    }
    Node* curr = root;
    while (true) {
        if (val < curr->data) {
            if (curr->left == nullptr) {
                curr->left = newNode;
                break;
            } else {
                curr = curr->left;
            }
        } else {
            // val >= curr->data goes to right
            if (curr->right == nullptr) {
                curr->right = newNode;
                break;
            } else {
                curr = curr->right;
            }
        }
    }
}

void traversePre(Node* u) {
    if (!u) return;
    static bool first = true;
    if (!first) cout << " ";
    first = false;
    cout << u->data;
    traversePre(u->left);
    traversePre(u->right);
}

void traverseIn(Node* u) {
    if (!u) return;
    static bool first = true;
    traverseIn(u->left);
    if (!first) cout << " ";
    first = false;
    cout << u->data;
    traverseIn(u->right);
}

void traversePost(Node* u) {
    if (!u) return;
    static bool first = true;
    traversePost(u->left);
    traversePost(u->right);
    if (!first) cout << " ";
    first = false;
    cout << u->data;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    Node* root = nullptr;
    for (int i = 0; i < n; ++i) {
        long long val;
        cin >> val;
        insertIterative(root, val);
    }

    // Preorder
    vector<long long> preList;
    auto getPre = [&](auto& self, Node* cur) -> void {
        if (!cur) return;
        preList.push_back(cur->data);
        self(self, cur->left);
        self(self, cur->right);
    };
    getPre(getPre, root);
    for (size_t i = 0; i < preList.size(); ++i) {
        cout << preList[i] << (i + 1 == preList.size() ? "" : " ");
    }
    cout << "\n";

    // Inorder
    vector<long long> inList;
    auto getIn = [&](auto& self, Node* cur) -> void {
        if (!cur) return;
        self(self, cur->left);
        inList.push_back(cur->data);
        self(self, cur->right);
    };
    getIn(getIn, root);
    for (size_t i = 0; i < inList.size(); ++i) {
        cout << inList[i] << (i + 1 == inList.size() ? "" : " ");
    }
    cout << "\n";

    // Postorder
    vector<long long> postList;
    auto getPost = [&](auto& self, Node* cur) -> void {
        if (!cur) return;
        self(self, cur->left);
        self(self, cur->right);
        postList.push_back(cur->data);
    };
    getPost(getPost, root);
    for (size_t i = 0; i < postList.size(); ++i) {
        cout << postList[i] << (i + 1 == postList.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}

