int computeDepth(int u, const vector<Node>& tree) {
    if (u == 0) return 0;
    int dLeft = computeDepth(tree[u].left, tree);
    int dRight = computeDepth(tree[u].right, tree);
    return 1 + max(dLeft, dRight);
}

