#include <iostream>
#include <string>
#include <sstream>
#include <vector>

using namespace std;

struct Node {
    string data;
    Node* left = nullptr;
    Node* right = nullptr;
    Node(string d) : data(d), left(nullptr), right(nullptr) {}
};

void insertBST(Node*& root, const string& word) {
    if (!root) {
        root = new Node(word);
        return;
    }
    Node* curr = root;
    while (true) {
        if (word == curr->data) {
            return; // duplicate, skip
        } else if (word < curr->data) {
            if (curr->left == nullptr) {
                curr->left = new Node(word);
                return;
            }
            curr = curr->left;
        } else {
            if (curr->right == nullptr) {
                curr->right = new Node(word);
                return;
            }
            curr = curr->right;
        }
    }
}

void traverseInOrder(Node* u, vector<string>& out) {
    if (!u) return;
    traverseInOrder(u->left, out);
    out.push_back(u->data);
    traverseInOrder(u->right, out);
}

void traversePreOrder(Node* u, vector<string>& out) {
    if (!u) return;
    out.push_back(u->data);
    traversePreOrder(u->left, out);
    traversePreOrder(u->right, out);
}

void traversePostOrder(Node* u, vector<string>& out) {
    if (!u) return;
    traversePostOrder(u->left, out);
    traversePostOrder(u->right, out);
    out.push_back(u->data);
}

void display(const string& prefix, const vector<string>& items) {
    cout << prefix;
    for (size_t i = 0; i < items.size(); ++i) {
        cout << (i == 0 ? " " : " ") << items[i];
    }
    cout << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!getline(cin, s)) {
        cout << "In-order:\nPre-order:\nPost-order:\n";
        return 0;
    }

    stringstream ss(s);
    string token;
    Node* root = nullptr;
    while (ss >> token) {
        insertBST(root, token);
    }

    vector<string> in_list, pre_list, post_list;
    traverseInOrder(root, in_list);
    traversePreOrder(root, pre_list);
    traversePostOrder(root, post_list);

    display("In-order:", in_list);
    display("Pre-order:", pre_list);
    display("Post-order:", post_list);

    return 0;
