ListNode* searchListPtr(ListNode* node, int x) {
    if (!node) return nullptr;
    if (node->data == x) return node;
    return searchListPtr(node->next, x);
}

// Hàm tính vị trí của con trỏ target trong danh sách
int getIndex(ListNode* head, ListNode* target, int cur) {
    if (!head || !target) return -1;
    if (head == target) return cur;
    return getIndex(head->next, target, cur + 1);
}

