#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

struct Customer {
    int id;
    int arrival_time;
    int service_time;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int T, N;
    if (!(cin >> T >> N)) return 0;

    vector<Customer> customers(N);
    for (int i = 0; i < N; ++i) {
        customers[i].id = i + 1;
        cin >> customers[i].arrival_time >> customers[i].service_time;
    }

    int max_queue_len = 0;
    long long max_wait_time = 0;

    queue<Customer> q;
    int cust_idx = 0;
    bool busy = false;
    int finish_time = -1;

    for (int t = 1; t <= T; ++t) {
        // 1. Check if current service completes at time t
        if (busy && t == finish_time) {
            busy = false;
        }

        // 2. All customers arriving at time t are added to queue
        while (cust_idx < N && customers[cust_idx].arrival_time == t) {
            q.push(customers[cust_idx]);
            cust_idx++;
        }

        // Record max queue length at this point
        max_queue_len = max(max_queue_len, (int)q.size());

        // 3. If counter is free and queue is not empty, dequeue and start service
        if (!busy && !q.empty()) {
            Customer next_c = q.front();
            q.pop();
            busy = true;
            finish_time = t + next_c.service_time;
            long long wait_time = t - next_c.arrival_time;
            max_wait_time = max(max_wait_time, wait_time);
        }
    }

    cout << max_queue_len << " " << max_wait_time << "\n";

    return 0;
}

