        if (busy_until == -1 && !waiting_line.empty()) {
            Cust c = waiting_line.front();
            waiting_line.pop();
            int wait = minute - c.arr;
            if (wait > max_wait) {
                max_wait = wait;
            }
            busy_until = minute + c.serv;
        }
    }

    cout << max_q << " " << max_wait << "\n";
    return 0;
