using namespace std;

struct TreeNode {
    long long val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(long long v) : val(v), left(nullptr), right(nullptr) {}
};

TreeNode* insertBST(TreeNode* root, long long val) {
    if (!root) return new TreeNode(val);
    TreeNode* curr = root;
    while (true) {
        if (val == curr->val) {
            break;
        } else if (val < curr->val) {
            if (!curr->left) {
                curr->left = new TreeNode(val);
                break;
            } else {
                curr = curr->left;
            }
        } else {
            if (!curr->right) {
                curr->right = new TreeNode(val);
                break;
            } else {
                curr = curr->right;
            }
        }
    }
    return root;
}

pair<bool, int> binaryTreeSearch(TreeNode* root, long long key) {
    TreeNode* curr = root;
    int steps = 0;
    while (curr != nullptr) {
        steps++;
        if (curr->val == key) {
            return {true, steps};
        } else if (key < curr->val) {
            curr = curr->left;
        } else {
            curr = curr->right;
        }
    }
    return {false, steps};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    TreeNode* root = nullptr;
    for (int i = 0; i < n; ++i) {
        long long v;
        cin >> v;
        root = insertBST(root, v);
    }
    int q;
    if (cin >> q) {
        while (q--) {
            long long key;
            cin >> key;
            auto [found, steps] = binaryTreeSearch(root, key);
            if (found) {
                cout << "FOUND " << steps << "\n";
            } else {
                cout << "NOT FOUND " << steps << "\n";
            }
        }
    }
    return 0;
}

