#include <iostream>
#include <string>

class Account {
private:
    long long balance;
public:
    Account(long long initialBalance) {
        if (initialBalance >= 0) {
            balance = initialBalance;
        } else {
            balance = 0;
            std::cout << "Error: Initial balance was invalid.\n";
        }
    }

    void credit(long long amount) {
        balance += amount;
    }

    void debit(long long amount) {
        if (amount > balance) {
            std::cout << "Debit amount exceeded account balance.\n";
        } else {
            balance -= amount;
        }
    }

    long long getBalance() const {
        return balance;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    long long initBal;
    if (!(std::cin >> initBal)) return 0;

    Account acc(initBal);

    int q;
    if (!(std::cin >> q)) return 0;

    while (q--) {
        std::string op;
        std::cin >> op;
        if (op == "credit") {
            long long x;
            std::cin >> x;
            acc.credit(x);
        } else if (op == "debit") {
            long long x;
            std::cin >> x;
            acc.debit(x);
        } else if (op == "balance") {
            std::cout << acc.getBalance() << "\n";
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct BankAccount {
    long long curBalance = 0;

    BankAccount(long long initial) {
        if (initial < 0) {
            cout << "Error: Initial balance was invalid.\n";
            curBalance = 0;
        } else {
            curBalance = initial;
        }
    }

    void addMoney(long long val) {
        curBalance += val;
    }

    void withdrawMoney(long long val) {
        if (val > curBalance) {
            cout << "Debit amount exceeded account balance.\n";
        } else {
            curBalance -= val;
        }
    }

    long long queryBalance() const {
        return curBalance;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long b;
    if (cin >> b) {
        BankAccount account(b);
        int n;
        if (cin >> n) {
            for (int i = 0; i < n; ++i) {
                string cmd;
                cin >> cmd;
                if (cmd == "credit") {
                    long long amt;
                    cin >> amt;
                    account.addMoney(amt);
                } else if (cmd == "debit") {
                    long long amt;
                    cin >> amt;
                    account.withdrawMoney(amt);
                } else if (cmd == "balance") {
                    cout << account.queryBalance() << "\n";
                }
            }
        }
    }
    return 0;
}

#include <iostream>
