class Employee {
private:
    std::string firstName;
    std::string lastName;
    int monthlySalary;

public:
    Employee(const std::string& fName, const std::string& lName, int salary) {
        firstName = fName;
        lastName = lName;
        setMonthlySalary(salary);
    }

    void setFirstName(const std::string& fName) { firstName = fName; }
    std::string getFirstName() const { return firstName; }

    void setLastName(const std::string& lName) { lastName = lName; }
    std::string getLastName() const { return lastName; }

    void setMonthlySalary(int salary) {
        if (salary > 0) {
            monthlySalary = salary;
        } else {
            monthlySalary = 0;
        }
    }
    int getMonthlySalary() const { return monthlySalary; }

    int getYearlySalary() const {
        return monthlySalary * 12;
    }

    double getYearlySalaryWithRaise() const {
        return monthlySalary * 1.10 * 12.0;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) return 0;

    for (int i = 0; i < n; ++i) {
        std::string first, last;
        int salary;
        std::cin >> first >> last >> salary;
        Employee emp(first, last, salary);
        std::cout << emp.getFirstName() << " " << emp.getLastName() << ": "
                  << emp.getYearlySalary() << " -> "
                  << std::fixed << std::setprecision(2) << emp.getYearlySalaryWithRaise() << "\n";
    }

    return 0;
}

