struct EmployeeRecord {
    std::string first;
    std::string last;
    int salary;

    EmployeeRecord(std::string f, std::string l, int s) : first(std::move(f)), last(std::move(l)) {
        salary = (s > 0) ? s : 0;
    }

    long long yearly() const {
        return 1LL * salary * 12;
    }

    double raisedYearly() const {
        return yearly() * 1.10;
    }
};

