    int n;
    if (std::cin >> n) {
        while (n--) {
            std::string f, l;
            int s;
            std::cin >> f >> l >> s;
            EmployeeRecord emp(f, l, s);
            std::printf("%s %s: %lld -> %.2f\n", emp.first.c_str(), emp.last.c_str(), emp.yearly(), emp.raisedYearly());
        }
    }
    return 0;
}

