        partNumber = pNumber;
        partDescription = pDesc;
        setQuantity(qty);
        setPrice(prc);
    }

    void setPartNumber(string pNumber) { partNumber = pNumber; }
    string getPartNumber() const { return partNumber; }

    void setPartDescription(string pDesc) { partDescription = pDesc; }
    string getPartDescription() const { return partDescription; }

