    Invoice(const std::string& number, const std::string& desc, int qty, int price) 
        : partNumber(number), partDescription(desc) {
        setQuantity(qty);
        setPricePerItem(price);
    }

    void setQuantity(int qty) {
        if (qty > 0) quantity = qty;
        else quantity = 0;
    }

    void setPricePerItem(int price) {
        if (price > 0) pricePerItem = price;
        else pricePerItem = 0;
    }

    std::string getPartNumber() const { return partNumber; }
    int getQuantity() const { return quantity; }
    int getPricePerItem() const { return pricePerItem; }

    long long getInvoiceAmount() const {
        return static_cast<long long>(quantity) * pricePerItem;
    }
};

