class Time {
private:
    int hour;
    int minute;
    int second;

public:
    Time(int h = 0, int m = 0, int s = 0) : hour(h), minute(m), second(s) {}

    void tick() {
        second++;
        if (second >= 60) {
            second = 0;
            minute++;
            if (minute >= 60) {
                minute = 0;
                hour++;
                if (hour >= 24) {
                    hour = 0;
                }
            }
        }
    }

    void printStandard() const {
        int h = (hour == 0 || hour == 12) ? 12 : hour % 12;
        std::cout << h << ":"
                  << std::setfill('0') << std::setw(2) << minute << ":"
                  << std::setfill('0') << std::setw(2) << second << " "
                  << (hour < 12 ? "AM" : "PM") << "\n";
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int h, m, s, k;
    if (std::cin >> h >> m >> s >> k) {
        Time t(h, m, s);
        for (int i = 0; i < k; ++i) {
            t.tick();
            t.printStandard();
        }
    }
    return 0;
}

