struct ClockTime {
    int totalSeconds;

    ClockTime(int h, int m, int s) {
        totalSeconds = (h * 3600 + m * 60 + s) % 86400;
    }

    void tick() {
        totalSeconds = (totalSeconds + 1) % 86400;
    }

    void printStandard() const {
        int h = totalSeconds / 3600;
        int m = (totalSeconds % 3600) / 60;
        int s = totalSeconds % 60;
        int displayH = (h == 0 || h == 12) ? 12 : h % 12;
        const char* ampm = (h < 12) ? "AM" : "PM";
        std::printf("%d:%02d:%02d %s\n", displayH, m, s, ampm);
    }
};

