}

int getMonthDays(int mo, int yr) {
    const int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (mo < 1 || mo > 12) return 0;
    if (mo == 2 && checkLeap(yr)) return 29;
    return days[mo];
}

struct SimpleDate {
