        if (y < 1 || y > 9999) return false;
        if (m < 1 || m > 12) return false;
        return d >= 1 && d <= getMonthDays(m, y);
    }

    void advance() {
        d++;
        if (d > getMonthDays(m, y)) {
            d = 1;
            m++;
            if (m > 12) {
                m = 1;
                y++;
            }
        }
