#include <iostream>
#include <numeric>
#include <iomanip>

class Rational {
private:
    long long num;
    long long den;

    void reduce() {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        if (num == 0) {
            den = 1;
            return;
        }
        long long g = std::gcd(std::abs(num), den);
        num /= g;
        den /= g;
    }

public:
    Rational(long long n = 0, long long d = 1) : num(n), den(d) {
        reduce();
    }

    Rational add(const Rational& other) const {
        return Rational(num * other.den + other.num * den, den * other.den);
    }

    Rational subtract(const Rational& other) const {
        return Rational(num * other.den - other.num * den, den * other.den);
    }

    Rational multiply(const Rational& other) const {
        return Rational(num * other.num, den * other.den);
    }

    Rational divide(const Rational& other) const {
        return Rational(num * other.den, den * other.num);
    }

    bool isZero() const {
        return num == 0;
    }

    void printFraction() const {
        std::cout << num << "/" << den << "\n";
    }

    void printFloat() const {
        double val = static_cast<double>(num) / static_cast<double>(den);
        std::cout << std::fixed << std::setprecision(6) << val << "\n";
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    long long a1, b1, a2, b2;
    if (std::cin >> a1 >> b1 >> a2 >> b2) {
        Rational r1(a1, b1);
        Rational r2(a2, b2);

        Rational sum = r1.add(r2);
        sum.printFraction();
        sum.printFloat();

        Rational diff = r1.subtract(r2);
        diff.printFraction();
        diff.printFloat();

        Rational prod = r1.multiply(r2);
        prod.printFraction();
        prod.printFloat();

        if (r2.isZero()) {
            std::cout << "DIV_BY_ZERO\n";
        } else {
            Rational quot = r1.divide(r2);
            quot.printFraction();
            quot.printFloat();
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>

long long calcGcd(long long a, long long b) {
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    while (b) {
        a %= b;
        long long tmp = a;
        a = b;
        b = tmp;
    }
    return a;
}

struct RationalNumber {
    long long numerator;
    long long denominator;

    RationalNumber(long long n = 0, long long d = 1) {
        if (d < 0) {
            n = -n;
            d = -d;
        }
        if (n == 0) {
            d = 1;
        } else {
            long long g = calcGcd(n, d);
            n /= g;
            d /= g;
        }
        numerator = n;
        denominator = d;
    }

    RationalNumber operator+(const RationalNumber& o) const {
        return RationalNumber(numerator * o.denominator + o.numerator * denominator, denominator * o.denominator);
    }

    RationalNumber operator-(const RationalNumber& o) const {
        return RationalNumber(numerator * o.denominator - o.numerator * denominator, denominator * o.denominator);
    }

    RationalNumber operator*(const RationalNumber& o) const {
        return RationalNumber(numerator * o.numerator, denominator * o.denominator);
    }

    RationalNumber operator/(const RationalNumber& o) const {
        return RationalNumber(numerator * o.denominator, denominator * o.numerator);
    }
};

void display(const RationalNumber& r) {
    std::cout << r.numerator << "/" << r.denominator << "\n";
    std::cout << std::fixed << std::setprecision(6) << ((double)r.numerator / (double)r.denominator) << "\n";
}

int main() {
    long long a1, b1, a2, b2;
    if (std::cin >> a1 >> b1 >> a2 >> b2) {
        RationalNumber r1(a1, b1);
        RationalNumber r2(a2, b2);

        display(r1 + r2);
        display(r1 - r2);
        display(r1 * r2);

        if (r2.numerator == 0) {
            std::cout << "DIV_BY_ZERO\n";
        } else {
            display(r1 / r2);
        }
    }
    return 0;
}

