}

int daysInMonth(int m, int y) {
    switch (m) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12: return 31;
        case 4: case 6: case 9: case 11: return 30;
        case 2: return isLeapYear(y) ? 29 : 28;
        default: return 30;
    }
}

class DateAndTime {
private:
    int year, month, day;
    int hour, minute, second;

public:
    DateAndTime(int y, int m, int d, int hr, int min, int sec)
        : year(y), month(m), day(d), hour(hr), minute(min), second(sec) {}

    void nextDay() {
        day++;
        if (day > daysInMonth(month, year)) {
            day = 1;
            month++;
            if (month > 12) {
                month = 1;
                year++;
            }
        }
    }

    void tick() {
        second++;
        if (second == 60) {
            second = 0;
            minute++;
            if (minute == 60) {
                minute = 0;
                hour++;
                if (hour == 24) {
                    hour = 0;
                    nextDay();
                }
            }
        }
    }

    void advance(long long k) {
        long long totalSec = hour * 3600LL + minute * 60LL + second + k;
        long long daysToAdd = totalSec / 86400LL;
        int remSec = totalSec % 86400LL;

        hour = remSec / 3600;
        minute = (remSec % 3600) / 60;
        second = remSec % 60;

        while (daysToAdd > 0) {
            int dim = daysInMonth(month, year);
            int remainingInMonth = dim - day + 1;
            if (daysToAdd >= remainingInMonth) {
                daysToAdd -= remainingInMonth;
                day = 1;
                month++;
                if (month > 12) {
                    month = 1;
                    year++;
                }
            } else {
                day += daysToAdd;
                daysToAdd = 0;
            }
        }
    }

    void printUniversal() const {
        cout << setfill('0')
             << setw(4) << year << "-"
             << setw(2) << month << "-"
             << setw(2) << day << " "
             << setw(2) << hour << ":"
             << setw(2) << minute << ":"
             << setw(2) << second << "\n";
    }

    void printStandard() const {
        int stdHour = (hour == 0 || hour == 12) ? 12 : hour % 12;
        string period = (hour < 12) ? "AM" : "PM";
        cout << setfill('0')
             << setw(4) << year << "-"
             << setw(2) << month << "-"
             << setw(2) << day << " "
             << setw(2) << stdHour << ":"
             << setw(2) << minute << ":"
             << setw(2) << second << " " << period << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int y, m, d, hr, mn, sc;
    long long k;
    if (cin >> y >> m >> d >> hr >> mn >> sc >> k) {
        DateAndTime dt(y, m, d, hr, mn, sc);
        dt.advance(k);
        dt.printUniversal();
        dt.printStandard();
    }
    return 0;
}

#include <cstdio>

static const int DAYS_PER_MONTH[2][13] = {
    {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31},
    {0, 31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
};

inline bool leap(int y) {
    return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
}

struct DateTime {
    int year, month, day;
    int hour, min, sec;

    void addDays(long long d) {
        while (d > 0) {
            int isL = leap(year) ? 1 : 0;
            int inMonth = DAYS_PER_MONTH[isL][month] - day + 1;
            if (d >= inMonth) {
                d -= inMonth;
                day = 1;
                month++;
                if (month > 12) {
                    month = 1;
                    year++;
                }
            } else {
                day += (int)d;
                d = 0;
            }
        }
    }

    void addSeconds(long long s) {
        long long currentSec = hour * 3600LL + min * 60LL + sec + s;
        long long d = currentSec / 86400LL;
        long long rem = currentSec % 86400LL;
        hour = rem / 3600;
        min = (rem % 3600) / 60;
        sec = rem % 60;
        addDays(d);
    }
};

int main() {
    int y, m, d, h, mn, s;
    long long k;
    if (scanf("%d %d %d %d %d %d %lld", &y, &m, &d, &h, &mn, &s, &k) == 7) {
        DateTime dt{y, m, d, h, mn, s};
        dt.addSeconds(k);

        // Print Universal
        printf("%04d-%02d-%02d %02d:%02d:%02d\n", dt.year, dt.month, dt.day, dt.hour, dt.min, dt.sec);

        // Print Standard
        int stdH = (dt.hour == 0 || dt.hour == 12) ? 12 : (dt.hour % 12);
        const char* ampm = (dt.hour < 12) ? "AM" : "PM";
        printf("%04d-%02d-%02d %02d:%02d:%02d %s\n", dt.year, dt.month, dt.day, stdH, dt.min, dt.sec, ampm);
    }
    return 0;
}

