#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>

using namespace std;

const double EPS = 1e-6;

struct Point {
    double x, y;
};

double distSq(Point a, Point b) {
    return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
}

void solve() {
    Point p[4];
    bool inRange = true;
    for (int i = 0; i < 4; ++i) {
        cin >> p[i].x >> p[i].y;
        if (p[i].x < -EPS || p[i].x > 20.0 + EPS || p[i].y < -EPS || p[i].y > 20.0 + EPS) {
            inRange = false;
        }
    }

    if (!inRange) {
        cout << "INVALID\n";
        return;
    }

    // Find pairwise distances between p[0] and p[1], p[2], p[3]
    int perm[4] = {0, 1, 2, 3};
    bool found = false;
    double side1 = 0, side2 = 0;

    // A rectangle ABCD has AB^2 + BC^2 = AC^2 and AD = BC, AB = CD, AC = BD
    // Check all permutations of 4 vertices
    sort(perm, perm + 4);
    do {
        Point A = p[perm[0]];
        Point B = p[perm[1]];
        Point C = p[perm[2]];
        Point D = p[perm[3]];

        double dAB = distSq(A, B);
        double dBC = distSq(B, C);
        double dCD = distSq(C, D);
        double dDA = distSq(D, A);
        double dAC = distSq(A, C);
        double dBD = distSq(B, D);

        if (dAB > EPS && dBC > EPS &&
            fabs(dAB - dCD) < EPS && fabs(dBC - dDA) < EPS &&
            fabs(dAB + dBC - dAC) < EPS && fabs(dAC - dBD) < EPS) {
            side1 = sqrt(dAB);
            side2 = sqrt(dBC);
            found = true;
            break;
        }
    } while (next_permutation(perm, perm + 4));

    if (!found) {
        cout << "INVALID\n";
        return;
    }

    double len = max(side1, side2);
    double wid = min(side1, side2);
    double perim = 2.0 * (len + wid);
    double area = len * wid;
    bool isSquare = fabs(len - wid) < 1e-5;

    cout << fixed << setprecision(2) 
         << len << " " << wid << " " << perim << " " << area << " " 
         << (isSquare ? "YES" : "NO") << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (cin >> T) {
        while (T--) {
            solve();
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Pt {
    double x, y;
};

double dist(Pt a, Pt b) {
    return hypot(a.x - b.x, a.y - b.y);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        vector<Pt> pts(4);
        bool validCoords = true;
        for (int i = 0; i < 4; ++i) {
            cin >> pts[i].x >> pts[i].y;
            if (pts[i].x < 0.0 - 1e-7 || pts[i].x > 20.0 + 1e-7 ||
                pts[i].y < 0.0 - 1e-7 || pts[i].y > 20.0 + 1e-7) {
                validCoords = false;
            }
        }

        if (!validCoords) {
            cout << "INVALID\n";
            continue;
        }

        // Compute center of mass
        Pt center = {0, 0};
        for (auto& p : pts) {
            center.x += p.x / 4.0;
            center.y += p.y / 4.0;
        }

        // Sort points by polar angle with respect to center
        sort(pts.begin(), pts.end(), [&](const Pt& a, const Pt& b) {
            return atan2(a.y - center.y, a.x - center.x) < atan2(b.y - center.y, b.x - center.x);
        });

        // Check distances to center
        double d0 = dist(pts[0], center);
        double d1 = dist(pts[1], center);
        double d2 = dist(pts[2], center);
        double d3 = dist(pts[3], center);

        double edge0 = dist(pts[0], pts[1]);
        double edge1 = dist(pts[1], pts[2]);
        double edge2 = dist(pts[2], pts[3]);
        double edge3 = dist(pts[3], pts[0]);
        double diag0 = dist(pts[0], pts[2]);
        double diag1 = dist(pts[1], pts[3]);

        bool isRect = true;
        if (edge0 < 1e-6 || edge1 < 1e-6) isRect = false;
        if (abs(edge0 - edge2) > 1e-6 || abs(edge1 - edge3) > 1e-6) isRect = false;
        if (abs(diag0 - diag1) > 1e-6) isRect = false;
        if (abs(edge0 * edge0 + edge1 * edge1 - diag0 * diag0) > 1e-5) isRect = false;

        if (!isRect) {
            cout << "INVALID\n";
        } else {
            double length = max(edge0, edge1);
            double width = min(edge0, edge1);
            double perimeter = 2.0 * (length + width);
            double area = length * width;
            string sq = (abs(length - width) < 1e-5) ? "YES" : "NO";
            cout << fixed << setprecision(2) 
                 << length << " " << width << " " << perimeter << " " << area << " " << sq << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class TicTacToe {
private:
    int board[3][3];
    int currentPlayer;
    int moveCount;
    bool gameOver;

    bool checkWin(int player) {
        for (int i = 0; i < 3; ++i) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;
        return false;
    }

public:
    TicTacToe() {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                board[i][j] = 0;
        currentPlayer = 1;
        moveCount = 0;
        gameOver = false;
    }

    bool isGameOver() const {
        return gameOver;
    }

    void makeMove(int r, int c) {
        if (gameOver) return;
        if (r < 1 || r > 3 || c < 1 || c > 3 || board[r - 1][c - 1] != 0) {
            cout << "INVALID\n";
            return;
        }

        board[r - 1][c - 1] = currentPlayer;
        moveCount++;

        if (checkWin(currentPlayer)) {
            gameOver = true;
            if (currentPlayer == 1) cout << "PLAYER 1 WINS\n";
            else cout << "PLAYER 2 WINS\n";
        } else if (moveCount == 9) {
            gameOver = true;
            cout << "DRAW\n";
        } else {
            cout << "CONTINUE\n";
            currentPlayer = (currentPlayer == 1 ? 2 : 1);
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    TicTacToe game;
    int r, c;
    while (cin >> r >> c) {
        if (game.isGameOver()) break;
        game.makeMove(r, c);
    }
    return 0;
}

#include <iostream>

class TicTacToeBoard {
    int grid[3][3] = {};
    int turn = 1;
    int validMoves = 0;
    bool finished = false;

    bool hasWon(int p) const {
        for (int i = 0; i < 3; ++i) {
            if (grid[i][0] == p && grid[i][1] == p && grid[i][2] == p) return true;
            if (grid[0][i] == p && grid[1][i] == p && grid[2][i] == p) return true;
        }
        if (grid[0][0] == p && grid[1][1] == p && grid[2][2] == p) return true;
        if (grid[0][2] == p && grid[1][1] == p && grid[2][0] == p) return true;
        return false;
    }

public:
    bool isFinished() const { return finished; }

    void process(int row, int col) {
        if (finished) return;
        if (row < 1 || row > 3 || col < 1 || col > 3 || grid[row - 1][col - 1] != 0) {
            std::cout << "INVALID\n";
            return;
        }
        grid[row - 1][col - 1] = turn;
        validMoves++;
        if (hasWon(turn)) {
            finished = true;
            std::cout << "PLAYER " << turn << " WINS\n";
        } else if (validMoves == 9) {
            finished = true;
            std::cout << "DRAW\n";
        } else {
            std::cout << "CONTINUE\n";
            turn = 3 - turn;
        }
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    TicTacToeBoard game;
    int r, c;
    while (std::cin >> r >> c) {
        if (game.isFinished()) break;
        game.process(r, c);
    }
    return 0;
}

