#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <iomanip>

using namespace std;

const vector<string> MONTH_NAMES = {
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
};

bool isLeapYear(int y) {
    return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
}

int daysInMonth(int m, int y) {
    static const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (m == 2 && isLeapYear(y)) return 29;
    return days[m - 1];
}

struct Date {
    int day;
    int month;
    int year;

    int dayOfYear() const {
        int d = 0;
        for (int m = 1; m < month; ++m) {
            d += daysInMonth(m, year);
        }
        return d + day;
    }
};

Date parseDate(const string& line) {
    Date dt;
    if (line.find('/') != string::npos) {
        // Format 2: MM/DD/YY
        int m = stoi(line.substr(0, 2));
        int d = stoi(line.substr(3, 2));
        int y2 = stoi(line.substr(6, 2));
        int y = (y2 >= 50) ? (1900 + y2) : (2000 + y2);
        dt = {d, m, y};
    } else if (line.find(',') != string::npos) {
        // Format 3: Month DD, YYYY
        stringstream ss(line);
        string mName, dStr, yStr;
        ss >> mName >> dStr >> yStr;
        if (!dStr.empty() && dStr.back() == ',') dStr.pop_back();
        int m = 1;
        for (int i = 0; i < 12; ++i) {
            if (MONTH_NAMES[i] == mName) {
                m = i + 1;
                break;
            }
        }
        int d = stoi(dStr);
        int y = stoi(yStr);
        dt = {d, m, y};
    } else {
        // Format 1: DDD YYYY
        stringstream ss(line);
        int ddd, y;
        ss >> ddd >> y;
        int m = 1;
        while (m <= 12) {
            int dim = daysInMonth(m, y);
            if (ddd <= dim) break;
            ddd -= dim;
            m++;
        }
        dt = {ddd, m, y};
    }
    return dt;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (!(cin >> T)) return 0;
    string dummy;
    getline(cin, dummy);
    while (T--) {
        string line;
        if (!getline(cin, line)) break;
        if (line.empty()) {
            T++;
            continue;
        }
        Date dt = parseDate(line);

        // Format 1: DDD YYYY
        cout << setfill('0') << setw(3) << dt.dayOfYear() << " " << setw(4) << dt.year << "\n";

        // Format 2: MM/DD/YY
        cout << setfill('0') << setw(2) << dt.month << "/" 
             << setfill('0') << setw(2) << dt.day << "/"
             << setfill('0') << setw(2) << (dt.year % 100) << "\n";

        // Format 3: Month DD, YYYY
        cout << MONTH_NAMES[dt.month - 1] << " "
             << setfill('0') << setw(2) << dt.day << ", "
             << setw(4) << dt.year << "\n";
    }
    return 0;
}

#include <cstdio>
#include <iostream>
#include <string>
#include <vector>

using namespace std;

class MyDate {
private:
    int d, m, y;

    static bool leap(int yr) {
        return (yr % 400 == 0) || (yr % 4 == 0 && yr % 100 != 0);
    }

    static int mdays(int mo, int yr) {
        const int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (mo == 2 && leap(yr)) return 29;
        return days[mo];
    }

public:
    MyDate(int day, int month, int year) : d(day), m(month), y(year) {}

    static MyDate fromDddYyyy(int ddd, int year) {
        int month = 1;
        while (month <= 12) {
            int cur = mdays(month, year);
            if (ddd <= cur) break;
            ddd -= cur;
            month++;
        }
        return MyDate(ddd, month, year);
    }

    static MyDate fromMmDdYy(int month, int day, int yy) {
        int year = (yy >= 50) ? (1900 + yy) : (2000 + yy);
        return MyDate(day, month, year);
    }

    int getDayOfYear() const {
        int res = 0;
        for (int i = 1; i < m; ++i) res += mdays(i, y);
        return res + d;
    }

    void printFormats() const {
        static const char* const mnames[] = {
            "", "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        printf("%03d %04d\n", getDayOfYear(), y);
        printf("%02d/%02d/%02d\n", m, d, y % 100);
        printf("%s %02d, %04d\n", mnames[m], d, y);
    }
};

int main() {
    int T;
    if (scanf("%d\n", &T) != 1) return 0;
    char line[256];
    while (T--) {
        if (!fgets(line, sizeof(line), stdin)) break;
        string s(line);
        while (!s.empty() && (s.back() == '\r' || s.back() == '\n')) s.pop_back();
        if (s.empty()) { T++; continue; }

        if (s.find('/') != string::npos) {
            int mm, dd, yy;
            sscanf(s.c_str(), "%d/%d/%d", &mm, &dd, &yy);
            MyDate dt = MyDate::fromMmDdYy(mm, dd, yy);
            dt.printFormats();
        } else if (s.find(',') != string::npos) {
            char monthStr[32];
            int dd, yyyy;
            sscanf(s.c_str(), "%s %d, %d", monthStr, &dd, &yyyy);
            static const string names[] = {
                "January", "February", "March", "April", "May", "June",
                "July", "August", "September", "October", "November", "December"
            };
            int mm = 1;
            for (int i = 0; i < 12; ++i) {
                if (names[i] == monthStr) {
                    mm = i + 1;
                    break;
                }
            }
            MyDate dt(dd, mm, yyyy);
            dt.printFormats();
        } else {
            int ddd, yyyy;
            sscanf(s.c_str(), "%d %d", &ddd, &yyyy);
            MyDate dt = MyDate::fromDddYyyy(ddd, yyyy);
            dt.printFormats();
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

class HugeInteger {
private:
    vector<int> digits; // digits in reverse order (0-indexed: least significant)

    void trim() {
        while (digits.size() > 1 && digits.back() == 0) {
            digits.pop_back();
        }
    }

public:
    HugeInteger() {
        digits.push_back(0);
    }

    void input(const string& s) {
        digits.clear();
        for (int i = (int)s.length() - 1; i >= 0; --i) {
            if (isdigit(s[i])) {
                digits.push_back(s[i] - '0');
            }
        }
        if (digits.empty()) {
            digits.push_back(0);
        }
        trim();
    }

    string toString() const {
        string s = "";
        for (int i = (int)digits.size() - 1; i >= 0; --i) {
            s += to_string(digits[i]);
        }
        return s;
    }

    bool isZero() const {
        return digits.size() == 1 && digits[0] == 0;
    }

    bool isEqualTo(const HugeInteger& other) const {
        return digits == other.digits;
    }

    bool isLessThan(const HugeInteger& other) const {
        if (digits.size() != other.digits.size()) {
            return digits.size() < other.digits.size();
        }
        for (int i = (int)digits.size() - 1; i >= 0; --i) {
            if (digits[i] != other.digits[i]) {
                return digits[i] < other.digits[i];
            }
        }
        return false;
    }

    bool isGreaterThan(const HugeInteger& other) const {
        return other.isLessThan(*this);
    }

    HugeInteger add(const HugeInteger& other) const {
        HugeInteger res;
        res.digits.clear();
        int carry = 0;
        size_t n = max(digits.size(), other.digits.size());
        for (size_t i = 0; i < n || carry; ++i) {
            int sum = carry;
            if (i < digits.size()) sum += digits[i];
            if (i < other.digits.size()) sum += other.digits[i];
            res.digits.push_back(sum % 10);
            carry = sum / 10;
        }
        res.trim();
        return res;
    }

    // Assume *this >= other
    HugeInteger subtract(const HugeInteger& other) const {
        HugeInteger res;
        res.digits.clear();
        int borrow = 0;
        for (size_t i = 0; i < digits.size(); ++i) {
            int sub = digits[i] - borrow;
            if (i < other.digits.size()) sub -= other.digits[i];
            if (sub < 0) {
                sub += 10;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.digits.push_back(sub);
        }
        res.trim();
        return res;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string sA, sB;
    if (!(cin >> sA >> sB)) return 0;

    HugeInteger A, B;
    A.input(sA);
    B.input(sB);

    HugeInteger sum = A.add(B);
    cout << sum.toString() << "\n";

    HugeInteger diff;
    if (A.isGreaterThan(B) || A.isEqualTo(B)) {
        diff = A.subtract(B);
    } else {
        diff = B.subtract(A);
    }
    cout << diff.toString() << "\n";

    if (A.isEqualTo(B)) {
        cout << "=\n";
    } else if (A.isLessThan(B)) {
        cout << "<\n";
    } else {
        cout << ">\n";
    }

    cout << (A.isZero() ? "ZERO" : "NON_ZERO") << " "
         << (B.isZero() ? "ZERO" : "NON_ZERO") << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

class HugeInteger {
private:
    int d[50];
    int len;

public:
    HugeInteger() {
        for (int i = 0; i < 50; ++i) d[i] = 0;
        len = 1;
    }

    void load(string s) {
        for (int i = 0; i < 50; ++i) d[i] = 0;
        // strip leading spaces
        int start = 0;
        while (start + 1 < (int)s.size() && s[start] == '0') start++;
        s = s.substr(start);
        len = (int)s.size();
        for (int i = 0; i < len; ++i) {
            d[i] = s[len - 1 - i] - '0';
        }
    }

    void print() const {
        for (int i = len - 1; i >= 0; --i) {
            cout << d[i];
        }
        cout << "\n";
    }

    bool isZero() const {
        return len == 1 && d[0] == 0;
    }

    int compare(const HugeInteger& o) const {
        if (len != o.len) return len < o.len ? -1 : 1;
        for (int i = len - 1; i >= 0; --i) {
            if (d[i] != o.d[i]) {
                return d[i] < o.d[i] ? -1 : 1;
            }
        }
        return 0;
    }

    HugeInteger plus(const HugeInteger& o) const {
        HugeInteger res;
        int carry = 0;
        int maxL = max(len, o.len);
        for (int i = 0; i < maxL || carry; ++i) {
            int v = carry + (i < len ? d[i] : 0) + (i < o.len ? o.d[i] : 0);
            res.d[i] = v % 10;
            carry = v / 10;
            res.len = i + 1;
        }
        return res;
    }

    HugeInteger minus(const HugeInteger& o) const {
        HugeInteger res;
        int borrow = 0;
        for (int i = 0; i < len; ++i) {
            int cur = d[i] - borrow - (i < o.len ? o.d[i] : 0);
            if (cur < 0) {
                cur += 10;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.d[i] = cur;
        }
        res.len = len;
        while (res.len > 1 && res.d[res.len - 1] == 0) {
            res.len--;
        }
        return res;
    }
};

int main() {
    string a, b;
    if (!(cin >> a >> b)) return 0;
    HugeInteger A, B;
    A.load(a);
    B.load(b);

    HugeInteger sum = A.plus(B);
    sum.print();

    int cmp = A.compare(B);
    HugeInteger diff;
    if (cmp >= 0) {
        diff = A.minus(B);
    } else {
        diff = B.minus(A);
    }
    diff.print();

    if (cmp == 0) cout << "=\n";
    else if (cmp < 0) cout << "<\n";
    else cout << ">\n";

    cout << (A.isZero() ? "ZERO" : "NON_ZERO") << " "
         << (B.isZero() ? "ZERO" : "NON_ZERO") << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <iomanip>

using namespace std;

class Time {
private:
    int totalSeconds;

public:
    Time() : totalSeconds(0) {}

    void setTime(int h, int m, int s) {
        totalSeconds = (h * 3600 + m * 60 + s) % 86400;
    }

    void addSeconds(long long x) {
        totalSeconds = (int)((totalSeconds + (x % 86400)) % 86400);
    }

    int getHour() const {
        return totalSeconds / 3600;
    }

    int getMinute() const {
        return (totalSeconds % 3600) / 60;
    }

    int getSecond() const {
        return totalSeconds % 60;
    }

    void printUniversal() const {
        int h = getHour();
        int m = getMinute();
        int s = getSecond();
        cout << setfill('0') << setw(2) << h << ":"
             << setw(2) << m << ":"
             << setw(2) << s << "\n";
    }

    void printStandard() const {
        int h = getHour();
        int m = getMinute();
        int s = getSecond();
        int displayHour = (h == 0 || h == 12) ? 12 : h % 12;
        string period = (h < 12) ? "AM" : "PM";
        cout << displayHour << ":"
             << setfill('0') << setw(2) << m << ":"
             << setw(2) << s << " " << period << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int q;
    if (!(cin >> q)) return 0;

    Time t;
    while (q--) {
        string cmd;
        cin >> cmd;
        if (cmd == "SET") {
            int h, m, s;
            cin >> h >> m >> s;
            t.setTime(h, m, s);
        } else if (cmd == "ADD_SEC") {
            long long x;
            cin >> x;
            t.addSeconds(x);
        } else if (cmd == "PRINT_24") {
            t.printUniversal();
        } else if (cmd == "PRINT_12") {
            t.printStandard();
        }
    }
    return 0;
}

#include <cstdio>
#include <cstring>

class ClockTimer {
    int secFromMidnight;
public:
    ClockTimer() {
        secFromMidnight = 0;
    }

    void set(int h, int m, int s) {
        secFromMidnight = h * 3600 + m * 60 + s;
    }

    void advance(long long extra) {
        long long cur = secFromMidnight + extra;
        secFromMidnight = (int)(cur % 86400);
    }

    void show24() const {
        int h = secFromMidnight / 3600;
        int rem = secFromMidnight % 3600;
        int m = rem / 60;
        int s = rem % 60;
        printf("%02d:%02d:%02d\n", h, m, s);
    }

    void show12() const {
        int h = secFromMidnight / 3600;
        int rem = secFromMidnight % 3600;
        int m = rem / 60;
        int s = rem % 60;

        int h12 = h % 12;
        if (h12 == 0) h12 = 12;
        const char* ampm = (h < 12) ? "AM" : "PM";
        printf("%d:%02d:%02d %s\n", h12, m, s, ampm);
    }
};

int main() {
    int Q;
    if (scanf("%d", &Q) != 1) return 0;

    ClockTimer timer;
    char op[32];
    for (int i = 0; i < Q; ++i) {
        scanf("%s", op);
        if (strcmp(op, "SET") == 0) {
            int h, m, s;
            scanf("%d %d %d", &h, &m, &s);
            timer.set(h, m, s);
        } else if (strcmp(op, "ADD_SEC") == 0) {
            long long x;
            scanf("%lld", &x);
            timer.advance(x);
        } else if (strcmp(op, "PRINT_24") == 0) {
            timer.show24();
        } else if (strcmp(op, "PRINT_12") == 0) {
            timer.show12();
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

int rankToVal(const string& r) {
    if (r == "2") return 2;
    if (r == "3") return 3;
    if (r == "4") return 4;
    if (r == "5") return 5;
    if (r == "6") return 6;
    if (r == "7") return 7;
    if (r == "8") return 8;
    if (r == "9") return 9;
    if (r == "10") return 10;
    if (r == "J") return 11;
    if (r == "Q") return 12;
    if (r == "K") return 13;
    if (r == "A") return 14;
    return 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<int> ranks;
    vector<char> suits;
    map<int, int> countMap;

    for (int i = 0; i < 5; ++i) {
        string s;
        if (!(cin >> s)) return 0;
        char suit = s.back();
        string r = s.substr(0, s.size() - 1);
        int val = rankToVal(r);
        ranks.push_back(val);
        suits.push_back(suit);
        countMap[val]++;
    }

    vector<int> counts;
    for (auto const& [val, count] : countMap) {
        counts.push_back(count);
    }
    sort(counts.rbegin(), counts.rend());

    bool pair = (counts.size() == 4 && counts[0] == 2);
    bool twoPairs = (counts.size() == 3 && counts[0] == 2 && counts[1] == 2);
    bool threeKind = (counts.size() == 3 && counts[0] == 3);
    bool fourKind = (counts.size() == 2 && counts[0] == 4);

    bool flush = true;
    for (int i = 1; i < 5; ++i) {
        if (suits[i] != suits[0]) {
            flush = false;
            break;
        }
    }

    vector<int> sortedRanks = ranks;
    sort(sortedRanks.begin(), sortedRanks.end());

    bool straight = false;
    if (counts.size() == 5) {
        if (sortedRanks[4] - sortedRanks[0] == 4) {
            straight = true;
        } else if (sortedRanks[0] == 2 && sortedRanks[1] == 3 && sortedRanks[2] == 4 && sortedRanks[3] == 5 && sortedRanks[4] == 14) {
            straight = true;
        }
    }

    cout << (pair ? "Yes" : "No") << "\n";
    cout << (twoPairs ? "Yes" : "No") << "\n";
    cout << (threeKind ? "Yes" : "No") << "\n";
    cout << (fourKind ? "Yes" : "No") << "\n";
    cout << (flush ? "Yes" : "No") << "\n";
    cout << (straight ? "Yes" : "No") << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Card {
    int rank;
    char suit;
};

int parseRank(const string& s) {
    string r = s.substr(0, s.length() - 1);
    if (r == "A") return 14;
    if (r == "K") return 13;
    if (r == "Q") return 12;
    if (r == "J") return 11;
    return stoi(r);
}

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);
    vector<Card> hand(5);
    for (int i = 0; i < 5; ++i) {
        string token;
        if (!(cin >> token)) return 0;
        hand[i].suit = token.back();
        hand[i].rank = parseRank(token);
    }

    int rankFreq[15] = {0};
    for (const auto& c : hand) {
        rankFreq[c.rank]++;
    }

    int pairCount = 0;
    int threeCount = 0;
    int fourCount = 0;
    for (int r = 2; r <= 14; ++r) {
        if (rankFreq[r] == 2) pairCount++;
        else if (rankFreq[r] == 3) threeCount++;
        else if (rankFreq[r] == 4) fourCount++;
    }

    bool isFlush = true;
    for (int i = 1; i < 5; ++i) {
        if (hand[i].suit != hand[0].suit) {
            isFlush = false;
            break;
        }
    }

    vector<int> sortedVals;
    for (const auto& c : hand) sortedVals.push_back(c.rank);
    sort(sortedVals.begin(), sortedVals.end());

    bool isStraight = false;
    bool uniqueFive = true;
    for (int i = 0; i < 4; ++i) {
        if (sortedVals[i] == sortedVals[i+1]) uniqueFive = false;
    }
    if (uniqueFive) {
        if (sortedVals[4] - sortedVals[0] == 4) {
            isStraight = true;
        } else if (sortedVals == vector<int>{2, 3, 4, 5, 14}) {
            isStraight = true;
        }
    }

    cout << (pairCount == 1 && threeCount == 0 ? "Yes" : "No") << "\n";
    cout << (pairCount == 2 ? "Yes" : "No") << "\n";
    cout << (threeCount == 1 && pairCount == 0 ? "Yes" : "No") << "\n";
    cout << (fourCount == 1 ? "Yes" : "No") << "\n";
    cout << (isFlush ? "Yes" : "No") << "\n";
    cout << (isStraight ? "Yes" : "No") << "\n";

    return 0;
}

#include <iostream>
