class TimeKeeper {
    int secFromMidnight;
public:
    TimeKeeper() : secFromMidnight(0) {}

    void set(int h, int m, int s) {
        secFromMidnight = h * 3600 + m * 60 + s;
    }

    void advance(long long k) {
        secFromMidnight = (int)((secFromMidnight + (k % 86400)) % 86400);
    }

    void output24() const {
        int h = secFromMidnight / 3600;
        int m = (secFromMidnight / 60) % 60;
        int s = secFromMidnight % 60;
        printf("%02d:%02d:%02d\n", h, m, s);
    }

    void output12() const {
        int h = secFromMidnight / 3600;
        int m = (secFromMidnight / 60) % 60;
        int s = secFromMidnight % 60;
        int displayHour = (h == 0) ? 12 : (h > 12 ? h - 12 : h);
        const char* ampm = (h < 12) ? "AM" : "PM";
        printf("%d:%02d:%02d %s\n", displayHour, m, s, ampm);
    }
};

