            tk.set(h, m, s);
        } else if (strcmp(cmd, "TICK") == 0) {
            long long k;
            scanf("%lld", &k);
            tk.advance(k);
        } else if (strcmp(cmd, "PRINT24") == 0) {
            tk.output24();
        } else if (strcmp(cmd, "PRINT12") == 0) {
