using namespace std;

int rankToVal(char r) {
    if (r >= '2' && r <= '9') return r - '0';
    if (r == 'T') return 10;
    if (r == 'J') return 11;
    if (r == 'Q') return 12;
    if (r == 'K') return 13;
    if (r == 'A') return 14;
    return 0;
}

struct Card {
    string s;
    int val;
    char suit;
};

Card makeCard(string s) {
    return {s, rankToVal(s[0]), s[1]};
}

bool isFlush(const vector<Card>& hand) {
    for (int i = 1; i < 5; ++i) {
        if (hand[i].suit != hand[0].suit) return false;
    }
    return true;
}

bool isStraight(const vector<Card>& hand) {
    vector<int> vals;
    for (const auto& c : hand) vals.push_back(c.val);
    sort(vals.begin(), vals.end());
    // Check normal straight
    bool normal = true;
    for (int i = 0; i < 4; ++i) {
        if (vals[i+1] - vals[i] != 1) {
            normal = false;
            break;
        }
    }
    if (normal) return true;
    // Check A-2-3-4-5 straight (Ace as 1)
    if (vals[0] == 2 && vals[1] == 3 && vals[2] == 4 && vals[3] == 5 && vals[4] == 14) return true;
    return false;
}

string evaluate(const vector<Card>& hand) {
    map<int, int> counts;
    for (const auto& c : hand) counts[c.val]++;
    vector<int> freq;
    for (auto const& p : counts) freq.push_back(p.second);
    sort(freq.rbegin(), freq.rend());

    bool flush = isFlush(hand);
    bool straight = isStraight(hand);

    if (flush && straight) return "Straight Flush";
    if (freq[0] == 4) return "Four of a Kind";
    if (freq[0] == 3 && freq[1] == 2) return "Full House";
    if (flush) return "Flush";
    if (straight) return "Straight";
    if (freq[0] == 3) return "Three of a Kind";
    if (freq[0] == 2 && freq[1] == 2) return "Two Pair";
    if (freq[0] == 2) return "One Pair";
    return "High Card";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<Card> hand(5);
    for (int i = 0; i < 5; ++i) {
        string s; cin >> s;
        hand[i] = makeCard(s);
    }
    vector<Card> draw(3);
    for (int i = 0; i < 3; ++i) {
        string s; cin >> s;
        draw[i] = makeCard(s);
    }

    string initialEval = evaluate(hand);
    cout << initialEval << "\n";

    map<int, int> counts;
    for (const auto& c : hand) counts[c.val]++;

    vector<Card> kept;
    vector<Card> discarded;

    if (initialEval == "Straight Flush" || initialEval == "Full House" || 
        initialEval == "Flush" || initialEval == "Straight") {
        // keep all 5
        kept = hand;
    } else if (initialEval == "Four of a Kind") {
        for (const auto& c : hand) {
            if (counts[c.val] == 4) kept.push_back(c);
            else discarded.push_back(c);
        }
    } else if (initialEval == "Three of a Kind") {
        for (const auto& c : hand) {
            if (counts[c.val] == 3) kept.push_back(c);
            else discarded.push_back(c);
        }
    } else if (initialEval == "Two Pair") {
        for (const auto& c : hand) {
            if (counts[c.val] == 2) kept.push_back(c);
            else discarded.push_back(c);
        }
    } else if (initialEval == "One Pair") {
        for (const auto& c : hand) {
            if (counts[c.val] == 2) kept.push_back(c);
            else discarded.push_back(c);
        }
    } else {
        // High card: keep 2 highest cards
        vector<Card> sortedHand = hand;
        sort(sortedHand.begin(), sortedHand.end(), [](const Card& a, const Card& b) {
            return a.val > b.val;
        });
        kept.push_back(sortedHand[0]);
        kept.push_back(sortedHand[1]);
        for (int i = 2; i < 5; ++i) discarded.push_back(sortedHand[i]);
    }

    int k = discarded.size();
    cout << k << "\n";

    vector<Card> finalHand = kept;
    for (int i = 0; i < k; ++i) {
        finalHand.push_back(draw[i]);
    }

    cout << evaluate(finalHand) << "\n";

    return 0;
}

