using namespace std;

int rankValue(char c) {
    if (c >= '2' && c <= '9') return c - '0';
    if (c == 'T') return 10;
    if (c == 'J') return 11;
    if (c == 'Q') return 12;
    if (c == 'K') return 13;
    if (c == 'A') return 14;
    return 0;
}

struct HandRank {
    int category; // 8: Straight Flush, 7: 4 of a kind, 6: Full house, 5: Flush, 4: Straight, 3: 3 of a kind, 2: 2 pair, 1: 1 pair, 0: High card
    vector<int> tieBreakers;

    bool operator<(const HandRank& other) const {
        if (category != other.category) return category < other.category;
        return tieBreakers < other.tieBreakers;
    }
    bool operator>(const HandRank& other) const {
        if (category != other.category) return category > other.category;
        return tieBreakers > other.tieBreakers;
    }
    bool operator==(const HandRank& other) const {
        return category == other.category && tieBreakers == other.tieBreakers;
    }
};

HandRank evaluateHand(const vector<string>& cards) {
    vector<int> values;
    map<int, int> countMap;
    bool isFlush = true;
    char suit0 = cards[0][1];

    for (const auto& card : cards) {
        int v = rankValue(card[0]);
        values.push_back(v);
        countMap[v]++;
        if (card[1] != suit0) isFlush = false;
    }

    sort(values.begin(), values.end());

    // Check straight
    bool isStraight = false;
    int straightHigh = 0;
    if (values[0] + 1 == values[1] && values[1] + 1 == values[2] &&
        values[2] + 1 == values[3] && values[3] + 1 == values[4]) {
        isStraight = true;
        straightHigh = values[4];
    } else if (values[0] == 2 && values[1] == 3 && values[2] == 4 && values[3] == 5 && values[4] == 14) {
        // Ace low straight: A-2-3-4-5
        isStraight = true;
        straightHigh = 5;
    }

    // Group by counts
    vector<pair<int, int>> groups; // {count, value}
    for (auto const& [val, cnt] : countMap) {
        groups.push_back({cnt, val});
    }
    sort(groups.begin(), groups.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second > b.second;
    });

    if (isStraight && isFlush) {
        return {8, {straightHigh}};
    }
    if (groups[0].first == 4) {
        return {7, {groups[0].second, groups[1].second}};
    }
    if (groups[0].first == 3 && groups[1].first == 2) {
        return {6, {groups[0].second, groups[1].second}};
    }
    if (isFlush) {
        vector<int> desc = values;
        reverse(desc.begin(), desc.end());
        return {5, desc};
    }
    if (isStraight) {
        return {4, {straightHigh}};
    }
    if (groups[0].first == 3) {
        return {3, {groups[0].second, groups[1].second, groups[2].second}};
    }
    if (groups[0].first == 2 && groups[1].first == 2) {
        return {2, {groups[0].second, groups[1].second, groups[2].second}};
    }
    if (groups[0].first == 2) {
        return {1, {groups[0].second, groups[1].second, groups[2].second, groups[3].second}};
    }

    vector<int> desc = values;
    reverse(desc.begin(), desc.end());
    return {0, desc};
}

void solve() {
    vector<string> hand1(5), hand2(5);
    for (int i = 0; i < 5; ++i) cin >> hand1[i];
    for (int i = 0; i < 5; ++i) cin >> hand2[i];

    HandRank r1 = evaluateHand(hand1);
    HandRank r2 = evaluateHand(hand2);

    if (r1 > r2) {
