    for (int i = 0; i < 5; ++i) {
        freq[hand[i].rank]++;
        if (i > 0 && hand[i].suit != hand[0].suit) flush = false;
    }

    vector<int> ranks;
    for (int i = 0; i < 5; ++i) ranks.push_back(hand[i].rank);
    sort(ranks.begin(), ranks.end());

