        score.push_back(countPairs[0].second);
        score.push_back(countPairs[1].second);
        score.push_back(countPairs[2].second);
    } else if (countPairs[0].first == 2 && countPairs[1].first == 2) {
        score.push_back(2);
        score.push_back(countPairs[0].second);
        score.push_back(countPairs[1].second);
