        deck.reserve(52);
        for (int i = 0; i < 52; ++i) {
            deck.push_back(Card(i % 13, i / 13));
        }
    }

    void shuffle(const std::vector<int>& swapIndices) {
        for (size_t i = 0; i < deck.size() && i < swapIndices.size(); ++i) {
            int target = swapIndices[i];
            if (target >= 0 && target < static_cast<int>(deck.size())) {
                std::swap(deck[i], deck[target]);
            }
        }
        currentCard = 0;
    }

    bool moreCards() const {
        return currentCard < static_cast<int>(deck.size());
    }

    Card dealCard() {
