    IntegerSet() : a(101, false) {}

    IntegerSet(const vector<int>& elements) : a(101, false) {
        for (int x : elements) {
            if (x >= 0 && x <= 100) {
                a[x] = true;
            }
        }
    }

    void insertElement(int k) {
        if (k >= 0 && k <= 100) {
            a[k] = true;
        }
    }

    void deleteElement(int m) {
        if (m >= 0 && m <= 100) {
            a[m] = false;
        }
    }

    IntegerSet unionOfSets(const IntegerSet& other) const {
        IntegerSet result;
        for (int i = 0; i <= 100; ++i) {
            result.a[i] = this->a[i] || other.a[i];
        }
        return result;
    }

    IntegerSet intersectionOfSets(const IntegerSet& other) const {
        IntegerSet result;
        for (int i = 0; i <= 100; ++i) {
            result.a[i] = this->a[i] && other.a[i];
        }
        return result;
    }

    bool isEqualTo(const IntegerSet& other) const {
        for (int i = 0; i <= 100; ++i) {
            if (this->a[i] != other.a[i]) return false;
        }
        return true;
    }

    void printSet() const {
        bool empty = true;
        bool first = true;
        for (int i = 0; i <= 100; ++i) {
            if (a[i]) {
                empty = false;
                if (!first) cout << " ";
                cout << i;
                first = false;
            }
        }
        if (empty) {
            cout << "---";
        }
        cout << "\n";
    }
};

