#include <iostream>
#include <numeric>

using namespace std;

long long gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a < 0 ? -a : a;
}

struct RationalNumber {
    long long num;
    long long den;

    RationalNumber(long long n = 0, long long d = 1) {
        if (d < 0) {
            n = -n;
            d = -d;
        }
        long long g = gcd(n < 0 ? -n : n, d);
        if (g == 0) g = 1;
        num = n / g;
        den = d / g;
    }

    RationalNumber operator+(const RationalNumber& o) const {
        return RationalNumber(num * o.den + o.num * den, den * o.den);
    }

    RationalNumber operator-(const RationalNumber& o) const {
        return RationalNumber(num * o.den - o.num * den, den * o.den);
    }

    RationalNumber operator*(const RationalNumber& o) const {
        return RationalNumber(num * o.num, den * o.den);
    }

    RationalNumber operator/(const RationalNumber& o) const {
        return RationalNumber(num * o.den, den * o.num);
    }

    bool operator==(const RationalNumber& o) const {
        return num == o.num && den == o.den;
    }

    bool operator<(const RationalNumber& o) const {
        return num * o.den < o.num * den;
    }

    bool operator>(const RationalNumber& o) const {
        return num * o.den > o.num * den;
    }
};

int main() {
    long long a1, b1, a2, b2;
    if (!(cin >> a1 >> b1 >> a2 >> b2)) return 0;

    RationalNumber r1(a1, b1);
    RationalNumber r2(a2, b2);

    cout << r1.num << "/" << r1.den << "\n";
    cout << r2.num << "/" << r2.den << "\n";

    RationalNumber sum = r1 + r2;
    cout << sum.num << "/" << sum.den << "\n";

    RationalNumber diff = r1 - r2;
    cout << diff.num << "/" << diff.den << "\n";

    RationalNumber prod = r1 * r2;
    cout << prod.num << "/" << prod.den << "\n";

    if (r2.num == 0) {
        cout << "INVALID\n";
    } else {
        RationalNumber quot = r1 / r2;
        cout << quot.num << "/" << quot.den << "\n";
    }

    if (r1 < r2) {
        cout << "<\n";
    } else if (r1 > r2) {
        cout << ">\n";
    } else {
        cout << "=\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class RationalNumber {
private:
    long long numerator;
    long long denominator;

    void reduce() {
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        if (numerator == 0) {
            denominator = 1;
            return;
        }
        long long common = std::gcd(std::abs(numerator), denominator);
        numerator /= common;
        denominator /= common;
    }

public:
    RationalNumber(long long n = 0, long long d = 1) : numerator(n), denominator(d) {
        reduce();
    }

    long long getNum() const { return numerator; }
    long long getDen() const { return denominator; }

    RationalNumber operator+(const RationalNumber& other) const {
        return RationalNumber(numerator * other.denominator + other.numerator * denominator,
                              denominator * other.denominator);
    }

    RationalNumber operator-(const RationalNumber& other) const {
        return RationalNumber(numerator * other.denominator - other.numerator * denominator,
                              denominator * other.denominator);
    }

    RationalNumber operator*(const RationalNumber& other) const {
        return RationalNumber(numerator * other.numerator,
                              denominator * other.denominator);
    }

    RationalNumber operator/(const RationalNumber& other) const {
        return RationalNumber(numerator * other.denominator,
                              denominator * other.numerator);
    }

    bool operator==(const RationalNumber& other) const {
        return numerator * other.denominator == other.numerator * denominator;
    }

    bool operator<(const RationalNumber& other) const {
        return numerator * other.denominator < other.numerator * denominator;
    }

    bool operator>(const RationalNumber& other) const {
        return numerator * other.denominator > other.numerator * denominator;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long a1, b1, a2, b2;
    if (cin >> a1 >> b1 >> a2 >> b2) {
        RationalNumber r1(a1, b1), r2(a2, b2);
        cout << r1.getNum() << "/" << r1.getDen() << "\n";
        cout << r2.getNum() << "/" << r2.getDen() << "\n";

        RationalNumber add = r1 + r2;
        cout << add.getNum() << "/" << add.getDen() << "\n";

        RationalNumber sub = r1 - r2;
        cout << sub.getNum() << "/" << sub.getDen() << "\n";

        RationalNumber mul = r1 * r2;
        cout << mul.getNum() << "/" << mul.getDen() << "\n";

        if (r2.getNum() == 0) {
            cout << "INVALID\n";
        } else {
            RationalNumber div = r1 / r2;
            cout << div.getNum() << "/" << div.getDen() << "\n";
        }

        if (r1 < r2) cout << "<\n";
        else if (r1 > r2) cout << ">\n";
        else cout << "=\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

string normalize(string s) {
    int i = 0;
    while (i + 1 < (int)s.size() && s[i] == '0') i++;
    return s.substr(i);
}

int compareHuge(const string &a, const string &b) {
    string s1 = normalize(a);
    string s2 = normalize(b);
    if (s1.length() != s2.length())
        return s1.length() < s2.length() ? -1 : 1;
    if (s1 < s2) return -1;
    if (s1 > s2) return 1;
    return 0;
}

string subtractHuge(string a, string b) {
    a = normalize(a);
    b = normalize(b);
    string res = "";
    int i = a.size() - 1, j = b.size() - 1, borrow = 0;
    while (i >= 0) {
        int sub = (a[i] - '0') - borrow - (j >= 0 ? (b[j] - '0') : 0);
        if (sub < 0) {
            sub += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        res.push_back(sub + '0');
        i--;
        j--;
    }
    while (res.size() > 1 && res.back() == '0') res.pop_back();
    reverse(res.begin(), res.end());
    return res;
}

string multiplyHuge(string a, string b) {
    a = normalize(a);
    b = normalize(b);
    if (a == "0" || b == "0") return "0";
    int n = a.size(), m = b.size();
    vector<int> res(n + m, 0);
    for (int i = n - 1; i >= 0; i--) {
        for (int j = m - 1; j >= 0; j--) {
            int p = (a[i] - '0') * (b[j] - '0');
            int sum = p + res[i + j + 1];
            res[i + j + 1] = sum % 10;
            res[i + j] += sum / 10;
        }
    }
    string s = "";
    int i = 0;
    while (i < (int)res.size() && res[i] == 0) i++;
    for (; i < (int)res.size(); i++) s.push_back(res[i] + '0');
    return s.empty() ? "0" : s;
}

pair<string, string> divideHuge(string a, string b) {
    a = normalize(a);
    b = normalize(b);
    if (compareHuge(a, b) < 0) return {"0", a};
    string cur = "";
    string quot = "";
    for (char c : a) {
        cur.push_back(c);
        cur = normalize(cur);
        int count = 0;
        while (compareHuge(cur, b) >= 0) {
            cur = subtractHuge(cur, b);
            count++;
        }
        quot.push_back(count + '0');
    }
    return {normalize(quot), normalize(cur)};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string a, b;
    if (!(cin >> a >> b)) return 0;
    a = normalize(a);
    b = normalize(b);

    int cmp = compareHuge(a, b);
    cout << (cmp < 0 ? 1 : 0) << " "
         << (cmp <= 0 ? 1 : 0) << " "
         << (cmp > 0 ? 1 : 0) << " "
         << (cmp >= 0 ? 1 : 0) << " "
         << (cmp == 0 ? 1 : 0) << " "
         << (cmp != 0 ? 1 : 0) << "\n";

    cout << multiplyHuge(a, b) << "\n";

    if (b == "0") {
        cout << "DIV_BY_ZERO\n";
    } else {
        auto [q, r] = divideHuge(a, b);
        cout << q << " " << r << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

struct BigInt {
    vector<int> d;

    BigInt() {}
    BigInt(const string &s) {
        for (int i = (int)s.length() - 1; i >= 0; --i) {
            d.push_back(s[i] - '0');
        }
        trim();
    }

    void trim() {
        while (d.size() > 1 && d.back() == 0) d.pop_back();
        if (d.empty()) d.push_back(0);
    }

    bool operator<(const BigInt &o) const {
        if (d.size() != o.d.size()) return d.size() < o.d.size();
        for (int i = (int)d.size() - 1; i >= 0; --i) {
            if (d[i] != o.d[i]) return d[i] < o.d[i];
        }
        return false;
    }

    bool operator<=(const BigInt &o) const {
        return !(o < *this);
    }

    bool operator>(const BigInt &o) const {
        return o < *this;
    }

    bool operator>=(const BigInt &o) const {
        return !(*this < o);
    }

    bool operator==(const BigInt &o) const {
        return d == o.d;
    }

    bool operator!=(const BigInt &o) const {
        return !(*this == o);
    }

    BigInt operator-(const BigInt &o) const {
        BigInt res;
        res.d.clear();
        long long carry = 0;
        for (size_t i = 0; i < d.size(); ++i) {
            long long sub = d[i] - carry - (i < o.d.size() ? o.d[i] : 0);
            if (sub < 0) {
                sub += 10;
                carry = 1;
            } else {
                carry = 0;
            }
            res.d.push_back(sub);
        }
        res.trim();
        return res;
    }

    BigInt operator*(const BigInt &o) const {
        BigInt res;
        res.d.assign(d.size() + o.d.size(), 0);
        for (size_t i = 0; i < d.size(); ++i) {
            long long carry = 0;
            for (size_t j = 0; j < o.d.size() || carry; ++j) {
                long long cur = res.d[i + j] + carry + d[i] * 1LL * (j < o.d.size() ? o.d[j] : 0);
                res.d[i + j] = cur % 10;
                carry = cur / 10;
            }
        }
        res.trim();
        return res;
    }

    string toString() const {
        string s = "";
        for (int i = (int)d.size() - 1; i >= 0; --i) {
            s.push_back(d[i] + '0');
        }
        return s;
    }
};

pair<BigInt, BigInt> divide(BigInt a, BigInt b) {
    if (a < b) return {BigInt("0"), a};
    string sa = a.toString();
    BigInt cur("0");
    string res = "";
    for (char c : sa) {
        if (cur == BigInt("0")) cur.d.clear();
        cur.d.insert(cur.d.begin(), c - '0');
        cur.trim();
        int count = 0;
        while (cur >= b) {
            cur = cur - b;
            count++;
        }
        res.push_back(count + '0');
    }
    return {BigInt(res), cur};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string sa, sb;
    if (!(cin >> sa >> sb)) return 0;
    BigInt a(sa), b(sb);

    cout << (a < b) << " "
         << (a <= b) << " "
         << (a > b) << " "
         << (a >= b) << " "
         << (a == b) << " "
         << (a != b) << "\n";

    cout << (a * b).toString() << "\n";

    if (b == BigInt("0")) {
        cout << "DIV_BY_ZERO\n";
    } else {
        auto p = divide(a, b);
        cout << p.first.toString() << " " << p.second.toString() << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

class DoubleSubscriptedArray {
private:
    int rows;
    int cols;
    std::vector<long long> data;

public:
    DoubleSubscriptedArray(int r = 1, int c = 1) : rows(r), cols(c), data(r * c, 0) {}

    int getRows() const { return rows; }
    int getCols() const { return cols; }

    // Overload operator() lvalue
    long long& operator()(int r, int c) {
        return data[r * cols + c];
    }

    // Overload operator() const rvalue
    long long operator()(int r, int c) const {
        return data[r * cols + c];
    }

    bool operator==(const DoubleSubscriptedArray& other) const {
        if (rows != other.rows || cols != other.cols) return false;
        return data == other.data;
    }

    bool operator!=(const DoubleSubscriptedArray& other) const {
        return !(*this == other);
    }

    DoubleSubscriptedArray& operator=(const DoubleSubscriptedArray& other) {
        if (this != &other) {
            rows = other.rows;
            cols = other.cols;
            data = other.data;
        }
        return *this;
    }

    friend std::ostream& operator<<(std::ostream& os, const DoubleSubscriptedArray& arr) {
        for (int i = 0; i < arr.rows; ++i) {
            for (int j = 0; j < arr.cols; ++j) {
                os << arr(i, j) << (j + 1 == arr.cols ? "" : " ");
            }
            os << "\n";
        }
        return os;
    }

    friend std::istream& operator>>(std::istream& is, DoubleSubscriptedArray& arr) {
        for (int i = 0; i < arr.rows; ++i) {
            for (int j = 0; j < arr.cols; ++j) {
                is >> arr(i, j);
            }
        }
        return is;
    }
};

