#include <iostream>
#include <string>
#include <memory>
#include <algorithm>

class DoubleSubscriptedArray {
private:
    int m_rows;
    int m_cols;
    long long* m_ptr;

public:
    DoubleSubscriptedArray(int rows = 0, int cols = 0) 
        : m_rows(rows), m_cols(cols), m_ptr(nullptr) {
        if (m_rows > 0 && m_cols > 0) {
            m_ptr = new long long[m_rows * m_cols]();
        }
    }

    DoubleSubscriptedArray(const DoubleSubscriptedArray& other)
        : m_rows(other.m_rows), m_cols(other.m_cols), m_ptr(nullptr) {
        if (m_rows > 0 && m_cols > 0) {
            m_ptr = new long long[m_rows * m_cols];
            std::copy(other.m_ptr, other.m_ptr + m_rows * m_cols, m_ptr);
        }
    }

    ~DoubleSubscriptedArray() {
        delete[] m_ptr;
    }

    DoubleSubscriptedArray& operator=(const DoubleSubscriptedArray& other) {
        if (this != &other) {
            delete[] m_ptr;
            m_rows = other.m_rows;
            m_cols = other.m_cols;
            if (m_rows > 0 && m_cols > 0) {
                m_ptr = new long long[m_rows * m_cols];
                std::copy(other.m_ptr, other.m_ptr + m_rows * m_cols, m_ptr);
            } else {
                m_ptr = nullptr;
            }
        }
        return *this;
    }

    long long& operator()(int r, int c) {
        return *(m_ptr + (r * m_cols + c));
    }

    long long operator()(int r, int c) const {
        return *(m_ptr + (r * m_cols + c));
    }

    bool operator==(const DoubleSubscriptedArray& other) const {
        if (m_rows != other.m_rows || m_cols != other.m_cols) return false;
        for (int i = 0; i < m_rows * m_cols; ++i) {
            if (m_ptr[i] != other.m_ptr[i]) return false;
        }
        return true;
    }

    bool operator!=(const DoubleSubscriptedArray& other) const {
        return !(*this == other);
    }

    friend std::ostream& operator<<(std::ostream& out, const DoubleSubscriptedArray& arr) {
        for (int r = 0; r < arr.m_rows; ++r) {
            for (int c = 0; c < arr.m_cols; ++c) {
                out << arr(r, c);
                if (c + 1 < arr.m_cols) out << ' ';
            }
            out << '\n';
        }
        return out;
    }

    friend std::istream& operator>>(std::istream& in, DoubleSubscriptedArray& arr) {
        for (int r = 0; r < arr.m_rows; ++r) {
            for (int c = 0; c < arr.m_cols; ++c) {
                in >> arr(r, c);
            }
        }
        return in;
    }
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int R, C;
    if (!(std::cin >> R >> C)) return 0;

    DoubleSubscriptedArray A(R, C), B(R, C);
    int Q;
    if (!(std::cin >> Q)) return 0;

    for (int i = 0; i < Q; ++i) {
        std::string cmd;
        std::cin >> cmd;
        if (cmd == "SET") {
            char target;
            int r, c;
            long long val;
            std::cin >> target >> r >> c >> val;
            if (target == 'A') A(r, c) = val;
            else B(r, c) = val;
        } else if (cmd == "GET") {
            char target;
            int r, c;
            std::cin >> target >> r >> c;
            if (target == 'A') std::cout << A(r, c) << '\n';
            else std::cout << B(r, c) << '\n';
        } else if (cmd == "COPY") {
            char dst, src;
            std::cin >> dst >> src;
            if (dst == 'A' && src == 'B') A = B;
            else if (dst == 'B' && src == 'A') B = A;
        } else if (cmd == "COMPARE") {
            std::cout << (A == B ? "EQUAL\n" : "NOT_EQUAL\n");
        } else if (cmd == "PRINT") {
            char target;
            std::cin >> target;
            if (target == 'A') std::cout << A;
            else std::cout << B;
        } else if (cmd == "LOAD") {
            char target;
            std::cin >> target;
            if (target == 'A') std::cin >> A;
            else std::cin >> B;
        }
    }

    return 0;
}

