#include <map>
#include <algorithm>

using namespace std;

class Polynomial {
private:
    map<int, long long> terms;

public:
    Polynomial() {}

    void addTerm(int exp, long long coeff) {
        terms[exp] += coeff;
        if (terms[exp] == 0) {
            terms.erase(exp);
        }
    }

    Polynomial operator+(const Polynomial& other) const {
        Polynomial res = *this;
        for (auto const& [exp, coeff] : other.terms) {
            res.addTerm(exp, coeff);
        }
        return res;
    }

    Polynomial operator-(const Polynomial& other) const {
        Polynomial res = *this;
        for (auto const& [exp, coeff] : other.terms) {
            res.addTerm(exp, -coeff);
        }
        return res;
    }

    Polynomial operator*(const Polynomial& other) const {
        Polynomial res;
        for (auto const& [exp1, coeff1] : this->terms) {
            for (auto const& [exp2, coeff2] : other.terms) {
                res.addTerm(exp1 + exp2, coeff1 * coeff2);
            }
        }
        return res;
    }

    void print() const {
        if (terms.empty()) {
            cout << 0 << "\n";
            return;
        }
        bool first = true;
        for (auto it = terms.rbegin(); it != terms.rend(); ++it) {
            if (!first) cout << " ";
            cout << it->second << " x^" << it->first;
            first = false;
        }
        cout << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    Polynomial A;
    for (int i = 0; i < n; ++i) {
        long long c;
        int e;
        cin >> c >> e;
        A.addTerm(e, c);
    }

    int m;
    cin >> m;
    Polynomial B;
    for (int i = 0; i < m; ++i) {
        long long c;
        int e;
        cin >> c >> e;
        B.addTerm(e, c);
    }

    Polynomial sum = A + B;
    Polynomial diff = A - B;
    Polynomial prod = A * B;

    sum.print();
    diff.print();
    prod.print();

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Term {
    long long coeff;
    int exp;
};

class Poly {
public:
    vector<long long> c;

    Poly(int maxDeg = 205) {
        c.assign(maxDeg + 1, 0);
    }

    void add(int exp, long long coeff) {
        if (exp >= (int)c.size()) {
            c.resize(exp + 1, 0);
        }
        c[exp] += coeff;
    }

    Poly operator+(const Poly& o) const {
        int sz = max(c.size(), o.c.size());
        Poly res(sz);
        for (size_t i = 0; i < c.size(); ++i) res.c[i] += c[i];
        for (size_t i = 0; i < o.c.size(); ++i) res.c[i] += o.c[i];
        return res;
    }

    Poly operator-(const Poly& o) const {
        int sz = max(c.size(), o.c.size());
        Poly res(sz);
        for (size_t i = 0; i < c.size(); ++i) res.c[i] += c[i];
        for (size_t i = 0; i < o.c.size(); ++i) res.c[i] -= o.c[i];
        return res;
    }

    Poly operator*(const Poly& o) const {
        int sz = (int)c.size() + (int)o.c.size();
        Poly res(sz);
        for (size_t i = 0; i < c.size(); ++i) {
            if (c[i] == 0) continue;
            for (size_t j = 0; j < o.c.size(); ++j) {
                if (o.c[j] == 0) continue;
                res.c[i + j] += c[i] * o.c[j];
            }
        }
        return res;
    }

    void display() const {
        bool hasAny = false;
        for (int i = (int)c.size() - 1; i >= 0; --i) {
            if (c[i] != 0) {
                if (hasAny) cout << " ";
                cout << c[i] << " x^" << i;
                hasAny = true;
            }
        }
        if (!hasAny) {
            cout << 0;
        }
        cout << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    Poly A;
    for (int i = 0; i < n; ++i) {
        long long coeff;
        int exp;
        cin >> coeff >> exp;
        A.add(exp, coeff);
    }

    int m;
    cin >> m;
    Poly B;
    for (int i = 0; i < m; ++i) {
        long long coeff;
        int exp;
        cin >> coeff >> exp;
        B.add(exp, coeff);
    }

    (A + B).display();
    (A - B).display();
    (A * B).display();

    return 0;
}

