class Account {
protected:
    double balance;
public:
    Account(double initialBalance) {
        if (initialBalance >= 0.0) {
            balance = initialBalance;
        } else {
            balance = 0.0;
            std::cout << "Error: Initial balance cannot be negative.\n";
        }
    }

    virtual void credit(double amount) {
        balance += amount;
    }

    virtual bool debit(double amount) {
        if (amount <= balance) {
            balance -= amount;
            return true;
        } else {
            std::cout << "Debit amount exceeded account balance.\n";
            return false;
        }
    }

    double getBalance() const {
        return balance;
    }
};

class SavingsAccount : public Account {
private:
    double interestRate;
public:
    SavingsAccount(double initialBalance, double rate) 
        : Account(initialBalance), interestRate(rate) {}

    double calculateInterest() const {
        return balance * interestRate;
    }

    void applyInterest() {
        double interest = calculateInterest();
        credit(interest);
    }
};

class CheckingAccount : public Account {
private:
    double transactionFee;
public:
    CheckingAccount(double initialBalance, double fee)
        : Account(initialBalance), transactionFee(fee) {}

    void credit(double amount) override {
        Account::credit(amount);
        balance -= transactionFee;
    }

    bool debit(double amount) override {
        bool success = Account::debit(amount);
        if (success) {
            balance -= transactionFee;
            return true;
        }
        return false;
    }
};

