#include <iostream>
#include <vector>
#include <iomanip>
#include <memory>

using namespace std;

class Account {
protected:
    double balance;
public:
    Account(double initialBalance) : balance(initialBalance >= 0.0 ? initialBalance : 0.0) {}
    virtual ~Account() = default;

    virtual bool credit(double amount) {
        if (amount > 0) {
            balance += amount;
            return true;
        }
        return false;
    }

    virtual bool debit(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    double getBalance() const {
        return balance;
    }
};

class SavingsAccount : public Account {
private:
    double interestRate;
public:
    SavingsAccount(double initialBalance, double rate)
        : Account(initialBalance), interestRate(rate >= 0.0 ? rate : 0.0) {}

    double calculateInterest() const {
        return balance * interestRate;
    }
};

class CheckingAccount : public Account {
private:
    double fee;
public:
    CheckingAccount(double initialBalance, double transactionFee)
        : Account(initialBalance), fee(transactionFee >= 0.0 ? transactionFee : 0.0) {}

    bool credit(double amount) override {
        if (Account::credit(amount)) {
            if (balance >= fee) {
                balance -= fee;
                return true;
            }
        }
        return false;
    }

    bool debit(double amount) override {
        if (Account::debit(amount)) {
            if (balance >= fee) {
                balance -= fee;
                return true;
            } else {
                balance += amount; // Rollback
                return false;
            }
        }
        return false;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<unique_ptr<Account>> accounts;
    vector<pair<double, double>> transactions;

    for (int i = 0; i < n; ++i) {
        char type;
        cin >> type;
        if (type == 'S') {
            double bal, rate;
            cin >> bal >> rate;
            accounts.push_back(make_unique<SavingsAccount>(bal, rate));
        } else {
            double bal, fee;
            cin >> bal >> fee;
            accounts.push_back(make_unique<CheckingAccount>(bal, fee));
        }
        double w, d;
        cin >> w >> d;
        transactions.emplace_back(w, d);
    }

    cout << fixed << setprecision(2);
    for (size_t i = 0; i < accounts.size(); ++i) {
        Account* acc = accounts[i].get();
        double w = transactions[i].first;
        double d = transactions[i].second;

        acc->debit(w);
        acc->credit(d);

        SavingsAccount* sa = dynamic_cast<SavingsAccount*>(acc);
        if (sa != nullptr) {
            double interest = sa->calculateInterest();
            sa->credit(interest);
        }

        cout << acc->getBalance() << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <iomanip>

struct IAccount {
    double bal;
    explicit IAccount(double b) : bal(b >= 0.0 ? b : 0.0) {}
    virtual ~IAccount() = default;
    virtual bool deposit(double amt) {
        if (amt > 0.0) {
            bal += amt;
            return true;
        }
        return false;
    }
    virtual bool withdraw(double amt) {
        if (amt > 0.0 && amt <= bal) {
            bal -= amt;
            return true;
        }
        return false;
    }
    double getBal() const { return bal; }
};

struct Savings : public IAccount {
    double rate;
    Savings(double b, double r) : IAccount(b), rate(r >= 0.0 ? r : 0.0) {}
    double getInterest() const { return bal * rate; }
};

struct Checking : public IAccount {
    double fee;
    Checking(double b, double f) : IAccount(b), fee(f >= 0.0 ? f : 0.0) {}
    bool deposit(double amt) override {
        if (amt > 0.0) {
            bal += amt;
            if (bal >= fee) {
                bal -= fee;
            }
            return true;
        }
        return false;
    }
    bool withdraw(double amt) override {
        if (amt > 0.0 && amt <= bal) {
            bal -= amt;
            if (bal >= fee) {
                bal -= fee;
                return true;
            } else {
                bal += amt;
                return false;
            }
        }
        return false;
    }
};

int main() {
    std::cin.tie(nullptr)->sync_with_stdio(false);
    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<IAccount*> list;
    std::vector<std::pair<double, double>> ops(n);

    for (int i = 0; i < n; ++i) {
        char t;
        std::cin >> t;
        if (t == 'S') {
            double b, r;
            std::cin >> b >> r;
            list.push_back(new Savings(b, r));
        } else {
            double b, f;
            std::cin >> b >> f;
            list.push_back(new Checking(b, f));
        }
        std::cin >> ops[i].first >> ops[i].second;
    }

    std::cout << std::fixed << std::setprecision(2);
    for (int i = 0; i < n; ++i) {
        list[i]->withdraw(ops[i].first);
        list[i]->deposit(ops[i].second);

        if (auto* s = dynamic_cast<Savings*>(list[i])) {
            double interest = s->getInterest();
            s->deposit(interest);
        }

        std::cout << list[i]->getBal() << "\n";
        delete list[i];
    }

    return 0;
}

