    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    const string& getName() const { return name; }
    const Date& getBirthDate() const { return birthDate; }
};

class SalariedEmployee : public Employee {
    double weeklySalary;
public:
    SalariedEmployee(string n, Date d, double w) : Employee(n, d), weeklySalary(w) {}
    double earnings() const override {
        return 4.0 * weeklySalary;
    }
};

class HourlyEmployee : public Employee {
    double wage;
    double hours;
public:
    HourlyEmployee(string n, Date d, double w, double h) : Employee(n, d), wage(w), hours(h) {}
    double earnings() const override {
        if (hours <= 160.0) return hours * wage;
        return 160.0 * wage + (hours - 160.0) * 1.5 * wage;
    }
};

class CommissionEmployee : public Employee {
    double grossSales;
    double commissionRate;
public:
    CommissionEmployee(string n, Date d, double s, double r) : Employee(n, d), grossSales(s), commissionRate(r) {}
    double earnings() const override {
        return grossSales * commissionRate;
    }
};

class BasePlusCommissionEmployee : public CommissionEmployee {
    double baseSalary;
public:
    BasePlusCommissionEmployee(string n, Date d, double base, double s, double r)
        : CommissionEmployee(n, d, s, r), baseSalary(base) {}
    double earnings() const override {
        return baseSalary + CommissionEmployee::earnings();
    }
};

