};

class StaffMember {
public:
    string empName;
    BirthDate bDate;

    StaffMember(const string& name, int d, int m, int y) : empName(name), bDate{d, m, y} {}
    virtual ~StaffMember() {}
    virtual double calculatePay() const = 0;
};

class FixedSalaried : public StaffMember {
    double salaryPerWeek;
public:
    FixedSalaried(const string& name, int d, int m, int y, double sw)
        : StaffMember(name, d, m, y), salaryPerWeek(sw) {}
    double calculatePay() const override {
        return 4.0 * salaryPerWeek;
    }
};

class HourlyPaid : public StaffMember {
    double payRate;
    double totalHours;
public:
    HourlyPaid(const string& name, int d, int m, int y, double rate, double h)
        : StaffMember(name, d, m, y), payRate(rate), totalHours(h) {}
    double calculatePay() const override {
        if (totalHours <= 160.0) return totalHours * payRate;
        return 160.0 * payRate + (totalHours - 160.0) * payRate * 1.5;
    }
};

class PureCommission : public StaffMember {
    double sales;
    double rate;
public:
    PureCommission(const string& name, int d, int m, int y, double s, double r)
        : StaffMember(name, d, m, y), sales(s), rate(r) {}
    double calculatePay() const override {
        return sales * rate;
    }
};

class BaseAndCommission : public StaffMember {
    double base;
    double sales;
    double rate;
public:
    BaseAndCommission(const string& name, int d, int m, int y, double b, double s, double r)
        : StaffMember(name, d, m, y), base(b), sales(s), rate(r) {}
    double calculatePay() const override {
        return base + (sales * rate);
    }
};

