#include <memory>
#include <iomanip>

using namespace std;

struct PersonInfo {
    string name;
    string address;
    string city;
    string state;
    string zip;
};

class Package {
protected:
    PersonInfo sender;
    PersonInfo recipient;
    double weight;
    double costPerOunce;
public:
    Package(const PersonInfo& s, const PersonInfo& r, double w, double c)
        : sender(s), recipient(r), weight(w), costPerOunce(c) {}

    virtual ~Package() = default;

    virtual double calculateCost() const {
        return weight * costPerOunce;
    }

    const PersonInfo& getSender() const { return sender; }
    const PersonInfo& getRecipient() const { return recipient; }
};

class TwoDayPackage : public Package {
private:
    double flatFee;
public:
    TwoDayPackage(const PersonInfo& s, const PersonInfo& r, double w, double c, double fee)
        : Package(s, r, w, c), flatFee(fee) {}

    double calculateCost() const override {
        return Package::calculateCost() + flatFee;
    }
};

class OvernightPackage : public Package {
private:
    double additionalFeePerOunce;
public:
    OvernightPackage(const PersonInfo& s, const PersonInfo& r, double w, double c, double feePerOz)
        : Package(s, r, w, c), additionalFeePerOunce(feePerOz) {}

    double calculateCost() const override {
        return weight * (costPerOunce + additionalFeePerOunce);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<unique_ptr<Package>> packages;
    packages.reserve(n);

    for (int i = 0; i < n; ++i) {
        string type;
        getline(cin, type);
        PersonInfo s, r;
        getline(cin, s.name);
        getline(cin, s.address);
        getline(cin, s.city);
        getline(cin, s.state);
        getline(cin, s.zip);

        getline(cin, r.name);
        getline(cin, r.address);
        getline(cin, r.city);
        getline(cin, r.state);
        getline(cin, r.zip);

        double w, c;
        cin >> w >> c;
        if (type == "TwoDay") {
            double fee;
            cin >> fee;
            packages.push_back(make_unique<TwoDayPackage>(s, r, w, c, fee));
        } else {
            double feePerOz;
            cin >> feePerOz;
            packages.push_back(make_unique<OvernightPackage>(s, r, w, c, feePerOz));
        }
        getline(cin, dummy);
    }

    double totalCost = 0.0;
    cout << fixed << setprecision(2);
    for (size_t i = 0; i < packages.size(); ++i) {
        if (i > 0) cout << "\n";
        const auto& p = packages[i];
        double cost = p->calculateCost();
        totalCost += cost;

        const auto& s = p->getSender();
        const auto& r = p->getRecipient();

        cout << "Package " << (i + 1) << ":\n";
        cout << "Sender:\n";
        cout << "  " << s.name << "\n";
        cout << "  " << s.address << "\n";
        cout << "  " << s.city << ", " << s.state << " " << s.zip << "\n";
        cout << "Recipient:\n";
        cout << "  " << r.name << "\n";
        cout << "  " << r.address << "\n";
        cout << "  " << r.city << ", " << r.state << " " << r.zip << "\n";
        cout << "Cost: $" << cost << "\n";
    }

    cout << "\nTotal shipping cost: $" << totalCost << "\n";

    return 0;
}

