        : sName(move(sn)), sAddr(move(sa)), sCity(move(sc)), sState(move(ss)), sZip(move(sz)),
          rName(move(rn)), rAddr(move(ra)), rCity(move(rc)), rState(move(rs)), rZip(move(rz)),
          weight(w), costPerOz(c) {}

    virtual ~Package() {}

    virtual double calculateCost() const {
        return weight * costPerOz;
    }

    string getSenderName() const { return sName; }
    string getSenderAddr() const { return sAddr; }
    string getSenderCity() const { return sCity; }
    string getSenderState() const { return sState; }
    string getSenderZip() const { return sZip; }

    string getRecipName() const { return rName; }
    string getRecipAddr() const { return rAddr; }
    string getRecipCity() const { return rCity; }
    string getRecipState() const { return rState; }
    string getRecipZip() const { return rZip; }
};

class TwoDayPackage : public Package {
    double flatFee;
public:
    TwoDayPackage(string sn, string sa, string sc, string ss, string sz,
                  string rn, string ra, string rc, string rs, string rz,
                  double w, double c, double fee)
        : Package(sn, sa, sc, ss, sz, rn, ra, rc, rs, rz, w, c), flatFee(fee) {}

    double calculateCost() const override {
        return (weight * costPerOz) + flatFee;
    }
};

class OvernightPackage : public Package {
    double extraPerOz;
public:
    OvernightPackage(string sn, string sa, string sc, string ss, string sz,
                     string rn, string ra, string rc, string rs, string rz,
                     double w, double c, double extra)
        : Package(sn, sa, sc, ss, sz, rn, ra, rc, rs, rz, w, c), extraPerOz(extra) {}

    double calculateCost() const override {
        return weight * (costPerOz + extraPerOz);
    }
};

