            idx++;
        }

        int base = 10;
        if (idx < token.size() && token[idx] == '0') {
            if (idx + 1 < token.size() && (token[idx + 1] == 'x' || token[idx + 1] == 'X')) {
                base = 16;
                idx += 2;
            } else {
                base = 8;
            }
        }

        while (idx < token.size()) {
            char c = token[idx++];
            int digit = 0;
            if (c >= '0' && c <= '9') digit = c - '0';
            else if (c >= 'a' && c <= 'f') digit = c - 'a' + 10;
            else if (c >= 'A' && c <= 'F') digit = c - 'A' + 10;
            x = x * base + digit;
        }
        if (neg) x = -x;

        std::cout << std::dec << x << " ";
        if (x < 0) {
            std::cout << "-0" << std::oct << -x << " ";
            std::cout << "-0x" << std::hex << -x << "\n";
