using namespace std;

bool isValid(const string& s, string& areaCode, string& exchange, string& line) {
    if (s.length() != 14) return false;
    if (s[0] != '(' || s[4] != ')' || s[5] != ' ' || s[9] != '-') return false;

    // Kiểm tra tất cả các vị trí số
    int digitIndices[] = {1, 2, 3, 6, 7, 8, 10, 11, 12, 13};
    for (int idx : digitIndices) {
        if (!isdigit(static_cast<unsigned char>(s[idx]))) return false;
    }

    // Ràng buộc a & b: Area code không bắt đầu bằng 0 hoặc 1
    if (s[1] == '0' || s[1] == '1') return false;
    // Ràng buộc c: Ký tự giữa của Area code phải là 0 hoặc 1
    if (s[2] != '0' && s[2] != '1') return false;
    // Ràng buộc b: Exchange không bắt đầu bằng 0 hoặc 1
    if (s[6] == '0' || s[6] == '1') return false;

    areaCode = s.substr(1, 3);
    exchange = s.substr(6, 3);
    line = s.substr(10, 4);
    return true;
}

