    }
    string areaCode, exchange, line;
    if (isValid(s, areaCode, exchange, line)) {
        cout << "Valid phone number\n";
        cout << "Area code: " << areaCode << ", Exchange: " << exchange << ", Line: " << line << "\n";
    } else {
        cout << "Invalid phone number\n";
    }
    return 0;
}

#include <iostream>
#include <string>

using namespace std;

struct PhoneNumber {
    string areaCode;
    string exchange;
    string line;
};

istream& operator>>(istream& is, PhoneNumber& p) {
    string s;
    getline(is, s);
    if (s.size() != 14) {
        is.setstate(ios_base::failbit);
        return is;
    }
    if (s[0] != '(' || s[4] != ')' || s[5] != ' ' || s[9] != '-') {
        is.setstate(ios_base::failbit);
        return is;
    }
    for (int i : {1, 2, 3, 6, 7, 8, 10, 11, 12, 13}) {
        if (s[i] < '0' || s[i] > '9') {
            is.setstate(ios_base::failbit);
            return is;
        }
    }
    // area code first digit not 0 or 1
    if (s[1] == '0' || s[1] == '1') {
        is.setstate(ios_base::failbit);
        return is;
    }
    // area code middle digit must be 0 or 1
    if (s[2] != '0' && s[2] != '1') {
        is.setstate(ios_base::failbit);
        return is;
    }
    // exchange first digit not 0 or 1
    if (s[6] == '0' || s[6] == '1') {
        is.setstate(ios_base::failbit);
        return is;
    }
    p.areaCode = s.substr(1, 3);
    p.exchange = s.substr(6, 3);
    p.line = s.substr(10, 4);
    return is;
}

