#include <iostream>
#include <string>
#include <sstream>
#include <cctype>

using namespace std;

class Complex {
private:
    long long real;
    long long imaginary;
    bool valid;
public:
    Complex() : real(0), imaginary(0), valid(true) {}
    Complex(long long r, long long i) : real(r), imaginary(i), valid(true) {}

    bool isValid() const { return valid; }

    friend istream& operator>>(istream& is, Complex& c);
    friend ostream& operator<<(ostream& os, const Complex& c);
};

istream& operator>>(istream& is, Complex& c) {
    string line;
    if (!getline(is, line)) {
        return is;
    }
    // Bỏ khoảng trắng
    string s = "";
    for (char ch : line) {
        if (!isspace((unsigned char)ch)) s += ch;
    }
    if (s.empty()) {
        c.valid = false;
        return is;
    }

    // Phân tích cú pháp s
    // Token hóa thành các thành phần: [+/-] a, [+/-] b i
    long long r = 0, im = 0;
    bool has_r = false, has_im = false;
    int n = s.size();
    int i = 0;

    while (i < n) {
        int sign = 1;
        if (s[i] == '+') {
            sign = 1;
            i++;
        } else if (s[i] == '-') {
            sign = -1;
            i++;
        }

        if (i >= n) {
            c.valid = false;
            return is;
        }

        if (s[i] == 'i') {
            // Dạng +i hoặc -i hoặc i
            if (has_im) { c.valid = false; return is; }
            im = sign * 1;
            has_im = true;
            i++;
        } else if (isdigit((unsigned char)s[i])) {
            long long val = 0;
            while (i < n && isdigit((unsigned char)s[i])) {
                val = val * 10 + (s[i] - '0');
                i++;
            }
            val *= sign;
            if (i < n && s[i] == 'i') {
                if (has_im) { c.valid = false; return is; }
                im = val;
                has_im = true;
                i++;
            } else {
                if (has_r) { c.valid = false; return is; }
                r = val;
                has_r = true;
            }
        } else {
            c.valid = false;
            return is;
        }
    }

    c.real = r;
    c.imaginary = im;
    c.valid = true;
    return is;
}

ostream& operator<<(ostream& os, const Complex& c) {
    if (!c.valid) {
        os << "INVALID";
        return os;
    }
    if (c.real == 0 && c.imaginary == 0) {
        os << 0;
    } else if (c.imaginary == 0) {
        os << c.real;
    } else if (c.real == 0) {
        os << c.imaginary << "i";
    } else {
        os << c.real;
        if (c.imaginary > 0) {
            os << " + " << c.imaginary << "i";
        } else {
            os << " - " << -c.imaginary << "i";
        }
    }
    return os;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    Complex c;
    while (cin >> c) {
        cout << c << "\n";
    }
    return 0;
}

#include <iostream>
