class Complex {
private:
    long long real;
    long long imaginary;
    bool ok;
public:
    Complex() : real(0), imaginary(0), ok(true) {}

    bool isOk() const { return ok; }

    static bool parse(const std::string& line, long long& out_r, long long& out_i) {
        std::string s;
        for (char ch : line) {
            if (!std::isspace(static_cast<unsigned char>(ch))) s.push_back(ch);
        }
        if (s.empty()) return false;

        size_t idx = 0;
        size_t len = s.length();
        bool gotReal = false, gotImag = false;
        long long r = 0, im = 0;

        while (idx < len) {
            long long sign = 1;
            if (s[idx] == '+') {
                sign = 1;
                idx++;
            } else if (s[idx] == '-') {
                sign = -1;
                idx++;
            }
            if (idx >= len) return false;

            if (s[idx] == 'i') {
                if (gotImag) return false;
                im = sign;
                gotImag = true;
                idx++;
            } else if (std::isdigit(static_cast<unsigned char>(s[idx]))) {
                long long val = 0;
                while (idx < len && std::isdigit(static_cast<unsigned char>(s[idx]))) {
                    val = val * 10 + (s[idx] - '0');
                    idx++;
                }
                val *= sign;
                if (idx < len && s[idx] == 'i') {
                    if (gotImag) return false;
                    im = val;
                    gotImag = true;
                    idx++;
                } else {
                    if (gotReal) return false;
                    r = val;
                    gotReal = true;
                }
            } else {
                return false;
            }
        }
        out_r = r;
        out_i = im;
        return true;
    }

    friend std::istream& operator>>(std::istream& is, Complex& c) {
        std::string line;
        if (!std::getline(is, line)) return is;
        long long r = 0, i = 0;
        if (parse(line, r, i)) {
            c.real = r;
            c.imaginary = i;
            c.ok = true;
        } else {
            c.ok = false;
        }
        return is;
    }

    friend std::ostream& operator<<(std::ostream& os, const Complex& c) {
        if (!c.ok) {
            return os << "INVALID";
        }
        if (c.real == 0 && c.imaginary == 0) {
            return os << 0;
        }
        if (c.imaginary == 0) {
            return os << c.real;
        }
        if (c.real == 0) {
            return os << c.imaginary << "i";
        }
        os << c.real;
        if (c.imaginary > 0) {
            os << " + " << c.imaginary << "i";
        } else {
            os << " - " << -c.imaginary << "i";
        }
        return os;
    }
};

