    if (step == target) {
        throw target;
    }
    recurse(step + 1, target);
    std::cout << "Exit level " << step << "\n";
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int depth = 0;
    if (std::cin >> depth) {
        if (depth <= 0) {
            std::cout << "No exception thrown\n";
        } else {
            try {
                recurse(1, depth);
            } catch (int ex) {
                std::cout << "Caught exception at depth " << ex << "\n";
            }
        }
    }
    return 0;
}

