template <typename T>
class Array {
private:
    size_t size_;
    T* ptr_;

public:
    explicit Array(size_t size = 10) : size_(size), ptr_(new T[size_]) {}

    Array(const Array& other) : size_(other.size_), ptr_(new T[other.size_]) {
        for (size_t i = 0; i < size_; ++i) {
            ptr_[i] = other.ptr_[i];
        }
    }

    ~Array() {
        delete[] ptr_;
    }

    Array& operator=(const Array& other) {
        if (this != &other) {
            if (size_ != other.size_) {
                delete[] ptr_;
                size_ = other.size_;
                ptr_ = new T[size_];
            }
            for (size_t i = 0; i < size_; ++i) {
                ptr_[i] = other.ptr_[i];
            }
        }
        return *this;
    }

    bool operator==(const Array& other) const {
        if (size_ != other.size_) return false;
        for (size_t i = 0; i < size_; ++i) {
            if (ptr_[i] != other.ptr_[i]) return false;
        }
        return true;
    }

    bool operator!=(const Array& other) const {
        return !(*this == other);
    }

    T& operator[](size_t index) {
        return ptr_[index];
    }

    const T& operator[](size_t index) const {
        return ptr_[index];
    }

    size_t getSize() const {
        return size_;
    }

    friend std::istream& operator>>(std::istream& in, Array& a) {
        for (size_t i = 0; i < a.size_; ++i) {
            in >> a.ptr_[i];
        }
        return in;
    }

    friend std::ostream& operator<<(std::ostream& out, const Array& a) {
        for (size_t i = 0; i < a.size_; ++i) {
            out << a.ptr_[i] << (i + 1 == a.size_ ? "" : " ");
        }
        return out;
    }
};

