template <typename ElementType>
class Array {
private:
    size_t length;
    std::unique_ptr<ElementType[]> data;

public:
    explicit Array(size_t sz = 0) : length(sz), data(sz > 0 ? std::make_unique<ElementType[]>(sz) : nullptr) {}

    Array(const Array& src) : length(src.length), data(src.length > 0 ? std::make_unique<ElementType[]>(src.length) : nullptr) {
        for (size_t i = 0; i < length; ++i) {
            data[i] = src.data[i];
        }
    }

    Array& operator=(const Array& rhs) {
        if (this != &rhs) {
            if (length != rhs.length) {
                length = rhs.length;
                data = length > 0 ? std::make_unique<ElementType[]>(length) : nullptr;
            }
            for (size_t i = 0; i < length; ++i) {
                data[i] = rhs.data[i];
            }
        }
        return *this;
    }

    bool operator==(const Array& rhs) const {
        if (length != rhs.length) return false;
        for (size_t i = 0; i < length; ++i) {
            if (data[i] != rhs.data[i]) return false;
        }
        return true;
    }

    bool operator!=(const Array& rhs) const {
        return !(*this == rhs);
    }

    ElementType& operator[](size_t idx) {
        return data[idx];
    }

    const ElementType& operator[](size_t idx) const {
        return data[idx];
    }

    size_t size() const {
        return length;
    }
};

template <typename T>
std::istream& operator>>(std::istream& is, Array<T>& arr) {
    for (size_t i = 0; i < arr.size(); ++i) {
        is >> arr[i];
