    return is;
}

template <typename T>
std::ostream& operator<<(std::ostream& os, const Array<T>& arr) {
    for (size_t i = 0; i < arr.size(); ++i) {
        if (i > 0) os << " ";
        os << arr[i];
    }
    return os;
}

