using namespace std;

bool canCatch(const string& handler, const string& thrown) {
    if (handler == "...") return true;
    if (handler == "BaseException") return true; // catches Base, Derived, SubDerived
    if (handler == "DerivedException") {
        return (thrown == "DerivedException" || thrown == "SubDerivedException");
    }
    if (handler == "SubDerivedException") {
        return thrown == "SubDerivedException";
    }
    return false;
}

int main() {
