    vector<string> handlers(n);
    for (int i = 0; i < n; ++i) {
        cin >> handlers[i];
    }
    string thrown;
    cin >> thrown;
    for (int i = 0; i < n; ++i) {
        if (canCatch(handlers[i], thrown)) {
            cout << handlers[i] << "\n";
            return 0;
        }
    }
    cout << "UNCAUGHT\n";
    return 0;
}

#include <iostream>
#include <string>

using namespace std;

// Hierarchy representation using numeric levels:
// BaseException = 0, DerivedException = 1, SubDerivedException = 2
int getLevel(const string& s) {
    if (s == "BaseException") return 0;
    if (s == "DerivedException") return 1;
    if (s == "SubDerivedException") return 2;
    return -1;
}

int main() {
    int n;
    if (cin >> n) {
        string h[15];
        for (int i = 0; i < n; ++i) {
            cin >> h[i];
        }
        string thrown;
        cin >> thrown;
        int thrownLevel = getLevel(thrown);

        string matched = "UNCAUGHT";
        for (int i = 0; i < n; ++i) {
            if (h[i] == "...") {
                matched = h[i];
                break;
            }
            int handlerLevel = getLevel(h[i]);
            if (handlerLevel != -1 && thrownLevel >= handlerLevel) {
                matched = h[i];
                break;
            }
        }
        cout << matched << endl;
    }
    return 0;
}

