        } else {
            double x = (e * d - b * f) / denominator;
            double y = (a * f - e * c) / denominator;
            if (std::fabs(x) < 1e-6) x = 0.0;
            if (std::fabs(y) < 1e-6) y = 0.0;
            printf("x is %.1f and y is %.1f\n", x, y);
        }
    }
    return 0;
}

