    double delta = b * b - 4 * a * c;
    const double EPS = 1e-9;

    cout << fixed << setprecision(6);

    if (delta > EPS) {
        double sqrt_d = sqrt(delta);
        double r1 = (-b + sqrt_d) / (2 * a);
        double r2 = (-b - sqrt_d) / (2 * a);
        if (abs(r1) < EPS) r1 = 0.0;
        if (abs(r2) < EPS) r2 = 0.0;
        cout << "The roots are " << r1 << " and " << r2 << "\n";
    } else if (abs(delta) <= EPS) {
        double r = -b / (2 * a);
        if (abs(r) < EPS) r = 0.0;
        cout << "The root is " << r << "\n";
    } else {
        cout << "The equation has no real roots\n";
    }

    return 0;
}

