using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double x1, y1, x2, y2, x3, y3, x4, y4;
    if (!(cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3 >> x4 >> y4)) {
        return 0;
    }

    double a = y1 - y2;
    double b = -(x1 - x2);
    double c = y3 - y4;
    double d = -(x3 - x4);

    double e = a * x1 + b * y1;
    double f = c * x3 + d * y3;

    double det = a * d - b * c;

    if (fabs(det) < 1e-9) {
        cout << "The two lines are parallel\n";
    } else {
        double x = (e * d - b * f) / det;
        double y = (a * f - e * c) / det;
        // Avoid -0.00000 in output
        if (fabs(x) < 1e-9) x = 0.0;
        if (fabs(y) < 1e-9) y = 0.0;
        cout << fixed << setprecision(5);
        cout << "The intersecting point is at (" << x << ", " << y << ")\n";
    }

    return 0;
}

