    double minY1 = y1 - h1 / 2.0;
    double maxY1 = y1 + h1 / 2.0;

    // Tọa độ các cạnh của r2
    double minX2 = x2 - w2 / 2.0;
    double maxX2 = x2 + w2 / 2.0;
    double minY2 = y2 - h2 / 2.0;
    double maxY2 = y2 + h2 / 2.0;

    const double EPS = 1e-9;

    // Kiểm tra r2 có nằm trong r1 không
    if (minX2 >= minX1 - EPS && maxX2 <= maxX1 + EPS &&
        minY2 >= minY1 - EPS && maxY2 <= maxY1 + EPS) {
        cout << "r2 is inside r1\n";
    }
    // Kiểm tra r2 có giao/chạm với r1 không
    else if (minX1 <= maxX2 + EPS && maxX1 >= minX2 - EPS &&
             minY1 <= maxY2 + EPS && maxY1 >= minY2 - EPS) {
        cout << "r2 overlaps r1\n";
    }
    else {
        cout << "r2 does not overlap r1\n";
    }

    return 0;
}

