        double dx = std::abs(x1 - x2);
        double dy = std::abs(y1 - y2);
        const double EPS = 1e-9;

        // Điều kiện r2 hoàn toàn trong r1:
        // Khoảng cách giữa 2 tâm theo trục x <= (w1 - w2) / 2 và w2 <= w1 (tương tự cho y)
        bool insideX = (w2 <= w1 + EPS) && (dx <= (w1 - w2) / 2.0 + EPS);
        bool insideY = (h2 <= h1 + EPS) && (dy <= (h1 - h2) / 2.0 + EPS);

        if (insideX && insideY) {
            cout << "r2 is inside r1\n";
        } else {
            // Điều kiện giao nhau: khoảng cách giữa 2 tâm <= (w1 + w2) / 2 theo cả 2 chiều
            bool overlapX = dx <= (w1 + w2) / 2.0 + EPS;
            bool overlapY = dy <= (h1 + h2) / 2.0 + EPS;
            if (overlapX && overlapY) {
                cout << "r2 overlaps r1\n";
            } else {
                cout << "r2 does not overlap r1\n";
            }
        }
    }
