using namespace std;

const double PI = std::acos(-1.0);

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double r, a1, a2, a3;
    if (!(cin >> r >> a1 >> a2 >> a3)) return 0;

    double x1 = r * cos(a1), y1 = r * sin(a1);
    double x2 = r * cos(a2), y2 = r * sin(a2);
    double x3 = r * cos(a3), y3 = r * sin(a3);

    // Lengths of sides: a opposite to (x1, y1), b opposite to (x2, y2), c opposite to (x3, y3)
    double a = hypot(x2 - x3, y2 - y3);
    double b = hypot(x1 - x3, y1 - y3);
    double c = hypot(x1 - x2, y1 - y2);

    // Law of cosines to find angles
    auto get_angle = [](double opp, double adj1, double adj2) {
        double cos_val = (adj1 * adj1 + adj2 * adj2 - opp * opp) / (2.0 * adj1 * adj2);
        cos_val = max(-1.0, min(1.0, cos_val));
        return acos(cos_val) * 180.0 / PI;
    };

    vector<double> angles = {
        get_angle(a, b, c),
        get_angle(b, a, c),
        get_angle(c, a, b)
    };

    sort(angles.begin(), angles.end());

    cout << fixed << setprecision(2);
    cout << angles[0] << " " << angles[1] << " " << angles[2] << "\n";

    return 0;
}

