    double r, a[3];
    if (!(cin >> r >> a[0] >> a[1] >> a[2])) return 0;

    const double PI = atan2(0.0, -1.0);

    // Sort the angles in increasing order along the circle
    sort(a, a + 3);

    // Arc lengths (subtended central angles)
    double arc1 = a[1] - a[0];
    double arc2 = a[2] - a[1];
    double arc3 = 2.0 * PI - (arc1 + arc2);

    // Inscribed angle theorem: an inscribed angle is half of the subtended arc angle
    vector<double> angles = {
        arc1 * 0.5 * (180.0 / PI),
        arc2 * 0.5 * (180.0 / PI),
        arc3 * 0.5 * (180.0 / PI)
    };

    sort(angles.begin(), angles.end());

    cout << fixed << setprecision(2);
    cout << angles[0] << " " << angles[1] << " " << angles[2] << "\n";

    return 0;
}

