    if (scanf("%lf", &r) != 1) return 0;

    double pi = 3.14159265358979323846;
    double d_theta = 2.0 * pi / 5.0;
    double start_theta = pi / 2.0 - d_theta;

    for (int i = 0; i < 5; ++i) {
        double theta = start_theta + i * d_theta;
        double x = r * std::cos(theta);
        double y = r * std::sin(theta);
        if (std::abs(x) < 1e-5) x = 0.0;
        if (std::abs(y) < 1e-5) y = 0.0;
        std::printf("(%.4f, %.4f)\n", x, y);
    }
    return 0;
}

