#include <iostream>
#include <string>

using namespace std;

void printPatternA(int n) {
    if (n == 1) {
        cout << 1 << "\n";
        return;
    }
    for (int j = 1; j <= n; ++j) cout << j;
    cout << "\n";
    for (int i = 2; i < n; ++i) {
        cout << 1;
        for (int s = 0; s < n - 2; ++s) cout << ' ';
        cout << n << "\n";
    }
    for (int j = 1; j <= n; ++j) cout << j;
    cout << "\n";
}

void printPatternB(int n) {
    for (int i = 1; i <= n; ++i) {
        int spaces = (n - i) * 2;
        for (int s = 0; s < spaces; ++s) cout << ' ';
        int count = 2 * i - 1;
        for (int j = 1; j <= count; ++j) {
            cout << j << (j == count ? "" : " ");
        }
        cout << "\n";
    }
}

void printPatternC(int n) {
    int totalLines = 2 * n - 1;
    for (int row = 1; row <= totalLines; ++row) {
        int k = (row <= n) ? row : (2 * n - row);
        int spaces = (n - k) * 2;
        for (int s = 0; s < spaces; ++s) cout << ' ';
        for (int j = 1; j <= k; ++j) {
            cout << 3 << (j == k ? "" : " ");
        }
        cout << "\n";
    }
}

void printPatternD(int n) {
    for (int i = 1; i <= n; ++i) {
        int spaces = (n - i) * 2;
        for (int s = 0; s < spaces; ++s) cout << ' ';
        for (int j = 1; j <= i; ++j) {
            cout << j << (j == i ? "" : " ");
        }
        cout << "\n";
    }
}

