    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    char t;
    int n;
    if (cin >> t >> n) {
        if (t == 'A') printPatternA(n);
        else if (t == 'B') printPatternB(n);
        else if (t == 'C') printPatternC(n);
        else if (t == 'D') printPatternD(n);
    }
    return 0;
}

