int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    char patternType;
    int n;
    if (!(cin >> patternType >> n)) return 0;

    switch (patternType) {
        case 'A': {
            for (int r = 1; r <= n; ++r) {
                if (r == 1 || r == n) {
                    for (int c = 1; c <= n; ++c) cout << c;
                } else {
                    cout << 1;
                    cout << string(n - 2, ' ');
                    cout << n;
                }
                cout << "\n";
            }
            break;
        }
        case 'B': {
            for (int r = 1; r <= n; ++r) {
                cout << string((n - r) * 2, ' ');
                int limit = 2 * r - 1;
                for (int v = 1; v <= limit; ++v) {
                    if (v > 1) cout << ' ';
                    cout << v;
                }
                cout << "\n";
            }
            break;
        }
        case 'C': {
            for (int r = 1; r <= 2 * n - 1; ++r) {
                int numThrees = (r <= n) ? r : (2 * n - r);
                cout << string((n - numThrees) * 2, ' ');
                for (int v = 1; v <= numThrees; ++v) {
                    if (v > 1) cout << ' ';
                    cout << 3;
                }
                cout << "\n";
            }
            break;
        }
        case 'D': {
            for (int r = 1; r <= n; ++r) {
                cout << string((n - r) * 2, ' ');
                for (int v = 1; v <= r; ++v) {
                    if (v > 1) cout << ' ';
                    cout << v;
                }
                cout << "\n";
            }
            break;
        }
    }
    return 0;
}

