double averageDigits(long long n) {
    if (n == 0) return 0.0;
    if (n < 0) {
        // Handle negative numbers; avoid overflow if n == LLONG_MIN
        // In C++, LLONG_MIN is -9223372036854775808, abs fits in unsigned long long
    }
    unsigned long long temp = (n < 0) ? -(unsigned long long)n : (unsigned long long)n;
    long long sum = 0;
    int count = 0;
    while (temp > 0) {
        sum += (temp % 10);
        count++;
        temp /= 10;
    }
    return (double)sum / count;
}

