using namespace std;

bool isArmstrong(long long num) {
    if (num <= 0) return false;
    long long temp = num;
    int k = 0;
    while (temp > 0) {
        k++;
        temp /= 10;
    }
    temp = num;
    long long sum = 0;
    while (temp > 0) {
        int d = temp % 10;
        long long p = 1;
        for (int i = 0; i < k; ++i) {
            p *= d;
        }
        sum += p;
        temp /= 10;
    }
    return sum == num;
}

long long reverseNumber(long long num) {
    long long rev = 0;
    while (num > 0) {
        rev = rev * 10 + (num % 10);
        num /= 10;
    }
    return rev;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long n;
    if (cin >> n) {
        if (!isArmstrong(n)) {
            cout << "NOT ARMSTRONG\n";
        } else {
            long long rev = reverseNumber(n);
            if (isArmstrong(rev)) {
                cout << "REVERSE ARMSTRONG\n";
            } else {
                cout << "ARMSTRONG\n";
            }
        }
    }
    return 0;
}

