bool checkArmstrong(long long val) {
    if (val <= 0) return false;
    vector<int> digits;
    long long t = val;
    while (t > 0) {
        digits.push_back(t % 10);
        t /= 10;
    }
    int len = digits.size();
    long long total = 0;
    for (int d : digits) {
        long long term = 1;
        for (int i = 0; i < len; ++i) {
            term *= d;
        }
        total += term;
    }
    return total == val;
}

