double computeTax(int status, double taxableIncome) {
    double brackets[4][5] = {
        {8350, 33950, 82250, 171550, 372950},
        {16700, 67900, 137050, 208850, 372950},
        {8350, 33950, 68525, 104425, 186475},
        {11950, 45500, 117450, 190200, 372950}
    };
    double rates[6] = {0.10, 0.15, 0.25, 0.28, 0.33, 0.35};

    double tax = 0.0;
    if (taxableIncome <= brackets[status][0]) {
        tax = taxableIncome * rates[0];
    } else if (taxableIncome <= brackets[status][1]) {
        tax = brackets[status][0] * rates[0] + (taxableIncome - brackets[status][0]) * rates[1];
    } else if (taxableIncome <= brackets[status][2]) {
        tax = brackets[status][0] * rates[0] + (brackets[status][1] - brackets[status][0]) * rates[1] + (taxableIncome - brackets[status][1]) * rates[2];
    } else if (taxableIncome <= brackets[status][3]) {
        tax = brackets[status][0] * rates[0] + (brackets[status][1] - brackets[status][0]) * rates[1] + (brackets[status][2] - brackets[status][1]) * rates[2] + (taxableIncome - brackets[status][2]) * rates[3];
    } else if (taxableIncome <= brackets[status][4]) {
        tax = brackets[status][0] * rates[0] + (brackets[status][1] - brackets[status][0]) * rates[1] + (brackets[status][2] - brackets[status][1]) * rates[2] + (brackets[status][3] - brackets[status][2]) * rates[3] + (taxableIncome - brackets[status][3]) * rates[4];
    } else {
        tax = brackets[status][0] * rates[0] + (brackets[status][1] - brackets[status][0]) * rates[1] + (brackets[status][2] - brackets[status][1]) * rates[2] + (brackets[status][3] - brackets[status][2]) * rates[3] + (brackets[status][4] - brackets[status][3]) * rates[4] + (taxableIncome - brackets[status][4]) * rates[5];
    }
    return tax;
}

