#include <cmath>

using namespace std;

struct TaxBracket {
    vector<double> limits;
    vector<double> rates = {0.10, 0.15, 0.25, 0.28, 0.33, 0.35};
};

double computeTax(int status, double taxableIncome) {
    static const double limits[4][5] = {
        {8350, 33950, 82250, 171550, 372950},
        {16700, 67900, 137050, 208850, 372950},
        {8350, 33950, 68525, 104425, 186475},
        {11950, 45500, 117450, 190200, 372950}
    };
    static const double rates[6] = {0.10, 0.15, 0.25, 0.28, 0.33, 0.35};

    double tax = 0.0;
    double prev = 0.0;
    for (int i = 0; i < 5; ++i) {
        if (taxableIncome > limits[status][i]) {
            tax += (limits[status][i] - prev) * rates[i];
            prev = limits[status][i];
        } else {
            tax += (taxableIncome - prev) * rates[i];
            return tax;
        }
    }
    tax += (taxableIncome - prev) * rates[5];
    return tax;
}

