    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long fromInc, toInc, step;
    if (cin >> fromInc >> toInc >> step) {
        for (long long income = fromInc; income <= toInc; income += step) {
            cout << income;
            for (int status = 0; status < 4; ++status) {
                cout << " " << (long long)std::round(computeTax(status, (double)income));
            }
            cout << "\n";
        }
    }
    return 0;
}

