using namespace std;

const double EPS = 1e-9;

bool onTheLineSegment(double x0, double y0, double x1, double y1, double x2, double y2) {
    double cross = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    if (abs(cross) > EPS) return false;
    return (x2 >= min(x0, x1) - EPS && x2 <= max(x0, x1) + EPS) &&
           (y2 >= min(y0, y1) - EPS && y2 <= max(y0, y1) + EPS);
}

bool onTheSameLine(double x0, double y0, double x1, double y1, double x2, double y2) {
    double cross = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return abs(cross) <= EPS;
}

bool leftOfTheLine(double x0, double y0, double x1, double y1, double x2, double y2) {
    double cross = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return cross > EPS;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    double x0, y0, x1, y1, x2, y2;
    if (cin >> x0 >> y0 >> x1 >> y1 >> x2 >> y2) {
        cout << fixed << setprecision(1);
        if (onTheLineSegment(x0, y0, x1, y1, x2, y2)) {
            cout << "(" << x2 << ", " << y2 << ") is on the line segment from (" 
                 << x0 << ", " << y0 << ") to (" << x1 << ", " << y1 << ")\n";
        } else if (onTheSameLine(x0, y0, x1, y1, x2, y2)) {
            cout << "(" << x2 << ", " << y2 << ") is on the same line from (" 
                 << x0 << ", " << y0 << ") to (" << x1 << ", " << y1 << ")\n";
        } else if (leftOfTheLine(x0, y0, x1, y1, x2, y2)) {
            cout << "(" << x2 << ", " << y2 << ") is on the left side of the line from (" 
                 << x0 << ", " << y0 << ") to (" << x1 << ", " << y1 << ")\n";
        } else {
            cout << "(" << x2 << ", " << y2 << ") is on the right side of the line from (" 
                 << x0 << ", " << y0 << ") to (" << x1 << ", " << y1 << ")\n";
        }
    }
    return 0;
}

