static const int MAX_VAL = 200000;
bool prime[MAX_VAL + 1];

void sieve() {
    for (int i = 0; i <= MAX_VAL; ++i) prime[i] = true;
    prime[0] = prime[1] = false;
    for (int p = 2; p * p <= MAX_VAL; ++p) {
        if (prime[p]) {
            for (int i = p * p; i <= MAX_VAL; i += p)
                prime[i] = false;
        }
    }
}

int digitSum(int val) {
    int ans = 0;
    while (val > 0) {
        ans += val % 10;
        val /= 10;
    }
    return ans;
}

