double babylonianSqrt(int n) {
    double lastGuess = 1.0;
    while (true) {
        double nextGuess = (lastGuess + (static_cast<double>(n) / lastGuess)) / 2.0;
        if (std::abs(nextGuess - lastGuess) < 0.0001) {
            return nextGuess;
        }
        lastGuess = nextGuess;
    }
}

