int main() {
    unsigned long long n;
    if (!(std::cin >> n)) return 0;

    std::vector<int> digits;
    if (n == 0) {
        digits.push_back(0);
    } else {
        unsigned long long temp = n;
        while (temp > 0) {
            digits.push_back(temp % 10);
            temp /= 10;
        }
    }

    // Đảo lại để thành thứ tự từ trái sang phải
    // digits[0] là chữ số bên phải, đảo lại:
    int len = digits.size();
    long long sumEven = 0;
    int countEven = 0;

    // Vị trí 1-based từ trái sang phải: i = 1, 2, ..., len
    // Vị trí chẵn là i = 2, 4, ...
    // Trong vector đảo (0-based từ trái): index 1, 3, 5, ...
    for (int i = 0; i < len; ++i) {
        int original_idx = len - 1 - i; // từ trái sang phải: i = 0 là chữ số đầu tiên
        int pos = i + 1;
        if (pos % 2 == 0) {
            sumEven += digits[original_idx];
            countEven++;
        }
    }

    double result = 0.0;
    if (countEven > 0) {
        result = (double)sumEven / countEven;
