using namespace std;

bool isLeapYear(long long year) {
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long t;
    if (!(cin >> t)) return 0;

    long long second = t % 60;
    long long totalMinutes = t / 60;
    long long minute = totalMinutes % 60;
    long long totalHours = totalMinutes / 60;
    long long hour = totalHours % 24;
    long long totalDays = totalHours / 24;

    long long year = 1970;
    while (true) {
        long long daysInYear = isLeapYear(year) ? 366 : 365;
        if (totalDays >= daysInYear) {
            totalDays -= daysInYear;
            year++;
        } else {
            break;
        }
    }

    int daysInMonth[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (isLeapYear(year)) {
        daysInMonth[1] = 29;
    }

    string monthNames[] = {"January", "February", "March", "April", "May", "June", 
                           "July", "August", "September", "October", "November", "December"};

    int month = 0;
    while (month < 12 && totalDays >= daysInMonth[month]) {
        totalDays -= daysInMonth[month];
        month++;
    }

    long long day = totalDays + 1;

    cout << "Current date and time is " << monthNames[month] << " " << day << ", " << year << " ";
    cout << setfill('0') << setw(2) << hour << ":"
         << setw(2) << minute << ":"
         << setw(2) << second << "\n";

    return 0;
}

