    if (scanf("%lld", &totalSec) != 1) return 0;

    long long sec = totalSec % 60;
    long long totalMin = totalSec / 60;
    long long min = totalMin % 60;
    long long totalHr = totalMin / 60;
    long long hr = totalHr % 24;
    long long days = totalHr / 24;

    long long curYear = 1970;
    while (true) {
        long long d = checkLeap(curYear) ? 366 : 365;
        if (days >= d) {
            days -= d;
            curYear++;
        } else {
            break;
        }
    }

    int mDays[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (checkLeap(curYear)) mDays[1] = 29;

    int curMonth = 0;
    for (int i = 0; i < 12; ++i) {
        if (days >= mDays[i]) {
            days -= mDays[i];
        } else {
            curMonth = i;
            break;
        }
    }
    long long curDay = days + 1;

    printf("Current date and time is %s %lld, %lld %02lld:%02lld:%02lld\n",
           MONTHS[curMonth], curDay, curYear, hr, min, sec);
