int dec2Octal(const int& decimal) {
    if (decimal == 0) {
        return 0;
    }
    int n = decimal;
    long long octal = 0;
    long long place = 1;
    while (n > 0) {
        int rem = n % 8;
        octal += rem * place;
        place *= 10;
        n /= 8;
    }
    return static_cast<int>(octal);
}

