#include <cmath>

using namespace std;

bool solveEquation(double a, double b, double c, double d, double e, double f, double& x, double& y) {
    double det = a * d - b * c;
    if (fabs(det) < 1e-9) {
        return false;
    }
    x = (e * d - b * f) / det;
    y = (a * f - e * c) / det;
    return true;
}

bool onSegment(double x, double y, double x1, double y1, double x2, double y2) {
    const double eps = 1e-7;
    return (x >= min(x1, x2) - eps && x <= max(x1, x2) + eps &&
            y >= min(y1, y2) - eps && y <= max(y1, y2) + eps);
}

void intersectPoint(double x1, double y1, double x2, double y2,
                    double x3, double y3, double x4, double y4,
                    double& x, double& y, bool& isIntersecting) {
    double a = y1 - y2;
    double b = -(x1 - x2);
    double e = (y1 - y2) * x1 - (x1 - x2) * y1;

    double c = y3 - y4;
    double d = -(x3 - x4);
    double f = (y3 - y4) * x3 - (x3 - x4) * y3;

    if (solveEquation(a, b, c, d, e, f, x, y)) {
        if (onSegment(x, y, x1, y1, x2, y2) && onSegment(x, y, x3, y3, x4, y4)) {
            isIntersecting = true;
            return;
        }
    }
    isIntersecting = false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double x1, y1, x2, y2, x3, y3, x4, y4;
    if (cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3 >> x4 >> y4) {
        double x = 0, y = 0;
        bool isIntersecting = false;
        intersectPoint(x1, y1, x2, y2, x3, y3, x4, y4, x, y, isIntersecting);

        if (isIntersecting) {
            // Fix negative zero display
            if (fabs(x) < 1e-7) x = 0.0;
            if (fabs(y) < 1e-7) y = 0.0;
            cout << fixed << setprecision(4);
            cout << "The intersecting point is: (" << x << ", " << y << ")\n";
        } else {
            cout << "The two lines do not cross\n";
        }
    }
    return 0;
}

#include <cstdio>
#include <algorithm>
#include <cmath>

struct Point {
    double x, y;
};

int main() {
    Point p1, p2, p3, p4;
    if (scanf("%lf %lf %lf %lf %lf %lf %lf %lf", 
              &p1.x, &p1.y, &p2.x, &p2.y, &p3.x, &p3.y, &p4.x, &p4.y) != 8) {
        return 0;
    }

    double a = p1.y - p2.y;
    double b = p2.x - p1.x;
    double e = a * p1.x + b * p1.y;

    double c = p3.y - p4.y;
    double d = p4.x - p3.x;
    double f = c * p3.x + d * p3.y;

    double det = a * d - b * c;
    const double EPS = 1e-9;
    const double BOX_EPS = 1e-7;

    if (std::abs(det) < EPS) {
        std::printf("The two lines do not cross\n");
        return 0;
    }

    double ix = (e * d - b * f) / det;
    double iy = (a * f - e * c) / det;

    bool in1 = (ix >= std::min(p1.x, p2.x) - BOX_EPS && ix <= std::max(p1.x, p2.x) + BOX_EPS &&
                iy >= std::min(p1.y, p2.y) - BOX_EPS && iy <= std::max(p1.y, p2.y) + BOX_EPS);
    bool in2 = (ix >= std::min(p3.x, p4.x) - BOX_EPS && ix <= std::max(p3.x, p4.x) + BOX_EPS &&
                iy >= std::min(p3.y, p4.y) - BOX_EPS && iy <= std::max(p3.y, p4.y) + BOX_EPS);

    if (in1 && in2) {
        if (std::abs(ix) < 1e-7) ix = 0.0;
        if (std::abs(iy) < 1e-7) iy = 0.0;
        std::printf("The intersecting point is: (%.4f, %.4f)\n", ix, iy);
    } else {
        std::printf("The two lines do not cross\n");
    }

    return 0;
}

