#include <iostream>
#include <string>

using namespace std;

int getDigit(int number) {
    if (number < 10) return number;
    return number / 10 + number % 10;
}

int sumOfDoubleEvenPlace(const string& cardNumber) {
    int sum = 0;
    int n = cardNumber.length();
    for (int i = n - 2; i >= 0; i -= 2) {
        sum += getDigit((cardNumber[i] - '0') * 2);
    }
    return sum;
}

int sumOfOddPlace(const string& cardNumber) {
    int sum = 0;
    int n = cardNumber.length();
    for (int i = n - 1; i >= 0; i -= 2) {
        sum += (cardNumber[i] - '0');
    }
    return sum;
}

bool startsWith(const string& cardNumber, const string& prefix) {
    if (cardNumber.length() < prefix.length()) return false;
    return cardNumber.compare(0, prefix.length(), prefix) == 0;
}

bool isValid(const string& cardNumber) {
    int len = cardNumber.length();
    if (len < 13 || len > 16) return false;

    bool validPrefix = startsWith(cardNumber, "4") ||
                       startsWith(cardNumber, "5") ||
                       startsWith(cardNumber, "37") ||
                       startsWith(cardNumber, "6");
    if (!validPrefix) return false;

    int totalSum = sumOfDoubleEvenPlace(cardNumber) + sumOfOddPlace(cardNumber);
    return (totalSum % 10 == 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string cardNumber;
    if (cin >> cardNumber) {
        if (isValid(cardNumber)) {
            cout << "VALID\n";
        } else {
            cout << "INVALID\n";
        }
    }
    return 0;
}

