using namespace std;

string octal2Binary(const int& octalNumber) {
    if (octalNumber == 0) return "0";

    // Đổi số bát phân sang giá trị thập phân trước
    long long decimalVal = 0;
    long long base = 1;
    int temp = octalNumber;
    while (temp > 0) {
        int digit = temp % 10;
        decimalVal += digit * base;
        base *= 8;
        temp /= 10;
    }

    // Đổi từ thập phân sang chuỗi nhị phân
    string bin = "";
    while (decimalVal > 0) {
        bin += (decimalVal % 2 == 1 ? '1' : '0');
        decimalVal /= 2;
    }
    reverse(bin.begin(), bin.end());
    return bin.empty() ? "0" : bin;
}

