    }

    if (first_one == -1) {
        cout << 0 << "\n";
        return 0;
    }

    s = s.substr(first_one);
    int rem = s.size() % 3;
    if (rem != 0) {
        s = string(3 - rem, '0') + s;
    }

    string octal = "";
    for (size_t i = 0; i < s.size(); i += 3) {
        int val = (s[i] - '0') * 4 + (s[i + 1] - '0') * 2 + (s[i + 2] - '0');
        octal.push_back((char)('0' + val));
    }

    cout << octal << "\n";
    return 0;
}

