    cin.tie(NULL);

    long long totalSeconds;
    if (!(cin >> totalSeconds)) return 0;

    long long totalDays = totalSeconds / 86400LL;

    long long year = 1970;
    while (true) {
        long long daysInYear = isLeapYear(year) ? 366 : 365;
        if (totalDays >= daysInYear) {
            totalDays -= daysInYear;
            year++;
        } else {
