using namespace std;

double mean(const double x[], int size) {
    double sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += x[i];
    }
    return sum / size;
}

double deviation(const double x[], int size) {
    double m = mean(x, size);
    double sumSqDiff = 0;
    for (int i = 0; i < size; ++i) {
        sumSqDiff += (x[i] - m) * (x[i] - m);
    }
    return std::sqrt(sumSqDiff / (size - 1));
}

