#include <utility>

void bubbleSortVector(std::vector<double>& a) {
    int n = static_cast<int>(a.size());
    bool swapped = true;
    while (swapped) {
        swapped = false;
        for (int i = 0; i < n - 1; ++i) {
            if (a[i] > a[i + 1]) {
                std::swap(a[i], a[i + 1]);
                swapped = true;
            }
        }
        --n;
    }
}

