    for (int c = 1; c <= 8; ++c) {
        if (!usedCol[c] && !usedDiag1[r - c + 8] && !usedDiag2[r + c]) {
            col[r] = c;
            usedCol[c] = usedDiag1[r - c + 8] = usedDiag2[r + c] = true;
            backtrack(r + 1);
            usedCol[c] = usedDiag1[r - c + 8] = usedDiag2[r + c] = false;
        }
    }
}

