    int max_height = 0;
    for (int count : slots) {
        if (count > max_height) {
            max_height = count;
        }
    }

    for (int h = max_height; h >= 1; --h) {
        string line = "";
        for (int i = 0; i < k; ++i) {
            if (slots[i] >= h) {
                line += 'O';
            } else {
                line += ' ';
            }
        }
        cout << line << "\n";
    }

    return 0;
}

