void merge(const std::vector<long long>& list1, const std::vector<long long>& list2, std::vector<long long>& list3) {
    int i = 0, j = 0;
    int n1 = list1.size();
    int n2 = list2.size();
    while (i < n1 && j < n2) {
        if (list1[i] <= list2[j]) {
            list3.push_back(list1[i++]);
        } else {
            list3.push_back(list2[j++]);
        }
    }
    while (i < n1) {
        list3.push_back(list1[i++]);
    }
    while (j < n2) {
        list3.push_back(list2[j++]);
    }
}

