// Calculate area of triangle formed by (x0, y0), (x1, y1), (x2, y2)
double triangleArea(double x0, double y0, double x1, double y1, double x2, double y2) {
    return 0.5 * abs((x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0));
}

int main() {
