    }

    // Sum of areas of triangles (p0, p1, p2), (p0, p2, p3), (p0, p3, p4), (p0, p4, p5)
    double totalArea = 0.0;
    for (int i = 1; i <= 4; ++i) {
        totalArea += triangleArea(x[0], y[0], x[i], y[i], x[i + 1], y[i + 1]);
    }

    cout << fixed << setprecision(2) << totalArea << "\n";
    return 0;
}

