using namespace std;

int partition(int list[], int size) {
    if (size <= 1) return 0;
    int pivot = list[0];
    int low = 1;
    int high = size - 1;

    while (high > low) {
        while (low <= high && list[low] <= pivot) {
            low++;
        }
        while (high >= low && list[high] > pivot) {
            high--;
        }
        if (high > low) {
            swap(list[low], list[high]);
        }
    }

    while (high >= low && list[high] > pivot) {
        high--;
    }

    if (high >= 0 && pivot > list[high]) {
        list[0] = list[high];
        list[high] = pivot;
        return high;
    } else {
        return 0;
    }
}

