int partition(int a[], int n) {
    if (n <= 1) return 0;
    int pivot = a[0];
    int low = 1, high = n - 1;
    while (high > low) {
        while (low <= high && a[low] <= pivot) low++;
        while (high >= low && a[high] > pivot) high--;
        if (high > low) {
            int temp = a[low];
            a[low] = a[high];
            a[high] = temp;
        }
    }
    while (high >= 1 && a[high] > pivot) high--;
    if (high >= 1 && a[0] > a[high]) {
        swap(a[0], a[high]);
        return high;
    }
    return 0;
}

