int isPalindrome(const char s[]) {
    int len = 0;
    while (s[len] != '\0') {
        len++;
    }
    int left = 0, right = len - 1;
    while (left < right) {
        if (s[left] != s[right]) {
            return -1;
        }
        left++;
        right--;
    }
    return len;
}

