void swapCase(const char s1[], char s2[]) {
    int i = 0;
    while (s1[i] != '\0') {
        if (std::isupper(static_cast<unsigned char>(s1[i]))) {
            s2[i] = static_cast<char>(std::tolower(static_cast<unsigned char>(s1[i])));
        } else if (std::islower(static_cast<unsigned char>(s1[i]))) {
            s2[i] = static_cast<char>(std::toupper(static_cast<unsigned char>(s1[i])));
        } else {
            s2[i] = s1[i];
        }
        i++;
    }
    s2[i] = '\0';
}

