void swapCase(const char s1[], char s2[]) {
    int idx = 0;
    for (; s1[idx] != '\0'; ++idx) {
        char c = s1[idx];
        if (c >= 'a' && c <= 'z') {
            s2[idx] = c - 'a' + 'A';
        } else if (c >= 'A' && c <= 'Z') {
            s2[idx] = c - 'A' + 'a';
        } else {
            s2[idx] = c;
        }
    }
    s2[idx] = '\0';
}

