void itoaUse(int value, char s[], int radix) {
    if (value == 0) {
        s[0] = '0';
        s[1] = '\0';
        return;
    }
    int idx = 0;
    bool negative = false;
    long long val = value;
    if (val < 0) {
        negative = true;
        val = -val;
    }
    while (val > 0) {
        int rem = val % radix;
        s[idx++] = (rem < 10) ? ('0' + rem) : ('a' + rem - 10);
        val /= radix;
    }
    if (negative) {
        s[idx++] = '-';
    }
    s[idx] = '\0';
    std::reverse(s, s + idx);
}

