void itoaUse(int value, char s[], int radix) {
    if (value == 0) {
        s[0] = '0';
        s[1] = '\0';
        return;
    }
    bool negative = false;
    long long val = value;
    if (val < 0) {
        negative = true;
        val = -val;
    }
    int idx = 0;
    while (val > 0) {
        int rem = val % radix;
        if (rem < 10) {
            s[idx++] = '0' + rem;
        } else {
            s[idx++] = 'A' + (rem - 10);
        }
        val /= radix;
    }
    if (negative) {
        s[idx++] = '-';
    }
    s[idx] = '\0';
    // Đảo ngược chuỗi
    for (int i = 0, j = idx - 1; i < j; ++i, --j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
    }
}

