using namespace std;

void octal2Binary(const string& octal, string& binary) {
    if (octal == "0") {
        binary = "0";
        return;
    }
    binary = "";
    for (char c : octal) {
        int val = c - '0';
        binary += (val & 4) ? '1' : '0';
        binary += (val & 2) ? '1' : '0';
        binary += (val & 1) ? '1' : '0';
    }
    // Bỏ qua các số 0 ở đầu
    size_t firstOne = binary.find('1');
    if (firstOne != string::npos) {
        binary = binary.substr(firstOne);
    } else {
        binary = "0";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string octal;
    if (cin >> octal) {
        string binary;
        octal2Binary(octal, binary);
        cout << binary << "\n";
    }
    return 0;
}

