#include <iostream>

using namespace std;

bool isLeapYear(long long year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

int getDaysInMonth(long long year, int month) {
    static const int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && isLeapYear(year)) return 29;
    return days[month];
}

void solve(long long elapseTime) {
    long long totalDays = elapseTime / 86400LL;
    long long year = 1970;
    while (true) {
        long long daysInCurYear = isLeapYear(year) ? 366 : 365;
        if (totalDays >= daysInCurYear) {
            totalDays -= daysInCurYear;
            year++;
        } else {
            break;
        }
    }
    int month = 1;
    while (true) {
        int dim = getDaysInMonth(year, month);
        if (totalDays >= dim) {
            totalDays -= dim;
            month++;
        } else {
            break;
        }
    }
    long long day = totalDays + 1;
    cout << year << " " << month << " " << day << "\n";
}

