using namespace std;

class Date {
private:
    long long year;
    int month;
    int day;

    static bool isLeap(long long y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    static int daysOfMonth(long long y, int m) {
        switch (m) {
            case 2: return isLeap(y) ? 29 : 28;
            case 4: case 6: case 9: case 11: return 30;
            default: return 31;
        }
    }

public:
    Date(long long elapseTime) {
        setDate(elapseTime);
    }

    void setDate(long long elapseTime) {
        long long days = elapseTime / 86400LL;
        year = 1970;
        while (true) {
            long long d = isLeap(year) ? 366 : 365;
            if (days >= d) {
                days -= d;
                year++;
            } else {
                break;
            }
        }
        month = 1;
        while (true) {
            int d = daysOfMonth(year, month);
            if (days >= d) {
                days -= d;
                month++;
            } else {
                break;
            }
        }
        day = (int)days + 1;
    }

    long long getYear() const { return year; }
    int getMonth() const { return month; }
    int getDay() const { return day; }
};

