        if (eq.isSolvable()) {
            double x = eq.getX();
            double y = eq.getY();
            if (std::abs(x) < 1e-9) x = 0.0;
            if (std::abs(y) < 1e-9) y = 0.0;
            std::cout << std::fixed << std::setprecision(4) << x << " " << y << "\n";
        } else {
            std::cout << "The equation has no solution.\n";
        }
    }
    return 0;
}

