struct System2x2 {
    double a, b, c, d, e, f;

    double determinant() const {
        return a * d - b * c;
    }

    bool solvable() const {
        return std::abs(determinant()) > 1e-9;
    }

    double solveX() const {
        return (e * d - b * f) / determinant();
    }

    double solveY() const {
        return (a * f - e * c) / determinant();
    }
};

int main() {
