bool isAnagram(const std::string& s1, const std::string& s2) {
    if (s1.length() != s2.length()) return false;
    std::unordered_map<char, int> count;
    for (char c : s1) {
        count[c]++;
    }
    for (char c : s2) {
        auto it = count.find(c);
        if (it == count.end() || it->second == 0) {
            return false;
        }
        it->second--;
    }
    return true;
}

