            int j = i + 3;
            bool found = false;
            while (j + 2 < n) {
                string codon = s.substr(j, 3);
                if (isEnd(codon)) {
                    genes.push_back(s.substr(i + 3, j - (i + 3)));
                    i = j + 3;
