#include <iostream>
#include <iomanip>
#include <cmath>

class Loan {
public:
    static double getMonthlyPayment(double annualInterestRate, int numberOfYears, double loanAmount) {
        if (annualInterestRate == 0.0) {
            return loanAmount / (numberOfYears * 12.0);
        }
        double monthlyInterestRate = annualInterestRate / 1200.0;
        double monthlyPayment = loanAmount * monthlyInterestRate / 
            (1.0 - 1.0 / std::pow(1.0 + monthlyInterestRate, numberOfYears * 12.0));
        return monthlyPayment;
    }

    static double getTotalPayment(double annualInterestRate, int numberOfYears, double loanAmount) {
        return getMonthlyPayment(annualInterestRate, numberOfYears, loanAmount) * numberOfYears * 12.0;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int T;
    if (std::cin >> T) {
        std::cout << std::fixed << std::setprecision(2);
        while (T--) {
            double rate, amount;
            int years;
            std::cin >> rate >> years >> amount;
            double monthly = Loan::getMonthlyPayment(rate, years, amount);
            double total = Loan::getTotalPayment(rate, years, amount);
            std::cout << monthly << " " << total << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

struct LoanCalculator {
    static double monthly(double rate, int years, double principal) {
        if (std::abs(rate) < 1e-9) {
            return principal / (years * 12);
        }
        double r = rate / 1200.0;
        int n = years * 12;
        double factor = std::pow(1.0 + r, n);
        return principal * (r * factor) / (factor - 1.0);
    }

    static double total(double rate, int years, double principal) {
        return monthly(rate, years, principal) * years * 12;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
