    for (int i = 0; i < t; ++i) {
        double annualRate, loanAmount;
        int years;
        std::cin >> annualRate >> years >> loanAmount;
        double m = LoanCalculator::monthly(annualRate, years, loanAmount);
        double tot = LoanCalculator::total(annualRate, years, loanAmount);
        std::cout << m << " " << tot << "\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

class RegularPolygon {
private:
    int n;
    double side;
    double x;
    double y;

public:
    RegularPolygon() : n(3), side(1.0), x(0.0), y(0.0) {}

    RegularPolygon(int n, double side) : n(n), side(side), x(0.0), y(0.0) {}

    RegularPolygon(int n, double side, double x, double y) : n(n), side(side), x(x), y(y) {}

    int getN() const { return n; }
    void setN(int n) { this->n = n; }

    double getSide() const { return side; }
    void setSide(double side) { this->side = side; }

    double getX() const { return x; }
    void setX(double x) { this->x = x; }

    double getY() const { return y; }
    void setY(double y) { this->y = y; }

    double getPerimeter() const {
        return n * side;
    }

    double getArea() const {
        const double PI = std::acos(-1.0);
        return (n * side * side) / (4.0 * std::tan(PI / n));
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

