    std::cout << std::fixed << std::setprecision(4);
    while (t--) {
        int n;
        double side, x, y;
        std::cin >> n >> side >> x >> y;
        RegularPolygon polygon(n, side, x, y);
        std::cout << polygon.getPerimeter() << " " << polygon.getArea() << "\n";
    }

    return 0;
}

