struct PolygonGeometry {
    static double calculatePerimeter(int n, double s) {
        return static_cast<double>(n) * s;
    }

    static double calculateArea(int n, double s) {
        const double pi = 3.14159265358979323846;
        double angle = pi / static_cast<double>(n);
        return (static_cast<double>(n) * s * s) / (4.0 * std::tan(angle));
    }
};

