using namespace std;

class MyInteger {
private:
    int value;

public:
    MyInteger(int val) : value(val) {}

    int getValue() const {
        return value;
    }

    static bool isEven(int val) {
        return val % 2 == 0;
    }

    static bool isOdd(int val) {
        return val % 2 != 0;
    }

    static bool isPrime(int val) {
        if (val <= 1) return false;
        for (long long i = 2; i * i <= val; ++i) {
            if (val % i == 0) return false;
        }
        return true;
    }

    bool isEven() const {
        return isEven(value);
    }

    bool isOdd() const {
        return isOdd(value);
    }

    bool isPrime() const {
        return isPrime(value);
    }

    static bool isEven(const MyInteger& obj) {
        return isEven(obj.getValue());
    }

    static bool isOdd(const MyInteger& obj) {
        return isOdd(obj.getValue());
    }

    static bool isPrime(const MyInteger& obj) {
        return isPrime(obj.getValue());
    }

    bool equals(int val) const {
        return value == val;
    }

    bool equals(const MyInteger& obj) const {
        return value == obj.getValue();
    }

    static int parseInt(const string& s) {
        int sign = 1;
        size_t start = 0;
        if (!s.empty() && s[0] == '-') {
            sign = -1;
            start = 1;
        } else if (!s.empty() && s[0] == '+') {
            start = 1;
        }
        long long res = 0;
        for (size_t i = start; i < s.size(); ++i) {
            if (s[i] >= '0' && s[i] <= '9') {
                res = res * 10 + (s[i] - '0');
            }
        }
        return (int)(res * sign);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n1, n2;
    if (!(cin >> n1 >> n2)) return 0;
    string s;
    cin >> s;

    MyInteger myInt1(n1);
    MyInteger myInt2(n2);

    cout << "myInt1: value = " << myInt1.getValue()
         << ", even = " << myInt1.isEven()
         << ", odd = " << myInt1.isOdd()
         << ", prime = " << myInt1.isPrime() << "\n";

    cout << "myInt2: value = " << myInt2.getValue()
         << ", even = " << myInt2.isEven()
         << ", odd = " << myInt2.isOdd()
         << ", prime = " << myInt2.isPrime() << "\n";

    cout << "Static tests for n1: even = " << MyInteger::isEven(n1)
         << ", odd = " << MyInteger::isOdd(n1)
         << ", prime = " << MyInteger::isPrime(n1) << "\n";

    cout << "Static tests for myInt2: even = " << MyInteger::isEven(myInt2)
         << ", odd = " << MyInteger::isOdd(myInt2)
         << ", prime = " << MyInteger::isPrime(myInt2) << "\n";

    cout << "myInt1 equals n2: " << myInt1.equals(n2) << "\n";
    cout << "myInt1 equals myInt2: " << myInt1.equals(myInt2) << "\n";

    int parsed = MyInteger::parseInt(s);
    cout << "Parsed int from string: " << parsed << "\n";
    cout << "Parsed value prime: " << MyInteger::isPrime(parsed) << "\n";

    return 0;
}

#include <iostream>
#include <string>

class MyInteger {
private:
    int value;
public:
    MyInteger(int v) : value(v) {}

    int getValue() const {
        return value;
    }

    bool isEven() const {
        return (value % 2) == 0;
    }

    bool isOdd() const {
        return (value % 2) != 0;
    }

    bool isPrime() const {
        return isPrime(value);
    }

    static bool isEven(int v) {
        return (v % 2) == 0;
    }

    static bool isOdd(int v) {
        return (v % 2) != 0;
    }

    static bool isPrime(int v) {
        if (v < 2) return false;
        if (v == 2 || v == 3) return true;
        if (v % 2 == 0 || v % 3 == 0) return false;
        for (long long i = 5; i * i <= v; i += 6) {
            if (v % i == 0 || v % (i + 2) == 0) return false;
        }
        return true;
    }

    static bool isEven(const MyInteger& other) {
        return other.isEven();
    }

    static bool isOdd(const MyInteger& other) {
        return other.isOdd();
    }

    static bool isPrime(const MyInteger& other) {
        return other.isPrime();
    }

    bool equals(int v) const {
        return value == v;
    }

    bool equals(const MyInteger& other) const {
        return value == other.value;
    }

    static int parseInt(const std::string& str) {
        int res = 0;
        int sign = 1;
        int idx = 0;
        int len = (int)str.length();
        if (idx < len && str[idx] == '-') {
            sign = -1;
            idx++;
        } else if (idx < len && str[idx] == '+') {
            idx++;
        }
        while (idx < len) {
            res = res * 10 + (str[idx] - '0');
            idx++;
        }
        return res * sign;
    }
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n1, n2;
