              << ", even = " << m1.isEven()
              << ", odd = " << m1.isOdd()
              << ", prime = " << m1.isPrime() << "\n";

    std::cout << "myInt2: value = " << m2.getValue()
              << ", even = " << m2.isEven()
              << ", odd = " << m2.isOdd()
              << ", prime = " << m2.isPrime() << "\n";

    std::cout << "Static tests for n1: even = " << MyInteger::isEven(n1)
              << ", odd = " << MyInteger::isOdd(n1)
              << ", prime = " << MyInteger::isPrime(n1) << "\n";

    std::cout << "Static tests for myInt2: even = " << MyInteger::isEven(m2)
              << ", odd = " << MyInteger::isOdd(m2)
              << ", prime = " << MyInteger::isPrime(m2) << "\n";

    std::cout << "myInt1 equals n2: " << m1.equals(n2) << "\n";
    std::cout << "myInt1 equals myInt2: " << m1.equals(m2) << "\n";

