#include <iostream>

void bubbleSort(int* const array, int size) {
    if (size <= 1) return;
    int end = size - 1;
    while (end > 0) {
        int lastSwap = 0;
        for (int i = 0; i < end; ++i) {
            if (*(array + i) > *(array + i + 1)) {
                int temp = *(array + i);
                *(array + i) = *(array + i + 1);
                *(array + i + 1) = temp;
                lastSwap = i;
            }
        }
        end = lastSwap;
    }
}

