#include <iostream>
#include <cmath>
#include <iomanip>

using namespace std;

const double PI = acos(-1.0);
const double EPS = 1e-7;

class Circle2D {
private:
    double x, y, radius;
public:
    Circle2D() : x(0), y(0), radius(1) {}
    Circle2D(double x, double y, double radius) : x(x), y(y), radius(radius) {}

    double getX() const { return x; }
    double getY() const { return y; }
    double getRadius() const { return radius; }

    double getArea() const {
        return PI * radius * radius;
    }

    double getPerimeter() const {
        return 2 * PI * radius;
    }

    bool contains(double px, double py) const {
        double d = hypot(px - x, py - y);
        return d <= radius + EPS;
    }

    bool contains(const Circle2D& circle) const {
        double d = hypot(circle.x - x, circle.y - y);
        return d + circle.radius <= radius + EPS;
    }

    bool overlaps(const Circle2D& circle) const {
        double d = hypot(circle.x - x, circle.y - y);
        return (d <= radius + circle.radius + EPS) && (d >= abs(radius - circle.radius) - EPS);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double x1, y1, r1;
    if (!(cin >> x1 >> y1 >> r1)) return 0;
    Circle2D c1(x1, y1, r1);

    double xp, yp;
    cin >> xp >> yp;

    double x2, y2, r2;
    cin >> x2 >> y2 >> r2;
    Circle2D c2(x2, y2, r2);

    double x3, y3, r3;
    cin >> x3 >> y3 >> r3;
    Circle2D c3(x3, y3, r3);

    cout << fixed << setprecision(3);
    cout << c1.getArea() << "\n";
    cout << c1.getPerimeter() << "\n";
    cout << (c1.contains(xp, yp) ? "true" : "false") << "\n";
    cout << (c1.contains(c2) ? "true" : "false") << "\n";
    cout << (c1.overlaps(c3) ? "true" : "false") << "\n";

    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

struct Circle {
    double cx, cy, r;

    double area() const {
        return std::acos(-1.0) * r * r;
    }

    double perimeter() const {
        return 2.0 * std::acos(-1.0) * r;
    }

    bool containsPoint(double x, double y) const {
        double distSq = (x - cx) * (x - cx) + (y - cy) * (y - cy);
        return distSq <= (r + 1e-7) * (r + 1e-7);
    }

    bool containsCircle(const Circle& other) const {
        double d = std::sqrt((cx - other.cx) * (cx - other.cx) + (cy - other.cy) * (cy - other.cy));
        return (d + other.r) <= (r + 1e-7);
    }

    bool overlapsCircle(const Circle& other) const {
        double d = std::sqrt((cx - other.cx) * (cx - other.cx) + (cy - other.cy) * (cy - other.cy));
        return (d <= r + other.r + 1e-7) && (d >= std::abs(r - other.r) - 1e-7);
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    Circle c1, c2, c3;
    double px, py;

    if (std::cin >> c1.cx >> c1.cy >> c1.r) {
        std::cin >> px >> py;
        std::cin >> c2.cx >> c2.cy >> c2.r;
        std::cin >> c3.cx >> c3.cy >> c3.r;

        std::cout << std::fixed << std::setprecision(3);
        std::cout << c1.area() << "\n";
        std::cout << c1.perimeter() << "\n";
        std::cout << (c1.containsPoint(px, py) ? "true" : "false") << "\n";
        std::cout << (c1.containsCircle(c2) ? "true" : "false") << "\n";
        std::cout << (c1.overlapsCircle(c3) ? "true" : "false") << "\n";
    }
    return 0;
}

