struct Rectangle2D {
    double x, y; // center
    double width, height;
};

Rectangle2D getBoundingBox(int n) {
    double minX = 0, maxX = 0, minY = 0, maxY = 0;
    for (int i = 0; i < n; ++i) {
        double px, py;
        std::cin >> px >> py;
        if (i == 0) {
            minX = maxX = px;
            minY = maxY = py;
        } else {
            if (px < minX) minX = px;
            if (px > maxX) maxX = px;
            if (py < minY) minY = py;
            if (py > maxY) maxY = py;
        }
    }
    Rectangle2D rect;
    rect.x = (minX + maxX) / 2.0;
    rect.y = (minY + maxY) / 2.0;
    rect.width = maxX - minX;
    rect.height = maxY - minY;
    return rect;
}

