#include <iostream>

using namespace std;

bool isLeapYear(long long year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

int getDaysInMonth(long long year, int month) {
    static const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 1 && isLeapYear(year)) return 29;
    return days[month];
}

void computeDate(long long totalSeconds, long long &year, int &month, int &day) {
    long long totalDays = totalSeconds / 86400;

    // Tinh nam
    // 400 nam co 146097 ngay
    // 100 nam co 36524 ngay
    // 4 nam co 1461 ngay
    // 1 nam co 365 ngay
    year = 1970;

    // Co the dung chu ky 400 nam de tang toc neu T rat lon
    long long daysIn400Years = 146097;
    // Can than vi 1970 khong phai dau chu ky 400 nam chia het cho 400
    // Ta co the dua ve moc nam 2000 (1970 toi 2000 la 30 nam: 1972, 76, 80, 84, 88, 92, 96 la 7 nam nhuan => 30*365 + 7 = 10957 ngay)
    if (totalDays >= 10957) {
        totalDays -= 10957;
        year = 2000;
        long long cycles = totalDays / daysIn400Years;
        year += cycles * 400;
        totalDays %= daysIn400Years;
    }

    while (true) {
        int diy = isLeapYear(year) ? 366 : 365;
        if (totalDays >= diy) {
            totalDays -= diy;
            year++;
        } else {
            break;
        }
    }

    month = 0;
    while (true) {
        int dim = getDaysInMonth(year, month);
        if (totalDays >= dim) {
            totalDays -= dim;
            month++;
        } else {
            break;
        }
    }

    day = totalDays + 1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int q;
    if (cin >> q) {
        while (q--) {
            long long t;
            cin >> t;
            long long y;
            int m, d;
            computeDate(t, y, m, d);
            cout << y << " " << m << " " << d << "\n";
        }
    }
    return 0;
}

