// Su dung cong thuc tinh lich Gregory thong qua ngay tuyet doi theo thuat toan Euclidean Affine
// Epoch 1970-01-01
void unixSecondsToYMD(unsigned long long sec, long long &outYear, int &outMonth, int &outDay) {
    long long days = sec / 86400LL;

    // Chuyen ve he quy chieu tu 0001-01-01 hoac Rata Die
    // So ngay tu 0001-01-01 toi 1970-01-01:
    // 1969 nam truoc do: 1969 * 365 + 1969/4 - 1969/100 + 1969/400 = 719162
    long long z = days + 719468; // Epoch shift to 0000-03-01
    long long era = (z >= 0 ? z : z - 146096) / 146097;
    long long doe = static_cast<long long>(z - era * 146097); // [0, 146096]
    long long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
    long long y = yoe + era * 400;
    long long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    long long mp = (5 * doy + 2) / 153;
    long long d = doy - (153 * mp + 2) / 5 + 1;
    long long m = mp + (mp < 10 ? 3 : -9);
    y += (m <= 2);

    outYear = y;
    outMonth = m - 1; // 0-based month
    outDay = d;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int q;
    if (cin >> q) {
        while (q--) {
            unsigned long long t;
            cin >> t;
            long long y;
            int m, d;
            unixSecondsToYMD(t, y, m, d);
            cout << y << " " << m << " " << d << "\n";
        }
    }
    return 0;
}

