using namespace std;

class Rectangle2D {
private:
    double x, y;
    double width, height;

public:
    Rectangle2D() : x(0), y(0), width(1), height(1) {}
    Rectangle2D(double x, double y, double width, double height)
        : x(x), y(y), width(width), height(height) {}

    double getX() const { return x; }
    double getY() const { return y; }
    double getWidth() const { return width; }
    double getHeight() const { return height; }

    void setX(double x) { this->x = x; }
    void setY(double y) { this->y = y; }
    void setWidth(double width) { this->width = width; }
    void setHeight(double height) { this->height = height; }

    double getArea() const {
        return width * height;
    }

    double getPerimeter() const {
        return 2 * (width + height);
    }

    bool contains(double px, double py) const {
        const double eps = 1e-7;
        double minX = x - width / 2.0;
        double maxX = x + width / 2.0;
        double minY = y - height / 2.0;
        double maxY = y + height / 2.0;
        return (px >= minX - eps && px <= maxX + eps && py >= minY - eps && py <= maxY + eps);
    }

    bool contains(const Rectangle2D &r) const {
        const double eps = 1e-7;
        double left = r.getX() - r.getWidth() / 2.0;
        double right = r.getX() + r.getWidth() / 2.0;
        double bottom = r.getY() - r.getHeight() / 2.0;
        double top = r.getY() + r.getHeight() / 2.0;

        double myLeft = x - width / 2.0;
        double myRight = x + width / 2.0;
        double myBottom = y - height / 2.0;
        double myTop = y + height / 2.0;

        return (left >= myLeft - eps && right <= myRight + eps &&
                bottom >= myBottom - eps && top <= myTop + eps);
    }

    bool overlaps(const Rectangle2D &r) const {
        const double eps = 1e-7;
        double left1 = x - width / 2.0;
        double right1 = x + width / 2.0;
        double bottom1 = y - height / 2.0;
        double top1 = y + height / 2.0;

        double left2 = r.getX() - r.getWidth() / 2.0;
        double right2 = r.getX() + r.getWidth() / 2.0;
        double bottom2 = r.getY() - r.getHeight() / 2.0;
        double top2 = r.getY() + r.getHeight() / 2.0;

        if (right1 < left2 - eps || left1 > right2 + eps) return false;
        if (top1 < bottom2 - eps || bottom1 > top2 + eps) return false;
        return true;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double x1, y1, w1, h1;
    if (!(cin >> x1 >> y1 >> w1 >> h1)) return 0;
    Rectangle2D r1(x1, y1, w1, h1);

    double x2, y2, w2, h2;
    cin >> x2 >> y2 >> w2 >> h2;
    Rectangle2D r2(x2, y2, w2, h2);

    double x3, y3, w3, h3;
    cin >> x3 >> y3 >> w3 >> h3;
    Rectangle2D r3(x3, y3, w3, h3);

    double px, py;
    cin >> px >> py;

    cout << fixed << setprecision(2);
    cout << r1.getArea() << "\n";
    cout << r1.getPerimeter() << "\n";
    cout << (r1.contains(px, py) ? "true" : "false") << "\n";
    cout << (r1.contains(r2) ? "true" : "false") << "\n";
    cout << (r1.overlaps(r3) ? "true" : "false") << "\n";

    return 0;
}

