struct Interval {
    double low, high;
    bool contains(double v, double eps = 1e-7) const {
        return v >= low - eps && v <= high + eps;
    }
    bool contains(const Interval &o, double eps = 1e-7) const {
        return o.low >= low - eps && o.high <= high + eps;
    }
    bool overlaps(const Interval &o, double eps = 1e-7) const {
        return !(high < o.low - eps || low > o.high + eps);
    }
};

class Rectangle2D {
private:
    double cx, cy;
    double w, h;

    Interval getXInterval() const {
        return {cx - w / 2.0, cx + w / 2.0};
    }
    Interval getYInterval() const {
        return {cy - h / 2.0, cy + h / 2.0};
    }

public:
    Rectangle2D() : cx(0.0), cy(0.0), w(1.0), h(1.0) {}
    Rectangle2D(double cx, double cy, double w, double h) : cx(cx), cy(cy), w(w), h(h) {}

    double getX() const { return cx; }
    double getY() const { return cy; }
    double getWidth() const { return w; }
    double getHeight() const { return h; }

    void setX(double x) { cx = x; }
    void setY(double y) { cy = y; }
    void setWidth(double width) { w = width; }
    void setHeight(double height) { h = height; }

    double getArea() const {
        return w * h;
    }

    double getPerimeter() const {
        return 2.0 * (w + h);
    }

    bool contains(double px, double py) const {
        return getXInterval().contains(px) && getYInterval().contains(py);
    }

    bool contains(const Rectangle2D &other) const {
        return getXInterval().contains(other.getXInterval()) && getYInterval().contains(other.getYInterval());
    }

    bool overlaps(const Rectangle2D &other) const {
        return getXInterval().overlaps(other.getXInterval()) && getYInterval().overlaps(other.getYInterval());
    }
};

int main() {
