#include <iostream>
#include <string>

class Course {
private:
    std::string courseName;
    std::string* students;
    int numberOfStudents;
    int capacity;

    void resize(int newCapacity) {
        std::string* temp = new std::string[newCapacity];
        for (int i = 0; i < numberOfStudents; ++i) {
            temp[i] = students[i];
        }
        delete[] students;
        students = temp;
        capacity = newCapacity;
    }

public:
    Course(const std::string& name, int cap = 2) : courseName(name), numberOfStudents(0), capacity(cap) {
        students = new std::string[capacity];
    }

    ~Course() {
        delete[] students;
    }

    Course(const Course& other) : courseName(other.courseName), numberOfStudents(other.numberOfStudents), capacity(other.capacity) {
        students = new std::string[capacity];
        for (int i = 0; i < numberOfStudents; ++i) {
            students[i] = other.students[i];
        }
    }

    Course& operator=(const Course& other) {
        if (this != &other) {
            delete[] students;
            courseName = other.courseName;
            numberOfStudents = other.numberOfStudents;
            capacity = other.capacity;
            students = new std::string[capacity];
            for (int i = 0; i < numberOfStudents; ++i) {
                students[i] = other.students[i];
            }
        }
        return *this;
    }

    void addStudent(const std::string& name) {
        if (numberOfStudents >= capacity) {
            resize(capacity * 2);
        }
        students[numberOfStudents++] = name;
    }

    void dropStudent(const std::string& name) {
        int idx = -1;
        for (int i = 0; i < numberOfStudents; ++i) {
            if (students[i] == name) {
                idx = i;
                break;
            }
        }
        if (idx != -1) {
            for (int i = idx; i < numberOfStudents - 1; ++i) {
                students[i] = students[i + 1];
            }
            numberOfStudents--;
        }
    }

    void clear() {
        numberOfStudents = 0;
    }

    int getNumberOfStudents() const {
        return numberOfStudents;
    }

    std::string* getStudents() const {
        return students;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    Course course("CS101");
    int q;
    if (!(std::cin >> q)) return 0;

    while (q--) {
        std::string op;
        std::cin >> op;
        if (op == "ADD") {
            std::string name;
            std::cin >> name;
            course.addStudent(name);
        } else if (op == "DROP") {
            std::string name;
            std::cin >> name;
            course.dropStudent(name);
        } else if (op == "CLEAR") {
            course.clear();
        } else if (op == "PRINT") {
            int n = course.getNumberOfStudents();
            std::cout << n << ":";
            std::string* list = course.getStudents();
            for (int i = 0; i < n; ++i) {
                std::cout << " " << list[i];
            }
            std::cout << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

class CustomCourse {
private:
    std::string title;
    std::string* studentList;
    int count;
    int maxCap;

public:
    CustomCourse(std::string name = "DefaultCourse") : title(name), count(0), maxCap(4) {
        studentList = new std::string[maxCap];
    }

    ~CustomCourse() {
        delete[] studentList;
    }

    CustomCourse(const CustomCourse& other) {
        title = other.title;
        count = other.count;
        maxCap = other.maxCap;
        studentList = new std::string[maxCap];
        for (int i = 0; i < count; ++i) {
            studentList[i] = other.studentList[i];
        }
    }

    void add(const std::string& student) {
        if (count == maxCap) {
            int newCap = maxCap * 2;
            std::string* next = new std::string[newCap];
            for (int i = 0; i < count; ++i) {
                next[i] = studentList[i];
            }
            delete[] studentList;
            studentList = next;
            maxCap = newCap;
        }
        studentList[count++] = student;
    }

    void drop(const std::string& student) {
        int found = -1;
        for (int i = 0; i < count; ++i) {
            if (studentList[i] == student) {
                found = i;
                break;
            }
        }
        if (found != -1) {
            for (int i = found; i + 1 < count; ++i) {
                studentList[i] = studentList[i + 1];
            }
            --count;
        }
    }

    void reset() {
        count = 0;
    }

    void display() const {
        std::cout << count << ":";
        for (int i = 0; i < count; ++i) {
            std::cout << ' ' << studentList[i];
        }
        std::cout << '\n';
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int commands;
    if (!(std::cin >> commands)) return 0;

    CustomCourse c("Programming_Design");
    for (int k = 0; k < commands; ++k) {
        std::string type;
        std::cin >> type;
        if (type == "ADD") {
            std::string sname;
            std::cin >> sname;
            c.add(sname);
        } else if (type == "DROP") {
            std::string sname;
            std::cin >> sname;
            c.drop(sname);
        } else if (type == "CLEAR") {
            c.reset();
        } else if (type == "PRINT") {
            c.display();
        }
    }

    return 0;
}

