template <typename T>
const T& getMinimum(const T* a, int n) {
    int bestIdx = 0;
    for (int i = 1; i < n; ++i) {
        if (a[i] < a[bestIdx]) {
            bestIdx = i;
        }
    }
    return a[bestIdx];
}

