using namespace std;

struct SimpleString {
    vector<char> buf;

    SimpleString() {}

    void assign_char(int n, char c) {
        buf.assign(n, c);
    }

    void assign_str(const string& s) {
        buf.assign(s.begin(), s.end());
    }

    void assign_substr(const string& s, int index, int n) {
        buf.clear();
        int len = (int)s.size();
        for (int i = 0; i < n && index + i < len; ++i) {
            buf.push_back(s[index + i]);
        }
    }

    void append_char(int n, char c) {
        buf.insert(buf.end(), n, c);
    }

    void append_str(const string& s) {
        buf.insert(buf.end(), s.begin(), s.end());
    }

    void append_substr(const string& s, int index, int n) {
        int len = (int)s.size();
        for (int i = 0; i < n && index + i < len; ++i) {
            buf.push_back(s[index + i]);
        }
    }

    void substr(int index, int n) {
        vector<char> next_buf;
        int len = (int)buf.size();
        for (int i = 0; i < n && index + i < len; ++i) {
            next_buf.push_back(buf[index + i]);
        }
        buf = move(next_buf);
    }

    void substr_from(int index) {
        vector<char> next_buf;
        int len = (int)buf.size();
        for (int i = index; i < len; ++i) {
            next_buf.push_back(buf[i]);
        }
        buf = move(next_buf);
    }

    void erase(int index, int n) {
        int len = (int)buf.size();
        if (index >= len) return;
        int cnt = min(n, len - index);
        buf.erase(buf.begin() + index, buf.begin() + index + cnt);
    }

    int size() const {
        return (int)buf.size();
    }

    string to_string() const {
        return string(buf.begin(), buf.end());
    }
};

