    char* str;
    int len;

public:
    MyString() {
        len = 0;
        str = new char[1];
        str[0] = '\0';
    }

    MyString(const char* cString) {
        if (cString == nullptr) {
            len = 0;
            str = new char[1];
            str[0] = '\0';
        } else {
            len = std::strlen(cString);
            str = new char[len + 1];
            std::strcpy(str, cString);
        }
    }

    MyString(const MyString& other) {
        len = other.len;
        str = new char[len + 1];
        std::strcpy(str, other.str);
    }

    MyString& operator=(const MyString& other) {
        if (this != &other) {
            delete[] str;
            len = other.len;
            str = new char[len + 1];
            std::strcpy(str, other.str);
        }
        return *this;
    }

    ~MyString() {
        delete[] str;
    }

    char at(int index) const {
        return str[index];
    }

    int length() const {
        return len;
    }

    void clear() {
        delete[] str;
        len = 0;
        str = new char[1];
        str[0] = '\0';
    }

    bool empty() const {
        return len == 0;
    }

    int compare(const MyString& s) const {
        int res = std::strcmp(str, s.str);
        if (res < 0) return -1;
        if (res > 0) return 1;
        return 0;
    }

    int compare(int index, int n, const MyString& s) const {
        int count = n;
        if (index + count > len) count = len - index;
        if (count < 0) count = 0;

        for (int i = 0; i < count && i < s.len; ++i) {
            if (str[index + i] < s.str[i]) return -1;
            if (str[index + i] > s.str[i]) return 1;
        }
        if (count < s.len) return -1;
        if (count > s.len) return 1;
        return 0;
    }

    void copy(char s[], int index, int n) {
        int count = n;
        if (index + count > len) count = len - index;
        for (int i = 0; i < count; ++i) {
            s[i] = str[index + i];
        }
    }

    char* data() const {
        return str;
    }

    int find(char ch) const {
        return find(ch, 0);
    }

    int find(char ch, int index) const {
        if (index < 0 || index >= len) return -1;
        for (int i = index; i < len; ++i) {
            if (str[i] == ch) return i;
        }
        return -1;
    }

    int find(const MyString& s, int index) const {
        if (index < 0 || index > len) return -1;
        if (s.len == 0) return index;
        for (int i = index; i + s.len <= len; ++i) {
            bool match = true;
            for (int j = 0; j < s.len; ++j) {
                if (str[i + j] != s.str[j]) {
                    match = false;
                    break;
                }
            }
            if (match) return i;
        }
        return -1;
    }
};

