class MyString {
private:
    int sz;
    char* buffer;

public:
    MyString() : sz(0) {
        buffer = new char[1];
        buffer[0] = 0;
    }

    MyString(const char* cString) {
        if (!cString) {
            sz = 0;
            buffer = new char[1];
            buffer[0] = 0;
        } else {
            sz = 0;
            while (cString[sz]) sz++;
            buffer = new char[sz + 1];
            for (int i = 0; i <= sz; ++i) buffer[i] = cString[i];
        }
    }

    MyString(const MyString& other) : sz(other.sz) {
        buffer = new char[sz + 1];
        for (int i = 0; i <= sz; ++i) buffer[i] = other.buffer[i];
    }

    ~MyString() {
        delete[] buffer;
    }

    MyString& operator=(const MyString& other) {
        if (this != &other) {
            delete[] buffer;
            sz = other.sz;
            buffer = new char[sz + 1];
            for (int i = 0; i <= sz; ++i) buffer[i] = other.buffer[i];
        }
        return *this;
    }

    char at(int index) const {
        return buffer[index];
    }

    int length() const {
        return sz;
    }

    void clear() {
        delete[] buffer;
        sz = 0;
        buffer = new char[1];
        buffer[0] = 0;
    }

    bool empty() const {
        return sz == 0;
    }

    int compare(const MyString& s) const {
        int minL = sz < s.sz ? sz : s.sz;
        for (int i = 0; i < minL; ++i) {
            if (buffer[i] < s.buffer[i]) return -1;
            if (buffer[i] > s.buffer[i]) return 1;
        }
        if (sz < s.sz) return -1;
        if (sz > s.sz) return 1;
        return 0;
    }

    int compare(int index, int n, const MyString& s) const {
        int count = n;
        if (index + count > sz) count = sz - index;
        if (count < 0) count = 0;
        int minL = count < s.sz ? count : s.sz;
        for (int i = 0; i < minL; ++i) {
            if (buffer[index + i] < s.buffer[i]) return -1;
            if (buffer[index + i] > s.buffer[i]) return 1;
        }
        if (count < s.sz) return -1;
        if (count > s.sz) return 1;
        return 0;
    }

    void copy(char s[], int index, int n) {
        int count = n;
        if (index + count > sz) count = sz - index;
        for (int i = 0; i < count; ++i) {
            s[i] = buffer[index + i];
        }
    }

    char* data() const {
        return buffer;
    }

    int find(char ch) const {
        return find(ch, 0);
    }

    int find(char ch, int index) const {
        for (int i = index; i < sz; ++i) {
            if (buffer[i] == ch) return i;
        }
        return -1;
    }

    int find(const MyString& s, int index) const {
        if (index < 0 || index > sz) return -1;
        if (s.sz == 0) return index;
        for (int i = index; i + s.sz <= sz; ++i) {
            int j = 0;
            while (j < s.sz && buffer[i + j] == s.buffer[j]) ++j;
            if (j == s.sz) return i;
        }
        return -1;
    }
};

