template <typename T>
void selectionSort(T arr[], int size) {
    for (int i = 0; i < size - 1; ++i) {
        T currentMin = arr[i];
        int currentMinIndex = i;
        for (int j = i + 1; j < size; ++j) {
            if (arr[j] < currentMin) {
                currentMin = arr[j];
                currentMinIndex = j;
            }
        }
        if (currentMinIndex != i) {
            arr[currentMinIndex] = arr[i];
            arr[i] = currentMin;
        }
    }
}

