template <typename T>
class GenericStack {
private:
    T* arr;
    int capacity;
    int topIndex;

    void resize(int newCapacity) {
        T* newArr = new T[newCapacity];
        for (int i = 0; i <= topIndex; ++i) {
            newArr[i] = arr[i];
        }
        delete[] arr;
        arr = newArr;
        capacity = newCapacity;
    }

public:
    GenericStack() : capacity(16), topIndex(-1) {
        arr = new T[capacity];
    }
    ~GenericStack() {
        delete[] arr;
    }
    bool isEmpty() const {
        return topIndex == -1;
    }
    void push(const T& val) {
        if (topIndex + 1 == capacity) {
            resize(capacity * 2);
        }
        arr[++topIndex] = val;
    }
    void pop() {
        if (topIndex >= 0) {
            topIndex--;
        }
    }
    void printStack() const {
        if (topIndex == -1) {
            cout << "Empty\n";
            return;
        }
        for (int i = 0; i <= topIndex; ++i) {
            if (i > 0) cout << ' ';
            cout << arr[i];
        }
        cout << '\n';
    }
};

