template <typename T>
class GenericStack {
private:
    vector<T> elements;
public:
    bool empty() const {
        return elements.empty();
    }

    int getSize() const {
        return elements.size();
    }

    void push(T value) {
        elements.push_back(value);
    }

    T pop() {
        if (empty()) return T();
        T val = elements.back();
        elements.pop_back();
        return val;
    }

    int position(T element) const {
        for (int i = (int)elements.size() - 1; i >= 0; --i) {
            if (elements[i] == element) {
                return (int)elements.size() - 1 - i;
            }
        }
        return -1;
    }
};

