using namespace std;

template <typename E>
struct VectorStack {
    vector<E> data;

    void push(E item) {
        data.push_back(move(item));
    }

    bool isEmpty() const {
        return data.empty();
    }

    size_t size() const {
        return data.size();
    }

    bool top(E& out) const {
        if (data.empty()) return false;
        out = data.back();
        return true;
    }

    bool pop(E& out) {
        if (data.empty()) return false;
        out = data.back();
        data.pop_back();
        return true;
    }
};

