using namespace std;

struct Point {
    long long x, y;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Point> pts(n);
    for (int i = 0; i < n; ++i) {
        cin >> pts[i].x >> pts[i].y;
    }

    if (n <= 2) {
        cout << "YES\n";
        return 0;
    }

    // Tìm 2 điểm phân biệt đầu tiên để xác định phương của đường thẳng
    int first_diff = -1;
    for (int i = 1; i < n; ++i) {
        if (pts[i].x != pts[0].x || pts[i].y != pts[0].y) {
            first_diff = i;
            break;
        }
    }

    // Nếu tất cả các điểm trùng nhau, chúng cùng nằm trên một đường thẳng
    if (first_diff == -1) {
        cout << "YES\n";
        return 0;
    }

    Point p0 = pts[0];
    Point p1 = pts[first_diff];
    long long dx = p1.x - p0.x;
    long long dy = p1.y - p0.y;

    bool collinear = true;
    for (int i = 0; i < n; ++i) {
        // Tích có hướng: (pts[i].x - p0.x) * dy - (pts[i].y - p0.y) * dx == 0
        // Dùng __int128 để tránh tràn số khi nhân hai hiệu số lên tới 2*10^9
        __int128 cross_product = (__int128)(pts[i].x - p0.x) * dy - (__int128)(pts[i].y - p0.y) * dx;
        if (cross_product != 0) {
            collinear = false;
            break;
        }
    }

    if (collinear) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

#include <iostream>
