#include <numeric>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<pair<long long, long long>> points(n);
    for (int i = 0; i < n; ++i) {
        cin >> points[i].first >> points[i].second;
    }

    if (n <= 2) {
        cout << "YES\n";
        return 0;
    }

    // Đường thẳng dạng A*x + B*y + C = 0
    // Tìm 2 điểm khác nhau để lập phương trình đường thẳng
    long long A = 0, B = 0, C = 0;
    bool found_line = false;

    for (int i = 1; i < n; ++i) {
        if (points[i] != points[0]) {
            // Vector chỉ phương (dx, dy) = (x1 - x0, y1 - y0)
            // Vector pháp tuyến (A, B) = (-(y1 - y0), x1 - x0) = (y0 - y1, x1 - x0)
            A = points[0].second - points[i].second;
            B = points[i].first - points[0].first;
            found_line = true;
            break;
        }
    }

    if (!found_line) {
        cout << "YES\n";
        return 0;
    }

    // C = -(A * x0 + B * y0)
    // Kiểm tra tất cả các điểm xem có thỏa mãn A*x + B*y + C == 0
    // Tương đương A*(x - x0) + B*(y - y0) == 0
    long long x0 = points[0].first;
    long long y0 = points[0].second;

    for (int i = 0; i < n; ++i) {
        __int128 val = (__int128)A * (points[i].first - x0) + (__int128)B * (points[i].second - y0);
        if (val != 0) {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "YES\n";
    return 0;
}

