#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

const double EPS = 1e-6;

bool solve(vector<double> nums) {
    if (nums.size() == 1) {
        return fabs(nums[0] - 24.0) < EPS;
    }
    int n = nums.size();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            vector<double> next_nums;
            for (int k = 0; k < n; ++k) {
                if (k != i && k != j) next_nums.push_back(nums[k]);
            }
            // Try operations between nums[i] and nums[j]
            // + 
            next_nums.push_back(nums[i] + nums[j]);
            if (solve(next_nums)) return true;
            next_nums.pop_back();

            // -
            next_nums.push_back(nums[i] - nums[j]);
            if (solve(next_nums)) return true;
            next_nums.pop_back();

            // *
            next_nums.push_back(nums[i] * nums[j]);
            if (solve(next_nums)) return true;
            next_nums.pop_back();

            // /
            if (fabs(nums[j]) > EPS) {
                next_nums.push_back(nums[i] / nums[j]);
                if (solve(next_nums)) return true;
                next_nums.pop_back();
            }
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    vector<double> nums(4);
    if (cin >> nums[0] >> nums[1] >> nums[2] >> nums[3]) {
        if (solve(nums)) {
            cout << "YES\n";
        } else {
            cout << "NO\n";
        }
    }
    return 0;
}

