            // op +
            if (i < j) {
                rem.push_back(a[i] + a[j]);
                if (can24(rem)) return true;
                rem.pop_back();
            }

            // op -
            rem.push_back(a[i] - a[j]);
            if (can24(rem)) return true;
            rem.pop_back();

            // op *
            if (i < j) {
                rem.push_back(a[i] * a[j]);
                if (can24(rem)) return true;
                rem.pop_back();
            }

            // op /
            if (a[j].num != 0) {
                rem.push_back(a[i] / a[j]);
                if (can24(rem)) return true;
                rem.pop_back();
            }
        }
    }
