using namespace std;

const double EPS = 1e-6;

bool solve(vector<double> nums) {
    if (nums.size() == 1) {
        return abs(nums[0] - 24.0) < EPS;
    }
    int n = nums.size();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            vector<double> next_nums;
            for (int k = 0; k < n; ++k) {
                if (k != i && k != j) {
                    next_nums.push_back(nums[k]);
                }
            }
            // try all operations
            vector<double> results = {
                nums[i] + nums[j],
                nums[i] - nums[j],
                nums[i] * nums[j]
            };
            if (abs(nums[j]) > EPS) {
                results.push_back(nums[i] / nums[j]);
            }
            for (double val : results) {
                next_nums.push_back(val);
                if (solve(next_nums)) return true;
                next_nums.pop_back();
            }
        }
    }
    return false;
}

