const double EPS = 1e-7;

struct Rational {
    double val;
    Rational(double v = 0) : val(v) {}
};

bool dfs(vector<double>& a) {
    int sz = a.size();
    if (sz == 1) {
        return std::abs(a[0] - 24.0) < EPS;
    }
    for (int i = 0; i < sz; ++i) {
        for (int j = i + 1; j < sz; ++j) {
            double x = a[i], y = a[j];
            vector<double> nxt;
            nxt.reserve(sz - 1);
            for (int k = 0; k < sz; ++k) {
                if (k != i && k != j) nxt.push_back(a[k]);
            }

            // x + y, x * y
            vector<double> candidates = {x + y, x - y, y - x, x * y};
            if (std::abs(y) > EPS) candidates.push_back(x / y);
            if (std::abs(x) > EPS) candidates.push_back(y / x);

            for (double cand : candidates) {
                nxt.push_back(cand);
                if (dfs(nxt)) return true;
                nxt.pop_back();
            }
        }
    }
    return false;
}

