int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!getline(cin, s)) return 0;

    vector<string> tokens;
    int n = s.size();
    for (int i = 0; i < n; ) {
        if (isspace(s[i])) {
            i++;
        } else if (isalnum(s[i])) {
            string operand = "";
            while (i < n && isalnum(s[i])) {
                operand += s[i];
                i++;
            }
            tokens.push_back(operand);
        } else {
            string op(1, s[i]);
            tokens.push_back(op);
            i++;
        }
    }

    vector<string> postfix;
    stack<char> opStack;

    for (const string& token : tokens) {
        if (isalnum(token[0])) {
            postfix.push_back(token);
        } else if (token == "(") {
            opStack.push('(');
        } else if (token == ")") {
            while (!opStack.empty() && opStack.top() != '(') {
                postfix.push_back(string(1, opStack.top()));
                opStack.pop();
            }
            if (!opStack.empty() && opStack.top() == '(') {
                opStack.pop();
            }
        } else {
            char curOp = token[0];
            while (!opStack.empty() && precedence(opStack.top()) >= precedence(curOp)) {
                postfix.push_back(string(1, opStack.top()));
                opStack.pop();
            }
            opStack.push(curOp);
        }
    }

    while (!opStack.empty()) {
        postfix.push_back(string(1, opStack.top()));
        opStack.pop();
    }

    for (size_t i = 0; i < postfix.size(); i++) {
        if (i > 0) cout << " ";
        cout << postfix[i];
    }
    cout << "\n";

    return 0;
}

#include <iostream>
