using namespace std;

int getPriority(char c) {
    switch (c) {
        case '*':
        case '/':
            return 2;
        case '+':
        case '-':
            return 1;
        default:
            return 0;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string expr;
    if (!getline(cin, expr)) return 0;

    stack<char> st;
    string res = "";
    bool first = true;

    auto appendToken = [&](const string& t) {
        if (!first) res += " ";
        res += t;
        first = false;
    };

    int len = expr.length();
    int idx = 0;
    while (idx < len) {
        char c = expr[idx];
        if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
            idx++;
            continue;
        }

        if ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
            string term = "";
            while (idx < len && ((expr[idx] >= '0' && expr[idx] <= '9') ||
                                 (expr[idx] >= 'a' && expr[idx] <= 'z') ||
                                 (expr[idx] >= 'A' && expr[idx] <= 'Z'))) {
                term += expr[idx];
                idx++;
            }
            appendToken(term);
        } else if (c == '(') {
            st.push('(');
            idx++;
        } else if (c == ')') {
            while (!st.empty() && st.top() != '(') {
                appendToken(string(1, st.top()));
                st.pop();
            }
            if (!st.empty()) st.pop();
            idx++;
        } else {
            while (!st.empty() && getPriority(st.top()) >= getPriority(c)) {
                appendToken(string(1, st.top()));
                st.pop();
            }
            st.push(c);
            idx++;
        }
    }

    while (!st.empty()) {
        appendToken(string(1, st.top()));
        st.pop();
    }

    cout << res << "\n";
    return 0;
}

