#include <cctype>

using namespace std;

long long power(long long base, long long exp) {
    long long res = 1;
    long long b = base;
    while (exp > 0) {
        if (exp & 1) res *= b;
        b *= b;
        exp >>= 1;
    }
    return res;
}

int precedence(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/' || op == '%') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}

void applyOp(stack<long long>& values, stack<char>& ops) {
    if (values.size() < 2 || ops.empty()) return;
    long long b = values.top(); values.pop();
    long long a = values.top(); values.pop();
    char op = ops.top(); ops.pop();
    long long res = 0;
    if (op == '+') res = a + b;
    else if (op == '-') res = a - b;
    else if (op == '*') res = a * b;
    else if (op == '/') res = a / b;
    else if (op == '%') res = a % b;
    else if (op == '^') res = power(a, b);
    values.push(res);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (!getline(cin, s)) return 0;

    stack<long long> values;
    stack<char> ops;

    int n = s.length();
    for (int i = 0; i < n; ++i) {
        if (isspace(s[i])) continue;
        if (isdigit(s[i])) {
            long long val = 0;
            while (i < n && isdigit(s[i])) {
                val = val * 10 + (s[i] - '0');
                i++;
            }
            i--;
            values.push(val);
        } else if (s[i] == '(') {
            ops.push(s[i]);
        } else if (s[i] == ')') {
            while (!ops.empty() && ops.top() != '(') {
                applyOp(values, ops);
            }
            if (!ops.empty() && ops.top() == '(') {
                ops.pop();
            }
        } else {
            while (!ops.empty() && ops.top() != '(' && precedence(ops.top()) >= precedence(s[i])) {
                applyOp(values, ops);
            }
            ops.push(s[i]);
        }
    }

    while (!ops.empty()) {
        applyOp(values, ops);
    }

    if (!values.empty()) {
        cout << values.top() << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <cctype>

using namespace std;

long long fastPow(long long a, long long b) {
    long long ans = 1;
    while (b > 0) {
        if (b % 2 == 1) ans *= a;
        a *= a;
        b /= 2;
    }
    return ans;
}

int getPrec(char op) {
    switch (op) {
        case '^': return 3;
        case '*':
        case '/':
        case '%': return 2;
        case '+':
        case '-': return 1;
        default: return -1;
    }
}

long long compute(long long a, long long b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return a / b;
        case '%': return a % b;
        case '^': return fastPow(a, b);
    }
    return 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string line;
    if (!getline(cin, line)) return 0;

    vector<long long> numStack;
    vector<char> opStack;

    for (size_t i = 0; i < line.size(); ++i) {
        char c = line[i];
        if (isspace(c)) continue;
        if (isdigit(c)) {
            long long cur = 0;
            while (i < line.size() && isdigit(line[i])) {
                cur = cur * 10 + (line[i] - '0');
                i++;
            }
            i--;
            numStack.push_back(cur);
        } else if (c == '(') {
            opStack.push_back(c);
        } else if (c == ')') {
            while (!opStack.empty() && opStack.back() != '(') {
                char op = opStack.back(); opStack.pop_back();
                long long val2 = numStack.back(); numStack.pop_back();
                long long val1 = numStack.back(); numStack.pop_back();
                numStack.push_back(compute(val1, val2, op));
            }
            if (!opStack.empty()) opStack.pop_back();
        } else {
            while (!opStack.empty() && opStack.back() != '(' && getPrec(opStack.back()) >= getPrec(c)) {
                char op = opStack.back(); opStack.pop_back();
                long long val2 = numStack.back(); numStack.pop_back();
                long long val1 = numStack.back(); numStack.pop_back();
                numStack.push_back(compute(val1, val2, op));
            }
            opStack.push_back(c);
        }
    }

    while (!opStack.empty()) {
        char op = opStack.back(); opStack.pop_back();
        long long val2 = numStack.back(); numStack.pop_back();
        long long val1 = numStack.back(); numStack.pop_back();
        numStack.push_back(compute(val1, val2, op));
    }

    cout << numStack.back() << "\n";
    return 0;
}

