bool isConsecutiveFour(const vector<vector<int>>& values) {
    int R = values.size();
    if (R == 0) return false;
    int C = values[0].size();
    if (C == 0) return false;

    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            int val = values[i][j];
            // Ngang (sang phai)
            if (j + 3 < C && values[i][j+1] == val && values[i][j+2] == val && values[i][j+3] == val) {
                return true;
            }
            // Doc (xuong duoi)
            if (i + 3 < R && values[i+1][j] == val && values[i+2][j] == val && values[i+3][j] == val) {
                return true;
            }
            // Cheo chinh (xuong duoi, sang phai)
            if (i + 3 < R && j + 3 < C && values[i+1][j+1] == val && values[i+2][j+2] == val && values[i+3][j+3] == val) {
                return true;
            }
            // Cheo phu (xuong duoi, sang trai)
            if (i + 3 < R && j - 3 >= 0 && values[i+1][j-1] == val && values[i+2][j-2] == val && values[i+3][j-3] == val) {
                return true;
            }
        }
    }
    return false;
}

