    vector<vector<int>> values(R, vector<int>(C));
    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            cin >> values[i][j];
        }
    }
    if (isConsecutiveFour(values)) {
        cout << "true\n";
    } else {
        cout << "false\n";
    }
    return 0;
}

