using namespace std;

bool isConsecutiveFour(const vector<vector<int>>& values) {
    int r = values.size();
    int c = values[0].size();
    const int dr[] = {0, 1, 1, 1};
    const int dc[] = {1, 0, 1, -1};

    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            for (int dir = 0; dir < 4; ++dir) {
                int nr = i + 3 * dr[dir];
                int nc = j + 3 * dc[dir];
                if (nr >= 0 && nr < r && nc >= 0 && nc < c) {
                    int v = values[i][j];
                    bool match = true;
                    for (int step = 1; step <= 3; ++step) {
                        if (values[i + step * dr[dir]][j + step * dc[dir]] != v) {
                            match = false;
                            break;
                        }
                    }
                    if (match) return true;
                }
            }
        }
    }
    return false;
}

