    double detA = a11 * a22 * a33 + a31 * a12 * a23 + a13 * a21 * a32
                - a13 * a22 * a31 - a11 * a23 * a32 - a33 * a21 * a12;

    if (fabs(detA) < 1e-9) {
        cout << "The equation has no solution.\n";
    } else {
        double numX = (a22 * a33 - a23 * a32) * b1 + (a13 * a32 - a12 * a33) * b2 + (a12 * a23 - a13 * a22) * b3;
        double numY = (a23 * a31 - a21 * a33) * b1 + (a11 * a33 - a13 * a31) * b2 + (a13 * a21 - a11 * a23) * b3;
        double numZ = (a21 * a32 - a22 * a31) * b1 + (a12 * a31 - a11 * a32) * b2 + (a11 * a22 - a12 * a21) * b3;

        double x = fixZero(numX / detA);
        double y = fixZero(numY / detA);
        double z = fixZero(numZ / detA);

        cout << fixed << setprecision(2);
        cout << "The solution is " << x << " " << y << " " << z << "\n";
    }
    return 0;
}

#include <cstdio>
#include <cmath>

int main() {
    double a[3][3];
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (scanf("%lf", &a[i][j]) != 1) return 0;
        }
    }
    double b[3];
    for (int i = 0; i < 3; ++i) {
        if (scanf("%lf", &b[i]) != 1) return 0;
    }

    auto det3 = [](double m[3][3]) {
        return m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
             - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
             + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
    };

    double d = det3(a);
    if (std::fabs(d) < 1e-9) {
        printf("The equation has no solution.\n");
        return 0;
    }

    double mx[3][3], my[3][3], mz[3][3];
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            mx[i][j] = a[i][j];
            my[i][j] = a[i][j];
            mz[i][j] = a[i][j];
        }
        mx[i][0] = b[i];
        my[i][1] = b[i];
        mz[i][2] = b[i];
    }

    double x = det3(mx) / d;
    double y = det3(my) / d;
    double z = det3(mz) / d;

    if (std::fabs(x) < 1e-7) x = 0.0;
    if (std::fabs(y) < 1e-7) y = 0.0;
    if (std::fabs(z) < 1e-7) z = 0.0;

    printf("The solution is %.2f %.2f %.2f\n", x, y, z);
    return 0;
}

