#include <iostream>
#include <vector>

using namespace std;

vector<int> findLargestBlock(const vector<vector<int>>& m) {
    int n = m.size();
    if (n == 0) return {0, 0, 0};

    vector<vector<int>> dp(n, vector<int>(n, 0));
    int max_size = 0;
    int best_r = 0, best_c = 0;

    // dp[i][j] stores the size of the largest square submatrix with bottom-right corner at (i, j)
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (m[i][j] == 1) {
                if (i == 0 || j == 0) {
                    dp[i][j] = 1;
                } else {
                    dp[i][j] = min(dp[i - 1][j], min(dp[i][j - 1], dp[i - 1][j - 1])) + 1;
                }
                if (dp[i][j] > max_size) {
                    max_size = dp[i][j];
                }
            }
        }
    }

    if (max_size == 0) {
        return {0, 0, 0};
    }

    // Tie-breaking: find the smallest top-left row, then col
    bool found = false;
    for (int r = 0; r <= n - max_size; ++r) {
        for (int c = 0; c <= n - max_size; ++c) {
            if (dp[r + max_size - 1][c + max_size - 1] >= max_size) {
                best_r = r;
                best_c = c;
                found = true;
                break;
            }
        }
        if (found) break;
    }

    return {best_r, best_c, max_size};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<vector<int>> m(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> m[i][j];
        }
    }
    vector<int> res = findLargestBlock(m);
    cout << "The maximum square submatrix is at (" << res[0] << ", " << res[1] << ") with size " << res[2] << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<int>> a(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    // 2D Prefix sums to check all 1s in O(1)
    vector<vector<int>> pref(n + 1, vector<int>(n + 1, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            pref[i + 1][j + 1] = a[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j];
        }
    }

    auto query = [&](int r1, int c1, int r2, int c2) {
        return pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
    };

    int best_k = 0;
    int best_r = 0, best_c = 0;

    for (int k = 1; k <= n; ++k) {
        for (int r = 0; r + k <= n; ++r) {
            for (int c = 0; c + k <= n; ++c) {
                if (query(r, c, r + k - 1, c + k - 1) == k * k) {
                    if (k > best_k) {
                        best_k = k;
                        best_r = r;
                        best_c = c;
                    }
                    break; // found smallest (r, c) for this k
                }
            }
            if (best_k == k) break;
        }
    }

    cout << "The maximum square submatrix is at (" << best_r << ", " << best_c << ") with size " << best_k << "\n";
    return 0;
}

