#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
#include <numeric>

using namespace std;

struct Fraction {
    long long num, den;
    Fraction(long long n = 0, long long d = 1) {
        if (d < 0) { n = -n; d = -d; }
        long long g = std::gcd(std::abs(n), std::abs(d));
        if (g == 0) g = 1;
        num = n / g;
        den = d / g;
    }
    Fraction operator+(const Fraction& o) const { return Fraction(num * o.den + o.num * den, den * o.den); }
    Fraction operator-(const Fraction& o) const { return Fraction(num * o.den - o.num * den, den * o.den); }
    Fraction operator*(const Fraction& o) const { return Fraction(num * o.num, den * o.den); }
    Fraction operator/(const Fraction& o) const { return Fraction(num * o.den, den * o.num); }
    bool operator==(const Fraction& o) const { return num == o.num && den == o.den; }
};

bool solve(vector<Fraction> cards, long long target) {
    if (cards.size() == 1) {
        return cards[0].den == 1 && cards[0].num == target;
    }
    int n = cards.size();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            vector<Fraction> nextCards;
            for (int k = 0; k < n; ++k) {
                if (k != i && k != j) nextCards.push_back(cards[k]);
            }
            // Try operations
            // +
            if (i < j) {
                nextCards.push_back(cards[i] + cards[j]);
                if (solve(nextCards, target)) return true;
                nextCards.pop_back();
            }
            // *
            if (i < j) {
                nextCards.push_back(cards[i] * cards[j]);
                if (solve(nextCards, target)) return true;
                nextCards.pop_back();
            }
            // -
            nextCards.push_back(cards[i] - cards[j]);
            if (solve(nextCards, target)) return true;
            nextCards.pop_back();
            // /
            if (cards[j].num != 0) {
                nextCards.push_back(cards[i] / cards[j]);
                if (solve(nextCards, target)) return true;
                nextCards.pop_back();
            }
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int M, TARGET;
    if (!(cin >> M >> TARGET)) return 0;

    int no_sol = 0, has_sol = 0;
    for (int a = 1; a <= M; ++a) {
        for (int b = a; b <= M; ++b) {
            for (int c = b; c <= M; ++c) {
                for (int d = c; d <= M; ++d) {
                    vector<Fraction> cards = {Fraction(a), Fraction(b), Fraction(c), Fraction(d)};
                    if (solve(cards, TARGET)) {
                        has_sol++;
                    } else {
                        no_sol++;
                    }
                }
            }
        }
    }

    cout << no_sol << " " << has_sol << " ";
    if (has_sol == 0) {
        cout << "inf\n";
    } else {
        cout << fixed << setprecision(4) << (double)no_sol / has_sol << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

const double EPS = 1e-7;

bool canAchieve(vector<double>& nums, double target) {
    if (nums.size() == 1) {
        return std::abs(nums[0] - target) < EPS;
    }
    int sz = nums.size();
    for (int i = 0; i < sz; ++i) {
        for (int j = 0; j < sz; ++j) {
            if (i == j) continue;
            vector<double> nextNums;
            nextNums.reserve(sz - 1);
            for (int k = 0; k < sz; ++k) {
                if (k != i && k != j) nextNums.push_back(nums[k]);
            }
            double a = nums[i], b = nums[j];
            if (i < j) {
                nextNums.push_back(a + b);
                if (canAchieve(nextNums, target)) return true;
                nextNums.back() = a * b;
                if (canAchieve(nextNums, target)) return true;
                nextNums.pop_back();
            }
            nextNums.push_back(a - b);
            if (canAchieve(nextNums, target)) return true;
            nextNums.pop_back();
            if (std::abs(b) > EPS) {
                nextNums.push_back(a / b);
                if (canAchieve(nextNums, target)) return true;
                nextNums.pop_back();
            }
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int M; double target;
    if (!(cin >> M >> target)) return 0;

    int no_cnt = 0, sol_cnt = 0;
    for (int a = 1; a <= M; ++a) {
        for (int b = a; b <= M; ++b) {
            for (int c = b; c <= M; ++c) {
                for (int d = c; d <= M; ++d) {
                    vector<double> nums = {(double)a, (double)b, (double)c, (double)d};
                    if (canAchieve(nums, target)) {
                        sol_cnt++;
                    } else {
                        no_cnt++;
                    }
                }
            }
        }
    }

    cout << no_cnt << " " << sol_cnt << " ";
    if (sol_cnt == 0) {
        cout << "inf\n";
    } else {
        cout << fixed << setprecision(4) << (double)no_cnt / sol_cnt << "\n";
    }
    return 0;
}

