#include <iostream>
#include <vector>
#include <string>

using namespace std;

const int ROWS = 6;
const int COLS = 7;

bool checkWin(const vector<vector<char>>& board, char color) {
    // Check horizontal
    for (int r = 0; r < ROWS; ++r) {
        for (int c = 0; c <= COLS - 4; ++c) {
            if (board[r][c] == color && board[r][c+1] == color &&
                board[r][c+2] == color && board[r][c+3] == color) return true;
        }
    }
    // Check vertical
    for (int r = 0; r <= ROWS - 4; ++r) {
        for (int c = 0; c < COLS; ++c) {
            if (board[r][c] == color && board[r+1][c] == color &&
                board[r+2][c] == color && board[r+3][c] == color) return true;
        }
    }
    // Check diagonal (down-right)
    for (int r = 0; r <= ROWS - 4; ++r) {
        for (int c = 0; c <= COLS - 4; ++c) {
            if (board[r][c] == color && board[r+1][c+1] == color &&
                board[r+2][c+2] == color && board[r+3][c+3] == color) return true;
        }
    }
    // Check diagonal (up-right)
    for (int r = 3; r < ROWS; ++r) {
        for (int c = 0; c <= COLS - 4; ++c) {
            if (board[r][c] == color && board[r-1][c+1] == color &&
                board[r-2][c+2] == color && board[r-3][c+3] == color) return true;
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<vector<char>> board(ROWS, vector<char>(COLS, ' '));
    vector<int> colCount(COLS, 0);

    string result = "Ongoing";
    int totalMoves = 0;
    bool finished = false;

    for (int i = 0; i < n; ++i) {
        int col;
        cin >> col;
        if (finished) continue;

        char player = (i % 2 == 0) ? 'R' : 'Y';
        int row = ROWS - 1 - colCount[col];
        board[row][col] = player;
        colCount[col]++;
        totalMoves++;

        if (checkWin(board, player)) {
            if (player == 'R') result = "The red player won";
            else result = "The yellow player won";
            finished = true;
        } else if (totalMoves == ROWS * COLS) {
            result = "Draw";
            finished = true;
        }
    }

    cout << result << "\n";
    return 0;
}

