using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int N;
    if (!(cin >> N)) return 0;

    // 6 rows (0 to 5, where 5 is bottom), 7 columns
    vector<vector<char>> grid(6, vector<char>(7, '.'));
    vector<int> top(7, 5); // bottom row starts at 5

    auto countDir = [&](int r, int c, int dr, int dc, char piece) {
        int cnt = 0;
        int cr = r + dr, cc = c + dc;
        while (cr >= 0 && cr < 6 && cc >= 0 && cc < 7 && grid[cr][cc] == piece) {
            cnt++;
            cr += dr;
            cc += dc;
        }
        return cnt;
    };

    auto hasFour = [&](int r, int c, char piece) {
        int dirs[4][2] = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};
        for (auto& d : dirs) {
            int total = 1 + countDir(r, c, d[0], d[1], piece) + countDir(r, c, -d[0], -d[1], piece);
            if (total >= 4) return true;
        }
        return false;
    };

    string outcome = "Ongoing";
    bool done = false;
    int piecesPlaced = 0;

    for (int step = 0; step < N; ++step) {
        int col;
        cin >> col;
        if (done) continue;

        char piece = (step % 2 == 0) ? 'R' : 'Y';
        int row = top[col]--;
        grid[row][col] = piece;
        piecesPlaced++;

        if (hasFour(row, col, piece)) {
            outcome = (piece == 'R') ? "The red player won" : "The yellow player won";
            done = true;
        } else if (piecesPlaced == 42) {
            outcome = "Draw";
            done = true;
        }
    }

    cout << outcome << "\n";
    return 0;
}

