trong đó:
- `rank` là một số nguyên (thứ hạng ban đầu trong bản ghi đó, bỏ qua khi xử lý);
- `boyName` là chuỗi ký tự gồm các chữ cái không chứa dấu cách, đại diện cho tên bé trai;
- `boyCount` là số nguyên dương — số lượng bé trai mang tên này;
- `girlName` là chuỗi ký tự gồm các chữ cái không chứa dấu cách, đại diện cho tên bé gái;
- `girlCount` là số nguyên dương — số lượng bé gái mang tên này.

references:
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

using namespace std;

struct NameRecord {
    string name;
    long long count;
};

bool compareRecords(const NameRecord& a, const NameRecord& b) {
    if (a.count != b.count) {
        return a.count > b.count;
    }
    return a.name < b.name;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    unordered_map<string, long long> boyCounts;
    unordered_map<string, long long> girlCounts;

    for (int i = 0; i < n; ++i) {
        int rank;
        string boyName, girlName;
        long long boyCount, girlCount;
        cin >> rank >> boyName >> boyCount >> girlName >> girlCount;
        boyCounts[boyName] += boyCount;
        girlCounts[girlName] += girlCount;
    }

    vector<NameRecord> boys;
    boys.reserve(boyCounts.size());
    for (auto const& [name, count] : boyCounts) {
        boys.push_back({name, count});
    }
    sort(boys.begin(), boys.end(), compareRecords);

    vector<NameRecord> girls;
    girls.reserve(girlCounts.size());
    for (auto const& [name, count] : girlCounts) {
        girls.push_back({name, count});
    }
    sort(girls.begin(), girls.end(), compareRecords);

    cout << "Boy names:\n";
    for (size_t i = 0; i < boys.size(); ++i) {
        cout << (i + 1) << " " << boys[i].name << " " << boys[i].count << "\n";
    }

    cout << "Girl names:\n";
    for (size_t i = 0; i < girls.size(); ++i) {
        cout << (i + 1) << " " << girls[i].name << " " << girls[i].count << "\n";
    }

    return 0;
}

