int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<int>> a(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            char c;
            cin >> c;
            while (c != '0' && c != '1') cin >> c;
            a[i][j] = c - '0';
        }
    }

    // Check rows
    vector<int> row0, row1;
    for (int i = 0; i < n; ++i) {
        bool all0 = true, all1 = true;
        for (int j = 0; j < n; ++j) {
            if (a[i][j] != 0) all0 = false;
            if (a[i][j] != 1) all1 = false;
        }
        if (all0) row0.push_back(i);
        if (all1) row1.push_back(i);
    }
    if (row0.empty() && row1.empty()) {
        cout << "No same numbers on a row\n";
    } else {
        if (!row0.empty()) printList("All 0s on row ", row0);
        if (!row1.empty()) printList("All 1s on row ", row1);
    }

    // Check columns
    vector<int> col0, col1;
    for (int j = 0; j < n; ++j) {
        bool all0 = true, all1 = true;
        for (int i = 0; i < n; ++i) {
            if (a[i][j] != 0) all0 = false;
            if (a[i][j] != 1) all1 = false;
        }
        if (all0) col0.push_back(j);
        if (all1) col1.push_back(j);
    }
    if (col0.empty() && col1.empty()) {
        cout << "No same numbers on a column\n";
    } else {
        if (!col0.empty()) printList("All 0s on column ", col0);
        if (!col1.empty()) printList("All 1s on column ", col1);
    }

    // Check major diagonal
    bool diag0 = true, diag1 = true;
    for (int i = 0; i < n; ++i) {
        if (a[i][i] != 0) diag0 = false;
        if (a[i][i] != 1) diag1 = false;
    }
    if (diag0) cout << "All 0s on the major diagonal\n";
    else if (diag1) cout << "All 1s on the major diagonal\n";
    else cout << "No same numbers on the major diagonal\n";

    // Check subdiagonal
    bool sub0 = true, sub1 = true;
    for (int i = 0; i < n; ++i) {
        if (a[i][n - 1 - i] != 0) sub0 = false;
        if (a[i][n - 1 - i] != 1) sub1 = false;
    }
    if (sub0) cout << "All 0s on the subdiagonal\n";
    else if (sub1) cout << "All 1s on the subdiagonal\n";
    else cout << "No same numbers on the subdiagonal\n";

    return 0;
}

