        string s = "";
        while ((int)s.length() < n) {
            string token;
            cin >> token;
            for (char ch : token) {
                if (ch == '0' || ch == '1') {
                    s.push_back(ch);
                }
            }
        }
        grid[i] = s;
    }

    // Rows
    vector<int> r0, r1;
    for (int r = 0; r < n; ++r) {
        int cnt1 = 0;
        for (int c = 0; c < n; ++c) {
            if (grid[r][c] == '1') cnt1++;
        }
        if (cnt1 == 0) r0.push_back(r);
        if (cnt1 == n) r1.push_back(r);
    }
    if (r0.empty() && r1.empty()) {
        cout << "No same numbers on a row\n";
    } else {
        if (!r0.empty()) {
            cout << "All 0s on row ";
            for (size_t i = 0; i < r0.size(); ++i) {
                cout << (i ? ", " : "") << r0[i];
            }
            cout << "\n";
        }
        if (!r1.empty()) {
            cout << "All 1s on row ";
            for (size_t i = 0; i < r1.size(); ++i) {
                cout << (i ? ", " : "") << r1[i];
            }
            cout << "\n";
        }
    }

    // Columns
    vector<int> c0, c1;
    for (int c = 0; c < n; ++c) {
        int cnt1 = 0;
        for (int r = 0; r < n; ++r) {
            if (grid[r][c] == '1') cnt1++;
        }
        if (cnt1 == 0) c0.push_back(c);
        if (cnt1 == n) c1.push_back(c);
    }
    if (c0.empty() && c1.empty()) {
        cout << "No same numbers on a column\n";
    } else {
        if (!c0.empty()) {
            cout << "All 0s on column ";
            for (size_t i = 0; i < c0.size(); ++i) {
                cout << (i ? ", " : "") << c0[i];
            }
            cout << "\n";
        }
        if (!c1.empty()) {
            cout << "All 1s on column ";
            for (size_t i = 0; i < c1.size(); ++i) {
                cout << (i ? ", " : "") << c1[i];
            }
            cout << "\n";
        }
    }

    // Major diagonal
    int major1 = 0;
    for (int i = 0; i < n; ++i) {
        if (grid[i][i] == '1') major1++;
    }
    if (major1 == 0) cout << "All 0s on the major diagonal\n";
    else if (major1 == n) cout << "All 1s on the major diagonal\n";
    else cout << "No same numbers on the major diagonal\n";

    // Subdiagonal
    int sub1 = 0;
    for (int i = 0; i < n; ++i) {
        if (grid[i][n - 1 - i] == '1') sub1++;
    }
