#include <iostream>
#include <iomanip>
#include <cmath>
#include <vector>

class Loan {
private:
    double annualInterestRate;
    int numberOfYears;
    double loanAmount;

public:
    Loan(double rate = 2.5, int years = 1, double amount = 1000.0) {
        annualInterestRate = rate;
        numberOfYears = years;
        loanAmount = amount;
    }

    double getLoanAmount() const {
        return loanAmount;
    }

    double getMonthlyPayment() const {
        if (annualInterestRate == 0.0) {
            return loanAmount / (numberOfYears * 12);
        }
        double monthlyInterestRate = annualInterestRate / 1200.0;
        double monthlyPayment = loanAmount * monthlyInterestRate / 
            (1.0 - std::pow(1.0 + monthlyInterestRate, -numberOfYears * 12));
        return monthlyPayment;
    }

    double getTotalPayment() const {
        return getMonthlyPayment() * numberOfYears * 12;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<Loan> loans;
    double totalLoanAmount = 0.0;

    for (int i = 0; i < n; ++i) {
        double rate, amount;
        int years;
        std::cin >> rate >> years >> amount;
        loans.emplace_back(rate, years, amount);
        totalLoanAmount += amount;
    }

    std::cout << std::fixed << std::setprecision(2);
    for (const auto& loan : loans) {
        std::cout << loan.getMonthlyPayment() << " " << loan.getTotalPayment() << "\n";
    }
    std::cout << totalLoanAmount << "\n";

    return 0;
}

#include <cstdio>
#include <vector>
#include <cmath>

struct LoanRecord {
    double rate;
    int years;
    double principal;

    double monthly() const {
        if (rate <= 1e-9) {
            return principal / (years * 12.0);
        }
        double mRate = rate / 1200.0;
        return principal * mRate / (1.0 - std::pow(1.0 + mRate, -years * 12.0));
    }

    double total() const {
        return monthly() * years * 12.0;
    }
};

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    std::vector<LoanRecord> records(n);
    double sumPrincipal = 0.0;

    for (int i = 0; i < n; ++i) {
        scanf("%lf %d %lf", &records[i].rate, &records[i].years, &records[i].principal);
        sumPrincipal += records[i].principal;
    }

    for (int i = 0; i < n; ++i) {
        printf("%.2f %.2f\n", records[i].monthly(), records[i].total());
    }
    printf("%.2f\n", sumPrincipal);

    return 0;
}

