};

bool compareDesc(const YearSummary& a, const YearSummary& b) {
    return a.year > b.year;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    if (!(cin >> t)) return 0;

    vector<YearSummary> summaries;
    summaries.reserve(t);

    for (int i = 0; i < t; ++i) {
        int year, k;
        cin >> year >> k;
        YearSummary ys;
        ys.year = year;
        for (int j = 0; j < k; ++j) {
            int r;
            string bName, gName;
            long long bCnt, gCnt;
            cin >> r >> bName >> bCnt >> gName >> gCnt;
            if (r >= 1 && r <= 5) {
                ys.boys[r - 1] = bName;
                ys.girls[r - 1] = gName;
            }
        }
        summaries.push_back(ys);
    }

    sort(summaries.begin(), summaries.end(), compareDesc);

    for (const auto& entry : summaries) {
        cout << entry.year;
        for (int r = 0; r < 5; ++r) {
            cout << ' ' << entry.girls[r];
        }
        for (int r = 0; r < 5; ++r) {
            cout << ' ' << entry.boys[r];
        }
        cout << '\n';
    }

