#include <bits/stdc++.h>
using namespace std;

void play_game(const string& secret, const string& guesses) {
    int n = secret.size();
    string displayed(n, '*');
    int errors = 0;
    int revealed_count = 0;

    for (char c : guesses) {
        // Check if c is already displayed
        bool already_open = false;
        for (int i = 0; i < n; ++i) {
            if (displayed[i] == c) {
                already_open = true;
                break;
            }
        }

        if (already_open) {
            cout << c << " da co trong tu\n";
        } else {
            bool in_secret = false;
            for (int i = 0; i < n; ++i) {
                if (secret[i] == c) {
                    displayed[i] = c;
                    in_secret = true;
                    revealed_count++;
                }
            }
            if (!in_secret) {
                errors++;
            }
        }

        cout << displayed << "\n";

        if (revealed_count == n) {
            cout << "Tu can doan la " << secret << ". So lan doan sai: " << errors << "\n";
            return;
        }
    }
}

