#include <iostream>
#include <cstring>

using namespace std;

class MyString {
private:
    char* buffer;
    size_t len;
    size_t cap;

    void reserve(size_t new_cap) {
        if (new_cap <= cap) return;
        char* new_buf = new char[new_cap + 1];
        if (buffer) {
            std::memcpy(new_buf, buffer, len);
            delete[] buffer;
        }
        buffer = new_buf;
        cap = new_cap;
        buffer[len] = '\0';
    }

public:
    MyString() : buffer(nullptr), len(0), cap(0) {
        reserve(16);
    }

    MyString(const char* s) : buffer(nullptr), len(0), cap(0) {
        len = std::strlen(s);
        cap = len;
        buffer = new char[cap + 1];
        std::memcpy(buffer, s, len + 1);
    }

    MyString(const MyString& other) : buffer(nullptr), len(0), cap(0) {
        len = other.len;
        cap = other.cap;
        buffer = new char[cap + 1];
        std::memcpy(buffer, other.buffer, len + 1);
    }

    MyString& operator=(const MyString& other) {
        if (this != &other) {
            delete[] buffer;
            len = other.len;
            cap = other.cap;
            buffer = new char[cap + 1];
            std::memcpy(buffer, other.buffer, len + 1);
        }
        return *this;
    }

    ~MyString() {
        delete[] buffer;
    }

    char& operator[](size_t index) {
        return buffer[index];
    }

    const char& operator[](size_t index) const {
        return buffer[index];
    }

    MyString& operator+=(const MyString& rhs) {
        if (len + rhs.len > cap) {
            size_t new_cap = (cap * 2 > len + rhs.len) ? cap * 2 : len + rhs.len;
            reserve(new_cap);
        }
        std::memcpy(buffer + len, rhs.buffer, rhs.len);
        len += rhs.len;
        buffer[len] = '\0';
        return *this;
    }

    friend MyString operator+(const MyString& lhs, const MyString& rhs) {
        MyString result(lhs);
        result += rhs;
        return result;
    }

    const char* c_str() const {
        return buffer ? buffer : "";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!(cin >> s)) return 0;

    MyString str(s.c_str());
    int q;
    if (!(cin >> q)) return 0;

    for (int k = 0; k < q; ++k) {
        int op;
        cin >> op;
        if (op == 1) {
            int idx;
            cin >> idx;
            cout << str[idx] << "\n";
        } else if (op == 2) {
            string t;
            cin >> t;
            str += MyString(t.c_str());
        } else if (op == 3) {
            string t;
            cin >> t;
            MyString res = str + MyString(t.c_str());
            cout << res.c_str() << "\n";
        }
    }
    cout << str.c_str() << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <numeric>

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        std::swap(a, b);
    }
    return a < 0 ? -a : a;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::string s;
    if (!(std::cin >> s)) return 0;

    bool negative = false;
    if (s[0] == '-') {
        negative = true;
        s = s.substr(1);
    }

    size_t dot_pos = s.find('.');
    long long num = 0;
    long long den = 1;

    if (dot_pos == std::string::npos) {
        num = std::stoll(s);
        den = 1;
    } else {
        std::string int_part = s.substr(0, dot_pos);
        std::string frac_part = s.substr(dot_pos + 1);
        long long whole = int_part.empty() ? 0 : std::stoll(int_part);
        long long frac = frac_part.empty() ? 0 : std::stoll(frac_part);
        for (size_t i = 0; i < frac_part.length(); ++i) {
            den *= 10;
        }
        num = whole * den + frac;
    }

    if (negative) {
        num = -num;
    }

    if (num == 0) {
        std::cout << "0/1\n";
        return 0;
    }

    long long g = gcd(num, den);
    num /= g;
    den /= g;
    if (den < 0) {
        num = -num;
        den = -den;
    }

    std::cout << num << "/" << den << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

long long calc_gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b > 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main() {
    std::string str;
    if (std::cin >> str) {
        int sign = 1;
        size_t start = 0;
        if (str[0] == '-') {
            sign = -1;
            start = 1;
        } else if (str[0] == '+') {
            start = 1;
        }

        size_t dot = str.find('.', start);
        long long numerator = 0;
        long long denominator = 1;

        if (dot == std::string::npos) {
            numerator = std::stoll(str.substr(start));
            denominator = 1;
        } else {
            std::string int_str = str.substr(start, dot - start);
            std::string frac_str = str.substr(dot + 1);

            long long int_val = int_str.empty() ? 0 : std::stoll(int_str);
            long long frac_val = frac_str.empty() ? 0 : std::stoll(frac_str);

            for (size_t i = 0; i < frac_str.size(); ++i) {
                denominator *= 10;
            }
            numerator = int_val * denominator + frac_val;
        }

        numerator *= sign;

        if (numerator == 0) {
            denominator = 1;
        } else {
            long long g = calc_gcd(numerator, denominator);
            numerator /= g;
            denominator /= g;
        }

        std::cout << numerator << "/" << denominator << "\n";
    }
    return 0;
}

