class GeometricObject {
private:
    std::string color;
    bool filled;

public:
    GeometricObject() : color("white"), filled(false) {}
    GeometricObject(const std::string& color, bool filled) : color(color), filled(filled) {}

    std::string getColor() const { return color; }
    void setColor(const std::string& color) { this->color = color; }

    bool isFilled() const { return filled; }
    void setFilled(bool filled) { this->filled = filled; }
};

class Triangle : public GeometricObject {
private:
    double side1, side2, side3;

public:
    Triangle() : side1(1.0), side2(1.0), side3(1.0) {}
    Triangle(double side1, double side2, double side3) : side1(side1), side2(side2), side3(side3) {}

    double getSide1() const { return side1; }
    double getSide2() const { return side2; }
    double getSide3() const { return side3; }

    double getPerimeter() const {
        return side1 + side2 + side3;
    }

    double getArea() const {
        double s = getPerimeter() / 2.0;
        return std::sqrt(s * (s - side1) * (s - side2) * (s - side3));
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    double s1, s2, s3;
    std::string color;
    int filledInt;

    if (std::cin >> s1 >> s2 >> s3 >> color >> filledInt) {
        Triangle t(s1, s2, s3);
        t.setColor(color);
        t.setFilled(filledInt != 0);

        std::cout << std::fixed << std::setprecision(2);
        std::cout << t.getArea() << "\n";
        std::cout << t.getPerimeter() << "\n";
        std::cout << t.getColor() << "\n";
        std::cout << (t.isFilled() ? "true" : "false") << "\n";
    }

    return 0;
}

