double calcDistance(const Point3D& a, const Point3D& b) {
    return std::hypot(a.x - b.x, a.y - b.y, a.z - b.z);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int numTests;
    if (std::cin >> numTests) {
        std::cout << std::fixed << std::setprecision(2);
        for (int i = 0; i < numTests; ++i) {
            Point3D p1, p2;
            std::cin >> p1.x >> p1.y >> p1.z >> p2.x >> p2.y >> p2.z;
            std::cout << calcDistance(p1, p2) << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

using namespace std;

template<typename T>
class GenericStack : public vector<T> {
public:
    bool isEmpty() const {
        return this->empty();
    }

    int getSize() const {
        return (int)this->size();
    }

    T peek() const {
        return this->back();
    }

    void push(const T& value) {
        this->push_back(value);
    }

    T pop() {
        T temp = this->back();
        this->pop_back();
        return temp;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int q;
    if (!(cin >> q)) return 0;

    GenericStack<string> st;

    while (q--) {
        string op;
        cin >> op;
        if (op == "push") {
            string val;
            cin >> val;
            st.push(val);
        } else if (op == "pop") {
            if (st.isEmpty()) {
                cout << "EMPTY\n";
            } else {
                cout << st.pop() << "\n";
            }
        } else if (op == "peek") {
            if (st.isEmpty()) {
                cout << "EMPTY\n";
            } else {
                cout << st.peek() << "\n";
            }
        } else if (op == "size") {
            cout << st.getSize() << "\n";
        } else if (op == "empty") {
            cout << (st.isEmpty() ? "true" : "false") << "\n";
        }
    }

    return 0;
}

