// Derived class extending std::vector<T>
template<class ElementType>
class MyDerivedStack : public std::vector<ElementType> {
public:
    MyDerivedStack() : std::vector<ElementType>() {}

    void pushElement(const ElementType& item) {
        this->push_back(item);
    }

    bool hasElements() const {
        return !this->empty();
    }

    ElementType getTop() const {
        return this->back();
    }

    ElementType removeTop() {
        ElementType topVal = this->back();
        this->pop_back();
        return topVal;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int numQueries;
    if (!(cin >> numQueries)) return 0;

    MyDerivedStack<string> stackInstance;

    for (int i = 0; i < numQueries; ++i) {
        string command;
        cin >> command;
        if (command == "push") {
            string element;
            cin >> element;
            stackInstance.pushElement(element);
        } else if (command == "pop") {
            if (!stackInstance.hasElements()) {
                cout << "EMPTY\n";
            } else {
                cout << stackInstance.removeTop() << "\n";
            }
        } else if (command == "peek") {
            if (!stackInstance.hasElements()) {
                cout << "EMPTY\n";
            } else {
                cout << stackInstance.getTop() << "\n";
            }
        } else if (command == "size") {
            cout << stackInstance.size() << "\n";
