class Account {
protected:
    int id;
    double balance;
public:
    Account(int id, double balance) : id(id), balance(balance) {}
    virtual ~Account() = default;

    virtual void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    virtual bool withdraw(double amount) {
        if (amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    virtual std::string toString() const {
        std::ostringstream oss;
        oss << std::fixed << std::setprecision(2);
        oss << "Account ID: " << id << ", Balance: " << balance;
        return oss.str();
    }
};

class SavingsAccount : public Account {
public:
    SavingsAccount(int id, double balance) : Account(id, balance) {}

    bool withdraw(double amount) override {
        if (amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    std::string toString() const override {
        std::ostringstream oss;
        oss << std::fixed << std::setprecision(2);
        oss << "SavingsAccount ID: " << id << ", Balance: " << balance;
        return oss.str();
    }
};

class CheckingAccount : public Account {
private:
    double overdraftLimit;
public:
    CheckingAccount(int id, double balance, double overdraftLimit)
        : Account(id, balance), overdraftLimit(overdraftLimit) {}

    bool withdraw(double amount) override {
        if (balance - amount >= -overdraftLimit - 1e-9) {
            balance -= amount;
            return true;
        }
        return false;
    }

    std::string toString() const override {
        std::ostringstream oss;
        oss << std::fixed << std::setprecision(2);
        oss << "CheckingAccount ID: " << id << ", Balance: " << balance
            << ", Overdraft Limit: " << overdraftLimit;
        return oss.str();
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) return 0;

    std::map<int, std::shared_ptr<Account>> accounts;
    for (int i = 0; i < n; ++i) {
        int type, id;
        double bal;
        std::cin >> type >> id >> bal;
        if (type == 1) {
            accounts[id] = std::make_shared<Account>(id, bal);
        } else if (type == 2) {
            accounts[id] = std::make_shared<SavingsAccount>(id, bal);
        } else if (type == 3) {
            double limit;
            std::cin >> limit;
            accounts[id] = std::make_shared<CheckingAccount>(id, bal, limit);
        }
    }

    int q;
    if (!(std::cin >> q)) return 0;
    while (q--) {
        std::string cmd;
        int id;
        std::cin >> cmd >> id;
        if (cmd == "DEPOSIT") {
            double amount;
            std::cin >> amount;
            accounts[id]->deposit(amount);
        } else if (cmd == "WITHDRAW") {
            double amount;
            std::cin >> amount;
            accounts[id]->withdraw(amount);
        } else if (cmd == "PRINT") {
            std::cout << accounts[id]->toString() << "\n";
        }
    }

    return 0;
}

