    for (char c : s) {
        long long val = hexCharToDec(c);
        if (val == -1) {
            valid = false;
            break;
        }
        decimalValue = decimalValue * 16 + val;
    }

    if (valid) {
        cout << decimalValue << "\n";
    } else {
        cout << "invalid_argument\n";
    }
    return 0;
}

