#include <iostream>
#include <numeric>
#include <string>

class Rational {
private:
    long long r[2]; // r[0]: numerator, r[1]: denominator

    void reduce() {
        if (r[1] < 0) {
            r[0] = -r[0];
            r[1] = -r[1];
        }
        if (r[0] == 0) {
            r[1] = 1;
            return;
        }
        long long g = std::gcd(std::abs(r[0]), r[1]);
        r[0] /= g;
        r[1] /= g;
    }

public:
    Rational(long long num = 0, long long den = 1) {
        r[0] = num;
        r[1] = den;
        reduce();
    }

    long long getNumerator() const { return r[0]; }
    long long getDenominator() const { return r[1]; }

    Rational add(const Rational& second) const {
        long long num = r[0] * second.r[1] + r[1] * second.r[0];
        long long den = r[1] * second.r[1];
        return Rational(num, den);
    }

    Rational subtract(const Rational& second) const {
        long long num = r[0] * second.r[1] - r[1] * second.r[0];
        long long den = r[1] * second.r[1];
        return Rational(num, den);
    }

    Rational multiply(const Rational& second) const {
        long long num = r[0] * second.r[0];
        long long den = r[1] * second.r[1];
        return Rational(num, den);
    }

    Rational divide(const Rational& second) const {
        long long num = r[0] * second.r[1];
        long long den = r[1] * second.r[0];
        return Rational(num, den);
    }

    void print() const {
        if (r[1] == 1) {
            std::cout << r[0] << "\n";
        } else {
            std::cout << r[0] << "/" << r[1] << "\n";
        }
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int t;
    if (!(std::cin >> t)) return 0;
    while (t--) {
        long long a, b, c, d;
        char op;
        std::cin >> a >> b >> op >> c >> d;
        Rational r1(a, b), r2(c, d);
        Rational res;
        if (op == '+') res = r1.add(r2);
        else if (op == '-') res = r1.subtract(r2);
        else if (op == '*') res = r1.multiply(r2);
        else if (op == '/') res = r1.divide(r2);
        res.print();
    }
    return 0;
}

#include <iostream>
