long long gcd_val(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a < 0 ? -a : a;
}

class Rational {
    int r[2];

    void simplify() {
        if (r[1] < 0) {
            r[0] = -r[0];
            r[1] = -r[1];
        }
        if (r[0] == 0) {
            r[1] = 1;
            return;
        }
        long long g = gcd_val(r[0], r[1]);
        r[0] /= g;
        r[1] /= g;
    }

public:
    Rational(long long n = 0, long long d = 1) {
        r[0] = n;
        r[1] = d;
        simplify();
    }

    friend Rational operator+(const Rational& lhs, const Rational& rhs) {
        long long n = (long long)lhs.r[0] * rhs.r[1] + (long long)lhs.r[1] * rhs.r[0];
        long long d = (long long)lhs.r[1] * rhs.r[1];
        return Rational(n, d);
    }

    friend Rational operator-(const Rational& lhs, const Rational& rhs) {
        long long n = (long long)lhs.r[0] * rhs.r[1] - (long long)lhs.r[1] * rhs.r[0];
        long long d = (long long)lhs.r[1] * rhs.r[1];
        return Rational(n, d);
    }

    friend Rational operator*(const Rational& lhs, const Rational& rhs) {
        long long n = (long long)lhs.r[0] * rhs.r[0];
        long long d = (long long)lhs.r[1] * rhs.r[1];
        return Rational(n, d);
    }

    friend Rational operator/(const Rational& lhs, const Rational& rhs) {
        long long n = (long long)lhs.r[0] * rhs.r[1];
        long long d = (long long)lhs.r[1] * rhs.r[0];
        return Rational(n, d);
    }

    friend std::ostream& operator<<(std::ostream& os, const Rational& q) {
        if (q.r[1] == 1) {
            os << q.r[0];
        } else {
            os << q.r[0] << "/" << q.r[1];
        }
        return os;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    int T;
    if (std::cin >> T) {
        while (T--) {
            long long a, b, c, d;
            char op;
            std::cin >> a >> b >> op >> c >> d;
            Rational r1(a, b), r2(c, d);
            Rational ans;
            switch (op) {
                case '+': ans = r1 + r2; break;
                case '-': ans = r1 - r2; break;
                case '*': ans = r1 * r2; break;
                case '/': ans = r1 / r2; break;
            }
            std::cout << ans << "\n";
        }
    }
    return 0;
}

