class HexFormatException {
private:
    std::string message;
public:
    HexFormatException(const std::string& msg = "HexFormatException") : message(msg) {}
    const std::string& getMessage() const { return message; }
};

long long hex2Dec(const std::string& hexString) {
    if (hexString.empty()) {
        throw HexFormatException("Empty string");
    }
    long long decimalValue = 0;
    for (char ch : hexString) {
        char upper = std::toupper(static_cast<unsigned char>(ch));
        int digit = 0;
        if (upper >= '0' && upper <= '9') {
            digit = upper - '0';
        } else if (upper >= 'A' && upper <= 'F') {
            digit = 10 + (upper - 'A');
        } else {
            throw HexFormatException("Invalid hex character");
        }
        decimalValue = decimalValue * 16 + digit;
    }
    return decimalValue;
}

