    long long ans = 0;
    for (size_t i = 0; i < hexString.length(); ++i) {
        int val = hexCharToVal(hexString[i]);
        if (val == -1) {
            throw HexFormatException();
        }
        ans = (ans << 4) | val;
    }
    return ans;
}

