class RuntimeError {
private:
    const char* msg;
public:
    RuntimeError(const char* m) : msg(m) {}
    const char* what() const { return msg; }
};

class Rational {
private:
    long long numerator;
    long long denominator;

    static long long gcd(long long x, long long y) {
        while (y != 0) {
            long long t = x % y;
            x = y;
            y = t;
        }
        return x < 0 ? -x : x;
    }

public:
    Rational(long long num = 0, long long den = 1) {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        long long g = gcd(std::abs(num), den);
        numerator = num / g;
        denominator = den / g;
    }

    long long operator[](int index) const {
        if (index == 0) return numerator;
        if (index == 1) return denominator;
        throw RuntimeError("Index out of range");
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

