struct MyRuntimeError {
    const char* message;
    MyRuntimeError(const char* m) : message(m) {}
    const char* what() const { return message; }
};

long long findGCD(long long u, long long v) {
    if (u < 0) u = -u;
    if (v < 0) v = -v;
    while (v > 0) {
        long long r = u % v;
        u = v;
        v = r;
    }
    return u;
}

class Rational {
    long long n, d;
public:
    Rational(long long num, long long den) {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        long long g = findGCD(num, den);
        if (g == 0) g = 1;
        n = num / g;
        d = den / g;
    }

    long long operator[](int i) const {
        switch (i) {
            case 0: return n;
            case 1: return d;
            default: throw MyRuntimeError("Index out of range");
        }
    }
};

