class BinaryFormatException {
};

std::string bin2Octal(const std::string& binaryString) {
    if (binaryString.empty()) {
        throw BinaryFormatException();
    }
    for (char c : binaryString) {
        if (c != '0' && c != '1') {
            throw BinaryFormatException();
        }
    }

    int i = 0;
    while (i < (int)binaryString.size() - 1 && binaryString[i] == '0') {
        i++;
    }
    std::string s = binaryString.substr(i);

    int rem = s.size() % 3;
    if (rem != 0) {
        s = std::string(3 - rem, '0') + s;
    }

    std::string octal = "";
    for (size_t j = 0; j < s.size(); j += 3) {
        int val = (s[j] - '0') * 4 + (s[j + 1] - '0') * 2 + (s[j + 2] - '0');
        octal += std::to_string(val);
    }

    size_t start = 0;
    while (start < octal.size() - 1 && octal[start] == '0') {
        start++;
    }
    return octal.substr(start);
}

