class BinaryFormatException {};

std::string bin2Octal(const std::string& s) {
    if (s.empty()) throw BinaryFormatException();
    for (char ch : s) {
        if (ch != '0' && ch != '1') {
            throw BinaryFormatException();
        }
    }

    std::string res = "";
    int n = s.length();
    for (int i = n; i > 0; i -= 3) {
        int chunk = 0;
        int p = 1;
        for (int j = i - 1; j >= std::max(0, i - 3); --j) {
            chunk += (s[j] - '0') * p;
            p *= 2;
        }
        res += (char)('0' + chunk);
    }
    std::reverse(res.begin(), res.end());

    size_t firstNonZero = res.find_first_not_of('0');
    if (firstNonZero == std::string::npos) {
        return "0";
    }
    return res.substr(firstNonZero);
}

