            stack.push(x);
        } else if (op == "pop") {
            try {
                int val = stack.pop();
                std::cout << val << "\n";
            } catch (const EmptyStackException&) {
                std::cout << "EmptyStackException\n";
            }
        } else if (op == "peek") {
            try {
                int val = stack.peek();
                std::cout << val << "\n";
            } catch (const EmptyStackException&) {
                std::cout << "EmptyStackException\n";
            }
        }
    }

