}

#include <iostream>
#include <string>

class EmptyStackException {
};

class StackOfIntegers {
private:
    int* data;
    int capacity;
    int topIndex;

    void resize() {
        int newCap = capacity * 2;
        int* newData = new int[newCap];
        for (int i = 0; i < capacity; ++i) {
            newData[i] = data[i];
        }
        delete[] data;
        data = newData;
        capacity = newCap;
    }

public:
    StackOfIntegers(int cap = 16) : capacity(cap), topIndex(0) {
        data = new int[capacity];
    }

    ~StackOfIntegers() {
        delete[] data;
    }

    void push(int value) {
        if (topIndex == capacity) {
            resize();
        }
        data[topIndex++] = value;
    }

    int pop() {
        if (topIndex == 0) {
            throw EmptyStackException();
        }
        return data[--topIndex];
    }

    int peek() const {
        if (topIndex == 0) {
            throw EmptyStackException();
        }
        return data[topIndex - 1];
    }

    bool empty() const {
        return topIndex == 0;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int q;
    if (!(std::cin >> q)) return 0;

    StackOfIntegers s;
    for (int i = 0; i < q; ++i) {
        std::string command;
        std::cin >> command;
