            try {
                std::cout << s.pop() << "\n";
            } catch (const EmptyStackException&) {
                std::cout << "EmptyStackException\n";
            }
        } else if (command == "peek") {
            try {
                std::cout << s.peek() << "\n";
            } catch (const EmptyStackException&) {
                std::cout << "EmptyStackException\n";
            }
        }
    }
    return 0;
}

