using namespace std;

double det3(double m[3][3]) {
    return m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
         - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
         + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double a[3][3];
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (!(cin >> a[i][j])) return 0;
        }
    }
    double b[3];
    for (int i = 0; i < 3; ++i) {
        cin >> b[i];
    }

    double detA = det3(a);
    if (fabs(detA) < 1e-9) {
        cout << "The equation has no solution\n";
    } else {
        double a1[3][3], a2[3][3], a3[3][3];
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                a1[i][j] = (j == 0 ? b[i] : a[i][j]);
                a2[i][j] = (j == 1 ? b[i] : a[i][j]);
                a3[i][j] = (j == 2 ? b[i] : a[i][j]);
            }
        }
        double x = det3(a1) / detA;
        double y = det3(a2) / detA;
        double z = det3(a3) / detA;

        if (fabs(x) < 1e-7) x = 0.0;
        if (fabs(y) < 1e-7) y = 0.0;
        if (fabs(z) < 1e-7) z = 0.0;

        cout << fixed << setprecision(2) << x << " " << y << " " << z << "\n";
    }
    return 0;
}

