using namespace std;

double computeDet(const vector<vector<double>>& m) {
    return m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
         - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
         + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<vector<double>> a(3, vector<double>(3));
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (!(cin >> a[i][j])) return 0;
        }
    }
    vector<double> b(3);
    for (int i = 0; i < 3; ++i) {
        cin >> b[i];
    }

    double d = computeDet(a);
    if (abs(d) < 1e-9) {
        cout << "The equation has no solution\n";
    } else {
        vector<vector<double>> ax = a, ay = a, az = a;
        for (int i = 0; i < 3; ++i) {
            ax[i][0] = b[i];
            ay[i][1] = b[i];
            az[i][2] = b[i];
        }
        double x = computeDet(ax) / d;
        double y = computeDet(ay) / d;
        double z = computeDet(az) / d;

        auto fixZero = [](double val) {
            return (abs(val) < 1e-7) ? 0.0 : val;
        };

        cout << fixed << setprecision(2)
             << fixZero(x) << " "
             << fixZero(y) << " "
             << fixZero(z) << "\n";
    }
    return 0;
}

