// Divide-and-conquer recursive function to find minimum element
long long findMinDivideAndConquer(const vector<long long>& arr, int l, int r) {
    if (l == r) {
        return arr[l];
    }
    int mid = l + (r - l) / 2;
    long long minLeft = findMinDivideAndConquer(arr, l, mid);
    long long minRight = findMinDivideAndConquer(arr, mid + 1, r);
    return (minLeft < minRight) ? minLeft : minRight;
}

