    if (getline(cin, s)) {
        // To avoid deep recursion stack overflow for long strings up to 10^5 in reference,
        // we can implement a tail-call or divide-and-conquer recursion.
        // Let's use divide and conquer recursion for safety with deep call stacks:
    }
    // Re-evaluating getNumberOfLowercaseLetters with divide-and-conquer to handle constraints safely without stack overflow:
    auto countDC = [](auto& self, const string& str, int l, int r) -> int {
        if (l > r) return 0;
        if (l == r) return (str[l] >= 'a' && str[l] <= 'z') ? 1 : 0;
        int mid = l + (r - l) / 2;
        return self(self, str, l, mid) + self(self, str, mid + 1, r);
    };
    cout << countDC(countDC, s, 0, (int)s.length() - 1) << "\n";
    return 0;
}

