// Helper recursive function
int binaryToDecimalHelper(const string& binaryString, int index) {
    if (index == (int)binaryString.length()) {
        return 0;
    }
    return (binaryString[index] - '0') * (1 << (binaryString.length() - 1 - index)) + binaryToDecimalHelper(binaryString, index + 1);
}

int binaryToDecimal(const string& binaryString) {
    return binaryToDecimalHelper(binaryString, 0);
}

