using namespace std;

// Alternative recursive approach using Horner's method / prefix recursion
int binaryToDecimalRecursive(const string& s, int n) {
    if (n == 0) {
        return 0;
    }
    return (binaryToDecimalRecursive(s, n - 1) << 1) + (s[n - 1] - '0');
}

int binaryToDecimal(const string& binaryString) {
    return binaryToDecimalRecursive(binaryString, binaryString.length());
}

