#include <cctype>

int hexCharToDecimal(char ch) {
    if (ch >= '0' && ch <= '9') {
        return ch - '0';
    }
    ch = std::toupper(ch);
    return 10 + (ch - 'A');
}

long long hexToDecimalHelper(const std::string& hexString, size_t index) {
    if (index == hexString.length()) {
        return 0;
    }
    return hexCharToDecimal(hexString[index]) + 16LL * hexToDecimalHelper(hexString, index + 1);
}

long long hexToDecimal(const std::string& hexString) {
    if (hexString.empty()) return 0;
    int lastVal = hexCharToDecimal(hexString.back());
    if (hexString.length() == 1) {
        return lastVal;
    }
    return hexToDecimal(hexString.substr(0, hexString.length() - 1)) * 16LL + lastVal;
}

