int charValue(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    return 0;
}

long long parseHexRecursive(const std::string& s, size_t pos, long long currentVal) {
    if (pos == s.length()) {
        return currentVal;
    }
    return parseHexRecursive(s, pos + 1, currentVal * 16LL + charValue(s[pos]));
}

