using namespace std;

int grid[9][9];

bool isValid(int r, int c, int val) {
    for (int i = 0; i < 9; ++i) {
        if (grid[r][i] == val) return false;
        if (grid[i][c] == val) return false;
    }
    int startR = (r / 3) * 3;
    int startC = (c / 3) * 3;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (grid[startR + i][startC + j] == val) return false;
        }
    }
    return true;
}

bool solve(int r, int c) {
    if (r == 9) return true;
    if (c == 9) return solve(r + 1, 0);
    if (grid[r][c] != 0) return solve(r, c + 1);

    for (int num = 1; num <= 9; ++num) {
        if (isValid(r, c, num)) {
            grid[r][c] = num;
            if (solve(r, c + 1)) return true;
            grid[r][c] = 0;
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    bool initialValid = true;
    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            if (!(cin >> grid[i][j])) return 0;
        }
    }

    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            if (grid[i][j] != 0) {
                int v = grid[i][j];
                grid[i][j] = 0;
                if (!isValid(i, j, v)) initialValid = false;
                grid[i][j] = v;
            }
        }
    }

    if (initialValid && solve(0, 0)) {
        for (int i = 0; i < 9; ++i) {
            for (int j = 0; j < 9; ++j) {
                cout << grid[i][j] << (j == 8 ? "" : " ");
            }
            cout << "\n";
        }
    } else {
        cout << "No solution\n";
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int board[9][9];
int rowMask[9], colMask[9], boxMask[9];

bool dfs(int idx, const vector<pair<int, int>>& emptyCells) {
    if (idx == (int)emptyCells.size()) return true;
    int r = emptyCells[idx].first;
    int c = emptyCells[idx].second;
    int b = (r / 3) * 3 + (c / 3);

    for (int v = 1; v <= 9; ++v) {
        int bit = (1 << v);
        if (!(rowMask[r] & bit) && !(colMask[c] & bit) && !(boxMask[b] & bit)) {
            board[r][c] = v;
            rowMask[r] |= bit;
            colMask[c] |= bit;
            boxMask[b] |= bit;

            if (dfs(idx + 1, emptyCells)) return true;

            board[r][c] = 0;
            rowMask[r] &= ~bit;
            colMask[c] &= ~bit;
            boxMask[b] &= ~bit;
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<pair<int, int>> emptyCells;
    bool ok = true;

    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            if (!(cin >> board[i][j])) return 0;
            int v = board[i][j];
            if (v != 0) {
                int bit = (1 << v);
                int b = (i / 3) * 3 + (j / 3);
                if ((rowMask[i] & bit) || (colMask[j] & bit) || (boxMask[b] & bit)) {
                    ok = false;
                }
                rowMask[i] |= bit;
                colMask[j] |= bit;
                boxMask[b] |= bit;
            } else {
                emptyCells.push_back({i, j});
            }
        }
    }

    if (ok && dfs(0, emptyCells)) {
        for (int i = 0; i < 9; ++i) {
            for (int j = 0; j < 9; ++j) {
                cout << board[i][j] << (j == 8 ? "" : " ");
            }
            cout << "\n";
        }
    } else {
        cout << "No solution\n";
    }

    return 0;
}

