#include <iostream>
#include <vector>

using namespace std;

struct SudokuSolver {
    int grid[9][9];
    int rowMask[9] = {0};
    int colMask[9] = {0};
    int boxMask[3][3] = {0};
    vector<pair<int, int>> emptyCells;
    vector<vector<vector<int>>> solutions;

    bool isValidInitial() {
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                int val = grid[r][c];
                if (val > 0) {
                    int mask = 1 << val;
                    if ((rowMask[r] & mask) || (colMask[c] & mask) || (boxMask[r / 3][c / 3] & mask)) {
                        return false;
                    }
                    rowMask[r] |= mask;
                    colMask[c] |= mask;
                    boxMask[r / 3][c / 3] |= mask;
                } else {
                    emptyCells.push_back({r, c});
                }
            }
        }
        return true;
    }

    void backtrack(size_t idx) {
        if (idx == emptyCells.size()) {
            vector<vector<int>> sol(9, vector<int>(9));
            for (int r = 0; r < 9; ++r) {
                for (int c = 0; c < 9; ++c) {
                    sol[r][c] = grid[r][c];
                }
            }
            solutions.push_back(sol);
            return;
        }

        int r = emptyCells[idx].first;
        int c = emptyCells[idx].second;
        int br = r / 3, bc = c / 3;
        int used = rowMask[r] | colMask[c] | boxMask[br][bc];

        for (int num = 1; num <= 9; ++num) {
            if (!(used & (1 << num))) {
                grid[r][c] = num;
                rowMask[r] |= (1 << num);
                colMask[c] |= (1 << num);
                boxMask[br][bc] |= (1 << num);

                backtrack(idx + 1);

                boxMask[br][bc] &= ~(1 << num);
                colMask[c] &= ~(1 << num);
                rowMask[r] &= ~(1 << num);
                grid[r][c] = 0;
            }
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    SudokuSolver solver;
    for (int r = 0; r < 9; ++r) {
        for (int c = 0; c < 9; ++c) {
            if (!(cin >> solver.grid[r][c])) return 0;
        }
    }

    if (solver.isValidInitial()) {
        solver.backtrack(0);
    }

    cout << solver.solutions.size() << "\n";
    for (const auto& sol : solver.solutions) {
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                cout << sol[r][c] << (c == 8 ? "" : " ");
            }
            cout << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int board[9][9];
vector<vector<vector<int>>> allSolutions;

bool canPlace(int r, int c, int num) {
    for (int i = 0; i < 9; ++i) {
        if (board[r][i] == num || board[i][c] == num) return false;
    }
    int startR = (r / 3) * 3;
    int startC = (c / 3) * 3;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (board[startR + i][startC + j] == num) return false;
        }
    }
    return true;
}

void solve(int cellIndex) {
    if (cellIndex == 81) {
        vector<vector<int>> cur(9, vector<int>(9));
        for (int i = 0; i < 9; ++i) {
            for (int j = 0; j < 9; ++j) {
                cur[i][j] = board[i][j];
            }
        }
        allSolutions.push_back(cur);
        return;
    }

    int r = cellIndex / 9;
    int c = cellIndex % 9;

    if (board[r][c] != 0) {
        solve(cellIndex + 1);
    } else {
        for (int num = 1; num <= 9; ++num) {
            if (canPlace(r, c, num)) {
                board[r][c] = num;
                solve(cellIndex + 1);
                board[r][c] = 0;
            }
        }
    }
}

bool checkInitialState() {
    for (int r = 0; r < 9; ++r) {
        for (int c = 0; c < 9; ++c) {
            if (board[r][c] != 0) {
                int val = board[r][c];
                board[r][c] = 0;
                if (!canPlace(r, c, val)) {
                    board[r][c] = val;
                    return false;
                }
                board[r][c] = val;
            }
        }
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    for (int i = 0; i < 9; ++i) {
        for (int j = 0; j < 9; ++j) {
            if (!(cin >> board[i][j])) return 0;
        }
    }

    if (checkInitialState()) {
        solve(0);
    }

    cout << allSolutions.size() << "\n";
    for (size_t s = 0; s < allSolutions.size(); ++s) {
        for (int i = 0; i < 9; ++i) {
            for (int j = 0; j < 9; ++j) {
                cout << allSolutions[s][i][j] << (j == 8 ? "" : " ");
            }
            cout << "\n";
        }
    }

    return 0;
}

