using namespace std;

struct Date {
    int day, month, year;
};

int calculateAge(const Date& birth, const Date& current) {
    int age = current.year - birth.year;
    if (current.month < birth.month || (current.month == birth.month && current.day < birth.day)) {
        age--;
    }
    return age;
}

int main() {
    string firstName, lastName;
    if (!(cin >> firstName >> lastName)) return 0;

    Date birth, current;
    cin >> birth.day >> birth.month >> birth.year;
    cin >> current.day >> current.month >> current.year;

    int age = calculateAge(birth, current);
    int maxHeartRate = 220 - age;
    double targetLow = maxHeartRate * 0.5;
    double targetHigh = maxHeartRate * 0.85;

    cout << "Name: " << firstName << " " << lastName << "\n";
    cout << "Date of Birth: " << birth.day << "/" << birth.month << "/" << birth.year << "\n";
    cout << "Age: " << age << ", Max Heart Rate: " << maxHeartRate << " bpm\n";
    printf("Target Heart Rate Range: %.1f - %.1f bpm\n", targetLow, targetHigh);

    return 0;
}

