#include <iostream>
#include <string>
#include <iomanip>

using namespace std;

class HealthProfile {
private:
    string firstName;
    string lastName;
    string gender;
    int birthDay, birthMonth, birthYear;
    double height; // inches
    double weight; // pounds

public:
    HealthProfile(string fName, string lName, string gen, int bDay, int bMonth, int bYear, double h, double w)
        : firstName(fName), lastName(lName), gender(gen), birthDay(bDay), birthMonth(bMonth), birthYear(bYear), height(h), weight(w) {}

    int getAge(int curDay, int curMonth, int curYear) const {
        int age = curYear - birthYear;
        if (curMonth < birthMonth || (curMonth == birthMonth && curDay < birthDay)) {
            age--;
        }
        return age;
    }

    int getMaxHeartRate(int age) const {
        return 220 - age;
    }

    double getMinTargetHeartRate(int maxHR) const {
        return 0.50 * maxHR;
    }

    double getMaxTargetHeartRate(int maxHR) const {
        return 0.85 * maxHR;
    }

    double getBMI() const {
        return (weight * 703.0) / (height * height);
    }

    string getFullName() const {
        return lastName + " " + firstName;
    }

    string getGender() const {
        return gender;
    }

    void printDOB() const {
        cout << birthDay << "/" << birthMonth << "/" << birthYear;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string lastName, firstName, gender;
    if (!(cin >> lastName >> firstName >> gender)) return 0;

    int bDay, bMonth, bYear;
    cin >> bDay >> bMonth >> bYear;

    int cDay, cMonth, cYear;
    cin >> cDay >> cMonth >> cYear;

    double height, weight;
    cin >> height >> weight;

    HealthProfile profile(firstName, lastName, gender, bDay, bMonth, bYear, height, weight);

    int age = profile.getAge(cDay, cMonth, cYear);
    int maxHR = profile.getMaxHeartRate(age);
    double minTarget = profile.getMinTargetHeartRate(maxHR);
    double maxTarget = profile.getMaxTargetHeartRate(maxHR);
    double bmi = profile.getBMI();

    cout << "Ho va ten: " << profile.getFullName() << "\n";
    cout << "Gioi tinh: " << profile.getGender() << "\n";
    cout << "Ngay sinh: ";
    profile.printDOB();
    cout << "\n";
    cout << "Tuoi: " << age << "\n";
    cout << fixed << setprecision(1);
    cout << "BMI: " << bmi << "\n";
    cout << "Nhip tim toi da: " << maxHR << " bpm\n";
    cout << "Khoang nhip tim muc tieu: " << minTarget << " - " << maxTarget << " bpm\n";

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct Date {
    int day;
    int month;
    int year;
};

int calculateAge(const Date& dob, const Date& cur) {
    int age = cur.year - dob.year;
    if (cur.month < dob.month || (cur.month == dob.month && cur.day < dob.day)) {
        age--;
    }
    return age;
}

