using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n;
    if (!(cin >> n)) return 0;

    long long fact = 1;
    long long i = 1;
    while (i <= n) {
        fact *= i;
        i++;
    }
    cout << fact << "\n";

    int k1;
    cin >> k1;
    double e_est = 0.0;
    double term1 = 1.0;
    int count1 = 0;
    while (count1 < k1) {
        e_est += term1;
        count1++;
        if (count1 < k1) {
            term1 /= count1;
        }
    }
    cout << fixed << setprecision(8) << e_est << "\n";

    double x;
    int k2;
    cin >> x >> k2;
    double ex_est = 0.0;
    double term2 = 1.0;
    int count2 = 0;
    while (count2 < k2) {
        ex_est += term2;
        count2++;
        if (count2 < k2) {
            term2 = term2 * x / count2;
        }
    }
    cout << fixed << setprecision(8) << ex_est << "\n";

    return 0;
}

#include <cstdio>

int main() {
