    while (idx < k1) {
        sum_e += cur_term;
        idx++;
        cur_term /= (double)idx;
    }
    printf("%.8f\n", sum_e);

    double x;
    int k2;
    scanf("%lf %d", &x, &k2);
    double sum_ex = 0.0;
    double cur_ex_term = 1.0;
    idx = 0;
    while (idx < k2) {
        sum_ex += cur_ex_term;
        idx++;
        cur_ex_term = (cur_ex_term * x) / (double)idx;
    }
    printf("%.8f\n", sum_ex);

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

using namespace std;

string encrypt(const string& s) {
    vector<int> d(4);
    for (int i = 0; i < 4; ++i) {
        d[i] = (s[i] - '0' + 7) % 10;
    }
    swap(d[0], d[2]);
    swap(d[1], d[3]);
    string res = "";
    for (int i = 0; i < 4; ++i) {
        res += to_string(d[i]);
    }
    return res;
}

string decrypt(const string& s) {
    vector<int> d(4);
    for (int i = 0; i < 4; ++i) {
        d[i] = s[i] - '0';
    }
    swap(d[0], d[2]);
    swap(d[1], d[3]);
    string res = "";
    for (int i = 0; i < 4; ++i) {
        int orig = (d[i] + 10 - 7) % 10;
        res += to_string(orig);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int mode;
        string s;
        cin >> mode >> s;
        if (mode == 1) {
            cout << encrypt(s) << "\n";
        } else {
            cout << decrypt(s) << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (cin >> T) {
        while (T--) {
            int type;
            string str;
            cin >> type >> str;
            char a = str[0], b = str[1], c = str[2], d = str[3];
            if (type == 1) {
                int na = (a - '0' + 7) % 10;
                int nb = (b - '0' + 7) % 10;
                int nc = (c - '0' + 7) % 10;
                int nd = (d - '0' + 7) % 10;
                // swap 1st with 3rd, 2nd with 4th
                cout << nc << nd << na << nb << "\n";
            } else {
                // decrypt: first undo the swap
                // currently at positions: pos0 came from orig 2, pos1 from 3, pos2 from 0, pos3 from 1
                // Thus orig_mod: [pos2, pos3, pos0, pos1]
                int mod0 = a - '0';
                int mod1 = b - '0';
                int mod2 = c - '0';
                int mod3 = d - '0';
                // Undo swap:
                int na = mod2;
                int nb = mod3;
                int nc = mod0;
                int nd = mod1;
                // (x + 7) % 10 = n  => x = (n + 3) % 10
                int orig_a = (na + 3) % 10;
                int orig_b = (nb + 3) % 10;
                int orig_c = (nc + 3) % 10;
                int orig_d = (nd + 3) % 10;
                cout << orig_a << orig_b << orig_c << orig_d << "\n";
            }
        }
    }
    return 0;
}

