using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double P0, r;
    if (!(cin >> P0 >> r)) return 0;

    double current_P = P0;
    int double_year = -1;

    for (int t = 1; t <= 75; ++t) {
        double next_P = current_P * (1.0 + r / 100.0);
        double increase = next_P - current_P;

        long long rounded_P = static_cast<long long>(round(next_P));
        long long rounded_inc = static_cast<long long>(round(increase));

        cout << t << " " << rounded_P << " " << rounded_inc << "\n";

        if (double_year == -1 && next_P >= 2.0 * P0) {
            double_year = t;
        }

        current_P = next_P;
    }

    cout << double_year << "\n";

    return 0;
}

