    long long init_pop;
    double rate;
    if (!(cin >> init_pop >> rate)) return 0;

    double p0 = static_cast<double>(init_pop);
    double factor = 1.0 + rate / 100.0;
    double cur = p0;
    int ans_year = -1;

    for (int year = 1; year <= 75; ++year) {
        double next_val = cur * factor;
        double diff = next_val - cur;

        long long disp_pop = llround(next_val);
        long long disp_inc = llround(diff);

        cout << year << ' ' << disp_pop << ' ' << disp_inc << '\n';

        if (ans_year == -1 && next_val >= 2.0 * p0) {
            ans_year = year;
        }
        cur = next_val;
    }

    cout << ans_year << '\n';
    return 0;
}

