#include <iostream>
#include <string>
#include <algorithm>

std::string toBase(int n, int base, bool uppercase = false) {
    if (n == 0) return "0";
    std::string s = "";
    while (n > 0) {
        int rem = n % base;
        if (rem < 10) s += char('0' + rem);
        else s += char((uppercase ? 'A' : 'a') + rem - 10);
        n /= base;
    }
    std::reverse(s.begin(), s.end());
    return s;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    if (std::cin >> n) {
        for (int i = 1; i <= n; ++i) {
            std::string bin = toBase(i, 2);
            std::string oct = toBase(i, 8);
            std::string hex = toBase(i, 16, true);
            std::cout << i << ' ' << bin << ' ' << oct << ' ' << hex << '\n';
        }
    }
    return 0;
}

