    while (base < target - 1e-11) {
        base *= rate;
        months++;
    }

    // Start: month 10, year 2012
    // 0 months: 10/2012
    // m months:
    int total_months = (2012 * 12 + (10 - 1)) + months;
    int year = total_months / 12;
    int month = (total_months % 12) + 1;

    std::cout << months << "\n";
    std::cout << std::setfill('0') << std::setw(2) << month << "/" << year << "\n";

    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    double r;
    if (!(std::cin >> r)) return 0;

    // P_m = P_0 * (1 + r/100)^m >= P_target
    // m = ceil( ln(2.5) / ln(1 + r/100) )
    double target_ratio = 2.5;
    double growth_factor = 1.0 + r / 100.0;
    int months = static_cast<int>(std::ceil(std::log(target_ratio) / std::log(growth_factor) - 1e-12));

    int start_year = 2012;
    int start_month = 10;

    int current_month = start_month + months;
    int year = start_year + (current_month - 1) / 12;
    int month = ((current_month - 1) % 12) + 1;

    std::cout << months << "\n";
    std::cout << std::setw(2) << std::setfill('0') << month << "/" << year << "\n";

    return 0;
}

