#include <iostream>

long long integerPower(long long base, int exponent) {
    if (exponent == 1) return base;
    long long half = integerPower(base, exponent / 2);
    if (exponent % 2 == 0) {
        return half * half;
    } else {
        return half * half * base;
    }
}

