using namespace std;

bool isPerfect(int n, vector<int>& divisors) {
    if (n <= 1) return false;
    divisors.clear();
    divisors.push_back(1);
    int sum = 1;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            sum += i;
            if (i * i != n) {
                divisors.push_back(n / i);
                sum += n / i;
            }
        }
    }
    if (sum == n) {
        sort(divisors.begin(), divisors.end());
        return true;
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (cin >> n) {
        vector<int> divs;
        for (int i = 1; i <= n; ++i) {
            if (isPerfect(i, divs)) {
                cout << i << " = ";
                for (size_t j = 0; j < divs.size(); ++j) {
                    cout << divs[j] << (j + 1 == divs.size() ? "" : " + ");
                }
                cout << "\n";
            }
        }
    }
    return 0;
}

