long long reverseDigits(long long n) {
    bool isNegative = false;
    if (n < 0) {
        isNegative = true;
        n = -n;
    }
    long long reversed = 0;
    while (n > 0) {
        reversed = reversed * 10 + (n % 10);
        n /= 10;
    }
    return isNegative ? -reversed : reversed;
}

