// Làm tròn số thực sang số nguyên gần nhất (half away from zero)
long long roundHalfAwayFromZero(double val) {
    if (val >= 0.0) {
        return static_cast<long long>(std::floor(val + 0.5));
    } else {
        return static_cast<long long>(std::ceil(val - 0.5));
    }
}

long long celsius(long long f) {
    double c = 5.0 * (f - 32) / 9.0;
    return roundHalfAwayFromZero(c);
}

long long fahrenheit(long long c) {
    double f = 9.0 * c / 5.0 + 32.0;
    return roundHalfAwayFromZero(f);
}

