// Chuyển đổi F sang C bằng số học nguyên có làm tròn chuẩn
// C = (5 * (F - 32)) / 9
long long f_to_c(long long f) {
    long long num = 5 * (f - 32);
    long long den = 9;
    if (num >= 0) {
        return (num + den / 2) / den;
    } else {
        return (num - den / 2) / den;
    }
}

// Chuyển đổi C sang F bằng số học nguyên có làm tròn chuẩn
// F = (9 * C) / 5 + 32
long long c_to_f(long long c) {
    long long num = 9 * c;
    long long den = 5;
    long long div_part;
    if (num >= 0) {
        div_part = (num + den / 2) / den;
    } else {
        div_part = (num - den / 2) / den;
    }
    return div_part + 32;
}

