long long factorial(int k, int depth) {
    for (int i = 0; i < depth; ++i) cout << ' ';
    cout << "-> factorial(" << k << ")\n";

    long long ans;
    if (k <= 1) {
        ans = 1;
    } else {
        long long sub = factorial(k - 1, depth + 1);
        ans = (long long)k * sub;
    }

    for (int i = 0; i < depth; ++i) cout << ' ';
    cout << "<- return " << ans << "\n";
    return ans;
}

