long long trace_factorial(int n, int level) {
    string indent(level, ' ');
    cout << indent << "-> factorial(" << n << ")" << "\n";

    long long ret = 1;
    if (n > 1) {
        ret = (long long)n * trace_factorial(n - 1, level + 1);
    }

    cout << indent << "<- return " << ret << "\n";
    return ret;
}

