            // Between src and aux
            if (peg[aux].empty() || (!peg[src].empty() && peg[src].back() < peg[aux].back())) {
                peg[aux].push_back(peg[src].back());
                peg[src].pop_back();
                cout << src << " -> " << aux << "\n";
            } else {
                peg[src].push_back(peg[aux].back());
