        for (int i = 0; i < numQueries; ++i) {
            char code;
            std::cin >> code;
            switch (code) {
                case 'i': {
                    long long x, y;
                    std::cin >> x >> y;
                    std::cout << maximum<long long>(x, y) << '\n';
                    break;
                }
                case 'c': {
                    char x, y;
                    std::cin >> x >> y;
                    std::cout << maximum<char>(x, y) << '\n';
                    break;
                }
                case 'd': {
                    double x, y;
                    std::cin >> x >> y;
                    std::cout << std::fixed << std::setprecision(2) << maximum<double>(x, y) << '\n';
                    break;
                }
            }
        }
    }
    return 0;
}

