#include <iomanip>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<long long> win_count(22, 0);
    vector<long long> lose_count(22, 0);
    long long total_rolls = 0;
    long long total_wins = 0;

    for (int game = 0; game < n; ++game) {
        string line;
        if (!getline(cin, line)) break;
        stringstream ss(line);
        int d1, d2;
        int roll_idx = 0;
        int point = 0;
        bool finished = false;
        bool won = false;

        while (ss >> d1 >> d2) {
            roll_idx++;
            int sum = d1 + d2;
            if (roll_idx == 1) {
                if (sum == 7 || sum == 11) {
                    won = true;
                    finished = true;
                } else if (sum == 2 || sum == 3 || sum == 12) {
                    won = false;
                    finished = true;
                } else {
                    point = sum;
                }
            } else {
                if (sum == point) {
                    won = true;
                    finished = true;
                } else if (sum == 7) {
                    won = false;
                    finished = true;
                }
            }
            if (finished) break;
        }

        total_rolls += roll_idx;
        int bucket = (roll_idx <= 20) ? roll_idx : 21;
        if (won) {
            win_count[bucket]++;
            total_wins++;
        } else {
            lose_count[bucket]++;
        }
    }

    for (int i = 1; i <= 20; ++i) {
        cout << "Luot " << i << ": Thang = " << win_count[i] << ", Thua = " << lose_count[i] << "\n";
    }
    cout << "Sau luot 20: Thang = " << win_count[21] << ", Thua = " << lose_count[21] << "\n";

    double win_percentage = (n > 0) ? (double)total_wins * 100.0 / n : 0.0;
    double avg_length = (n > 0) ? (double)total_rolls / n : 0.0;

    cout << fixed << setprecision(2);
    cout << "Tong thang: " << total_wins << " / " << n << " (" << win_percentage << "%)\n";
    cout << "Do dai trung binh: " << avg_length << " luot\n";

    return 0;
}

