int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    array<int, 22> wins{};
    array<int, 22> losses{};
    long long total_rolls = 0;
    int total_wins = 0;

    for (int g = 0; g < N; ++g) {
        int rolls_this_game = 0;
        int point = 0;
        bool game_won = false;

        while (true) {
            int d1, d2;
            cin >> d1 >> d2;
            rolls_this_game++;
            int s = d1 + d2;

            if (rolls_this_game == 1) {
                if (s == 7 || s == 11) {
                    game_won = true;
                    break;
                } else if (s == 2 || s == 3 || s == 12) {
                    game_won = false;
                    break;
                } else {
                    point = s;
                }
            } else {
                if (s == point) {
                    game_won = true;
                    break;
                } else if (s == 7) {
                    game_won = false;
                    break;
                }
            }
        }

        total_rolls += rolls_this_game;
        int cat = (rolls_this_game > 20) ? 21 : rolls_this_game;
        if (game_won) {
            wins[cat]++;
            total_wins++;
        } else {
            losses[cat]++;
        }
    }

    for (int i = 1; i <= 20; ++i) {
        cout << "Luot " << i << ": Thang = " << wins[i] << ", Thua = " << losses[i] << "\n";
    }
    cout << "Sau luot 20: Thang = " << wins[21] << ", Thua = " << losses[21] << "\n";

    double win_rate = 100.0 * total_wins / N;
    double avg_len = (double)total_rolls / N;

    cout.setf(ios::fixed);
    cout.precision(2);
    cout << "Tong thang: " << total_wins << " / " << N << " (" << win_rate << "%)\n";
    cout << "Do dai trung binh: " << avg_len << " luot\n";

    return 0;
}

