    cin.tie(NULL);

    vector<vector<int>> solutions;
    vector<int> p(8);
    iota(p.begin(), p.end(), 1);

    do {
        bool ok = true;
        for (int i = 0; i < 8 && ok; ++i) {
            for (int j = i + 1; j < 8; ++j) {
                if (abs(p[i] - p[j]) == abs(i - j)) {
                    ok = false;
                    break;
                }
            }
        }
        if (ok) {
            solutions.push_back(p);
        }
    } while (next_permutation(p.begin(), p.end()));

