                    cout << solutions[k - 1][i] << (i == 7 ? "" : " ");
                }
                cout << "\n";
            }
        }
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

vector<vector<int>> all_solutions;
int col[8];
bool used_col[9];
bool diag1[17]; // r - c + 8
bool diag2[17]; // r + c

void backtrack(int row) {
    if (row == 8) {
        vector<int> sol(8);
        for (int i = 0; i < 8; ++i) sol[i] = col[i];
        all_solutions.push_back(sol);
        return;
    }
    for (int c = 1; c <= 8; ++c) {
        if (!used_col[c] && !diag1[row - c + 8] && !diag2[row + c]) {
            used_col[c] = diag1[row - c + 8] = diag2[row + c] = true;
            col[row] = c;
            backtrack(row + 1);
            used_col[c] = diag1[row - c + 8] = diag2[row + c] = false;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    backtrack(0);

    int t;
    if (cin >> t) {
        while (t--) {
            int k;
            cin >> k;
            for (int i = 0; i < 8; ++i) {
                cout << all_solutions[k - 1][i] << (i == 7 ? "" : " ");
            }
            cout << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int dr[8] = {-1, -2, -2, -1, 1, 2, 2, 1};
const int dc[8] = {2, 1, -1, -2, -2, -1, 1, 2};

bool isValid(int r, int c, const vector<vector<int>>& board) {
    return (r >= 0 && r < 8 && c >= 0 && c < 8 && board[r][c] == 0);
}

int getAccessibility(int r, int c, const vector<vector<int>>& board) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (isValid(nr, nc, board)) {
            count++;
        }
    }
    return count;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int r0, c0;
    if (!(cin >> r0 >> c0)) return 0;

    vector<vector<int>> board(8, vector<int>(8, 0));
    int r = r0, c = c0;
    board[r][c] = 1;

    for (int step = 2; step <= 64; ++step) {
        int bestMove = -1;
        int minAccess = 999;
        for (int i = 0; i < 8; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc, board)) {
                int access = getAccessibility(nr, nc, board);
                if (access < minAccess) {
                    minAccess = access;
                    bestMove = i;
                }
            }
        }
        if (bestMove == -1) break;
        r += dr[bestMove];
        c += dc[bestMove];
        board[r][c] = step;
    }

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            cout << board[i][j] << (j == 7 ? "" : " ");
        }
        cout << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct Move {
    int dr;
    int dc;
};

const Move MOVES[8] = {
    {-1, 2},
    {-2, 1},
    {-2, -1},
    {-1, -2},
    {1, -2},
    {2, -1},
    {2, 1},
    {1, 2}
};

int main() {
    int startR, startC;
    if (scanf("%d %d", &startR, &startC) != 2) return 0;

    int grid[8][8];
    memset(grid, 0, sizeof(grid));

    int curR = startR, curC = startC;
    grid[curR][curC] = 1;

    for (int moveCount = 2; moveCount <= 64; ++moveCount) {
        int chosenMove = -1;
        int lowestDegree = 100;

        for (int k = 0; k < 8; ++k) {
            int nextR = curR + MOVES[k].dr;
            int nextC = curC + MOVES[k].dc;

            if (nextR >= 0 && nextR < 8 && nextC >= 0 && nextC < 8 && grid[nextR][nextC] == 0) {
                int degree = 0;
                for (int m = 0; m < 8; ++m) {
                    int nnR = nextR + MOVES[m].dr;
                    int nnC = nextC + MOVES[m].dc;
                    if (nnR >= 0 && nnR < 8 && nnC >= 0 && nnC < 8 && grid[nnR][nnC] == 0) {
                        degree++;
                    }
                }
                if (degree < lowestDegree) {
                    lowestDegree = degree;
                    chosenMove = k;
                }
            }
        }

        if (chosenMove == -1) {
            break;
        }
        curR += MOVES[chosenMove].dr;
        curC += MOVES[chosenMove].dc;
        grid[curR][curC] = moveCount;
    }

    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            printf("%d%c", grid[i][j], j == 7 ? '\n' : ' ');
        }
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

bool isUnderAttack(int r, int c, const vector<pair<int, int>>& queens) {
    for (const auto& q : queens) {
        if (q.first == r || q.second == c || abs(q.first - r) == abs(q.second - c)) {
            return true;
        }
    }
    return false;
}

int countEliminated(int r, int c, const vector<vector<bool>>& isAvail) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            if (isAvail[i][j]) {
                if (i == r || j == c || abs(i - r) == abs(j - c)) {
                    count++;
                }
            }
        }
    }
    return count;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int k;
    if (!(cin >> k)) return 0;

    vector<pair<int, int>> queens(k);
    for (int i = 0; i < k; ++i) {
        cin >> queens[i].first >> queens[i].second;
    }

    vector<vector<bool>> isAvail(8, vector<bool>(8, false));
    int totalAvail = 0;
    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            if (!isUnderAttack(r, c, queens)) {
                isAvail[r][c] = true;
                totalAvail++;
            }
        }
    }

    cout << totalAvail << "\n";

    if (totalAvail == 0) {
        cout << "-1 -1 -1\n";
        return 0;
    }

    int bestR = -1, bestC = -1, minElim = 1000;
    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            if (isAvail[r][c]) {
                int elim = countEliminated(r, c, isAvail);
                if (elim < minElim) {
                    minElim = elim;
                    bestR = r;
                    bestC = c;
                }
            }
        }
    }

    cout << bestR << " " << bestC << " " << minElim << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int k;
    if (!(cin >> k)) return 0;

    vector<pair<int, int>> placed(k);
    for (int i = 0; i < k; ++i) {
        cin >> placed[i].first >> placed[i].second;
    }

    auto attacks = [](int r1, int c1, int r2, int c2) {
        return r1 == r2 || c1 == c2 || (r1 - c1 == r2 - c2) || (r1 + c1 == r2 + c2);
    };

    vector<pair<int, int>> avail;
    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            bool ok = true;
            for (auto& q : placed) {
                if (attacks(r, c, q.first, q.second)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                avail.push_back({r, c});
            }
        }
    }

    cout << avail.size() << "\n";
    if (avail.empty()) {
        cout << "-1 -1 -1\n";
        return 0;
    }

    int best_r = -1, best_c = -1, min_elim = 1e9;
    for (auto& p1 : avail) {
        int r = p1.first, c = p1.second;
        int elim = 0;
        for (auto& p2 : avail) {
            if (attacks(r, c, p2.first, p2.second)) {
                elim++;
            }
        }
        if (elim < min_elim) {
            min_elim = elim;
            best_r = r;
            best_c = c;
        }
    }

    cout << best_r << " " << best_c << " " << min_elim << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int dr[8] = {-1, -2, -2, -1, 1, 2, 2, 1};
int dc[8] = {2, 1, -1, -2, -2, -1, 1, 2};

struct LCG {
    long long s, a, c, m;
    long long next() {
        s = (a * s + c) % m;
        return s;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int r0, c0;
    if (!(cin >> r0 >> c0)) return 0;

    LCG rng;
    cin >> rng.s >> rng.a >> rng.c >> rng.m;

    int T;
    cin >> T;

    vector<int> count_len(65, 0);
    int max_len = 0;

    for (int t = 0; t < T; ++t) {
        vector<vector<bool>> visited(8, vector<bool>(8, false));
        int curr_r = r0;
        int curr_c = c0;
        visited[curr_r][curr_c] = true;
        int tour_len = 1;

        while (tour_len < 64) {
            vector<int> valid_moves;
            for (int k = 0; k < 8; ++k) {
                int nr = curr_r + dr[k];
                int nc = curr_c + dc[k];
                if (nr >= 0 && nr < 8 && nc >= 0 && nc < 8 && !visited[nr][nc]) {
                    valid_moves.push_back(k);
                }
            }

            if (valid_moves.empty()) {
                break;
            }

            long long rand_val = rng.next();
            int chosen_move = valid_moves[rand_val % valid_moves.size()];

            curr_r += dr[chosen_move];
            curr_c += dc[chosen_move];
            visited[curr_r][curr_c] = true;
            tour_len++;
        }

        count_len[tour_len]++;
        if (tour_len > max_len) {
            max_len = tour_len;
        }
    }

    cout << max_len << "\n";
    for (int len = 1; len <= 64; ++len) {
        if (count_len[len] > 0) {
            cout << len << " " << count_len[len] << "\n";
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int DR[8] = {-1, -2, -2, -1, 1, 2, 2, 1};
const int DC[8] = {2, 1, -1, -2, -2, -1, 1, 2};

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);

    int startR, startC;
    if (!(cin >> startR >> startC)) return 0;

    long long state, A, C, M;
    cin >> state >> A >> C >> M;

    int totalTours;
    cin >> totalTours;

    auto getNextRand = [&]() -> long long {
        state = (A * state + C) % M;
        return state;
    };

    int freq[65] = {0};
    int best = 0;

    for (int tour = 0; tour < totalTours; ++tour) {
        bool seen[8][8] = {};
        int r = startR, c = startC;
        seen[r][c] = true;
        int steps = 1;

        while (steps < 64) {
            int available[8];
            int numAvail = 0;
            for (int i = 0; i < 8; ++i) {
                int nextR = r + DR[i];
                int nextC = c + DC[i];
                if (nextR >= 0 && nextR < 8 && nextC >= 0 && nextC < 8 && !seen[nextR][nextC]) {
                    available[numAvail++] = i;
                }
            }
            if (numAvail == 0) break;

            long long rnd = getNextRand();
            int pickedMove = available[rnd % numAvail];
            r += DR[pickedMove];
            c += DC[pickedMove];
            seen[r][c] = true;
            steps++;
        }

        freq[steps]++;
        if (steps > best) best = steps;
    }

    cout << best << "\n";
    for (int length = 1; length <= 64; ++length) {
        if (freq[length] > 0) {
            cout << length << " " << freq[length] << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <string>

using namespace std;

bool testPalindrome(const string &s, int left, int right) {
    if (left >= right) {
        return true;
    }
    if (s[left] != s[right]) {
        return false;
    }
    return testPalindrome(s, left + 1, right - 1);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (!(cin >> t)) return 0;
    string dummy;
    getline(cin, dummy);
    while (t--) {
        string s;
        if (!getline(cin, s)) break;
        if (testPalindrome(s, 0, (int)s.length() - 1)) {
            cout << "true\n";
        } else {
            cout << "false\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>

using namespace std;

bool testPalindromeHelper(const string &str, size_t start, size_t len) {
    if (len <= 1) {
        return true;
    }
    if (str[start] != str[start + len - 1]) {
        return false;
    }
    return testPalindromeHelper(str, start + 1, len - 2);
}

bool testPalindrome(const string &s) {
    return testPalindromeHelper(s, 0, s.size());
}

int main() {
    int n;
    if (cin >> n) {
        string line;
        getline(cin, line);
        for (int i = 0; i < n; ++i) {
            getline(cin, line);
            cout << (testPalindrome(line) ? "true" : "false") << "\n";
        }
    }
    return 0;
}

