#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

int n, k;
int fixed_pos[15];
bool col_used[15];
bool diag1[30]; // r + c
bool diag2[30]; // r - c + n
vector<int> current_sol;
vector<vector<int>> all_sols;

void solve(int r) {
    if (r > n) {
        all_sols.push_back(current_sol);
        return;
    }
    if (fixed_pos[r] != 0) {
        int c = fixed_pos[r];
        if (!col_used[c] && !diag1[r + c] && !diag2[r - c + n]) {
            col_used[c] = diag1[r + c] = diag2[r - c + n] = true;
            current_sol.push_back(c);
            solve(r + 1);
            current_sol.pop_back();
            col_used[c] = diag1[r + c] = diag2[r - c + n] = false;
        }
        return;
    }
    for (int c = 1; c <= n; ++c) {
        if (!col_used[c] && !diag1[r + c] && !diag2[r - c + n]) {
            col_used[c] = diag1[r + c] = diag2[r - c + n] = true;
            current_sol.push_back(c);
            solve(r + 1);
            current_sol.pop_back();
            col_used[c] = diag1[r + c] = diag2[r - c + n] = false;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    if (!(cin >> n >> k)) return 0;
    bool valid_initial = true;
    for (int i = 0; i < k; ++i) {
        int r, c;
        cin >> r >> c;
        if (fixed_pos[r] != 0 && fixed_pos[r] != c) valid_initial = false;
        fixed_pos[r] = c;
    }
    // Pre-check for conflicting initial fixed positions
    vector<pair<int, int>> initial_queens;
    for (int r = 1; r <= n; ++r) {
        if (fixed_pos[r] != 0) {
            initial_queens.push_back({r, fixed_pos[r]});
        }
    }
    for (size_t i = 0; i < initial_queens.size(); ++i) {
        for (size_t j = i + 1; j < initial_queens.size(); ++j) {
            int r1 = initial_queens[i].first, c1 = initial_queens[i].second;
            int r2 = initial_queens[j].first, c2 = initial_queens[j].second;
            if (c1 == c2 || abs(r1 - r2) == abs(c1 - c2)) {
                valid_initial = false;
            }
        }
    }

    if (valid_initial) {
        solve(1);
    }

    if (all_sols.empty()) {
        cout << 0 << "\n";
    } else {
        cout << all_sols.size() << "\n";
        for (const auto& sol : all_sols) {
            for (int i = 0; i < n; ++i) {
                cout << sol[i] << (i + 1 == n ? "" : " ");
            }
            cout << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Solver {
    int n;
    vector<int> fixed_cols;
    vector<vector<int>> results;
    vector<int> board;

    Solver(int n_val, const vector<int>& fixed) : n(n_val), fixed_cols(fixed) {
        board.resize(n + 1, 0);
    }

    bool is_safe(int row, int col) {
        for (int i = 1; i < row; ++i) {
            int other_col = board[i];
            if (other_col == col) return false;
            if (abs(row - i) == abs(col - other_col)) return false;
        }
        return true;
    }

    void backtrack(int row) {
        if (row > n) {
            vector<int> sol(board.begin() + 1, board.end());
            results.push_back(sol);
            return;
        }
        if (fixed_cols[row] != 0) {
            int col = fixed_cols[row];
            if (is_safe(row, col)) {
                board[row] = col;
                backtrack(row + 1);
                board[row] = 0;
            }
        } else {
            for (int col = 1; col <= n; ++col) {
                if (is_safe(row, col)) {
                    board[row] = col;
                    backtrack(row + 1);
                    board[row] = 0;
                }
            }
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> fixed_cols(n + 1, 0);
    bool conflict = false;
    for (int i = 0; i < k; ++i) {
        int r, c;
        cin >> r >> c;
        if (fixed_cols[r] != 0 && fixed_cols[r] != c) conflict = true;
        fixed_cols[r] = c;
    }
    if (conflict) {
        cout << 0 << "\n";
        return 0;
    }
    Solver solver(n, fixed_cols);
    solver.backtrack(1);
    if (solver.results.empty()) {
        cout << 0 << "\n";
    } else {
        cout << solver.results.size() << "\n";
        for (const auto& row : solver.results) {
            for (size_t i = 0; i < row.size(); ++i) {
                cout << row[i] << (i + 1 == row.size() ? "" : " ");
            }
            cout << "\n";
        }
    }
    return 0;
}

