// Chia đôi để tránh vượt quá giới hạn ngăn xếp (stack overflow) khi n lớn
long long recursiveMinimum(const vector<long long>& a, int start, int end) {
    if (start == end) {
        return a[start];
    }
    int mid = start + (end - start) / 2;
    long long minLeft = recursiveMinimum(a, start, mid);
    long long minRight = recursiveMinimum(a, mid + 1, end);
    return min(minLeft, minRight);
}

