long long recursiveMinimum(const vector<long long>& a, int start, int end) {
    if (start >= end) {
        return a[start];
    }
    int mid = start + (end - start) / 2;
    long long leftVal = recursiveMinimum(a, start, mid);
    long long rightVal = recursiveMinimum(a, mid + 1, end);
    return (leftVal < rightVal) ? leftVal : rightVal;
}

