    cin.tie(NULL);

    vector<pair<int, int>> pos(65, {-1, -1});
    bool valid_range = true;

    for (int r = 0; r < 8; ++r) {
        for (int c = 0; c < 8; ++c) {
            int val;
            if (!(cin >> val)) return 0;
            if (val >= 1 && val <= 64) {
                if (pos[val].first != -1) {
                    valid_range = false; // duplicate
                }
                pos[val] = {r, c};
            } else {
                valid_range = false;
            }
        }
    }

    if (!valid_range) {
        cout << "INVALID\n";
        return 0;
    }

    for (int k = 1; k <= 64; ++k) {
        if (pos[k].first == -1) {
            cout << "INVALID\n";
            return 0;
        }
    }

    for (int k = 1; k < 64; ++k) {
        if (!is_knight_move(pos[k].first, pos[k].second, pos[k + 1].first, pos[k + 1].second)) {
            cout << "INVALID\n";
            return 0;
        }
    }

    if (is_knight_move(pos[64].first, pos[64].second, pos[1].first, pos[1].second)) {
        cout << "CLOSED\n";
    } else {
        cout << "OPEN\n";
    }

    return 0;
}

