#include <iostream>
#include <vector>
#include <string>

using namespace std;

// Directions: 0: North, 1: East, 2: South, 3: West
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, 1, 0, -1};

int getInitialDir(int r, int c) {
    if (c == 0) return 1;      // East
    if (c == 11) return 3;     // West
    if (r == 0) return 2;      // South
    return 0;                  // North
}

bool isValid(int r, int c, const vector<string>& maze) {
    if (r < 0 || r >= 12 || c < 0 || c >= 12) return false;
    return maze[r][c] != '#';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int startR, startC;
    if (!(cin >> startR >> startC)) return 0;

    vector<string> maze(12);
    for (int i = 0; i < 12; ++i) {
        cin >> maze[i];
    }

    int dir = getInitialDir(startR, startC);
    int r = startR, c = startC;
    maze[r][c] = 'X';

    int steps = 0;
    while (steps < 100000) {
        // Try directions in order: right (dir+1)%4, forward dir, left (dir+3)%4, back (dir+2)%4
        int nextDir = -1;
        int prio[4] = {(dir + 1) % 4, dir, (dir + 3) % 4, (dir + 2) % 4};

        for (int i = 0; i < 4; ++i) {
            int d = prio[i];
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (isValid(nr, nc, maze)) {
                nextDir = d;
                break;
            }
        }

        if (nextDir == -1) break; // Trapped

        dir = nextDir;
        r += dr[dir];
        c += dc[dir];
        maze[r][c] = 'X';
        steps++;

        // Check termination
        if (r == startR && c == startC) {
            break; // Returned to start
        }
        if (r == 0 || r == 11 || c == 0 || c == 11) {
            break; // Reached an exit on boundary
        }
    }

    for (int i = 0; i < 12; ++i) {
        cout << maze[i] << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Walker {
    int r, c, dir;
    // dir: 0: Up, 1: Right, 2: Down, 3: Left
};

int main() {
    int start_r, start_c;
    if (scanf("%d %d", &start_r, &start_c) != 2) return 0;

    char grid[12][13];
    for (int i = 0; i < 12; ++i) {
        scanf("%s", grid[i]);
    }

    int d = 0;
    if (start_c == 0) d = 1;
    else if (start_c == 11) d = 3;
    else if (start_r == 0) d = 2;
    else if (start_r == 11) d = 0;

    Walker walker = {start_r, start_c, d};
    grid[walker.r][walker.c] = 'X';

    const int dr[] = {-1, 0, 1, 0};
    const int dc[] = {0, 1, 0, -1};

    for (int iter = 0; iter < 100000; ++iter) {
        int chosen_dir = -1;
        int check_dirs[4] = {
            (walker.dir + 1) % 4, // right
            walker.dir,           // ahead
            (walker.dir + 3) % 4, // left
            (walker.dir + 2) % 4  // back
        };

        for (int k = 0; k < 4; ++k) {
            int cd = check_dirs[k];
            int nr = walker.r + dr[cd];
            int nc = walker.c + dc[cd];
            if (nr >= 0 && nr < 12 && nc >= 0 && nc < 12 && grid[nr][nc] != '#') {
                chosen_dir = cd;
                break;
            }
        }

        if (chosen_dir == -1) break;

        walker.dir = chosen_dir;
        walker.r += dr[walker.dir];
        walker.c += dc[walker.dir];
        grid[walker.r][walker.c] = 'X';

        if (walker.r == start_r && walker.c == start_c) break;
        if (walker.r == 0 || walker.r == 11 || walker.c == 0 || walker.c == 11) break;
    }

    for (int i = 0; i < 12; ++i) {
        printf("%s\n", grid[i]);
    }

    return 0;
}

