void moveTortoise(int* pos, int i) {
    if (i >= 1 && i <= 5) {
        *pos += 3;
    } else if (i >= 6 && i <= 7) {
        *pos -= 6;
    } else if (i >= 8 && i <= 10) {
        *pos += 1;
    }
    if (*pos < 1) *pos = 1;
}

void moveHare(int* pos, int i) {
    if (i >= 1 && i <= 2) {
        *pos += 0;
    } else if (i >= 3 && i <= 4) {
        *pos += 9;
    } else if (i == 5) {
        *pos -= 12;
    } else if (i >= 6 && i <= 8) {
        *pos += 1;
    } else if (i >= 9 && i <= 10) {
        *pos -= 2;
    }
    if (*pos < 1) *pos = 1;
}

