static void updateTortoise(int &t, int roll) {
    if (roll <= 5) t += 3;
    else if (roll <= 7) t -= 6;
    else t += 1;
    if (t < 1) t = 1;
}

static void updateHare(int &h, int roll) {
    if (roll <= 2) {} // sleep
    else if (roll <= 4) h += 9;
    else if (roll == 5) h -= 12;
    else if (roll <= 8) h += 1;
    else h -= 2;
    if (h < 1) h = 1;
}

