class Complex {
private:
    double realPart;
    double imaginaryPart;

    static double cleanZero(double val) {
        if (std::abs(val) < 1e-9) return 0.0;
        return val;
    }

public:
    Complex(double r = 0.0, double i = 0.0) : realPart(r), imaginaryPart(i) {}

    Complex add(const Complex& right) const {
        return Complex(realPart + right.realPart, imaginaryPart + right.imaginaryPart);
    }

    Complex subtract(const Complex& right) const {
        return Complex(realPart - right.realPart, imaginaryPart - right.imaginaryPart);
    }

    void print() const {
        double r = cleanZero(realPart);
        double i = cleanZero(imaginaryPart);
        std::cout << "(" << std::fixed << std::setprecision(2) << r << ", " << i << ")\n";
    }
};

