#include <iostream>
#include <numeric>
#include <iomanip>

using namespace std;

class Rational {
private:
    long long numerator;
    long long denominator;

    void reduce() {
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        if (numerator == 0) {
            denominator = 1;
            return;
        }
        long long g = std::gcd(std::abs(numerator), std::abs(denominator));
        numerator /= g;
        denominator /= g;
    }

public:
    Rational(long long num = 0, long long den = 1) : numerator(num), denominator(den) {
        reduce();
    }

    Rational add(const Rational& other) const {
        return Rational(numerator * other.denominator + other.numerator * denominator,
                        denominator * other.denominator);
    }

    Rational subtract(const Rational& other) const {
        return Rational(numerator * other.denominator - other.numerator * denominator,
                        denominator * other.denominator);
    }

    Rational multiply(const Rational& other) const {
        return Rational(numerator * other.numerator, denominator * other.denominator);
    }

    Rational divide(const Rational& other) const {
        return Rational(numerator * other.denominator, denominator * other.numerator);
    }

    bool isZero() const {
        return numerator == 0;
    }

    void print() const {
        double val = static_cast<double>(numerator) / static_cast<double>(denominator);
        cout << numerator << "/" << denominator << " = "
             << fixed << setprecision(6) << val << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long a1, b1, a2, b2;
    if (!(cin >> a1 >> b1 >> a2 >> b2)) return 0;

    Rational r1(a1, b1);
    Rational r2(a2, b2);

    Rational resAdd = r1.add(r2);
    resAdd.print();

    Rational resSub = r1.subtract(r2);
    resSub.print();

    Rational resMul = r1.multiply(r2);
    resMul.print();

    if (r2.isZero()) {
        cout << "DIVISION BY ZERO\n";
    } else {
        Rational resDiv = r1.divide(r2);
        resDiv.print();
    }

    return 0;
}

#include <iostream>
#include <iomanip>

using namespace std;

long long computeGcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a < 0 ? -a : a;
}

struct Fraction {
    long long num, den;

    Fraction(long long n = 0, long long d = 1) {
        if (d < 0) {
            n = -n;
            d = -d;
        }
        if (n == 0) {
            num = 0;
            den = 1;
        } else {
            long long g = computeGcd(n < 0 ? -n : n, d);
            num = n / g;
            den = d / g;
        }
    }

    Fraction operator+(const Fraction& o) const {
        return Fraction(num * o.den + o.num * den, den * o.den);
    }

    Fraction operator-(const Fraction& o) const {
        return Fraction(num * o.den - o.num * den, den * o.den);
    }

    Fraction operator*(const Fraction& o) const {
        return Fraction(num * o.num, den * o.den);
    }

    Fraction operator/(const Fraction& o) const {
        return Fraction(num * o.den, den * o.num);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a1, b1, a2, b2;
    if (cin >> a1 >> b1 >> a2 >> b2) {
        Fraction f1(a1, b1);
        Fraction f2(a2, b2);

        Fraction add_res = f1 + f2;
        cout << add_res.num << "/" << add_res.den << " = "
             << fixed << setprecision(6) << (double)add_res.num / (double)add_res.den << "\n";

        Fraction sub_res = f1 - f2;
        cout << sub_res.num << "/" << sub_res.den << " = "
             << fixed << setprecision(6) << (double)sub_res.num / (double)sub_res.den << "\n";

        Fraction mul_res = f1 * f2;
        cout << mul_res.num << "/" << mul_res.den << " = "
             << fixed << setprecision(6) << (double)mul_res.num / (double)mul_res.den << "\n";

        if (f2.num == 0) {
            cout << "DIVISION BY ZERO\n";
        } else {
            Fraction div_res = f1 / f2;
            cout << div_res.num << "/" << div_res.den << " = "
                 << fixed << setprecision(6) << (double)div_res.num / (double)div_res.den << "\n";
        }
    }
    return 0;
}

