using namespace std;

bool isLeapYear(int y) {
    return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
}

int daysInMonth(int m, int y) {
    switch (m) {
        case 4: case 6: case 9: case 11: return 30;
        case 2: return isLeapYear(y) ? 29 : 28;
        default: return 31;
    }
}

class DateAndTime {
private:
    int year, month, day;
    int hour, minute, second;

    void nextDay() {
        day++;
        if (day > daysInMonth(month, year)) {
            day = 1;
            month++;
            if (month > 12) {
                month = 1;
                year++;
            }
        }
    }

public:
    DateAndTime(int y, int m, int d, int hr, int min, int sec)
        : year(y), month(m), day(d), hour(hr), minute(min), second(sec) {}

    void advanceSeconds(long long k) {
        long long totalSec = second + k;
        long long totalMin = minute + totalSec / 60;
        second = totalSec % 60;
        long long totalHr = hour + totalMin / 60;
        minute = totalMin % 60;
        long long addDays = totalHr / 24;
        hour = totalHr % 24;

        while (addDays > 0) {
            int dim = daysInMonth(month, year);
            int remainingInMonth = dim - day + 1;
            if (addDays >= remainingInMonth) {
                addDays -= remainingInMonth;
                day = 1;
                month++;
                if (month > 12) {
                    month = 1;
                    year++;
                }
            } else {
                day += addDays;
                addDays = 0;
            }
        }
    }

    void printUniversal() const {
        cout << setfill('0') << setw(4) << year << "-"
             << setw(2) << month << "-"
             << setw(2) << day << " "
             << setw(2) << hour << ":"
             << setw(2) << minute << ":"
             << setw(2) << second << "\n";
    }

    void printStandard() const {
        int stdHour = (hour == 0 || hour == 12) ? 12 : hour % 12;
        string period = (hour < 12) ? "AM" : "PM";
        cout << setfill('0') << setw(4) << year << "-"
             << setw(2) << month << "-"
             << setw(2) << day << " "
             << setw(2) << stdHour << ":"
             << setw(2) << minute << ":"
             << setw(2) << second << " " << period << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int y, m, d, h, min, s;
    if (cin >> y >> m >> d >> h >> min >> s) {
        long long k;
        cin >> k;
        DateAndTime dt(y, m, d, h, min, s);
        dt.advanceSeconds(k);
        dt.printUniversal();
        dt.printStandard();
    }
    return 0;
}

#include <cstdio>

struct DateAndTime {
    int Y, M, D;
    int h, m, s;

    static bool isLeap(int year) {
        return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
    }

    static int getDaysInMonth(int month, int year) {
        static const int days[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (month == 2 && isLeap(year)) return 29;
        return days[month];
    }

    void addDays(long long daysToAdd) {
        while (daysToAdd > 0) {
            int dInM = getDaysInMonth(M, Y);
            long long left = dInM - D;
            if (daysToAdd <= left) {
                D += daysToAdd;
                daysToAdd = 0;
            } else {
                daysToAdd -= (left + 1);
                D = 1;
                M++;
                if (M > 12) {
                    M = 1;
                    Y++;
                }
            }
        }
    }

    void addSeconds(long long k) {
        long long totalSec = s + k;
        s = totalSec % 60;
        long long totalMin = m + totalSec / 60;
        m = totalMin % 60;
        long long totalHours = h + totalMin / 60;
        h = totalHours % 24;
        long long days = totalHours / 24;
        addDays(days);
    }

    void printUniversal() const {
        std::printf("%04d-%02d-%02d %02d:%02d:%02d\n", Y, M, D, h, m, s);
    }

    void printStandard() const {
        int stdH = h % 12;
        if (stdH == 0) stdH = 12;
        const char* ampm = (h < 12) ? "AM" : "PM";
        std::printf("%04d-%02d-%02d %02d:%02d:%02d %s\n", Y, M, D, stdH, m, s, ampm);
    }
};

int main() {
    DateAndTime dt;
    long long k;
    if (std::scanf("%d %d %d %d %d %d", &dt.Y, &dt.M, &dt.D, &dt.h, &dt.m, &dt.s) == 6) {
        if (std::scanf("%lld", &k) == 1) {
            dt.addSeconds(k);
            dt.printUniversal();
            dt.printStandard();
        }
    }
    return 0;
}

