#include <iostream>
#include <vector>

using namespace std;

class TicTacToe {
private:
    int board[3][3];
    int current_player;
    int valid_moves_count;
    bool game_over;

    bool check_win(int player) const {
        for (int i = 0; i < 3; ++i) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;
        return false;
    }

public:
    TicTacToe() : current_player(1), valid_moves_count(0), game_over(false) {
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                board[i][j] = 0;
    }

    bool make_move(int r, int c) {
        if (game_over) return false;
        if (r < 0 || r >= 3 || c < 0 || c >= 3) return false;
        if (board[r][c] != 0) return false;

        board[r][c] = current_player;
        valid_moves_count++;

        if (check_win(current_player)) {
            cout << "Player " << current_player << " wins at move " << valid_moves_count << "\n";
            game_over = true;
            return true;
        }

        if (valid_moves_count == 9) {
            cout << "Draw at move 9\n";
            game_over = true;
            return true;
        }

        current_player = (current_player == 1) ? 2 : 1;
        return true;
    }

    bool is_over() const { return game_over; }
    int get_valid_moves() const { return valid_moves_count; }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    TicTacToe game;
    for (int i = 0; i < n; ++i) {
        int r, c;
        cin >> r >> c;
        if (!game.is_over()) {
            game.make_move(r, c);
        }
    }

    if (!game.is_over()) {
        cout << "In progress after " << game.get_valid_moves() << " moves\n";
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

struct Board {
    int grid[3][3] = {{0}};

    bool is_valid(int r, int c) const {
        return r >= 0 && r < 3 && c >= 0 && c < 3 && grid[r][c] == 0;
    }

    bool has_won(int p) const {
        // check rows & cols
        for (int i = 0; i < 3; ++i) {
            if (grid[i][0] == p && grid[i][1] == p && grid[i][2] == p) return true;
            if (grid[0][i] == p && grid[1][i] == p && grid[2][i] == p) return true;
        }
        // diagonals
        if (grid[0][0] == p && grid[1][1] == p && grid[2][2] == p) return true;
        if (grid[0][2] == p && grid[1][1] == p && grid[2][0] == p) return true;
        return false;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    Board b;
    int turn = 1;
    int valid_steps = 0;
    bool finished = false;

    for (int i = 0; i < n; ++i) {
        int r, c;
        cin >> r >> c;
        if (finished) continue;

        if (!b.is_valid(r, c)) {
            continue;
        }

        b.grid[r][c] = turn;
        valid_steps++;

        if (b.has_won(turn)) {
            cout << "Player " << turn << " wins at move " << valid_steps << "\n";
            finished = true;
        } else if (valid_steps == 9) {
            cout << "Draw at move 9\n";
            finished = true;
        } else {
            turn = 3 - turn; // toggle 1 <-> 2
        }
    }

    if (!finished) {
        cout << "In progress after " << valid_steps << " moves\n";
    }

    return 0;
}

