        double d12 = distSq(p1, p2);
        double d23 = distSq(p2, p3);
        double d30 = distSq(p3, p0);
        double d02 = distSq(p0, p2);
        double d13 = distSq(p1, p3);

        if (d01 > 1e-9 && d12 > 1e-9) {
            if (abs(d01 - d23) < 1e-7 && abs(d12 - d30) < 1e-7 && abs(d02 - d13) < 1e-7) {
                if (abs(d01 + d12 - d02) < 1e-7) {
                    double s1 = sqrt(d01);
                    double s2 = sqrt(d12);
                    len = max(s1, s2);
                    wid = min(s1, s2);
                    found = true;
                    break;
                }
            }
        }
    } while (next_permutation(p, p + 4));

    if (!found) {
        cout << "INVALID\n";
    } else {
        double perimeter = 2 * (len + wid);
        double area = len * wid;
        cout << fixed << setprecision(2);
        cout << len << "\n";
        cout << wid << "\n";
        cout << perimeter << "\n";
        cout << area << "\n";
        if (abs(len - wid) < 1e-6) {
            cout << "SQUARE\n";
        } else {
            cout << "NOT SQUARE\n";
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
#include <algorithm>

using namespace std;

struct Point {
    double x, y;
};

int main() {
    Point p[4];
    for (int i = 0; i < 4; ++i) {
        cin >> p[i].x >> p[i].y;
        if (p[i].x < 0.0 || p[i].x > 20.0 || p[i].y < 0.0 || p[i].y > 20.0) {
            cout << "INVALID\n";
            return 0;
        }
    }

    // Pairwise squared distances: 6 pairs
    vector<double> d;
    for (int i = 0; i < 4; ++i) {
        for (int j = i + 1; j < 4; ++j) {
            double dx = p[i].x - p[j].x;
            double dy = p[i].y - p[j].y;
            d.push_back(dx * dx + dy * dy);
        }
    }
    sort(d.begin(), d.end());

    // For a non-degenerate rectangle, the 6 distances must be:
    // d[0] == d[1] (side a^2 > 0)
    // d[2] == d[3] (side b^2 > 0)
    // d[4] == d[5] (diagonal^2 == a^2 + b^2)
    if (d[0] < 1e-9 || abs(d[0] - d[1]) > 1e-7 || abs(d[2] - d[3]) > 1e-7 || abs(d[4] - d[5]) > 1e-7 || abs(d[0] + d[2] - d[4]) > 1e-7) {
        cout << "INVALID\n";
        return 0;
    }

    // Check center symmetry to ensure it's not some self-intersecting kite
    // Sum of all points / 4 is center. Opposite points must sum to 2*center.
    Point center = {0, 0};
    for (int i = 0; i < 4; ++i) {
        center.x += p[i].x / 4.0;
        center.y += p[i].y / 4.0;
    }
    bool symmetric = true;
    for (int i = 0; i < 4; ++i) {
        bool hasOpp = false;
        for (int j = 0; j < 4; ++j) {
            if (i != j && abs((p[i].x + p[j].x) / 2.0 - center.x) < 1e-7 && abs((p[i].y + p[j].y) / 2.0 - center.y) < 1e-7) {
                hasOpp = true;
                break;
            }
        }
        if (!hasOpp) symmetric = false;
    }

    if (!symmetric) {
        cout << "INVALID\n";
        return 0;
    }

    double s1 = sqrt(d[0]);
    double s2 = sqrt(d[2]);
    double len = max(s1, s2);
    double wid = min(s1, s2);
    double peri = 2.0 * (len + wid);
    double area = len * wid;

    cout << fixed << setprecision(2);
    cout << len << "\n";
    cout << wid << "\n";
    cout << peri << "\n";
    cout << area << "\n";
    if (abs(len - wid) < 1e-6) {
        cout << "SQUARE\n";
    } else {
        cout << "NOT SQUARE\n";
    }
    return 0;
}

