        if (m >= 0 && m < 60) {
            minute = m;
            return true;
        }
        return false;
    }

    bool setSecond(int s) {
        if (s >= 0 && s < 60) {
            second = s;
            return true;
        }
        return false;
    }

    bool setTime(int h, int m, int s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            hour = h;
            minute = m;
            second = s;
            return true;
        }
        return false;
    }

    void printUniversal() const {
        cout << setfill('0') << setw(2) << hour << ":"
             << setw(2) << minute << ":"
             << setw(2) << second << "\n";
    }
};

