using namespace std;

bool isLeap(int y) {
    return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
}

const vector<string> MONTH_NAMES = {
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
};

int getDaysInMonth(int m, int y) {
    static const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (m == 2 && isLeap(y)) return 29;
    return days[m - 1];
}

int monthNameToIndex(const string& name) {
    for (int i = 0; i < 12; ++i) {
        if (MONTH_NAMES[i] == name) return i + 1;
    }
    return 1;
}

struct Date {
    int day;
    int month;
    int year;

    Date(int d, int m, int y) : day(d), month(m), year(y) {}

    static Date fromDDD(int ddd, int y) {
        int m = 1;
        while (m <= 12) {
            int dim = getDaysInMonth(m, y);
            if (ddd <= dim) break;
            ddd -= dim;
            m++;
        }
        return Date(ddd, m, y);
    }

    int toDDD() const {
        int ddd = day;
        for (int m = 1; m < month; ++m) {
            ddd += getDaysInMonth(m, year);
        }
        return ddd;
    }

    void printFormats() const {
        // Format 1: DDD YYYY
        cout << toDDD() << " " << year << "\n";
        // Format 2: MM/DD/YY
        cout << setfill('0') << setw(2) << month << "/"
             << setw(2) << day << "/"
             << setw(2) << (year % 100) << "\n";
        // Format 3: Month D, YYYY
        cout << MONTH_NAMES[month - 1] << " " << day << ", " << year << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int type;
        cin >> type;
        if (type == 1) {
            int ddd, y;
            cin >> ddd >> y;
            Date d = Date::fromDDD(ddd, y);
            d.printFormats();
        } else if (type == 2) {
            string s;
            cin >> s;
            int m = stoi(s.substr(0, 2));
            int d = stoi(s.substr(3, 2));
            int y = stoi(s.substr(6, 4));
            Date dt(d, m, y);
            dt.printFormats();
        } else if (type == 3) {
            string mName, dStr;
            int y;
            cin >> mName >> dStr >> y;
            if (!dStr.empty() && dStr.back() == ',') {
                dStr.pop_back();
            }
            int d = stoi(dStr);
            int m = monthNameToIndex(mName);
            Date dt(d, m, y);
            dt.printFormats();
        }
    }
    return 0;
}

#include <cstdio>
#include <iostream>
#include <string>
#include <vector>
#include <map>

using namespace std;

static const int mdays[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
static const char* mnames[] = {
    "", "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
};

bool leapYear(int y) {
    return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);
}

int daysInMonth(int m, int y) {
    if (m == 2 && leapYear(y)) return 29;
    return mdays[m];
}

void solveQuery(int day, int month, int year) {
    int ddd = day;
    for (int m = 1; m < month; ++m) {
        ddd += daysInMonth(m, year);
    }
    printf("%d %d\n", ddd, year);
    printf("%02d/%02d/%02d\n", month, day, year % 100);
    printf("%s %d, %d\n", mnames[month], day, year);
}

int main() {
    map<string, int> nameToMonth;
    for (int i = 1; i <= 12; ++i) {
        nameToMonth[mnames[i]] = i;
    }

    int T;
    if (scanf("%d", &T) != 1) return 0;
    while (T--) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            int ddd, y;
            scanf("%d %d", &ddd, &y);
            int m = 1;
            while (ddd > daysInMonth(m, y)) {
                ddd -= daysInMonth(m, y);
                m++;
            }
            solveQuery(ddd, m, y);
        } else if (type == 2) {
            int m, d, y;
            scanf("%d/%d/%d", &m, &d, &y);
            solveQuery(d, m, y);
        } else {
            char sMonth[32];
            int d, y;
            scanf("%s %d, %d", sMonth, &d, &y);
            int m = nameToMonth[string(sMonth)];
            solveQuery(d, m, y);
        }
    }
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
#include <array>

class HugeInteger {
private:
    // Lưu 40 chữ số theo thứ tự: digits[0] là hàng đơn vị, digits[39] là hàng cao nhất
    std::array<int, 40> digits;

public:
    HugeInteger() {
        digits.fill(0);
    }

    void input(const std::string& s) {
        digits.fill(0);
        int len = s.length();
        for (int i = 0; i < len && i < 40; ++i) {
            digits[i] = s[len - 1 - i] - '0';
        }
    }

    void output() const {
        int high = 39;
        while (high > 0 && digits[high] == 0) {
            --high;
        }
        for (int i = high; i >= 0; --i) {
            std::cout << digits[i];
        }
        std::cout << "\n";
    }

    bool isZero() const {
        for (int i = 0; i < 40; ++i) {
            if (digits[i] != 0) return false;
        }
        return true;
    }

    bool isEqualTo(const HugeInteger& other) const {
        for (int i = 0; i < 40; ++i) {
            if (digits[i] != other.digits[i]) return false;
        }
        return true;
    }

    bool isNotEqualTo(const HugeInteger& other) const {
        return !isEqualTo(other);
    }

    bool isGreaterThan(const HugeInteger& other) const {
        for (int i = 39; i >= 0; --i) {
            if (digits[i] > other.digits[i]) return true;
            if (digits[i] < other.digits[i]) return false;
        }
        return false;
    }

    bool isLessThan(const HugeInteger& other) const {
        for (int i = 39; i >= 0; --i) {
            if (digits[i] < other.digits[i]) return true;
            if (digits[i] > other.digits[i]) return false;
        }
        return false;
    }

    bool isGreaterThanOrEqualTo(const HugeInteger& other) const {
        return !isLessThan(other);
    }

    bool isLessThanOrEqualTo(const HugeInteger& other) const {
        return !isGreaterThan(other);
    }

    HugeInteger add(const HugeInteger& other) const {
        HugeInteger res;
        int carry = 0;
        for (int i = 0; i < 40; ++i) {
            int sum = digits[i] + other.digits[i] + carry;
            res.digits[i] = sum % 10;
            carry = sum / 10;
        }
        return res;
    }

    HugeInteger subtract(const HugeInteger& other) const {
        HugeInteger res;
        int borrow = 0;
        for (int i = 0; i < 40; ++i) {
            int diff = digits[i] - other.digits[i] - borrow;
            if (diff < 0) {
                diff += 10;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.digits[i] = diff;
        }
        return res;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::string s1, s2;
    if (!(std::cin >> s1 >> s2)) return 0;

    HugeInteger a, b;
    a.input(s1);
    b.input(s2);

    std::cout << (a.isZero() ? "true" : "false") << "\n";
    std::cout << (b.isZero() ? "true" : "false") << "\n";

    std::cout << (a.isEqualTo(b) ? "true" : "false") << " "
              << (a.isNotEqualTo(b) ? "true" : "false") << " "
              << (a.isGreaterThan(b) ? "true" : "false") << " "
              << (a.isLessThan(b) ? "true" : "false") << " "
              << (a.isGreaterThanOrEqualTo(b) ? "true" : "false") << " "
              << (a.isLessThanOrEqualTo(b) ? "true" : "false") << "\n";

    HugeInteger sum = a.add(b);
    sum.output();

    HugeInteger diff = a.subtract(b);
    diff.output();

    return 0;
}

#include <iostream>
