    int instructionRegister = 0;
    int operationCode = 0;
    int operand = 0;

    bool fatal = false;
    string errorDesc = "";

    while (instructionCounter >= 0 && instructionCounter < 100) {
        instructionRegister = memory[instructionCounter];
        if (instructionRegister < 0) {
            fatal = true;
            errorDesc = "*** Invalid operation code ***";
            operationCode = abs(instructionRegister) / 100;
            operand = abs(instructionRegister) % 100;
            break;
        }

        operationCode = instructionRegister / 100;
        operand = instructionRegister % 100;

        if (operand < 0 || operand >= 100) {
            fatal = true;
            errorDesc = "*** Invalid operation code ***";
            break;
        }

        if (operationCode == 43) { // HALT
            break;
        }

        int nextInstruction = instructionCounter + 1;

        switch (operationCode) {
            case 10: // READ
                cin >> memory[operand];
                break;
            case 11: // WRITE
                cout << memory[operand] << "\n";
                break;
            case 20: // LOAD
                accumulator = memory[operand];
                break;
            case 21: // STORE
                memory[operand] = accumulator;
                break;
            case 30: // ADD
                accumulator += memory[operand];
                if (accumulator > 9999 || accumulator < -9999) {
                    fatal = true;
                    errorDesc = "*** Accumulator overflow ***";
                }
                break;
            case 31: // SUBTRACT
                accumulator -= memory[operand];
                if (accumulator > 9999 || accumulator < -9999) {
                    fatal = true;
                    errorDesc = "*** Accumulator overflow ***";
                }
                break;
            case 32: // DIVIDE
                if (memory[operand] == 0) {
                    fatal = true;
                    errorDesc = "*** Attempt to divide by zero ***";
                } else {
                    accumulator /= memory[operand];
                }
                break;
            case 33: // MULTIPLY
                accumulator *= memory[operand];
                if (accumulator > 9999 || accumulator < -9999) {
                    fatal = true;
                    errorDesc = "*** Accumulator overflow ***";
                }
                break;
            case 40: // BRANCH
                nextInstruction = operand;
                break;
            case 41: // BRANCHNEG
                if (accumulator < 0) nextInstruction = operand;
                break;
            case 42: // BRANCHZERO
                if (accumulator == 0) nextInstruction = operand;
                break;
            default:
                fatal = true;
                errorDesc = "*** Invalid operation code ***";
                break;
        }

        if (fatal) break;
        instructionCounter = nextInstruction;
