class Card {
private:
    int face;
    int suit;
    static const std::string faces[13];
    static const std::string suits[4];
public:
    Card(int f = 0, int s = 0) : face(f), suit(s) {}
    std::string toString() const {
        return faces[face] + " of " + suits[suit];
    }
};

const std::string Card::faces[13] = {
    "Ace", "Deuce", "Three", "Four", "Five", "Six", "Seven", 
    "Eight", "Nine", "Ten", "Jack", "Queen", "King"
};

const std::string Card::suits[4] = {
    "Hearts", "Diamonds", "Clubs", "Spades"
};

class DeckOfCards {
private:
    std::vector<Card> deck;
    int currentCard;
public:
    DeckOfCards() : currentCard(0) {
        deck.reserve(52);
        for (int i = 0; i < 52; ++i) {
            deck.emplace_back(i % 13, i / 13);
        }
    }

    void shuffle(const std::vector<int>& swapIndices) {
        for (int i = 0; i < 52; ++i) {
            int j = swapIndices[i];
            Card temp = deck[i];
            deck[i] = deck[j];
            deck[j] = temp;
        }
    }

    Card dealCard() {
        return deck[currentCard++];
    }

    bool moreCards() const {
        return currentCard < 52;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    std::vector<int> p(52);
    for (int i = 0; i < 52; ++i) {
        std::cin >> p[i];
    }

    DeckOfCards deck;
    deck.shuffle(p);

    while (deck.moreCards()) {
        std::cout << deck.dealCard().toString() << "\n";
    }

    return 0;
}

