#include <iostream>
#include <iomanip>
#include <string>

using namespace std;

class Time {
private:
    int totalSeconds;

public:
    Time(int h = 0, int m = 0, int s = 0) {
        setTime(h, m, s);
    }

    void setTime(int h, int m, int s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            totalSeconds = h * 3600 + m * 60 + s;
        } else {
            totalSeconds = 0;
        }
    }

    void addSeconds(long long k) {
        long long s = (totalSeconds + k) % 86400;
        if (s < 0) s += 86400;
        totalSeconds = static_cast<int>(s);
    }

    int getHour() const { return totalSeconds / 3600; }
    int getMinute() const { return (totalSeconds % 3600) / 60; }
    int getSecond() const { return totalSeconds % 60; }

    void print() const {
        int h = getHour();
        int m = getMinute();
        int s = getSecond();

        // Universal time: HH:MM:SS
        cout << setfill('0') << setw(2) << h << ":"
             << setw(2) << m << ":"
             << setw(2) << s << " | ";

        // Standard time: h:MM:SS AM/PM
        int stdH = (h == 0 || h == 12) ? 12 : h % 12;
        string period = (h < 12) ? "AM" : "PM";
        cout << stdH << ":"
             << setfill('0') << setw(2) << m << ":"
             << setw(2) << s << " " << period << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (!(cin >> t)) return 0;

    Time timeObj;
    while (t--) {
        string cmd;
        cin >> cmd;
        if (cmd == "SET") {
            long long h, m, s;
            cin >> h >> m >> s;
            if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
                timeObj.setTime((int)h, (int)m, (int)s);
            } else {
                timeObj.setTime(99, 99, 99); // triggers default 00:00:00
            }
        } else if (cmd == "ADD") {
            long long k;
            cin >> k;
            timeObj.addSeconds(k);
        }
        timeObj.print();
    }
    return 0;
}

#include <cstdio>
#include <string>
#include <iostream>

using namespace std;

struct ClockTime {
    int secFromMidnight;

    ClockTime() : secFromMidnight(0) {}

    void reset(long long h, long long m, long long s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            secFromMidnight = (int)(h * 3600 + m * 60 + s);
        } else {
            secFromMidnight = 0;
        }
    }

    void advance(long long delta) {
        long long cur = secFromMidnight + delta;
        cur %= 86400;
        if (cur < 0) cur += 86400;
        secFromMidnight = (int)cur;
    }

    void display() const {
        int h = secFromMidnight / 3600;
        int rem = secFromMidnight % 3600;
        int m = rem / 60;
        int s = rem % 60;

        int standardH = h % 12;
        if (standardH == 0) standardH = 12;
        const char* ampm = (h < 12) ? "AM" : "PM";

        printf("%02d:%02d:%02d | %d:%02d:%02d %s\n", h, m, s, standardH, m, s, ampm);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (!(cin >> T)) return 0;
    ClockTime ct;
    for (int i = 0; i < T; ++i) {
        string op;
        cin >> op;
        if (op == "SET") {
            long long h, m, s;
            cin >> h >> m >> s;
            ct.reset(h, m, s);
        } else if (op == "ADD") {
            long long k;
            cin >> k;
            ct.advance(k);
        }
        ct.display();
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

class IntegerSet {
private:
    std::vector<bool> a;

public:
    IntegerSet() : a(101, false) {}

    IntegerSet(const std::vector<int>& arr) : a(101, false) {
        for (int x : arr) {
            if (x >= 0 && x <= 100) {
                a[x] = true;
            }
        }
    }

    IntegerSet unionOfSets(const IntegerSet& other) const {
        IntegerSet result;
        for (int i = 0; i <= 100; ++i) {
            result.a[i] = this->a[i] || other.a[i];
        }
        return result;
    }

    IntegerSet intersectionOfSets(const IntegerSet& other) const {
        IntegerSet result;
        for (int i = 0; i <= 100; ++i) {
            result.a[i] = this->a[i] && other.a[i];
        }
        return result;
    }

    void insertElement(int k) {
        if (k >= 0 && k <= 100) {
            a[k] = true;
        }
    }

    void deleteElement(int m) {
        if (m >= 0 && m <= 100) {
            a[m] = false;
        }
    }

    bool isEqualTo(const IntegerSet& other) const {
        for (int i = 0; i <= 100; ++i) {
            if (this->a[i] != other.a[i]) return false;
        }
        return true;
    }

    void printSet() const {
        bool first = true;
        for (int i = 0; i <= 100; ++i) {
            if (a[i]) {
                if (!first) std::cout << " ";
                std::cout << i;
                first = false;
            }
        }
        if (first) {
            std::cout << "---";
        }
        std::cout << "\n";
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int nA;
    if (!(std::cin >> nA)) return 0;
    std::vector<int> initA(nA);
    for (int i = 0; i < nA; ++i) {
        std::cin >> initA[i];
    }

    int nB;
    std::cin >> nB;
    std::vector<int> initB(nB);
    for (int i = 0; i < nB; ++i) {
        std::cin >> initB[i];
    }

    IntegerSet setA(initA);
    IntegerSet setB(initB);

    int q;
    std::cin >> q;
    while (q--) {
        std::string op, target;
        int val;
        std::cin >> op >> target >> val;
        if (target == "A") {
            if (op == "INSERT") setA.insertElement(val);
            else if (op == "DELETE") setA.deleteElement(val);
        } else if (target == "B") {
            if (op == "INSERT") setB.insertElement(val);
            else if (op == "DELETE") setB.deleteElement(val);
        }
    }

    setA.printSet();
    setB.printSet();
    IntegerSet unionSet = setA.unionOfSets(setB);
    unionSet.printSet();
    IntegerSet interSet = setA.intersectionOfSets(setB);
    interSet.printSet();
    std::cout << (setA.isEqualTo(setB) ? "true" : "false") << "\n";

    return 0;
}

