#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

struct Card {
    int val;
    int suit;
};

bool hasPair(const vector<Card>& hand) {
    map<int, int> cnt;
    for (const auto& c : hand) cnt[c.val]++;
    for (const auto& p : cnt) {
        if (p.second >= 2) return true;
    }
    return false;
}

bool hasTwoPairs(const vector<Card>& hand) {
    map<int, int> cnt;
    for (const auto& c : hand) cnt[c.val]++;
    int pairCount = 0;
    for (const auto& p : cnt) {
        if (p.second >= 2) pairCount++;
    }
    return pairCount >= 2;
}

bool hasThreeOfAKind(const vector<Card>& hand) {
    map<int, int> cnt;
    for (const auto& c : hand) cnt[c.val]++;
    for (const auto& p : cnt) {
        if (p.second >= 3) return true;
    }
    return false;
}

bool hasFourOfAKind(const vector<Card>& hand) {
    map<int, int> cnt;
    for (const auto& c : hand) cnt[c.val]++;
    for (const auto& p : cnt) {
        if (p.second >= 4) return true;
    }
    return false;
}

bool hasFlush(const vector<Card>& hand) {
    int s = hand[0].suit;
    for (int i = 1; i < 5; ++i) {
        if (hand[i].suit != s) return false;
    }
    return true;
}

bool hasStraight(const vector<Card>& hand) {
    vector<int> vals;
    for (const auto& c : hand) vals.push_back(c.val);
    sort(vals.begin(), vals.end());
    // Check distinct
    for (int i = 0; i < 4; ++i) {
        if (vals[i] == vals[i+1]) return false;
    }
    // Standard straight
    if (vals[4] - vals[0] == 4) return true;
    // Ace-high straight: 1, 10, 11, 12, 13
    if (vals[0] == 1 && vals[1] == 10 && vals[2] == 11 && vals[3] == 12 && vals[4] == 13) return true;
    return false;
}

void solve() {
    vector<Card> hand(5);
    for (int i = 0; i < 5; ++i) {
        cin >> hand[i].val >> hand[i].suit;
    }
    cout << (hasPair(hand) ? "YES" : "NO") << " "
         << (hasTwoPairs(hand) ? "YES" : "NO") << " "
         << (hasThreeOfAKind(hand) ? "YES" : "NO") << " "
         << (hasFourOfAKind(hand) ? "YES" : "NO") << " "
         << (hasFlush(hand) ? "YES" : "NO") << " "
         << (hasStraight(hand) ? "YES" : "NO") << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (cin >> T) {
        while (T--) {
            solve();
        }
    }
    return 0;
}

