        int freq[14] = {0};
        int suit_freq[5] = {0};
        for (int i = 0; i < 5; ++i) {
            cin >> v[i] >> s[i];
            freq[v[i]]++;
            suit_freq[s[i]]++;
        }

        bool pair = false, two_pairs = false, three = false, four = false, flush = false, straight = false;
        int p_cnt = 0;
        for (int i = 1; i <= 13; ++i) {
            if (freq[i] >= 2) {
                pair = true;
                p_cnt++;
            }
            if (freq[i] >= 3) three = true;
            if (freq[i] >= 4) four = true;
        }
        if (p_cnt >= 2) two_pairs = true;

        for (int i = 1; i <= 4; ++i) {
            if (suit_freq[i] == 5) flush = true;
        }

        vector<int> sorted_v(v, v + 5);
        sort(sorted_v.begin(), sorted_v.end());
        bool all_unique = true;
        for (int i = 0; i < 4; ++i) {
            if (sorted_v[i] == sorted_v[i+1]) all_unique = false;
        }

        if (all_unique) {
            if (sorted_v[4] - sorted_v[0] == 4) straight = true;
            if (sorted_v[0] == 1 && sorted_v[1] == 10 && sorted_v[2] == 11 && sorted_v[3] == 12 && sorted_v[4] == 13) {
                straight = true;
            }
        }

        cout << (pair ? "YES" : "NO") << " "
             << (two_pairs ? "YES" : "NO") << " "
             << (three ? "YES" : "NO") << " "
             << (four ? "YES" : "NO") << " "
             << (flush ? "YES" : "NO") << " "
             << (straight ? "YES" : "NO") << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <iomanip>

using namespace std;

class Time {
private:
    int totalSeconds;

public:
    Time() : totalSeconds(0) {}

    bool setTime(long long h, long long m, long long s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            totalSeconds = static_cast<int>(h * 3600 + m * 60 + s);
            return true;
        }
        return false;
    }

    void addSeconds(long long k) {
        totalSeconds = static_cast<int>((totalSeconds + k % 86400) % 86400);
    }

    int getSecondsSinceMidnight() const {
        return totalSeconds;
    }

    void printUniversal() const {
        int h = totalSeconds / 3600;
        int m = (totalSeconds % 3600) / 60;
        int s = totalSeconds % 60;
        cout << setfill('0') << setw(2) << h << ":"
             << setw(2) << m << ":"
             << setw(2) << s << "\n";
    }

    void printStandard() const {
        int h = totalSeconds / 3600;
        int m = (totalSeconds % 3600) / 60;
        int s = totalSeconds % 60;
        int displayHour = (h == 0 || h == 12) ? 12 : h % 12;
        string period = (h < 12) ? "AM" : "PM";
        cout << displayHour << ":"
             << setfill('0') << setw(2) << m << ":"
             << setw(2) << s << " " << period << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int q;
    if (!(cin >> q)) return 0;

    Time t;
    while (q--) {
        string cmd;
        cin >> cmd;
        if (cmd == "SET") {
            long long h, m, s;
            cin >> h >> m >> s;
            if (!t.setTime(h, m, s)) {
                cout << "INVALID\n";
            }
        } else if (cmd == "ADD_SECONDS") {
            long long k;
            cin >> k;
            t.addSeconds(k);
        } else if (cmd == "PRINT_UNIVERSAL") {
            t.printUniversal();
        } else if (cmd == "PRINT_STANDARD") {
            t.printStandard();
        } else if (cmd == "GET_SECONDS") {
            cout << t.getSecondsSinceMidnight() << "\n";
        }
    }
    return 0;
}

#include <cstdio>
#include <string>
#include <iostream>

using namespace std;

class TimeRepresentation {
    int secFromMidnight;
public:
    TimeRepresentation() : secFromMidnight(0) {}

    bool update(long long h, long long m, long long s) {
        if (h < 0 || h >= 24 || m < 0 || m >= 60 || s < 0 || s >= 60) {
            return false;
        }
        secFromMidnight = (int)(h * 3600 + m * 60 + s);
        return true;
    }

    void advance(long long s) {
        long long cur = secFromMidnight + s;
        secFromMidnight = (int)(cur % 86400);
    }

    int getRaw() const {
        return secFromMidnight;
    }

    void show24() const {
        int hh = secFromMidnight / 3600;
        int mm = (secFromMidnight % 3600) / 60;
        int ss = secFromMidnight % 60;
        char buf[16];
        snprintf(buf, sizeof(buf), "%02d:%02d:%02d", hh, mm, ss);
        cout << buf << "\n";
    }

    void show12() const {
        int hh = secFromMidnight / 3600;
        int mm = (secFromMidnight % 3600) / 60;
        int ss = secFromMidnight % 60;
        int h12 = (hh == 0 || hh == 12) ? 12 : (hh % 12);
        const char* ampm = (hh < 12) ? "AM" : "PM";
        char buf[20];
        snprintf(buf, sizeof(buf), "%d:%02d:%02d %s", h12, mm, ss, ampm);
        cout << buf << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    if (!(cin >> q)) return 0;
    TimeRepresentation tr;

    for (int i = 0; i < q; ++i) {
        string type;
        cin >> type;
        if (type == "SET") {
            long long h, m, s;
            cin >> h >> m >> s;
            if (!tr.update(h, m, s)) {
                cout << "INVALID\n";
            }
        } else if (type == "ADD_SECONDS") {
            long long k;
            cin >> k;
            tr.advance(k);
        } else if (type == "PRINT_UNIVERSAL") {
            tr.show24();
        } else if (type == "PRINT_STANDARD") {
            tr.show12();
        } else if (type == "GET_SECONDS") {
            cout << tr.getRaw() << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>

using namespace std;

int rankToVal(char c) {
    if (c >= '2' && c <= '9') return c - '0';
    if (c == 'T') return 10;
    if (c == 'J') return 11;
    if (c == 'Q') return 12;
    if (c == 'K') return 13;
    if (c == 'A') return 14;
    return 0;
}

struct Card {
    string s;
    int r;
    char suit;
    Card(string str = "") : s(str) {
        if (str.size() >= 2) {
            r = rankToVal(str[0]);
            suit = str[1];
        } else {
            r = 0;
            suit = ' ';
        }
    }
};

string evaluateHand(const vector<Card>& hand) {
    map<int, int> counts;
    map<char, int> suitCounts;
    vector<int> ranks;
    for (const auto& c : hand) {
        counts[c.r]++;
        suitCounts[c.suit]++;
        ranks.push_back(c.r);
    }
    sort(ranks.begin(), ranks.end());

    bool isFlush = (suitCounts.size() == 1);
    bool isStraight = false;
    if (counts.size() == 5) {
        if (ranks[4] - ranks[0] == 4) isStraight = true;
        if (ranks[0] == 2 && ranks[1] == 3 && ranks[2] == 4 && ranks[3] == 5 && ranks[4] == 14) isStraight = true;
    }

    if (isFlush && isStraight) return "Straight Flush";
    for (auto p : counts) if (p.second == 4) return "Four of a Kind";
    bool has3 = false, has2 = false;
    for (auto p : counts) {
        if (p.second == 3) has3 = true;
        if (p.second == 2) has2 = true;
    }
    if (has3 && has2) return "Full House";
    if (isFlush) return "Flush";
    if (isStraight) return "Straight";
    if (has3) return "Three of a Kind";
    int pairCount = 0;
    for (auto p : counts) if (p.second == 2) pairCount++;
    if (pairCount == 2) return "Two Pair";
    if (pairCount == 1) return "One Pair";
    return "High Card";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<Card> hand(5);
    for (int i = 0; i < 5; ++i) {
        string s;
        if (!(cin >> s)) return 0;
        hand[i] = Card(s);
    }
    vector<Card> deck(3);
    for (int i = 0; i < 3; ++i) {
        string s;
        cin >> s;
        deck[i] = Card(s);
    }

    string initType = evaluateHand(hand);
    cout << initType << "\n";

    map<int, int> counts;
    for (const auto& c : hand) counts[c.r]++;

    int k = 0;
    vector<Card> kept;
    if (initType == "Straight Flush" || initType == "Four of a Kind" || 
        initType == "Full House" || initType == "Flush" || initType == "Straight") {
        k = 0;
        kept = hand;
    } else if (initType == "Three of a Kind") {
        k = 2;
        for (const auto& c : hand) {
            if (counts[c.r] == 3) kept.push_back(c);
        }
    } else if (initType == "Two Pair") {
        k = 1;
        for (const auto& c : hand) {
            if (counts[c.r] == 2) kept.push_back(c);
        }
    } else if (initType == "One Pair") {
        k = 3;
        for (const auto& c : hand) {
            if (counts[c.r] == 2) kept.push_back(c);
        }
    } else { // High Card
        k = 3;
        vector<Card> sortedHand = hand;
        sort(sortedHand.begin(), sortedHand.end(), [](const Card& a, const Card& b) {
            return a.r > b.r;
        });
        kept.push_back(sortedHand[0]);
        kept.push_back(sortedHand[1]);
    }

    cout << k << "\n";
    if (k == 0) {
        cout << "None\n";
    } else {
        for (int i = 0; i < k; ++i) {
            cout << deck[i].s << (i + 1 == k ? "" : " ");
            kept.push_back(deck[i]);
        }
        cout << "\n";
    }

    string finalType = evaluateHand(kept);
    cout << finalType << "\n";

    return 0;
}

