    for (int i = 1; i < 5; ++i) {
        if (s[i] != s[0]) flush = false;
    }
    vector<int> sortedR = r;
    sort(sortedR.begin(), sortedR.end());
    bool straight = false;
    bool distinct = true;
    for (int i = 0; i < 4; ++i) {
        if (sortedR[i] == sortedR[i+1]) distinct = false;
    }
    if (distinct) {
        if (sortedR[4] - sortedR[0] == 4) straight = true;
        if (sortedR[0] == 2 && sortedR[1] == 3 && sortedR[2] == 4 && sortedR[3] == 5 && sortedR[4] == 14) straight = true;
    }

