    if (has3 && has2) return "Full House";
    if (flush) return "Flush";
    if (straight) return "Straight";
    if (has3) return "Three of a Kind";
    if (pairs == 2) return "Two Pair";
    if (pairs == 1) return "One Pair";
    return "High Card";
}

