#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>

using namespace std;

int rankToVal(char c) {
    if (c >= '2' && c <= '9') return c - '0';
    if (c == 'T') return 10;
    if (c == 'J') return 11;
    if (c == 'Q') return 12;
    if (c == 'K') return 13;
    if (c == 'A') return 14;
    return 0;
}

struct HandRank {
    int category; // 8: Straight Flush, 7: 4 of a kind, 6: Full house, 5: Flush, 4: Straight, 3: 3 of a kind, 2: 2 pair, 1: 1 pair, 0: High card
    vector<int> tieBreakers;

    bool operator<(const HandRank& other) const {
        if (category != other.category) return category < other.category;
        return tieBreakers < other.tieBreakers;
    }
    bool operator>(const HandRank& other) const {
        if (category != other.category) return category > other.category;
        return tieBreakers > other.tieBreakers;
    }
    bool operator==(const HandRank& other) const {
        return category == other.category && tieBreakers == other.tieBreakers;
    }
};

HandRank evaluateHand(const vector<string>& cards) {
    vector<int> ranks;
    vector<char> suits;
    map<int, int> countMap;
    for (const auto& card : cards) {
        int r = rankToVal(card[0]);
        ranks.push_back(r);
        suits.push_back(card[1]);
        countMap[r]++;
    }
    sort(ranks.begin(), ranks.end(), greater<int>());

    bool flush = true;
    for (int i = 1; i < 5; ++i) {
        if (suits[i] != suits[0]) {
            flush = false;
            break;
        }
    }

    bool straight = false;
    int straightHigh = 0;
    vector<int> uniqueRanks = ranks;
    uniqueRanks.erase(unique(uniqueRanks.begin(), uniqueRanks.end()), uniqueRanks.end());

    if (uniqueRanks.size() == 5) {
        if (uniqueRanks[0] - uniqueRanks[4] == 4) {
            straight = true;
            straightHigh = uniqueRanks[0];
        } else if (uniqueRanks[0] == 14 && uniqueRanks[1] == 5 && uniqueRanks[2] == 4 && uniqueRanks[3] == 3 && uniqueRanks[4] == 2) {
            straight = true;
            straightHigh = 5;
        }
    }

    if (straight && flush) {
        return {8, {straightHigh}};
    }

    vector<pair<int, int>> freq;
    for (auto const& [r, count] : countMap) {
        freq.push_back({count, r});
    }
    sort(freq.begin(), freq.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second > b.second;
    });

    if (freq[0].first == 4) {
        return {7, {freq[0].second, freq[1].second}};
    }

    if (freq[0].first == 3 && freq[1].first == 2) {
        return {6, {freq[0].second, freq[1].second}};
    }

    if (flush) {
        return {5, ranks};
    }

    if (straight) {
        return {4, {straightHigh}};
    }

    if (freq[0].first == 3) {
        return {3, {freq[0].second, freq[1].second, freq[2].second}};
    }

    if (freq[0].first == 2 && freq[1].first == 2) {
        return {2, {freq[0].second, freq[1].second, freq[2].second}};
    }

    if (freq[0].first == 2) {
        return {1, {freq[0].second, freq[1].second, freq[2].second, freq[3].second}};
    }

    return {0, ranks};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (cin >> T) {
        while (T--) {
            vector<string> p1(5), p2(5);
            for (int i = 0; i < 5; ++i) cin >> p1[i];
            for (int i = 0; i < 5; ++i) cin >> p2[i];

            HandRank r1 = evaluateHand(p1);
            HandRank r2 = evaluateHand(p2);

            if (r1 > r2) {
                cout << "Player 1\n";
            } else if (r2 > r1) {
                cout << "Player 2\n";
            } else {
                cout << "Tie\n";
            }
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct HandScore {
    int type;
    vector<int> kickers;
    bool operator<(const HandScore& o) const {
        if (type != o.type) return type < o.type;
        return kickers < o.kickers;
    }
};

int getRank(char c) {
    string order = "23456789TJQKA";
    return 2 + (int)order.find(c);
}

HandScore eval(const vector<string>& hand) {
    vector<int> r(5);
    bool sameSuit = true;
    for (int i = 0; i < 5; ++i) {
        r[i] = getRank(hand[i][0]);
        if (hand[i][1] != hand[0][1]) sameSuit = false;
    }
    map<int, int> cnt;
    for (int x : r) cnt[x]++;

    vector<pair<int, int>> grps;
    for (auto p : cnt) grps.push_back({p.second, p.first});
    sort(grps.begin(), grps.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second > b.second;
    });

    vector<int> sortedR = r;
    sort(sortedR.begin(), sortedR.end());
    bool isStr = false;
    int strTop = 0;
    if (grps.size() == 5) {
        if (sortedR[4] - sortedR[0] == 4) {
            isStr = true;
            strTop = sortedR[4];
        } else if (sortedR == vector<int>{2, 3, 4, 5, 14}) {
            isStr = true;
            strTop = 5;
        }
    }

    if (sameSuit && isStr) return {8, {strTop}};
    if (grps[0].first == 4) return {7, {grps[0].second, grps[1].second}};
    if (grps[0].first == 3 && grps[1].first == 2) return {6, {grps[0].second, grps[1].second}};
    if (sameSuit) {
        vector<int> k = r;
        sort(k.rbegin(), k.rend());
        return {5, k};
    }
    if (isStr) return {4, {strTop}};
    if (grps[0].first == 3) return {3, {grps[0].second, grps[1].second, grps[2].second}};
    if (grps[0].first == 2 && grps[1].first == 2) return {2, {grps[0].second, grps[1].second, grps[2].second}};
    if (grps[0].first == 2) return {1, {grps[0].second, grps[1].second, grps[2].second, grps[3].second}};

    vector<int> k = r;
    sort(k.rbegin(), k.rend());
    return {0, k};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (cin >> T) {
        while (T--) {
            vector<string> h1(5), h2(5);
            for (int i = 0; i < 5; ++i) cin >> h1[i];
            for (int i = 0; i < 5; ++i) cin >> h2[i];
            HandScore s1 = eval(h1), s2 = eval(h2);
            if (s2 < s1) cout << "Player 1\n";
            else if (s1 < s2) cout << "Player 2\n";
            else cout << "Tie\n";
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

class Complex {
private:
    double real;
    double imag;

public:
    Complex(double r = 0.0, double i = 0.0) : real(r), imag(i) {}

    Complex operator+(const Complex& other) const {
        return Complex(real + other.real, imag + other.imag);
    }

    Complex operator-(const Complex& other) const {
        return Complex(real - other.real, imag - other.imag);
    }

    Complex operator*(const Complex& other) const {
        return Complex(real * other.real - imag * other.imag,
                       real * other.imag + imag * other.real);
    }

    bool operator==(const Complex& other) const {
        return std::abs(real - other.real) < 1e-9 && std::abs(imag - other.imag) < 1e-9;
    }

    bool operator!=(const Complex& other) const {
        return !(*this == other);
    }

    friend std::istream& operator>>(std::istream& in, Complex& c) {
        in >> c.real >> c.imag;
        return in;
    }

    friend std::ostream& operator<<(std::ostream& out, const Complex& c) {
        out << '(' << std::fixed << std::setprecision(2) << c.real << ", " << c.imag << ')';
        return out;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    Complex A, B;
    if (std::cin >> A >> B) {
        std::cout << "A + B = " << (A + B) << "\n";
        std::cout << "A - B = " << (A - B) << "\n";
        std::cout << "A * B = " << (A * B) << "\n";
        std::cout << "A == B: " << (A == B ? "true" : "false") << "\n";
        std::cout << "A != B: " << (A != B ? "true" : "false") << "\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>

struct ComplexNumber {
    double re;
    double im;

    ComplexNumber(double r = 0, double i = 0) : re(r), im(i) {}
};

ComplexNumber operator+(const ComplexNumber& u, const ComplexNumber& v) {
    return ComplexNumber(u.re + v.re, u.im + v.im);
}

ComplexNumber operator-(const ComplexNumber& u, const ComplexNumber& v) {
    return ComplexNumber(u.re - v.re, u.im - v.im);
}

ComplexNumber operator*(const ComplexNumber& u, const ComplexNumber& v) {
    return ComplexNumber(u.re * v.re - u.im * v.im, u.re * v.im + u.im * v.re);
}

bool operator==(const ComplexNumber& u, const ComplexNumber& v) {
    const double EPS = 1e-9;
    double dr = u.re - v.re;
    double di = u.im - v.im;
    if (dr < 0) dr = -dr;
    if (di < 0) di = -di;
    return dr < EPS && di < EPS;
}

bool operator!=(const ComplexNumber& u, const ComplexNumber& v) {
    return !(u == v);
}

std::istream& operator>>(std::istream& is, ComplexNumber& c) {
    return is >> c.re >> c.im;
}

std::ostream& operator<<(std::ostream& os, const ComplexNumber& c) {
    auto flags = os.flags();
    auto prec = os.precision();
    os << std::fixed << std::setprecision(2);
    os << '(' << c.re << ", " << c.im << ')';
    os.flags(flags);
    os.precision(prec);
    return os;
}

int main() {
    ComplexNumber num1, num2;
    if (!(std::cin >> num1 >> num2)) return 0;

    std::cout << "A + B = " << num1 + num2 << "\n";
    std::cout << "A - B = " << num1 - num2 << "\n";
    std::cout << "A * B = " << num1 * num2 << "\n";
    std::cout << "A == B: " << (num1 == num2 ? "true" : "false") << "\n";
    std::cout << "A != B: " << (num1 != num2 ? "true" : "false") << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

using namespace std;

class DoubleSubscriptedArray {
private:
    int rows;
    int cols;
    vector<long long> data;

public:
    DoubleSubscriptedArray(int r = 0, int c = 0) : rows(r), cols(c), data(r * c, 0) {}

    int getRows() const { return rows; }
    int getCols() const { return cols; }

    long long& operator()(int r, int c) {
        return data[r * cols + c];
    }

    long long operator()(int r, int c) const {
        return data[r * cols + c];
    }

    bool operator==(const DoubleSubscriptedArray& other) const {
        if (rows != other.rows || cols != other.cols) return false;
        return data == other.data;
    }

    bool operator!=(const DoubleSubscriptedArray& other) const {
        return !(*this == other);
    }

    DoubleSubscriptedArray& operator=(const DoubleSubscriptedArray& other) {
        if (this != &other) {
            rows = other.rows;
            cols = other.cols;
            data = other.data;
        }
        return *this;
    }

    friend istream& operator>>(istream& is, DoubleSubscriptedArray& arr) {
        for (int i = 0; i < arr.rows; ++i) {
            for (int j = 0; j < arr.cols; ++j) {
                is >> arr(i, j);
            }
        }
        return is;
    }

    friend ostream& operator<<(ostream& os, const DoubleSubscriptedArray& arr) {
        for (int i = 0; i < arr.rows; ++i) {
            for (int j = 0; j < arr.cols; ++j) {
                os << arr(i, j) << (j + 1 == arr.cols ? "" : " ");
            }
            os << "\n";
        }
        return os;
    }
};

