using namespace std;

class DoubleSubscriptedArray {
    int r, c;
    long long* ptr;
public:
    DoubleSubscriptedArray(int rows = 0, int cols = 0) : r(rows), c(cols) {
        ptr = (r * c > 0) ? new long long[r * c]() : nullptr;
    }

    DoubleSubscriptedArray(const DoubleSubscriptedArray& other) : r(other.r), c(other.c) {
        ptr = (r * c > 0) ? new long long[r * c] : nullptr;
        for (int i = 0; i < r * c; ++i) ptr[i] = other.ptr[i];
    }

    ~DoubleSubscriptedArray() {
        delete[] ptr;
    }

    DoubleSubscriptedArray& operator=(const DoubleSubscriptedArray& other) {
        if (this != &other) {
            delete[] ptr;
            r = other.r;
            c = other.c;
            ptr = (r * c > 0) ? new long long[r * c] : nullptr;
            for (int i = 0; i < r * c; ++i) ptr[i] = other.ptr[i];
        }
        return *this;
    }

    long long& operator()(int row, int col) {
        return *(ptr + row * c + col);
    }

    long long operator()(int row, int col) const {
        return *(ptr + row * c + col);
    }

    bool operator==(const DoubleSubscriptedArray& other) const {
        if (r != other.r || c != other.c) return false;
        for (int i = 0; i < r * c; ++i) {
            if (ptr[i] != other.ptr[i]) return false;
        }
        return true;
    }

    bool operator!=(const DoubleSubscriptedArray& other) const {
        return !(*this == other);
    }

    int numRows() const { return r; }
    int numCols() const { return c; }
};

istream& operator>>(istream& is, DoubleSubscriptedArray& arr) {
    for (int i = 0; i < arr.numRows(); ++i) {
        for (int j = 0; j < arr.numCols(); ++j) {
            is >> arr(i, j);
        }
    }
    return is;
}

ostream& operator<<(ostream& os, const DoubleSubscriptedArray& arr) {
    for (int i = 0; i < arr.numRows(); ++i) {
        for (int j = 0; j < arr.numCols(); ++j) {
            os << arr(i, j) << (j + 1 == arr.numCols() ? "" : " ");
        }
        os << "\n";
    }
    return os;
}

