#include <iostream>
#include <string>
#include <numeric>
#include <cstdint>

using namespace std;

class RationalNumber {
private:
    __int128 num;
    __int128 den;

    static __int128 gcd(__int128 a, __int128 b) {
        if (a < 0) a = -a;
        if (b < 0) b = -b;
        while (b) {
            a %= b;
            __int128 t = a; a = b; b = t;
        }
        return a;
    }

    void reduce() {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        if (num == 0) {
            den = 1;
            return;
        }
        __int128 g = gcd(num, den);
        num /= g;
        den /= g;
    }

public:
    RationalNumber(__int128 n = 0, __int128 d = 1) : num(n), den(d) {
        reduce();
    }

    RationalNumber operator+(const RationalNumber& o) const {
        return RationalNumber(num * o.den + o.num * den, den * o.den);
    }

    RationalNumber operator-(const RationalNumber& o) const {
        return RationalNumber(num * o.den - o.num * den, den * o.den);
    }

    RationalNumber operator*(const RationalNumber& o) const {
        return RationalNumber(num * o.num, den * o.den);
    }

    RationalNumber operator/(const RationalNumber& o) const {
        return RationalNumber(num * o.den, den * o.num);
    }

    bool operator==(const RationalNumber& o) const {
        return num == o.num && den == o.den;
    }

    bool operator!=(const RationalNumber& o) const {
        return !(*this == o);
    }

    bool operator<(const RationalNumber& o) const {
        return num * o.den < o.num * den;
    }

    bool operator<=(const RationalNumber& o) const {
        return num * o.den <= o.num * den;
    }

    bool operator>(const RationalNumber& o) const {
        return num * o.den > o.num * den;
    }

    bool operator>=(const RationalNumber& o) const {
        return num * o.den >= o.num * den;
    }

    void print() const {
        long long n = (long long)num;
        long long d = (long long)den;
        cout << n << "/" << d << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        long long a1, b1, a2, b2;
        string op;
        cin >> a1 >> b1 >> op >> a2 >> b2;
        RationalNumber r1(a1, b1), r2(a2, b2);
        if (op == "+") {
            (r1 + r2).print();
        } else if (op == "-") {
            (r1 - r2).print();
        } else if (op == "*") {
            (r1 * r2).print();
        } else if (op == "/") {
            (r1 / r2).print();
        } else if (op == "==") {
            cout << (r1 == r2 ? "true" : "false") << "\n";
        } else if (op == "!=") {
            cout << (r1 != r2 ? "true" : "false") << "\n";
        } else if (op == "<") {
            cout << (r1 < r2 ? "true" : "false") << "\n";
        } else if (op == "<=") {
            cout << (r1 <= r2 ? "true" : "false") << "\n";
        } else if (op == ">") {
            cout << (r1 > r2 ? "true" : "false") << "\n";
        } else if (op == ">=") {
            cout << (r1 >= r2 ? "true" : "false") << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>

using namespace std;

typedef __int128_t int128;

int128 get_gcd(int128 a, int128 b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        int128 r = a % b;
        a = b;
        b = r;
    }
    return a;
}

struct Fraction {
    int128 p, q;
    Fraction(int128 num = 0, int128 den = 1) {
        if (den < 0) {
            num = -num;
            den = -den;
        }
        if (num == 0) {
            p = 0;
            q = 1;
        } else {
            int128 g = get_gcd(num, den);
            p = num / g;
            q = den / g;
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (cin >> T) {
        while (T--) {
            long long a1, b1, a2, b2;
            string op;
            cin >> a1 >> b1 >> op >> a2 >> b2;
            Fraction f1(a1, b1), f2(a2, b2);
            if (op == "+") {
                Fraction res(f1.p * f2.q + f2.p * f1.q, f1.q * f2.q);
                cout << (long long)res.p << "/" << (long long)res.q << "\n";
            } else if (op == "-") {
                Fraction res(f1.p * f2.q - f2.p * f1.q, f1.q * f2.q);
                cout << (long long)res.p << "/" << (long long)res.q << "\n";
            } else if (op == "*") {
                Fraction res(f1.p * f2.p, f1.q * f2.q);
                cout << (long long)res.p << "/" << (long long)res.q << "\n";
            } else if (op == "/") {
                Fraction res(f1.p * f2.q, f1.q * f2.p);
                cout << (long long)res.p << "/" << (long long)res.q << "\n";
            } else if (op == "==") {
                cout << ((f1.p == f2.p && f1.q == f2.q) ? "true" : "false") << "\n";
            } else if (op == "!=") {
                cout << ((f1.p != f2.p || f1.q != f2.q) ? "true" : "false") << "\n";
            } else {
                int128 diff = f1.p * f2.q - f2.p * f1.q;
                if (op == "<") cout << (diff < 0 ? "true" : "false") << "\n";
                else if (op == "<=") cout << (diff <= 0 ? "true" : "false") << "\n";
                else if (op == ">") cout << (diff > 0 ? "true" : "false") << "\n";
                else if (op == ">=") cout << (diff >= 0 ? "true" : "false") << "\n";
            }
        }
    }
    return 0;
}

