using namespace std;

class Account {
protected:
    double balance;
public:
    Account(double initialBalance) {
        if (initialBalance >= 0.0) {
            balance = initialBalance;
        } else {
            balance = 0.0;
            cout << "Error: Initial balance cannot be negative.\n";
        }
    }
    virtual ~Account() = default;

    virtual void credit(double amount) {
        if (amount > 0.0) {
            balance += amount;
        }
    }

    virtual bool debit(double amount) {
        if (amount > balance) {
            cout << "Debit amount exceeded account balance.\n";
            return false;
        } else {
            balance -= amount;
            return true;
        }
    }

    double getBalance() const {
        return balance;
    }
};

class SavingsAccount : public Account {
private:
    double interestRate;
public:
    SavingsAccount(double initialBalance, double rate) : Account(initialBalance) {
        interestRate = (rate >= 0.0) ? rate : 0.0;
    }

    double calculateInterest() const {
        return balance * interestRate;
    }
};

class CheckingAccount : public Account {
private:
    double fee;
public:
    CheckingAccount(double initialBalance, double transactionFee) : Account(initialBalance) {
        fee = (transactionFee >= 0.0) ? transactionFee : 0.0;
    }

    void credit(double amount) override {
        Account::credit(amount);
        balance -= fee;
    }

    bool debit(double amount) override {
        bool success = Account::debit(amount);
        if (success) {
            balance -= fee;
            return true;
        }
        return false;
    }
};

