#include <iostream>
#include <vector>
#include <map>

using namespace std;

struct Term {
    long long coeff;
    int exp;
};

class Polynomial {
private:
    map<int, long long> terms; // exp -> coeff
public:
    Polynomial() {}

    void addTerm(long long c, int e) {
        terms[e] += c;
        if (terms[e] == 0) {
            terms.erase(e);
        }
    }

    Polynomial& operator+=(const Polynomial& other) {
        for (const auto& kv : other.terms) {
            this->addTerm(kv.second, kv.first);
        }
        return *this;
    }

    Polynomial operator+(const Polynomial& other) const {
        Polynomial res = *this;
        res += other;
        return res;
    }

    Polynomial& operator-=(const Polynomial& other) {
        for (const auto& kv : other.terms) {
            this->addTerm(-kv.second, kv.first);
        }
        return *this;
    }

    Polynomial operator-(const Polynomial& other) const {
        Polynomial res = *this;
        res -= other;
        return res;
    }

    Polynomial operator*(const Polynomial& other) const {
        Polynomial res;
        for (const auto& p1 : this->terms) {
            for (const auto& p2 : other.terms) {
                res.addTerm(p1.second * p2.second, p1.first + p2.first);
            }
        }
        return res;
    }

    Polynomial& operator*=(const Polynomial& other) {
        *this = *this * other;
        return *this;
    }

    void print() const {
        vector<pair<int, long long>> nonZero;
        for (auto it = terms.rbegin(); it != terms.rend(); ++it) {
            if (it->second != 0) {
                nonZero.push_back({it->first, it->second});
            }
        }
        if (nonZero.empty()) {
            cout << 0 << "\n";
        } else {
            cout << nonZero.size() << "\n";
            for (const auto& item : nonZero) {
                cout << item.second << " " << item.first << "\n";
            }
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    Polynomial A;
    for (int i = 0; i < n; ++i) {
        long long c;
        int e;
        cin >> c >> e;
        A.addTerm(c, e);
    }

    int m;
    if (!(cin >> m)) return 0;
    Polynomial B;
    for (int i = 0; i < m; ++i) {
        long long c;
        int e;
        cin >> c >> e;
        B.addTerm(c, e);
    }

    Polynomial sum = A + B;
    sum.print();

    Polynomial diff = A - B;
    diff.print();

    Polynomial prod = A * B;
    prod.print();

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

class Polynomial {
public:
    vector<long long> poly;

    Polynomial() {
        poly.assign(205, 0);
    }

    void setCoeff(int exp, long long coeff) {
        if (exp >= (int)poly.size()) {
            poly.resize(exp + 1, 0);
        }
        poly[exp] += coeff;
    }

    Polynomial operator+(const Polynomial& b) const {
        Polynomial res;
        int sz = max(this->poly.size(), b.poly.size());
        res.poly.assign(sz, 0);
        for (size_t i = 0; i < this->poly.size(); ++i) res.poly[i] += this->poly[i];
        for (size_t i = 0; i < b.poly.size(); ++i) res.poly[i] += b.poly[i];
        return res;
    }

    Polynomial operator-(const Polynomial& b) const {
        Polynomial res;
        int sz = max(this->poly.size(), b.poly.size());
        res.poly.assign(sz, 0);
        for (size_t i = 0; i < this->poly.size(); ++i) res.poly[i] += this->poly[i];
        for (size_t i = 0; i < b.poly.size(); ++i) res.poly[i] -= b.poly[i];
        return res;
    }

    Polynomial operator*(const Polynomial& b) const {
        Polynomial res;
        res.poly.assign(this->poly.size() + b.poly.size() + 2, 0);
        for (size_t i = 0; i < this->poly.size(); ++i) {
            if (this->poly[i] == 0) continue;
            for (size_t j = 0; j < b.poly.size(); ++j) {
                if (b.poly[j] == 0) continue;
                res.poly[i + j] += this->poly[i] * b.poly[j];
            }
        }
        return res;
    }

    void output() const {
        vector<pair<int, long long>> non_zero;
        for (int i = (int)poly.size() - 1; i >= 0; --i) {
            if (poly[i] != 0) {
                non_zero.push_back({i, poly[i]});
            }
        }
        if (non_zero.empty()) {
            cout << 0 << "\n";
        } else {
            cout << non_zero.size() << "\n";
            for (const auto& p : non_zero) {
                cout << p.second << " " << p.first << "\n";
            }
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    Polynomial A;
    for (int i = 0; i < n; ++i) {
        long long c;
        int e;
        cin >> c >> e;
        A.setCoeff(e, c);
    }

    int m;
    if (!(cin >> m)) return 0;
    Polynomial B;
    for (int i = 0; i < m; ++i) {
        long long c;
        int e;
        cin >> c >> e;
        B.setCoeff(e, c);
    }

    (A + B).output();
    (A - B).output();
    (A * B).output();

    return 0;
}

