class Employee {
protected:
    std::string name;
public:
    Employee(const std::string& n) : name(n) {}
    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    std::string getName() const { return name; }
};

class PieceWorker : public Employee {
private:
    double wage;
    int pieces;
public:
    PieceWorker(const std::string& n, double w, int p)
        : Employee(n), wage(w), pieces(p) {}
    double earnings() const override {
        return wage * pieces;
    }
};

class HourlyWorker : public Employee {
private:
    double wage;
    double hours;
public:
    HourlyWorker(const std::string& n, double w, double h)
        : Employee(n), wage(w), hours(h) {}
    double earnings() const override {
        if (hours <= 40.0) {
            return hours * wage;
        } else {
            return 40.0 * wage + (hours - 40.0) * wage * 1.5;
        }
    }
};

