#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int compareHuge(const string &a, const string &b) {
    if (a.length() < b.length()) return -1;
    if (a.length() > b.length()) return 1;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

string subtractHuge(string a, string b) {
    string res = "";
    int n = a.length(), m = b.length();
    int borrow = 0;
    for (int i = 0; i < n; ++i) {
        int digitA = a[n - 1 - i] - '0';
        int digitB = (i < m ? b[m - 1 - i] - '0' : 0);
        int diff = digitA - digitB - borrow;
        if (diff < 0) {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        res.push_back(diff + '0');
    }
    while (res.length() > 1 && res.back() == '0') {
        res.pop_back();
    }
    reverse(res.begin(), res.end());
    return res;
}

string multiplyHuge(const string &a, const string &b) {
    if (a == "0" || b == "0") return "0";
    int n = a.length(), m = b.length();
    vector<int> res(n + m, 0);
    for (int i = n - 1; i >= 0; --i) {
        for (int j = m - 1; j >= 0; --j) {
            res[i + j + 1] += (a[i] - '0') * (b[j] - '0');
        }
    }
    for (int i = n + m - 1; i > 0; --i) {
        res[i - 1] += res[i] / 10;
        res[i] %= 10;
    }
    string s = "";
    int start = (res[0] == 0 ? 1 : 0);
    for (int i = start; i < n + m; ++i) {
        s.push_back(res[i] + '0');
    }
    return s.empty() ? "0" : s;
}

string divideHuge(const string &a, const string &b) {
    if (compareHuge(a, b) < 0) return "0";
    string quotient = "";
    string current = "";
    for (char c : a) {
        if (current == "0") current = "";
        current.push_back(c);
        int count = 0;
        while (compareHuge(current, b) >= 0) {
            current = subtractHuge(current, b);
            count++;
        }
        quotient.push_back(count + '0');
    }
    int start = 0;
    while (start < (int)quotient.length() - 1 && quotient[start] == '0') {
        start++;
    }
    return quotient.substr(start);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string A, B;
    if (!(cin >> A >> B)) return 0;

    int cmp = compareHuge(A, B);
    cout << (cmp == 0 ? "true" : "false") << " "
         << (cmp != 0 ? "true" : "false") << " "
         << (cmp < 0 ? "true" : "false") << " "
         << (cmp <= 0 ? "true" : "false") << " "
         << (cmp > 0 ? "true" : "false") << " "
         << (cmp >= 0 ? "true" : "false") << "\n";

    cout << multiplyHuge(A, B) << "\n";
    cout << divideHuge(A, B) << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

struct BigInt {
    vector<int> d;

    BigInt() {}
    BigInt(const string &s) {
        for (int i = (int)s.size() - 1; i >= 0; --i) {
            d.push_back(s[i] - '0');
        }
        trim();
    }

    void trim() {
        while (d.size() > 1 && d.back() == 0) {
            d.pop_back();
        }
    }

    bool operator==(const BigInt &other) const {
        return d == other.d;
    }
    bool operator!=(const BigInt &other) const {
        return !(*this == other);
    }
    bool operator<(const BigInt &other) const {
        if (d.size() != other.d.size()) return d.size() < other.d.size();
        for (int i = (int)d.size() - 1; i >= 0; --i) {
            if (d[i] != other.d[i]) return d[i] < other.d[i];
        }
        return false;
    }
    bool operator<=(const BigInt &other) const {
        return *this < other || *this == other;
    }
    bool operator>(const BigInt &other) const {
        return !(*this <= other);
    }
    bool operator>=(const BigInt &other) const {
        return !(*this < other);
    }

    BigInt operator*(const BigInt &other) const {
        if ((d.size() == 1 && d[0] == 0) || (other.d.size() == 1 && other.d[0] == 0)) {
            return BigInt("0");
        }
        BigInt res;
        res.d.assign(d.size() + other.d.size(), 0);
        for (size_t i = 0; i < d.size(); ++i) {
            for (size_t j = 0; j < other.d.size(); ++j) {
                res.d[i + j] += d[i] * other.d[j];
            }
        }
        int carry = 0;
        for (size_t i = 0; i < res.d.size(); ++i) {
            int cur = res.d[i] + carry;
            res.d[i] = cur % 10;
            carry = cur / 10;
        }
        res.trim();
        return res;
    }

    BigInt operator-(const BigInt &other) const {
        BigInt res = *this;
        int carry = 0;
        for (size_t i = 0; i < res.d.size(); ++i) {
            int sub = (i < other.d.size() ? other.d[i] : 0) + carry;
            if (res.d[i] < sub) {
                res.d[i] += 10 - sub;
                carry = 1;
            } else {
                res.d[i] -= sub;
                carry = 0;
            }
        }
        res.trim();
        return res;
    }

    BigInt operator/(const BigInt &other) const {
        if (*this < other) return BigInt("0");
        BigInt cur("0");
        BigInt res;
        res.d.assign(d.size(), 0);
        for (int i = (int)d.size() - 1; i >= 0; --i) {
            if (cur.d.size() == 1 && cur.d[0] == 0) {
                cur.d[0] = d[i];
            } else {
                cur.d.insert(cur.d.begin(), d[i]);
            }
            cur.trim();
            int l = 0, r = 9, ans = 0;
            while (l <= r) {
                int mid = (l + r) / 2;
                BigInt m;
                m.d = {mid};
                if (other * m <= cur) {
                    ans = mid;
                    l = mid + 1;
                } else {
                    r = mid - 1;
                }
            }
            res.d[i] = ans;
            BigInt m;
            m.d = {ans};
            cur = cur - (other * m);
        }
        res.trim();
        return res;
    }

    string toString() const {
        string s = "";
        for (int i = (int)d.size() - 1; i >= 0; --i) {
            s.push_back(d[i] + '0');
        }
        return s;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string sA, sB;
    if (!(cin >> sA >> sB)) return 0;

    BigInt A(sA), B(sB);

    cout << (A == B ? "true" : "false") << " "
         << (A != B ? "true" : "false") << " "
         << (A < B ? "true" : "false") << " "
         << (A <= B ? "true" : "false") << " "
         << (A > B ? "true" : "false") << " "
         << (A >= B ? "true" : "false") << "\n";

    cout << (A * B).toString() << "\n";
    cout << (A / B).toString() << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <memory>
#include <iomanip>

class Account {
protected:
    double balance;
public:
    Account(double initialBalance) : balance(initialBalance >= 0.0 ? initialBalance : 0.0) {}
    virtual ~Account() = default;

    virtual void credit(double amount) {
        if (amount > 0.0) {
            balance += amount;
        }
    }

    virtual bool debit(double amount) {
        if (amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    double getBalance() const {
        return balance;
    }
};

class SavingsAccount : public Account {
private:
    double interestRate;
public:
    SavingsAccount(double initialBalance, double rate) 
        : Account(initialBalance), interestRate(rate >= 0.0 ? rate : 0.0) {}

    double calculateInterest() const {
        return balance * interestRate;
    }
};

class CheckingAccount : public Account {
private:
    double fee;
public:
    CheckingAccount(double initialBalance, double transactionFee) 
        : Account(initialBalance), fee(transactionFee >= 0.0 ? transactionFee : 0.0) {}

    void credit(double amount) override {
        Account::credit(amount);
        balance -= fee;
    }

    bool debit(double amount) override {
        if (Account::debit(amount)) {
            balance -= fee;
            return true;
        }
        return false;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<std::unique_ptr<Account>> accounts;
    std::vector<std::pair<double, double>> transactions;

    for (int i = 0; i < n; ++i) {
        char type;
        std::cin >> type;
        if (type == 'S') {
            double bal, rate, w, d;
            std::cin >> bal >> rate >> w >> d;
            accounts.push_back(std::make_unique<SavingsAccount>(bal, rate));
            transactions.push_back({w, d});
        } else {
            double bal, fee, w, d;
            std::cin >> bal >> fee >> w >> d;
            accounts.push_back(std::make_unique<CheckingAccount>(bal, fee));
            transactions.push_back({w, d});
        }
    }

    std::cout << std::fixed << std::setprecision(2);
    for (size_t i = 0; i < accounts.size(); ++i) {
        double w = transactions[i].first;
        double d = transactions[i].second;

        accounts[i]->debit(w);
        accounts[i]->credit(d);

        SavingsAccount* savings = dynamic_cast<SavingsAccount*>(accounts[i].get());
        if (savings != nullptr) {
            double interest = savings->calculateInterest();
            savings->credit(interest);
        }

        std::cout << accounts[i]->getBalance() << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <iomanip>

struct BaseAccount {
    double bal;
    BaseAccount(double b) : bal(b >= 0.0 ? b : 0.0) {}
    virtual ~BaseAccount() = default;
    virtual void deposit(double amt) { if (amt > 0) bal += amt; }
    virtual bool withdraw(double amt) {
        if (amt <= bal) {
            bal -= amt;
            return true;
        }
        return false;
    }
    double currentBalance() const { return bal; }
};

struct Savings : public BaseAccount {
    double rate;
    Savings(double b, double r) : BaseAccount(b), rate(r) {}
    double getInterest() const { return bal * rate; }
};

struct Checking : public BaseAccount {
    double fee;
    Checking(double b, double f) : BaseAccount(b), fee(f) {}
    void deposit(double amt) override {
        BaseAccount::deposit(amt);
        bal -= fee;
    }
    bool withdraw(double amt) override {
        if (BaseAccount::withdraw(amt)) {
            bal -= fee;
            return true;
        }
        return false;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) return 0;

    std::cout << std::fixed << std::setprecision(2);

    for (int i = 0; i < n; ++i) {
        char type;
        std::cin >> type;
        if (type == 'S') {
            double b, r, w, d;
            std::cin >> b >> r >> w >> d;
            Savings sa(b, r);
            sa.withdraw(w);
            sa.deposit(d);
            double interest = sa.getInterest();
            sa.deposit(interest);
            std::cout << sa.currentBalance() << "\n";
        } else {
            double b, f, w, d;
            std::cin >> b >> f >> w >> d;
            Checking ca(b, f);
            ca.withdraw(w);
            ca.deposit(d);
            std::cout << ca.currentBalance() << "\n";
        }
    }

    return 0;
}

