using namespace std;

struct Address {
    string name;
    string street;
    string city;
    string state;
    string zip;
};

class Package {
protected:
    Address sender;
    Address recipient;
    double weight;
    double costPerOunce;
public:
    Package(const Address& s, const Address& r, double w, double c)
        : sender(s), recipient(r), weight(w), costPerOunce(c) {}
    virtual ~Package() = default;

    const Address& getSender() const { return sender; }
    const Address& getRecipient() const { return recipient; }
    double getWeight() const { return weight; }
    double getCostPerOunce() const { return costPerOunce; }

    virtual double calculateCost() const {
        return weight * costPerOunce;
    }
};

class TwoDayPackage : public Package {
private:
    double flatFee;
public:
    TwoDayPackage(const Address& s, const Address& r, double w, double c, double fee)
        : Package(s, r, w, c), flatFee(fee) {}

    double calculateCost() const override {
        return Package::calculateCost() + flatFee;
    }
};

class OvernightPackage : public Package {
private:
    double additionalFeePerOunce;
public:
    OvernightPackage(const Address& s, const Address& r, double w, double c, double addFee)
        : Package(s, r, w, c), additionalFeePerOunce(addFee) {}

    double calculateCost() const override {
        return weight * (costPerOunce + additionalFeePerOunce);
    }
};

Address parseAddress(const string& line) {
    Address addr;
    stringstream ss(line);
    getline(ss, addr.name, '|');
    getline(ss, addr.street, '|');
    getline(ss, addr.city, '|');
    getline(ss, addr.state, '|');
    getline(ss, addr.zip, '|');
    return addr;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<unique_ptr<Package>> packages;

    for (int i = 0; i < n; ++i) {
        string type;
        getline(cin, type);
        string senderLine, recipientLine;
        getline(cin, senderLine);
        getline(cin, recipientLine);
        Address sender = parseAddress(senderLine);
        Address recipient = parseAddress(recipientLine);

        if (type == "TwoDay") {
            double w, c, fee;
            cin >> w >> c >> fee;
            getline(cin, dummy);
            packages.push_back(make_unique<TwoDayPackage>(sender, recipient, w, c, fee));
        } else {
            double w, c, addFee;
            cin >> w >> c >> addFee;
            getline(cin, dummy);
            packages.push_back(make_unique<OvernightPackage>(sender, recipient, w, c, addFee));
        }
    }

    double totalCost = 0.0;
    cout << fixed << setprecision(2);

    for (size_t i = 0; i < packages.size(); ++i) {
        if (i > 0) cout << "\n";
        cout << "Package " << (i + 1) << ":\n";
        const Address& s = packages[i]->getSender();
        const Address& r = packages[i]->getRecipient();
        cout << "Sender:\n";
        cout << "  " << s.name << "\n";
        cout << "  " << s.street << "\n";
        cout << "  " << s.city << ", " << s.state << " " << s.zip << "\n";
        cout << "Recipient:\n";
        cout << "  " << r.name << "\n";
        cout << "  " << r.street << "\n";
        cout << "  " << r.city << ", " << r.state << " " << r.zip << "\n";
        double cost = packages[i]->calculateCost();
        cout << "Cost: $" << cost << "\n";
        totalCost += cost;
    }

    cout << "\nTotal shipping cost: $" << totalCost << "\n";

    return 0;
}

#include <iostream>
#include <string>
