#include <iomanip>

using namespace std;

struct Contact {
    string name, street, city, state, zip;
};

class Package {
protected:
    Contact sender;
    Contact recipient;
    double weight;
    double rate;
public:
    Package(Contact s, Contact r, double w, double rt)
        : sender(move(s)), recipient(move(r)), weight(w), rate(rt) {}
    virtual ~Package() {}

    const Contact& getSender() const { return sender; }
    const Contact& getRecipient() const { return recipient; }
    virtual double calculateCost() const {
        return weight * rate;
    }
};

class TwoDayPackage : public Package {
    double flatFee;
public:
    TwoDayPackage(Contact s, Contact r, double w, double rt, double fee)
        : Package(move(s), move(r), w, rt), flatFee(fee) {}
    double calculateCost() const override {
        return Package::calculateCost() + flatFee;
    }
};

class OvernightPackage : public Package {
    double extraPerOunce;
public:
    OvernightPackage(Contact s, Contact r, double w, double rt, double extra)
        : Package(move(s), move(r), w, rt), extraPerOunce(extra) {}
    double calculateCost() const override {
        return weight * (rate + extraPerOunce);
    }
};

static Contact readContact(const string& str) {
    Contact c;
    size_t p1 = str.find('|');
    size_t p2 = str.find('|', p1 + 1);
    size_t p3 = str.find('|', p2 + 1);
    size_t p4 = str.find('|', p3 + 1);
    c.name = str.substr(0, p1);
    c.street = str.substr(p1 + 1, p2 - p1 - 1);
    c.city = str.substr(p2 + 1, p3 - p2 - 1);
    c.state = str.substr(p3 + 1, p4 - p3 - 1);
    c.zip = str.substr(p4 + 1);
    return c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<Package*> vec;
    vec.reserve(n);

    for (int i = 0; i < n; ++i) {
        string type;
        getline(cin, type);
        string sLine, rLine;
        getline(cin, sLine);
        getline(cin, rLine);
        Contact s = readContact(sLine);
        Contact r = readContact(rLine);
        double w, rate, extra;
        cin >> w >> rate >> extra;
        getline(cin, dummy);

        if (type == "TwoDay") {
            vec.push_back(new TwoDayPackage(s, r, w, rate, extra));
        } else {
            vec.push_back(new OvernightPackage(s, r, w, rate, extra));
        }
    }

    cout << fixed << setprecision(2);
    double grandTotal = 0.0;
    for (int i = 0; i < n; ++i) {
        if (i > 0) cout << "\n";
        cout << "Package " << (i + 1) << ":\n";
        cout << "Sender:\n";
        cout << "  " << vec[i]->getSender().name << "\n";
        cout << "  " << vec[i]->getSender().street << "\n";
        cout << "  " << vec[i]->getSender().city << ", " << vec[i]->getSender().state << " " << vec[i]->getSender().zip << "\n";
        cout << "Recipient:\n";
        cout << "  " << vec[i]->getRecipient().name << "\n";
        cout << "  " << vec[i]->getRecipient().street << "\n";
        cout << "  " << vec[i]->getRecipient().city << ", " << vec[i]->getRecipient().state << " " << vec[i]->getRecipient().zip << "\n";
        double cost = vec[i]->calculateCost();
        cout << "Cost: $" << cost << "\n";
        grandTotal += cost;
    }

    cout << "\nTotal shipping cost: $" << grandTotal << "\n";

    for (auto ptr : vec) delete ptr;
    return 0;
}

