        if (!isdigit(c)) { cout << "ERROR\n"; return 0; }
    }
    for (char c : line) {
        if (!isdigit(c)) { cout << "ERROR\n"; return 0; }
    }

    if (area[0] == '0' || area[0] == '1') {
        cout << "ERROR\n";
        return 0;
    }

    if (area[1] != '0' && area[1] != '1') {
        cout << "ERROR\n";
        return 0;
    }

    if (exchange[0] == '0' || exchange[0] == '1') {
        cout << "ERROR\n";
        return 0;
    }

    cout << area << " " << exchange << " " << line << "\n";
    return 0;
}

#include <iostream>
#include <string>

using namespace std;

bool isDigit(char c) {
    return c >= '0' && c <= '9';
}

int main() {
    string line;
    if (!getline(cin, line)) {
        cout << "ERROR\n";
        return 0;
    }

    if (line.size() != 14) {
        cout << "ERROR\n";
        return 0;
    }

    // Check formatting characters
    if (line[0] != '(' || line[4] != ')' || line[5] != ' ' || line[9] != '-') {
        cout << "ERROR\n";
        return 0;
    }

    // Digits indices: 1, 2, 3 (area), 6, 7, 8 (exchange), 10, 11, 12, 13 (line)
    int digitIndices[] = {1, 2, 3, 6, 7, 8, 10, 11, 12, 13};
    for (int idx : digitIndices) {
        if (!isDigit(line[idx])) {
            cout << "ERROR\n";
            return 0;
        }
    }

    // Area code first digit cannot be 0 or 1
    if (line[1] == '0' || line[1] == '1') {
        cout << "ERROR\n";
        return 0;
    }

    // Area code middle digit must be 0 or 1
    if (line[2] != '0' && line[2] != '1') {
        cout << "ERROR\n";
        return 0;
    }

    // Exchange first digit cannot be 0 or 1
    if (line[6] == '0' || line[6] == '1') {
        cout << "ERROR\n";
        return 0;
    }

    string areaCode = line.substr(1, 3);
    string exchangeCode = line.substr(6, 3);
    string lineNumber = line.substr(10, 4);

    cout << areaCode << " " << exchangeCode << " " << lineNumber << "\n";
    return 0;
}

#include <iostream>
#include <string>
