class Point {
private:
    int xCoordinate;
    int yCoordinate;

public:
    Point(int x = 0, int y = 0) : xCoordinate(x), yCoordinate(y) {}

    friend std::istream& operator>>(std::istream& in, Point& p) {
        char ch1 = 0, ch2 = 0, ch3 = 0;
        int x = 0, y = 0;
        if (!(in >> ch1) || ch1 != '(') {
            in.setstate(std::ios_base::failbit);
            return in;
        }
        if (!(in >> x)) {
            return in;
        }
        if (!(in >> ch2) || ch2 != ',') {
            in.setstate(std::ios_base::failbit);
            return in;
        }
        if (!(in >> y)) {
            return in;
        }
        if (!(in >> ch3) || ch3 != ')') {
            in.setstate(std::ios_base::failbit);
            return in;
        }
        p.xCoordinate = x;
        p.yCoordinate = y;
        return in;
    }

    friend std::ostream& operator<<(std::ostream& out, const Point& p) {
        if (!out.fail()) {
            out << "(" << p.xCoordinate << ", " << p.yCoordinate << ")";
        }
        return out;
    }
};

