#include <iostream>
#include <string>
#include <sstream>

class Point {
private:
    int xCoordinate;
    int yCoordinate;

public:
    Point() : xCoordinate(0), yCoordinate(0) {}
    Point(int x, int y) : xCoordinate(x), yCoordinate(y) {}

    friend std::istream& operator>>(std::istream& is, Point& pt) {
        char openParen, comma, closeParen;
        int x, y;
        if (is >> openParen && openParen == '(' &&
            is >> x &&
            is >> comma && comma == ',' &&
            is >> y &&
            is >> closeParen && closeParen == ')') {
            pt.xCoordinate = x;
            pt.yCoordinate = y;
        } else {
            is.setstate(std::ios_base::failbit);
        }
        return is;
    }

    friend std::ostream& operator<<(std::ostream& os, const Point& pt) {
        if (!os.fail()) {
            os << '(' << pt.xCoordinate << ", " << pt.yCoordinate << ')';
        }
        return os;
    }
};

