#include <iostream>
#include <string>
#include <sstream>
#include <vector>

using namespace std;

void runExperimentGet(const string& S, int N, char delim) {
    stringstream ss(S);
    vector<char> buffer(N, '\0');

    ss.get(buffer.data(), N, delim);
    string bufStr(buffer.data());

    int nextChar = ss.peek();

    string remaining;
    if (ss) {
        string rem;
        getline(ss, rem, '\0');
        remaining = rem;
    }

    cout << "GET:\n";
    cout << "Buffer: \"" << bufStr << "\" (len = " << bufStr.length() << ")\n";
    cout << "Next char ASCII: " << (nextChar == EOF ? -1 : nextChar) << "\n";
    cout << "Remaining: \"" << remaining << "\"\n";
}

void runExperimentGetline(const string& S, int N, char delim) {
    stringstream ss(S);
    vector<char> buffer(N, '\0');

    ss.getline(buffer.data(), N, delim);
    string bufStr(buffer.data());

    int nextChar = ss.peek();

    string remaining;
    if (!ss.eof()) {
        string rem;
        getline(ss, rem, '\0');
        remaining = rem;
    }

    cout << "GETLINE:\n";
    cout << "Buffer: \"" << bufStr << "\" (len = " << bufStr.length() << ")\n";
    cout << "Next char ASCII: " << (nextChar == EOF ? -1 : nextChar) << "\n";
    cout << "Remaining: \"" << remaining << "\"\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    char delim;
    if (!(cin >> N >> delim)) return 0;
    string dummy;
    getline(cin, dummy); // consume newline

    string S;
    getline(cin, S);

    runExperimentGet(S, N, delim);
    runExperimentGetline(S, N, delim);

    return 0;
}

