using namespace std;

class Person {
private:
    string lastName;
    string firstName;
    int age;
public:
    Person() : lastName("unassigned"), firstName(""), age(0) {}

    void reset() {
        lastName = "unassigned";
        firstName = "";
        age = 0;
    }

    bool hasInfo() const {
        return lastName != "unassigned";
    }

    void setInfo(const string& ln, const string& fn, int a) {
        lastName = ln;
        firstName = fn;
        age = a;
    }

    void print(int id) const {
        cout << id << " " << lastName << " " 
             << (firstName.empty() ? "EMPTY" : firstName) 
             << " " << age << "\n";
    }
};

