    for (int k = 0; k < Q; ++k) {
        string op;
        cin >> op;
        if (op == "INSERT") {
            int id, age;
            string ln, fn;
            cin >> id >> ln >> fn >> age;
            db[id].setInfo(ln, fn, age);
        } else if (op == "UPDATE") {
            int id, age;
            string ln, fn;
            cin >> id >> ln >> fn >> age;
            if (!db[id].hasInfo()) {
                cout << "No info\n";
            } else {
                db[id].setInfo(ln, fn, age);
            }
