#include <iostream>
#include <string>
#include <sstream>
#include <cctype>

using namespace std;

class Complex {
private:
    long long real;
    long long imaginary;
    bool valid;

public:
    Complex(long long r = 0, long long i = 0, bool v = true) : real(r), imaginary(i), valid(v) {}

    bool isValid() const { return valid; }

    friend istream& operator>>(istream& is, Complex& c);
    friend ostream& operator<<(ostream& os, const Complex& c);
};

istream& operator>>(istream& is, Complex& c) {
    string line;
    if (!getline(is, line)) {
        return is;
    }

    // Parse line
    int n = line.size();
    int idx = 0;
    auto skipSpaces = [&]() {
        while (idx < n && isspace(line[idx])) idx++;
    };

    skipSpaces();
    if (idx >= n) {
        c.valid = false;
        is.setstate(ios::failbit);
        return is;
    }

    // Try to parse first component
    // Could be a number (real), or a number with 'i' (pure imaginary), or '+/-i'
    int sign1 = 1;
    if (line[idx] == '+') {
        sign1 = 1;
        idx++;
        skipSpaces();
    } else if (line[idx] == '-') {
        sign1 = -1;
        idx++;
        skipSpaces();
    }

    if (idx >= n) {
        c.valid = false;
        is.setstate(ios::failbit);
        return is;
    }

    // Check if it directly starts with 'i'
    if (line[idx] == 'i') {
        idx++;
        skipSpaces();
        if (idx == n) {
            c.real = 0;
            c.imaginary = sign1 * 1;
            c.valid = true;
            return is;
        } else {
            c.valid = false;
            is.setstate(ios::failbit);
            return is;
        }
    }

    if (!isdigit(line[idx])) {
        c.valid = false;
        is.setstate(ios::failbit);
        return is;
    }

    long long val1 = 0;
    while (idx < n && isdigit(line[idx])) {
        val1 = val1 * 10 + (line[idx] - '0');
        idx++;
    }
    val1 *= sign1;

    // Check if val1 is followed by 'i'
    skipSpaces();
    if (idx < n && line[idx] == 'i') {
        idx++;
        skipSpaces();
        if (idx == n) {
            c.real = 0;
            c.imaginary = val1;
            c.valid = true;
            return is;
        } else {
            c.valid = false;
            is.setstate(ios::failbit);
            return is;
        }
    }

    // val1 was a real number, now look for second part or end
    if (idx == n) {
        c.real = val1;
        c.imaginary = 0;
        c.valid = true;
        return is;
    }

    int sign2 = 0;
    if (line[idx] == '+') {
        sign2 = 1;
        idx++;
    } else if (line[idx] == '-') {
        sign2 = -1;
        idx++;
    } else {
        c.valid = false;
        is.setstate(ios::failbit);
        return is;
    }

    skipSpaces();
    if (idx >= n) {
        c.valid = false;
        is.setstate(ios::failbit);
        return is;
    }

    long long val2 = 1;
    if (line[idx] == 'i') {
        idx++;
    } else if (isdigit(line[idx])) {
        val2 = 0;
        while (idx < n && isdigit(line[idx])) {
            val2 = val2 * 10 + (line[idx] - '0');
            idx++;
        }
        skipSpaces();
        if (idx >= n || line[idx] != 'i') {
            c.valid = false;
            is.setstate(ios::failbit);
            return is;
        }
        idx++;
    } else {
        c.valid = false;
        is.setstate(ios::failbit);
        return is;
    }

    skipSpaces();
    if (idx == n) {
        c.real = val1;
        c.imaginary = sign2 * val2;
        c.valid = true;
    } else {
        c.valid = false;
        is.setstate(ios::failbit);
        return is;
    }

    return is;
}

ostream& operator<<(ostream& os, const Complex& c) {
    if (!c.valid) {
        os << "ERROR";
    } else {
        os << c.real;
        if (c.imaginary >= 0) {
            os << " + " << c.imaginary << "i";
        } else {
            os << " - " << -c.imaginary << "i";
        }
    }
    return os;
}

int main() {
    Complex c;
    while (cin >> c) {
        cout << c << "\n";
    }
    // If stream failed due to bad format, clear state to process subsequent lines if any
    while (cin.fail() && !cin.eof()) {
        cout << c << "\n";
        cin.clear();
    }
    return 0;
}

#include <iostream>
#include <string>
#include <regex>

using namespace std;

class Complex {
private:
    long long real;
    long long imaginary;
    bool valid;

public:
    Complex() : real(0), imaginary(0), valid(false) {}

    friend istream& operator>>(istream& in, Complex& c);
    friend ostream& operator<<(ostream& out, const Complex& c);
};

istream& operator>>(istream& in, Complex& c) {
    string s;
    if (!getline(in, s)) {
        return in;
    }

    // Regular expression for validating the complex input
    // Matches: whitespace* [+-]? digits whitespace* ( [+-] whitespace* (digits)? i )? whitespace*
    // or whitespace* [+-]? (digits)? i whitespace*
    static const regex full_regex(R"(^\s*([+-]?\s*\d+)\s*([+-])\s*(\d*)\s*i\s*$)");
    static const regex real_only_regex(R"(^\s*([+-]?\s*\d+)\s*$)");
    static const regex imag_only_regex(R"(^\s*([+-]?)\s*(\d*)\s*i\s*$)");

    auto clean_int = [](string str) -> long long {
        string res = "";
        for (char ch : str) if (!isspace(ch)) res += ch;
        return stoll(res);
    };

    smatch match;
    if (regex_match(s, match, full_regex)) {
        long long r = clean_int(match[1].str());
        string sign_str = match[2].str();
        string coeff_str = match[3].str();
        long long coeff = coeff_str.empty() ? 1 : clean_int(coeff_str);
        long long im = (sign_str == "-") ? -coeff : coeff;
        c.real = r;
        c.imaginary = im;
        c.valid = true;
    } else if (regex_match(s, match, real_only_regex)) {
        long long r = clean_int(match[1].str());
        c.real = r;
        c.imaginary = 0;
        c.valid = true;
    } else if (regex_match(s, match, imag_only_regex)) {
        string sign_str = match[1].str();
        string coeff_str = match[2].str();
        long long coeff = coeff_str.empty() ? 1 : clean_int(coeff_str);
        if (sign_str.find('-') != string::npos) coeff = -coeff;
        c.real = 0;
        c.imaginary = coeff;
        c.valid = true;
    } else {
        c.valid = false;
        in.setstate(ios::failbit);
    }

    return in;
}

ostream& operator<<(ostream& out, const Complex& c) {
    if (!c.valid) {
        out << "ERROR";
    } else {
        out << c.real;
        if (c.imaginary >= 0) {
            out << " + " << c.imaginary << "i";
        } else {
            out << " - " << -c.imaginary << "i";
        }
    }
    return out;
}

int main() {
    Complex c;
    while (!cin.eof()) {
        if (cin >> c) {
            cout << c << "\n";
        } else {
            if (cin.eof()) break;
            cout << c << "\n";
            cin.clear();
        }
    }
    return 0;
}

