using namespace std;

const vector<string> mapping = {
    "",    // 0
    "",    // 1
    "ABC", // 2
    "DEF", // 3
    "GHI", // 4
    "JKL", // 5
    "MNO", // 6
    "PRS", // 7
    "TUV", // 8
    "WXY"  // 9
};

void backtrack(const string& digits, int idx, string& current) {
    if (idx == 7) {
        cout << current << '\n';
        return;
    }
    int d = digits[idx] - '0';
    for (char c : mapping[d]) {
        current.push_back(c);
        backtrack(digits, idx + 1, current);
        current.pop_back();
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (cin >> s) {
        string current = "";
        backtrack(s, 0, current);
    }
    return 0;
}

