using namespace std;

string to_lower(const string& s) {
    string res = s;
    for (char &c : res) {
        c = tolower(static_cast<unsigned char>(c));
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    struct Keyword {
        int points;
        string original;
        string lower;
        long long count;
    };

    vector<Keyword> keywords(n);
    for (int i = 0; i < n; ++i) {
        cin >> keywords[i].points;
        string dummy;
        getline(cin, dummy); // read remaining whitespace on the line
        // Trim leading spaces from dummy if any, or read the rest of line
        while (!dummy.empty() && dummy[0] == ' ') {
            dummy.erase(dummy.begin());
        }
        keywords[i].original = dummy;
        keywords[i].lower = to_lower(dummy);
        keywords[i].count = 0;
    }

    int m;
    if (!(cin >> m)) return 0;
    string dummy;
    getline(cin, dummy); // finish the line containing m

    for (int line_idx = 0; line_idx < m; ++line_idx) {
        string line;
        getline(cin, line);
        string line_lower = to_lower(line);

        for (auto& kw : keywords) {
            if (kw.lower.empty()) continue;
            size_t pos = 0;
            while ((pos = line_lower.find(kw.lower, pos)) != string::npos) {
                kw.count++;
                pos += 1; // allow overlapping
            }
        }
    }

    long long total_score = 0;
    for (const auto& kw : keywords) {
        if (kw.count > 0) {
            long long pts = kw.count * kw.points;
            total_score += pts;
            cout << kw.original << ": " << kw.count << " lan, " << pts << " diem\n";
        }
    }
    cout << "Tong diem: " << total_score << "\n";

    return 0;
}

