int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<pair<int, string>> terms(n);
    for (int i = 0; i < n; ++i) {
        cin >> terms[i].first;
        string phrase;
        getline(cin, phrase);
        size_t start = phrase.find_first_not_of(" \t");
        if (start != string::npos) {
            phrase = phrase.substr(start);
        } else {
            phrase = "";
        }
        terms[i].second = phrase;
    }

    int m;
    if (!(cin >> m)) return 0;
    string emptyLine;
    getline(cin, emptyLine);

    vector<string> email_lines(m);
    for (int i = 0; i < m; ++i) {
        getline(cin, email_lines[i]);
        for (char &c : email_lines[i]) {
            c = tolower((unsigned char)c);
        }
    }

    long long grand_total = 0;
    for (int i = 0; i < n; ++i) {
        string pat = terms[i].second;
        string pat_low = pat;
        for (char &c : pat_low) {
            c = tolower((unsigned char)c);
        }

