        if (!pat_low.empty()) {
            for (const auto& line : email_lines) {
                if (pat_low.size() > line.size()) continue;
                for (size_t pos = 0; pos + pat_low.size() <= line.size(); ++pos) {
                    bool match = true;
                    for (size_t k = 0; k < pat_low.size(); ++k) {
                        if (line[pos + k] != pat_low[k]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        count++;
                    }
                }
            }
