// Hàm khuôn mẫu kiểm tra vector đối xứng như yêu cầu bài học
template <typename T>
bool palindrome(const std::vector<T>& v) {
    if (v.empty()) return true;
    size_t left = 0;
    size_t right = v.size() - 1;
    while (left < right) {
        if (v[left] != v[right]) {
            return false;
        }
        ++left;
        --right;
    }
    return true;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) {
        return 0;
    }

    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    if (palindrome(a)) {
        std::cout << "true\n";
    } else {
        std::cout << "false\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

template <typename T>
bool palindrome(const std::vector<T>& vec) {
    return std::equal(vec.begin(), vec.begin() + vec.size() / 2, vec.rbegin());
}

