using namespace std;

bool isPrime(long long n) {
    if (n < 2) return false;
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n;
    if (!(cin >> n)) return 0;

    if (isPrime(n)) {
        cout << n << " is prime\n";
    } else {
        vector<long long> factors;
        long long temp = n;
        for (long long d = 2; d * d <= temp; ++d) {
            while (temp % d == 0) {
                factors.push_back(d);
                temp /= d;
            }
        }
        if (temp > 1) {
            factors.push_back(temp);
        }

        cout << "The unique prime factorization of " << n << " is: ";
        for (size_t i = 0; i < factors.size(); ++i) {
            if (i > 0) cout << " * ";
            cout << factors[i];
        }
        cout << "\n";
    }
    return 0;
}

