    long long n;
    if (!(cin >> n)) return 0;

    vector<long long> factors;
    long long temp = n;

    // Tách thừa số 2
    while (temp % 2 == 0) {
        factors.push_back(2);
        temp /= 2;
    }

    // Tách các thừa số lẻ từ 3
    for (long long d = 3; d * d <= temp; d += 2) {
        while (temp % d == 0) {
            factors.push_back(d);
            temp /= d;
        }
    }
    if (temp > 1) {
        factors.push_back(temp);
    }

    if (factors.size() == 1) {
        cout << n << " is prime\n";
    } else {
        cout << "The unique prime factorization of " << n << " is: ";
        for (size_t i = 0; i < factors.size(); ++i) {
            cout << (i == 0 ? "" : " * ") << factors[i];
        }
        cout << "\n";
    }

    return 0;
}

