struct Tracer {
    string name;
    Tracer(string n) : name(n) {}
    ~Tracer() {
        cout << "Destroy " << name << "\n";
    }
};

int N, K, H;
string M;
vector<string> names;

void call_func(int level) {
    cout << "Enter " << names[level - 1] << "\n";
    Tracer local_var(names[level - 1]);

    if (level == K) {
        if (H == 1) {
            try {
                throw string(M);
            } catch (const string& e) {
                cout << "Handled at " << names[level - 1] << ": " << e << "\n";
            }
        } else {
            throw string(M);
        }
    } else {
        call_func(level + 1);
    }

    cout << "Exit " << names[level - 1] << "\n";
}

