// Custom stack implementation
template <typename T>
class MyStack {
private:
    std::vector<T> data;
public:
    void push(const T& val) {
        data.push_back(val);
    }
    void pop() {
        if (!data.empty()) {
            data.pop_back();
        }
    }
    T top() const {
        return data.back();
    }
    bool empty() const {
        return data.empty();
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

