        for (size_t i = 0; i < line.length(); ++i) {
            s.push(line[i]);
        }
        while (!s.empty()) {
            std::cout << s.top();
            s.pop();
        }
        std::cout << "\n";
    } else {
        std::cout << "\n";
    }
    return 0;
}

#include <iostream>

using namespace std;

struct Node {
    char data;
    Node* next;
    Node(char c) : data(c), next(nullptr) {}
};

class LinkedList {
public:
    Node* head;
    Node* tail;
    LinkedList() : head(nullptr), tail(nullptr) {}

    void push_back(char c) {
        Node* newNode = new Node(c);
        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    void push_front(char c) {
        Node* newNode = new Node(c);
        newNode->next = head;
        head = newNode;
        if (!tail) tail = newNode;
    }

    ~LinkedList() {
        Node* curr = head;
        while (curr) {
            Node* tmp = curr->next;
            delete curr;
            curr = tmp;
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    LinkedList list1;
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        list1.push_back(c);
    }

    LinkedList list2;
    Node* curr = list1.head;
    while (curr) {
        list2.push_front(curr->data);
        curr = curr->next;
    }

    Node* out = list2.head;
    bool first = true;
    while (out) {
        if (!first) cout << ' ';
        cout << out->data;
        first = false;
        out = out->next;
    }
    cout << '\n';

    return 0;
}

