using namespace std;

// Merge sort to simulate ordered list / ordered collection efficiently
void mergeSort(vector<long long>& arr, int l, int r) {
    if (l >= r) return;
    int mid = l + (r - l) / 2;
    mergeSort(arr, l, mid);
    mergeSort(arr, mid + 1, r);

    vector<long long> temp;
    int i = l, j = mid + 1;
    while (i <= mid && j <= r) {
        if (arr[i] <= arr[j]) {
            temp.push_back(arr[i++]);
        } else {
            temp.push_back(arr[j++]);
        }
    }
    while (i <= mid) temp.push_back(arr[i++]);
    while (j <= r) temp.push_back(arr[j++]);
    for (int k = 0; k < (int)temp.size(); ++k) {
        arr[l + k] = temp[k];
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> list(n);
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        cin >> list[i];
        total += list[i];
    }

    mergeSort(list, 0, n - 1);

    for (int i = 0; i < n; ++i) {
        cout << list[i] << (i == n - 1 ? "" : " ");
    }
    cout << "\n";
    cout << total << "\n";
    double average = (double)total / (double)n;
    cout << fixed << setprecision(2) << average << "\n";

    return 0;
}

#include <iostream>
#include <vector>

void mergeLists(const std::vector<int>& a, const std::vector<int>& b, std::vector<int>& result) {
    result.clear();
    result.reserve(a.size() + b.size());
    size_t i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] <= b[j]) {
            result.push_back(a[i]);
            ++i;
        } else {
            result.push_back(b[j]);
            ++j;
        }
    }
    while (i < a.size()) {
        result.push_back(a[i++]);
    }
    while (j < b.size()) {
        result.push_back(b[j++]);
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) return 0;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    int m;
    if (!(std::cin >> m)) return 0;
    std::vector<int> b(m);
    for (int j = 0; j < m; ++j) {
        std::cin >> b[j];
    }

    std::vector<int> merged;
    mergeLists(a, b, merged);

    for (size_t i = 0; i < merged.size(); ++i) {
        std::cout << merged[i] << (i + 1 == merged.size() ? "" : " ");
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>

struct Node {
    int val;
    Node* next;
    Node(int v) : val(v), next(nullptr) {}
};

void append(Node*& head, Node*& tail, int val) {
    Node* newNode = new Node(val);
    if (!head) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
}

Node* merge(Node* l1, Node* l2) {
    Node dummy(0);
    Node* tail = &dummy;
    while (l1 && l2) {
        if (l1->val <= l2->val) {
            tail->next = l1;
            l1 = l1->next;
        } else {
            tail->next = l2;
            l2 = l2->next;
        }
        tail = tail->next;
    }
    if (l1) tail->next = l1;
    if (l2) tail->next = l2;
    return dummy.next;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n)) return 0;
    Node* head1 = nullptr;
    Node* tail1 = nullptr;
    for (int i = 0; i < n; ++i) {
        int x;
        std::cin >> x;
        append(head1, tail1, x);
    }

    int m;
    if (!(std::cin >> m)) return 0;
    Node* head2 = nullptr;
    Node* tail2 = nullptr;
    for (int i = 0; i < m; ++i) {
        int x;
        std::cin >> x;
        append(head2, tail2, x);
    }

    Node* res = merge(head1, head2);
    bool first = true;
    while (res) {
        if (!first) std::cout << ' ';
        std::cout << res->val;
        first = false;
        Node* tmp = res;
        res = res->next;
        delete tmp;
    }
    std::cout << '\n';

    return 0;
}

