class CharList {
public:
    struct Node {
        char val;
        Node* next;
        Node(char v) : val(v), next(nullptr) {}
    };

    Node* head = nullptr;
    Node* tail = nullptr;

    void append(char c) {
        Node* p = new Node(c);
        if (!head) head = tail = p;
        else {
            tail->next = p;
            tail = p;
        }
    }
};

void concatenate(CharList& a, CharList& b) {
    if (a.tail != nullptr) {
        a.tail->next = b.head;
        if (b.tail != nullptr) {
            a.tail = b.tail;
        }
    } else {
        a.head = b.head;
        a.tail = b.tail;
    }
    b.head = b.tail = nullptr;
}

