long long computeOp(long long op1, const std::string& op, long long op2) {
    if (op == "+") return op1 + op2;
    if (op == "-") return op1 - op2;
    if (op == "*") return op1 * op2;
    if (op == "/") return op1 / op2;
    if (op == "%") return op1 % op2;
    if (op == "^") {
        long long ans = 1;
        for (long long i = 0; i < op2; ++i) ans *= op1;
        return ans;
    }
    return 0;
}

