struct StackNode {
    long long data;
    StackNode* next;
    StackNode(long long val, StackNode* n = nullptr) : data(val), next(n) {}
};

class CustomStack {
private:
    StackNode* topNode;
public:
    CustomStack() : topNode(nullptr) {}
    ~CustomStack() {
        while (!isEmpty()) pop();
    }
    void push(long long val) {
        topNode = new StackNode(val, topNode);
    }
    long long pop() {
        if (isEmpty()) return 0;
        StackNode* temp = topNode;
        long long val = temp->data;
        topNode = topNode->next;
        delete temp;
        return val;
    }
    bool isEmpty() const {
        return topNode == nullptr;
    }
    long long top() const {
        return topNode ? topNode->data : 0;
    }
};

long long calc(long long op1, char op, long long op2) {
    if (op == '+') return op1 + op2;
    if (op == '-') return op1 - op2;
    if (op == '*') return op1 * op2;
    if (op == '/') return op1 / op2;
    if (op == '%') return op1 % op2;
    if (op == '^') {
        long long ans = 1;
        for (long long i = 0; i < op2; ++i) {
            ans *= op1;
        }
        return ans;
    }
    return 0;
}

