        char ch = line[i];
        if (ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n') continue;
        if (ch >= '0' && ch <= '9') {
            s.push(ch - '0');
        } else {
            long long x = s.pop();
            long long y = s.pop();
            s.push(calc(y, ch, x));
        }
    }

    std::cout << s.top() << "\n";
    return 0;
}

