using namespace std;

int getPrecedence(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/' || op == '%') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}

bool isOp(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '^';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!getline(cin, s)) return 0;

    string filtered = "";
    for (char c : s) {
        if (!isspace(static_cast<unsigned char>(c))) {
            filtered += c;
        }
    }

    filtered += ')';
    vector<char> st;
    st.push_back('(');

    vector<char> postfix;

    for (char c : filtered) {
        if (isdigit(static_cast<unsigned char>(c))) {
            postfix.push_back(c);
        } else if (c == '(') {
            st.push_back(c);
        } else if (isOp(c)) {
            while (!st.empty() && isOp(st.back()) && getPrecedence(st.back()) >= getPrecedence(c)) {
                postfix.push_back(st.back());
                st.pop_back();
            }
            st.push_back(c);
        } else if (c == ')') {
            while (!st.empty() && st.back() != '(') {
                postfix.push_back(st.back());
                st.pop_back();
            }
            if (!st.empty() && st.back() == '(') {
                st.pop_back();
            }
        }
    }

    for (size_t i = 0; i < postfix.size(); ++i) {
        cout << postfix[i] << (i + 1 == postfix.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}

