using namespace std;

struct StackNode {
    char data;
    StackNode* next;
    StackNode(char val, StackNode* nxt = nullptr) : data(val), next(nxt) {}
};

class CustomStack {
private:
    StackNode* head;
public:
    CustomStack() : head(nullptr) {}
    ~CustomStack() {
        while (head) {
            StackNode* tmp = head;
            head = head->next;
            delete tmp;
        }
    }
    void push(char val) {
        head = new StackNode(val, head);
    }
    void pop() {
        if (head) {
            StackNode* tmp = head;
            head = head->next;
            delete tmp;
        }
    }
    char top() const {
        return head ? head->data : '\0';
    }
    bool empty() const {
        return head == nullptr;
    }
};

int precedenceLevel(char op) {
    switch (op) {
        case '^': return 3;
        case '*':
        case '/':
        case '%': return 2;
        case '+':
        case '-': return 1;
        default: return 0;
    }
}

bool isOperatorChar(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '^';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string line;
    if (!getline(cin, line)) return 0;

    string infix = "";
    for (char ch : line) {
        if (!isspace(static_cast<unsigned char>(ch))) {
            infix += ch;
        }
    }
    infix += ')';

    CustomStack st;
    st.push('(');

    string postfix = "";
    for (char ch : infix) {
        if (isdigit(static_cast<unsigned char>(ch))) {
            if (!postfix.empty()) postfix += ' ';
            postfix += ch;
        } else if (ch == '(') {
            st.push(ch);
        } else if (isOperatorChar(ch)) {
            while (!st.empty() && isOperatorChar(st.top()) && precedenceLevel(st.top()) >= precedenceLevel(ch)) {
                if (!postfix.empty()) postfix += ' ';
                postfix += st.top();
                st.pop();
            }
            st.push(ch);
        } else if (ch == ')') {
            while (!st.empty() && st.top() != '(') {
                if (!postfix.empty()) postfix += ' ';
                postfix += st.top();
                st.pop();
            }
            if (!st.empty() && st.top() == '(') {
                st.pop();
            }
        }
    }

    cout << postfix << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>

using namespace std;

struct Customer {
    long long t;
    long long s;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Customer> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i].t >> a[i].s;
    }

    long long max_wait = 0;
    long long current_free_time = 0;
    vector<long long> start_time(n);

    for (int i = 0; i < n; ++i) {
        long long start = max(a[i].t, current_free_time);
        start_time[i] = start;
        long long wait = start - a[i].t;
        if (wait > max_wait) {
            max_wait = wait;
        }
        current_free_time = start + a[i].s;
    }

    // Tinh do dai hang doi toi da
    // Khach i o trong hang doi trong khoang thoi gian [a[i].t, start_time[i]).
    // Neu a[i].t == start_time[i], khach khong phai cho trong hang doi.
    // Ta co the dung con tro hai dau hoac min-heap de dem so luong khach dang cho.
    queue<long long> q; // luu start_time cua nhung nguoi dang cho
    int max_queue_len = 0;

    for (int i = 0; i < n; ++i) {
        // Cac khach co start_time <= a[i].t da duoc phuc vu (roi khoi hang doi)
        while (!q.empty() && q.front() <= a[i].t) {
            q.pop();
        }
        // Khach i chi vao hang doi neu ho khong duoc phuc vu ngay
        if (start_time[i] > a[i].t) {
            q.push(start_time[i]);
        }
        if ((int)q.size() > max_queue_len) {
            max_queue_len = q.size();
        }
    }

    cout << max_wait << " " << max_queue_len << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> t(n), s(n);
    for (int i = 0; i < n; ++i) {
        cin >> t[i] >> s[i];
    }

    long long max_wait = 0;
    long long finish_prev = 0;
    vector<long long> start(n);

    for (int i = 0; i < n; ++i) {
        long long cur_start = max(t[i], finish_prev);
        start[i] = cur_start;
        long long wait = cur_start - t[i];
        if (wait > max_wait) {
            max_wait = wait;
        }
        finish_prev = cur_start + s[i];
    }

    // Do dai hang doi: tai thoi diem t[i], khach i gia nhap hang doi neu start[i] > t[i]
    // Nhung nguoi truoc do roi hang doi khi start[j] <= t[i]
    int max_q = 0;
    int pop_ptr = 0;
    int cur_q = 0;

    for (int i = 0; i < n; ++i) {
        while (pop_ptr < i) {
            if (start[pop_ptr] <= t[i]) {
                if (start[pop_ptr] > t[pop_ptr]) {
                    cur_q--;
                }
                pop_ptr++;
            } else {
                break;
            }
        }
        if (start[i] > t[i]) {
            cur_q++;
        }
        if (cur_q > max_q) {
            max_q = cur_q;
        }
    }

    cout << max_wait << " " << max_q << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

struct TreeNode {
    long long val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(long long v) : val(v), left(nullptr), right(nullptr) {}
};

TreeNode* insertNode(TreeNode* root, long long val) {
    if (root == nullptr) {
        return new TreeNode(val);
    }
    if (val < root->val) {
        root->left = insertNode(root->left, val);
    } else {
        root->right = insertNode(root->right, val);
    }
    return root;
}

void preorder(TreeNode* root, vector<long long>& res) {
    if (!root) return;
    res.push_back(root->val);
    preorder(root->left, res);
    preorder(root->right, res);
}

void inorder(TreeNode* root, vector<long long>& res) {
    if (!root) return;
    inorder(root->left, res);
    res.push_back(root->val);
    inorder(root->right, res);
}

void postorder(TreeNode* root, vector<long long>& res) {
    if (!root) return;
    postorder(root->left, res);
    postorder(root->right, res);
    res.push_back(root->val);
}

void printVec(const vector<long long>& v) {
    for (size_t i = 0; i < v.size(); ++i) {
        if (i > 0) cout << " ";
        cout << v[i];
    }
    cout << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    TreeNode* root = nullptr;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        root = insertNode(root, x);
    }
    vector<long long> pre, in, post;
    preorder(root, pre);
    inorder(root, in);
    postorder(root, post);
    printVec(pre);
    printVec(in);
    printVec(post);
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

class BST {
private:
    struct Node {
        long long data;
        Node* left;
        Node* right;
        Node(long long d) : data(d), left(nullptr), right(nullptr) {}
    };
    Node* root = nullptr;

    void insertHelper(Node*& node, long long val) {
        if (node == nullptr) {
            node = new Node(val);
            return;
        }
        if (val < node->data) {
            insertHelper(node->left, val);
        } else {
            insertHelper(node->right, val);
        }
    }

    void preHelper(Node* node, vector<long long>& out) const {
        if (!node) return;
        out.push_back(node->data);
        preHelper(node->left, out);
        preHelper(node->right, out);
    }

    void inHelper(Node* node, vector<long long>& out) const {
        if (!node) return;
        inHelper(node->left, out);
        out.push_back(node->data);
        inHelper(node->right, out);
    }

    void postHelper(Node* node, vector<long long>& out) const {
        if (!node) return;
        postHelper(node->left, out);
        postHelper(node->right, out);
        out.push_back(node->data);
    }

public:
    void insert(long long val) {
        insertHelper(root, val);
    }

    vector<long long> getPreorder() const {
        vector<long long> res;
        preHelper(root, res);
        return res;
    }

    vector<long long> getInorder() const {
        vector<long long> res;
        inHelper(root, res);
        return res;
    }

    vector<long long> getPostorder() const {
        vector<long long> res;
        postHelper(root, res);
        return res;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    BST tree;
    for (int i = 0; i < n; ++i) {
        long long val;
        cin >> val;
        tree.insert(val);
    }
    auto printSeq = [](const vector<long long>& seq) {
        for (size_t i = 0; i < seq.size(); ++i) {
            if (i > 0) cout << " ";
            cout << seq[i];
        }
        cout << "\n";
    };
    printSeq(tree.getPreorder());
    printSeq(tree.getInorder());
    printSeq(tree.getPostorder());
    return 0;
}

