        // Khi in ngược từ cuối về đầu, kết quả chính là dãy được sắp xếp giảm dần.
        std::sort(nums.rbegin(), nums.rend());
        for (int i = 0; i < n; ++i) {
            if (i > 0) std::cout << ' ';
            std::cout << nums[i];
        }
        std::cout << '\n';
    }
    return 0;
}

#include <iostream>
