using namespace std;

struct TreeNode {
    string val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(string v) : val(v), left(nullptr), right(nullptr) {}
};

class BST {
private:
    TreeNode* root;

    TreeNode* insert(TreeNode* node, const string& val) {
        if (!node) {
            return new TreeNode(val);
        }
        if (val < node->val) {
            node->left = insert(node->left, val);
        } else if (val > node->val) {
            node->right = insert(node->right, val);
        }
        return node;
    }

    void preorder(TreeNode* node, vector<string>& res) const {
        if (!node) return;
        res.push_back(node->val);
        preorder(node->left, res);
        preorder(node->right, res);
    }

    void inorder(TreeNode* node, vector<string>& res) const {
        if (!node) return;
        inorder(node->left, res);
        res.push_back(node->val);
        inorder(node->right, res);
    }

    void postorder(TreeNode* node, vector<string>& res) const {
        if (!node) return;
        postorder(node->left, res);
        postorder(node->right, res);
        res.push_back(node->val);
    }

    void clear(TreeNode* node) {
        if (!node) return;
        clear(node->left);
        clear(node->right);
        delete node;
    }

public:
    BST() : root(nullptr) {}
    ~BST() { clear(root); }

    void insert(const string& val) {
        root = insert(root, val);
    }

    vector<string> getPreorder() const {
        vector<string> res;
        preorder(root, res);
        return res;
    }

    vector<string> getInorder() const {
        vector<string> res;
        inorder(root, res);
        return res;
    }

    vector<string> getPostorder() const {
        vector<string> res;
        postorder(root, res);
        return res;
    }
};

void printTraversal(const string& label, const vector<string>& words) {
    cout << label << ":";
    for (const auto& w : words) {
        cout << " " << w;
    }
    cout << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string line;
    if (getline(cin, line)) {
        stringstream ss(line);
        string word;
        BST tree;
        while (ss >> word) {
            tree.insert(word);
        }
        printTraversal("Preorder", tree.getPreorder());
        printTraversal("Inorder", tree.getInorder());
        printTraversal("Postorder", tree.getPostorder());
    } else {
        cout << "Preorder:\n";
        cout << "Inorder:\n";
        cout << "Postorder:\n";
    }
    return 0;
}

