#include <iostream>
#include <vector>

class LinkedList {
public:
    struct Node {
        long long data;
        Node* next;
        Node(long long val) : data(val), next(nullptr) {}
    };

    Node* head;

    LinkedList() : head(nullptr) {}

    void append(long long val) {
        Node* newNode = new Node(val);
        if (!head) {
            head = newNode;
            return;
        }
        Node* cur = head;
        while (cur->next) {
            cur = cur->next;
        }
        cur->next = newNode;
    }

    // De quy tim kiem ListNode*
    Node* searchList(Node* cur, long long val) const {
        if (!cur) return nullptr;
        if (cur->data == val) return cur;
        return searchList(cur->next, val);
    }

    int searchIndex(Node* cur, long long val, int depth) const {
        if (!cur) return -1;
        if (cur->data == val) return depth;
        return searchIndex(cur->next, val, depth + 1);
    }

    ~LinkedList() {
        Node* cur = head;
        while (cur) {
            Node* nxt = cur->next;
            delete cur;
            cur = nxt;
        }
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

