using namespace std;

struct Node {
    long long key;
    Node* left;
    Node* right;
    Node(long long k) : key(k), left(nullptr), right(nullptr) {}
};

void insertNode(Node*& root, long long val) {
    Node** cur = &root;
    while (*cur != nullptr) {
        if (val < (*cur)->key) {
            cur = &((*cur)->left);
        } else if (val > (*cur)->key) {
            cur = &((*cur)->right);
        } else {
            return;
        }
    }
    *cur = new Node(val);
}

Node* binaryTreeSearch(Node* root, long long key) {
    if (root == nullptr || root->key == key) {
        return root;
    }
    if (key < root->key) {
        return binaryTreeSearch(root->left, key);
    }
    return binaryTreeSearch(root->right, key);
}

