#include <bits/stdc++.h>
using namespace std;

struct Node {
    int data;
    Node *left = nullptr, *right = nullptr;
    Node(int val) : data(val) {}
};

class BST {
public:
    Node* root = nullptr;

    void insert(int val) {
        if (!root) {
            root = new Node(val);
            return;
        }
        Node* cur = root;
        while (true) {
            if (val == cur->data) {
                return;
            } else if (val < cur->data) {
                if (!cur->left) {
                    cur->left = new Node(val);
                    return;
                }
                cur = cur->left;
            } else {
                if (!cur->right) {
                    cur->right = new Node(val);
                    return;
                }
                cur = cur->right;
            }
        }
    }

    vector<int> levelOrder() {
        vector<int> res;
        if (!root) return res;
        queue<Node*> q;
        q.push(root);
        while (!q.empty()) {
            Node* u = q.front();
            q.pop();
            res.push_back(u->data);
            if (u->left) q.push(u->left);
            if (u->right) q.push(u->right);
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (cin >> n) {
        BST tree;
        for (int i = 0; i < n; ++i) {
            int x;
            cin >> x;
            tree.insert(x);
        }
        vector<int> ans = tree.levelOrder();
        for (size_t i = 0; i < ans.size(); ++i) {
