template <typename T>
class Array {
private:
    size_t size;
    T* ptr;
public:
    explicit Array(size_t arraySize = 0) : size(arraySize), ptr(arraySize ? new T[arraySize] : nullptr) {}

    Array(const Array& other) : size(other.size), ptr(other.size ? new T[other.size] : nullptr) {
        for (size_t i = 0; i < size; ++i) ptr[i] = other.ptr[i];
    }

    ~Array() { delete[] ptr; }

    Array& operator=(const Array& other) {
        if (this != &other) {
            delete[] ptr;
            size = other.size;
            ptr = size ? new T[size] : nullptr;
            for (size_t i = 0; i < size; ++i) ptr[i] = other.ptr[i];
        }
        return *this;
    }

    bool operator==(const Array& other) const {
        if (size != other.size) return false;
        for (size_t i = 0; i < size; ++i) {
            if (ptr[i] != other.ptr[i]) return false;
        }
        return true;
    }

    bool operator!=(const Array& other) const {
        return !(*this == other);
    }

    size_t getSize() const { return size; }

    T& operator[](size_t index) { return ptr[index]; }
    const T& operator[](size_t index) const { return ptr[index]; }
};

template <typename T>
void process() {
    int n1, n2;
    if (!(std::cin >> n1)) return;
    Array<T> a(n1);
    for (int i = 0; i < n1; ++i) {
        std::cin >> a[i];
    }

    if (!(std::cin >> n2)) return;
    Array<T> b(n2);
    for (int i = 0; i < n2; ++i) {
        std::cin >> b[i];
    }

    if (a == b) {
        std::cout << "EQUAL\n";
    } else {
        std::cout << "NOT EQUAL\n";
    }

    a = b;

    int q;
    if (!(std::cin >> q)) return;
    for (int k = 0; k < q; ++k) {
        int idx;
        std::cin >> idx;
        if (idx >= 0 && static_cast<size_t>(idx) < a.getSize()) {
            std::cout << a[idx] << "\n";
        } else {
            std::cout << "OUT OF RANGE\n";
        }
    }

    std::cout << a.getSize();
    for (size_t i = 0; i < a.getSize(); ++i) {
        std::cout << " " << a[i];
    }
    std::cout << "\n";
}

