    Node* left = nullptr;
    Node* right = nullptr;
    Node(long long d) : data(d) {}
};

void insertNode(Node*& root, long long val) {
    if (root == nullptr) {
        root = new Node(val);
        return;
    }
    Node* curr = root;
    while (true) {
        if (val < curr->data) {
            if (curr->left == nullptr) {
                curr->left = new Node(val);
                break;
            } else {
                curr = curr->left;
            }
        } else if (val > curr->data) {
            if (curr->right == nullptr) {
                curr->right = new Node(val);
                break;
            } else {
                curr = curr->right;
            }
        } else {
            break; // Duplicate value, skip
        }
    }
