struct Node {
    int val;
    Node* next;
    Node(int v) : val(v), next(nullptr) {}
};

class LinkedList {
private:
    Node* head;
    int size;
public:
    LinkedList() : head(nullptr), size(0) {}

    ~LinkedList() {
        Node* curr = head;
        while (curr) {
            Node* tmp = curr->next;
            delete curr;
            curr = tmp;
        }
    }

    void insertAt(long long index, int value) {
        if (index < 0 || index > size) return;
        Node* newNode = new Node(value);
        if (index == 0) {
            newNode->next = head;
            head = newNode;
        } else {
            Node* curr = head;
            for (int i = 0; i < index - 1; ++i) {
                curr = curr->next;
            }
            newNode->next = curr->next;
            curr->next = newNode;
        }
        size++;
    }

    void deleteAt(long long index) {
        if (index < 0 || index >= size) return;
        if (index == 0) {
            Node* tmp = head;
            head = head->next;
            delete tmp;
        } else {
            Node* curr = head;
            for (int i = 0; i < index - 1; ++i) {
                curr = curr->next;
            }
            Node* tmp = curr->next;
            curr->next = tmp->next;
            delete tmp;
        }
        size--;
    }

    void print() {
        if (size == 0) {
            cout << "EMPTY\n";
            return;
        }
        Node* curr = head;
        bool first = true;
        while (curr) {
            if (!first) cout << " ";
            cout << curr->val;
            first = false;
            curr = curr->next;
        }
        cout << "\n";
    }
};

