void bucketSort(vector<long long>& arr) {
    if (arr.empty()) return;
    long long maxVal = 0;
    for (long long x : arr) {
        if (x > maxVal) maxVal = x;
    }

    long long exp = 1;
    while (maxVal / exp > 0 || (exp == 1 && maxVal == 0)) {
        vector<vector<long long>> buckets(10);
        for (long long x : arr) {
            int digit = (x / exp) % 10;
            buckets[digit].push_back(x);
        }

        int idx = 0;
        for (int d = 0; d < 10; ++d) {
            for (long long x : buckets[d]) {
                arr[idx++] = x;
            }
        }

        if (maxVal / exp == 0) break;
        exp *= 10;
    }
}

