// Hoare-style partition with pivot
void quickSortHelper(vector<int>& a, int left, int right) {
    if (left >= right) return;
    int mid = left + (right - left) / 2;
    int pivot = a[mid];
    int i = left, j = right;
    while (i <= j) {
        while (a[i] < pivot) i++;
        while (a[j] > pivot) j--;
        if (i <= j) {
            swap(a[i], a[j]);
            i++;
            j--;
        }
    }
    if (left < j) quickSortHelper(a, left, j);
    if (i < right) quickSortHelper(a, i, right);
}

