int recursiveBinarySearch(const vector<int>& a, int key, int low, int high) {
    if (low > high) {
        return -1;
    }
    int mid = low + (high - low) / 2;
    if (a[mid] == key) {
        return mid;
    } else if (a[mid] > key) {
        return recursiveBinarySearch(a, key, low, mid - 1);
    } else {
        return recursiveBinarySearch(a, key, mid + 1, high);
    }
}

