#include <iostream>
#include <vector>

using namespace std;

struct Node {
    int key;
    Node* left;
    Node* right;
    Node(int v) : key(v), left(nullptr), right(nullptr) {}
};

Node* insertNode(Node* root, int val) {
    if (!root) return new Node(val);
    if (val < root->key) root->left = insertNode(root->left, val);
    else if (val > root->key) root->right = insertNode(root->right, val);
    return root;
}

bool deleteNode(Node*& root, int val) {
    Node** curr = &root;
    while (*curr && (*curr)->key != val) {
        if (val < (*curr)->key) curr = &((*curr)->left);
        else curr = &((*curr)->right);
    }
    if (!*curr) return false;

    Node* toDelete = *curr;
    if (!toDelete->left && !toDelete->right) {
        *curr = nullptr;
        delete toDelete;
    } else if (!toDelete->left) {
        *curr = toDelete->right;
        delete toDelete;
    } else if (!toDelete->right) {
        *curr = toDelete->left;
        delete toDelete;
    } else {
        // Two children: replacement is the maximum node in the left subtree
        Node** repParent = &(toDelete->left);
        while ((*repParent)->right) {
            repParent = &((*repParent)->right);
        }
        Node* rep = *repParent;
        *repParent = rep->left;

        rep->left = toDelete->left;
        rep->right = toDelete->right;
        *curr = rep;
        delete toDelete;
    }
    return true;
}

void getInorder(Node* root, vector<int>& res) {
    if (!root) return;
    getInorder(root->left, res);
    res.push_back(root->key);
    getInorder(root->right, res);
}

void getPreorder(Node* root, vector<int>& res) {
    if (!root) return;
    res.push_back(root->key);
    getPreorder(root->left, res);
    getPreorder(root->right, res);
}

void getPostorder(Node* root, vector<int>& res) {
    if (!root) return;
    getPostorder(root->left, res);
    getPostorder(root->right, res);
    res.push_back(root->key);
}

void printTraversal(const string& label, const vector<int>& v) {
    cout << label;
    for (size_t i = 0; i < v.size(); ++i) {
        cout << " " << v[i];
    }
    cout << "\n";
}

