            } else {
                cout << v << " not found\n";
            }
        }
    }

    vector<int> inOrderRes, preOrderRes, postOrderRes;
    getInorder(root, inOrderRes);
    getPreorder(root, preOrderRes);
    getPostorder(root, postOrderRes);

    printTraversal("Inorder:", inOrderRes);
    printTraversal("Preorder:", preOrderRes);
    printTraversal("Postorder:", postOrderRes);

