#include <iostream>
#include <vector>

using namespace std;

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

void bstInsert(TreeNode*& root, int key) {
    TreeNode** cur = &root;
    while (*cur) {
        if (key < (*cur)->val) {
            cur = &((*cur)->left);
        } else if (key > (*cur)->val) {
            cur = &((*cur)->right);
        } else {
            return;
        }
    }
    *cur = new TreeNode(key);
}

bool bstDelete(TreeNode*& root, int key) {
    TreeNode* parent = nullptr;
    TreeNode* curr = root;
    while (curr && curr->val != key) {
        parent = curr;
        if (key < curr->val) curr = curr->left;
        else curr = curr->right;
    }
    if (!curr) return false;

    // Case 1 & 2: at most one child
    if (!curr->left || !curr->right) {
        TreeNode* child = curr->left ? curr->left : curr->right;
        if (!parent) {
            root = child;
        } else if (parent->left == curr) {
            parent->left = child;
        } else {
            parent->right = child;
        }
        delete curr;
    } else {
        // Case 3: two children. Find max in left subtree
        TreeNode* repParent = curr;
        TreeNode* rep = curr->left;
        while (rep->right) {
            repParent = rep;
            rep = rep->right;
        }

        // Unlink rep from its parent
        if (repParent != curr) {
            repParent->right = rep->left;
            rep->left = curr->left;
        }
        rep->right = curr->right;

        if (!parent) {
            root = rep;
        } else if (parent->left == curr) {
            parent->left = rep;
        } else {
            parent->right = rep;
        }
        delete curr;
    }
    return true;
}

void inorder(TreeNode* node, vector<int>& out) {
    if (!node) return;
    inorder(node->left, out);
    out.push_back(node->val);
    inorder(node->right, out);
}

void preorder(TreeNode* node, vector<int>& out) {
    if (!node) return;
    out.push_back(node->val);
    preorder(node->left, out);
    preorder(node->right, out);
}

void postorder(TreeNode* node, vector<int>& out) {
    if (!node) return;
    postorder(node->left, out);
    postorder(node->right, out);
    out.push_back(node->val);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    TreeNode* root = nullptr;
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        bstInsert(root, x);
    }

    int q;
    if (cin >> q) {
        for (int i = 0; i < q; ++i) {
            int v;
            cin >> v;
            if (bstDelete(root, v)) {
                cout << "Deleted " << v << "\n";
            } else {
                cout << v << " not found\n";
            }
        }
    }

    vector<int> inList, preList, postList;
    inorder(root, inList);
    preorder(root, preList);
    postorder(root, postList);

    cout << "Inorder:";
    for (int x : inList) cout << " " << x;
    cout << "\n";

    cout << "Preorder:";
    for (int x : preList) cout << " " << x;
    cout << "\n";

    cout << "Postorder:";
    for (int x : postList) cout << " " << x;
    cout << "\n";

    return 0;
}

