    for (int i = 0; i < (int)revealed.size(); ++i) {
        if (!correct_guessed.count(revealed[i])) {
            revealed[i] = 'X';
        }
    }

    cout << revealed << "\n";
    cout << wrong_count << "\n";
    cout << status << "\n";

