        if (in_word[idx]) {
            correct_distinct++;
            if (correct_distinct == distinct_needed) {
                result = "WIN";
                break;
            }
        } else {
            wrong++;
            if (wrong >= 7) {
                result = "LOSE";
                break;
            }
        }
    }

    string display = "";
    for (char c : word) {
        if (tried[c - 'A'] && in_word[c - 'A']) {
            display += c;
        } else {
            display += 'X';
        }
    }

    cout << display << "\n";
    cout << wrong << "\n";
    cout << result << "\n";

    return 0;
}

