using namespace std;

bool isPalindrome(const string& word) {
    if (word.empty()) return false;
    int left = 0;
    int right = (int)word.size() - 1;
    while (left < right) {
        if (tolower(word[left]) != tolower(word[right])) {
            return false;
        }
        left++;
        right--;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!getline(cin, s)) {
        cout << 0 << "\n";
        return 0;
    }

    int count = 0;
    string current_word = "";

    for (char c : s) {
        if (isalpha(static_cast<unsigned char>(c))) {
            current_word += c;
        } else {
            if (!current_word.empty()) {
                if (isPalindrome(current_word)) {
                    count++;
                }
                current_word.clear();
            }
        }
    }

    if (!current_word.empty()) {
        if (isPalindrome(current_word)) {
            count++;
        }
    }

    cout << count << "\n";
    return 0;
}

