int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string line;
    getline(cin, line);

    vector<pair<string, int>> animals(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, line);
        animals[i] = {line, i};
    }

    auto cmp = [](const pair<string, int>& a, const pair<string, int>& b) {
        int lenA = a.first.size();
        int lenB = b.first.size();
        int minLen = min(lenA, lenB);
        for (int i = 0; i < minLen; ++i) {
            char ca = toupper(static_cast<unsigned char>(a.first[i]));
            char cb = toupper(static_cast<unsigned char>(b.first[i]));
            if (ca != cb) {
                return ca < cb;
            }
        }
        if (lenA != lenB) {
            return lenA < lenB;
        }
        return a.second < b.second;
    };

    sort(animals.begin(), animals.end(), cmp);

    for (int i = 0; i < n; ++i) {
        cout << animals[i].first << "\n";
    }

    return 0;
}

