        if (!s.empty() && s.back() == '\r') {
            s.pop_back();
        }
        printReverse(s.cbegin(), s.cend());
        std::cout << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>

// Ham de quy chia de tri hoac dao nguoc bang cach hoan doi hai dau
void reverseRecursive(std::string& s, size_t left, size_t right) {
    if (left >= right) {
        return;
    }
    std::swap(s[left], s[right]);
    reverseRecursive(s, left + 1, right - 1);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::string s;
    if (std::getline(std::cin, s)) {
        if (!s.empty() && s.back() == '\r') {
            s.pop_back();
        }
        if (!s.empty()) {
            reverseRecursive(s, 0, s.length() - 1);
        }
        std::cout << s << "\n";
    }
    return 0;
}

