#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s < n - i; s++) {
            putchar(' ');
        }
        char c = (char)('a' + i - 1);
        char peak = (char)(c + i - 1);
        for (char ch = c; ch <= peak; ch++) {
            putchar(ch);
        }
        for (char ch = (char)(peak - 1); ch >= c; ch--) {
            putchar(ch);
        }
        putchar('\n');
    }
    return 0;
}

