#include <iostream>
#include <string>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::string text;
    if (!(std::cin >> text)) return 0;
    int queries;
    if (!(std::cin >> queries)) return 0;
    for (int i = 0; i < queries; ++i) {
        int op;
        std::cin >> op;
        if (op == 1) {
            int idx;
            std::cin >> idx;
            auto it = text.begin();
            std::advance(it, idx);
            text.erase(it);
        } else if (op == 2) {
            int left, right;
            std::cin >> left >> right;
            auto it1 = text.begin();
            std::advance(it1, left);
            auto it2 = text.begin();
            std::advance(it2, right + 1);
            text.erase(it1, it2);
        }
    }
    if (text.length() == 0) {
        std::cout << "EMPTY\n";
    } else {
        std::cout << text << "\n";
    }
    return 0;
}

