bool isValidSocialSecurityNumber(const string& s) {
    if (s.length() != 11) return false;
    for (int i = 0; i < 11; ++i) {
        if (i == 3 || i == 6) {
            if (s[i] != '-') return false;
        } else {
            if (!isdigit(static_cast<unsigned char>(s[i]))) return false;
        }
    }
    return true;
}

