    if (!(cin >> K)) return 0;
    string p;
    cin >> p;
    cin.ignore(); // skip newline

    string s;
    getline(cin, s);

    vector<int> freq(26, 0);
    for (char ch : s) {
        if (isalpha(static_cast<unsigned char>(ch))) {
            freq[tolower(static_cast<unsigned char>(ch)) - 'a']++;
        }
    }

    vector<int> letters(26);
    for (int i = 0; i < 26; ++i) letters[i] = i;

    sort(letters.begin(), letters.end(), [&](int a, int b) {
        if (freq[a] != freq[b]) {
            return freq[a] > freq[b];
        }
        return a < b;
    });

    vector<char> mapLower(26, 0);
    vector<char> mapUpper(26, 0);
    for (int i = 0; i < 26; ++i) {
        mapLower[i] = (char)('a' + i);
        mapUpper[i] = (char)('A' + i);
    }

    for (int i = 0; i < K; ++i) {
        int orig = letters[i];
        char target = p[i];
        mapLower[orig] = target;
        mapUpper[orig] = toupper(static_cast<unsigned char>(target));
    }

    for (char &ch : s) {
        if (islower(static_cast<unsigned char>(ch))) {
            ch = mapLower[ch - 'a'];
        } else if (isupper(static_cast<unsigned char>(ch))) {
            ch = mapUpper[ch - 'A'];
        }
    }

    cout << s << "\n";
    return 0;
}

