string toLower(const string& s) {
    string res = s;
    for (char &c : res) c = tolower(static_cast<unsigned char>(c));
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string line;
    while (getline(cin, line)) {
        stringstream ss(line);
        vector<string> tokens;
        string word;
        while (ss >> word) {
            tokens.push_back(word);
        }

        vector<string> result;
        for (size_t i = 0; i < tokens.size(); ) {
            if (i + 1 < tokens.size()) {
                string two = toLower(tokens[i]) + " " + toLower(tokens[i+1]);
                if (two == "sour cream") {
                    result.push_back("yogurt");
                    i += 2;
                    continue;
                } else if (two == "white bread") {
                    result.push_back("whole-grain bread");
                    i += 2;
                    continue;
                }
            }
            string one = toLower(tokens[i]);
            if (one == "butter") {
                result.push_back("yogurt");
            } else if (one == "flour") {
                result.push_back("rye or rice flour");
            } else if (one == "sugar") {
                result.push_back("honey");
            } else if (one == "mayonnaise") {
                result.push_back("cottage cheese");
            } else if (one == "oil") {
                result.push_back("applesauce");
            } else if (one == "milk") {
                result.push_back("soy milk");
            } else if (one == "egg" || one == "eggs") {
                result.push_back("egg whites");
            } else {
                result.push_back(tokens[i]);
            }
            i++;
        }

        for (size_t i = 0; i < result.size(); ++i) {
            cout << result[i] << (i + 1 == result.size() ? "" : " ");
        }
        cout << "\n";
    }
    cout << "Always consult your physician before making significant changes to your diet." << "\n";
    return 0;
}

#include <iostream>
