#include <vector>
#include <cctype>

using namespace std;

struct Replacement {
    string target;
    string rep;
    int wordCount;
};

string lowerStr(const string& s) {
    string ans = "";
    for (char c : s) ans += tolower((unsigned char)c);
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<Replacement> twoWords = {
        {"sour cream", "yogurt", 2},
        {"white bread", "whole-grain bread", 2}
    };

    string line;
    while (getline(cin, line)) {
        vector<string> words;
        string cur = "";
        for (char c : line) {
            if (isspace((unsigned char)c)) {
                if (!cur.empty()) {
                    words.push_back(cur);
                    cur.clear();
                }
            } else {
                cur += c;
            }
        }
        if (!cur.empty()) words.push_back(cur);

        string outLine = "";
        int n = words.size();
        for (int i = 0; i < n; ) {
            bool matched = false;
            if (i + 1 < n) {
                string t2 = lowerStr(words[i]) + " " + lowerStr(words[i+1]);
                for (auto& rw : twoWords) {
                    if (t2 == rw.target) {
                        if (!outLine.empty()) outLine += " ";
                        outLine += rw.rep;
                        i += 2;
                        matched = true;
                        break;
                    }
                }
            }
            if (matched) continue;

            string t1 = lowerStr(words[i]);
            string repl = "";
            if (t1 == "butter") repl = "yogurt";
            else if (t1 == "flour") repl = "rye or rice flour";
            else if (t1 == "sugar") repl = "honey";
            else if (t1 == "mayonnaise") repl = "cottage cheese";
            else if (t1 == "oil") repl = "applesauce";
            else if (t1 == "milk") repl = "soy milk";
            else if (t1 == "egg" || t1 == "eggs") repl = "egg whites";

            if (!repl.empty()) {
                if (!outLine.empty()) outLine += " ";
                outLine += repl;
                i++;
            } else {
                if (!outLine.empty()) outLine += " ";
                outLine += words[i];
                i++;
            }
        }
        cout << outLine << "\n";
    }
    cout << "Always consult your physician before making significant changes to your diet.\n";
    return 0;
}

