using namespace std;

string to_lower(const string& s) {
    string res = s;
    for (char &c : res) {
        c = (char)tolower((unsigned char)c);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<string> keywords(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, keywords[i]);
        keywords[i] = to_lower(keywords[i]);
    }

    int l;
    if (!(cin >> l)) return 0;
    getline(cin, dummy);

    string email_text = "";
    for (int i = 0; i < l; ++i) {
        string line;
        getline(cin, line);
        email_text += line;
        if (i + 1 < l) email_text += "\n";
    }

    string lower_text = to_lower(email_text);

    int score = 0;
    for (const string& kw : keywords) {
        if (kw.empty()) continue;
        size_t pos = 0;
        while ((pos = lower_text.find(kw, pos)) != string::npos) {
            score++;
            pos++;
        }
    }

    cout << "Diem spam: " << score << "\n";
    if (score == 0) {
        cout << "Khong phai spam\n";
    } else if (score <= 5) {
        cout << "Kha nghi thap\n";
    } else if (score <= 15) {
        cout << "Kha nghi trung binh\n";
    } else {
        cout << "Kha nghi cao\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static inline string lowerString(string str) {
    transform(str.begin(), str.end(), str.begin(), [](unsigned char c) { return tolower(c); });
    return str;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    cin.ignore();

    vector<string> patterns;
    patterns.reserve(n);
    for (int i = 0; i < n; i++) {
        string p;
        getline(cin, p);
        patterns.push_back(lowerString(p));
    }

    int l;
    if (!(cin >> l)) return 0;
    cin.ignore();

    string fullContent = "";
    for (int i = 0; i < l; i++) {
        string line;
        getline(cin, line);
        fullContent += line;
        if (i < l - 1) fullContent.push_back('\n');
    }

    string lowerContent = lowerString(fullContent);

    long long totalScore = 0;
    for (const auto& pat : patterns) {
        if (pat.empty()) continue;
        size_t current = 0;
        while ((current = lowerContent.find(pat, current)) != string::npos) {
            totalScore++;
            current++;
        }
    }

    cout << "Diem spam: " << totalScore << "\n";
    if (totalScore == 0) {
        cout << "Khong phai spam\n";
    } else if (totalScore >= 1 && totalScore <= 5) {
        cout << "Kha nghi thap\n";
    } else if (totalScore >= 6 && totalScore <= 15) {
        cout << "Kha nghi trung binh\n";
    } else {
        cout << "Kha nghi cao\n";
    }

    return 0;
}

