#include <iostream>
#include <cstdint>
#include <string>

using namespace std;

string toBinaryString(int32_t val) {
    string s = "";
    uint32_t u = static_cast<uint32_t>(val);
    for (int i = 31; i >= 0; --i) {
        s += ((u >> i) & 1) ? '1' : '0';
    }
    return s;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int32_t n;
    if (!(cin >> n)) return 0;

    string before = toBinaryString(n);
    int32_t shifted = n >> 4;
    string after = toBinaryString(shifted);

    cout << before << "\n";
    cout << after << "\n";

    string top4 = after.substr(0, 4);
    if (top4 == "0000") {
        cout << "0\n";
    } else if (top4 == "1111") {
        cout << "1\n";
    } else {
        cout << "OTHER\n";
    }
    return 0;
}

