    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    uint32_t n;
    if (std::cin >> n) {
        std::cout << toBinary32(n) << "\n";
        uint32_t reversed = reverseBits(n);
        std::cout << toBinary32(reversed) << "\n";
        std::cout << reversed << "\n";
    }
    return 0;
}

