struct Entry {
    string abbr;
    string exp;
    vector<string> expWords;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<Entry> dict(n);
    for (int i = 0; i < n; ++i) {
        string line;
        getline(cin, line);
        size_t colonPos = line.find(':');
        string abbr = line.substr(0, colonPos);
        while (!abbr.empty() && abbr.back() == ' ') abbr.pop_back();
        while (!abbr.empty() && abbr.front() == ' ') abbr.erase(abbr.begin());

        string exp = line.substr(colonPos + 1);
        while (!exp.empty() && exp.front() == ' ') exp.erase(exp.begin());
        while (!exp.empty() && exp.back() == ' ') exp.pop_back();

        dict[i].abbr = abbr;
        dict[i].exp = exp;

        stringstream ss(exp);
        string w;
        while (ss >> w) {
            dict[i].expWords.push_back(w);
        }
    }

    int mode;
    cin >> mode;
    getline(cin, dummy);

    string textLine;
    getline(cin, textLine);
    stringstream ss(textLine);
    vector<string> words;
    string w;
    while (ss >> w) {
        words.push_back(w);
    }

    vector<string> result;
    if (mode == 1) {
        for (const string& word : words) {
            string lowerWord = toLower(word);
            bool matched = false;
            for (const auto& entry : dict) {
                if (toLower(entry.abbr) == lowerWord) {
                    stringstream expSS(entry.exp);
                    string ew;
                    while (expSS >> ew) {
                        result.push_back(ew);
                    }
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                result.push_back(word);
            }
        }
    } else {
        int i = 0;
        int m = words.size();
        while (i < m) {
            int bestMatchIdx = -1;
            int bestMatchLen = 0;
            for (int d = 0; d < n; ++d) {
                int len = dict[d].expWords.size();
                if (i + len <= m) {
                    bool match = true;
                    for (int k = 0; k < len; ++k) {
                        if (toLower(words[i + k]) != toLower(dict[d].expWords[k])) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        if (len > bestMatchLen) {
                            bestMatchLen = len;
                            bestMatchIdx = d;
                        }
                    }
                }
            }
            if (bestMatchIdx != -1) {
                result.push_back(dict[bestMatchIdx].abbr);
                i += bestMatchLen;
            } else {
                result.push_back(words[i]);
                i++;
            }
        }
    }

    for (size_t i = 0; i < result.size(); ++i) {
        cout << result[i] << (i + 1 == result.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static inline string lower_str(string s) {
    for (char &c : s) c = (char)tolower((unsigned char)c);
    return s;
}

struct Rule {
    string abbr;
    string exp;
    vector<string> words;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    string line;
    getline(cin, line);

    vector<Rule> rules(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, line);
        auto pos = line.find(':');
        string a = line.substr(0, pos);
        string b = line.substr(pos + 1);

        // Trim whitespace
        stringstream sa(a), sb(b);
        sa >> rules[i].abbr;

        string word;
        vector<string> expWords;
        while (sb >> word) {
            expWords.push_back(word);
        }
        rules[i].words = expWords;
        string reconstructed = "";
        for (size_t k = 0; k < expWords.size(); ++k) {
            if (k > 0) reconstructed += " ";
            reconstructed += expWords[k];
        }
        rules[i].exp = reconstructed;
    }

    int mode;
    cin >> mode;
    getline(cin, line);

    getline(cin, line);
    stringstream sin(line);
    vector<string> inputWords;
    string token;
    while (sin >> token) {
        inputWords.push_back(token);
    }

    vector<string> outTokens;
    if (mode == 1) {
        for (const auto& w : inputWords) {
            string lw = lower_str(w);
            int found = -1;
            for (int i = 0; i < n; ++i) {
                if (lower_str(rules[i].abbr) == lw) {
                    found = i;
                    break;
                }
            }
            if (found != -1) {
                for (const auto& ew : rules[found].words) {
                    outTokens.push_back(ew);
                }
            } else {
                outTokens.push_back(w);
            }
        }
    } else {
        int idx = 0;
        int total = (int)inputWords.size();
        while (idx < total) {
            int bestRule = -1;
            int maxLen = 0;
            for (int r = 0; r < n; ++r) {
                int rlen = (int)rules[r].words.size();
                if (idx + rlen <= total) {
                    bool ok = true;
                    for (int j = 0; j < rlen; ++j) {
                        if (lower_str(inputWords[idx + j]) != lower_str(rules[r].words[j])) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok && rlen > maxLen) {
                        maxLen = rlen;
                        bestRule = r;
                    }
                }
            }
            if (bestRule != -1) {
                outTokens.push_back(rules[bestRule].abbr);
                idx += maxLen;
            } else {
                outTokens.push_back(inputWords[idx]);
                idx++;
            }
        }
    }

    for (size_t i = 0; i < outTokens.size(); ++i) {
        if (i > 0) cout << " ";
        cout << outTokens[i];
    }
    cout << "\n";
    return 0;
}

