bool mystery(unsigned int bits) {
    const int SHIFT = 8 * sizeof(unsigned int) - 1;
    const unsigned int MASK = 1u << SHIFT;
    unsigned int total = 0;

    for (int i = 0; i < SHIFT + 1; ++i, bits <<= 1) {
        if ((bits & MASK) == MASK) {
            ++total;
        }
    }
    return !(total % 2);
}

