using namespace std;

// Phiên bản 1: Cài đặt so sánh sử dụng chỉ số mảng (subscripting)
int my_strcmp_index(const string& s1, const string& s2) {
    size_t i = 0;
    while (i < s1.size() && i < s2.size()) {
        unsigned char c1 = static_cast<unsigned char>(s1[i]);
        unsigned char c2 = static_cast<unsigned char>(s2[i]);
        if (c1 != c2) {
            return (c1 < c2) ? -1 : 1;
        }
        i++;
    }
    if (s1.size() < s2.size()) return -1;
    if (s1.size() > s2.size()) return 1;
    return 0;
}

int my_strncmp_index(const string& s1, const string& s2, size_t n) {
    for (size_t i = 0; i < n; i++) {
        bool end1 = (i >= s1.size());
        bool end2 = (i >= s2.size());
        if (end1 || end2) {
            if (end1 && end2) return 0;
            return end1 ? -1 : 1;
        }
        unsigned char c1 = static_cast<unsigned char>(s1[i]);
        unsigned char c2 = static_cast<unsigned char>(s2[i]);
        if (c1 != c2) {
            return (c1 < c2) ? -1 : 1;
        }
    }
    return 0;
}

char to_char_cmp(int res) {
    if (res < 0) return '<';
    if (res > 0) return '>';
    return '=';
}

