// Phiên bản 2: Cài đặt so sánh sử dụng con trỏ (pointers & pointer arithmetic)
int my_strcmp_ptr(const char* p1, const char* p2) {
    while (*p1 && (*p1 == *p2)) {
        p1++;
        p2++;
    }
    unsigned char c1 = static_cast<unsigned char>(*p1);
    unsigned char c2 = static_cast<unsigned char>(*p2);
    if (c1 < c2) return -1;
    if (c1 > c2) return 1;
    return 0;
}

int my_strncmp_ptr(const char* p1, const char* p2, size_t n) {
    while (n > 0 && *p1 && (*p1 == *p2)) {
        p1++;
        p2++;
        n--;
    }
    if (n == 0) return 0;
    unsigned char c1 = static_cast<unsigned char>(*p1);
    unsigned char c2 = static_cast<unsigned char>(*p2);
    if (c1 < c2) return -1;
    if (c1 > c2) return 1;
    return 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s1, s2;
    if (!getline(cin, s1)) s1 = "";
    if (!getline(cin, s2)) s2 = "";

    size_t n;
    if (!(cin >> n)) n = 0;

    int res1 = my_strcmp_ptr(s1.c_str(), s2.c_str());
    int res2 = my_strncmp_ptr(s1.c_str(), s2.c_str(), n);

    if (res1 < 0) cout << "<\n";
    else if (res1 > 0) cout << ">\n";
    else cout << "=\n";

    if (res2 < 0) cout << "<\n";
    else if (res2 > 0) cout << ">\n";
    else cout << "=\n";

    return 0;
}

