#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <cctype>
#include <algorithm>

using namespace std;

bool isWordChar(char c) {
    return (isalpha(static_cast<unsigned char>(c)) || c == '\'');
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<int> letterCount(26, 0);
    map<int, int> lengthCount;
    map<string, int> wordCount;
    int maxLen = 0;

    string line;
    while (getline(cin, line)) {
        for (char c : line) {
            if (isalpha(static_cast<unsigned char>(c))) {
                letterCount[tolower(static_cast<unsigned char>(c)) - 'a']++;
            }
        }

        string currentWord = "";
        for (size_t i = 0; i <= line.size(); ++i) {
            if (i < line.size() && isWordChar(line[i])) {
                currentWord += tolower(static_cast<unsigned char>(line[i]));
            } else {
                if (!currentWord.empty()) {
                    int len = currentWord.length();
                    lengthCount[len]++;
                    wordCount[currentWord]++;
                    if (len > maxLen) {
                        maxLen = len;
                    }
                    currentWord.clear();
                }
            }
        }
    }

    cout << "Letter Frequency:\n";
    for (int i = 0; i < 26; ++i) {
        if (letterCount[i] > 0) {
            cout << (char)('a' + i) << ": " << letterCount[i] << "\n";
        }
    }

    cout << "---\n";
    cout << "Word Length Frequency:\n";
    for (int len = 1; len <= maxLen; ++len) {
        cout << len << ": " << lengthCount[len] << "\n";
    }

    cout << "---\n";
    cout << "Word Frequency:\n";
    for (const auto& pair : wordCount) {
        cout << pair.first << ": " << pair.second << "\n";
    }

    return 0;
}

