using namespace std;

const vector<string> ones = {"", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"};
const vector<string> teens = {"TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN", "EIGHTEEN", "NINETEEN"};
const vector<string> tens = {"", "", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"};

string convertTwoDigits(int n) {
    if (n == 0) return "";
    if (n < 10) return ones[n];
    if (n < 20) return teens[n - 10];
    int t = n / 10;
    int o = n % 10;
    if (o == 0) return tens[t];
    return tens[t] + " " + ones[o];
}

string convertNumberToWords(int n) {
    if (n == 0) return "ZERO";
    string res = "";
    if (n >= 100) {
        res += ones[n / 100] + " HUNDRED";
        n %= 100;
        if (n > 0) {
            res += " ";
        }
    }
    if (n > 0) {
        res += convertTwoDigits(n);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (cin >> s) {
        size_t dot = s.find('.');
        int dollars = 0;
        string cents = "00";
        if (dot != string::npos) {
            dollars = stoi(s.substr(0, dot));
            cents = s.substr(dot + 1);
            if (cents.length() == 1) cents += "0";
            else if (cents.length() > 2) cents = cents.substr(0, 2);
        } else {
            dollars = stoi(s);
        }
        cout << convertNumberToWords(dollars) << " and " << cents << "/100" << "\n";
    }
    return 0;
}

#include <iostream>
