using namespace std;

string tens_word(int d) {
    switch(d) {
        case 2: return "TWENTY";
        case 3: return "THIRTY";
        case 4: return "FORTY";
        case 5: return "FIFTY";
        case 6: return "SIXTY";
        case 7: return "SEVENTY";
        case 8: return "EIGHTY";
        case 9: return "NINETY";
        default: return "";
    }
}

string digit_word(int d) {
    switch(d) {
        case 1: return "ONE";
        case 2: return "TWO";
        case 3: return "THREE";
        case 4: return "FOUR";
        case 5: return "FIVE";
        case 6: return "SIX";
        case 7: return "SEVEN";
        case 8: return "EIGHT";
        case 9: return "NINE";
        default: return "";
    }
}

string teen_word(int d) {
    switch(d) {
        case 10: return "TEN";
        case 11: return "ELEVEN";
        case 12: return "TWELVE";
        case 13: return "THIRTEEN";
        case 14: return "FOURTEEN";
        case 15: return "FIFTEEN";
        case 16: return "SIXTEEN";
        case 17: return "SEVENTEEN";
        case 18: return "EIGHTEEN";
        case 19: return "NINETEEN";
        default: return "";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string line;
    if (cin >> line) {
        size_t dot_pos = line.find('.');
        int dollar_val = stoi(line.substr(0, dot_pos));
        string cent_val = line.substr(dot_pos + 1);

        string words = "";
        if (dollar_val == 0) {
            words = "ZERO";
        } else {
            int hundreds = dollar_val / 100;
            int rem = dollar_val % 100;
            if (hundreds > 0) {
                words += digit_word(hundreds) + " HUNDRED";
                if (rem > 0) words += " ";
            }
            if (rem >= 10 && rem <= 19) {
                words += teen_word(rem);
            } else if (rem >= 20) {
                words += tens_word(rem / 10);
                if (rem % 10 > 0) {
                    words += " " + digit_word(rem % 10);
                }
            } else if (rem > 0) {
                words += digit_word(rem);
            }
        }

        cout << words << " and " << cent_val << "/100\n";
    }
    return 0;
}

#include <iostream>
