#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>
#include <algorithm>
#include <cctype>
#include <map>

using namespace std;

struct UnitInfo {
    string category;
    double factor; // factor to base unit
};

string toLower(const string& s) {
    string res = s;
    for (char &c : res) c = tolower(c);
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    map<string, UnitInfo> units;
    // Length (base: meter)
    auto addL = [&](const string& name, double f) {
        units[name] = {"length", f};
    };
    addL("meter", 1.0); addL("meters", 1.0);
    addL("centimeter", 0.01); addL("centimeters", 0.01);
    addL("millimeter", 0.001); addL("millimeters", 0.001);
    addL("kilometer", 1000.0); addL("kilometers", 1000.0);
    addL("inch", 0.0254); addL("inches", 0.0254);
    addL("foot", 0.3048); addL("feet", 0.3048);
    addL("yard", 0.9144); addL("yards", 0.9144);
    addL("mile", 1609.344); addL("miles", 1609.344);

    // Weight (base: gram)
    auto addW = [&](const string& name, double f) {
        units[name] = {"weight", f};
    };
    addW("gram", 1.0); addW("grams", 1.0);
    addW("kilogram", 1000.0); addW("kilograms", 1000.0);
    addW("milligram", 0.001); addW("milligrams", 0.001);
    addW("pound", 453.59237); addW("pounds", 453.59237);
    addW("ounce", 28.349523125); addW("ounces", 28.349523125);

    // Volume (base: liter)
    auto addV = [&](const string& name, double f) {
        units[name] = {"volume", f};
    };
    addV("liter", 1.0); addV("liters", 1.0);
    addV("milliliter", 0.001); addV("milliliters", 0.001);
    addV("gallon", 3.785411784); addV("gallons", 3.785411784);
    addV("quart", 0.946352946); addV("quarts", 0.946352946);
    addV("pint", 0.473176473); addV("pints", 0.473176473);

    int t;
    if (!(cin >> t)) return 0;
    string line;
    getline(cin, line);

    while (t--) {
        if (!getline(cin, line)) break;
        if (line.empty()) continue;
        stringstream ss(line);
        string w1, w2, unit1, w3, w4, valStr, unit2WithQ;
        if (ss >> w1 >> w2 >> unit1 >> w3 >> w4 >> valStr >> unit2WithQ) {
            if (!unit2WithQ.empty() && unit2WithQ.back() == '?') {
                unit2WithQ.pop_back();
            }
            string u1 = toLower(unit1);
            string u2 = toLower(unit2WithQ);
            double val = stod(valStr);

            if (units.find(u1) == units.end() || units.find(u2) == units.end()) {
                cout << "Invalid conversion\n";
            } else if (units[u1].category != units[u2].category) {
                cout << "Invalid conversion\n";
            } else {
                // convert val unit2 to base, then base to unit1
                double valInBase = val * units[u2].factor;
                double res = valInBase / units[u1].factor;
                cout << fixed << setprecision(4) << res << "\n";
            }
        } else {
            cout << "Invalid conversion\n";
        }
    }
    return 0;
}

