    };

    int T;
    if (!(cin >> T)) return 0;
    string dummy;
    getline(cin, dummy);

    for (int t = 0; t < T; ++t) {
        string line;
        if (!getline(cin, line)) break;
        if (line.empty()) continue;

        stringstream ss(line);
        vector<string> tokens;
        string tok;
        while (ss >> tok) {
            tokens.push_back(tok);
        }

        // Expected pattern: "How many <unit1> are in <val> <unit2>?"
        if (tokens.size() != 7) {
            cout << "Invalid conversion\n";
            continue;
        }

        string u1 = tokens[2];
        string valStr = tokens[5];
        string u2 = tokens[6];
        if (!u2.empty() && u2.back() == '?') {
            u2.pop_back();
        }

        for (char &c : u1) c = (char)tolower(c);
        for (char &c : u2) c = (char)tolower(c);

        auto it1 = dict.find(u1);
        auto it2 = dict.find(u2);

        if (it1 == dict.end() || it2 == dict.end()) {
            cout << "Invalid conversion\n";
            continue;
        }

        if (it1->second.type != it2->second.type) {
            cout << "Invalid conversion\n";
            continue;
        }

        double val = stod(valStr);
        double ans = (val * it2->second.toBase) / it1->second.toBase;
        cout << fixed << setprecision(4) << ans << "\n";
    }

    return 0;
}

