#include <iostream>
#include <string>
#include <vector>
#include <unordered_set>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> dict(n);
    unordered_set<string> dict_set;
    for (int i = 0; i < n; ++i) {
        cin >> dict[i];
        dict_set.insert(dict[i]);
    }

    string s;
    cin >> s;

    if (dict_set.count(s)) {
        cout << "Word is spelled correctly.\n";
        return 0;
    }

    cout << "Word is not spelled correctly.\n";

    // Generate all candidate words from S
    unordered_set<string> candidates;

    // 1. Transpositions of adjacent letters
    int len = s.length();
    for (int i = 0; i + 1 < len; ++i) {
        if (s[i] != s[i + 1]) {
            string t = s;
            swap(t[i], t[i + 1]);
            candidates.insert(t);
        }
    }

    // 2. Replacing double letter with single letter
    for (int i = 0; i + 1 < len; ++i) {
        if (s[i] == s[i + 1]) {
            string t = s.substr(0, i) + s.substr(i + 1);
            candidates.insert(t);
        }
    }

    // Iterate through dictionary in original order
    for (const string& word : dict) {
        if (candidates.count(word)) {
            cout << "Did you mean \"" << word << "\"?\n";
        }
    }

    return 0;
}

