int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> words(n);
    for (int i = 0; i < n; ++i) {
        cin >> words[i];
    }

    string target;
    cin >> target;

    for (const auto& w : words) {
        if (w == target) {
            cout << "Word is spelled correctly.\n";
            return 0;
        }
    }

    cout << "Word is not spelled correctly.\n";

    int m = target.size();
    set<string> validSuggestions;

    // Generate adjacent swaps
    for (int i = 0; i + 1 < m; ++i) {
        string altered = target;
        swap(altered[i], altered[i + 1]);
        validSuggestions.insert(altered);
    }

    // Generate single removals for consecutive duplicate characters
    for (int i = 0; i + 1 < m; ++i) {
        if (target[i] == target[i + 1]) {
            string altered = target;
            altered.erase(i, 1);
            validSuggestions.insert(altered);
        }
    }

    for (const auto& w : words) {
        if (validSuggestions.find(w) != validSuggestions.end()) {
            cout << "Did you mean \"" << w << "\"?\n";
        }
    }

    return 0;
}

