#include <iostream>

class Base {
public:
    long long val_base;
    Base(long long v) : val_base(v) {}
};

class DerivedA : virtual public Base {
public:
    long long val_a;
    DerivedA(long long vb, long long va) : Base(vb), val_a(va) {}
};

class DerivedB : virtual public Base {
public:
    long long val_b;
    DerivedB(long long vb, long long vb_val) : Base(vb), val_b(vb_val) {}
};

class DerivedFinal : public DerivedA, public DerivedB {
public:
    long long val_final;
    DerivedFinal(long long vb, long long va, long long v_b, long long vf)
        : Base(vb), DerivedA(vb, va), DerivedB(vb, v_b), val_final(vf) {}

    void print() const {
        long long sum = val_base + val_a + val_b + val_final;
        std::cout << val_base << " " << val_a << " " << val_b << " " << val_final << " " << sum << "\n";
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int q;
    if (!(std::cin >> q)) return 0;
    while (q--) {
        long long vb, va, v_b, vf;
        std::cin >> vb >> va >> v_b >> vf;
        DerivedFinal obj(vb, va, v_b, vf);
        obj.print();
    }
    return 0;
}

#include <iostream>

struct TopBase {
    long long base_value;
    explicit TopBase(long long val) : base_value(val) {}
};

struct LeftBranch : virtual TopBase {
    long long left_value;
    LeftBranch(long long b_val, long long l_val) : TopBase(b_val), left_value(l_val) {}
};

struct RightBranch : virtual TopBase {
    long long right_value;
    RightBranch(long long b_val, long long r_val) : TopBase(b_val), right_value(r_val) {}
};

struct DiamondBottom : LeftBranch, RightBranch {
    long long bottom_value;
    DiamondBottom(long long b, long long l, long long r, long long bot)
        : TopBase(b), LeftBranch(b, l), RightBranch(b, r), bottom_value(bot) {}

    long long getSum() const {
        return base_value + left_value + right_value + bottom_value;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int numQueries;
    if (std::cin >> numQueries) {
        for (int i = 0; i < numQueries; ++i) {
            long long b, a, r, f;
            std::cin >> b >> a >> r >> f;
            DiamondBottom obj(b, a, r, f);
            std::cout << obj.base_value << " " << obj.left_value << " " << obj.right_value << " " << obj.bottom_value << " " << obj.getSum() << "\n";
        }
    }
    return 0;
}

