#include <bits/stdc++.h>

using namespace std;

bool canMatch(char c1, char c2) {
    vector<char> v1, v2;
    if (c1 == 'a') v1.push_back('b');
    else if (c1 == 'z') v1.push_back('y');
    else { v1.push_back(c1 - 1); v1.push_back(c1 + 1); }

    if (c2 == 'a') v2.push_back('b');
    else if (c2 == 'z') v2.push_back('y');
    else { v2.push_back(c2 - 1); v2.push_back(c2 + 1); }

    for (char a : v1) {
        for (char b : v2) {
            if (a == b) return true;
        }
    }
    return false;
}

int main() {
