        char s[105];
        scanf("%s", s);
        bool possible = true;
        for (int i = 0, j = n - 1; i < j; ++i, --j) {
            if (!canMatch(s[i], s[j])) {
                possible = false;
                break;
            }
        }
        if (possible) puts("YES");
        else puts("NO");
    }
    return 0;
}

