#include <iostream>
#include <vector>

using namespace std;

bool isPrime(long long x) {
    if (x < 2) return false;
    if (x == 2 || x == 3) return true;
    if (x % 2 == 0 || x % 3 == 0) return false;
    for (long long i = 5; i * i <= x; i += 6) {
        if (x % i == 0 || x % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<vector<long long>> a(n, vector<long long>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        // Chéo chính: a[i][i]
        if (isPrime(a[i][i])) {
            sum += a[i][i];
        }
        // Chéo phụ: a[i][n - 1 - i]
        if (n - 1 - i != i) {
            if (isPrime(a[i][n - 1 - i])) {
                sum += a[i][n - 1 - i];
            }
        }
    }
    cout << sum << "\n";
    return 0;
}

