#include <iostream>

using namespace std;

bool isLeapYear(long long year) {
    if (year <= 0) return false;
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long t, n;
    if (cin >> t >> n) {
        if (t < 1 || t > 12 || n <= 0) {
            cout << "INVALID\n";
        } else {
            if (t == 2) {
                if (isLeapYear(n)) {
                    cout << 29 << "\n";
                } else {
                    cout << 28 << "\n";
                }
            } else if (t == 4 || t == 6 || t == 9 || t == 11) {
                cout << 30 << "\n";
            } else {
                cout << 31 << "\n";
            }
        }
    }
    return 0;
}

