bool isPalindrome(const string &s) {
    int l = 0, r = (int)s.length() - 1;
    while (l < r) {
        if (s[l] != s[r]) return false;
        l++;
        r--;
    }
    return true;
}

struct WordInfo {
    string word;
    int first_pos;
    int len;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string line;
    if (!getline(cin, line)) return 0;

    stringstream ss(line);
    string w;
    vector<WordInfo> palindromes;
    unordered_set<string> seen;
    int order = 0;

    while (ss >> w) {
        if (isPalindrome(w)) {
            if (seen.find(w) == seen.end()) {
                seen.insert(w);
                palindromes.push_back({w, order++, (int)w.length()});
            }
        }
    }

    stable_sort(palindromes.begin(), palindromes.end(), [](const WordInfo &a, const WordInfo &b) {
        if (a.len != b.len) return a.len < b.len;
        return a.first_pos < b.first_pos;
    });

    for (size_t i = 0; i < palindromes.size(); ++i) {
        cout << palindromes[i].word << (i + 1 == palindromes.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}

