bool isGreater(const string& a, const string& b) {
    if (a.length() != b.length()) {
        return a.length() > b.length();
    }
    return a > b;
}

string normalize(const string& s) {
    int i = 0;
    while (i + 1 < (int)s.length() && s[i] == '0') {
        i++;
    }
    return s.substr(i);
}

int main() {
    ios_base::sync_with_stdio(false);
