    string max_val = "";
    string cur = "";

    for (char c : s) {
        if (isdigit(c)) {
            cur += c;
        } else {
            if (!cur.empty()) {
                string norm = normalize(cur);
                if (max_val.empty() || isGreater(norm, max_val)) {
                    max_val = norm;
                }
                cur.clear();
            }
        }
    }
    if (!cur.empty()) {
        string norm = normalize(cur);
        if (max_val.empty() || isGreater(norm, max_val)) {
            max_val = norm;
        }
    }

    cout << max_val << "\n";
    return 0;
}

