const long long MOD = 1e9 + 7;

long long powerMod(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) {
            res = (__int128)res * base % MOD;
        }
        base = (__int128)base * base % MOD;
        exp /= 2;
    }
    return res;
}

