#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long binpow(long long a, unsigned long long b) {
    long long ans = 1 % MOD;
    a %= MOD;
    while (b > 0) {
        if (b & 1) ans = (ans * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return ans;
}

