int power_mod(int a, int exp, int mod) {
    int res = 1;
    a %= mod;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * a) % mod;
        a = (a * a) % mod;
        exp /= 2;
    }
    return res;
}

