        cout << 4 << "\n";
        return 0;
    }
    // Modulo 4 of n
    int mod4 = 0;
    for (char c : n_str) {
        mod4 = (mod4 * 10 + (c - '0')) % 4;
    }
    // If mod4 is 0, since n > 0, we can use exp = 4
    int exp = (mod4 == 0) ? 4 : mod4;
    int ans = (power_mod(1, exp, 5) + power_mod(2, exp, 5) + power_mod(3, exp, 5) + power_mod(4, exp, 5)) % 5;
    cout << ans << "\n";
    return 0;
}

