#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <map>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    map<string, long long> scores;
    string line;
    while (getline(cin, line)) {
        if (line.empty()) continue;
        stringstream ss(line);
        vector<string> tokens;
        string token;
        while (ss >> token) {
            tokens.push_back(token);
        }
        if (tokens.empty()) continue;

        int dash_idx = -1;
        for (int i = 0; i < (int)tokens.size(); ++i) {
            if (tokens[i] == "-") {
                dash_idx = i;
                break;
            }
        }
        if (dash_idx < 2 || dash_idx + 2 >= (int)tokens.size()) continue;

        long long a = stoll(tokens[dash_idx - 1]);
        long long b = stoll(tokens[dash_idx + 1]);

        string teamX = "";
        for (int i = 0; i < dash_idx - 1; ++i) {
            if (!teamX.empty()) teamX += " ";
            teamX += tokens[i];
        }

        string teamY = "";
        for (int i = dash_idx + 2; i < (int)tokens.size(); ++i) {
            if (!teamY.empty()) teamY += " ";
            teamY += tokens[i];
        }

        scores[teamX] += a;
        scores[teamY] += b;
    }

    vector<pair<string, long long>> res(scores.begin(), scores.end());
    sort(res.begin(), res.end(), [](const pair<string, long long>& p1, const pair<string, long long>& p2) {
        if (p1.second != p2.second) {
            return p1.second > p2.second;
        }
        return p1.first < p2.first;
    });

    for (const auto& p : res) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Team {
    string name;
    long long goals;
};

bool compareTeams(const Team& a, const Team& b) {
    if (a.goals != b.goals) {
        return a.goals > b.goals;
    }
    return a.name < b.name;
}

int main() {
    cin.tie(nullptr)->sync_with_stdio(false);

    unordered_map<string, long long> score_table;
    string s;
    while (getline(cin, s)) {
        if (s.find('-') == string::npos) continue;
        size_t dash = s.find(" - ");
        if (dash == string::npos) continue;

        // Left part: "X a"
        string left = s.substr(0, dash);
        size_t last_sp = left.rfind(' ');
        string teamX = left.substr(0, last_sp);
        long long scoreA = stoll(left.substr(last_sp + 1));

        // Right part: "b Y"
        string right = s.substr(dash + 3);
        size_t first_sp = right.find(' ');
        long long scoreB = stoll(right.substr(0, first_sp));
        string teamY = right.substr(first_sp + 1);

        score_table[teamX] += scoreA;
        score_table[teamY] += scoreB;
    }

    vector<Team> teams;
    teams.reserve(score_table.size());
    for (auto& entry : score_table) {
        teams.push_back({entry.first, entry.second});
    }

    sort(teams.begin(), teams.end(), compareTeams);

    for (const auto& t : teams) {
        cout << t.name << " " << t.goals << "\n";
    }
    return 0;
}

