#include <vector>
#include <algorithm>

using namespace std;

int sum_digits(long long n) {
    if (n == 0) return 0;
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    sort(a.begin(), a.end(), [](int x, int y) {
        int sx = sum_digits(x);
        int sy = sum_digits(y);
        if (sx != sy) return sx < sy;
        return x < y;
    });
    for (int i = 0; i < n; ++i) {
        cout << a[i] << (i + 1 == n ? "" : " ");
    }
    cout << "\n";
    return 0;
}

