bool isPrime(long long n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (long long i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    // 1. Max element and first index
    long long max_val = a[0];
    int max_idx = 0;
    for (int i = 1; i < n; ++i) {
        if (a[i] > max_val) {
            max_val = a[i];
            max_idx = i;
        }
    }
    cout << max_val << " " << max_idx << "\n";

    // 2. Min element and last index
    long long min_val = a[0];
    int min_idx = 0;
    for (int i = 1; i < n; ++i) {
        if (a[i] <= min_val) {
            min_val = a[i];
            min_idx = i;
        }
    }
    cout << min_val << " " << min_idx << "\n";

    // 3. Count primes
    int prime_count = 0;
    for (int i = 0; i < n; ++i) {
        if (isPrime(a[i])) {
            prime_count++;
        }
    }
    cout << prime_count << "\n";

    // 4. Max product of 2 elements
    // Find top 2 max and top 2 min
    long long max1 = -2e18, max2 = -2e18;
    long long min1 = 2e18, min2 = 2e18;
    for (int i = 0; i < n; ++i) {
        if (a[i] > max1) {
            max2 = max1;
            max1 = a[i];
        } else if (a[i] > max2) {
            max2 = a[i];
        }

        if (a[i] < min1) {
            min2 = min1;
            min1 = a[i];
        } else if (a[i] < min2) {
            min2 = a[i];
        }
    }
    long long max_prod = max(max1 * max2, min1 * min2);
    cout << max_prod << "\n";

    // 5. Symmetric check
    bool symmetric = true;
    for (int i = 0; i < n / 2; ++i) {
        if (a[i] != a[n - 1 - i]) {
            symmetric = false;
            break;
        }
    }
    cout << (symmetric ? "YES" : "NO") << "\n";

    // 6. Product of all elements modulo 10^9 + 7
    long long MOD = 1000000007;
    long long total_prod = 1;
    for (int i = 0; i < n; ++i) {
        long long rem = (a[i] % MOD + MOD) % MOD;
        total_prod = (total_prod * rem) % MOD;
    }
    cout << total_prod << "\n";

    return 0;
}

