using namespace std;

bool checkPrime(long long n) {
    if (n < 2) return false;
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long val;
    vector<long long> unique_primes;
    unordered_map<long long, int> count_map;

    while (cin >> val) {
        if (checkPrime(val)) {
            if (count_map.find(val) == count_map.end()) {
                unique_primes.push_back(val);
                count_map[val] = 1;
            } else {
                count_map[val]++;
            }
        }
    }

    for (long long p : unique_primes) {
        cout << p << " " << count_map[p] << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    vector<int> b(m);
    for (int i = 0; i < m; ++i) {
        cin >> b[i];
    }

    sort(a.begin(), a.end());
    a.erase(unique(a.begin(), a.end()), a.end());

    sort(b.begin(), b.end());
    b.erase(unique(b.begin(), b.end()), b.end());

    vector<int> intersection_res;
    vector<int> union_res;

    int i = 0, j = 0;
    while (i < (int)a.size() && j < (int)b.size()) {
        if (a[i] == b[j]) {
            intersection_res.push_back(a[i]);
            union_res.push_back(a[i]);
            i++;
            j++;
        } else if (a[i] < b[j]) {
            union_res.push_back(a[i]);
            i++;
        } else {
            union_res.push_back(b[j]);
            j++;
        }
    }
    while (i < (int)a.size()) {
        union_res.push_back(a[i++]);
    }
    while (j < (int)b.size()) {
        union_res.push_back(b[j++]);
    }

    for (int k = 0; k < (int)intersection_res.size(); ++k) {
        cout << intersection_res[k] << (k + 1 == (int)intersection_res.size() ? "" : " ");
    }
    cout << "\n";

    for (int k = 0; k < (int)union_res.size(); ++k) {
        cout << union_res[k] << (k + 1 == (int)union_res.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}

