bool check(long long n) {
    int last_digit = 10;
    while (n > 0) {
        int digit = n % 10;
        if (digit > last_digit) return false;
        last_digit = digit;
        n /= 10;
    }
    return true;
}

struct Item {
    int val;
    int count;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    unordered_map<int, int> freq;
    int n;
    while (cin >> n) {
        if (check(n)) {
            freq[n]++;
        }
    }

    vector<Item> v;
    v.reserve(freq.size());
    for (auto& entry : freq) {
        v.push_back({entry.first, entry.second});
    }

    sort(v.begin(), v.end(), [](const Item& a, const Item& b) {
        if (a.count != b.count) return a.count > b.count;
        return a.val < b.val;
    });

    for (const auto& item : v) {
        cout << item.val << " " << item.count << "\n";
    }

    return 0;
}

