int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<unsigned long long> sq(n);
    for (int i = 0; i < n; ++i) {
        unsigned long long val;
        cin >> val;
        sq[i] = val * val;
    }

    sort(sq.begin(), sq.end());

    bool found = false;
    for (int k = n - 1; k >= 2; --k) {
        int left = 0;
        int right = k - 1;
        while (left < right) {
            unsigned long long current_sum = sq[left] + sq[right];
            if (current_sum == sq[k]) {
                found = true;
                break;
            } else if (current_sum < sq[k]) {
                ++left;
            } else {
                --right;
            }
        }
        if (found) break;
    }

    if (found) cout << "YES\n";
    else cout << "NO\n";

    return 0;
}

