        if (i == 0) {
            prev = current;
        } else {
            if (current <= prev) {
                total_ops += (prev + 1 - current);
                prev = prev + 1;
            } else {
                prev = current;
            }
        }
    }

    printf("%lld\n", total_ops);
    return 0;
}

