// Hàm cộng hai số nguyên lớn dạng chuỗi
string addBigInt(const string &a, const string &b) {
    string res = "";
    int i = (int)a.size() - 1;
    int j = (int)b.size() - 1;
    int carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += a[i--] - '0';
        if (j >= 0) sum += b[j--] - '0';
        res.push_back((sum % 10) + '0');
        carry = sum / 10;
    }
    reverse(res.begin(), res.end());
    // Xóa các số 0 ở đầu nếu có, trừ khi chuỗi chỉ gồm các số 0
    int pos = 0;
    while (pos + 1 < (int)res.size() && res[pos] == '0') {
        pos++;
    }
    return res.substr(pos);
}

