    }
    sort(a.begin(), a.end());

    // Tách thành hai số dưới dạng mảng các chữ số đảo ngược (least significant first)
    vector<int> num1, num2;
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) num1.push_back(a[i]);
        else num2.push_back(a[i]);
    }
    reverse(num1.begin(), num1.end());
    reverse(num2.begin(), num2.end());

    vector<int> sum;
    int carry = 0;
    int sz = max(num1.size(), num2.size());
    for (int i = 0; i < sz || carry; ++i) {
        int cur = carry;
        if (i < (int)num1.size()) cur += num1[i];
        if (i < (int)num2.size()) cur += num2[i];
        sum.push_back(cur % 10);
        carry = cur / 10;
    }

    while (sum.size() > 1 && sum.back() == 0) {
        sum.pop_back();
    }
    reverse(sum.begin(), sum.end());
    for (int digit : sum) {
        cout << digit;
    }
    cout << "\n";
    return 0;
}

