const int MAX_VAL = 1000000;
bool is_prime[MAX_VAL + 1];
int prime_count[MAX_VAL + 1];

void sieve() {
    for (int i = 2; i <= MAX_VAL; ++i) {
        is_prime[i] = true;
    }
    for (int p = 2; p * p <= MAX_VAL; ++p) {
        if (is_prime[p]) {
            for (int i = p * p; i <= MAX_VAL; i += p) {
                is_prime[i] = false;
            }
        }
    }
    prime_count[0] = 0;
    for (int i = 1; i <= MAX_VAL; ++i) {
        prime_count[i] = prime_count[i - 1] + (is_prime[i] ? 1 : 0);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    sieve();

    int q;
    if (!(cin >> q)) return 0;
    while (q--) {
        int l, r;
        cin >> l >> r;
        if (l > r) swap(l, r);
        cout << prime_count[r] - prime_count[l - 1] << "\n";
    }
    return 0;
}

