    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    unordered_map<long long, int> first_occurrence;
    first_occurrence.reserve(n * 2);
    first_occurrence[0] = -1;

    long long current_sum = 0;
    int max_len = 0;
    int best_start = -1;
    int best_end = -1;

    for (int i = 0; i < n; ++i) {
        current_sum += a[i];
        auto it = first_occurrence.find(current_sum);
        if (it != first_occurrence.end()) {
            int len = i - it->second;
            if (len > max_len) {
                max_len = len;
                best_start = it->second + 1;
                best_end = i;
            }
        } else {
            first_occurrence[current_sum] = i;
        }
    }

    if (max_len == 0) {
        cout << "NOT FOUND\n";
    } else {
        for (int i = best_start; i <= best_end; ++i) {
