#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Prefix {
    long long sum;
    int index;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    // Using sorting instead of hash map
    vector<Prefix> pref(n + 1);
    pref[0] = {0, -1};
    long long s = 0;
    for (int i = 0; i < n; ++i) {
        s += a[i];
        pref[i + 1] = {s, i};
    }

    sort(pref.begin(), pref.end(), [](const Prefix& x, const Prefix& y) {
        if (x.sum != y.sum) return x.sum < y.sum;
        return x.index < y.index;
    });

    int max_len = 0;
    int best_start = -1;
    int best_end = -1;

    // For each unique sum, the first occurrence has minimum index
    int i = 0;
    while (i <= n) {
        int j = i;
        while (j <= n && pref[j].sum == pref[i].sum) {
            j++;
        }
        // Indices are from i to j - 1
        int min_idx = pref[i].index;
        for (int k = i + 1; k < j; ++k) {
            int current_len = pref[k].index - min_idx;
            int start_idx = min_idx + 1;
            int end_idx = pref[k].index;
            if (current_len > max_len) {
                max_len = current_len;
                best_start = start_idx;
                best_end = end_idx;
            } else if (current_len == max_len && max_len > 0) {
                if (start_idx < best_start) {
                    best_start = start_idx;
                    best_end = end_idx;
                }
            }
        }
        i = j;
    }

    if (max_len == 0) {
        cout << "NOT FOUND\n";
    } else {
        for (int k = best_start; k <= best_end; ++k) {
            cout << a[k] << (k == best_end ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

