#include <queue>

using namespace std;

const int dx[8] = {-2, -2, -1, -1, 1, 1, 2, 2};
const int dy[8] = {-1, 1, -2, 2, -2, 2, -1, 1};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    int s, t, u, v;
    cin >> s >> t >> u >> v;
    --s; --t; --u; --v;

    vector<vector<int>> a(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    if (s == u && t == v) {
        cout << "YES\n";
        return 0;
    }

    vector<vector<bool>> visited(n, vector<bool>(n, false));
    queue<pair<int, int>> q;

    q.push({s, t});
    visited[s][t] = true;

    bool reachable = false;
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if (x == u && y == v) {
            reachable = true;
            break;
        }

        for (int i = 0; i < 8; ++i) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                if (a[nx][ny] == 1 && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    q.push({nx, ny});
                }
            }
        }
    }

    if (reachable) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

