#include <iostream>

long long solve(long long n) {
    // Sử dụng công thức trực tiếp để đối chiếu hoặc đệ quy
    // Ở đây dùng đệ quy tail-recursive / tích luỹ
    auto rec = [](auto& self, long long k, long long acc) -> long long {
        if (k == 0) return acc;
        return self(self, k - 1, acc + k * k * k);
    };
    return rec(rec, n, 0LL);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    long long n;
    if (std::cin >> n) {
        std::cout << solve(n) << "\n";
    }
    return 0;
}

