#include <iostream>
#include <vector>
#include <queue>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, s, t;
    if (!(cin >> n >> s >> t)) return 0;

    vector<vector<int>> a(n + 1, vector<int>(n + 1));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            cin >> a[i][j];
        }
    }

    vector<vector<bool>> visited(n + 1, vector<bool>(n + 1, false));
    queue<pair<int, int>> q;

    visited[s][t] = true;
    q.push({s, t});
    int count = 0;

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        count++;

        for (int k = 0; k < 4; ++k) {
            int nr = r + dx[k];
            int nc = c + dy[k];
            if (nr >= 1 && nr <= n && nc >= 1 && nc <= n) {
                if (!visited[nr][nc] && a[nr][nc] == 0) {
                    visited[nr][nc] = true;
                    q.push({nr, nc});
                }
            }
        }
    }

    cout << count << "\n";
    return 0;
}

