long long power_recursive(long long a, long long b) {
    if (b == 0) return 1;
    long long half = power_recursive(a, b / 2);
    long long res = (half * half) % MOD;
    if (b % 2 == 1) {
        res = (res * (a % MOD)) % MOD;
    }
    return res;
}

