bool binarySearchDesc(const vector<int>& a, int left, int right, int x) {
    if (left > right) return false;
    int mid = left + (right - left) / 2;
    if (a[mid] == x) return true;
    if (a[mid] < x) {
        // Do mảng giảm dần, các phần tử lớn hơn x sẽ nằm ở nửa bên trái
        return binarySearchDesc(a, left, mid - 1, x);
    } else {
        return binarySearchDesc(a, mid + 1, right, x);
    }
}

