#include <iostream>

using namespace std;

int a[1005];

int check(int l, int r, int x) {
    if (l > r) return 0;
    int m = (l + r) / 2;
    if (a[m] == x) return 1;
    if (a[m] > x) {
        return check(m + 1, r, x);
    } else {
        return check(l, m - 1, x);
    }
}

int main() {
    int n;
    if (cin >> n) {
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }
        int x;
        cin >> x;
        cout << check(0, n - 1, x) << "\n";
    }
    return 0;
}

