    vector<int> cnt(256, 0);
    for (int i = 0; i < n; ++i) {
        char c;
        cin >> c;
        cnt[(unsigned char)c]++;
    }

    vector<pair<char, int>> elements;
    for (int c = 0; c < 256; ++c) {
        if (cnt[c] > 0) {
            elements.push_back({(char)c, cnt[c]});
        }
    }

    // Yêu cầu 1: phần tử đầu tiên
    cout << elements.front().first << " " << elements.front().second << "\n\n";

    // Yêu cầu 2: phần tử cuối cùng
    cout << elements.back().first << " " << elements.back().second << "\n\n";

    // Yêu cầu 3: thứ tự tăng dần
    for (const auto& item : elements) {
        cout << item.first << " " << item.second << "\n";
    }
    cout << "\n";

    // Yêu cầu 4: thứ tự giảm dần
    for (int i = (int)elements.size() - 1; i >= 0; --i) {
        cout << elements[i].first << " " << elements[i].second << "\n";
    }

    return 0;
}

