        if (a[i] < b[j]) {
            ans.push_back(a[i]);
            i++;
        } else if (a[i] > b[j]) {
            j++;
        } else {
            i++;
            j++;
        }
    }
    while (i < a.size()) {
        ans.push_back(a[i]);
        i++;
    }

    for (size_t idx = 0; idx < ans.size(); ++idx) {
        if (idx > 0) cout << " ";
        cout << ans[idx];
    }
    cout << "\n";

    return 0;
}

