#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    vector<pair<int, int>> vals(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        vals[i] = {a[i], i};
    }

    // Coordinate compression / tracking unique elements backwards
    // Using a sorted array approach to find last occurrence of each element
    sort(vals.begin(), vals.end(), [](const pair<int, int>& p1, const pair<int, int>& p2) {
        if (p1.first != p2.first) return p1.first < p2.first;
        return p1.second < p2.second;
    });

    vector<int> is_first_from_right(n, 0);
    for (int i = 0; i < n; ++i) {
        if (i + 1 == n || vals[i].first != vals[i + 1].first) {
            // vals[i].second is the last occurrence (rightmost occurrence)
            // but we need unique elements in suffix: an element is first seen from right at its last occurrence
            // Wait, an element appears in suffix [L..N-1] if its last occurrence >= L.
            // Actually, any occurrence will do: an element is present in [L..N-1] iff its rightmost occurrence >= L
            // Wait, simpler: every unique element contributes 1 from its FIRST occurrence from the right, which is its rightmost index in the array!
            is_first_from_right[vals[i].second] = 1;
        }
    }

    vector<int> f(n);
    int current = 0;
    for (int i = n - 1; i >= 0; --i) {
        if (is_first_from_right[i]) {
            current++;
        }
        f[i] = current;
    }

    int q;
    if (cin >> q) {
        while (q--) {
            int l;
            cin >> l;
            cout << f[l] << "\n";
        }
    }

    return 0;
}

#include <iostream>
