#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!(cin >> s)) return 0;

    vector<int> freq(26, 0);
    for (char c : s) {
        freq[c - 'a']++;
    }

    int max_freq = -1;
    char max_char = 'z' + 1;
    int min_freq = 1e9;
    char min_char = 'a' - 1;
    int distinct_count = 0;

    for (int i = 0; i < 26; ++i) {
        if (freq[i] > 0) {
            distinct_count++;
            char c = (char)('a' + i);

            // Tìm tần suất lớn nhất, ưu tiên thứ tự từ điển nhỏ nhất
            if (freq[i] > max_freq) {
                max_freq = freq[i];
                max_char = c;
            } else if (freq[i] == max_freq && c < max_char) {
                max_char = c;
            }

            // Tìm tần suất nhỏ nhất, ưu tiên thứ tự từ điển lớn nhất
            if (freq[i] < min_freq) {
                min_freq = freq[i];
                min_char = c;
            } else if (freq[i] == min_freq && c > min_char) {
                min_char = c;
            }
        }
    }

    cout << max_char << " " << max_freq << "\n";
    cout << min_char << " " << min_freq << "\n";
    cout << distinct_count << "\n";

    return 0;
}

