    int n;
    if (!(cin >> n)) return 0;
    multiset<int> ms;
    for (int i = 0; i < n; ++i) {
        int val;
        cin >> val;
        ms.insert(val);
    }
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int type, x;
        cin >> type >> x;
        if (type == 1) {
            ms.insert(x);
        } else if (type == 2) {
            auto it = ms.find(x);
            if (it != ms.end()) {
                ms.erase(it);
            }
        } else if (type == 3) {
            auto it = ms.lower_bound(x);
            if (it != ms.end()) {
                cout << *it << "\n";
            } else {
                cout << -1 << "\n";
            }
        } else if (type == 4) {
            auto it = ms.upper_bound(x);
            if (it != ms.begin()) {
                --it;
                cout << *it << "\n";
            } else {
                cout << -1 << "\n";
            }
        }
    }
    return 0;
}

