#include <iostream>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;

    // Hinh 1
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            cout << '*';
        }
        cout << '\n';
    }
    cout << '\n';

    // Hinh 2
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (i == 1 || i == n || j == 1 || j == n) {
                cout << '*';
            } else {
                cout << ' ';
            }
        }
        cout << '\n';
    }
    cout << '\n';

    // Hinh 3
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (i == 1 || i == n || j == 1 || j == n) {
                cout << '*';
            } else {
                cout << '#';
            }
        }
        cout << '\n';
    }
    cout << '\n';

    // Hinh 4
    for (int i = 1; i <= n; ++i) {
        if (n == 1) {
            cout << i << '\n';
        } else if (i == 1 || i == n) {
            for (int j = 1; j <= n; ++j) {
                cout << i << (j == n ? "" : " ");
            }
            cout << '\n';
        } else {
            cout << i;
            for (int j = 0; j < 2 * n - 3; ++j) {
                cout << ' ';
            }
            cout << i << '\n';
        }
    }

    return 0;
}

