            cout << string(n, '*') << "\n";
        } else {
            cout << '*' << string(n - 2, '#') << '*' << "\n";
        }
    }
}

void drawPattern4(int n) {
    for (int i = 1; i <= n; i++) {
        if (n == 1) {
