#include <iostream>
#include <vector>

using namespace std;

long long factorial(int k) {
    long long res = 1;
    for (int i = 2; i <= k; ++i) {
        res *= i;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    vector<bool> used(n + 1, false);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    long long rank = 1;
    for (int i = 0; i < n; ++i) {
        int smaller = 0;
        for (int v = 1; v < a[i]; ++v) {
            if (!used[v]) smaller++;
        }
        rank += smaller * factorial(n - 1 - i);
        used[a[i]] = true;
    }
    cout << rank << "\n";
    return 0;
}

