        while (i >= 1 && a[i] == 1) {
            i--;
        }
        if (i == 0) {
            ok = false;
        } else {
            a[i]--;
            int d = cnt - i + 1;
            cnt = i;
            int q = d / a[i];
            int r = d % a[i];
            for (int j = 1; j <= q; ++j) {
                a[++cnt] = a[i];
            }
            if (r > 0) {
                a[++cnt] = r;
            }
        }
    }

    cout << results.size() << "\n";
    for (const auto& p : results) {
        for (size_t i = 0; i < p.size(); ++i) {
            cout << p[i] << (i + 1 < p.size() ? '+' : '\n');
        }
    }

    return 0;
}

