#include <iostream>
#include <string>
#include <vector>

using namespace std;

int n, k;
vector<string> list1, list2;

bool hasExactlyOneBlockOfK(const string& s, int k) {
    int countK = 0;
    int curLen = 0;
    for (int i = 0; i <= (int)s.length(); ++i) {
        if (i < (int)s.length() && s[i] == '1') {
            curLen++;
        } else {
            if (curLen == k) {
                countK++;
            } else if (curLen > k) {
                // Có cụm dài hơn k, không hợp lệ theo nghĩa cụm đúng k bit 1 liên tiếp
                // Tuy nhiên câu hỏi nói: "duy nhất K bit 1 liên tiếp" nghĩa là chỉ có đúng 1 đoạn gồm K bit 1
                // Nếu có đoạn dài hơn k thì không phải là duy nhất k bit 1 liên tiếp
            }
            curLen = 0;
        }
    }
    return countK == 1;
}

void backtrack(int idx, string& current, int count1) {
    if (idx == n) {
        if (count1 == k) {
            list1.push_back(current);
        }
        if (hasExactlyOneBlockOfK(current, k)) {
            list2.push_back(current);
        }
        return;
    }

    current.push_back('0');
    backtrack(idx + 1, current, count1);
    current.pop_back();

    current.push_back('1');
    backtrack(idx + 1, current, count1 + 1);
    current.pop_back();
}

