    string cur = "";
    backtrack(0, cur, 0);

    for (size_t i = 0; i < list1.size(); ++i) {
        cout << list1[i] << (i + 1 == list1.size() ? "" : " ");
    }
    cout << "\n";

    for (size_t i = 0; i < list2.size(); ++i) {
        cout << list2[i] << (i + 1 == list2.size() ? "" : " ");
    }
    cout << "\n";

    return 0;
}

