bool checkBlock(int mask, int n, int k) {
    int countK = 0;
    int cur = 0;
    for (int i = 0; i < n; ++i) {
        if ((mask >> (n - 1 - i)) & 1) {
            cur++;
        } else {
            if (cur == k) countK++;
            cur = 0;
        }
    }
    if (cur == k) countK++;
    return countK == 1;
}

