bool findNextPermutation(string &s) {
    int n = s.length();
    int i = n - 2;
    while (i >= 0 && s[i] >= s[i + 1]) {
        i--;
    }
    if (i < 0) return false;
    int j = n - 1;
    while (s[j] <= s[i]) {
        j--;
    }
    swap(s[i], s[j]);
    reverse(s.begin() + i + 1, s.end());
    return true;
}

