using namespace std;

long long C(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;
    long long res = 1;
    for (int i = 1; i <= k; ++i) {
        res = res * (n - i + 1) / i;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> a(k);
    for (int i = 0; i < k; ++i) {
        cin >> a[i];
    }

    long long normal_rank = 1;
    int prev = 0;
    for (int i = 0; i < k; ++i) {
        for (int v = prev + 1; v < a[i]; ++v) {
            normal_rank += C(n - v, k - 1 - i);
        }
        prev = a[i];
    }

    long long total = C(n, k);
    long long reverse_rank = total - normal_rank + 1;
    cout << reverse_rank << "\n";
    return 0;
}

