using namespace std;

string solve(int n) {
    if (8 % n == 0) return "8";

    vector<int> parent(n, -1);
    vector<char> digit(n, ' ');
    vector<bool> visited(n, false);

    queue<int> q;
    int start_rem = 8 % n;
    visited[start_rem] = true;
    digit[start_rem] = '8';
    q.push(start_rem);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (u == 0) {
            break;
        }

        int next_rem0 = (u * 10) % n;
        if (!visited[next_rem0]) {
            visited[next_rem0] = true;
            parent[next_rem0] = u;
            digit[next_rem0] = '0';
            q.push(next_rem0);
            if (next_rem0 == 0) break;
        }

        int next_rem8 = (u * 10 + 8) % n;
        if (!visited[next_rem8]) {
            visited[next_rem8] = true;
            parent[next_rem8] = u;
            digit[next_rem8] = '8';
            q.push(next_rem8);
            if (next_rem8 == 0) break;
        }
    }

    string ans = "";
    int curr = 0;
    while (curr != -1) {
        ans += digit[curr];
        curr = parent[curr];
    }
    reverse(ans.begin(), ans.end());
    return ans;
}

