string bfs(int n) {
    struct State {
        int rem;
        string s;
    };

    vector<bool> seen(n, false);
    queue<State> q;

    q.push({8 % n, "8"});
    seen[8 % n] = true;

    while (!q.empty()) {
        State cur = q.front();
        q.pop();

        if (cur.rem == 0) return cur.s;

        int r0 = (cur.rem * 10) % n;
        if (!seen[r0]) {
            seen[r0] = true;
            q.push({r0, cur.s + "0"});
        }

        int r8 = (cur.rem * 10 + 8) % n;
        if (!seen[r8]) {
            seen[r8] = true;
            q.push({r8, cur.s + "8"});
        }
    }
    return "";
}

