void backtrack(int n, int open, int close, string &current) {
    if ((int)current.size() == n) {
        cout << current << "\n";
        return;
    }
    if (open < n / 2) {
        current.push_back('(');
        backtrack(n, open + 1, close, current);
        current.pop_back();
    }
    if (close < open) {
        current.push_back(')');
        backtrack(n, open, close + 1, current);
        current.pop_back();
    }
}

