        if (open < half) {
            self(self, s + "(", open + 1, close);
        }
        if (close < open) {
            self(self, s + ")", open, close + 1);
        }
    };
    generate(generate, "", 0, 0);
    for (const string &res : results) {
        cout << res << "\n";
    }
    return 0;
}

