#include <iostream>
#include <vector>
#include <string>
#include <cmath>

using namespace std;

int n;
vector<int> a;
vector<bool> used;

void backtrack(int pos) {
    if (pos == n) {
        for (int i = 0; i < n; ++i) {
            cout << a[i];
        }
        cout << '\n';
        return;
    }
    for (int v = 1; v <= n; ++v) {
        if (!used[v]) {
            if (pos == 0 || abs(a[pos - 1] - v) != 1) {
                used[v] = true;
                a[pos] = v;
                backtrack(pos + 1);
                used[v] = false;
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    if (cin >> n) {
        a.resize(n);
        used.assign(n + 1, false);
        backtrack(0);
    }
    return 0;
}

