bool isTriangle(long long a, long long b, long long c) {
    return (a > 0 && b > 0 && c > 0 && a + b > c && a + c > b && b + c > a);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long a, b, c;
    if (!(cin >> a >> b >> c)) return 0;

    if (!isTriangle(a, b, c)) {
        cout << "INVALID\n";
    } else if (a == b && b == c) {
        cout << 1 << "\n";
    } else if (a == b || b == c || a == c) {
        cout << 2 << "\n";
    } else if (a * a + b * b == c * c || a * a + c * c == b * b || b * b + c * c == a * a) {
        cout << 3 << "\n";
    } else {
        cout << 4 << "\n";
    }

    return 0;
}

