#include <iostream>

using namespace std;

int main() {
    long long n;
    if (cin >> n) {
        int distinct_prime_factors = 0;
        if (n % 2 == 0) {
            distinct_prime_factors++;
            while (n % 2 == 0) n /= 2;
        }
        for (long long d = 3; d * d <= n; d += 2) {
            if (n % d == 0) {
                distinct_prime_factors++;
                do {
                    n /= d;
                } while (n % d == 0);
            }
        }
        if (n > 1) {
            distinct_prime_factors++;
        }
        cout << distinct_prime_factors << "\n";
    }
    return 0;
}

#include <iostream>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n;
    if (!(cin >> n)) return 0;

    long long best_prime = -1;
    int max_exp = -1;

    for (long long d = 2; d * d <= n; ++d) {
        if (n % d == 0) {
            int count = 0;
            while (n % d == 0) {
                count++;
                n /= d;
            }
            if (count > max_exp) {
                max_exp = count;
                best_prime = d;
            }
        }
    }

    if (n > 1) {
        int count = 1;
        if (count > max_exp) {
            max_exp = count;
            best_prime = n;
        }
    }

    cout << best_prime << " " << max_exp << "\n";
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

int main() {
    long long N;
    if (cin >> N) {
        long long ans_p = 2;
        int ans_exp = 0;

        for (long long i = 2; i * i <= N; ++i) {
            if (N % i == 0) {
                int cnt = 0;
                while (N % i == 0) {
                    cnt++;
                    N /= i;
                }
                // Do ta duyệt i từ nhỏ đến lớn, điều kiện strictly greater (cnt > ans_exp)
                // sẽ đảm bảo ưu tiên thừa số nguyên tố nhỏ hơn khi số mũ bằng nhau.
                if (cnt > ans_exp) {
                    ans_exp = cnt;
                    ans_p = i;
                }
            }
        }
        if (N > 1) {
            int cnt = 1;
            if (cnt > ans_exp) {
                ans_exp = cnt;
                ans_p = N;
            }
        }
        cout << ans_p << " " << ans_exp << "\n";
    }
    return 0;
}

#include <iostream>
#include <numeric>

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        std::swap(a, b);
    }
    return a;
}

long long lcm(long long a, long long b) {
    return (a / gcd(a, b)) * b;
}

int main() {
    long long a, b, c, d;
    if (std::cin >> a >> b >> c >> d) {
        long long g = gcd(gcd(a, b), gcd(c, d));
        long long l = lcm(lcm(a, b), lcm(c, d));
        std::cout << g << " " << l << "\n";
    }
    return 0;
}

#include <iostream>

long long findGCD(long long x, long long y) {
    return y == 0 ? x : findGCD(y, x % y);
}

long long findLCM(long long x, long long y) {
    return (x / findGCD(x, y)) * y;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    long long arr[4];
    for (int i = 0; i < 4; ++i) {
        std::cin >> arr[i];
    }
    long long ansGCD = arr[0];
    long long ansLCM = arr[0];
    for (int i = 1; i < 4; ++i) {
        ansGCD = findGCD(ansGCD, arr[i]);
        ansLCM = findLCM(ansLCM, arr[i]);
    }
    std::cout << ansGCD << " " << ansLCM << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;

    int temp = n;
    vector<pair<int, int>> factors;
    for (int i = 2; 1LL * i * i <= temp; ++i) {
        if (temp % i == 0) {
            int count = 0;
            while (temp % i == 0) {
                ++count;
                temp /= i;
            }
            factors.push_back({i, count});
        }
    }
    if (temp > 1) {
        factors.push_back({temp, 1});
    }

    // Line 1: distinct prime factors
    for (size_t i = 0; i < factors.size(); ++i) {
        cout << factors[i].first << (i + 1 == factors.size() ? "" : " ");
    }
    cout << "\n";

    // Line 2: (p, k)
    for (size_t i = 0; i < factors.size(); ++i) {
        cout << "(" << factors[i].first << ", " << factors[i].second << ")" << (i + 1 == factors.size() ? "" : " ");
    }
    cout << "\n";

    // Line 3: product with ' x '
    bool first = true;
    for (const auto& f : factors) {
        for (int j = 0; j < f.second; ++j) {
            if (!first) cout << " x ";
            cout << f.first;
            first = false;
        }
    }
    cout << "\n";

    return 0;
}

#include <cstdio>
#include <vector>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    struct Factor {
        int p, k;
    };
    std::vector<Factor> f;
    int val = n;
    for (int p = 2; p * p <= val; ++p) {
        if (val % p == 0) {
            int k = 0;
            while (val % p == 0) {
                k++;
                val /= p;
            }
            f.push_back({p, k});
        }
    }
    if (val > 1) {
        f.push_back({val, 1});
    }

    for (size_t i = 0; i < f.size(); ++i) {
        printf("%d%c", f[i].p, (i + 1 == f.size()) ? '\n' : ' ');
    }

    for (size_t i = 0; i < f.size(); ++i) {
        printf("(%d, %d)%c", f[i].p, f[i].k, (i + 1 == f.size()) ? '\n' : ' ');
    }

    bool start = true;
    for (const auto& item : f) {
        for (int i = 0; i < item.k; ++i) {
            if (!start) printf(" x ");
            printf("%d", item.p);
            start = false;
        }
    }
    printf("\n");

    return 0;
}

