#include <iostream>

using namespace std;

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    if (r == 0 || r == n) return 1;
    if (r > n / 2) r = n - r;
    long long res = 1;
    for (int i = 1; i <= r; ++i) {
        res = res * (n - i + 1) / i;
    }
    return res;
}

int main() {
    int n;
    if (cin >> n) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= i; ++j) {
                cout << nCr(i, j) << (j == i ? "" : " ");
            }
            cout << "\n";
        }
    }
    return 0;
}

