#include <iostream>

using namespace std;

long long isqrt_ceil(long long x) {
    long long l = 1, r = 1000000, ans = 1000000;
    while (l <= r) {
        long long mid = l + (r - l) / 2;
        if (mid * mid >= x) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}

long long isqrt_floor(long long x) {
    long long l = 1, r = 1000000, ans = 0;
    while (l <= r) {
        long long mid = l + (r - l) / 2;
        if (mid * mid <= x) {
            ans = mid;
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return ans;
}

