unsigned long long integer_sqrt(unsigned long long n) {
    unsigned long long low = 0, high = 1000000000ULL, ans = 0;
    while (low <= high) {
        unsigned long long mid = low + (high - low) / 2;
        if (mid * mid <= n) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

