#include <iostream>

using namespace std;

long long sumDigits(long long n) {
    long long s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s;
}

bool isSmith(long long n) {
    if (n <= 1) return false;
    long long original = n;
    long long sumN = sumDigits(n);
    long long sumFactors = 0;

    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            long long sPrime = sumDigits(i);
            while (n % i == 0) {
                sumFactors += sPrime;
                n /= i;
            }
        }
    }

    // Nếu n chưa từng bị chia cho ước nào nhỏ hơn nó, n là số nguyên tố -> không phải số Smith
    if (n == original) return false;

    if (n > 1) {
        sumFactors += sumDigits(n);
    }

    return sumN == sumFactors;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long n;
    if (cin >> n) {
        if (isSmith(n)) {
            cout << "YES\n";
        } else {
            cout << "NO\n";
        }
    }
    return 0;
}

