    long long max_prime = -1;

    while (n % 2 == 0) {
        max_prime = 2;
        n /= 2;
    }

    for (long long i = 3; i * i <= n; i += 2) {
        if (n % i == 0) {
            max_prime = i;
            while (n % i == 0) {
                n /= i;
            }
        }
