bool isBeautiful(int n) {
    if (n < 4) return false;
    int temp = n;
    for (int p = 2; p * p <= temp; ++p) {
        if (temp % p == 0) {
            int count = 0;
            while (temp % p == 0) {
                count++;
                temp /= p;
            }
            if (count < 2) return false;
        }
    }
    if (temp > 1) return false; // Thừa số nguyên tố cuối cùng có số mũ là 1
    return true;
}

