    long long lower = 1;
    for (int i = 1; i < n; ++i) {
        lower *= 10;
    }
    long long upper = lower * 10 - 1;

    // Tim boi nho nhat cua L >= lower
    long long ans = ((lower + L - 1) / L) * L;

    if (ans <= upper) {
        cout << ans << "\n";
    } else {
        cout << -1 << "\n";
    }

    return 0;
}

