        unsigned long long g1 = std::gcd(x, y);
        unsigned long long l1 = (x / g1) * y;
        unsigned long long g2 = std::gcd(l1, z);
        unsigned long long L = (l1 / g2) * z;

        unsigned long long min_val = 1;
        for (unsigned long long i = 1; i < n; ++i) {
            min_val *= 10ULL;
        }

        unsigned long long rem = min_val % L;
        unsigned long long ans;
        if (rem == 0) {
            ans = min_val;
        } else {
            ans = min_val + (L - rem);
        }

        // Kiem tra xem ans co vuot qua n chu so hay khong
        // So lon nhat co n chu so co the tinh hoac so sanh ans < min_val * 10 (neu n < 19)
        if (n == 16) {
            if (ans >= 10000000000000000ULL) {
                cout << -1 << "\n";
            } else {
                cout << ans << "\n";
            }
        } else {
            if (ans >= min_val * 10ULL) {
                cout << -1 << "\n";
            } else {
                cout << ans << "\n";
            }
        }
    }
    return 0;
}

