static const long long MOD = 1000000007LL;

long long mul_mod(long long a, long long b) {
    return (__int128)a * b % MOD;
}

long long bin_pow(long long base, long long exp) {
    if (exp == 0) return 1LL;
    long long half = bin_pow(base, exp / 2);
    long long res = mul_mod(half, half);
    if (exp % 2 == 1) res = mul_mod(res, base % MOD);
    return res;
}

