    for (int p : primes) {
        long long exponent = 0;
        long long power = p;
        while (power <= n) {
            exponent += n / power;
            if (n / p < power) break;
            power *= p;
        }
        total_divisors = (total_divisors * ((exponent + 1) % MOD)) % MOD;
    }

    cout << total_divisors << "\n";
    return 0;
}

