const int MAX_VAL = 1000005;
vector<bool> prime(MAX_VAL, true);

void sieve() {
    prime[0] = prime[1] = false;
    for (int p = 2; p * p < MAX_VAL; p++) {
        if (prime[p]) {
            for (int i = p * p; i < MAX_VAL; i += p)
                prime[i] = false;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    sieve();

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + a[i];
    }

    vector<int> ans;
    for (int i = 0; i < n; ++i) {
        int left = pref[i];
        int right = pref[n] - pref[i + 1];
        if (left >= 0 && left < MAX_VAL && right >= 0 && right < MAX_VAL) {
            if (prime[left] && prime[right]) {
                ans.push_back(i);
            }
        }
    }

    for (size_t i = 0; i < ans.size(); ++i) {
        if (i > 0) cout << " ";
        cout << ans[i];
    }
    cout << "\n";

    return 0;
}

