#include <iostream>
#include <vector>
#include <string>
#include <cmath>

using namespace std;

bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

bool isPalindrome(int n) {
    string s = to_string(n);
    int l = 0, r = (int)s.length() - 1;
    while (l < r) {
        if (s[l] != s[r]) return false;
        l++;
        r--;
    }
    return true;
}

bool isSquare(int n) {
    if (n < 0) return false;
    int r = round(sqrt(n));
    return r * r == n;
}

bool isSumOfDigitsPrime(int n) {
    int sum = 0;
    int temp = n;
    if (temp == 0) sum = 0;
    while (temp > 0) {
        sum += temp % 10;
        temp /= 10;
    }
    return isPrime(sum);
}

int main() {
