    int c1 = 0, c2 = 0, c3 = 0, c4 = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (isPrime(a[i])) c1++;
        if (isPalindrome(a[i])) c2++;
        if (isSquare(a[i])) c3++;
        if (isSumOfDigitsPrime(a[i])) c4++;
    }
    cout << c1 << "\n";
    cout << c2 << "\n";
    cout << c3 << "\n";
    cout << c4 << "\n";
    return 0;
}

#include <stdio.h>
#include <stdbool.h>
#include <math.h>

bool check_prime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

bool check_palin(int n) {
    int original = n;
    int reversed = 0;
    int temp = n;
    while (temp > 0) {
        reversed = reversed * 10 + (temp % 10);
        temp /= 10;
    }
    return original == reversed;
}

bool check_sq(int n) {
    int s = (int)(sqrt(n) + 0.5);
    return s * s == n;
}

bool check_sum_digits_prime(int n) {
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return check_prime(s);
}

