    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        if (check_prime(a[i])) cnt1++;
        if (check_palin(a[i])) cnt2++;
        if (check_sq(a[i])) cnt3++;
        if (check_sum_digits_prime(a[i])) cnt4++;
    }
    printf("%d\n%d\n%d\n%d\n", cnt1, cnt2, cnt3, cnt4);
