    bool printed = false;
    for (int i = 0; i < n; ++i) {
        bool left = (i > 0) && (1LL * a[i] * a[i - 1] < 0);
        bool right = (i < n - 1) && (1LL * a[i] * a[i + 1] < 0);
        if (left || right) {
            if (printed) putchar(' ');
            printf("%d", a[i]);
            printed = true;
        }
    }
    putchar('\n');
    return 0;
}

