#include <iostream>
#include <vector>

using namespace std;

int findLast(const vector<long long>& a, long long x) {
    int low = 0, high = (int)a.size() - 1;
    int ans = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (a[mid] == x) {
            ans = mid;
            low = mid + 1;
        } else if (a[mid] < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

