    if (!(cin >> n >> x)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    int ans = findLast(a, x);
    cout << ans << "\n[Comparator_Binary Search].\n";
    return 0;
}

