#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int count_greater(const vector<int>& b, int val) {
    int low = 0, high = (int)b.size() - 1;
    int first_greater = b.size();
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (b[mid] > val) {
            first_greater = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return (int)b.size() - first_greater;
}

int main() {
