    long long ans = 0;
    if (k == 0) {
        long long count = 1;
        for (int i = 1; i < n; ++i) {
            if (a[i] == a[i - 1]) {
                count++;
            } else {
                ans += count * (count - 1) / 2;
                count = 1;
            }
        }
        ans += count * (count - 1) / 2;
    } else {
        for (int i = 0; i < n; ++i) {
            long long target = a[i] + k;
            auto low = lower_bound(a.begin() + i + 1, a.end(), target);
            auto high = upper_bound(a.begin() + i + 1, a.end(), target);
            ans += (high - low);
        }
    }

