#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long k;
    if (!(cin >> n >> k)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    sort(a.begin(), a.end());

    // Compress into unique values with frequencies
    vector<pair<long long, long long>> freq;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && a[j] == a[i]) {
            j++;
        }
        freq.push_back({a[i], (long long)(j - i)});
        i = j;
    }

    long long total_pairs = 0;
    int m = freq.size();
    if (k == 0) {
        for (int i = 0; i < m; ++i) {
            total_pairs += freq[i].second * (freq[i].second - 1) / 2;
        }
    } else {
        int right = 0;
        for (int left = 0; left < m; ++left) {
            while (right < m && freq[right].first < freq[left].first + k) {
                right++;
            }
            if (right < m && freq[right].first == freq[left].first + k) {
                total_pairs += freq[left].second * freq[right].second;
            }
        }
    }

    cout << total_pairs << "\n";
    return 0;
}

