#include <bits/stdc++.h>
using namespace std;

static long long target_val;

struct CmpDist {
    bool operator()(long long u, long long v) const {
        long long d1 = llabs(u - target_val);
        long long d2 = llabs(v - target_val);
        if (d1 != d2) return d1 < d2;
        return u < v;
    }
};

struct CmpParity {
    bool operator()(long long u, long long v) const {
        int p1 = (u & 1);
        int p2 = (v & 1);
        if (p1 != p2) return p1 < p2;
        if (p1 == 0) return u < v;
        return u > v;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n >> target_val)) return 0;

    vector<long long> arr1(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr1[i];
    }
    vector<long long> arr2 = arr1;

    stable_sort(arr1.begin(), arr1.end(), CmpDist());
    for (int i = 0; i < n; ++i) {
        if (i > 0) cout << ' ';
        cout << arr1[i];
    }
    cout << '\n';

    stable_sort(arr2.begin(), arr2.end(), CmpParity());
    for (int i = 0; i < n; ++i) {
        if (i > 0) cout << ' ';
        cout << arr2[i];
    }
    cout << '\n';
    cout << "[Comparator_Binary Search].\n";

    return 0;
}

