#include <iostream>
#include <iomanip>
#include <string>

using namespace std;

class MyTime {
private:
    int hour, minute, second;
public:
    MyTime(int h, int m, int s) : hour(h), minute(m), second(s) {}

    void print() const {
        cout << setfill('0') << setw(2) << hour << ":"
             << setw(2) << minute << ":"
             << setw(2) << second << "\n";
    }

    MyTime nextSecond() const {
        int h = hour, m = minute, s = second + 1;
        if (s == 60) {
            s = 0;
            m++;
            if (m == 60) {
                m = 0;
                h = (h + 1) % 24;
            }
        }
        return MyTime(h, m, s);
    }

    MyTime nextMinute() const {
        int h = hour, m = minute + 1, s = second;
        if (m == 60) {
            m = 0;
            h = (h + 1) % 24;
        }
        return MyTime(h, m, s);
    }

    MyTime nextHour() const {
        return MyTime((hour + 1) % 24, minute, second);
    }

    MyTime previousSecond() const {
        int h = hour, m = minute, s = second - 1;
        if (s == -1) {
            s = 59;
            m--;
            if (m == -1) {
                m = 59;
                h = (h - 1 + 24) % 24;
            }
        }
        return MyTime(h, m, s);
    }

    MyTime previousMinute() const {
        int h = hour, m = minute - 1, s = second;
        if (m == -1) {
            m = 59;
            h = (h - 1 + 24) % 24;
        }
        return MyTime(h, m, s);
    }

    MyTime previousHour() const {
        return MyTime((hour - 1 + 24) % 24, minute, second);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int h, m, s;
    char c1, c2;
    if (cin >> h >> c1 >> m >> c2 >> s) {
        MyTime t(h, m, s);
        t.nextSecond().print();
        t.nextMinute().print();
        t.nextHour().print();
        t.previousSecond().print();
        t.previousMinute().print();
        t.previousHour().print();
    }
    return 0;
}

#include <cstdio>

struct ClockTime {
    int totalSeconds;

    ClockTime(int h, int m, int s) {
        totalSeconds = h * 3600 + m * 60 + s;
    }

    static void printFromSec(int sec) {
        const int SEC_PER_DAY = 86400;
        sec = (sec % SEC_PER_DAY + SEC_PER_DAY) % SEC_PER_DAY;
        int h = sec / 3600;
        int m = (sec % 3600) / 60;
        int s = sec % 60;
        printf("%02d:%02d:%02d\n", h, m, s);
    }
};

int main() {
    int h, m, s;
    if (scanf("%d:%d:%d", &h, &m, &s) == 3) {
        int base = h * 3600 + m * 60 + s;
        // +1s
        ClockTime::printFromSec(base + 1);
        // +1m
        ClockTime::printFromSec(base + 60);
        // +1h
        ClockTime::printFromSec(base + 3600);
        // -1s
        ClockTime::printFromSec(base - 1);
        // -1m
        ClockTime::printFromSec(base - 60);
        // -1h
        ClockTime::printFromSec(base - 3600);
    }
    return 0;
}

