#include <iostream>
#include <string>
#include <vector>
#include <iomanip>
#include <algorithm>
#include <sstream>

using namespace std;

struct InvoiceInfo {
    int id;
    string name;
    double finalAmount;
};

string extractAfterColon(const string& s) {
    size_t pos = s.find(':');
    if (pos == string::npos) return "";
    size_t start = pos + 1;
    while (start < s.size() && s[start] == ' ') start++;
    return s.substr(start);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string line;
    getline(cin, line);

    vector<InvoiceInfo> list;
    for (int i = 0; i < n; ++i) {
        string l1, l2, l3, l4, l5;
        getline(cin, l1);
        while (l1.empty()) getline(cin, l1);
        getline(cin, l2);
        getline(cin, l3);
        getline(cin, l4);
        getline(cin, l5);

        string s_id = extractAfterColon(l1);
        int id = stoi(s_id);

        string name = extractAfterColon(l2);
        while (!name.empty() && (name.back() == ' ' || name.back() == '\r')) name.pop_back();

        string s_disc = extractAfterColon(l3);
        double discount = stod(s_disc);

        string s_amt = extractAfterColon(l5);
        stringstream ss(s_amt);
        double amount = 0;
        ss >> amount;

        double finalAmount = amount - amount * discount / 100.0;
        list.push_back({id, name, finalAmount});
    }

    sort(list.begin(), list.end(), [](const InvoiceInfo& a, const InvoiceInfo& b) {
        if (abs(a.finalAmount - b.finalAmount) > 1e-9) {
            return a.finalAmount > b.finalAmount;
        }
        return a.id < b.id;
    });

    cout << fixed << setprecision(2);
    for (const auto& item : list) {
        cout << "Customer ID : " << item.id << "\n";
        cout << "Full Name : " << item.name << "\n";
        cout << "Amount : " << item.finalAmount << " $\n";
    }

    return 0;
}

