    int discount;
public:
    Customer(int id = 0, string name = "", int discount = 0) 
        : id(id), name(name), discount(discount) {}
    int getId() const { return id; }
    string getName() const { return name; }
    int getDiscount() const { return discount; }
};

class Invoice {
private:
    Customer customer;
    int invoiceId;
    double amount;
public:
    Invoice(Customer c, int invId, double amt)
        : customer(c), invoiceId(invId), amount(amt) {}

    double getFinalAmount() const {
        return amount * (100 - customer.getDiscount()) / 100.0;
    }
    int getCustomerId() const {
        return customer.getId();
    }
    string getCustomerName() const {
        return customer.getName();
    }
};

string trim(const string& str) {
    size_t first = str.find_first_not_of(" \t\r\n");
    if (first == string::npos) return "";
    size_t last = str.find_last_not_of(" \t\r\n");
    return str.substr(first, (last - first + 1));
}

string parseValue(const string& line) {
    auto idx = line.find(':');
    if (idx != string::npos) {
        return trim(line.substr(idx + 1));
    }
    return "";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    string s;
    getline(cin, s);

    vector<Invoice> invoices;
    for (int i = 0; i < n; ++i) {
        string sId, sName, sDisc, sInv, sAmt;
        while (getline(cin, sId) && trim(sId).empty());
        getline(cin, sName);
        getline(cin, sDisc);
        getline(cin, sInv);
        getline(cin, sAmt);

        int id = stoi(parseValue(sId));
        string name = parseValue(sName);
        int discount = stoi(parseValue(sDisc));
        int invId = stoi(parseValue(sInv));

        string amtStr = parseValue(sAmt);
        size_t dollarPos = amtStr.find('$');
        if (dollarPos != string::npos) amtStr = amtStr.substr(0, dollarPos);
        double amt = stod(trim(amtStr));

        invoices.emplace_back(Customer(id, name, discount), invId, amt);
    }

    sort(invoices.begin(), invoices.end(), [](const Invoice& a, const Invoice& b) {
        double amtA = a.getFinalAmount();
        double amtB = b.getFinalAmount();
        if (abs(amtA - amtB) > 1e-9) {
            return amtA > amtB;
        }
        return a.getCustomerId() < b.getCustomerId();
    });

    cout << fixed << setprecision(2);
    for (const auto& inv : invoices) {
        cout << "Customer ID : " << inv.getCustomerId() << "\n";
        cout << "Full Name : " << inv.getCustomerName() << "\n";
        cout << "Amount : " << inv.getFinalAmount() << " $\n";
    }

    return 0;
}

