#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>
#include <map>

using namespace std;

struct Team {
    string code;
    string name;
    int played;
    int diff;
    int points;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<Team> teams;
    map<string, int> nameToIndex;

    while (teams.size() < 20) {
        string line;
        if (!getline(cin, line)) break;
        while (line.empty() || line.find_first_not_of(" _-\r\t") == string::npos) {
            if (!getline(cin, line)) break;
        }
        if (line.empty() || line[0] != '#') continue;
        // line is rank #k
        string code, name;
        if (!getline(cin, code)) break;
        // trim code
        while (!code.empty() && (code.back() == '\r' || code.back() == ' ')) code.pop_back();
        if (!getline(cin, name)) break;
        while (!name.empty() && (name.back() == '\r' || name.back() == ' ')) name.pop_back();
        int p, d, pts;
        string statsLine;
        if (!getline(cin, statsLine)) break;
        stringstream ss(statsLine);
        ss >> p >> d >> pts;
        nameToIndex[name] = teams.size();
        teams.push_back({code, name, p, d, pts});
    }

    for (int i = 0; i < 10; ++i) {
        string line;
        while (getline(cin, line)) {
            while (!line.empty() && (line.back() == '\r' || line.back() == ' ')) line.pop_back();
            if (!line.empty()) break;
        }
        if (line.empty()) continue;

        size_t dash = line.find(" - ");
        if (dash == string::npos) continue;
        string leftPart = line.substr(0, dash);
        string rightPart = line.substr(dash + 3);

        size_t lastSpace = leftPart.rfind(' ');
        string team1 = leftPart.substr(0, lastSpace);
        int score1 = stoi(leftPart.substr(lastSpace + 1));

        size_t firstSpace = rightPart.find(' ');
        int score2 = stoi(rightPart.substr(0, firstSpace));
        string team2 = rightPart.substr(firstSpace + 1);

        int idx1 = nameToIndex[team1];
        int idx2 = nameToIndex[team2];

        teams[idx1].played++;
        teams[idx2].played++;
        teams[idx1].diff += (score1 - score2);
        teams[idx2].diff += (score2 - score1);

        if (score1 > score2) {
            teams[idx1].points += 3;
        } else if (score1 < score2) {
            teams[idx2].points += 3;
        } else {
            teams[idx1].points += 1;
            teams[idx2].points += 1;
        }
    }

    sort(teams.begin(), teams.end(), [](const Team& a, const Team& b) {
        if (a.points != b.points) return a.points > b.points;
        if (a.diff != b.diff) return a.diff > b.diff;
        return a.code < b.code;
    });

    for (int i = 0; i < 20; ++i) {
        cout << "#" << (i + 1) << " " << teams[i].code << " " << teams[i].name << " "
             << teams[i].played << " " << teams[i].diff << " " << teams[i].points << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

using namespace std;

struct TeamData {
    string rankStr;
    string code;
    string name;
    int played;
    int goalDiff;
    int pts;
};

static string trim(const string& s) {
    size_t start = s.find_first_not_of(" \t\r\n");
    if (start == string::npos) return "";
    size_t end = s.find_last_not_of(" \t\r\n");
    return s.substr(start, end - start + 1);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    vector<TeamData> teams;
    unordered_map<string, int> teamLookup;

    while (teams.size() < 20) {
        string s;
        if (!getline(cin, s)) break;
        s = trim(s);
        if (s.empty() || s[0] != '#') continue;
        TeamData td;
        td.rankStr = s;
        getline(cin, td.code); td.code = trim(td.code);
        getline(cin, td.name); td.name = trim(td.name);
        cin >> td.played >> td.goalDiff >> td.pts;
        string dummy;
        getline(cin, dummy); // consume newline
        teamLookup[td.name] = (int)teams.size();
        teams.push_back(td);
    }

    for (int m = 0; m < 10; ++m) {
        string line;
        while (getline(cin, line)) {
            line = trim(line);
            if (!line.empty()) break;
        }
        if (line.empty()) break;

        size_t sep = line.find(" - ");
        string left = line.substr(0, sep);
        string right = line.substr(sep + 3);

        size_t sp1 = left.rfind(' ');
        string nameA = left.substr(0, sp1);
        int gA = stoi(left.substr(sp1 + 1));

        size_t sp2 = right.find(' ');
        int gB = stoi(right.substr(0, sp2));
        string nameB = right.substr(sp2 + 1);

        int u = teamLookup[nameA];
        int v = teamLookup[nameB];

        teams[u].played += 1;
        teams[v].played += 1;
        teams[u].goalDiff += (gA - gB);
        teams[v].goalDiff += (gB - gA);

        if (gA > gB) {
            teams[u].pts += 3;
        } else if (gA < gB) {
            teams[v].pts += 3;
        } else {
            teams[u].pts += 1;
            teams[v].pts += 1;
        }
    }

    auto cmp = [](const TeamData& a, const TeamData& b) {
        if (a.pts != b.pts) return a.pts > b.pts;
        if (a.goalDiff != b.goalDiff) return a.goalDiff > b.goalDiff;
        return a.code < b.code;
    };

    sort(teams.begin(), teams.end(), cmp);

    for (size_t i = 0; i < teams.size(); ++i) {
        cout << "#" << (i + 1) << " "
             << teams[i].code << " "
             << teams[i].name << " "
             << teams[i].played << " "
             << teams[i].goalDiff << " "
             << teams[i].pts << "\n";
    }

    return 0;
}

