#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int countGreaterOrEqual(const vector<int>& b, int val) {
    int left = 0, right = (int)b.size() - 1;
    int firstIdx = (int)b.size();
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (b[mid] >= val) {
            firstIdx = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return (int)b.size() - firstIdx;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> a(n), b(m);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int j = 0; j < m; ++j) cin >> b[j];
    sort(b.begin(), b.end());
    for (int i = 0; i < n; ++i) {
        int ans = countGreaterOrEqual(b, a[i]);
        cout << ans << (i + 1 == n ? "" : " ");
    }
    cout << "\n[Comparator_Binary Search].\n";
    return 0;
}

