using namespace std;

struct Subject {
    string name;
    int credits;
    double score;
};

struct Student {
    string id;
    string name;
    string className;
    double gpa;
};

bool compareStudents(const Student &a, const Student &b) {
    if (fabs(a.gpa - b.gpa) > 1e-7) {
        return a.gpa > b.gpa;
    }
    return a.id < b.id;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Student> students;
    for (int i = 0; i < n; ++i) {
        Student st;
        cin >> st.id;
        cin.ignore();
        getline(cin, st.name);
        cin >> st.className;
        int m;
        cin >> m;
        double totalScore = 0.0;
        int totalCredits = 0;
        for (int j = 0; j < m; ++j) {
            cin.ignore();
            string subName;
            getline(cin, subName);
            int cred;
            double sc;
            cin >> cred >> sc;
            totalCredits += cred;
            totalScore += cred * sc;
        }
        st.gpa = (totalCredits > 0) ? (totalScore / totalCredits) : 0.0;
        students.push_back(st);
    }

    sort(students.begin(), students.end(), compareStudents);

    for (const auto &st : students) {
        cout << st.id << " " << st.name << " " << st.className << " " << fixed << setprecision(2) << st.gpa << "\n";
    }

    return 0;
}

