    int tinChi;
    double diem;
};

class SinhVien {
public:
    string maSV;
    string hoTen;
    string lop;
    double gpa;

    void tinhGPA(const vector<MonHoc>& ds) {
        int tongTC = 0;
        double tongDiem = 0;
        for (const auto& mh : ds) {
            tongTC += mh.tinChi;
            tongDiem += mh.tinChi * mh.diem;
        }
        gpa = (tongTC == 0) ? 0.0 : (tongDiem / tongTC);
    }
};

