class Rectangle {
private:
    long long width, height;
    string color;
public:
    Rectangle(long long w, long long h, const string& c) : width(w), height(h), color(c) {}

    bool isValid() const {
        return width > 0 && height > 0;
    }

    long long getPerimeter() const {
        return 2 * (width + height);
    }

    long long getArea() const {
        return width * height;
    }

    string getFormattedColor() const {
        string res = color;
        if (!res.empty()) {
            res[0] = toupper(res[0]);
            for (size_t i = 1; i < res.size(); ++i) {
                res[i] = tolower(res[i]);
            }
        }
        return res;
    }
};

