    if (cin >> a >> b >> c) {
        Rectangle rect(a, b, c);
        if (rect.isValid()) {
            cout << rect.getPerimeter() << " " << rect.getArea() << " " << rect.getFormattedColor() << "\n";
        } else {
            cout << "INVALID\n";
        }
    }
    return 0;
}

