string normalizeName(const string& s) {
    stringstream ss(s);
    string word;
    string res = "";
    while (ss >> word) {
        for (int i = 0; i < (int)word.length(); ++i) {
            if (i == 0) word[i] = toupper((unsigned char)word[i]);
            else word[i] = tolower((unsigned char)word[i]);
        }
        if (!res.empty()) res += " ";
        res += word;
    }
    return res;
}

string normalizeDate(const string& s) {
    stringstream ss(s);
    string d, m, y;
    getline(ss, d, '/');
    getline(ss, m, '/');
    getline(ss, y, '/');
    if (d.length() == 1) d = "0" + d;
    if (m.length() == 1) m = "0" + m;
    return d + "/" + m + "/" + y;
}

