using namespace std;

struct NhanVien {
    string id = "00001";
    string name;
    string gender;
    string dob;
    string address;
    string tax;
    string contractDate;

    static string fixDate(string s) {
        size_t first = s.find('/');
        size_t second = s.rfind('/');
        string d = s.substr(0, first);
        string m = s.substr(first + 1, second - first - 1);
        string y = s.substr(second + 1);
        if (d.size() == 1) d = "0" + d;
        if (m.size() == 1) m = "0" + m;
        return d + "/" + m + "/" + y;
    }

    static string fixName(const string& s) {
        string res = "";
        int n = s.size();
        int i = 0;
        while (i < n) {
            while (i < n && s[i] == ' ') i++;
            if (i >= n) break;
            int j = i;
            while (j < n && s[j] != ' ') j++;
            string word = s.substr(i, j - i);
            for (int k = 0; k < (int)word.size(); ++k) {
                if (k == 0) word[k] = toupper((unsigned char)word[k]);
                else word[k] = tolower((unsigned char)word[k]);
            }
            if (!res.empty()) res += " ";
            res += word;
            i = j;
        }
        return res;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    NhanVien nv;
    if (!getline(cin, nv.name)) return 0;
    getline(cin, nv.gender);
    getline(cin, nv.dob);
    getline(cin, nv.address);
    getline(cin, nv.tax);
    getline(cin, nv.contractDate);

    cout << nv.id << " "
         << NhanVien::fixName(nv.name) << " "
         << nv.gender << " "
         << NhanVien::fixDate(nv.dob) << " "
         << nv.address << " "
         << nv.tax << " "
         << NhanVien::fixDate(nv.contractDate) << "\n";

    return 0;
}

