#include <iostream>
#include <vector>
#include <set>
#include <algorithm>

using namespace std;

class IntSet {
private:
    set<int> elements;
public:
    IntSet() {}
    IntSet(const vector<int>& v) {
        for (int x : v) elements.insert(x);
    }
    IntSet unionWith(const IntSet& other) const {
        IntSet res;
        res.elements = this->elements;
        for (int x : other.elements) {
            res.elements.insert(x);
        }
        return res;
    }
    void print() const {
        bool first = true;
        for (int x : elements) {
            if (!first) cout << " ";
            cout << x;
            first = false;
        }
        cout << "\n";
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<int> a(n), b(m);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < m; ++i) cin >> b[i];

    IntSet s1(a), s2(b);
    IntSet s3 = s1.unionWith(s2);
    s3.print();
    return 0;
}

