#include <iostream>
#include <vector>
#include <set>
#include <algorithm>

class IntSet {
private:
    std::set<int> elements;
public:
    IntSet() = default;
    IntSet(const std::vector<int>& arr) {
        for (int x : arr) {
            elements.insert(x);
        }
    }

    IntSet intersection(const IntSet& other) const {
        IntSet res;
        for (int x : elements) {
            if (other.elements.count(x)) {
                res.elements.insert(x);
            }
        }
        return res;
    }

    void print() const {
        bool first = true;
        for (int x : elements) {
            if (!first) std::cout << " ";
            std::cout << x;
            first = false;
        }
        std::cout << "\n";
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n, m;
    if (!(std::cin >> n >> m)) return 0;

    std::vector<int> a(n), b(m);
    for (int i = 0; i < n; ++i) std::cin >> a[i];
    for (int j = 0; j < m; ++j) std::cin >> b[j];

    IntSet s1(a);
    IntSet s2(b);
    IntSet s3 = s1.intersection(s2);
    s3.print();

    return 0;
}

