#include <iostream>
#include <numeric>
#include <algorithm>

using namespace std;

using ll = long long;

ll gcd_ll(ll a, ll b) {
    a = std::abs(a);
    b = std::abs(b);
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

struct Fraction {
    ll num, den;
};

Fraction add(Fraction a, Fraction b) {
    ll n = a.num * b.den + b.num * a.den;
    ll d = a.den * b.den;
    ll g = gcd_ll(n, d);
    n /= g;
    d /= g;
    if (d < 0) {
        n = -n;
        d = -d;
    }
    return {n, d};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        ll a_num, a_den, b_num, b_den;
        cin >> a_num >> a_den >> b_num >> b_den;

        // C = (A + B)^2
        Fraction sum = add({a_num, a_den}, {b_num, b_den});
        Fraction c;
        c.num = sum.num * sum.num;
        c.den = sum.den * sum.den;
        ll g_c = gcd_ll(c.num, c.den);
        c.num /= g_c;
        c.den /= g_c;
        if (c.den < 0) {
            c.num = -c.num;
            c.den = -c.den;
        }

        // D = A * B * C
        ll d_num = a_num * b_num * c.num;
        ll d_den = a_den * b_den * c.den;
        ll g_d = gcd_ll(d_num, d_den);
        d_num /= g_d;
        d_den /= g_d;
        if (d_num < 0 && d_den < 0) {
            d_num = -d_num;
            d_den = -d_den;
        }

        cout << c.num << "/" << c.den << " " << d_num << "/" << d_den << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll my_gcd(ll a, ll b) {
    return std::gcd(std::abs(a), std::abs(b));
}

void solve() {
    ll na, da, nb, db;
    if (!(cin >> na >> da >> nb >> db)) return;

    // Sum A + B
    ll n_sum = na * db + nb * da;
    ll d_sum = da * db;
    ll g_sum = my_gcd(n_sum, d_sum);
    n_sum /= g_sum;
    d_sum /= g_sum;
    if (d_sum < 0) {
        n_sum = -n_sum;
        d_sum = -d_sum;
    }

    // C = (A + B)^2
    ll nc = n_sum * n_sum;
    ll dc = d_sum * d_sum;
    ll gc = my_gcd(nc, dc);
    nc /= gc;
    dc /= gc;

    // D = A * B * C
    ll nd = na * nb * nc;
    ll dd = da * db * dc;
    ll gd = my_gcd(nd, dd);
    nd /= gd;
    dd /= gd;
    if (nd < 0 && dd < 0) {
        nd = -nd;
        dd = -dd;
    }

    cout << nc << "/" << dc << " " << nd << "/" << dd << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    if (cin >> T) {
        while (T--) solve();
    }
    return 0;
}

