using namespace std;

set<string> parseWords(const string& line) {
    set<string> res;
    stringstream ss(line);
    string w;
    while (ss >> w) {
        for (char &c : w) {
            c = tolower((unsigned char)c);
        }
        res.insert(w);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string line1, line2;
    if (!getline(cin, line1)) line1 = "";
    if (!getline(cin, line2)) line2 = "";

    set<string> s1 = parseWords(line1);
    set<string> s2 = parseWords(line2);

    set<string> union_set = s1;
    for (const string& w : s2) {
        union_set.insert(w);
    }

    set<string> inter_set;
    for (const string& w : s1) {
        if (s2.count(w)) {
            inter_set.insert(w);
        }
    }

    bool first = true;
    for (const string& w : union_set) {
        if (!first) cout << " ";
        cout << w;
        first = false;
    }
    cout << "\n";

    first = true;
    for (const string& w : inter_set) {
        if (!first) cout << " ";
        cout << w;
        first = false;
    }
    cout << "\n";

    return 0;
}

