#include <iostream>
#include <vector>

using namespace std;

class Matrix {
private:
    int n, m;
    vector<vector<long long>> a;
public:
    Matrix(int rows = 0, int cols = 0) : n(rows), m(cols), a(rows, vector<long long>(cols, 0)) {}

    void read() {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                cin >> a[i][j];
            }
        }
    }

    Matrix operator*(const Matrix& other) const {
        Matrix res(n, other.m);
        for (int i = 0; i < n; ++i) {
            for (int k = 0; k < m; ++k) {
                for (int j = 0; j < other.m; ++j) {
                    res.a[i][j] += a[i][k] * other.a[k][j];
                }
            }
        }
        return res;
    }

    void print() const {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                cout << a[i][j] << (j + 1 == m ? "" : " ");
            }
            cout << "\n";
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, m, p;
    if (!(cin >> n >> m >> p)) return 0;
    Matrix A(n, m), B(m, p);
    A.read();
    B.read();
    Matrix C = A * B;
    C.print();
    return 0;
}

