#include <iostream>
#include <vector>

using namespace std;

struct Matrix {
    int r, c;
    vector<vector<long long>> data;

    Matrix(int r, int c) : r(r), c(c), data(r, vector<long long>(c, 0)) {}

    Matrix transpose() const {
        Matrix res(c, r);
        for (int i = 0; i < r; ++i) {
            for (int j = 0; j < c; ++j) {
                res.data[j][i] = data[i][j];
            }
        }
        return res;
    }

    Matrix multiply(const Matrix& other) const {
        Matrix res(r, other.c);
        for (int i = 0; i < r; ++i) {
            for (int k = 0; k < c; ++k) {
                for (int j = 0; j < other.c; ++j) {
                    res.data[i][j] += data[i][k] * other.data[k][j];
                }
            }
        }
        return res;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    Matrix A(n, m);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> A.data[i][j];
        }
    }

    Matrix AT = A.transpose();
    Matrix C = A.multiply(AT);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << C.data[i][j] << (j == n - 1 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

