struct MatHang {
    int id;
    string ma;
    string ten;
    string donVi;
    long long giaMua;
    long long giaBan;
    long long loiNhuan;
};

bool cmp(const MatHang& a, const MatHang& b) {
    if (a.loiNhuan != b.loiNhuan) {
        return a.loiNhuan > b.loiNhuan;
    }
    return a.id < b.id;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int m;
    if (!(cin >> m)) return 0;
    string dummy;
    getline(cin, dummy);

    vector<MatHang> ds(m);
    for (int i = 0; i < m; ++i) {
        ds[i].id = i + 1;
        stringstream ss;
        ss << "MH" << setfill('0') << setw(4) << (i + 1);
        ds[i].ma = ss.str();

        getline(cin, ds[i].ten);
        getline(cin, ds[i].donVi);
        cin >> ds[i].giaMua >> ds[i].giaBan;
        getline(cin, dummy);

        ds[i].loiNhuan = ds[i].giaBan - ds[i].giaMua;
    }

    sort(ds.begin(), ds.end(), cmp);

    for (int i = 0; i < m; ++i) {
        cout << ds[i].ma << " " << ds[i].ten << " " << ds[i].donVi << " "
             << ds[i].giaMua << " " << ds[i].giaBan << " " << ds[i].loiNhuan << "\n";
    }

    return 0;
}

#include <cstdio>
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

class Item {
public:
    int id;
    string code;
    string name;
    string unit;
    long long buyPrice;
    long long sellPrice;
    long long profit;

    Item(int id, string name, string unit, long long buy, long long sell)
        : id(id), name(name), unit(unit), buyPrice(buy), sellPrice(sell) {
        profit = sell - buy;
        char buf[16];
        sprintf(buf, "MH%04d", id);
        code = string(buf);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Item> items;
    items.reserve(n);

    string line;
    getline(cin, line);

    for (int i = 1; i <= n; ++i) {
        string name, unit;
        long long buy, sell;
        getline(cin, name);
        getline(cin, unit);
        cin >> buy >> sell;
        getline(cin, line);
        items.emplace_back(i, name, unit, buy, sell);
    }

    stable_sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        return a.profit > b.profit;
    });

    for (const auto& it : items) {
        cout << it.code << " " << it.name << " " << it.unit << " "
             << it.buyPrice << " " << it.sellPrice << " " << it.profit << "\n";
    }

    return 0;
}

