struct Date {
    int d, m, y;
    bool operator<(const Date& other) const {
        if (y != other.y) return y < other.y;
        if (m != other.m) return m < other.m;
        return d < other.d;
        }
    bool operator==(const Date& other) const {
        return d == other.d && m == other.m && y == other.y;
    }
};

Date parseDate(const string& s) {
    int d, m, y;
    char c1, c2;
    stringstream ss(s);
    ss >> d >> c1 >> m >> c2 >> y;
    return {d, m, y};
}

string formatDate(const Date& dt) {
    stringstream ss;
    ss << setfill('0') << setw(2) << dt.d << "/"
       << setfill('0') << setw(2) << dt.m << "/"
       << setw(4) << dt.y;
    return ss.str();
}

