        getline(cin, timeIn);
        getline(cin, timeOut);

        int totalIn = parseTime(timeIn);
        int totalOut = parseTime(timeOut);
        list[i].durationMinutes = totalOut - totalIn;
        list[i].hours = list[i].durationMinutes / 60;
        list[i].minutes = list[i].durationMinutes % 60;
    }

    sort(list.begin(), list.end(), [](const Gamer& a, const Gamer& b) {
        if (a.durationMinutes != b.durationMinutes) {
