const long long MOD = 1000000007LL;

long long solve(long long n, long long k) {
    if (k == 0) return 1;
    long long half = solve(n, k / 2);
    long long res = (half * half) % MOD;
    if (k % 2 != 0) {
        res = (res * (n % MOD)) % MOD;
    }
    return res;
}

