#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Node {
    long long sum;
    long long pref;
    long long suff;
    long long ans;
};

Node combine(const Node& left, const Node& right) {
    Node res;
    res.sum = left.sum + right.sum;
    res.pref = max(left.pref, left.sum + right.pref);
    res.suff = max(right.suff, right.sum + left.suff);
    res.ans = max({left.ans, right.ans, left.suff + right.pref});
    return res;
}

Node build(const vector<long long>& a, int l, int r) {
    if (l == r) {
        return {a[l], a[l], a[l], a[l]};
    }
    int mid = l + (r - l) / 2;
    Node left = build(a, l, mid);
    Node right = build(a, mid + 1, r);
    return combine(left, right);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    Node total = build(a, 0, n - 1);
    cout << total.ans << "\n";
    return 0;
}

