int findKth(const vector<int>& a, int a_start, const vector<int>& b, int b_start, int k) {
    int n = a.size() - a_start;
    int m = b.size() - b_start;

    if (n > m) {
        return findKth(b, b_start, a, a_start, k);
    }
    if (n == 0) {
        return b[b_start + k - 1];
    }
    if (k == 1) {
        return min(a[a_start], b[b_start]);
    }

    int i = min(n, k / 2);
    int j = min(m, k / 2);

    if (a[a_start + i - 1] < b[b_start + j - 1]) {
        return findKth(a, a_start + i, b, b_start, k - i);
    } else {
        return findKth(a, a_start, b, b_start + j, k - j);
    }
}

