bool binarySearch(const vector<int>& a, int k) {
    int left = 0, right = (int)a.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] == k) return true;
        if (a[mid] < k) left = mid + 1;
        else right = mid - 1;
    }
    return false;
}

