const long long MOD = 1000000007;
map<long long, long long> F;

long long fib(long long n) {
    if (n == 0) return 0;
    if (n == 1 || n == 2) return 1;
    if (F.count(n)) return F[n];
    long long k = n / 2;
    if (n % 2 == 0) {
        long long fk = fib(k);
        long long fk1 = fib(k - 1);
        return F[n] = (fk * ((2 * fk1 % MOD + fk) % MOD)) % MOD;
    } else {
        long long fk = fib(k);
        long long fk1 = fib(k + 1);
        return F[n] = ((fk * fk) % MOD + (fk1 * fk1) % MOD) % MOD;
    }
}

