long long merge_and_count(vector<int>& a, vector<int>& temp, int left, int mid, int right) {
    int i = left;
    int j = mid + 1;
    int k = left;
    long long inv_count = 0;

    while (i <= mid && j <= right) {
        if (a[i] <= a[j]) {
            temp[k++] = a[i++];
        } else {
            temp[k++] = a[j++];
            inv_count += (mid - i + 1);
        }
    }

    while (i <= mid) {
        temp[k++] = a[i++];
    }

    while (j <= right) {
        temp[k++] = a[j++];
    }

    for (i = left; i <= right; ++i) {
        a[i] = temp[i];
    }

    return inv_count;
}

long long merge_sort(vector<int>& a, vector<int>& temp, int left, int right) {
    long long inv_count = 0;
    if (left < right) {
        int mid = left + (right - left) / 2;
        inv_count += merge_sort(a, temp, left, mid);
        inv_count += merge_sort(a, temp, mid + 1, right);
        inv_count += merge_and_count(a, temp, left, mid, right);
    }
    return inv_count;
}

