const int MAX_VAL = 1000000;
int bit[MAX_VAL + 1];

void update(int idx, int val) {
    for (; idx <= MAX_VAL; idx += idx & -idx) {
        bit[idx] += val;
    }
}

int query(int idx) {
    int sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

