long long count_ones(long long n, long long l, long long r, long long ql, long long qr) {
    if (ql > r || qr < l || n == 0) return 0;
    if (n == 1) return 1;

    long long mid = (l + r) / 2;
    long long ans = 0;

    // Nửa trái
    if (ql < mid) {
        ans += count_ones(n / 2, l, mid - 1, ql, min(qr, mid - 1));
