#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int n;
long long k;

vector<vector<long long>> multiply(const vector<vector<long long>>& A, const vector<vector<long long>>& B) {
    vector<vector<long long>> C(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            long long sum = 0;
            for (int p = 0; p < n; p++) {
                sum = (sum + A[i][p] * B[p][j]) % MOD;
            }
            C[i][j] = sum;
        }
    }
    return C;
}

vector<vector<long long>> matPow(vector<vector<long long>> A, long long exp) {
    vector<vector<long long>> res(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) res[i][i] = 1;
    while (exp > 0) {
        if (exp % 2 == 1) {
            res = multiply(res, A);
        }
        A = multiply(A, A);
        exp /= 2;
    }
    return res;
}

int main() {
    if (!(cin >> n >> k)) return 0;
    vector<vector<long long>> A(n, vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> A[i][j];
            A[i][j] %= MOD;
        }
    }
    vector<vector<long long>> ansMat = matPow(A, k);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        total = (total + ansMat[i][n - 1]) % MOD;
    }
    cout << total << endl;
    return 0;
}

