#include <iostream>
#include <string>
#include <stack>

using namespace std;

int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

bool isOperand(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (!(cin >> s)) return 0;
    string res = "";
    stack<char> st;
    for (char c : s) {
        if (isOperand(c)) {
            res += c;
        } else if (c == '(') {
            st.push(c);
        } else if (c == ')') {
            while (!st.empty() && st.top() != '(') {
                res += st.top();
                st.pop();
            }
            if (!st.empty()) st.pop(); // pop '('
        } else {
            // operator
            while (!st.empty() && precedence(st.top()) >= precedence(c)) {
                res += st.top();
                st.pop();
            }
            st.push(c);
        }
    }
    while (!st.empty()) {
        res += st.top();
        st.pop();
    }
    cout << res << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

using namespace std;

int getPriority(char c) {
    switch (c) {
        case '*':
        case '/':
            return 2;
        case '+':
        case '-':
            return 1;
        default:
            return 0;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string expr;
    if (!(cin >> expr)) return 0;
    vector<char> opStack;
    string postfix = "";
    for (size_t i = 0; i < expr.length(); ++i) {
        char ch = expr[i];
        if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
            postfix.push_back(ch);
        } else if (ch == '(') {
            opStack.push_back(ch);
        } else if (ch == ')') {
            while (!opStack.empty() && opStack.back() != '(') {
                postfix.push_back(opStack.back());
                opStack.pop_back();
            }
            if (!opStack.empty() && opStack.back() == '(') {
                opStack.pop_back();
            }
        } else {
            while (!opStack.empty() && getPriority(opStack.back()) >= getPriority(ch)) {
                postfix.push_back(opStack.back());
                opStack.pop_back();
            }
            opStack.push_back(ch);
        }
    }
    while (!opStack.empty()) {
        postfix.push_back(opStack.back());
        opStack.pop_back();
    }
    cout << postfix << "\n";
    return 0;
}

