        for (int j = 0; j < m; ++j) {
            int val;
            cin >> val;
            if (val == 1) {
                heights[j]++;
            } else {
                heights[j] = 0;
            }
        }
        ans = max(ans, largestRectangleArea(heights));
    }
    cout << ans << "\n";
    return 0;
}

