    vector<vector<int>> a(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
        }
    }

    vector<int> h(m, 0);
    vector<int> left(m), right(m);
    vector<int> st(m + 1);
    int max_area = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (a[i][j] == 1) {
                h[j]++;
            } else {
                h[j] = 0;
            }
        }

        int top = 0;
        for (int j = 0; j < m; ++j) {
            while (top > 0 && h[st[top - 1]] >= h[j]) {
                top--;
            }
            left[j] = (top == 0) ? 0 : (st[top - 1] + 1);
            st[top++] = j;
        }

        top = 0;
        for (int j = m - 1; j >= 0; --j) {
            while (top > 0 && h[st[top - 1]] >= h[j]) {
                top--;
            }
            right[j] = (top == 0) ? (m - 1) : (st[top - 1] - 1);
            st[top++] = j;
        }

        for (int j = 0; j < m; ++j) {
            max_area = max(max_area, h[j] * (right[j] - left[j] + 1));
        }
    }

