#include <iostream>
#include <string>
#include <vector>
#include <queue>

using namespace std;

string solve(int n) {
    if (n == 1) return "8";
    vector<int> parent_rem(n, -1);
    vector<char> parent_digit(n, ' ');
    vector<bool> visited(n, false);

    queue<int> q;
    int start_rem = 8 % n;
    if (start_rem == 0) return "8";

    visited[start_rem] = true;
    parent_digit[start_rem] = '8';
    q.push(start_rem);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (u == 0) break;

        int next_rem0 = (u * 10) % n;
        if (!visited[next_rem0]) {
            visited[next_rem0] = true;
            parent_rem[next_rem0] = u;
            parent_digit[next_rem0] = '0';
            q.push(next_rem0);
            if (next_rem0 == 0) break;
        }

        int next_rem8 = (u * 10 + 8) % n;
        if (!visited[next_rem8]) {
            visited[next_rem8] = true;
            parent_rem[next_rem8] = u;
            parent_digit[next_rem8] = '8';
            q.push(next_rem8);
            if (next_rem8 == 0) break;
        }
    }

    string res = "";
    int curr = 0;
    while (curr != -1) {
        res += parent_digit[curr];
        curr = parent_rem[curr];
    }
    string ans = "";
    for (int i = (int)res.size() - 1; i >= 0; --i) {
        ans += res[i];
    }
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            int n;
            cin >> n;
            cout << solve(n) << "\n";
        }
    }
    return 0;
}

