    if (!(cin >> t)) return;
    while (t--) {
        int n;
        cin >> n;
        vector<int> p(n, -2);
        vector<char> d(n, ' ');
        queue<int> q;

        int r0 = 8 % n;
        p[r0] = -1;
        d[r0] = '8';
        q.push(r0);

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (u == 0) break;

            int rems[2] = {(u * 10) % n, (u * 10 + 8) % n};
            char digits[2] = {'0', '8'};

            for (int i = 0; i < 2; ++i) {
                int nr = rems[i];
                if (p[nr] == -2) {
                    p[nr] = u;
                    d[nr] = digits[i];
                    q.push(nr);
                    if (nr == 0) goto found;
                }
            }
        }
    found:
        string res = "";
        for (int at = 0; at != -1; at = p[at]) {
            res.push_back(d[at]);
        }
        reverse(res.begin(), res.end());
        cout << res << "\n";
    }
}

