    int pos = -1;
    for (int i = 0; i < m; ++i) {
        if (s[i] >= '2') {
            pos = i;
            break;
        }
    }

    string s_mod = s;
    if (pos != -1) {
        for (int i = pos; i < m; ++i) {
            s_mod[i] = '1';
        }
    }

    // Tinh gia tri nhi phan cua tien to chu so 0 va 1
    // Neu s_mod chi co 0 va 1, ta can so BDN < N.
    // Neu s da bi sua o pos (vi co chu so >= 2), moi so BDN duoc tao boi s_mod se <= N.
    // Thuc te: ta chuyen s_mod (toan 0 va 1) sang gia tri thap phan tu ma nhi phan.
    // Neu khong bi sua (n ban dau chi gom 0 va 1), ta can nho hon n nen ket qua la val - 1.
    // Neu bi sua (tuc la s[pos] >= 2), thi tat ca cac so tao boi xau nhi phan <= s_mod deu < n, nen ket qua la val.

    long long val = 0;
    for (int i = 0; i < m; ++i) {
        val = val * 2 + (s_mod[i] - '0');
    }

    if (pos == -1) {
        return val - 1;
    } else {
        return val;
    }
}

