}

#include <iostream>
#include <vector>
#include <string>

using namespace std;

// Su dung queue / bfs hoac quy hoach dong de dem so BDN nho hon N
// Vi gia tri N len toi 2^63 (khoang 19 chu so), moi so BDN chi la bieu dien nhi phan duoc xem nhu thap phan.
long long countBDN(unsigned long long n) {
    string s = to_string(n);
    int len = s.length();

    // Duyet tim vi tri chu so dau tien >= 2
    int first_ge_2 = -1;
    for (int i = 0; i < len; ++i) {
        if (s[i] >= '2') {
            first_ge_2 = i;
            break;
        }
    }

    long long ans = 0;
    if (first_ge_2 != -1) {
        for (int i = 0; i < first_ge_2; ++i) {
            ans = (ans << 1) | (s[i] - '0');
        }
        for (int i = first_ge_2; i < len; ++i) {
            ans = (ans << 1) | 1;
        }
    } else {
        for (int i = 0; i < len; ++i) {
            ans = (ans << 1) | (s[i] - '0');
        }
        ans -= 1; // can strictly less than N
    }
    return ans;
}

