struct State {
    int rem;
    int parent;
    char d;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n;
        cin >> n;
        vector<bool> visited(n, false);
        vector<State> tree;
        queue<int> q;

        tree.push_back({1 % n, -1, '1'});
        visited[1 % n] = true;
        q.push(0);

        int target_idx = -1;
        while (!q.empty()) {
            int curr_idx = q.front();
            q.pop();

            if (tree[curr_idx].rem == 0) {
                target_idx = curr_idx;
                break;
            }

            int rem0 = (tree[curr_idx].rem * 10) % n;
            if (!visited[rem0]) {
                visited[rem0] = true;
                tree.push_back({rem0, curr_idx, '0'});
                q.push((int)tree.size() - 1);
            }

            int rem1 = (tree[curr_idx].rem * 10 + 1) % n;
            if (!visited[rem1]) {
                visited[rem1] = true;
                tree.push_back({rem1, curr_idx, '1'});
                q.push((int)tree.size() - 1);
            }
        }

        string res = "";
        while (target_idx != -1) {
            res += tree[target_idx].d;
            target_idx = tree[target_idx].parent;
        }
        reverse(res.begin(), res.end());
        cout << res << "\n";
    }
    return 0;
}

