const int MAX = 20005;

int bfs(int s, int t) {
    if (s == t) return 0;
    if (s > t) return s - t;
    vector<int> dist(MAX + 1, -1);
    queue<int> q;
    dist[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (u == t) return dist[u];
        // Thao tác u - 1
        if (u - 1 > 0 && dist[u - 1] == -1) {
            dist[u - 1] = dist[u] + 1;
            q.push(u - 1);
        }
        // Thao tác u * 2
        if (u * 2 <= MAX && dist[u * 2] == -1) {
            dist[u * 2] = dist[u] + 1;
            q.push(u * 2);
        }
    }
    return -1;
}

