#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

void solve() {
    long long k;
    if (!(cin >> k)) return;
    string s;
    cin >> s;
    long long n = s.length();
    if (k >= n) {
        cout << 0 << "\n";
        return;
    }
    vector<long long> cnt(256, 0);
    for (char c : s) {
        cnt[(unsigned char)c]++;
    }
    vector<long long> counts;
    for (int i = 0; i < 256; ++i) {
        if (cnt[i] > 0) counts.push_back(cnt[i]);
    }
    sort(counts.rbegin(), counts.rend());

    // Giảm dần các phần tử lớn nhất bằng tìm kiếm nhị phân hoặc mô phỏng phân phối
    // Vì tổng tần suất tối đa 10^6, ta có thể dùng kỹ thuật chặt nhị phân ngưỡng H
    long long low = 0, high = n, H = 0;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        long long needed = 0;
        for (long long c : counts) {
            if (c > mid) needed += (c - mid);
        }
        if (needed <= k) {
            H = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    long long rem_k = k;
    for (size_t i = 0; i < counts.size(); ++i) {
        if (counts[i] > H) {
            rem_k -= (counts[i] - H);
            counts[i] = H;
        }
    }
    for (size_t i = 0; i < counts.size(); ++i) {
        if (rem_k > 0 && counts[i] == H && counts[i] > 0) {
            counts[i]--;
            rem_k--;
        }
    }

    unsigned long long ans = 0;
    for (long long c : counts) {
        ans += (unsigned long long)c * c;
    }
    cout << ans << "\n";
}

