    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

#include <iostream>
#include <queue>
#include <unordered_map>
#include <cmath>

using namespace std;

int solve(int n) {
    if (n <= 1) return 0;
    queue<pair<int, int>> q;
    unordered_map<int, int> dist;

    q.push({n, 0});
    dist[n] = 0;

    while (!q.empty()) {
        auto [u, d] = q.front();
        q.pop();

        if (u == 1) return d;

        // Operation a
        if (u - 1 >= 1 && (dist.find(u - 1) == dist.end() || dist[u - 1] > d + 1)) {
            dist[u - 1] = d + 1;
            q.push({u - 1, d + 1});
        }

        // Operation b
        for (int i = 2; i * i <= u; ++i) {
            if (u % i == 0) {
                int v = max(i, u / i); // which is u / i since i <= u / i
                if (dist.find(v) == dist.end() || dist[v] > d + 1) {
                    dist[v] = d + 1;
                    q.push({v, d + 1});
                }
            }
        }
    }
    return 0;
}

