#include <map>

using namespace std;

void solve() {
    int n;
    cin >> n;
    if (n <= 1) {
        cout << 0 << "\n";
        return;
    }
    queue<int> q;
    map<int, int> d;
    q.push(n);
    d[n] = 0;

    while (!q.empty()) {
        int cur = q.front();
        int steps = d[cur];
        q.pop();

        if (cur == 1) {
            cout << steps << "\n";
            return;
        }

        // Op a: cur - 1
        if (cur > 1 && d.find(cur - 1) == d.end()) {
            d[cur - 1] = steps + 1;
            q.push(cur - 1);
        }

        // Op b: divisors
        for (int i = 2; 1LL * i * i <= cur; ++i) {
            if (cur % i == 0) {
                int next_val = cur / i;
                if (d.find(next_val) == d.end()) {
                    d[next_val] = steps + 1;
                    q.push(next_val);
                }
            }
        }
    }
}

