const int MAX_VAL = 10000;
bool is_prime[MAX_VAL];
vector<int> adj[MAX_VAL];

void sieve() {
    for (int i = 2; i < MAX_VAL; ++i) is_prime[i] = true;
    for (int p = 2; p * p < MAX_VAL; ++p) {
        if (is_prime[p]) {
            for (int i = p * p; i < MAX_VAL; i += p)
                is_prime[i] = false;
        }
    }
}

void build_graph() {
    vector<int> primes;
    for (int i = 1000; i < MAX_VAL; ++i) {
        if (is_prime[i]) primes.push_back(i);
    }

    for (int u : primes) {
        string s = to_string(u);
        for (int i = 0; i < 4; ++i) {
            char orig = s[i];
            for (char c = '0'; c <= '9'; ++c) {
                if (i == 0 && c == '0') continue;
                if (c == orig) continue;
                s[i] = c;
                int v = stoi(s);
                if (is_prime[v]) {
                    adj[u].push_back(v);
                }
            }
            s[i] = orig;
        }
    }
}

int bfs(int start, int target) {
    if (start == target) return 0;
    vector<int> dist(MAX_VAL, -1);
    queue<int> q;

    dist[start] = 0;
    q.push(start);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (u == target) return dist[u];

        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (v == target) return dist[v];
                q.push(v);
            }
        }
    }

    return dist[target];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    sieve();
    build_graph();

    int q;
    if (!(cin >> q)) return 0;
    while (q--) {
        int s, t;
        cin >> s >> t;
        cout << bfs(s, t) << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <cstring>

using namespace std;

bool is_prime_num(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int d[10000];
bool prime_table[10000];

void solve() {
    int s, t;
    cin >> s >> t;
    if (s == t) {
        cout << 0 << "\n";
        return;
    }
    memset(d, -1, sizeof(d));
    queue<int> q;
    d[s] = 0;
    q.push(s);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (u == t) {
            cout << d[u] << "\n";
            return;
        }

        string s_val = to_string(u);
        for (int i = 0; i < 4; ++i) {
            char old_c = s_val[i];
            for (char c = '0'; c <= '9'; ++c) {
                if (i == 0 && c == '0') continue;
                if (c == old_c) continue;
                s_val[i] = c;
                int next_val = stoi(s_val);
                if (prime_table[next_val] && d[next_val] == -1) {
                    d[next_val] = d[u] + 1;
                    if (next_val == t) {
                        cout << d[next_val] << "\n";
                        return;
                    }
                    q.push(next_val);
                }
            }
            s_val[i] = old_c;
        }
    }
    cout << -1 << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    for (int i = 1000; i <= 9999; ++i) {
        prime_table[i] = is_prime_num(i);
    }
    int T;
    if (cin >> T) {
        while (T--) {
            solve();
        }
    }
    return 0;
}

