const int dx[] = {-2, -2, -1, -1, 1, 1, 2, 2};
const int dy[] = {-1, 1, -2, 2, -2, 2, -1, 1};

void solve() {
    string st, en;
    if (!(cin >> st >> en)) return;
    int sx = st[0] - 'a', sy = st[1] - '1';
    int tx = en[0] - 'a', ty = en[1] - '1';

    if (sx == tx && sy == ty) {
        cout << 0 << "\n";
        return;
    }

    vector<vector<int>> dist(8, vector<int>(8, -1));
    queue<pair<int, int>> q;

    dist[sx][sy] = 0;
    q.push({sx, sy});

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if (x == tx && y == ty) {
