using namespace std;

int moves[8][2] = {
    {1, 2}, {1, -2}, {-1, 2}, {-1, -2},
    {2, 1}, {2, -1}, {-2, 1}, {-2, -1}
};

int bfs(int r1, int c1, int r2, int c2) {
    if (r1 == r2 && c1 == c2) return 0;
    int d[8][8];
    memset(d, -1, sizeof(d));
    d[r1][c1] = 0;
    queue<pair<int, int>> q;
    q.push({r1, c1});

    while (!q.empty()) {
        pair<int, int> curr = q.front();
        q.pop();
        int r = curr.first, c = curr.second;

        if (r == r2 && c == c2) return d[r][c];

        for (int i = 0; i < 8; ++i) {
            int nr = r + moves[i][0];
            int nc = c + moves[i][1];
            if (nr >= 0 && nr < 8 && nc >= 0 && nc < 8 && d[nr][nc] == -1) {
                d[nr][nc] = d[r][c] + 1;
                q.push({nr, nc});
            }
        }
    }
    return -1;
}

