            int r2 = b[0] - 'a', c2 = b[1] - '1';
            cout << bfs(r1, c1, r2, c2) << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>

using namespace std;

void solve() {
    int m, n;
    if (!(cin >> m >> n)) return;
    vector<vector<int>> a(m, vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    if (m == 1 && n == 1) {
        cout << 0 << "\n";
        return;
    }

    vector<vector<int>> dist(m, vector<int>(n, -1));
    queue<pair<int, int>> q;

    dist[0][0] = 0;
    q.push({0, 0});

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();

        if (r == m - 1 && c == n - 1) {
            cout << dist[r][c] << "\n";
            return;
        }

        int step = a[r][c];
        if (step <= 0) continue;

        // Right
        if (c + step < n && dist[r][c + step] == -1) {
            dist[r][c + step] = dist[r][c] + 1;
            q.push({r, c + step});
        }
        // Down
        if (r + step < m && dist[r + step][c] == -1) {
            dist[r + step][c] = dist[r][c] + 1;
            q.push({r + step, c});
        }
    }

    cout << -1 << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

#include <cstdio>
#include <vector>

using namespace std;

struct Point {
    int r, c;
};

void run_case() {
    int m, n;
    if (scanf("%d %d", &m, &n) != 2) return;
    vector<int> a(m * n);
    for (int i = 0; i < m * n; ++i) {
        scanf("%d", &a[i]);
    }

    if (m == 1 && n == 1) {
        printf("0\n");
        return;
    }

    vector<int> dist(m * n, -1);
    vector<Point> q(m * n);
    int head = 0, tail = 0;

    dist[0] = 0;
    q[tail++] = {0, 0};

    int ans = -1;
    while (head < tail) {
        Point cur = q[head++];
        int r = cur.r;
        int c = cur.c;
        int d = dist[r * n + c];

        if (r == m - 1 && c == n - 1) {
            ans = d;
            break;
        }

        int val = a[r * n + c];
        if (val <= 0) continue;

        // Move right
        int nc = c + val;
        if (nc < n && dist[r * n + nc] == -1) {
            dist[r * n + nc] = d + 1;
            q[tail++] = {r, nc};
        }

        // Move down
        int nr = r + val;
        if (nr < m && dist[nr * n + c] == -1) {
            dist[nr * n + c] = d + 1;
            q[tail++] = {nr, c};
        }
    }

    printf("%d\n", ans);
}

int main() {
    int t;
    if (scanf("%d", &t) == 1) {
        while (t--) {
            run_case();
        }
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

bool isValid(int n) {
    if (n <= 0) return false;
    int mask = 0;
    while (n > 0) {
        int d = n % 10;
        if (d > 5) return false;
        if (mask & (1 << d)) return false;
        mask |= (1 << d);
        n /= 10;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    const int MAXA = 100000;
    vector<int> pref(MAXA + 1, 0);
    for (int i = 1; i <= MAXA; ++i) {
        pref[i] = pref[i - 1] + (isValid(i) ? 1 : 0);
    }
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int l, r;
        cin >> l >> r;
        if (l == 0) l = 1;
        if (l > r) {
            cout << 0 << "\n";
        } else {
            cout << pref[r] - pref[l - 1] << "\n";
        }
    }
    return 0;
}

