    for (int d = 1; d <= 5; ++d) {
        q.push({d, 1 << d});
    }
    while (!q.empty()) {
        pair<int, int> cur = q.front();
        q.pop();
        int u = cur.first;
        int mask = cur.second;
        if (u <= 100000) {
            valid_nums.push_back(u);
        }
        for (int d = 0; d <= 5; ++d) {
            if (!(mask & (1 << d))) {
                long long nxt = 1LL * u * 10 + d;
                if (nxt <= 100000) {
                    q.push({(int)nxt, mask | (1 << d)});
                }
            }
        }
    }
    sort(valid_nums.begin(), valid_nums.end());

    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int l, r;
        cin >> l >> r;
        if (l == 0) l = 1;
        if (l > r) {
            cout << 0 << "\n";
            continue;
        }
        auto it1 = lower_bound(valid_nums.begin(), valid_nums.end(), l);
        auto it2 = upper_bound(valid_nums.begin(), valid_nums.end(), r);
        cout << (it2 - it1) << "\n";
    }
