using namespace std;

string formatNumber(double val) {
    if (fabs(val) < 1e-7) return "0";
    ostringstream oss;
    oss << fixed << setprecision(5) << val;
    string s = oss.str();
    s.erase(s.find_last_not_of('0') + 1, string::npos);
    if (!s.empty() && s.back() == '.') {
        s.pop_back();
    }
    if (s == "-0") s = "0";
    return s;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double x1, y1, x2, y2;
    if (!(cin >> x1 >> y1 >> x2 >> y2)) return 0;

    double m = (y2 - y1) / (x2 - x1);
    double b = y1 - m * x1;

    if (fabs(m) < 1e-7) m = 0.0;
    if (fabs(b) < 1e-7) b = 0.0;

    cout << "y = ";

    bool has_x = false;
    if (fabs(m) > 1e-7) {
        has_x = true;
        if (fabs(m - 1.0) < 1e-7) {
            cout << "x";
        } else if (fabs(m - (-1.0)) < 1e-7) {
            cout << "-x";
        } else {
            cout << formatNumber(m) << "x";
        }
    }

    if (fabs(b) > 1e-7) {
        if (has_x) {
            if (b > 0) {
                cout << " + " << formatNumber(b);
            } else {
                cout << " - " << formatNumber(fabs(b));
            }
        } else {
            cout << formatNumber(b);
        }
    } else {
        if (!has_x) {
            cout << "0";
        }
    }
    cout << "\n";
    return 0;
}

#include <cstdio>
