using namespace std;

static string cleanNum(double v) {
    if (abs(v) < 1e-7) return "0";
    char buf[64];
    snprintf(buf, sizeof(buf), "%.5f", v);
    string str = buf;
    while (str.find('.') != string::npos && (str.back() == '0' || str.back() == '.')) {
        char last = str.back();
        str.pop_back();
        if (last == '.') break;
    }
    if (str == "-0") return "0";
    return str;
}

int main() {
    double x1, y1, x2, y2;
    if (scanf("%lf %lf %lf %lf", &x1, &y1, &x2, &y2) == 4) {
        double m = (y2 - y1) / (x2 - x1);
        double b = y1 - m * x1;

        if (abs(m) < 1e-7) m = 0;
        if (abs(b) < 1e-7) b = 0;

        string res = "y = ";
        bool printed_m = false;

        if (abs(m) >= 1e-7) {
            printed_m = true;
            if (abs(m - 1.0) < 1e-7) {
                res += "x";
            } else if (abs(m + 1.0) < 1e-7) {
                res += "-x";
            } else {
                res += cleanNum(m) + "x";
            }
        }

        if (abs(b) >= 1e-7) {
            if (printed_m) {
                if (b > 0) {
                    res += " + " + cleanNum(b);
                } else {
                    res += " - " + cleanNum(-b);
                }
            } else {
                res += cleanNum(b);
            }
        } else if (!printed_m) {
            res += "0";
        }

        printf("%s\n", res.c_str());
    }
    return 0;
}

