    vector<int> queries(T);
    int max_n = 0;
    for (int i = 0; i < T; ++i) {
        cin >> queries[i];
        if (queries[i] > max_n) max_n = queries[i];
    }

    // Tiền xử lý tổng tiền tố để trả lời các truy vấn O(1)
    vector<double> prefix_sum(max_n + 1, 0.0);
    for (int i = 1; i <= max_n; ++i) {
        prefix_sum[i] = prefix_sum[i - 1] + 1.0 / ((double)i * i);
    }

    cout << fixed << setprecision(6);
    for (int i = 0; i < T; ++i) {
        int n = queries[i];
        double pi_approx = sqrt(6.0 * prefix_sum[n]);
        cout << pi_approx << "\n";
    }

    return 0;
}

