int main() {
    int year, start_day;
    if (scanf("%d %d", &year, &start_day) != 2) return 0;

    if (is_leap(year)) {
        MONTH_DAYS[1] = 29;
    } else {
        MONTH_DAYS[1] = 28;
    }

    int current_day = start_day;

    for (int m = 0; m < 12; ++m) {
        char header[100];
        sprintf(header, "%s %d", MONTHS[m], year);
        int len = strlen(header);
        int spaces = (47 - len) / 2;
        for (int s = 0; s < spaces; ++s) {
            putchar(' ');
        }
        printf("%s\n", header);
        printf("-----------------------------------------------\n");
        printf("  Sun    Mon    Tue    Wed    Thu    Fri    Sat\n");

        for (int i = 0; i < current_day; ++i) {
            printf("       ");
        }

        int total_days = MONTH_DAYS[m];
        for (int day = 1; day <= total_days; ++day) {
            printf("  %5d", day);
            current_day++;
            if (current_day == 7) {
                putchar('\n');
                current_day = 0;
            }
        }
        if (current_day != 0) {
            putchar('\n');
        }
    }

    return 0;
}

