#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    // Rationalize the denominator:
    // 1 / (a - b) = (a^2 + a*b + b^2) / (a^3 - b^3)
    // Here a = cbrt(k), b = cbrt(k - 6), so a^3 - b^3 = k - (k - 6) = 6.
    // Each term is (cbrt(k)^2 + cbrt(k)*cbrt(k-6) + cbrt(k-6)^2) / 6.0
    double total = 0.0;
    for (int k = 9; k <= 99; k += 6) {
        double a = std::cbrt(k);
        double b = std::cbrt(k - 6);
        double term = (a * a + a * b + b * b) / 6.0;
        total += term;
    }
    std::cout << std::fixed << std::setprecision(6) << total << "\n";
    return 0;
}

