#include <iostream>

long long calculate_profit(long long n) {
    if (n <= 0) return 0;
    long long profit = 0;
    if (n <= 1000) {
        profit = n * 1;
    } else if (n <= 5000) {
        profit = 1000 * 1 + (n - 1000) * 2;
    } else {
        profit = 1000 * 1 + 4000 * 2 + (n - 5000) * 5;
    }
    return profit;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    long long target;
    if (!(std::cin >> target)) return 0;
    if (target <= 0) {
        std::cout << 0 << "\n";
        return 0;
    }

    long long low = 0, high = 1000000000LL;
    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (calculate_profit(mid) >= target) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    std::cout << ans << "\n";
    return 0;
}

