const int N = 3;

void addMatrix(const double a[][N], const double b[][N], double c[][N]) {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            c[i][j] = a[i][j] + b[i][j];
        }
    }
}

