        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cin >> b[i][j];
        }
    }

    addMatrix(a, b, c);

    std::cout << std::fixed << std::setprecision(1);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cout << c[i][j] << (j == N - 1 ? "" : " ");
        }
