using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int s;
    double income;
    if (!(cin >> s >> income)) return 0;

    double rates[6] = {0.10, 0.15, 0.25, 0.28, 0.33, 0.36};
    int brackets[4][5] = {
        {8350, 33950, 82250, 171550, 372950},
        {16700, 67900, 137050, 208850, 372950},
        {8350, 33950, 68525, 104425, 186475},
        {11950, 45500, 117450, 190200, 372950}
    };

    double tax = 0;
    double prev = 0;
    for (int i = 0; i < 5; ++i) {
        if (income > brackets[s][i]) {
            tax += (brackets[s][i] - prev) * rates[i];
            prev = brackets[s][i];
        } else {
            tax += (income - prev) * rates[i];
            prev = income;
            break;
        }
    }
    if (income > brackets[s][4]) {
        tax += (income - brackets[s][4]) * rates[5];
    }

    cout << fixed << setprecision(2) << tax << "\n";
    return 0;
}

