#include <iostream>
#include <iomanip>

const int N = 3;

void multiplyMatrix(const double a[][N], const double b[][N], double c[][N]) {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            c[i][j] = 0.0;
            for (int k = 0; k < N; ++k) {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    double a[N][N], b[N][N], c[N][N];
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cin >> a[i][j];
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cin >> b[i][j];
        }
    }

    multiplyMatrix(a, b, c);

    std::cout << std::fixed << std::setprecision(1);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cout << c[i][j] << (j == N - 1 ? "" : " ");
        }
        std::cout << "\n";
    }

