};

double dist(const Point& a, const Point& b) {
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

void printDouble(double v) {
    if (abs(v) < 1e-9) v = 0.0;
    cout << fixed << setprecision(1) << v;
}

int main() {
    ios_base::sync_with_stdio(false);
