    }

    double minDist = 1e18;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double d = dist(p[i], p[j]);
            if (d < minDist) {
                minDist = d;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double d = dist(p[i], p[j]);
            if (abs(d - minDist) < 1e-9) {
                cout << "The closest two points are (";
                printDouble(p[i].x);
