                printDouble(p[i].y);
                cout << ") and (";
                printDouble(p[j].x);
                cout << ", ";
                printDouble(p[j].y);
                cout << ")\n";
            }
        }
    }
    cout << "Their distance is " << fixed << setprecision(6) << minDist << "\n";
    return 0;
}

