#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

const double EPS = 1e-6;

bool onLine(double x0, double y0, double x1, double y1, double x2, double y2) {
    return std::abs((x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0)) < EPS;
}

bool sameLine(const double points[][2], int numberOfPoints) {
    if (numberOfPoints <= 2) return true;
    // Find two distinct points to define the line
    int p0 = 0, p1 = -1;
    for (int i = 1; i < numberOfPoints; ++i) {
        if (std::abs(points[i][0] - points[0][0]) > EPS || std::abs(points[i][1] - points[0][1]) > EPS) {
            p1 = i;
            break;
        }
    }
    // If all points coincide
    if (p1 == -1) return true;

    for (int i = 0; i < numberOfPoints; ++i) {
        if (!onLine(points[p0][0], points[p0][1], points[p1][0], points[p1][1], points[i][0], points[i][1])) {
            return false;
        }
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    double points[5][2];
    for (int i = 0; i < 5; ++i) {
        if (!(cin >> points[i][0] >> points[i][1])) return 0;
    }
    if (sameLine(points, 5)) {
        cout << "The five points are on same line\n";
    } else {
        cout << "The five points are not on same line\n";
    }
    return 0;
}

#include <iostream>
#include <cmath>

using namespace std;

const double EPSILON = 1e-6;

struct Point {
    double x, y;
};

bool areCollinear(Point a, Point b, Point c) {
    double crossProduct = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    return std::abs(crossProduct) < EPSILON;
}

int main() {
    Point pts[5];
    for (int i = 0; i < 5; ++i) {
        cin >> pts[i].x >> pts[i].y;
    }

    // Check if every triplet (pts[0], pts[1], pts[i]) is collinear
    // If pts[0] and pts[1] coincide, pick another pair
    int idx1 = 0, idx2 = -1;
    for (int i = 1; i < 5; ++i) {
        if (std::abs(pts[i].x - pts[0].x) > EPSILON || std::abs(pts[i].y - pts[0].y) > EPSILON) {
            idx2 = i;
            break;
        }
    }

    bool collinear = true;
    if (idx2 != -1) {
        for (int i = 0; i < 5; ++i) {
            if (i != idx1 && i != idx2) {
                if (!areCollinear(pts[idx1], pts[idx2], pts[i])) {
                    collinear = false;
                    break;
                }
            }
        }
    }

    if (collinear) {
        cout << "The five points are on same line" << endl;
    } else {
        cout << "The five points are not on same line" << endl;
    }

    return 0;
}

