#include <iostream>
#include <vector>
#include <iomanip>
#include <cmath>

using namespace std;

double minor2x2(double a, double b, double c, double d) {
    return a * d - b * c;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double a[3][3];
    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            cin >> a[r][c];
        }
    }

    // Cofactor matrix elements
    double c00 =  minor2x2(a[1][1], a[1][2], a[2][1], a[2][2]);
    double c01 = -minor2x2(a[1][0], a[1][2], a[2][0], a[2][2]);
    double c02 =  minor2x2(a[1][0], a[1][1], a[2][0], a[2][1]);

    double c10 = -minor2x2(a[0][1], a[0][2], a[2][1], a[2][2]);
    double c11 =  minor2x2(a[0][0], a[0][2], a[2][0], a[2][2]);
    double c12 = -minor2x2(a[0][0], a[0][1], a[2][0], a[2][1]);

    double c20 =  minor2x2(a[0][1], a[0][2], a[1][1], a[1][2]);
    double c21 = -minor2x2(a[0][0], a[0][2], a[1][0], a[1][2]);
    double c22 =  minor2x2(a[0][0], a[0][1], a[1][0], a[1][1]);

    double det = a[0][0] * c00 + a[0][1] * c01 + a[0][2] * c02;

    // Adjugate is the transpose of the cofactor matrix
    double inv[3][3] = {
        {c00 / det, c10 / det, c20 / det},
        {c01 / det, c11 / det, c21 / det},
        {c02 / det, c12 / det, c22 / det}
    };

    cout << fixed << setprecision(4);
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            double val = inv[i][j];
            if (std::abs(val) < 1e-9) {
                val = 0.0;
            }
            cout << val << (j == 2 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}

