using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    double limit;
    if (!(cin >> n >> limit)) return 0;

    vector<double> balance(n);
    vector<vector<double>> loan(n, vector<double>(n, 0.0));
    vector<bool> isSafe(n, true);

    for (int i = 0; i < n; ++i) {
        cin >> balance[i];
        int k;
        cin >> k;
        for (int j = 0; j < k; ++j) {
            int borrower;
            double amount;
            cin >> borrower >> amount;
            loan[i][borrower] = amount;
        }
    }

    bool changed = true;
    while (changed) {
        changed = false;
        for (int i = 0; i < n; ++i) {
            if (isSafe[i]) {
                double totalAsset = balance[i];
                for (int j = 0; j < n; ++j) {
                    if (isSafe[j]) {
                        totalAsset += loan[i][j];
                    }
                }
                if (totalAsset < limit - 1e-9) {
                    isSafe[i] = false;
                    changed = true;
                }
            }
        }
    }

    vector<int> unsafe;
    for (int i = 0; i < n; ++i) {
        if (!isSafe[i]) {
            unsafe.push_back(i);
        }
    }

    if (unsafe.empty()) {
        cout << "None\n";
    } else {
        cout << "Unsafe banks are";
        for (int id : unsafe) {
            cout << " " << id;
        }
        cout << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <iomanip>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    double limit;
    if (!(cin >> n >> limit)) return 0;

    vector<double> balance(n);
    vector<vector<double>> loan(n, vector<double>(n, 0.0));
    vector<double> totalAsset(n, 0.0);
    vector<bool> unsafe(n, false);
    queue<int> q;

    for (int i = 0; i < n; ++i) {
        cin >> balance[i];
        int k;
        cin >> k;
        totalAsset[i] = balance[i];
        for (int j = 0; j < k; ++j) {
            int borrower;
            double amount;
            cin >> borrower >> amount;
            loan[i][borrower] = amount;
            totalAsset[i] += amount;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (totalAsset[i] < limit - 1e-9) {
            unsafe[i] = true;
            q.push(i);
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int i = 0; i < n; ++i) {
            if (!unsafe[i] && loan[i][u] > 0) {
                totalAsset[i] -= loan[i][u];
                loan[i][u] = 0;
                if (totalAsset[i] < limit - 1e-9) {
                    unsafe[i] = true;
                    q.push(i);
                }
            }
        }
    }

    bool hasUnsafe = false;
    for (int i = 0; i < n; ++i) {
        if (unsafe[i]) {
            if (!hasUnsafe) {
                cout << "Unsafe banks are";
                hasUnsafe = true;
            }
            cout << " " << i;
        }
    }

    if (!hasUnsafe) {
        cout << "None\n";
    } else {
        cout << "\n";
    }

    return 0;
}

