#include <iostream>
#include <vector>

using namespace std;

bool isConsecutiveFour(const vector<vector<int>>& grid, int R, int C) {
    if (R < 4 && C < 4) return false;

    const int dr[] = {0, 1, 1, 1};
    const int dc[] = {1, 0, 1, -1};

    for (int r = 0; r < R; ++r) {
        for (int c = 0; c < C; ++c) {
            int val = grid[r][c];
            for (int dir = 0; dir < 4; ++dir) {
                int r_end = r + 3 * dr[dir];
                int c_end = c + 3 * dc[dir];
                if (r_end >= 0 && r_end < R && c_end >= 0 && c_end < C) {
                    bool match = true;
                    for (int k = 1; k < 4; ++k) {
                        if (grid[r + k * dr[dir]][c + k * dc[dir]] != val) {
                            match = false;
                            break;
                        }
                    }
                    if (match) return true;
                }
            }
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int R, C;
    if (!(cin >> R >> C)) return 0;
    vector<vector<int>> grid(R, vector<int>(C));
    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            cin >> grid[i][j];
        }
    }
    if (isConsecutiveFour(grid, R, C)) {
        cout << "true\n";
    } else {
        cout << "false\n";
    }
    return 0;
}

