#include <iostream>
#include <vector>
#include <string>

using namespace std;

const int ROWS = 6;
const int COLS = 7;

bool checkWin(const vector<vector<char>>& board, int r, int c, char color) {
    const int dr[] = {0, 1, 1, 1};
    const int dc[] = {1, 0, 1, -1};

    for (int dir = 0; dir < 4; ++dir) {
        int count = 1;
        // Chiều dương
        for (int step = 1; step < 4; ++step) {
            int nr = r + dr[dir] * step;
            int nc = c + dc[dir] * step;
            if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS && board[nr][nc] == color) {
                count++;
            } else {
                break;
            }
        }
        // Chiều âm
        for (int step = 1; step < 4; ++step) {
            int nr = r - dr[dir] * step;
            int nc = c - dc[dir] * step;
            if (nr >= 0 && nr < ROWS && nc >= 0 && nc < COLS && board[nr][nc] == color) {
                count++;
            } else {
                break;
            }
        }
        if (count >= 4) return true;
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<char>> board(ROWS, vector<char>(COLS, '.'));
    vector<int> colHeight(COLS, 0);

    bool gameOver = false;
    string resultStatus = "CONTINUE";

    for (int moveIdx = 1; moveIdx <= n; ++moveIdx) {
        int col;
        cin >> col;
        if (gameOver) continue;

        char color = (moveIdx % 2 != 0) ? 'R' : 'Y';
        int row = ROWS - 1 - colHeight[col];
        board[row][col] = color;
        colHeight[col]++;

        if (checkWin(board, row, col, color)) {
            gameOver = true;
            if (color == 'R') {
                resultStatus = "RED wins at move " + to_string(moveIdx);
            } else {
                resultStatus = "YELLOW wins at move " + to_string(moveIdx);
            }
        } else if (moveIdx == ROWS * COLS) {
            gameOver = true;
            resultStatus = "DRAW at move 42";
        }
    }

    cout << resultStatus << "\n";
    for (int r = 0; r < ROWS; ++r) {
        for (int c = 0; c < COLS; ++c) {
            cout << board[r][c];
        }
        cout << "\n";
    }

    return 0;
}

