    if (!(cin >> n)) return 0;

    vector<string> grid(6, string(7, '.'));

    auto hasWon = [&](char ch) -> bool {
        for (int r = 0; r < 6; ++r) {
            for (int c = 0; c < 7; ++c) {
                // Ngang
                if (c + 3 < 7 && grid[r][c] == ch && grid[r][c+1] == ch && grid[r][c+2] == ch && grid[r][c+3] == ch) return true;
                // Dọc
                if (r + 3 < 6 && grid[r][c] == ch && grid[r+1][c] == ch && grid[r+2][c] == ch && grid[r+3][c] == ch) return true;
                // Chéo xuống phải
                if (r + 3 < 6 && c + 3 < 7 && grid[r][c] == ch && grid[r+1][c+1] == ch && grid[r+2][c+2] == ch && grid[r+3][c+3] == ch) return true;
                // Chéo lên phải
                if (r - 3 >= 0 && c + 3 < 7 && grid[r][c] == ch && grid[r-1][c+1] == ch && grid[r-2][c+2] == ch && grid[r-3][c+3] == ch) return true;
            }
        }
        return false;
    };

    int finishedMove = -1;
    string winner = "";

    for (int i = 1; i <= n; ++i) {
