using namespace std;

struct Point {
    double x, y;
};

double dist(const Point& a, const Point& b) {
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Point> cities(n);
    for (int i = 0; i < n; ++i) {
        cin >> cities[i].x >> cities[i].y;
    }

    int best_idx = 0;
    double min_total_dist = -1.0;

    for (int i = 0; i < n; ++i) {
        double current_total = 0.0;
        for (int j = 0; j < n; ++j) {
            current_total += dist(cities[i], cities[j]);
        }
        if (i == 0 || current_total < min_total_dist) {
            min_total_dist = current_total;
            best_idx = i;
        }
    }

    cout << fixed << setprecision(2);
    cout << "The central city is at (" << cities[best_idx].x << ", " << cities[best_idx].y << ")\n";
    cout << "The total distance to all other cities is " << min_total_dist << "\n";

    return 0;
}

