const int SIZE = 3;
const double EPS = 1e-6;

bool isMarkovMatrix(const double m[][SIZE]) {
    for (int i = 0; i < SIZE; ++i) {
        for (int j = 0; j < SIZE; ++j) {
            if (m[i][j] <= 1e-9) {
                return false;
            }
        }
    }
    for (int j = 0; j < SIZE; ++j) {
        double colSum = 0.0;
        for (int i = 0; i < SIZE; ++i) {
            colSum += m[i][j];
        }
        if (std::abs(colSum - 1.0) >= EPS) {
            return false;
        }
    }
    return true;
}

