            if (!(std::cin >> m[i][j])) {
                return 0;
            }
        }
    }

    if (isMarkovMatrix(m)) {
        std::cout << "It is a Markov matrix\n";
    } else {
        std::cout << "It is not a Markov matrix\n";
    }
    return 0;
}

