#include <cstdio>

const int SIZE = 3;

void sortRows(const double m[][SIZE], double result[][SIZE]) {
    for (int i = 0; i < SIZE; ++i) {
        for (int j = 0; j < SIZE; ++j) {
            result[i][j] = m[i][j];
        }
        // Simple insertion sort for each row
        for (int j = 1; j < SIZE; ++j) {
            double key = result[i][j];
            int k = j - 1;
            while (k >= 0 && result[i][k] > key) {
                result[i][k + 1] = result[i][k];
                --k;
            }
            result[i][k + 1] = key;
        }
    }
}

int main() {
    double m[SIZE][SIZE];
    for (int i = 0; i < SIZE; ++i) {
        for (int j = 0; j < SIZE; ++j) {
            if (scanf("%lf", &m[i][j]) != 1) return 0;
        }
    }

    double result[SIZE][SIZE];
    sortRows(m, result);

    for (int i = 0; i < SIZE; ++i) {
        printf("%.3f %.3f %.3f\n", result[i][0], result[i][1], result[i][2]);
    }

    return 0;
}

