            if (std::abs(result[0]) < 1e-7) result[0] = 0.0;
            if (std::abs(result[1]) < 1e-7) result[1] = 0.0;
            std::cout << std::fixed << std::setprecision(4) << result[0] << " " << result[1] << "\n";
