const int SIZE = 2;

bool getIntersectingPoint(const double points[][SIZE], double result[]) {
    double x1 = points[0][0], y1 = points[0][1];
    double x2 = points[1][0], y2 = points[1][1];
    double x3 = points[2][0], y3 = points[2][1];
    double x4 = points[3][0], y4 = points[3][1];

    double a = y1 - y2;
    double b = x2 - x1;
    double c = y3 - y4;
    double d = x4 - x3;
    double e = a * x1 + b * y1;
    double f = c * x3 + d * y3;

    double det = a * d - b * c;
    if (std::abs(det) < 1e-9) {
        return false;
    }

    result[0] = (e * d - b * f) / det;
    result[1] = (a * f - e * c) / det;
    return true;
}

