using namespace std;

const int SIZE = 2;

double getTriangleArea(const double points[][SIZE]) {
    double x1 = points[0][0], y1 = points[0][1];
    double x2 = points[1][0], y2 = points[1][1];
    double x3 = points[2][0], y3 = points[2][1];

    // Diện tích theo công thức định thức / shoelace formula:
    // Area = 0.5 * |x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2)|
    double area = 0.5 * abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));
    if (area <= 1e-6) {
        return 0.0;
    }
    return area;
}

