    }

    double area = getTriangleArea(points);
    if (area == 0.0) {
        cout << "The three points are on the same line\n";
    } else {
        cout << fixed << setprecision(2);
        cout << "The area of the triangle is " << area << "\n";
    }

    return 0;
}

