#include <cmath>

using namespace std;

struct Point {
    double x, y;
};

// Giao điểm của hai đường thẳng (p1-p2) và (p3-p4)
Point getIntersection(Point p1, Point p2, Point p3, Point p4) {
    double a1 = p1.y - p2.y;
    double b1 = p2.x - p1.x;
    double c1 = a1 * p1.x + b1 * p1.y;

    double a2 = p3.y - p4.y;
    double b2 = p4.x - p3.x;
    double c2 = a2 * p3.x + b2 * p3.y;

    double det = a1 * b2 - a2 * b1;
    Point p;
    p.x = (b2 * c1 - b1 * c2) / det;
    p.y = (a1 * c2 - a2 * c1) / det;
    return p;
}

double triangleArea(Point a, Point b, Point c) {
    return 0.5 * abs((b.x - a.x) * (c.y - a.y) - (c.x - a.x) * (b.y - a.y));
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Point v1, v2, v3, v4;
    if (!(cin >> v1.x >> v1.y >> v2.x >> v2.y >> v3.x >> v3.y >> v4.x >> v4.y)) return 0;

    Point O = getIntersection(v1, v3, v2, v4);

    vector<double> areas = {
        triangleArea(v1, v2, O),
        triangleArea(v2, v3, O),
        triangleArea(v3, v4, O),
        triangleArea(v4, v1, O)
    };

    sort(areas.begin(), areas.end());

    cout << fixed << setprecision(3);
    for (int i = 0; i < 4; ++i) {
        cout << areas[i] << (i == 3 ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <iostream>
