#include <iomanip>
#include <cmath>

using namespace std;

struct Vec2 {
    double x, y;
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    double cross(const Vec2& o) const { return x * o.y - y * o.x; }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Vec2 v[4];
    for (int i = 0; i < 4; ++i) {
        if (!(cin >> v[i].x >> v[i].y)) return 0;
    }

    // Line 1: v[0] to v[2], Line 2: v[1] to v[3]
    // Point on line 1: v[0] + t * (v[2] - v[0])
    // (v[0] + t * (v[2] - v[0]) - v[1]) x (v[3] - v[1]) = 0
    Vec2 d1 = v[2] - v[0];
    Vec2 d2 = v[3] - v[1];
    Vec2 v01 = v[0] - v[1];

    double t = -v01.cross(d2) / d1.cross(d2);
    Vec2 O = {v[0].x + t * d1.x, v[0].y + t * d1.y};

    vector<double> areas(4);
    for (int i = 0; i < 4; ++i) {
        int next_idx = (i + 1) % 4;
        areas[i] = 0.5 * std::abs((v[i] - O).cross(v[next_idx] - O));
    }

    sort(areas.begin(), areas.end());

    cout << fixed << setprecision(3);
    for (int i = 0; i < 4; ++i) {
        cout << areas[i] << (i == 3 ? "" : " ");
    }
    cout << "\n";

    return 0;
}

