class StackOfIntegers {
private:
    vector<long long> elements;
public:
    StackOfIntegers() {}

    void push(long long value) {
        elements.push_back(value);
    }

    void pop() {
        if (!elements.empty()) {
            elements.pop_back();
        }
    }

    int getSize() const {
        return (int)elements.size();
    }

    bool empty() const {
        return elements.empty();
    }

    long long operator[](int index) const {
        return elements[index];
    }
};

