#include <iostream>
#include <string>

using namespace std;

class StackOfIntegers {
private:
    long long* data;
    int capacity;
    int count;

    void resize(int newCapacity) {
        long long* newData = new long long[newCapacity];
        for (int i = 0; i < count; ++i) {
            newData[i] = data[i];
        }
        delete[] data;
        data = newData;
        capacity = newCapacity;
    }

public:
    StackOfIntegers(int cap = 16) : capacity(cap), count(0) {
        data = new long long[capacity];
    }

    ~StackOfIntegers() {
        delete[] data;
    }

    void push(long long val) {
        if (count >= capacity) {
            resize(capacity * 2);
        }
        data[count++] = val;
    }

    void pop() {
        if (count > 0) {
            --count;
        }
    }

    int size() const {
        return count;
    }

    long long operator[](int i) const {
        return data[i];
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int q;
    if (cin >> q) {
        StackOfIntegers myStack;
        for (int k = 0; k < q; ++k) {
            string cmd;
            cin >> cmd;
            if (cmd == "PUSH") {
                long long val;
                cin >> val;
                myStack.push(val);
            } else if (cmd == "POP") {
                myStack.pop();
            } else if (cmd == "AT") {
                long long idx;
                cin >> idx;
                if (idx >= 0 && idx < myStack.size()) {
                    cout << myStack[(int)idx] << "\n";
                } else {
                    cout << "OUT_OF_BOUNDS\n";
                }
            } else if (cmd == "PRINT") {
                int n = myStack.size();
                if (n == 0) {
                    cout << "EMPTY\n";
                } else {
                    for (int i = 0; i < n; ++i) {
                        cout << myStack[i] << (i + 1 == n ? "\n" : " ");
                    }
                }
            }
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

class Complex {
private:
    double a;
    double b;
public:
    Complex(double real = 0.0, double imag = 0.0) : a(real), b(imag) {}

    double getRealPart() const { return a; }
    double getImaginaryPart() const { return b; }

    Complex operator+(const Complex& other) const {
        return Complex(a + other.a, b + other.b);
    }

    Complex operator-(const Complex& other) const {
        return Complex(a - other.a, b - other.b);
    }

    Complex operator*(const Complex& other) const {
        return Complex(a * other.a - b * other.b, b * other.a + a * other.b);
    }

    Complex operator/(const Complex& other) const {
        double denom = other.a * other.a + other.b * other.b;
        return Complex((a * other.a + b * other.b) / denom,
                       (b * other.a - a * other.b) / denom);
    }

    double abs() const {
        return std::sqrt(a * a + b * b);
    }
};

static double fixZero(double val) {
    if (std::abs(val) < 1e-9) return 0.0;
    return val;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    double a, b, c, d;
    if (!(std::cin >> a >> b >> c >> d)) return 0;

    Complex z1(a, b);
    Complex z2(c, d);

    Complex addRes = z1 + z2;
    Complex subRes = z1 - z2;
    Complex mulRes = z1 * z2;
    Complex divRes = z1 / z2;
    double absZ1 = z1.abs();

    std::cout << std::fixed << std::setprecision(4);
    std::cout << fixZero(addRes.getRealPart()) << " " << fixZero(addRes.getImaginaryPart()) << "\n";
    std::cout << fixZero(subRes.getRealPart()) << " " << fixZero(subRes.getImaginaryPart()) << "\n";
    std::cout << fixZero(mulRes.getRealPart()) << " " << fixZero(mulRes.getImaginaryPart()) << "\n";
    std::cout << fixZero(divRes.getRealPart()) << " " << fixZero(divRes.getImaginaryPart()) << "\n";
    std::cout << fixZero(absZ1) << "\n";

    return 0;
}

