        cout << "The equation has no solution" << endl;
    } else {
        double x = (e * d - b * f) / det;
        double y = (a * f - e * c) / det;

        if (fabs(x) < 1e-9) x = 0.0;
        if (fabs(y) < 1e-9) y = 0.0;

        cout << fixed << setprecision(2);
        cout << "x is " << x << " and y is " << y << endl;
    }
    return 0;
}

