int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int status;
    double income;
    if (!(cin >> status >> income)) return 0;

    if (status < 0 || status > 3) {
        cout << "Wrong status\n";
        return 0;
    }

    vector<vector<double>> brackets = {
        {8350, 33950, 82250, 171550, 372950},
        {16700, 67900, 137050, 208850, 372950},
        {8350, 33950, 68525, 104425, 186475},
        {11950, 45500, 117450, 190200, 372950}
    };

    vector<double> rates = {0.10, 0.15, 0.25, 0.28, 0.33, 0.35};

    const auto& b = brackets[status];
    double tax = 0.0;

    if (income <= b[0]) {
        tax = income * rates[0];
    } else if (income <= b[1]) {
        tax = b[0] * rates[0] + (income - b[0]) * rates[1];
    } else if (income <= b[2]) {
        tax = b[0] * rates[0] + (b[1] - b[0]) * rates[1] + (income - b[1]) * rates[2];
    } else if (income <= b[3]) {
        tax = b[0] * rates[0] + (b[1] - b[0]) * rates[1] + (b[2] - b[1]) * rates[2] + (income - b[2]) * rates[3];
    } else if (income <= b[4]) {
        tax = b[0] * rates[0] + (b[1] - b[0]) * rates[1] + (b[2] - b[1]) * rates[2] + (b[3] - b[2]) * rates[3] + (income - b[3]) * rates[4];
    } else {
        tax = b[0] * rates[0] + (b[1] - b[0]) * rates[1] + (b[2] - b[1]) * rates[2] + (b[3] - b[2]) * rates[3] + (b[4] - b[3]) * rates[4] + (income - b[4]) * rates[5];
    }

    cout << fixed << setprecision(2) << tax << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>

using namespace std;

double computeSingle(double income, const double b[]) {
    double rates[] = {0.10, 0.15, 0.25, 0.28, 0.33, 0.35};
    double tax = 0.0;
    double prev = 0.0;
    for (int i = 0; i < 5; ++i) {
        if (income > b[i]) {
            tax += (b[i] - prev) * rates[i];
            prev = b[i];
        } else {
            tax += (income - prev) * rates[i];
            return tax;
        }
    }
    tax += (income - prev) * rates[5];
    return tax;
}

int main() {
    int status;
    double income;
    if (cin >> status >> income) {
        if (status < 0 || status > 3) {
            cout << "Wrong status" << endl;
