        double brackets[4][5] = {
            {8350.0, 33950.0, 82250.0, 171550.0, 372950.0},
            {16700.0, 67900.0, 137050.0, 208850.0, 372950.0},
            {8350.0, 33950.0, 68525.0, 104425.0, 186475.0},
            {11950.0, 45500.0, 117450.0, 190200.0, 372950.0}
        };
        double tax = computeSingle(income, brackets[status]);
        cout << fixed << setprecision(2) << tax << endl;
    }
    return 0;
}

