    double f = (y3 - y4) * x3 - (x3 - x4) * y3;

    double D = a * d - b * c;
    if (std::abs(D) < 1e-9) {
        printf("The two lines are parallel\n");
    } else {
        double Dx = e * d - b * f;
        double Dy = a * f - e * c;
        double px = Dx / D;
        double py = Dy / D;
        if (std::abs(px) < 1e-9) px = 0.0;
        if (std::abs(py) < 1e-9) py = 0.0;
