#include <iostream>
#include <iomanip>
#include <cmath>
#include <vector>
#include <algorithm>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    double a1, a2, a3;
    if (!(std::cin >> a1 >> a2 >> a3)) return 0;

    const double r = 40.0;
    const double PI = std::acos(-1.0);

    double x1 = r * std::cos(a1), y1 = r * std::sin(a1);
    double x2 = r * std::cos(a2), y2 = r * std::sin(a2);
    double x3 = r * std::cos(a3), y3 = r * std::sin(a3);

    // Lengths of sides a (BC), b (AC), c (AB)
    double a = std::hypot(x2 - x3, y2 - y3);
    double b = std::hypot(x1 - x3, y1 - y3);
    double c = std::hypot(x1 - x2, y1 - y2);

    // Law of cosines
    auto clamp_val = [](double val) {
        if (val > 1.0) return 1.0;
        if (val < -1.0) return -1.0;
        return val;
    };

    double cosA = clamp_val((b * b + c * c - a * a) / (2.0 * b * c));
    double cosB = clamp_val((a * a + c * c - b * b) / (2.0 * a * c));
    double cosC = clamp_val((a * a + b * b - c * c) / (2.0 * a * b));

    double angleA = std::acos(cosA) * 180.0 / PI;
    double angleB = std::acos(cosB) * 180.0 / PI;
    double angleC = std::acos(cosC) * 180.0 / PI;

    std::vector<double> angles = {angleA, angleB, angleC};
    std::sort(angles.begin(), angles.end());

    std::cout << std::fixed << std::setprecision(2);
    std::cout << angles[0] << " " << angles[1] << " " << angles[2] << "\n";

    return 0;
}

