int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    double alpha[3];
    if (!(std::cin >> alpha[0] >> alpha[1] >> alpha[2])) return 0;

    std::sort(alpha, alpha + 3);

    const double PI = std::atan(1.0) * 4.0;

    // Central angles between adjacent points along the circle
    double d1 = alpha[1] - alpha[0];
    double d2 = alpha[2] - alpha[1];
    double d3 = 2.0 * PI - (alpha[2] - alpha[0]);

    // Inscribed angle theorem: the inscribed angle subtending an arc is half the central angle of that arc
    // The three vertices see the three opposite arcs
    double deg1 = (d1 / 2.0) * (180.0 / PI);
    double deg2 = (d2 / 2.0) * (180.0 / PI);
    double deg3 = (d3 / 2.0) * (180.0 / PI);

    std::vector<double> angles = {deg1, deg2, deg3};
    std::sort(angles.begin(), angles.end());

    std::cout << std::fixed << std::setprecision(2);
    std::cout << angles[0] << " " << angles[1] << " " << angles[2] << "\n";

    return 0;
}

