    secondLowest.price = 1e18;
    secondLowest.index = -1;

    for (int i = 0; i < n; ++i) {
        Item current;
        cin >> current.name >> current.price;
        current.index = i;

        if (isBetter(current, lowest)) {
            secondLowest = lowest;
            lowest = current;
        } else if (isBetter(current, secondLowest)) {
            secondLowest = current;
        }
    }

    cout << fixed << setprecision(2);
    cout << lowest.name << " " << lowest.price << "\n";
    cout << secondLowest.name << " " << secondLowest.price << "\n";

    return 0;
}

