using namespace std;

struct Product {
    string name;
    double price;
    int order;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<Product> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i].name >> a[i].price;
        a[i].order = i;
    }

    auto cmp = [](const Product& x, const Product& y) {
        if (x.price != y.price) return x.price < y.price;
        return x.order < y.order;
    };

    partial_sort(a.begin(), a.begin() + 2, a.end(), cmp);

    cout << fixed << setprecision(2);
    cout << a[0].name << " " << a[0].price << "\n";
    cout << a[1].name << " " << a[1].price << "\n";

    return 0;
}

