#include <iostream>
#include <string>

using namespace std;

void printPatternA() {
    cout << "123456\n";
    for (int i = 0; i < 4; ++i) {
        cout << "1    6\n";
    }
    cout << "123456\n";
}

void printPatternB() {
    for (int i = 1; i <= 5; ++i) {
        int spaces = 5 - i;
        for (int s = 0; s < spaces; ++s) cout << ' ';
        int maxVal = 2 * i - 1;
        for (int j = 1; j <= maxVal; ++j) {
            cout << j << (j == maxVal ? "" : " ");
        }
        cout << "\n";
    }
}

void printPatternC() {
    int count[] = {1, 2, 3, 2, 1};
    for (int i = 0; i < 5; ++i) {
        int spaces = 3 - count[i];
        for (int s = 0; s < spaces; ++s) cout << ' ';
        for (int j = 0; j < count[i]; ++j) {
            cout << '3' << (j + 1 == count[i] ? "" : " ");
        }
        cout << "\n";
    }
}

void printPatternD() {
    for (int i = 1; i <= 6; ++i) {
        int leadingSpaces = 2 * (6 - i);
        for (int s = 0; s < leadingSpaces; ++s) cout << ' ';
        for (int j = 1; j <= i; ++j) {
            cout << j << (j == i ? "" : " ");
        }
        cout << "\n";
    }
}

int main() {
    char p;
    if (cin >> p) {
        if (p == 'A') printPatternA();
        else if (p == 'B') printPatternB();
        else if (p == 'C') printPatternC();
        else if (p == 'D') printPatternD();
    }
    return 0;
}

#include <iostream>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    char type;
    if (!(cin >> type)) return 0;
    switch (type) {
        case 'A': {
            for (int r = 1; r <= 6; ++r) {
                if (r == 1 || r == 6) {
                    for (int c = 1; c <= 6; ++c) cout << c;
                } else {
                    cout << '1';
                    for (int c = 0; c < 4; ++c) cout << ' ';
                    cout << '6';
                }
                cout << '\n';
            }
            break;
        }
        case 'B': {
            for (int r = 1; r <= 5; ++r) {
                for (int sp = 0; sp < 5 - r; ++sp) cout << ' ';
                int k = 2 * r - 1;
                for (int v = 1; v <= k; ++v) {
                    cout << v << (v < k ? " " : "");
                }
                cout << '\n';
            }
            break;
        }
        case 'C': {
            int rowSizes[5] = {1, 2, 3, 2, 1};
            for (int r = 0; r < 5; ++r) {
                for (int sp = 0; sp < 3 - rowSizes[r]; ++sp) cout << ' ';
                for (int v = 0; v < rowSizes[r]; ++v) {
                    cout << '3' << (v + 1 < rowSizes[r] ? " " : "");
                }
                cout << '\n';
            }
            break;
        }
        case 'D': {
            for (int r = 1; r <= 6; ++r) {
                for (int sp = 0; sp < 2 * (6 - r); ++sp) cout << ' ';
                for (int v = 1; v <= r; ++v) {
                    cout << v << (v < r ? " " : "");
                }
                cout << '\n';
            }
            break;
        }
    }
    return 0;
}

