#include <iostream>
#include <vector>

using namespace std;

bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int a, b;
    if (!(cin >> a >> b)) return 0;

    int countOnLine = 0;
    for (int i = a; i <= b; ++i) {
        if (!isPrime(i)) {
            if (countOnLine > 0) {
                cout << " ";
            }
            cout << i;
            countOnLine++;
            if (countOnLine == 5) {
                cout << "\n";
                countOnLine = 0;
            }
        }
    }
    if (countOnLine > 0) {
        cout << "\n";
    }
    return 0;
}

