int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int a, b;
    if (!(cin >> a >> b)) return 0;

    // Sàng nguyên tố đến b
    vector<bool> prime(b + 1, true);
    if (b >= 0) prime[0] = false;
    if (b >= 1) prime[1] = false;
    for (int p = 2; p * p <= b; ++p) {
        if (prime[p]) {
            for (int i = p * p; i <= b; i += p) {
                prime[i] = false;
            }
        }
    }

    int count = 0;
    for (int i = a; i <= b; ++i) {
        if (!prime[i]) {
            if (count % 5 != 0) {
                cout << " ";
            }
            cout << i;
            count++;
            if (count % 5 == 0) {
                cout << "\n";
            }
        }
    }
    if (count % 5 != 0) {
        cout << "\n";
    }
    return 0;
}

