#include <cmath>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double loanAmount;
    int numberOfYears;
    double annualInterestRate;

    if (!(cin >> loanAmount >> numberOfYears >> annualInterestRate)) return 0;

    int totalMonths = numberOfYears * 12;
    double monthlyRate = (annualInterestRate / 100.0) / 12.0;

    double monthlyPayment;
    if (monthlyRate == 0) {
        monthlyPayment = loanAmount / totalMonths;
    } else {
        monthlyPayment = loanAmount * monthlyRate / (1.0 - pow(1.0 + monthlyRate, -totalMonths));
    }

    double totalPayment = monthlyPayment * totalMonths;

    cout << fixed << setprecision(2);
    cout << "Monthly Payment: " << monthlyPayment << "\n";
    cout << "Total Payment: " << totalPayment << "\n";
    cout << "Payment# Interest Principal Balance\n";

    double balance = loanAmount;
    for (int i = 1; i <= totalMonths; ++i) {
        double interest = monthlyRate * balance;
        double principal = monthlyPayment - interest;
        balance -= principal;
        if (abs(balance) < 1e-9) balance = 0.0;
        cout << i << " " << interest << " " << principal << " " << balance << "\n";
    }

    return 0;
}

#include <cstdio>
#include <cmath>

int main() {
    double L;
    int Y;
    double r;
    if (scanf("%lf %d %lf", &L, &Y, &r) != 3) return 0;

    int n = Y * 12;
    double i = (r / 100.0) / 12.0;

    double m;
    if (i == 0.0) {
        m = L / n;
    } else {
        m = L * i / (1.0 - std::pow(1.0 + i, -n));
    }
    double total = m * n;

    printf("Monthly Payment: %.2f\n", m);
    printf("Total Payment: %.2f\n", total);
    printf("Payment# Interest Principal Balance\n");

    double bal = L;
    for (int month = 1; month <= n; ++month) {
        double interest = bal * i;
        double principal = m - interest;
        bal -= principal;
        if (std::abs(bal) < 1e-9) bal = 0.0;
        printf("%d %.2f %.2f %.2f\n", month, interest, principal, bal);
    }
    return 0;
}

